DROP TABLE IF EXISTS `user_new_words`;
CREATE TABLE `user_new_words`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID（自增，唯一标识每条记录）',
  `nick` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户唯一标识（UUID/手机号/用户ID）',
  `word_id` int(10) UNSIGNED NOT NULL COMMENT '关联单词表的主键ID（如words表的id）',
  `is_mastered` tinyint(1) NULL DEFAULT 0 COMMENT '是否掌握：0=未掌握，1=已掌握（适配复习场景）',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '软删除时间（NULL=未删除，非NULL=已删除）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_word_id`(`nick` ASC, `word_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`nick` ASC) USING BTREE,
  INDEX `idx_user_mastered`(`nick` ASC, `is_mastered` ASC) USING BTREE,
  INDEX `idx_user_created_at`(`nick` ASC, `created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户生词表（云端存储，仅关联word_id）' ROW_FORMAT = Dynamic;

