INSERT INTO `words` VALUES (1, 'ache', '/eɪk/', 'ache.mp3', 'n.疼痛；  v.觉得疼痛', 'fbd3d74be33a645b04e9b2136aeaf151_118640_1718087848.jpg', 'd_24_45_0_3_20150808223103.png', 'Mark had an ache in his back.', '马克背部疼痛。', 'bhl26pvfp2nz27kb9da48wwg2kk7pyzj.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2, 'adult', '/əˈdʌlt/', 'adult.mp3', 'n.成年人，成年动物；  adj.成年的；成年人的；（内容）色情的', 'ba231fcdd3650a847c268c8e44c29c65_145026_1595471950.jpeg', 'd_16_5623_0_2_20150808225602.png', 'An adult is a person who is 18 years old or over.', '成年人的年龄大于或等于18岁。', '696a721c0f30c43a_1266883197286767152_250207.mp3', 'ad(to)去 + ul成长 + t → adult成人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3, 'aircraft', '/ˈerkræft/', 'aircraft.mp3', 'n.飞机，航空器', '61ff9cdeb0e93da7c9408f222ee53360_151049_1538648807.jpg', 'a9f043d3a6418aed556ab7addd38b8ce_144630_1551250360.png', 'Aircraft are meant to be in the sky.', '飞机注定要飞上天空。', '1a17af110a33e5e3_1266883374987717438_250207.mp3', 'air空气 + craft技艺 → aircraft飞行器', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4, 'alcohol', '/ˈælkəhɔːl/', 'alcohol.mp3', 'n.酒；酒精，乙醇', 'dbec85012975f16afbbcec3b39a0f5e3_27345_1534129612.jpg', 'd_105_7977_0_2_20150809060632.png', 'I avoid alcohol because it weakens my judgment.', '我不喝酒，因为它会削弱我的判断力。', '91704bad991ac25776ac04f5868777c7_20373_1534129366.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (5, 'allowance', '/əˈlaʊəns/', 'allowance.mp3', 'n.零用钱', 'feb29b8ed86bc498b84ce24a06046a8e_78348_1565343414.jpg', 'd_16_4006_0_6_20150808223937.png', 'He has an allowance of 3', '他每月有3 000美元零用钱。', 'sa_31_4006_0_6_160322145645.aac', 'allow分配；发津贴 + ance行为，性质 → allowance津贴', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (6, 'analysis', '/əˈnæləsɪs/', 'analysis.mp3', 'n.分析报告', '20120429_04_43_54_887-gigapixel-scale.jpg', 'd_16_4927_0_4_20150808224625.png', 'Could you write up an analysis of how the market is moving this week?', '你能写一篇关于这周市场走势的分析报告吗？', 'sa_1_4927_0_2_20150808123155.aac', 'ana完全，彻底地 + lysis解开，分开 → 彻底分开来（观察） → analysis分析', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (7, 'appeal', '/əˈpiːl/', 'appeal.mp3', 'v.请求；上诉；有吸引力；  n.呼吁；请求；吸引力； 筹款努力', '194bd1e9d5520073d0d8590679fae7b9_199324_1564738253.jpeg', '20141011_04_36_25_65_v3.png', 'The animal rights group appeals for an end to commercial whaling.', '动物权益保护组织呼吁停止商业捕鲸。', 'us_The_animal_20230811141037881_233a68a5e0ad20f3a223.mp3', 'ap=ad去，向 + peal促使，推进 → appeal呼吁；上诉', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (8, 'assist', '/əˈsɪst/', 'assist.mp3', 'v.帮助；  n.帮助', 'cc1f3ee890569084b1efeb8b4e2ac5c0_97405_1584613498.jpeg', 'd_16_8408_0_2_20150808233017.png', 'They assisted each other to the top of the mountain.', '他们互相帮助，登上了山顶。', 'fce75a8e64bf870a5d20060ccd911424_44604_1584613495.mp3', 'as一再 ＋ sist站 → 站过来 → assist帮助', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (9, 'at the same time', '/ət ðə seɪm taɪm/', 'at the same time.mp3', 'phr.同时；然而', 'ddd6cc71bb8876ef3b58482a99d50804_169119_1565696258.jpg', '', 'It\'s difficult for her to answer so many calls at the same time.', '她很难同时接听这么多电话。', 'c039f590bcafc401_1266797982974782244_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (10, 'at this rate', '/æt ðɪs reɪt/', 'at this rate.mp3', 'n.照这样下去', '78e1cc3da722b51b21203c8969321d3c.jpg', '', 'This traffic\'s terrible. At this rate he\'ll never get to the airport on time.', '交通太糟糕了。照这样下去，他根本不可能准时到达机场。', '3f3b053fe7b0dacdaa482c1df0842f2a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (11, 'attractive', '/əˈtræktɪv/', 'attractive.mp3', 'adj.（事物）有吸引力的，诱人的；有魅力的，性感的；引起兴趣的', '0e8ef21e3ff40ada50158e9ba4c2700b_185138_1571630239.jpeg', '', 'With such a low price', '这个旅馆房间价格如此低廉，真的很吸引人。', '85810373b88f37d8_1266883012562279158_250207.mp3', 'at加强 + tract拉 + ive...的 → attract拉过来=吸引 + ive...的 → attractive引人注目的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (12, 'awkward', '/ˈɔːkwərd/', 'awkward.mp3', 'adj.尴尬的；笨拙的；不雅观的；棘手的；不方便的', '2e5188d21742dd5408b10552f51528e9_189487_1732240746.jpg', '', 'It was awkward when he farted in the library.', '他在图书馆放了个屁，真是尴尬。', '84khkhb353h9f7hm9vhc7d8vezldsvc9.mp3', 'awk错误方向 + ward朝向 → 转错方向 → awkward尴尬的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (13, 'balance', '/ˈbæləns/', 'balance.mp3', 'n.平衡，平衡能力；天平；  v.平衡；保持平衡', '5ef73b3793a90788f352a20c9e0d1ba3_81099_1538624010.jpg', 'd_16_4375_0_2_20150808224159.png', 'Look! He can keep balance on that rope.', '看！他能在那根绳索上保持平衡。', 'xrghd7u8xhmwumc7cjgvch79j8w6323m.mp3', 'ba=bi两个的 + lance天平刻度，盘子 → 天平的两端保持一致 → balance平衡', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (14, 'be helpful to', '/bi helpfl tuː/', 'be helpful to.mp3', 'phr.有助于...', '081f47cf56367074ea7e9574aa6aecd7.jpeg', '', 'Strength training is helpful to your muscle growth.', '力量训练有助于肌肉生长。', 'ad9a4c895bd061b0f207f8a1d6b56eb0.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (15, 'beyond', '/bɪˈjɑːnd/', 'beyond.mp3', 'prep.超出；  adv.在更远处，在另一边', 'fbd01b065db074aa8dd738c0956b17f5_97714_1604029987.jpg', 'd_24_9739_0_4_20150808230249.png', 'I couldn\'t hit him as he was beyond my reach.', '我打不了他，因为我够不着他。', '8495349493f14536e4afc147f48da421_22060_1540954683.mp3', 'be强调 + yond那边 → 超过', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (16, 'bring to', '/brɪŋ tu/', 'bring to.mp3', 'phr.使恢复知觉', '02af981cb698f16be86c1d33952961d3.jpg', '', 'The lifeguard brought the drowned man to consciousness.', '救生员让溺水者恢复了意识。', 'us_The_lifeguard_20241009154449290_aea7c83ce3260d9e6b82.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (17, 'capture', '/ˈkæptʃər/', 'capture.mp3', 'v.捕获，抓住；留存；  n.战利品', 'capture_9756_20231106_0d0a9a22.jpg', '20141011_13_28_26_53_v3.png', 'The rabbit was captured by the hunter.', '猎人抓到了那只兔子。', 'sa_1_9756_0_6_20150808131453.aac', 'capt拿，抓，握住 + ure名词后缀 → 抓住毛病 → capture逮捕，捉拿', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (18, 'chart', '/tʃɑːrt/', 'chart.mp3', 'n.图表，表格；  v.制成图表', '3_0_20160720071835_740_c-gigapixel-scale.jpg', 'd_24_5829_0_4_20150808224357.png', 'This chart shows that annual sales have continued to rise.', '这张图表显示年度销售额持续上升。', '3_0_20160720071835_18078_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (19, 'check in', '/tʃek ɪn/', 'check in.mp3', 'phr.登记（在旅馆、机场等）', '7e182082307dc2d66003613104529b44_97847_1600243414.jpg', '', 'When you arrive at the hotel', '当你到达酒店时，先登记入住。', 'z7t95wmwdxkqxc34r5k6uabl7uznf5j9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (20, 'clear away', '/klɪr əˈweɪ/', 'clear away.mp3', 'phr.把…收走', '6563661a468c6a9bed1498ae8c9e2698_29991_1584955979.jpeg', '', 'The waitress is clearing away the plates.', '女服务生正在收盘子。', '03a5b03b88217b03f07a0875c026112a_43826_1584955974.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (21, 'compensate', '/ˈkɑːmpenseɪt/', 'compensate.mp3', 'v.赔偿', '519e510bb27e1be2a7c4fea1901d9634_58379_1559730507.jpg', 'd_107_535_0_2_20150809000859.png', 'He should be compensated for his work-related injury.', '他应该得到工伤赔偿。', '7b04fb77eb7d81bc_1266883631653935770_250207.mp3', 'com全部 + pens花费 + ate动词后缀 → 花费的钱全部拿回来 → 赔偿', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (22, 'complain about', '/kəmˈplein əˈbaʊt/', 'complain about.mp3', 'phr.抱怨', 'aa3618119db26ae12ffd276523fc57f4.jpg', '', 'She is on the phone complaining about the bad service.', '她正在电话里抱怨服务不好。', '2b2bf5d8e2d627c2e42e0780f84abc47.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (23, 'completely', '/kəmˈpliːtli/', 'completely.mp3', 'adv.彻底地', 'i_9_7117_0_2_20150808154112-gigapixel-scale.jpg', 'd_109_7117_0_2_20150809054929.png', 'I\'ve lost all my hair—I\'m completely bald!', '我的头发已经掉完了，我彻底秃顶了！', '0f20100169396ea4_1266883478209583780_250207.mp3', 'com共同 + plete=plet满，填满 + ly……地 → adv.完全地，彻底地；完整地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (24, 'comprise', '/kəmˈpraɪz/', 'comprise.mp3', 'v.构成，由……组成；包含，包括', '1976f0d81c338ccb41a0bc758e5eb43f_149347_1561953069.jpg', 'd_107_556_0_2_20150809000922.png', 'These animals comprise most of the cat family.', '这些动物构成了猫科动物的大部分。', 'fc6582563335b553_1266883489917524690_250207.mp3', 'com全部 + prise拿住，抓住 → 全部抓住 → comprise包括，含有', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (25, 'conclusion', '/kənˈkluːʒn/', 'conclusion.mp3', 'n.结论，推论', 'i_1_10952_0_4_150925180737-gigapixel-scale.jpg', 'd_16_10952_0_7_20150808235736.png', 'She drew a conclusion from these facts.', '她终于从这些事实中得出了一条结论。', '74bf83e0ee86f2cc_1266883486858566282_250207.mp3', 'conclu表示结束 + sion为名词后缀 → conclusion结论；结束', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (26, 'connect', '/kəˈnekt/', 'connect.mp3', 'v.连接，关联；与……有同感；把……联系起来', 'i_24_7956_0_6_151123182919-gigapixel-scale.jpg', '20140929_11_00_44_458_v3.png', 'My phone is connected to the computer.', '我的手机正连接着电脑。', 'af09a9ea6a0f62f2_1266883325549915080_250207.mp3', 'con共同 + nect连结 → connect连结', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (27, 'consideration', '/ kənˌsɪdəˈreɪʃ(ə)n /', 'consideration.mp3', 'n.考虑，思考；体贴，体谅，顾及', '76d2d6159165bdc68f13225913fa53e8_207790_1749720161.jpg', 'd_16_608_0_7_20150808223255.png', 'He has three cars as options for consideration.', '他有三辆车作为选择以供考虑。', 'us_He_has_20250612172221568_9b137c9d18dee3fee06c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (28, 'constraint', '/kənˈstreɪnt/', 'constraint.mp3', 'n.限制；约束，束缚', '557a572d5e8ebaf607682bb1938dd288_197385_1586599882.jpeg', '20140916_16_40_07_92_v3.png', 'Money constraints prevented the boy from traveling the world.', '金钱的限制使这个男孩无法环游世界。', '5d2e39582c76789c34b07418ad1ca3aa_27857_1621931333.mp3', 'con一起 + strain拉紧，压 + t → 约束；强迫', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (29, 'convince of', '/kənˈvɪns ʌv/', 'convince of.mp3', 'phr.使信服', '957939ffb255381263b4c2f6f79c720c.jpg', '', 'Her collection of medals convinced him of her outstanding ability.', '她获得的奖牌使他相信其杰出的能力。', 'c743c450bff3a09a96ea94c7979ba56e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (30, 'crazy about', '/ˈkrezi əˈbaʊt/', 'crazy about.mp3', 'phr.痴迷于…，迷恋…', '3c33bac518f30b3a2eead70863f66062.jpeg', '', 'He\'s crazy about basketball.', '他对篮球十分痴迷。', '4a8243699b4b14c63391b40e7b7c78f5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (31, 'crowd', '/kraʊd/', 'crowd.mp3', 'n.人群，观众；民众；朋友；  v.聚集在……周围；涌入（脑海）；挤满', 'b05b41f4261bd0079e3d7d58f0c3311c_56439_1565684272.jpg', 'd_24_5667_0_4_20150808224246.png', 'Wow! There was a large crowd of people at the concert.', '音乐会上有很多人。', '50c9153bc8fd4e0e_1266883008374200970_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (32, 'cure', '/kjʊr/', 'cure.mp3', 'v.治愈，治疗', 'i_13_4579_0_4_151221175044-gigapixel-scale.jpg', 'd_16_4579_0_2_20150808224319.png', 'These pills will cure your sickness.', '这些药丸能治好你的病。', '06785a4cc75d9e24_1266883380113726032_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (33, 'deviate from', '/ˈdiviˌet frʌm/', 'deviate from.mp3', 'phr.偏离', '95263e4d88424c6402cc1b20f7148f7c.jpg', '', 'The driver deviated from the route on the map.', '司机偏离了地图上的路线。', 'e1200dbf8b66b33ab4e5ce4ea0a5221e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (34, 'differ from', '/ˈdɪfər frəm/', 'differ from.mp3', 'phr.不同于', 'a2ad9051d331f284c60f7d3e3d93ebca_187725.jpg', '', 'The direction that the one duck is facing differs from the others.', '那只鸭子所面对的方位和其他的鸭子不同。', 'bf94014a2d2e695eac62c7ce92196188_40879.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (35, 'disgusting', '/dɪsˈɡʌstɪŋ/', 'disgusting.mp3', 'adj.令人厌恶的；令人无法接受的', '6091332c7665db76a1464c137ac407a5_89151_1535595244.jpeg', 'd_102_12430_0_4_20150809042313.png', 'He finds the smell of the sock disgusting.', '这只袜子的味道实在让他恶心。', 'ecsy7vs9gl5wnz6v4htwaujz4rzsmuce.mp3', 'disgust使厌恶 + ing形容词后缀 → disgusting令人厌恶的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (36, 'do away with', '/doʊ əˈweɪ wɪθ/', 'do away with.mp3', 'phr.废除；消灭', 'doawaywith_7647_20231106_5f42769d.jpg', '', 'A number of countries do away with the death penalty.', '许多国家废除了死刑。', 'sa_11_7647_0_2_20150808173037.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (37, 'drown', '/draʊn/', 'drown.mp3', 'v.（使）淹死；淹没', '2ebd0357722831eb7111bdaa0daab8c6_68276_1586943437.jpeg', 'd_24_5865_0_4_20150808224358.png', 'The apple drowned in the water because it couldn\'t swim.', '苹果因为不会游泳而淹死在了水里。', '3f4a18a4a279ad370a53012d1b8c2796_50004_1586943435.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (38, 'durable', '/ˈdʊrəbl/', 'durable.mp3', 'adj.耐用的，长久的；  n.耐用品', '29b1a45eedc6751d797f983f8a1cccfc_88002_1565342875.jpg', 'd_107_974_0_2_20150809001428.png', 'We want a durable vehicle for this rough road.', '我们要在这条起伏不平的路上行驶，所以想要一辆耐用的车。', 'mhl7ek7mucepnjxwsgqkbxqql44lhcrz.mp3', 'dur持久，坚硬 + able能……的 → 持久的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (39, 'elsewhere', '/ˌelsˈwer/', 'elsewhere.mp3', 'adv.向别处，在别处', '3_0_20170930071137_54497_c-manual-scale.jpg', '20140731_15_12_00_22_v3.png', 'I want to move elsewhere because it\'s too noisy here.', '我想搬到别处去，因为这儿太吵了。', '3_0_20170930071137_6260_c.aac', 'else别的 + where地方 → elsewhere在别处', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (40, 'fairly', '/ˈferli/', 'fairly.mp3', 'adv.相当地；公平地', '1fd0c3f8d2955145b68cecd1cd8a8a87_196716_1588089082.jpeg', 'd_24_9091_0_4_20150808230000.png', 'The bag in the right looks fairly heavy.', '右边那个书包看上去相当沉。', 'us_The_bag_20250210103034325_a238a654eb340148e8a3.mp3', 'fair公平 + ly……地 → fairly公平地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (41, 'fight', '/faɪt/', 'fight.mp3', 'v.打架，打斗，搏斗；争吵；奋斗；  n.斗争；搏斗；比赛', 'e27d50199448542e158126d3107ebc6b_90600_1574846469.jpg', '20141009_23_26_44_74_v3.png', 'Let\'s fight! the man said to the other player.', '让我们战斗吧！ 那个男人对另一位参赛选手说道。', '70a7dd7710527afd_1266883199205530196_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (42, 'for instance', '/fər ˈɪnstəns/', 'for instance.mp3', 'phr.例如，比如', '78b7608e938e965fa09338d61a9a7983_115667_1624342883.jpg', '', 'There are various ways to protect against sunburn', '有很多方法可以防止晒伤，比如涂防晒霜。', '4f2fcf4b21c7d43961a5ee153c5d9b50.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (43, 'freshman', '/ˈfreʃmən/', 'freshman.mp3', 'n.大学一年级学生', '1606ccc80704e93dba4fa6e801fd733d_107898_1619159263.jpg', '', 'Freshmen always have lots of things to do in their first few days at college.', '在入学的头几天，新生们通常有很多事要做。', '568976dae247c072f6c7d5dc1f289e75_23869_1585366247.mp3', 'fresh新鲜 + man人 → freshman新手，生手', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (44, 'front', '/frʌnt/', 'front.mp3', 'n.前面，正面；  adj.前面的，正面的', '3fa98d35f2151aee7ba2346564f7da39_159655_1702867359.jpg', 'd_24_18736_0_4_20150808235640.png', 'The children sit in the front of the cinema.', '孩子们坐在电影院前排。', 'a681399e4d06734b_1266883007883815796_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (45, 'full', '/fʊl/', 'full.mp3', 'adj.满的，充满的；很受感动的；  n.完全，全部', '3cbffea4da5962c33ce3cf4cedb7078d_89869_1576736774.jpeg', 'd_24_16444_0_3_20150808231243.png', 'The cup on the left is full of water.', '左侧的杯子中装满了水。', '4bd0ee308a525537_1266763241783339940_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (46, 'fundamental', '/ˌfʌndəˈmentl/', 'fundamental.mp3', 'adj.基本的；至关重要的；基础的', '68fd8bf828022b761dae07ca0f4c4b87_60685_1701050878.jpg', 'd_107_5649_0_2_20150809013319.png', 'Among Maslow\'s needs', '在马斯洛的需求中，生理需求是人最基本的需求。', 'us_Among_Maslows_20231127101056381_201175901a41f850142a.mp3', 'fundament基础 + al形容词后缀 → fundamental基础的，基本的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (47, 'generate', '/ˈdʒenəreɪt/', 'generate.mp3', 'v.产生（热、电等能量）', '92f5df9a7d5defe9db6fbd7caf9b44ef_178898_1730258861.jpg', 'd_107_3978_0_2_20150809003827.png', 'A man is riding the bicycle to generate electricity.', '一个男人骑着自行车来发电。', 'd6889f7f0c7f7300598984d49edab0b8_19638_1624072580.mp3', 'gener出生，产生 + ate做，造成 → generate发生，引起', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (48, 'give up', '/ɡɪv ʌp/', 'give up.mp3', 'phr.投降', 'c_i_wm_20120922_04_07_07_423.jpg', '', 'The girl has given up doing her homework on the laptop.', '那个女生放弃用电脑做作业了。', '91a4a2adcf9958aa_1266883329656728338_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (49, 'graceful', '/ˈɡreɪsfl/', 'graceful.mp3', 'adj.优雅的，优美的，得体的', '1e3bda9db83ee520686187dc41678b30_52620_1557127640.jpg', '', 'She is such a graceful and beautiful actress!', '她是一个如此优雅美丽的演员！', 'sa_1_1301_0_7_151211153628.aac', 'grace优雅 + ful形容词后缀：…的 → graceful优雅的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (50, 'hand on', '/hænd ɑːn/', 'hand on.mp3', 'phr.依次传递', '3acb422e8773513c7bb63fd3a8bbca21_112308_1707026292.jpg', '', 'The tradition is handed on from generation to generation. ', '这种传统从一代代传递下来。', 'us_The_tradition_20240204135246940_b5aa50378539b8e6cafe.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (51, 'happen', '/ˈhæpən/', 'happen.mp3', 'v.发生', 'i_1_15921_0_2_20150808132039-gigapixel-scale.jpg', 'd_24_15921_0_4_20150808230830.png', 'How did this horrible accident happen?', '这次可怕的事故是如何发生的？', '86b7e969c5d785e2_1266763557851540298_250117.mp3', 'happ出现，是这种情况 + en动词后缀 → happen发生', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (52, 'hard', '/hɑːrd/', 'hard.mp3', 'adj.坚硬的；  adv.猛烈地', '6a7b81817410c875b375e5aaaeb2d776_75828_1587795033.jpeg', '20121225_19_04_25_85.png', 'The bed is soft but the chair is hard.', '床是软的，椅子是硬的。', '5wpqql9arjup996luvwtat2mqwbp4g3v.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (53, 'host', '/hoʊst/ ', 'host.mp3', 'n.主人，东道主；  v.主持，主办', '3e29c1860862fca240165852a0e9cdb7_94381_1565344062.jpg', 'd_24_5754_0_3_20150808224328.png', 'The hosts had cooked for us', '主人们为我们做了饭菜，所以我们给他们带了一些红酒。', 'us_The_hosts_20220627180655216_2d44cd92181072750fca.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (54, 'identical', '/aɪˈdɛntɪkəl/', 'identical.mp3', 'adj.相同的，同一的；  n.完全相同的事物', '6bac21b7d7e46de5d68668f0ff2605c4_158885_1573802082.jpeg', 'd_1_5827_0_2_20150808124453.png', 'All of the buildings in this row are identical.', '这一排房屋完全相同。', '21be8556be550d33_1266883528356878966_250207.mp3', 'ident相同 + ical…的 → identical一样的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (55, 'impose', '/ɪmˈpoʊz/', 'impose.mp3', 'v.把……强加给；强制实行，强迫接受', 'eec6964de1bc7760e5bee367e8cf60c3_87068_1742888906.jpg', 'd_1_3938_0_3_20150808122115.png', 'The government imposed a ban on single-use plastics to protect the environment.', '政府为保护环境强加了对一次性塑料的禁令。', 'us_The_government_20250325154058420_e6a078270a57d11cd98b.mp3', 'im进入 + pose放 → impose强加', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (56, 'in any case', '/ɪn ˈeniː keɪs/', 'in any case.mp3', 'phr.不管怎样', 'f95187988d30b875754a63aadd11ca8b.jpeg', '', 'As he\'ll pass the supermarket in any case', '不管怎样他都会经过超市，所以他同意载邻居过去。', 'd7def8fc24949775a484cf392bc58f3b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (57, 'in charge of', '/ɪn tʃɑrdʒ ʌv/', 'in charge of.mp3', 'phr.负责，主管', '9b58ef0536a6dd83d8f3532f510ce00c.jpg', '', 'The man in the suit is in charge of this metal processing plant.', '穿西装的男人主管这个金属加工厂。', 'b5b98175e5a647cbf817cef096bcb202_27701_1621931844.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (58, 'in honour of', '/ɪn \'ɑːnər əv/', 'in honour of.mp3', 'phr.为纪念，为庆祝，向…表示敬意', '67dc5b3d95fe4fc05d9b187596b4b00b_200668_1564370493.jpg', '', 'He wears the bullet in honour of his fallen comrades.', '他戴着子弹是为了纪念牺牲的战友们。', 'aa059101d0bd3e44_1266883325667879884_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (59, 'in place', '/ɪn pleɪs/', 'in place.mp3', 'phr.在适当的位置', '36632_20130916_03_03_46_209.jpg', '', 'It looks like my car will be in place for a while.', '看起来我的车得呆在那一段时间了。', 'sa_36_20139_0_3_20150808104534.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (60, 'in the face of', '/ɪn ðə feɪs əv/', 'in the face of.mp3', 'phr.面对', 'f09a00625407dbb6c4b938dc81f2e8a9.jpeg', '', 'He remains calm in the face of danger.', '面对危险，他依旧能保持冷静。', 'bb750ad9b15542c63031f484cc0b90a7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (61, 'include', '/ɪnˈkluːd/', 'include.mp3', 'v.包括，列入，包含', '295917d269a185fe7188d821601de07f_68443_1619162116.jpg', 'd_24_4920_0_4_20150808223647.png', 'Elephants', '大象、青蛙和鸟可以列入“动物”这个类别里。', 'e937180af9f9a59d_1266883330452794152_250207.mp3', 'in进入 + clude关闭 → 关进去 → include包括', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (62, 'inferior to', '/ɪnˈfɪriːər tu/', 'inferior to.mp3', 'phr.不如……', '6f07e6b088c02ca128d187510c527911.jpeg', '', 'The customer is complaining that the products are inferior in quality to the samples.', '顾客在抱怨产品的质量不如样品。', '311cbb6def75b760fc5033f08e1c9fb2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (63, 'influence', '/ˈɪnfluəns/', 'influence.mp3', 'n.影响，作用；  v.影响，作用', '64b32e6d5c6ae2179a18047c8a54a082_138611_1588130890.jpeg', 'd_24_4951_0_4_20150808223714.png', 'His mother was a main influence on his becoming a pianist.', '他成为一名钢琴家主要是受了他母亲的影响。', 'shyt2z9g3wraklxsycdcnqtrg6uyfgum.mp3', 'in进入 + flu流动 + ence名词后缀 → 流入 → influence影响', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (64, 'institute', '/ˈɪnstɪtuːt/', 'institute.mp3', 'n.学院，专科学院，研究院（或所）；学会；  v.建立，设立，制定', '0db268f54f9dc019efeea05a8da8c605_166361_1564730935.jpg', 'd_107_7812_0_2_20150809022140.png', 'A lot of top scientists are working in this institute of medical biology.', '许多顶尖的科学家在这家医用生物学的研究院工作。', '7f24c70fcd899ee2d52d23f672fc55f8_45684_1564730921.mp3', 'in内部 + stitut建立 + e → 建立在内部的 → 学院；制定，设立', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (65, 'insult', '/ɪnˈsʌlt/', 'insult.mp3', 'v.侮辱；  n.侮辱的言辞或行为', '354a8c7dcbb148023821c6982d2fb648_187822_1573797943.jpeg', '', 'The customer insulted the ice cream seller by throwing the money to the ground.', '这个顾客把钱丢在地上，以此来侮辱卖冰激凌的小贩。', 'e9ac5a08d784f5ab9e9e7037e8f85029_49918_1650263143.mp3', 'in进入 + sult跳 → 踩到别人的脸上 → insult侮辱', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (66, 'intellectual', '/ˌɪntəˈlektʃuəl/', 'intellectual.mp3', 'adj.聪明的；需用智力的；  n.知识分子', 'dcdc244ee9018018a625101dcc7bc1d0_176202_1538639217.jpg', 'd_1_1615_0_4_20150808121727.png', 'The intellectual girl is familiar with all the math formulas.', '这个聪明的女孩熟知所有的数学公式。', '543c37a79fa66308e279c0fa8617e0e7_17443_1538639225.mp3', 'intel在...之间 + lectu选，挑选 + al形容词后缀 -> intellectual聪明的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (67, 'introduce', '/ˌɪntrəˈduːs/', 'introduce.mp3', 'v.介绍；传入，引进', 'e56abfe75554ee2280fbefd90d17eda3_138277_1733290438.jpg', 'd_75_7109_0_3_20150809025644.png', 'Students will introduce themselves on the first day at school.', '开学第一天，学生们都要介绍自己。', 'ab8dd9c21bc9b70157286b738b378a1a_35246_1527321415.mp3', 'intro向内，入内 + duce引 → 引进 → introduce引入，介绍', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (68, 'item', '/ˈaɪtəm/', 'item.mp3', 'n.物品；一条，一则', 'd7e94161cfd6512e0f78183669c50c86_85032_1584956208.jpeg', 'd_1_4747_0_2_20150808122951.png', 'Here are a variety of office items', '这儿有各种各样的办公用品，比如笔记本电脑和电话。', '3159d4c90ccbadd7ffcb59c1d2a98669_48488_1584956192.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (69, 'jacket', '/ˈdʒækɪt/', 'jacket.mp3', 'n.短上衣，夹克衫；（书籍的）护封', '379250fd62d8b335e3917844c9fc08fa_91127_1577953889.jpeg', 'd_24_18144_0_4_20150808234948.png', 'These four jackets are different in both color and style.', '这四件夹克衫的颜色和风格都不同。', '3d2005bd766391b5_1268213314275918810_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (70, 'jeans', '/dʒiːnz/', 'jeans.mp3', 'n.牛仔裤', '3_0_20170928071445_88867_c-gigapixel-scale.jpg', 'd_105_17646_0_2_20150809062620.png', 'I\'m glad I put on a comfortable pair of jeans today.', '今天我很高兴，因为我穿了一条舒服的牛仔裤。', '07e56fc04336fb86_1266763400024447704_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (71, 'keep to', '/kip tu/', 'keep to.mp3', 'v.不偏离；遵循', 'i_11_7715_0_2_20150808173440.jpg', '', 'They will keep to their promise and never break it.', '他们会履行诺言而不会破坏它。', 'sa_11_7715_0_2_20150808173440.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (72, 'laughter', '/ˈlæftər/', 'laughter.mp3', 'n.笑，笑声', '20ed28ab42a64c5a449413db430ac269_413610_1701068730.jpg', '20121225_18_39_06_687.png', 'She burst into laughter while chatting with an old friend.', '和老朋友聊天，她开怀大笑起来。', 'e250024f6bd636d5_1266883629513681784_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (73, 'law', '/lɔː/', 'law.mp3', 'n.法律', 'ca33beed35b664f76f8af09fe2706dfe_144772_1587461759.jpeg', 'd_24_15899_0_3_20150808230736.png', 'Nobody is above the law.', '没有人能凌驾于法律之上。', 'ade1111f8d237201badbe153be5a0dc3_26590_1587461756.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (74, 'lay out', '/leɪ aʊt/', 'lay out.mp3', 'phr.摆开', 'fcd96df9dd7793e2cd2d497f85ccd640.jpg', '', 'The waiter laid the knives and forks out on the table. ', '服务员在餐桌上摆放了刀叉。', 'cdd45812d45aba3b66c7e235352dbdd9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (75, 'lay sb. off', '/leɪ ˈsʌmbədi ɑf/', 'lay sb. off.mp3', 'v.解雇；停止活动', 'i_12_16729_0_2_20150808184629.jpg', '', 'I\'m afraid your work hasn\'t been very good', '很遗憾你的工作做得不是很好，所以我不得不解雇你。', 'sa_12_16729_0_2_20150808184629.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (76, 'let go', '/lɛt ɡo/', 'let go.mp3', 'phr.放开', '5157e837a263109132df0c179c7bec03.jpg', '', 'Parents have to let their children go once they grow up. ', '孩子长大后，父母不得不放手。', '8c4e0ea4f4b36167ae805acea88c73de.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (77, 'lightning', '/ˈlaɪtnɪŋ/', 'lightning.mp3', 'n.闪电；  adj.迅速的，闪电般的', '9c881b52f6e1364fd2319ff0b612579e_167690_1534152640.jpeg', 'd_24_8488_0_4_20150808225743.png', 'Oh my God! A bolt of lightning is striking my house.', '我的天哪！一道闪电击中了我的房子。', '57a390147c627d8f2ff383ad830750d8_38959_1534152645.mp3', 'light光 + ning……的 → lightning闪电；闪电般的，快速的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (78, 'literature', '/ˈlɪtrətʃər/', 'literature.mp3', 'n.文学；文献', 'c_i_5613_1_0_3_150722100803-gigapixel-scale.jpg', '20121225_19_04_52_621.png', 'These four books are the classics of Chinese literature.', '这四本书是中国文学的经典。', 'f1d9ba37d569013c_1266883375325227854_250207.mp3', 'litera=letter文字，字母 + ture状态 → 文字状态 → literature文学', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (79, 'live up to', '/lɪv ʌp tu/', 'live up to.mp3', 'phr.不辜负', 'cab92f7c0c6aa32adf9955477e7f431e_110372_1701675083.jpeg', '', 'The son really lived up to his father\'s expectations; he was great at his job.', '这个儿子没有辜负他父亲的期望；他在工作上做得很好。', 'sa_11_4667_0_2_20150808153401.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (80, 'lower', '/ˈloʊər/', 'lower.mp3', 'v.降低，减少；  adj.下方的，底部的', 'fb0ee286ff09fd13c977efa60b7b3a65_187887_1727332295.jpg', 'd_1_4936_0_2_20150808123204.png', 'I need to lower the volume of the radio', '我得把收音机的声音调小一点，不然会把宝宝吵醒。', '8bee107d6fb62c33_1266883625924143910_250207.mp3', 'low低 + er比较级 → 使...更低 → lower降低，减少', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (81, 'magic', '/ˈmædʒɪk/', 'magic.mp3', 'adj.有魔力的，魔术的；  n.魔术，戏法', 'i_24_17735_0_4_20150808233340-gigapixel-scale.jpg', 'd_24_17735_0_4_20150808233340.png', 'The man took the rabbit out from this magic hat.', '这男人从这顶魔术帽中拎出了只兔子。', 'sa_24_17735_0_8_151214175405.aac', 'mag=mage魔术师 + ic…术 → magic魔术', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (82, 'mature', '/məˈtʃʊr/ ', 'mature.mp3', 'adj.成熟的；  v.使成熟；  v.成熟', '5e5ed907ba9754e421e0b0c855087509_193862_1569654777.jpeg', 'a43b6bf6d97e4bbc1fafa381ed38f8d6_346094_1551252818.png', 'The lion is now mature enough to go hunting alone.', '这头狮子现在已经成熟到可以独自捕猎了。', 'vpce9zfucstubykpr6yvltljcjgw4ptb.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (83, 'minor', '/ˈmaɪnər/ ', 'minor.mp3', 'adj.较小的', '77640244f0a3cea2163528cf8beafcb4_86039_1706756177.jpg', '', 'It was just a minor injury.', '这只是一个小伤。', 'lclutaexe3vv4zgundpw326yvpkagz9y.mp3', 'min小 ＋ or表物 → minor较小的；较少的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (84, 'minority', '/maɪˈnɔrɪti/', 'minority.mp3', 'n.少数民族；  adj.构成少数的', 'minority_3935_20231106_39375bb0.jpg', 'd_107_3935_0_2_20150809003549.png', 'The two ladies of an ethnic minority group wear colorful clothes.', '这两位少数民族妇女穿着鲜艳的服饰。', '6afbb0c0cc9d238b65d474ec681b34f1_45032_1603175485.mp3', 'minor小或少 + ity名词后缀 → 少的状态 → minority少数', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (85, 'mode', '/moʊd/', 'mode.mp3', 'n.模式；方式', '12fedec1641e0447969609e5c3b01872_112651_1587190461.jpg', 'd_1_3857_0_3_20150808121950.png', 'The camera has many different modes.', '这台照相机有很多种不同的拍摄模式。', 'sa_1_3857_0_3_20150808121950.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (86, 'negotiate', '/nɪˈɡəʊʃieɪt/', 'negotiate.mp3', 'v.谈判，磋商，商议', 'c897c60ee956569dcc2e5556e8e68663_98298_1724911982.jpg', 'd_107_6707_0_2_20150809020758.png', 'They are negotiating some details of the cooperation.', '他们正在商议合作的细节。', 'us_They_are_20240829141321343_62edd90b34b88a206e66.mp3', 'negoti协商 + ate动词后缀 → negotiate谈判，协商', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (87, 'numerous', '/ˈnuːmərəs/', 'numerous.mp3', 'adj.为数众多的，许多的', '7e0505c6812b086d362250e7163b75a1_113780_1565687763.jpg', 'd_2_3941_0_2_20150808142255.png', 'The stadium is filled with numerous sports fans.', '体育场里坐满了体育爱好者。', 'sa_1_3941_0_2_20150808122118.aac', 'numer数 + ous形容词后缀 → numerous无数的，许多的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (88, 'output', '/ˈaʊtpʊt/', 'output.mp3', 'n.产量', '2730e17ceb1cb22ec3bb78cff0da8410_79533_1569031375.jpg', 'd_16_3891_0_2_20150808223757.png', 'The oven\'s output is 48 loaves per hour.', '这个烤炉的产量是每小时48条面包。', 'sa_1_3891_0_2_20150808122021.aac', 'out出 + put放 → output产出', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (89, 'pace', '/peɪs/', 'pace.mp3', 'n.步伐；  v.踱步', 'i_24_8199_0_5_151222143440-gigapixel-scale.jpg', 'd_24_8199_0_3_20150808225524.png', 'They were walking at a fast pace.', '他们正在快步走。', 'sa_24_8199_0_5_151225160802.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (90, 'painful', '/ˈpeɪnfl/', 'painful.mp3', 'adj.疼痛的；痛苦的；艰难的', '9f42cf64f80739a528a3c03e49189ef9_89373_1617765355.jpg', 'd_24_8050_0_4_20150808225407.png', 'Oow! I hit my foot on the table! It\'s so painful!', '噢！我的脚撞到桌子了！疼死了！', '84w49xnlgef6t9fz69cpwbegta3fwsta.mp3', 'pain疼痛 + ful形容词后缀 → painful痛苦的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (91, 'passion', '/ˈpæʃn/', 'passion.mp3', 'n.强烈的情感，激情', '7529e1bb173a041823e1d4b6b2ada98f_129182_1729850358.jpg', 'd_1_5823_0_3_20150808124450.png', 'He shouted Passion! and conveyed the idea that passion changes lives.', '他高喊 “激情！”，并传达了 “激情改变生活 ”的理念。', 'bp9nbq7cuhh4a83gr33bwsc68ctsqygs.mp3', 'pass感情 + ion名词后缀 → passion热情，激情', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (92, 'persist in', '/pərˈsɪst ɪn/', 'persist in.mp3', 'phr.坚持', 'ba384c5f67b1a31dc7a9f7882bbbab0a.jpg', '', 'He persisted in training for many years despite his disability', '尽管身体残疾，他仍坚持训练多年，并最终赢得了比赛！', '0b33b58d1ad7db12bfcab29ab679d30b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (93, 'pie', '/paɪ/', 'pie.mp3', 'n.馅饼', '26922b8f575629ce8b17bed41837b1b0_91286_1535964865.jpeg', '20121225_20_28_31_471.png', 'May I have a slice of the blueberry pie?', '可以给我一片蓝莓派吗？', '602007788a4a447edd80497d1da1fe04_28780_1535964857.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (94, 'political', '/pəˈlɪtɪkl/', 'political.mp3', 'adj.政治的', '5b0abab15792c9296783192135b65527_87524_1541846034.jpg', 'd_51_13767_0_4_20150809022655.png', 'The young man is giving a political speech to the public.', '这个年轻人在向公众发表一场政治演说。', '7vrvragaqn43bkx2nylm8596v8lnw6dv.mp3', 'polit国家，城市 + ical...的 → political政治的，政治上的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (95, 'pretend', '/prɪˈtend/', 'pretend.mp3', 'v.假装，装扮', '2a587cb37e742aab5a1e5629a951a9cf_104291_1732262793.jpg', 'd_24_8948_0_3_20150808225937.png', 'I pretended to study hard', '我假装很努力地学习，但是实际上我在手机上聊天。', 'c1a2d2c7a75e26fe_1266883379730623276_250207.mp3', 'pre提前 + tend延伸 → 提前伸出想好借口 → pretend假装，借口', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (96, 'principal', '/ˈprɪnsəpəl/', 'principal.mp3', 'n.校长；  adj.主要的，首要的', '3_0_20160603100302_26507_c-gigapixel-scale.jpg', '20130616_02_21_05_496.png', 'Our principal gives a speech at our graduation ceremony.', '校长在我们的毕业典礼上致辞。', 'qqhkfruk66qly8sqvzssv2lk7mteau6h.mp3', 'prin主要的 + cip拿，抓，握住 + al形容词后缀 → principal主要的；首要的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (97, 'protection for sb.', '/prəˈtekʃn fɔːr ˈsʌmbədi/', 'protection for sb..mp3', 'phr.保护某人', '9fd92b2453dd36e52dba42520feebdb6.jpg', '', 'The suit provides protection for him; he won\'t get infected.', '这身衣服给他提供保护，这样他不会感染病毒。', '686f32bd6914fb35b23ed57e28a6b02d_49760_1593584630.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (98, 'provided', '/prəˈvaɪdɪd/', 'provided.mp3', 'conj.如果，以……为条件；  adj.预备好的', '73156ed912e599b792470b2e1abb158f_195524_1586855776.jpeg', 'd_107_3850_0_2_20150809003137.png', 'You may watch TV', '如果你先把家庭作业做完，你就可以看电视了。', 'jtvagj3p8fj43fx3l9zemx48ap4zlszz.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (99, 'provision of', '/prəˈvɪʒn əv/', 'provision of.mp3', 'phr.提供……', '523cd2204ea6fdff42bd9644ace0663e.jpg', '', 'The power plant is responsible for the provision of power.', '电厂负责提供电力。', '1fba282b87ec46c28bbc7c43d9546720_44720_1593584593.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (100, 'publication', '/ˌpʌblɪˈkeɪʃn/', 'publication.mp3', 'n.出版，发行；出版物；公布', 'dd85bb9741c96ba106c4149b21ce2e38_187705_1573804749.jpeg', 'd_107_5129_0_2_20150809011624.png', 'Once the publication process is complete', '出版流程一完成，就可以买到这本书了。', '13eb7eac5eb8c83b8816f41c70d22397_43416_1573804777.mp3', 'public公众的 + ation名词后缀 → 让公众都看到 → publication出版', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (101, 'reluctant', '/rɪˈlʌktənt/', 'reluctant.mp3', 'adj.不情愿的', '3_0_20160528174525_52257_c-gigapixel-scale.jpg', '20130510_18_02_27_334.png', 'The dog was reluctant to take a bath.', '狗狗不愿意去洗澡。', '87f1bfb350d0b016_1266883490567707358_250207.mp3', 're相反 + luct努力 + ant…的 → reluctant不情愿的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (102, 'rely', '/rɪˈlaɪ/', 'rely.mp3', 'v.依赖，依靠；信赖', '14668243203bf9136c049f9cbf22c979_108964_1585056569.jpeg', 'd_16_3968_0_2_20150808223908.png', 'I often rely on instant food because I am so bad at cooking.', '我经常吃速食，因为我不擅长烹饪。', '31197d7d2a5e8707fbfe0dce972aab29_24026_1625728909.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (103, 'resemble', '/rɪˈzembl/', 'resemble.mp3', 'v.像', '13d19b2a4be02f03bdf01285f1d417b7_83267_1714030135.jpg', 'd_107_10967_0_2_20150809025230.png', 'These two men resemble each other', '这两个男人长得很像，难以区分谁是谁。', '8f706144c2f8f62e_1266883379100342796_250207.mp3', 're表强调 + semble相类似，一样 → resemble类似', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (104, 'restaurant', '/ˈrestrɑːnt/', 'restaurant.mp3', 'n.餐厅，餐馆', '020c1cca86835ef4a106780c739f273c_86472_1574825502.jpg', '20130201_16_24_00_375.png', 'It is expensive to eat at this fancy restaurant.', '在这家高档餐厅吃饭很贵。', 'e145d11ca0c27cab_1266763405343677034_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (105, 'screen', '/skrin/', 'screen.mp3', 'n.屏幕，荧屏；  v.遮蔽', '4b0c8c837df4dcbfaa8573eb7e4c5eb6_91922_1565342489.jpg', '20141014_05_21_22_934_v3.png', 'The movie theater\'s screen is so large!', '这个电影院的银幕好大！', 'c870ecc3c113d99d_1266883114612206520_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
