INSERT INTO `words` VALUES (107, 'send off', '/send ɔːf/', 'send off.mp3', 'phr.【体】罚下场，给…送行', '98a252f7286cbd0c82c0b7403b275cfb_143664.jpg', '', 'He was sent off by the referee.', '他被裁判罚下场了。', 'b20b08b5d46f908c2899ccee4fc41d36_27151.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (108, 'service', '/ˈsɜːrvɪs/', 'service.mp3', 'n.服务；公共服务事业（或系统）；维修保养', '15833cd59f3ef376ce7033f141940120_83837_1575100049.jpeg', 'd_55_14139_0_4_20150809001902.png', 'The cleaning lady provides a range of cleaning services.', '这位清洁女工提供一系列清洁服务。', '9nhnzsu5jgt6qk7tbmmqmaafh9rddgt5.mp3', 'serv服务 + ice表名词，行为，状态 → service服务', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (109, 'set back', '/set bæk/', 'set back.mp3', 'phr.延缓', '63f76ae78e2bc73cede37839263ebc4b.jpeg', '', 'The scheduled flight time was set back a few hours due to the heavy fog.', '由于大雾，原定的飞行时间推迟了几个小时。', '372030607a75fb477600ef197683cee3_49054_1600078271.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (110, 'skillful', '/ˈskɪlfl/', 'skillful.mp3', 'adj.娴熟的', '03eb68c63a487aed538c8a9d93de97e3_100014_1588087442.jpeg', 'c3ca0393a8a4a39024fe38edcc9730a0_33028.jpg', 'They\'re very skillful skateboarders!', '他们是技术极其娴熟的滑板运动员！', 'edad64fb7394bed9be0cf7ce4f17574a_47350_1588087437.mp3', 'skill技术 + ful…的 → 有技术的 → skillful熟练的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (111, 'solution', '/səˈluːʃən/', 'solution.mp3', 'n.解决办法；答案，解答；溶液；溶解', '6d7a87935e0925616d2b7e0abec9cdb4_47757_1565619261.jpg', 'd_107_5537_0_2_20150809012926.png', 'I think the other plan is a better solution.', '我觉得另一个方案是更好的解决办法。', '6e13cd7c42c99f9f_1266883489490623176_250207.mp3', 'solut解开；溶解 + ion名词后缀，构成抽象名词 → 溶解；解决', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (112, 'substitute', '/ˈsʌbstɪˌtut/', 'substitute.mp3', 'v.代替；  n.替代物；替代者', 'i_1_7503_0_3_20150808125959-gigapixel-scale.jpg', 'd_16_7503_0_2_20150808231834.png', 'You should substitute fruits for sweets.', '你应该用水果代替甜食。', '268cc1fd30b30c6b6cad2a922f97435e_12427_1549876248.mp3', 'sub在下面，副手，次一等 + stitute创建，建立 → 建在下面 → substitute代替，候补', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (113, 'sum up', '/sʌm ʌp/', 'sum up.mp3', 'phr.总结', 'i_911_-911_0_1_160322132332.jpg', '', 'To sum up', '总而言之，2015年我有过很多重要时刻。', 'sa_911_-911_0_1_160323160157.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (114, 'supplement', '/ˈsʌplɪmənt/', 'supplement.mp3', 'n.增补，补充物，保健品；  v.补充（读作/ˈsʌpləˌmɛnt/）', 'i_1_6679_0_3_20150808125339-gigapixel-scale.jpg', 'd_107_6679_0_2_20150809020715.png', 'Taking these supplements may make you become more beautiful.', '吃这些保健品也许会让你变得更漂亮。', '3dad6153ea38384e6841c9c6e42a476a_26765_1621930437.mp3', 'sup在下面，次要 + ple满，填满 + ment名词后缀 → 增加次要的心填满 → 增补', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (115, 'sweep', '/swiːp/', 'sweep.mp3', 'v.扫，打扫；  n.清扫', 'i_1_6976_0_3_20150808125709-gigapixel-scale.jpg', 'd_24_6976_0_3_20150808224858.png', 'The floor is so dirty! I need to sweep it.', '地板太脏了！我需要扫扫。', 'd740d92f2d779c40_1266883377626831562_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (116, 'sympathy with', '/ˈsɪmpəθi wɪð/', 'sympathy with.mp3', 'phr.赞同', '249cebcaea222e5d3e74818bf1121fc5.jpg', '', 'She has sympathy with her colleague\'s idea.', '她赞同她同事的主意。', 'aa3b9a392e21b6253eb5e7658aed0fa0_39968_1593584279.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (117, 'talk over', '/tɔːk ˈoʊvər/', 'talk over.mp3', 'phr.讨论，商议', '90f678425031099803ccada7d32f429c.jpeg', '', 'The couple usually sit and talk over their plans for the day over breakfast.', '这对夫妻经常在吃早餐时讨论当天的计划。', '807645eeae9fc34d9454730895e9190e_26534_1599467643.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (118, 'term', '/tɜːrm/', 'term.mp3', 'n.学期；  v.把……称为', '3_0_20170712071051_57852_c-gigapixel-scale.jpg', 'd_57_14501_0_4_20150809005539.png', 'The autumn term in China begins from September 1st.', '中国的秋季学期是从9月1日开始的。', 'us_The_autumn_20250115140619762_0b4634809f007eba48f2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (119, 'tired of', '/ˈtaɪərd əv/', 'tired of.mp3', 'phr.厌倦', '7f7c67f1c949347442eebf715dd99e72.jpeg', '', 'He\'s sick and tired of his work. ', '他厌倦了他的工作。', 'a35a508d044fd137d379ffeecb9cfa58.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (120, 'transaction', '/trænˈzækʃən/', 'transaction.mp3', 'n.交易；学报', '52a4be2e392fcc54b8ca93243f3b6c12_33809_1566896159.jpg', '', 'I paid him and he gave me the house—it was an easy transaction.', '我给他钱，他给我房子——这是一笔轻松的交易。', 'sa_2_5809_0_2_20150808145720.aac', 'trans变换，转移 + action行动 → 交换行动 → 交易', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (121, 'unfortunately', '/ʌnˈfɔːrtʃənətli/', 'unfortunately.mp3', 'adv.遗憾地，可惜地，不幸地', '40de1e76d9fa189ce3714af37b3c768d_219653_1720085005.jpg', '20141012_09_02_23_775_v3.png', 'Unfortunately', '不幸的是，一场大雨打断了他们浪漫的晚餐。', '4911a8d543e518f1_1266883112292625286_250207.mp3', 'un不 + fortun=fortune运气 + ate造成…的 + ly有…特征的 → unfortunately遗憾的是，可惜的是', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (122, 'union', '/ˈjunjən/ ', 'union.mp3', 'n.工会；联合；合并；协会；同盟；一致；融洽', '6bdd17b7c64fcb8decfe28e93b86a699_142163_1573787857.jpeg', 'd_107_7829_0_2_20150809022217.png', 'The union is trying to protect their rights as workers.', '工会在努力保护他们作为劳动者的权利。', '1f9dbf13395aa67f_1266883485084047948_250207.mp3', 'un单一 + ion名词后缀 → 联成一体 → 联合，工会，联盟', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (123, 'variety', '/vəˈraɪəti/ ', 'variety.mp3', 'n.种类；变化，多样性', 'i_1_4977_0_3_20150808123249-gigapixel-scale.jpg', 'd_16_4977_0_2_20150808224728.png', 'There is a wide variety of tomatoes; they are different in color.', '番茄有很多种类，颜色各不相同。', '61a6a54e94949e8c_1266883614711655322_250207.mp3', 'vari变化 + ety名词后缀 → variety变化，多样化', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (124, 'adapt to', '/əˈdæpt tuː/', 'adapt to.mp3', 'phr.（使）适应', 'c52aa899b8923967476b4cf8e7869afe_158452_1605170680.jpg', '', 'It takes time for children to adapt to school life.', '孩子们需要一段时间来适应学校生活。', 'sa_908_-908_0_1_160301100750.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (125, 'agency', '/ˈeɪdʒənsi/', 'agency.mp3', 'n.代理机构', 'i_1_5037_0_7_151124155804-gigapixel-scale.jpg', 'd_107_5037_0_2_20150809011358.png', 'It\'s more convenient to buy tickets from a ticket agency.', '从车票代售点买票更方便。', 'sa_1_5037_0_7_151124155827.aac', 'ag做，代理做 + ency表示机构或状态 → 代理处', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (126, 'airport', '/ˈerpɔːrt/', 'airport.mp3', 'n.机场', 'cc37419bc571ef8dea2dda1648570f54_39538_1760080949.jpg', 'd_24_19574_0_3_20150809002107.png', 'The plane landed at the airport.', '飞机降落在机场。', '970f805844986f62_1268213311509775298_250930.mp3', 'air空气，空中 + port港口 → airport机场，航空站', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (127, 'applause', '/əˈplɔːz/', 'applause.mp3', 'n.鼓掌，掌声', 'e3fc469b2de1ea99bd0afa374032dbe2_170899_1530591314.jpeg', 'd_107_6833_0_2_20150809021026.png', 'The audience broke into enthusiastic applause for the three boys.', '观众们对三个男孩报以热烈的掌声。', '7b5e496ba9c1263fb7a9b5f03e062dbb_57635_1530591339.mp3', 'ap一再 + plause=plaud赞扬 → 一再赞扬 → applause掌声', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (128, 'article', '/ˈɑːrtɪkl/ ', 'article.mp3', 'n.（报刊上的）文章，论文，报道；物品', 'e5ff860d40ce1ad0baa4c723636559c8_195353_1733386173.jpg', 'd_24_225_0_4_20150808223110.png', 'She is reading the article in the newspaper.', '她正在阅读报纸上的文章。', 'sa_4_225_0_7_151222112510.aac', 'art技巧，艺术 + icle东西 → 用技巧做出的东西 → article物品，文章', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (129, 'attempt', '/əˈtempt/', 'attempt.mp3', 'v.试图，尝试；  n.努力，尝试；企图', '1425622792221-gigapixel-scale.jpg', 'd_24_4942_0_3_20150808223704.png', 'The cat attempts to catch that fish.', '那只猫咪试图抓到那条鱼。', 'sa_1_4942_0_2_20150808123211.aac', 'at表强调 + tempt尝试 → 一再尝试 → attempt尝试，企图', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (130, 'attempt at', '/əˈtempt æt/', 'attempt at.mp3', 'phr.企图，努力', 'c934276ab6529ee8d2051bbc6c134fd8.jpeg', '', 'The cat made an attempt at catching the fish.', '那只猫试图抓到鱼。', '0914f75111fb6fa7547c12f5eb1b8103_15249_1619161387.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (131, 'authorize', '/ˈɔːθəraɪz/', 'authorize.mp3', 'v.批准；授权', 'authorize_259_20231106_6e2811a2.jpg', '20140915_17_04_37_597_v3.png', 'The emperor authorized this document with a stamp.', '皇帝加印批准了这个文件。', 'sa_2_259_0_7_150829151755.aac', 'auth授权 + or人 + ize动词后缀 → authorize授权，批准', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (132, 'aware', '/əˈwer/', 'aware.mp3', 'adj.意识到的', '3a8159f42f63d83711324bc16c2b33a3_100004_1604025440.jpg', 'd_16_3864_0_6_20150808223738.png', 'The teacher is aware that the student is cheating in the exam.', '老师察觉到那个学生在考试中作弊。', 'a977278b982e4bf0_1266883522611862078_250207.mp3', 'a使 + ware注视 → aware意识到的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (133, 'be made from', '/biː meɪd frəm/', 'be made from.mp3', 'phr.由……制造', '61ec3f59f90783bbf141fc2c1abdcc25_171496.jpg', '', 'Wine is made from grapes.', '葡萄酒是由葡萄制成的。', '88bdca7367fe107dc7c9448bbbc505f1_25123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (134, 'beach', '/biːtʃ/', 'beach.mp3', 'n.海滩，河滩', '3b8883ba912ee52ec692429600b07474_87597_1565343556.jpg', 'd_13_5689_0_2_20150808182830.png', 'We spent a wonderful day at the beach.', '我们在海滩上度过了美妙的一天。', '8170535f1fc25c1e_1266763313920191382_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (135, 'blame on', '/bleɪm ɑːn/', 'blame on.mp3', 'phr.把责任推给……', 'c8c0e1bace7e0cda301f723b870ea57c.jpeg', '', 'The boy blamed his bad exam result on his naughty deskmate. ', '那个男孩把自己糟糕的考试成绩归咎于他调皮的同桌。', '1f48800f92efa36b83ddf175c2598c72.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (136, 'break off', '/breɪk ɔːf/', 'break off.mp3', 'phr.折断，掰掉；突然停止，暂停，中断', 'b0ac79a130620d58ae387cc63fb4c27e_90866_1580882686.jpg', '', 'She #broke off# a piece of chocolate.', '她掰开了一块巧克力。', '6aje94mkjl9vv7h3rfcu5ebnv5tz3lqh.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (137, 'candidate', '/ˈkændɪdət/', 'candidate.mp3', 'n. 候选人，申请人', '1426214732692-gigapixel-scale.jpg', 'd_107_4636_0_2_20150809010248.png', 'The candidates are presenting the speeches for the election.', '候选人正在为选举发表演说。', 'us_The_candidates_20231011105613486_2ce631131570b9c7398a.mp3', 'cand发光，白 + id + ate表名词  → 白衣人（古罗马时期谋求官职者都着白衣） → candidate候选人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (138, 'chase', '/tʃeɪs/', 'chase.mp3', 'v.追赶；驱逐；  n.追逐', 'a9178af5c0fd67f1dd9eee8dfb6f4dc8_183331_1700819863.jpg', 'd_107_5985_0_2_20150809014734.png', 'The kids chased each other on the grass. ', '孩子们在草地上相互追逐嬉戏。', 'us_The_kids_20231124175918839_182d3eed8684aa7dfd6f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (139, 'clear', '/klɪr/', 'clear.mp3', 'adj.清澈的；清楚的；  v.变清澈；  v.清除；  n.空隙；  adv.不靠近', '20121012_03_14_07_728-gigapixel-scale.jpg', 'd_24_17937_0_3_20150808233558.png', 'The water here is so clean and clear!', '这里的水真是干净清澈！', '3_72_20170930163731_95087_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (140, 'concentrate', '/ˈkɑːnsntreɪt/', 'concentrate.mp3', 'v.全神贯注于；浓缩；  n.浓缩物', '3_0_20170709071253_5788_c-gigapixel-scale.jpg', 'd_107_4385_0_2_20150809005508.png', 'He is concentrating on making his bread look perfect.', '他正在专心地使面包看起来完美。', 'ltkhuq4qaavu548eaq5culvme5k4ffpa.mp3', 'con共同 + centr中心 + ate动词后缀 → 都在中心 → concentrate集中；浓缩', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (141, 'concentration on', '/ˌkɑnsənˈtreʃən ɑn/', 'concentration on.mp3', 'phr.注意力集中于', '6026bdc4d3a3d6f90d56429a6e6adba4_98227_1707016354.jpg', '', 'His concentration on painting is admirable.', '他对绘画的专注令人钦佩。', 'us_His_concentration_20240204111114213_1c253307f51126ee1044.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (142, 'contact', '/ˈkɑːntækt/', 'contact.mp3', 'v.联系；  n.联系，联络', '3e48b234e87cf48f49d1258f6b0e5182_113031_1590336241.jpg', 'd_1_6958_0_4_20150808125653.png', 'They are contacting each other by a video call.', '他们正通过视频电话来联系对方。', 'us_They_are_20230504113822982_eeb49eebe1ab3b8df4bd.mp3', 'con一起 + tact接触 → contact接触，联系', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (143, 'contrast with', '/ˈkɑːntræst  wɪð/', 'contrast with.mp3', 'phr.与……形成对比', 'i_906_-906_0_1_160229095308.jpg', '', 'Contrasting with the past', '和过去相比，他现在瘦多了。', 'us_Contrasting_with_20250723093355407_5984644ff4e30a4a3d6e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (144, 'corner', '/ˈkɔːrnər/', 'corner.mp3', 'n.角落，角；困境', '7e8450d04cfb98dda74984f280f36c14_382527_1701678729.jpg', '20121225_19_59_42_137.png', 'The little boy unhappily sat in the corner of the room.', '小男孩不高兴地坐在房间的角落里。', '3_0_20170930071447_18089_c.aac', 'corn角，头 + er名词后缀，人或物 → corner角落', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (145, 'cover up', '/ˈkʌvər ʌp/', 'cover up.mp3', 'phr.掩盖', '22ee90354263c03c74fbce0c0393faff_194238_1574739397.jpeg', '', 'The two brothers tried to cover up the accident to their mother.', '这两个兄弟试图向他们的母亲掩盖这个事故。', 'us_The_two_20241009154627368_77da52e1bd149a3a00e8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (146, 'criminal', '/ˈkrɪmɪnl/', 'criminal.mp3', 'n.罪犯；  adj.犯罪的，犯法的', 'i_24_3900_0_4_20150808223401.jpg', 'd_24_3900_0_4_20150808223401.png', 'The criminal is in prison now.', '这个罪犯现在在监狱里。', 'sa_24_3900_0_4_20150808223401.aac', 'crimin罪 + al表名词 → criminal罪犯', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (147, 'danger', '/ˈdeɪndʒər/', 'danger.mp3', 'n.危险，（坏事或不快之事发生的）可能性', '3_0_20170713071131_76731_c-gigapixel-scale.jpg', 'd_24_15947_0_3_20150808230931.png', 'This sign warned us that we were in danger.', '这个指示牌警告我们有危险。', 'b85bb03a61d2dfc0_1266883009300683440_250207.mp3', 'dan(g)房子，家庭 + er名词后缀，表人或物 → 家庭抵御危险(法语传入) → danger危险', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (148, 'dash', '/dæʃ/', 'dash.mp3', 'v.猛冲，突进；  n.破折号', 'd4a9e16afcb5b7938121545adbe3e9ba_86650_1565951465.jpg', 'd_16_4836_0_2_20150808224500.png', 'The woman is dashing forward.', '这个女人朝前猛冲。', '9567853f547998ff_1266883374601055020_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (149, 'deed', '/diːd/', 'deed.mp3', 'n.行为；契约', '3fd6b9d73426483bc68804b1e98506f5_88929_1562661013.jpg', 'd_24_774_0_4_20150808223129.png', 'The kind man did many good deeds for people.', '这个善良的男人为人们做了很多好事。', 'us_The_kind_20220704174309291_d6f8d27ca47428671ee4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (150, 'depend on', '/dɪˈpɛnd ɑn/', 'depend on.mp3', 'phr.依靠，依赖；取决于', '1b7ca998420b58750a31b2667f99d004.jpg', '', 'Trapped under the collapsed house', '他被困在倒塌的房子下面，靠着这块巧克力维持生命。', '4ca6e7b9fc82524c4f9335e6269d5695_46318_1599622375.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (151, 'draft', '/dræft/', 'draft.mp3', 'n.草稿；  v.起草', 'c5087ce70e431a43eb330e2a5703b6d6_149874_1565345680.jpg', 'd_16_3962_0_3_20150808223906.png', 'This is just the draft of a building.', '这只是建筑的设计草图。', 'us_This_is_20250430165712239_5122c56158080010c0fe.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (152, 'dry', '/draɪ/', 'dry.mp3', 'adj.干的，干旱的；  v.弄干', '278b0e5fadb772ba3c943e05a571ee6d_99520_1577951030.jpeg', 'd_24_16638_0_4_20150808231737.png', 'These flowers are dry but still beautiful.', '这些花干了也挺漂亮。', '96a96e739d7386fc_1266741765139311568_250113.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (153, 'dumb', '/dʌm/', 'dumb.mp3', 'adj.愚笨的；  v.使沉默', 'b7abd2cf45d7c4122507d869ced4dd4e_193566_1538643081.jpg', 'd_1_6425_0_2_20150808125139.png', 'It\'s dumb to row on the cracked soil.', '在龟裂的土地上划船是件很蠢的事情。', 'us_Its_dumb_20241021101425616_f0beb7138c14ab1a15e7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (154, 'elaborate', '/ɪˈlæbəˌreɪt/', 'elaborate.mp3', 'adj.精心设计的，精巧的；  v.详细说明，详尽阐述', '4a2b0d99ee434324a0ca6dd2c5e769d5_100248_1586772042.jpeg', 'd_107_5987_0_2_20150809014744.png', 'This elaborate wood carving features delicate flowers.', '这件精巧的木雕上有精致的花朵。', '976kb4keesjvyt2t58fr2mzjc564dmcy.mp3', 'e=ex向外 + labor努力劳动 + ate表动词 → elaborate精心制作', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (155, 'entrance to', '/ˈɛntrəns tu/', 'entrance to.mp3', 'n....的入口，进入权，进入许可', '35db2f1c2b224021be4ca4fd82192964.jpeg', '', 'The reporter gained entrance to the hotel by pretending to be a cleaner.', '记者装扮成清洁工从而进入酒店。', '06fa06e38439bea95bdd7fa92ae64db3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (156, 'European', '/ˌjʊrəˈpiːən/', 'European.mp3', 'adj.欧洲的；欧洲人的；  n.欧洲人', '3885e624dd93e69a71a346cfb5e7be0a_109785_1524816740.jpeg', 'd_94_12601_0_4_20150809010031.png', 'These are all flags of European countries.', '这些是欧洲国家的国旗。', '944643cc370a6eb7_1266763446107855506_250117.mp3', 'Europe欧洲 + an表示属于…的 → European欧洲的，欧洲人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (157, 'exhibit', '/ɪɡˈzɪbɪt/', 'exhibit.mp3', 'n.展览会，陈列品；  v.展览，陈列', 'dfd51c42441f4d5a3bc81b6acb67ad7c_182170_1527909472.jpg', 'd_107_9114_0_2_20150809024255.png', 'Let\'s go to see the Picasso exhibit tomorrow.', '我们明天去看毕加索的展览吧。', 'b7f343f6847caa810c386798d38d3e9d_29471_1528942449.mp3', 'ex出 + hibit拿住 → 拿来 → exhibit展览，显示', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (158, 'filter', '/ˈfɪltər/', 'filter.mp3', 'n.过滤（器）；  v.过滤，渗透', 'ae46065ba33ba996c80056dbd7870461_67864_1564370466.jpg', 'd_1_4106_0_2_20150808122342.png', 'The water filter is used to purify the water.', '净水器用以净化水。', '9e4dca39dd3709a01c814729d4e7b9d3_32164_1564370465.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (159, 'finally', '/ˈfaɪnəli/', 'finally.mp3', 'adv.最终，终于', '3_0_20170930071205_55704_c-gigapixel-scale.jpg', 'd_1_4930_0_2_20150808123158.png', 'He finally found the right key after trying all the others.', '在试了其他所有钥匙之后，他最终找到了对的那把。', 'cklsebc5l7449q3puupynp2tav7lm9aw.mp3', 'fin结束，范围 + ally表示方式、程度、状态 → finally最后', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (160, 'for the present', '/fɔːr ðə ˈpreznt/', 'for the present.mp3', 'n.目前', 'dd674fdd590265a308bf167b15d77aa0.jpg', '', 'They don\'t need to worry about buying a bigger house', '至少在目前，这对夫妻不用为买套更大的房子而担心。', '84130edbe09bee2787cd6f43e66a3066.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (161, 'fulfill', '/fʊl\'fɪl/', 'fulfill.mp3', 'v.履行，实现，完成；满足（愿望、要求等），使满意', 'f0cb5ce989cb0daadc4ded7ef76912f0_75914_1538661116.jpg', 'd_1_10969_0_2_20150808131735.png', 'She fulfilled her goals on the list.', '她完成了清单上的目标。', '3747527e7eccae05fcdf2394a230f421_10390_1538661144.mp3', 'ful完全，完整 + fill填满 → 完全填满 → fulfill实现，完成', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (162, 'generous with sth.', '/ˈdʒenərəs wɪð ˈsʌmθɪŋ/', 'generous with sth..mp3', 'phr.在……方面大方', '41fec0925825c8b8dd6f123d99321231.jpg', '', 'He\'s generous with money', '他在金钱方面很大方，一直帮助穷人。', '083b4cde981da6af615602e777998b1a_45344_1593576109.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (163, 'genetic', '/dʒəˈnetɪk/', 'genetic.mp3', 'adj.遗传的', '9feac3f34573eaf6120606f251edd492_66843_1584931323.jpeg', '20140627_00_12_27_297_v3.png', 'Once I saw her mother', '一看到她母亲，我就明白了她的金发是遗传的。', '6c21cb67f5f29dd809582beab1cd0988_45394_1584956470.mp3', 'gen出生，产生 + etic与……相关的 → 与出生相关的 → genetic基因的，遗传学的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (164, 'go after', '/gəu\'ɑ:ftə/', 'go after.mp3', 'phr.追求', '3ab679e6b19cfca5e5053a330fdceb7b.jpg', '', 'He kept going after his dream.', '他一直坚持追求自己的梦想。', '5e6b4c719e7b4dfd41714df491832830.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
