INSERT INTO `words` VALUES (166, 'go in for', '/ɡoʊ ɪn fɔːr/', 'go in for.mp3', 'phr.从事', 'fc594fa48db23a1fd77d34eeb742cc46_69951_1707023317.jpg', '', 'I might go in for teaching.', '我可能会从事教育工作。', 'us_I_might_20240204115849707_5368eba775d529216c1d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (167, 'grand', '/ɡrænd/', 'grand.mp3', 'adj.壮丽的，宏伟的，宏大的；  n.一千美元；大钢琴', '7e7b9e5a44e9ecb0d0e9628fa1e7f01e_100959_1584955417.jpeg', 'd_24_3912_0_4_20150808223403.png', 'The hotel lobby was very impressive and grand.', '这家酒店的大厅非常宏伟壮观。', '30bf28b650df6c6812315d09c5152ba0_42482_1584955379.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (168, 'graphic', '/ˈɡræfɪk/', 'graphic.mp3', 'adj.形象的', '3_0_20160724070749_37676_c-gigapixel-scale.jpg', '20140918_03_54_40_666_v3.png', 'She gave a graphic description of the bloody battle.', '她生动地描述了这场激烈的战争。', '3_0_20160724070749_1631_c.aac', 'graph写，图 + ic表示“……的” → graphic生动的，形象的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (169, 'grind', '/ɡraɪnd/ ', 'grind.mp3', 'v.研磨；折磨；  n.苦差事，苦活儿', '2209e8296cb15821375c10b473fc1161_62250_1740463800.jpg', 'd_107_1315_0_2_20150809001806.png', 'This tool can grind the beans into powder.', '这种工具能将豆子磨成粉。', 'us_This_tool_20240115131927336_dcdf48c089b2eb0133b8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (170, 'guilty of', '/ˈɡɪlti əv/', 'guilty of.mp3', 'phr.有罪', '6ffcd394b7dc54c0c7a3d5213d29069e.jpeg', '', 'He has been found guilty of having an illegal income. ', '他犯了获取非法收入的罪。', '6ee3ab287adcb833af490254599744c5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (171, 'hand down', '/hænd daʊn/', 'hand down.mp3', 'phr.把...传下来', '8be4611dc05ec31bee07de41fc1664a8.jpg', '', 'The father is handing down the precious painting to his son.', '父亲正把这幅珍贵的画传给自己的儿子。', '4b71e2e3032e83f553af3b148d7c8d4f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (172, 'harbor', '/\'hɑːbə/', 'harbor.mp3', 'n.海港；避风港；  v.庇护；心怀（怨恨等）', '556cf8f39170009cf577a0a2cd85e62a_170285_1571126124.jpeg', 'd_105_10588_0_2_20150809061746.png', 'The harbor is full of boats.', '海港里面满是船只。', '15aca27638e886e0f1143b8272445525_25088_1572408000.mp3', 'har军队，队伍 + bor保护，庇护所 → 保护地 → harbor避风港，海港', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (173, 'have on', '/hæv ɑːn/', 'have on.mp3', 'phr.穿着', '3c7de4531780d7e4d8a02be23bea9351.jpg', '', 'The girl has her favorite T-shirt on.', '女孩穿着她最喜欢的T恤。', '8fa0b3a85dabfee8e13a7281e770e392.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
