INSERT INTO `words` VALUES (175, 'heaven', '/ˈhevn/', 'heaven.mp3', 'n.天堂；极乐世界', '883e54b4662c3b9eb8156ffac2a20066_185070_1578559969.jpeg', '20121225_19_55_17_568.png', 'The cat went to heaven after it died.', '这只猫死后去了天堂。', 'aa67ef3f1939e5eb_1266763557045623340_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
