INSERT INTO `words` VALUES (177, 'hint', '/hɪnt/', 'hint.mp3', 'n.暗示，示意；有益的建议', '3_0_20170926071136_91262_c-gigapixel-scale.jpg', 'd_1_7508_0_2_20150808130001.png', 'She made a gesture to hint that there was no problem.', '她用手势示意一切都没问题。', 'us_She_made_20241009155922969_4b0522af5e906d36d7ce.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
