INSERT INTO `words` VALUES (179, 'impact on', '/ˈɪmpækt ɑn/', 'impact on.mp3', 'phr.对……产生影响', 'cb6b46f8864d4b99bbfa4e819f5dd8ff.jpeg', '', 'The impact of global warming on the Earth could be terrible.', '全球变暖对地球的影响可能会很糟糕。', '48768e77ee6bf1df60f3058902af02b5_19951_1619319833.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (180, 'in spite of', '/ɪn spaɪt ʌv/', 'in spite of.mp3', 'conj.尽管，不管', 'i_903_-903_0_1_160130160448.jpg', '', 'In spite of their old age', '尽管年事已高，我的祖父母仍然充满活力。', 'f62b818ce2047ec5_1266883324694801332_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
