INSERT INTO `words` VALUES (185, 'June', '/dʒuːn/', 'June.mp3', 'n.六月', '3_0_20170714071139_87761_c-gigapixel-scale.jpg', 'd_24_17906_0_3_20150808233422.png', 'Children\'s Day falls on June 1st.', '儿童节在六月一日。', 'us_Childrens_Day_20250722171731938_320e6305f8e99bd4194a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
