INSERT INTO `words` VALUES (187, 'lag', '/læɡ/', 'lag.mp3', 'v.落后，滞后；缓慢进行，减退；  n.落后，延迟', 'ad3d1800e4f1ed87acd927aad968c710_372321_1708236812.jpg', '20140928_06_13_59_128_v3.png', 'He tends to lag during long races.', '他在长距离赛跑时常常落后。', 'us_He_tends_20240218141401394_e637ccc96a2b5a921e54.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
