INSERT INTO `words` VALUES (189, 'leave...out', '/liːv aʊt/', 'leave...out.mp3', 'phr.不考虑，排除在外', 'i_36_20118_0_3_20150808104520.jpg', '', 'That\'s not quite complete: you left out one small detail.', '这还不是很完整：你遗漏了一个小细节。', 'us_Thats_not_20241009154208008_17100b988f0a6f6024ae.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (190, 'liable', '/ˈlaɪəbl/', 'liable.mp3', 'adj.（for）有责任的；有义务的；（to）会……的，有……倾向的；易于……的，有可能……的', 'i_1_4744_0_3_20150808122949-gigapixel-scale.jpg', 'd_1_4744_0_3_20150808122949.png', 'You committed the crime', '你犯了罪，所以现在你要对后果负责。', 'sa_1_4744_0_3_20150808122949.aac', 'lia捆绑，捆扎 + ble形容词后缀 → 与...绑定的 → liable有责任的，有可能的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (191, 'lip', '/lɪp/', 'lip.mp3', 'n.嘴唇；唇状物', 'i_1_5635_0_4_150910152654-gigapixel-scale.jpg', 'd_24_5635_0_3_20150808224237.png', 'Her lips are the most beautiful part of her face.', '她的嘴唇是她脸上最漂亮的部位。', '3df2410212502dce_1266883010745096924_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
