INSERT INTO `words` VALUES (194, 'lord', '/lɔːrd/', 'lord.mp3', 'n.有爵位的贵族；  v.逞威风；  v.称…为勋爵', '61851ab94fcb44d008fcc9a31d0982b5_65769_1565322791.jpg', '', 'He\'s an English lord honored by the King.', '他是一个被国王册封的英国贵族。', 'sa_1_4921_0_3_20150808123150.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
