INSERT INTO `words` VALUES (196, 'loyalty to', '/ˈlɔɪəlti tuː/', 'loyalty to.mp3', 'phr.对……忠诚', 'ecaad891fd835282a3b9441deb3333a2.jpg', '', 'The dog has loyalty to its master and is waiting for his return.', '这只狗对主人忠诚，正等着他回来。', '73637ec32d053b036aa4a47995828d4d_47120_1593586497.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (197, 'machine', '/məˈʃiːn/ ', 'machine.mp3', 'n.机器，机械装置；  v.用机器加工', 'i_16_15936_0_6_151119142550-gigapixel-scale.jpg', 'd_24_15936_0_3_20150808230858.png', 'You can use this machine to make coffee.', '你可以用这台机器冲咖啡。', 'fl83hum6rbj3a7t7b7ukz889sr5ddb5x.mp3', 'mach机器 + ine表名词 → machine机器', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (198, 'make out', '/meɪk aʊt/', 'make out.mp3', 'phr.理解', 'i_908_-908_0_1_160225180657.jpg', '', 'I couldn\'t make out the answer to this math problem.', '我不知道怎么解答这道数学题。', 'sa_908_-908_0_1_160229113836.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (199, 'manage', '/ˈmænɪdʒ/', 'manage.mp3', 'v.管理', '3_0_20160521110946_76903_c-gigapixel-scale.jpg', 'd_24_4901_0_4_20150808223622.png', 'He managed his time well to complete all of his tasks.', '他将自己的时间管理得非常好，完成了他的所有任务。', '3_0_20160521110946_61091_c.aac', 'man手工，亲手 + age → 动手操作 → manage管理', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (200, 'manufacture', '/ˌmænjuˈfæktʃər/', 'manufacture.mp3', 'v.（批量）生产，制造；  n.制造业；（复数）产品', '68e586620915d4e95f01f2350b115966_90685_1533104917.jpeg', 'd_1_5767_0_2_20150808124350.png', 'This factory uses machines to manufacture goods.', '这家工厂用机器制造产品。', 'd22dd42724d4790e41f0320d914e5a7c_46934_1533104892.mp3', 'manu手 + fact做，制作 + ure名词后缀 → 手做 → manufacture制造业（机器发明前用手做）', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (201, 'memory', '/ˈmeməri/', 'memory.mp3', 'n.记忆', 'i_1_7901_0_3_20150808130119-gigapixel-scale.jpg', 'd_75_7901_0_3_20150809025718.png', 'My memory of Paris is more beautiful than the photos.', '我对巴黎的记忆比照片美多了。', 'us_My_memory_20250721083416340_0133a38f4ee475d31758.mp3', 'memor记忆 + y → memory记忆，记忆力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (202, 'method', '/ˈmeθəd/', 'method.mp3', 'n.方法；条理', 'i_24_10976_0_3_20150808230501-gigapixel-scale.jpg', 'd_24_10976_0_3_20150808230501.png', 'This is the correct method for washing your hands.', '这是正确的洗手方法。', 'us_This_is_20250822171803563_22936aec18dcfe38e4f2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (203, 'microscope', '/ˈmaɪkrəskoʊp/', 'microscope.mp3', 'n.显微镜', '8b5d54b5fc5f9a8a69f162486ad66907_82133_1565342861.jpg', 'd_105_6816_0_2_20150809060042.png', 'I can see really tiny things through this microscope.', '我可以用这台显微镜看到很小的东西。', 'f96geehd98gwh9zrfy8gv43ekgffty9b.mp3', 'micro微，小 + scope看 → 看小东西 → microscope显微镜', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (204, 'mouth', '/maʊθ/', 'mouth.mp3', 'n.嘴', '0c7fb847acd4f008c9f45340e249e7e5_62985_1656927689.jpg', 'd_24_16610_0_3_20150808231635.png', 'The boy opens his mouth wide.', '男孩张大了嘴巴。', '8ca31d37b681f07f_1266763527149738670_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (205, 'name after', '/nem ˈæftɚ/', 'name after.mp3', 'phr.以……命名', '0766853102af8d43c006dc23cf0c45c9_123127_1621912638.jpg', '', 'The new school was named after the former headteacher.', '这所新学校是以前任校长的名字命名的。', '2e1daac334b652bc7e920ac3f879d5a9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (206, 'nevertheless', '/ˌnevərðəˈles/', 'nevertheless.mp3', 'adv.然而，不过', '9a7d9df9daf673baf47aa5e371607ed7_48748_1707272318.jpg', 'd_107_3878_0_2_20150809003306.png', 'Our defeat was expected but it is disappointing nevertheless.', '我们的失败是意料中的事，尽管如此，它还是令人失望。', '9438dc7a038d7aa4_1266883375916165996_250207.mp3', 'never从不 + theless无……的 → nevertheless然而', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (207, 'no more', '/noʊ mɔːr/', 'no more.mp3', 'phr.不再', 'a15c455eabb8d8303e8bdeb95a916683.jpeg', '', ' He is totally full up and can eat no more.', '他吃得很饱了，再也吃不下了。', 'e990e49ef241bbc6e25676ea68ff1e96.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (208, 'north', '/nɔːrθ/', 'north.mp3', 'adj.北方的；  adv.向北方；  n.北方', '20120729_03_20_04_763-gigapixel-scale.jpg', 'd_24_17628_0_3_20150808233054.png', 'Polar bears live near the north pole.', '北极熊生活在北极附近。', 'tpu5ff4ufw2jqkp47wgcu6gbxvzwpz7b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (209, 'October', '/ɑːkˈtoʊbər/', 'October.mp3', 'n.十月', 'fc698d0331ccd608cc6509ef43f2475f_72776_1574765334.jpg', 'd_24_17634_0_3_20150808233123.png', 'October is my favorite month of the year.', '十月是一年中我最喜欢的月份。', 'cf3f973cebc66cb0_1266763405572659822_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (210, 'omit', '/əˈmɪt/', 'omit.mp3', 'v.删去，省去，忽略；遗漏', '9ecee3f8c26b4ac9030f93010f218ea6_359888_1619403197-800-600.jpg', 'd_107_5445_0_2_20150809012604.png', 'You should omit those repeated words in the article.', '你应该把文章里那些重复的词删掉。', '3_41_20170331154651_53351_c.aac', 'o表强调 + mit放手，送出 → omit除；省略', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (211, 'on a large scale', '/ɑn ə lɑrdʒ skeɪl/', 'on a large scale.mp3', 'adv.大规模地', 'b8868379d5479f4566551700125a04d1.jpeg', '', 'The new machines help to produce products on a large scale.', '新机器有助于大规模地生产产品。', '916a3c2b1968b481080819aaf28bf4bb.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (212, 'online', '/ˈɑːnlaɪn/', 'online.mp3', 'adj.在线的，联网的；  adv.从网上，在网上', 'i_1_8605_0_3_20150808130917-gigapixel-scale.jpg', 'd_109_8605_0_2_20150809055717.png', 'Online shopping provides a more convenient way of shopping.', '网络购物是一种更方便的购物途径。', 'dk64tb4t3f5npfvwycgfxjrbdj3kqsw7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (213, 'opportunity', '/ˌɑːpərˈtuːnəti/', 'opportunity.mp3', 'n.机会，良机', 'i_13_3865_0_4_160108114720-gigapixel-scale.jpg', '20130510_18_32_37_729.png', 'Look at the shooting stars! Let\'s seize the opportunity to make a wish.', '看，有流星！让我们抓住机会来许个愿吧。', 'sa_21_3865_0_4_160111164101.aac', 'opportun有机会的 + ity名词后缀 → opportunity机会', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (214, 'outlook', '/ˈaʊtlʊk/', 'outlook.mp3', 'n.景色，风光；观点；前景', 'i_1_6719_0_5_150919164249-gigapixel-scale.jpg', 'd_107_6719_0_2_20150809020824.png', 'The outlook of the mountains is very grand.', '群山的景色非常壮观。', 'd30913cf69848c86_1266797979958008566_250123.mp3', 'out胜过，超过 + look看 → outlook观点，看法，展望', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (215, 'palace', '/ˈpæləs/', 'palace.mp3', 'n.宫殿', 'e87a762657421b3303eeeab29053ec1a_192804_1576725274.jpeg', 'd_24_5067_0_3_20150808223855.png', 'The first snow this winter covered the palace in a blanket of white.', '今年冬天的初雪给这座宫殿盖上了一层雪白的毯子。', '4yzxneyghcaz5mzmkscmvlvy7y8hst9x.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (216, 'participant', '/pɑːrˈtɪsɪpənt/', 'participant.mp3', 'n.参与者，参加者', '8ec92276d5e8e947277731da5d4c54f3_92667_1570694126.jpeg', '', 'Every participant focused on the lecture.', '每个参与者都聚精会神地听了演讲。', '1d854d0944384b7d63051bc6440cdd80_24904_1570694124.mp3', 'parti准备 + cip拿，抓，握住 + ant名词后缀，表示人 → participant参与者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (217, 'pay', '/peɪ/', 'pay.mp3', 'v.支付，偿还', '828eba85e4ac31aac43a0850c1451b36_88747_1578561190.jpeg', 'd_24_15909_0_4_20150808230753.png', 'He paid for his coffee and bread.', '他付了咖啡和面包的钱。', '59b2kqclb54fmy2h6mn7ykpat444rb5y.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (218, 'pay off', '/peɪ ɔːf/', 'pay off.mp3', 'phr.付清；取得成功，使得益', 'i_11_4879_0_2_20150808154612.jpg', '', 'After years of hard work', '经过多年的努力工作，我终于还清了债务。', 'sa_11_4879_0_2_20150808154612.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (219, 'penny', '/ˈpeni/', 'penny.mp3', 'n.美分', 'dc43ab7b7a76ee56c5efad14dc296e17_145681_1656985986-800-600.jpg', 'd_24_17026_0_3_20150808231935.png', 'His parents give the little boy a penny a day.', '小男孩的父母每天给他一美分。', '81bad93bade1259b3708d4dfc9a2fabc_15719_1585376857.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (220, 'personal', '/ˈpɜːrsənl/', 'personal.mp3', 'adj.个人的，私人的', '3d55a1313666f83720d11bdc9702f3fc_184399_1578559511.jpeg', '2b0ff49c2a52ef97857d62d46f5de75c_31382_1539341354.png', 'He is riding his personal bike.', '他正在骑他自己的自行车。', 'd16b935458d032e9_1266797984652766026_250123.mp3', 'person人 ＋ al...的 → personal个人的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (221, 'pollution', '/pəˈluːʃn/', 'pollution.mp3', 'n.污染物', '1b7654331e150ed734787fd330c1d52f_89073_1595057498.jpg', '20121227_13_58_50_724.png', 'Pollution from the factories made the sky turn gray.', '工厂带来的污染使天空变成了灰色。', 'erplml5mprp9x2sbwyuh8v6q56hta8mv.mp3', 'pollut污染 + ion表示行为、行为的过程或结果、情况、状态 → pollution污染', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (222, 'portable', '/ˈpɔrtəbl/', 'portable.mp3', 'adj.轻便的，手提的，便携式的', '023ea44b5df9abcd911b791ab5e1f322_84857_1565322691.jpg', 'd_48_13781_0_4_20150809011832.png', 'I prefer portable computers—they\'re more convenient.', '我更喜欢手提电脑——它们更方便。', '3509b4bedddbf00aef73d7eca43d35b7_19794_1609122112.mp3', 'port拿，运 + able能…的 → portable可携带的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (223, 'potential', '/pəˈtenʃl/', 'potential.mp3', 'n.潜力，潜能；  adj.潜在的，可能的', '3_0_20170930071649_4913_c-gigapixel-scale.jpg', '20141010_01_20_48_675_v3.png', 'Just like the pony', '正如这匹小马一样，我们都有进步的潜力。', '3_0_20170930071649_85819_c.aac', 'potent能力，动力 + ial……的 → 由“能力”引申为“潜力” → potential潜力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (224, 'proud', '/praʊd/', 'proud.mp3', 'adj.骄傲的，自豪的', '9a6f173341fb48a646e7db0f58c57383_36372_1752642321.jpg', '20121227_14_00_53_958.png', 'He\'s proud of himself because everyone thinks he did a great job!', '他为自己骄傲，因为大家都觉得他做得很棒！', '220656ffc4659b3d_1266883113778698930_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (225, 'raw', '/rɔ:/', 'raw.mp3', 'adj.生的，未煮过的；未加工的；（因皮肤开裂）疼痛的', '3_0_20170713071255_70748_c-gigapixel-scale.jpg', 'd_16_3992_0_6_20150808223926.png', 'The beef on the wooden board is raw.', '木板上的牛肉是生的。', '7lky8lrhd4u3z7xp5knxk8hhe2eqdlu5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (226, 'reference', '/ˈrefrəns/', 'reference.mp3', 'n.参考；  v.给（书等）附参考资料', '675d473f71dbdd23185284d376cf39e4_194718_1565690774.jpeg', 'd_16_7128_0_2_20150808231527.png', 'The student working on his paper is taking references from books.', '这个写论文的学生正在翻书作为参考。', '5ccecbf1ed69be60186e82620dcd6dee_47552_1574674629.mp3', 're再次 + fer带来，拿来 + ence名词后缀 → 再次拿来用的 → reference参考；引证', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (227, 'regard...as', '/rɪˈɡɑːrd æz/', 'regard...as.mp3', 'phr.将……认为', '012028e376b6346dd81272ad450f1450.jpg', '', 'She regards him as her biggest enemy.', '她将他视为自己最大的敌人。', '6490bed928bba68a504594388e478c2d_41998_1600079653.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (228, 'remind', '/rɪˈmaɪnd/', 'remind.mp3', 'v.提醒', 'c2f0f4170c2eefcc4804102ed2c33d6e_79424_1586513536.jpg', 'd_24_5820_0_4_20150808224355.png', 'The alarm clock reminds me that I have a meeting this afternoon.', '闹钟提醒我今天下午有一个会议。', '180b096c92fb4d69_1266883330825890612_250207.mp3', 're再 + mind思考，神智 → 再次思考 → remind提醒', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (229, 'rescue', '/ˈreskjuː/', 'rescue.mp3', 'v.营救，解救；  n.救援', '04782b5cde85ee580f401d7ed91ead1a_122932_1717743630.jpg', 'd_16_5843_0_2_20150808225933.png', 'The brave puppy successfully rescued the kitten trapped in the gap.', '勇敢的小狗成功救出了被埋在缝隙中的小猫。', 'e6324172093d63e8_1266883379015232256_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (230, 'rocket', '/ˈrɑːkɪt/', 'rocket.mp3', 'n.火箭，火箭弹', '604aaba2806c6c33f9e9729e26bcded6_30676_1565628013.jpg', '20130307_16_43_55_341.png', 'The red rocket is flying over the clouds.', '红色的火箭在云层上飞行。', 'w92em6cmsrf8xaqk4dz24vg2dmwt85tv.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (231, 'rural', '/ˈrʊrəl/', 'rural.mp3', 'adj.乡村的，田园的', '37e996773f960be071c80bed06ed0ef2_128166_1543905334.jpeg', 'd_105_5567_0_2_20150809054836.png', 'The rural area is beautiful and peaceful.', '乡村的环境是美好而宁静的。', '1c2b43e038fd6ff878e564bdaa6213af_14309_1624261329.mp3', 'rur农村 + al表形容词 → rural乡村的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (232, 'sake', '/seɪk/; /ˈsɑːki/', 'sake.mp3', 'n.理由', '793bfd8c5d7632f577152efea596a946_91413_1585282095.jpeg', '', 'He wears the helmet for safety\'s sake.', '出于安全考虑，他戴着头盔。', 'b1d0a6f8b4952451a0b97fedaf9d23a5_14622_1585282107.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (233, 'secure from', '/sɪˈkjʊr frʌm/', 'secure from.mp3', 'phr.保护，使免受...(侵害等)的', 'ad7f9a49d6a46b4ea2c68cdbd2a3812c.jpeg', '', 'Their house is secure from the flood.', '他们的房子不会被洪水所淹。', '21c14830e20aa222552d3ce7a90cd5ff.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (234, 'send in', '/send ɪn/', 'send in.mp3', 'phr.递送', 'db6c350722d189501ae78dcd1700203c.jpeg', '', 'He completed the form and sent it in as soon as he could.', '他填好了表格，并尽快提交了。', 'fa8253269380f681e4713a136ae8c0b0_42910_1599552959.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (235, 'September', '/sepˈtembər/', 'September.mp3', 'n.九月', 'i_16_15930_0_4_151222173234-gigapixel-scale.jpg', 'd_24_15930_0_4_20150808230848.png', 'September 5th is my birthday. It\'s coming soon!', '9月5日是我的生日，就快要到了！', 'us_September_5th_20250122141450405_27a4be078bba64a07af1.mp3', 'Septem七 + ber → 古罗马的七月，历法修改后沿用成了九月 → September公历九月', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (236, 'shift', '/ʃɪft/', 'shift.mp3', 'v.换挡；改换，替换；转移；  n.轮班', 'bad1ea246958456aed62e92ce8414951_79390_1623839041.jpg', 'd_1_3921_0_2_20150808122056.png', 'You have to shift gears as you drive around the corner.', '你开车驶过拐角时要换挡。', 'aab5028d26b9857e5fc28935aa3729c4_37314_1522662753.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (237, 'significance', '/sɪɡˈnɪfɪkəns/', 'significance.mp3', 'n.意义，含义；重要性', '61facbe9e806f6ecbc41b87e3a2d8da0_129702_1552533087.jpeg', 'd_16_2355_0_2_20150808223533.png', 'The wedding anniversary is of great significance to the couple.', '结婚纪念日对这对夫妻来说意义重大。', 'f27c54d51d6b9c27f88e71583c2bcf7f_30341_1552533092.mp3', 'signific=signify有重要性的 + ance名词后缀 → significance重要性；意义', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (238, 'silent', '/ˈsaɪlənt/', 'silent.mp3', 'adj.沉默的，不说话的；  n.无声电影', '008bd48908557e8b63bfb36e8ba496c1_100775_1588080651.jpeg', 'd_24_5703_0_4_20150808224306.png', 'We should keep silent in the library.', '在图书馆里我们应当保持安静。', 'ff9d129367934fd68cf879117bd4ee8b_48022_1588080656.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (239, 'size', '/saɪz/', 'size.mp3', 'n.大小，尺寸', '38868c2ec8c148c4b865904dedb8b921_190579_1590506771.jpg', 'd_24_17989_0_3_20150808233955.png', 'These shoes come in different sizes: medium', '这些鞋子有不同的尺寸：中号、小号和大号。', '6e09ca9d73732d80_1266763524204178282_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (240, 'skilful at', '/ˈskɪlfl æt/', 'skilful at.mp3', 'phr.擅长，善于', '90aa251cc919b0187a7683a76a75d280.jpg', '', 'She\'s skilful at drawing.', '她擅长绘画。', '17bc16ba7eb69fd5d779fb2542899048_29216_1593575914.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (241, 'sleepwalk', '/ˈsliːpwɔːk/', 'sleepwalk.mp3', 'v.梦游', '20323ddecb81493de679029b59c9657c.jpg', '', 'The little boy went outside whilst sleepwalking.', '小男孩梦游的时候去了外面。', 'ef5d636fa651053e3af1a4c202ddaac1.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (242, 'slow down', '/sloʊ daʊn/', 'slow down.mp3', 'phr.放慢速度', '183342e27da4e4c30ada77d765dcd794.jpeg', '', 'The car slowed down as it approached the crosswalk.', '汽车在接近人行横道时放慢了速度。', 'bdf7da25b647fc57_1266883492116868076_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (243, 'south', '/saʊθ/', 'south.mp3', 'adv.向南方，在南方；  adj.南方的，南部的；  n.南方', '3_0_20170701113128_72520_c-gigapixel-scale.jpg', 'd_24_15908_0_3_20150808230751.png', 'A large number of birds fly south every winter.', '每年冬季，大量鸟类向南方迁徙。', 'fq95b264fwj6l2kwjvxxtcmadzclvmbw.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (244, 'spite', '/spaɪt/', 'spite.mp3', 'n.恶意，怨恨；  v.刁难，欺侮', '6da35a51ac2c29df5d3914106677cf90_193117_1587007968.jpeg', 'd_1_2422_0_2_20150808121841.png', 'The dog peed on his master\'s bed out of spite.', '出于怨恨，这只狗尿在了主人的床上。', '9e898857d0a212e56b5da33c69b939c6_46404_1587007964.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (245, 'sport', '/spɔːrt/', 'sport.mp3', 'n.运动；  v.炫耀，卖弄', '3_0_20170707160007_16116_c-gigapixel-scale.jpg', 'd_24_17290_0_5_20150808232622.png', 'He can play various sports.', '他擅长多种运动。', 'bc1a44b094e62650_1268213311376606144_250930.mp3', 's远离 + port带走，越过 → 不思考严肃的问题 → sport运动，娱乐', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (246, 'steam', '/stiːm/', 'steam.mp3', 'n.蒸汽，水蒸气；  v.冒水汽，冒热气', 'c0be35560f3e13e19991d3bb9e7cda61_123472_1557908347.jpeg', 'd_24_5763_0_4_20150808224332.png', 'Steam is coming from the pot. Turn off the stove!', '水蒸气正在往锅外冒，关火吧！', '3_0_20160528173103_53990_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (247, 'straight', '/streɪt/', 'straight.mp3', 'adj.直的；坦诚的；  adv.直接地', '28ee314def8b10d8a945acefc3af0906_93601_1565342304.jpg', 'd_24_7127_0_3_20150808224954.png', 'The road is very straight.', '这条路很直。', 'sa_1_7127_0_2_20150808125808.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (248, 'submit', '/səbˈmɪt/', 'submit.mp3', 'v.提交；呈递', 'i_1_5826_0_4_151112120448-gigapixel-scale.jpg', 'd_16_5826_0_2_20150808225920.png', 'The man is submitting the report to his boss.', '这个男人正在把报告递交给他的老板。', '76b0280b1e16023f_1266883374222387994_250207.mp3', 'sub下面 + mit放出，发送 → 从下面送出 → submit提交、呈递', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (249, 'succeed', '/səkˈsiːd/', 'succeed.mp3', 'v.成功，达到目的；接替；继承', '3_52_20170417165352_65515_c-gigapixel-scale.jpg', '20130106_14_37_35_898.png', 'I succeeded in shooting three arrows in the center of the target.', '我成功地将三支箭射中了靶心。', '9adc7e97466ccf3a_1266883486734592876_250207.mp3', 'suc在…下面 + ceed走 → 从下走到上面 → succeed成功', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (250, 'successfully', '/səkˈsesfəli/', 'successfully.mp3', 'adv.成功地，圆满地', '0b8507c7d873d054c03829d7890fb4e5.jpg', '', 'The rocket was launched successfully.', '火箭成功发射了。', '0766aef352418855_1266883481372502992_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (251, 'suitable', '/ˈsuːtəbl/', 'suitable.mp3', 'adj.合适的，适宜的', 'f9f43bd1f409cb95ddda53fd2cee206f_28456_1707275653.jpg', 'd_16_10108_0_5_20150808235114.png', 'That\'s a suitable dress for the party.', '那件裙子适合参加派对。', 'us_Thats_a_20240207111444549_22abc537597fde6c25a4.mp3', 'suit适合 + able……的 → suitable合适的，适宜的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (252, 'sum', '/sʌm/', 'sum.mp3', 'n.全部，总和；算术；  v.共计', 'i_33_19904_0_5_20150809001527-gigapixel-scale.jpg', '20141010_01_09_25_679_v3.png', 'The sum of one and one is two.', '一加一的和是二。', '23e728c310c6cc82_1266883369629559666_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (253, 'surprised', '/sərˈpraɪzd/', 'surprised.mp3', 'adj.感到惊讶的，惊喜的', '1425953095270-gigapixel-scale.jpg', '', 'Jenna was very surprised!', '珍娜感到很惊喜！', '9e40e6c45aaec0c5_1266883006525647686_250207.mp3', 'sur超过 + pris奖赏 + ed形容词后缀 → surprised感到惊讶的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (254, 'tennis', '/ˈtenɪs/', 'tennis.mp3', 'n.网球', 'd2cbe3e88f2a973e107b42584128dcd1.jpg', '20141012_17_15_05_912_v3.png', 'My father taught me how to play tennis.', '我父亲教我怎样打网球。', '2abb69437a59252e_1266763445609474952_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (255, 'thin', '/θɪn/', 'thin.mp3', 'adj.瘦的；稀薄的，淡的；  v.变薄，变少', '76bb7189aee64070011c5d3dd284b51e_74307_1731900644.jpg', 'd_24_17659_0_4_20150808233222.png', 'He became very thin due to work stress.', '他因工作压力变得很瘦。', 'us_He_became_20241118113035863_e7b1e669555e6b773a83.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (256, 'thorough', '/ˈθɜːroʊ/', 'thorough.mp3', 'adj.彻底的，完全的', 'i_1_16317_0_3_20150808132211-gigapixel-scale.jpg', 'd_16_16317_0_2_20150809001836.png', 'A thorough brushing will give you fresh breath.', '彻底的刷牙可以使你口气清新。', 'sa_1_16317_0_3_20150808132211.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (257, 'threaten', '/ˈθretn/', 'threaten.mp3', 'v.威胁；危及；恐吓；预示……的恶兆', '8de96b23762b480033cb903df73bdb49_38697_1754642023.jpg', '3c2be1ed5b9e1faee1f46b93057d6e77_103258_1551259250.png', 'The landlord threatened to kick out the tenant if he didn\'t pay the rent.', '房东威胁租客，如果不付房租就把他赶出去。', 'f7b199928d8bc1c0_1266883373838129680_250207.mp3', 'threat威胁 + en动词后缀 → threaten威胁，恐吓', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (258, 'throat', '/θroʊt/', 'throat.mp3', 'n.咽喉，喉咙', '508ee61f2a559eb55d48409ad250ae67_26967_1732244597.jpg', '20121225_19_04_28_717.png', 'I had a sore throat after I caught a cold.', '我感冒后喉咙很疼。', 'rqv9dhpsu4yth4jw6gtv7ufverwwwnd8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (259, 'tube', '/tuːb/', 'tube.mp3', 'n.管子，管道', 'c_i_wm_2999_20120507_03_49_38_604-gigapixel-scale.jpg', 'd_16_5855_0_5_20150808225942.png', 'These tubes are made of steel.', '这些管子都是由钢制成的。', '67f2170d064ac058_1266883324413237940_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (260, 'turn out', '/tɜrn aʊt/', 'turn out.mp3', 'phr.结果是，证明是', '041dceb3ca442fca1d298bfc557476c0.jpeg', '', 'The experiment didn\'t quite turn out like how he had expected.', '实验结果并不像他所设想的那样。', 'w8f6umzysgcah576nfbb6fvavcbwt4r5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (261, 'vocabulary', '/vəˈkæbjəleri/', 'vocabulary.mp3', 'n.词汇（量）；词（汇）表', 'f05083d54cb601ac95c87af3f574e861_96730_1705901228.jpeg', 'd_50_14702_0_4_20150809020015.png', 'He is trying to broaden his vocabulary through learning the dictionary.', '他正在通过学习字典来拓宽自己的词汇量。', 'sa_1000_14702_1_1_150923114954.aac', 'vocabul=vocable词 + ary表名词 → vocabulary词汇', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (262, 'wait', '/weɪt/', 'wait.mp3', 'v.等待；  n.等待', 'd4209c7b86885822bb044eacd4aa3a31_75182_1577949629.jpeg', 'd_24_16608_0_4_20150808231631.png', 'She is waiting for her flight.', '她正在等她的航班。', '3225f39bb05bd1e5_1266763314680081330_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (263, 'weekend', '/ˈwiːkend/', 'weekend.mp3', 'n.周末，星期六和星期日；  v.过周末', '3_0_20170609071036_61511_c-gigapixel-scale.jpg', 'd_24_17198_0_4_20150808232335.png', 'The weekend is coming!', '就要到周末啦！', 'dd27d551509c4814_1266763446367988642_250117.mp3', 'week周 + end结束 → weekend周末', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (264, 'welcome', '/ˈwelkəm/', 'welcome.mp3', 'v.欢迎；  n.欢迎；  adj.受欢迎的', '91e712c3fb06d9249c0df01954110d99_192625_1578563376.jpeg', 'd_24_16639_0_4_20150808231739.png', 'He stood at the door to welcome the student.', '他站在门口欢迎这位学生。', '1cf6fe1927ae9edc_1266763526736534178_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (265, 'agreement', '/əˈɡriːmənt/', 'agreement.mp3', 'n.协议，协定', '94d0f1dc356cebe4df3157d3ff9b07e1_87486_1588921185.jpeg', 'd_11_3855_0_2_20150808145547.png', 'The two businessmen signed a long-term agreement to cooperate.', '这两名商人签署了一份长期的合作协议。', '108df55a7b043639_1266883482377607692_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (266, 'alter', '/ˈɔːltər/', 'alter.mp3', 'v.改变；改动，使变样', '5d874723273adb83ad61139518032783_143610_1595060984.jpg', 'd_12_8374_0_2_20150808172354.png', 'Her face has altered over these years.', '她的面容在这些年里发生了改变。', '34558be58bd1914a85497d9acfae4831_43712_1596782326.mp3', 'alter其他的 → 变成〔其它的）→ alter变更，改变', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (267, 'amend', '/əˈmend /', 'amend.mp3', 'v.修正；改进，改善；修订', '46ce667f23c6f5c82a0bff137aea5a77_36784_1732003036.jpg', '02df1012cd3f2254ed8ae35e94a49fd0_63285_1551259240.png', 'We need to amend mistakes in a timely manner.', '我们应立即修正错误。', 'us_We_need_20241119155701964_e0785e52d5b8b44f68c4.mp3', 'a加强 + mend改正 → 不断改错 → 改正', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (268, 'annoyed', '/əˈnɔɪd/', 'annoyed.mp3', 'adj.恼怒的，烦闷的；  v.使烦恼，打扰', '55f3d05f2bdcfcdfeb8621308a7439cf_96832_1732261554.jpg', '', 'I am really annoyed with my roommate\'s snoring.', '我真的被室友的鼾声搞得很烦。', '7dffd7a6fc0193ab_1266883003524733464_250207.mp3', 'annoy烦人 + ed形容词后缀 → annoyed恼怒的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (269, 'approval', '/əˈpruːvl/', 'approval.mp3', 'n.批准；赞同', 'i_1_15252_0_3_20150808132009-gigapixel-scale.jpg', 'd_107_15252_0_2_20150809025610.png', 'The doctor gives me his approval to leave the hospital.', '医生批准我出院。', 'sa_13_15252_0_9_160427165538.aac', 'ap一再 + prov证明 + al名词后缀 → 赞成', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (270, 'arrive at', '/əˈraɪv æt/', 'arrive at.mp3', 'phr.到达', '60dbea419bc6033b2b88bdc930a8ff2c.jpg', '', 'The school bus arrives at school at 8 a.m. every day.', '校车每天早上8点到校。', '20b933b794e86661ed039b3643f65334.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (271, 'arrow', '/ˈæroʊ/', 'arrow.mp3', 'n.箭；箭头', '3fcbe3bcad0ce35db021bd4dd2060c7d_19369_1709194153.jpg', 'd_24_19531_0_4_20150809001848.png', 'An arrow has a sharp point at one end and feathers on the other.', '箭的一端是尖的，另一端是羽毛。', 'us_An_arrow_20240229160926425_023f7ff1d9f08b9f5133.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (272, 'as a matter of fact', '/æz ə ˈmætər əv fækt/', 'as a matter of fact.mp3', 'phr.事实上，其实', '3_0_20170712071650_73035_c.jpg', '', 'He thinks he\'s so fit. As a matter of fact', '他觉得自己身材很好，事实上，他挺胖的。', '3_0_20170712071650_47449_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (273, 'as far as...be concerned', '/əz fɑːr əz bi kənˈsɜːrnd/', 'as far as...be concerned.mp3', 'phr.就...而言', '190ac625d437dd377a9898e63698b2a4.jpg', '', 'His friends hate durian', '他的朋友都讨厌榴莲，但就他自己来说，榴莲是最好吃的水果。', 'b48f5356623617b7140bea5e69b19166_27161_1626679795.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (274, 'associate with', '/əˈsoʊsieɪt wɪð/', 'associate with.mp3', 'phr.与……常在一起', 'a7b23efa58edf3dfdce71757a0525bb4_135693_1707025938.jpeg', '', 'I associate with my good friends.', '我和好朋友们常在一起。', 'us_I_associate_20240204135222967_e222d8bd81de8dc6d94a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (275, 'at all events', '/ət ɔːl ɪ\'vents/', 'at all events.mp3', 'phr.无论如何', '87b3110e8363beefe91b4ed381876489.jpg', '', 'He knew the weather was bad this week', '他知道这周天气不好，但他无论如何都坚持跑步。', 'e059cbcfc5f9360ae96998bb933af027.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (276, 'attend to', '/əˈtend tu/', 'attend to.mp3', 'phr.照料，关怀', 'd9cc6746f313bb4d39fc76c1515bf6ca.jpg', '', 'The nurse attends to her patients carefully.', '护士精心地照顾着她的病人。', '897b7cca2c5918abc219d46993cf55d9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (277, 'attitude', '/ˈætɪtuːd/', 'attitude.mp3', 'n.态度；姿势', 'f2d41a87029e990f680ce886ebdc043a_70100_1729574955.jpg', '3d08c9134d678e0fa46ba533c3162ed2_27529_1539341553.png', 'A positive attitude is what you need to solve problems.', '你需要以积极的态度来解决问题。', 'd11c923924203c60_1266763527041604264_250117.mp3', 'att=apr倾向 + itude后缀，构成抽象名词 → attitude态度', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (278, 'attract', '/əˈtrækt/', 'attract.mp3', 'v.吸引', 'adbb5705d5f05c3dcf067ed00c07f13c_138147_1732002388.jpg', 'd_24_8393_0_4_20150808225636.png', 'This vibrant flower attracts a butterfly.', '这朵鲜艳的花吸引了一只蝴蝶。', '0814cd3d5431d9db_1266883322394160002_250207.mp3', 'at一再 + tract拉 → 拉过来 → attract吸引', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (279, 'avoid', '/əˈvɔɪd/', 'avoid.mp3', 'v.避免，防止', 'i_1_7123_0_7_151222172036-gigapixel-scale.jpg', '20130106_14_37_44_533.png', 'The driver avoided hitting the dogs on the road.', '司机避免了撞到路上的狗。', 'us_The_driver_20240418132141759_852ab08348eeeb0e52c0.mp3', 'a=out处于 ＋ void空 → 空出来 → avoid避开，避免', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (280, 'back and forth', '/bæk ənd fɔrθ/', 'back and forth.mp3', 'phr.来回地', '25bc2b53734ae25ff00a5fe7a675022f_71118_1569571786.jpeg', '', 'He paced back and forth outside the ward where his wife was giving birth.', '他在妻子的产房外来回踱步。', '31c426baee304a0c24ed1541f19de36a_46432_1569571783.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (281, 'basketball', '/ˈbæskɪtbɔːl/', 'basketball.mp3', 'n.篮球；篮球运动', '300a646b21933d596fbe2a43ab63acb1_511346_1611302510.jpg', 'd_76_11838_0_4_20150809030808.png', 'Girls love to play basketball too', '女生们也喜欢打篮球，而且她们打得不错。', 'fkzfvjsgwntsenqh4k2u5glx7d9w7pvs.mp3', 'basket篮子 + ball球 → basketball篮球', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
