INSERT INTO `words` VALUES (287, 'burn', '/bɜːrn/', 'burn.mp3', 'v.烧；  n.烧伤', '63e1c4e204b0ae4f4a94870fe2ca0d4e_158582_1559705859.jpeg', 'd_24_16009_0_4_20150808231031.png', 'The forest is burning. What a disaster!', '森林着火了。这真是场灾难！', '0dbf7ac08560860b_1266883197121768222_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
