INSERT INTO `words` VALUES (293, 'claim', '/kleɪm/ ', 'claim.mp3', 'n.索赔；主张；断言；  v.索赔', '8cdbd505fbb37b7e9a97cfe0de10076e_83735_1527493221.jpg', 'd_1_4730_0_2_20150808122939.png', 'I want to make an insurance claim for the damage of my car.', '我想为我的汽车遭受的损失提出保险索赔。', 'f16b6e009f297e4d13f3e8199e6312bc_35604_1527493217.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
