INSERT INTO `words` VALUES (301, 'confine', '/kənˈfaɪn/', 'confine.mp3', 'v.监禁；限制；  n.范围，界限，约束，限制', 'i_1_581_0_2_20150808113832-gigapixel-scale.jpg', 'd_1_581_0_2_20150808113832.png', 'I am confined to my jail cell.', '我被囚禁在监牢里了。', '23753c0ed1387df4_1266883378026884050_250207.mp3', 'con加强意义 + fine界限 → confine边界；限制', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (302, 'control over', '/kənˈtrol ˈovɚ/', 'control over.mp3', 'phr.控制', '66e36d58073555ba0dde3a20f83751bb.jpg', '', 'As the finance manager', '作为财务经理，她控制着预算。', 'us_As_the_20250605133918986_90387ffd66d06f37c584.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
