INSERT INTO `words` VALUES (311, 'description', '/dɪˈskrɪpʃn/', 'description.mp3', 'n.描写，形容，叙述', 'i_1_16320_0_4_150907141453-gigapixel-scale.jpg', 'd_95_12379_0_4_20150809012745.png', 'The policeman asked the girl to give a description of the criminal.', '警察让女孩描述一下犯罪嫌疑人的样子。', 'sa_1_16320_0_4_150914160144.aac', 'de向下 + script写 + ion表名词 → 写下来 → description描写', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (312, 'development', '/dɪˈveləpmənt/ ', 'development.mp3', 'n.发展', '3_0_20160520172841_80246_c-gigapixel-scale.jpg', 'd_24_17299_0_4_20150808232635.png', 'This picture shows the development of phones over time.', '这张图展示了电话发展变化的历程。', '3_0_20160520172841_45046_c.aac', 'develop发展 + ment名词后缀 → development发展', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (313, 'devote', '/dɪˈvoʊt/', 'devote.mp3', 'v.献身于，专心致力于，把……专用于', '3_0_20170703171625_93173_c-gigapixel-scale.jpg', 'd_24_5789_0_3_20150808224345.png', 'The chicken jumped into the pot and devoted his life to us.', '这只鸡跳进锅里，为我们献出了生命。', 'a666674f49900f33_1266883635302783700_250207.mp3', 'de加强 + vot发誓 + e → 拼命发誓，以命起誓 → devote将…奉献，致力于', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (314, 'dial', '/ˈdaɪəl/', 'dial.mp3', 'v.拨（电话号码）；  n.拨号盘', '6ae01648cd8e7740e8103e5f7af805bc_81980_1594801034.jpeg', 'd_24_6359_0_3_20150808224612.png', 'I am dialing a number on my phone.', '我正在手机上拨电话号码。', 'f7e3b5fbb29ff304adf77fd1e11baa15_48992_1599530282.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (315, 'difficulty', '/ˈdɪfɪkəlti/', 'difficulty.mp3', 'n.难题；经济拮据', '6f930b5ef850e865c25af95b71395702_131909_1533109953.jpeg', 'd_24_5027_0_4_20150808223829.png', 'The little boy is experiencing some difficulties in math.', '小男孩遇到了一些数学上的问题。', '431a4b749e241a786e900b557efa4845_52154_1533109835.mp3', 'difficult困难的 + y表名词 → difficulty困难', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (316, 'discipline', '/ˈdɪsəplɪn/ ', 'discipline.mp3', 'n.纪律；学科；训练；  v.训练', 'c5345b51d3cdcedb03685e36475928b2_242756_1738991552.jpg', 'd_1_5594_0_2_20150808124041.png', 'These soldiers are showing great discipline.', '这些士兵展现出很强的纪律性。', '88f5f7d48e96253c200a955bad739f48_44038_1588089579.mp3', 'dis分散 + cip拿 + line一条直线 → 使分散的成为一条直线 → discipline纪律', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (317, 'dispose', '/dɪˈspoʊz/', 'dispose.mp3', 'v.处理，处置', 'fb25640a4903edbc4d5bc7d075e3867e_101975_1588087917.jpeg', 'd_107_6591_0_2_20150809020506.png', 'She is disposing of the unwanted vegetables into the bin.', '她正在处理不需要的蔬菜，把它们全扔进垃圾箱里。', 'us_She_is_20241009153953722_c5e6b03bab081fbd6590.mp3', 'dis分开 + pos放 + e  → 分开排好 → dispose处理，处置', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (318, 'dominate', '/ˈdɑːmɪneɪt/', 'dominate.mp3', 'v.支配，统治，控制；在……中占首要地位；耸立于，俯视', 'f5a1aa6395fbcc8d55dcdceca3e4963c_134289_1558594695.jpeg', 'd_1_15250_0_4_20150808132006.png', 'In this household', '在这个家里，猫似乎占据着支配地位。', 'f04790ce8d1d077d88e62f4068522e80_18070_1625728082.mp3', 'domin=dom屋，家 + ate做… → 像家长一样 → dominate支配，统治', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (319, 'double up', '/ˈdʌbəl ʌp/', 'double up.mp3', 'phr.弯着身子', '1b7a8560938f015c62d175d864a5c865.jpg', '', 'The kids all doubled up with laughter.', '孩子们都笑弯了腰。', 'e9c905e698070031e8ca221137deb7cb.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (320, 'dozen', '/ˈdʌzn/', 'dozen.mp3', 'num.一打，十二个', 'i_1_6166_0_4_20150808124749-gigapixel-scale.jpg', 'd_24_6166_0_4_20150808224458.png', 'A dozen eggs now cost twenty dollars—how expensive!', '一打鸡蛋现在要20美元——好贵啊！', 'fb552beefa67d4fe85a00718f2387164_19323_1540957113.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (321, 'dress up', '/dres', 'dress up.mp3', 'phr.盛装，打扮，装饰', '6db8775238a452aeb3e76e9ea0fd0335_60503_1701222637.jpg', '', 'They dressed themselves up as superheros.', '他们把自己打扮成了超级英雄。', 'ktw6fatfy9xd9blef2kymr4vqhdndatz.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (322, 'education', '/ˌedʒuˈkeɪʃn/', 'education.mp3', 'n.教育，培养', '26e2f6645b3c23f08dbda3f5081e987a_99790_1595860717.jpg', 'd_24_16446_0_3_20150808231247.png', 'Nowadays students receive most of their education in the classroom.', '如今，孩子们在课堂上接受大部分教育。', '749432e3b763f374bb25eb74119b4e95_50350_1599449269.mp3', 'e出 + duc引导，带来 + ation行为 → 引出知识的行为 → education教育', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (323, 'effective', '/ɪˈfektɪv/', 'effective.mp3', 'adj.有效的', '30b6af04d15c91b1f36a772e74e8d2df_181100_1534820068.jpeg', 'd_1_7478_0_2_20150808125939.png', 'The medicine she took was effective for treating colds.', '她吃的药对治疗感冒很有效。', '3zw57u49p7p3ee95bncbzxyeqdkvaefs.mp3', 'ef出 ＋ fect做，制作 ＋ ive形容词后缀 → 做出来的 → effective有效的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (324, 'egg', '/eɡ/', 'egg.mp3', 'n.蛋，卵', 'i_1_19104_0_4_151019160748-gigapixel-scale.jpg', 'd_24_19104_0_3_20150809000620.png', 'The eggs were put in the basket.', '篮子里盛着鸡蛋。', 'gg6r2d7cw28ywbjyh322xg5ja5cenezt.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (325, 'enable', '/ɪˈneɪbl/', 'enable.mp3', 'v.使能够，使可能', 'i_1_14834_0_3_20150808131858-gigapixel-scale.jpg', 'd_1_14834_0_3_20150808131858.png', 'Vegetables enable me to keep healthy.', '蔬菜让我保持健康。', '0c33596a9926235e_1266883628389784170_250207.mp3', 'en使…进入状态 + able能够 → enable使能够', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (326, 'enthusiasm', '/ɪnˈθuːziæzəm/ ', 'enthusiasm.mp3', 'n.热情，热心，热忱', '22b9ca44762f7f588f2648fb063b1761_136830_1700445552.jpg', '', 'Those kids always have so much enthusiasm about studying.', '这些孩子总是对学习充满热情。', 'us_Those_kids_20231120095918168_68b530ef062eaace4c21.mp3', 'en进入 + thus = theo神 + iasm状态 → 进入神的状态 → 热情', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (327, 'era', '/ˈɪrə/', 'era.mp3', 'n.时代', 'fa59c57fc69c75b8f3335fefbf696e3c_186542_1588226836.jpg', 'd_1_6220_0_3_20150808124842.png', 'These kinds of costumes were quite popular in the Victorian era.', '这些装束在维多利亚时代非常流行。', 'a71ddae853b79eec_1266883617867324104_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (328, 'evaluate', '/ɪˈvæljuˌeɪt/', 'evaluate.mp3', 'v.评估；评价', '8f51218d22064b9825ff987561111592_328281_1724395659.jpg', 'd_107_4220_0_2_20150809004910.png', 'The judges evaluated her performance and didn\'t give her a pass.', '评委们评估了她的表演，并没有让她晋级。', 'us_The_judges_20240823144744092_d5829dbd4cd6baf40a0a.mp3', 'e使 + valu价值 + ate动词后缀 → 使……定价 → evaluate估价', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (329, 'excess', '/ɪkˈses/', 'excess.mp3', 'adj.额外的，过量的，过度的，附加的（读作/ˈekses/）；  n.超越，超过，过度（读作/ɪkˈsɛs/）', '5baffc73c372e6419977a65852754c77_135751_1575967883.jpeg', '', 'A man threw the excess chickpea into the bin after dinner.', '晚饭后，一个男人把过多的鹰嘴豆扔进了垃圾桶里。', 'us_A_man_20220817185253128_dce8f21cc5f0261173ee.mp3', 'ex出 + cess行走 → excess过度，过剩', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (330, 'expense', '/ɪkˈspens/ ', 'expense.mp3', 'n.花费，费用', 'i_1_8287_0_7_160321101858-gigapixel-scale.jpg', 'd_107_8287_0_2_20150809023029.png', 'Buying a car can be a great expense.', '买车是笔大花销。', '97f85689e30c44dc_1266883014365522718_250207.mp3', 'ex出 + pense付钱 → expense支出，花费，消费', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (331, 'facility', '/fəˈsɪləti/', 'facility.mp3', 'n.设施，设备', '4ef09f5f9e2c5a3ac72c677053fb01ad_129301_1713233747.jpg', 'd_1_4000_0_3_20150808122218.png', 'The facility is so popular that it attracts many visitors.', '这个设施非常受欢迎，吸引了许多人前来打卡。', 'us_The_facility_20240529130617388_a425472d04621584ff72.mp3', 'facile简单的 + ity表名词 → 促进事务简化的设施或工具  → facility设施，设备', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (332, 'faint', '/feɪnt/', 'faint.mp3', 'v.晕倒；昏厥；  adj.（光、声、味）微弱的', '1425953229336-gigapixel-scale.jpg', 'd_1_5971_0_2_20150808124612.png', 'The hot weather made him faint.', '炎热的天气使他晕倒了。', 'sa_1_5971_0_2_20150808124612.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (333, 'false', '/fɔːls/', 'false.mp3', 'adj.错误的', 'a27b192e691d70d7da8ee922ddf9b169_60728_1557048138.jpg', 'd_24_6642_0_4_20150808224704.png', 'Is this question true or false?', '这道题是对还是错？', 'sa_1_6642_0_3_20150808125309.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (334, 'fancy', '/ˈfænsi/', 'fancy.mp3', 'adj.奢华的；  n.喜爱；  v.想象，幻想', '909a566821b73d35e0519e486845263f_99234_1585132534.jpeg', 'd_107_6341_0_2_20150809015702.png', 'The big', '这家装饰华丽的大餐厅几乎空无一人。', '758d18d753380cb51cb76b66513c80f7_50512_1585132532.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
