INSERT INTO `words` VALUES (338, 'formal', '/ˈfɔːrml/', 'formal.mp3', 'adj.正式的；正规的，规范的；形式上的；礼节上的', '4f35224d00fe1e2179fe85505371925c_110201_1701221937.jpg', '', 'His job requires formal dress', '他的工作需要正式的着装，比如讲究的鞋子、衬衫和领带。', 'us_His_job_20231129100854406_03a987d753c3aa2d04fb.mp3', 'form形式 + al…的 → formal正式的，正规的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (339, 'forum', '/ˈfɔːrəm/', 'forum.mp3', 'n.论坛；讨论会', 'acf44c9383b8b180469839cc7aa9c3eb_145627_1522657115.jpg', '20140806_22_27_56_137_v3.png', 'The experts are sharing their knowledge at the forum.', '专家们正在论坛上分享他们的知识。', 'd8e0dd0dcca38e607b54b909356f5fb2_33882_1522657102.mp3', 'for(a)讨论 + um名词后缀：场所 → forum论坛', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (340, 'free from', '/friː frʌm/', 'free from.mp3', 'phr.免于……，不受……', '0c69b6e9993bc223ded95aa17a1f7045.jpg', '', 'Weekends can help to free office workers from stress. ', '周末可以帮助上班族摆脱压力。', '633fac02d67f611124aa8436eebc33fb.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (341, 'give back', '/ɡɪv bæk/', 'give back.mp3', 'phr.归还；送回', '7a427f4e59ac66eed11158ab13acccf0_183499_1579597744.jpeg', '', 'She gives the book back to him.', '她把书还给了他。', '4a61dbc4d8e193aaf8071a82f329e480_34798_1579597741.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
