INSERT INTO `words` VALUES (345, 'handsome', '/ˈhænsəm/', 'handsome.mp3', 'adj.英俊的，帅气的；漂亮的，大方的', '2e7dd138f5e062cee82d12fa9be1a9fb_172338_1527653046.jpg', '20140927_08_57_06_834_v3.png', 'The handsome man posed for pictures.', '这位英俊的男子摆好姿势准备照相。', '8d6173f6045f60ff_1266763243430456276_250117.mp3', 'hand操作 + some一些 → 易于操作的，可用的 → handsome合适的，外形好的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
