INSERT INTO `words` VALUES (347, 'hardware', '/ˈhɑrdwer/', 'hardware.mp3', 'n.五金器具', '2845a410c2903f35aab67e2515ab4e8e_87125_1582791548.jpeg', 'd_106_4010_0_2_20150809065159.png', 'He bought a lot of hardware from that store.', '他从那家店买了很多五金器具。', 'vhvhcpul75phdu9c4ba4cwvmbk6juxw9.mp3', 'hard硬 + ware物件 → hardware五金器具', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (348, 'history', '/ˈhɪstri/ ', 'history.mp3', 'n.历史，历史学；历史记录', 'i_24_17960_0_5_151216131354-gigapixel-scale.jpg', 'd_70_12989_0_4_20150809010027.png', 'These books are about Chinese history.', '这些书是关于中国历史的。', '63fe6c44wmhlkag8pxpmayldgh99ru3n.mp3', 'histor过去发生的事 + y表名词 → history历史；个人经历', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (349, 'hold out', '/hoʊld aʊt/', 'hold out.mp3', 'phr.坚持，维持；伸出手（或胳膊）', 'c_i_19303_16_0_7_150812112103.jpg', '', 'He is much stronger than me', '他比我强壮多了，但我能够坚持和他对抗60秒！', 'sa_16_19303_0_8_151017113041.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (350, 'honest', '/ˈɑːnɪst/', 'honest.mp3', 'adj.诚实的，正直的', '3_0_20170721071235_20618_c-gigapixel-scale.jpg', 'd_66_13004_0_4_20150809021701.png', 'Wow', '“哇哦，这个皇帝没穿衣服！” 一个诚实的男孩大叫道。', 'us_Wow_the_20220424160559584_5f0db7d2df842ee81c23.mp3', 'hon=honor荣誉，尊严 + est → honest诚实的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (351, 'honesty', '/ˈɑːnəsti/', 'honesty.mp3', 'n.诚实', '562038fcf81182956c641e79af659933_74759_1595059487.jpg', '', 'The boy shows honesty by saying that he broke the vase.', '男孩说是他打碎了花瓶，体现了自己的诚实。', '42a47d2d50c5eed6_1266883377028749994_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (352, 'human', '/ˈhjuːmən/ ', 'human.mp3', 'adj.人的，人类的', 'c6ad91e29828a4429681e81686f24c6c.jpeg', 'd_24_18735_0_3_20150808235634.png', 'Water is important for the human body. ', '水对人体很重要。', 'ba6a88b40f38a539cb9e42d94b6a6b81_43918_1599535381.mp3', 'hum 土，地 + an名词后缀：属于...的 → 传说人是由土造出的 → human 人类', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (353, 'in debt', '/ɪn det/', 'in debt.mp3', 'phr.欠债', 'i_16_18652_0_2_20150809015743.jpg', '', 'Being heavily in debt', '由于负债累累，他感到压力山大。', 'sa_16_18652_0_5_160510101708.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (354, 'in no way', '/ɪn noʊ weɪ/', 'in no way.mp3', 'phr.绝不，无论怎样也不', 'acc6d12e7b9f4213ba347a8f2adf70a1.jpeg', '', 'The president insisted that in no way did he advocate war.', '总统坚称他绝不主张战争。', '64ac260eb568b5de0da620282911da96.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
