INSERT INTO `words` VALUES (356, 'in short', '/ɪn ʃɔːrt/', 'in short.mp3', 'phr.简言之', '611a6765bac9ac81f19aa66a6fe4e88a.jpeg', '', 'It\'s a long story', '这个故事说来话长，但简而言之就是他们争吵过后又和好了。', 'd88df5a3cd154bfbaba2d8859b625cd1.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (357, 'in tears', '/ɪn tɪəs/', 'in tears.mp3', 'phr.流泪', '16c4028db4bdf652e00a77a709135412.jpeg', '', 'The moving film left her in tears. ', '这部动人的电影让她流泪。', 'd4dfc90184d384314329a8b30d56f8a8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (358, 'independence', '/ˌɪndɪˈpendəns/', 'independence.mp3', 'n.（国家的）独立；（人的）自立', '3_0_20160520172124_86569_c-gigapixel-scale.jpg', 'd_105_11343_0_2_20150809061846.png', 'It is from Britain that America gained its independence.', '美国是从英国获得独立的。', '2a6bc112a52faeef1853da6c57363562_19167_1620267741.mp3', 'in不 + depend依靠 + ence名词后缀 → 不依靠 → independence独立，自主', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (359, 'indispensable for', '/ˌɪndɪˈspensəbl fɔːr/', 'indispensable for.mp3', 'phr.对……必不可少的', '65d138651bf8f820a19ff8d328cdd86d.jpg', '', 'Water is indispensable for the human body.', '水对人体来说是必不可少的。', '87174cbae41e41ffcdb78be40d4dd2ff_40352_1593586175.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (360, 'influence on', '/ˈɪnfluəns ɑn/', 'influence on.mp3', 'n.对...产生影响', '627379a30fb3e07bf9194f37f58d8e84.jpeg', '', 'A healthy family environment will have a positive influence on any child.', '健康的家庭环境会对孩子有积极的影响。', '7a8b64def99f2c703e13b3b532e76077.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (361, 'inquire of', '/ɪnˈkwaɪr ʌv/', 'inquire of.mp3', 'phr.探问', '8cf85f45acc90e1c224d9d3d014228e1_60991_1707023845.jpg', '', 'Inquire of him what happened.', '问他发生了什么。', 'us_Inquire_of_20240204131733565_f56ded12bf887183de44.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (362, 'insert', '/ɪnˈsɜrt/', 'insert.mp3', 'v.插入，嵌入（读作/ɪnˈsɜrt/）；  n.插入物', 'c18b0f958f72acb39b5e8690eb51feaf_86158_1577953836.jpeg', 'd_107_8970_0_2_20150809023916.png', 'I am inserting my USB flash drive into the laptop.', '我正在将我的U盘插入笔记本电脑中。', 'c93a0d12a92b17dbc45ab4f84a95e132_48190_1577953833.mp3', 'in进入 + sert加入，插入 → 加入进来 → insert插入', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (363, 'inside', '/ˌɪnˈsaɪd/', 'inside.mp3', 'prep.在……里面，在......之内；  n.里面，内部；  adv.在（或向）里面，在内部；  adj.里面的', '3_0_20170614071313_60928_c-gigapixel-scale.jpg', 'd_78_13106_0_4_20150808234918.png', 'Guess what? I\'ve got a rabbit inside the box!', '你知道吗？我的盒子里面有一只小兔子！', '648a8224ebbeb906_1266883527994420060_250207.mp3', 'in向内，进入 + side边 → inside内部，里面', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (364, 'interest', '/ˈɪntrəst/ ', 'interest.mp3', 'n.利益', 'f9fbaa88d4e1724bdabec2c710384d46.jpeg', 'd_24_15900_0_3_20150808230739.png', 'We have to balance our economic and environmental interests.', '我们必须兼顾经济利益和环境利益。', '58a78bd0deb7c4fbd81edb7d19773257_46606_1600425606.mp3', 'inter表示“在…之间，相互 + est表示最高级“最……” → 兴趣；利益；利息', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (365, 'interval', '/ˈɪntərvl/', 'interval.mp3', 'n.间隔', 'i_1_6362_0_2_20150808125051-gigapixel-scale.jpg', 'd_16_6362_0_2_20150808230637.png', 'This clock only shows fifteen-second intervals.', '这个表只能显示15秒的时间间隔。', '0e851cf19b398163_1266883482014013952_250207.mp3', 'inter在内，中间 + val墙 → 两堵墙之间的空间 → interval间隔，间歇', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (366, 'interview', '/ˈɪntərvjuː/', 'interview.mp3', 'n.面试；  v.面试', 'eebc4204cb2501a03f6d818d86b372b0_120556_1732848826.jpg', 'd_24_8405_0_3_20150808225651.png', 'During the job interview', '在求职面试过程中，这位男士似乎很紧张。', 'sa_1_8405_0_4_150923120339.aac', 'inter互相 + view看见 → interview会见', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (367, 'involve', '/ɪnˈvɑːlv/', 'involve.mp3', 'v.卷入，使参与；涉及', '3_0_20160528174758_88536_c-gigapixel-scale.jpg', 'd_107_4771_0_2_20150809010642.png', 'I involved myself in working with them.', '我加入他们一起工作。', '78f70593ee25d30b_1266883321891084918_250207.mp3', 'in向内，进入 + volve=volv旋转，卷 → 使……卷入进去 → involve使卷入，牵涉', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (368, 'keep off', '/kip ɑf/', 'keep off.mp3', 'phr.不接近', '674729e02973dcbae0c843aabde6d39d_197692_1582876133.jpeg', '', 'They built fences to keep children off the grass.', '他们筑起篱笆来防止孩子们践踏草坪。', 'fc29c34070abbdfa2bf50b2947b4b386_50512_1582876131.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (369, 'kind', '/kaɪnd/', 'kind.mp3', 'adj. 善良的，仁慈的，亲切的，和蔼的；  n.种类', 'c5d17f8211fd71bd05c55698ccce7354_145756_1733304572.jpg', 'd_24_17941_0_4_20150808233625.png', 'She\'s a kind young woman who always helps others.', '她是个善良的年轻人，总是帮助别人。', '5cbd1da5298ab810_1266763526113090194_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (370, 'kitchen', '/ˈkɪtʃən/', 'kitchen.mp3', 'n.厨房；炊具', 'c1f0c2973f280076cfbfa52d4d245c7a_161777_1574908862.jpeg', 'd_24_16624_0_3_20150808231659.png', 'The kitchen is clean and modern.', '这个厨房整洁而现代。', 'ee0fce091a578fe3_1266763310602824492_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (371, 'later', '/ˈleɪtər/', 'later.mp3', 'adv.过一会儿', '6ea18ca2de3a9e2c42ca1d9c5a9a0c8f_68956_1564823223.jpg', '20140822_16_09_36_508_v3.png', 'I\'m doing my homework now so I can play basketball later.', '我正在写作业，那我过一会儿就可以打篮球了。', '31dc5eb20c5565cbbbcc19f416622bf7_43936_1564823215.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (372, 'laugh', '/læf/', 'laugh.mp3', 'v.笑，发笑；  n.笑', 'c035e14518713199dfcb26ab0f29a75e_182126_1744941949.jpg', 'd_24_17288_0_4_20150808232619.png', 'The girls couldn\'t stop laughing at the funny joke.', '女孩听了那个笑话之后笑得停不下来。', '69b473f9e7909a76_1266763524157451110_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (373, 'lay down', '/leɪ daʊn/', 'lay down.mp3', 'phr.放下', 'a7e3fff8149bdaf891bc34b3157772b2.jpg', '', 'She laid the book down on the table and took a break from reading.', '她把书放在桌子上，休息了一会儿。', 'xetslnsb5tvw9k4ph2velm346kf99j88.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (374, 'learn of', '/lɜːrn ʌv/', 'learn of.mp3', 'phr.获悉', 'c16ad231f204495d671a183cea042a61.jpg', '', 'She went straight to the store when she learned of their sale.', '当她得知了打折的消息，就直接去了店里。', '305df8295a4cc74611858b02b2b25b54.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (375, 'let out', '/ˈletˌaʊt/', 'let out.mp3', 'phr.放出；泄露；发出', 'db97d83cb8c2fc4feaab5da37e63fc1c_83659_1580871418.jpg', '', 'She opened the door and let out the dogs.', '她打开了门，把狗放了出去。', '4f00b5fc7d9093a0_1266883320215481152_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (376, 'liberty', '/ˈlɪbərti/', 'liberty.mp3', 'n.自由', '709bdd7fcdb494f5c87b605507c37ede_89424_1535598966.jpeg', 'd_16_6672_0_7_20150808230935.png', 'The bird flew from the cage and got liberty.', '这只鸟飞出了鸟笼，得到了自由。', 'cb506814e68a5e9f_1266883636847750124_250207.mp3', 'liber自由的 + ty表名词 → liberty自由', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (377, 'lifestyle', '/ˈlaɪfstaɪl/', 'lifestyle.mp3', 'n.生活方式', '49a004b16840f3961356f0f09587943f_187896_1578559014.jpeg', '', 'There are many differences between a healthy lifestyle and an unhealthy lifestyle.', '健康的生活方式和不健康的生活方式之间存在很多不同。', '3693cc80303f10952d1f647711d1b4db_40174_1578559011.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (378, 'limit', '/ˈlɪmɪt/', 'limit.mp3', 'n.限制；  v.限制', '03de7646066e3ddaf727ecec84199e80_195287_1524537577.jpg', 'd_24_10970_0_4_20150808230500.png', 'The car should follow the speed limit.', '汽车应该按限速行驶。', '3_0_20170701114426_83561_c.aac', 'lim门槛，限制 + it名词后缀 → limit限制', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (379, 'log', '/lɔːɡ/', 'log.mp3', 'n.原木；航海日志；  v.记录', 'i_1_4780_0_4_150923102739-gigapixel-scale.jpg', 'd_15_4780_0_2_20150808161903.png', 'The logs are put on top of each other.', '这些原木被堆在一起。', 'sa_1_4780_0_4_151017113551.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (380, 'madam', '/ˈmædəm/', 'madam.mp3', 'n.夫人', 'e65d507de0ee307ae23a46956f3163d5_49009_1537465498.jpg', 'd_24_19743_0_4_20150809002833.png', 'The madam is smiling.', '这位女士在微笑。', '491ff8b1ac77caf5_1266883116029225942_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (381, 'mainly', '/ˈmeɪnli/', 'mainly.mp3', 'adv.主要地', '9dd46bd3aa8c6d47f6d30b19c36b4a46_200378_1587795998.jpeg', '', 'He spends his money on many things', '他把钱花在很多东西上，但主要是饮食方面。', 'us_He_spends_20240223140344487_154a3f28f9d7873ea851.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (382, 'marry', '/ˈmæri/', 'marry.mp3', 'v.结婚', '438b515eeefca54f9536f62e323347bd_81194_1564370445.jpg', '', 'They finally married. The story has a happy ending.', '最终，他们结婚了。结局皆大欢喜。', 'yf2btzbla5p9jxu3xmcszu6rsxtkqg49.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (383, 'miracle', '/ˈmɪrəkl/ ', 'miracle.mp3', 'n.奇迹', '97c0ff768109d7d5490a0b2a08352aa2_35099_1565603019.jpg', 'd_107_8231_0_2_20150809022941.png', 'This mystic light swirling over my hands is a miracle.', '这束在我手掌间萦绕的神秘光线是一个奇迹。', 'mmkuc9fl45sbwn3xf7t5laefkjdpgavz.mp3', 'mir惊奇 + acle物品，状态 → miracle奇迹', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (384, 'mix up', '/mɪks ʌp/', 'mix up.mp3', 'phr.混合，混淆', '797a8ce4a040b3189e4f7e65b80b99c2_67068.jpg', '', 'It must have been mixed up', '肯定是弄混了，因为我没有订这件衬衫。', 'b605565352ae4c7531a5fcf31045139c_27221_1621928253.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (385, 'mobile', '/ˈməʊbl/', 'mobile.mp3', 'adj.可移动的；多变的', 'i_1_7269_0_4_20150808125908-gigapixel-scale.jpg', '20140930_17_08_11_215_v3.png', 'The professor will show you how to use the mobile phone.', '这位教授会给你演示如何使用手机。', 'us_The_professor_20241009151345558_8d9be446120a328aba80.mp3', 'mob动 + ile能…的 → mobile活动的，可动的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (386, 'neither', '/ˈnaɪðər', 'neither.mp3', 'pron.两者都不；  conj.既不；  adj.两者都不的；  adv.既不……也不……', '338750d40465d80cff8c5c4c4b330164_93144_1574845352.jpeg', 'd_24_17910_0_4_20150808233431.png', 'He tasted both dishes and decided neither was delicious.', '他两盘菜都尝了尝，觉得两个都不好吃。', '7be769df1a4c482d_1266883328798993152_250207.mp3', 'ne不，没有 + ither两者中的一个 → neither两者都不', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (387, 'nephew', '/ˈnefjuː/', 'nephew.mp3', 'n.侄子，外甥', 'i_1_8512_0_2_20150808130833-gigapixel-scale.jpg', 'd_24_8512_0_3_20150808225757.png', 'I can\'t wait to meet my nephew!', '我等不及去见我外甥了。', '8fe82f46d5402b52_1266763241015368322_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (388, 'net', '/net/', 'net.mp3', 'n.网，网状物；  adj.纯利的，净值的，净的', '20120428_04_24_15_313-gigapixel-scale.jpg', 'd_24_5004_0_4_20150808223814.png', 'The football was kicked into the net.', '足球被踢进了网内。', 'm7hrbh8tgmugamtab5vulccvg6bb7xhc.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (389, 'northern', '/ˈnɔːrðərn/', 'northern.mp3', 'adj.北部的，北方的，有北方特征的', '5cd74d33c90a6e99c181ba6876eb1591_212847_1739000123.jpeg', 'd_24_19586_0_3_20150809002213.png', 'This kind of bear can be found in northern areas.', '这种熊通常出没在北方地区。', 'x3fjtystca9rc9fesph65y53jtf9ugzn.mp3', 'north北 + ern形容词后缀 → northern 北方的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (390, 'notebook', '/ˈnoʊtbʊk/', 'notebook.mp3', 'n.笔记本', '8adb81938dc1d130f49851c57e330636_125629_1575018937.jpeg', '20141015_14_22_18_328_v3.png', 'I like to use colorful stickers to mark the important pages in my notebook.', '我喜欢用彩色便利贴在笔记本的重要页面上做标记。', 'c711dd1f20be51b97c9475a3f2c01f34_46224_1575018935.mp3', 'note笔记 + book书 → notebook笔记本，期票簿', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (391, 'obstacle to', '/ˈɑːbstəkl tuː/', 'obstacle to.mp3', 'phr.对……的障碍', 'd4961d75b457c56a886b8eec76458580.jpg', '', 'There\'s a huge obstacle to his career.', '他的职业生涯面临巨大的障碍。', '07a0ab4f5eabd01fd7137228b8326bae_36896_1593586055.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (392, 'on the side', '/ɑːn ðə saɪd/', 'on the side.mp3', 'phr.作为兼职', '096928a3abd0d7ef1f437784fa3f5481.jpeg', '', 'His main job is a writer', '他的主业是作家，但也同时兼职摆地摊。', '5cf36983e0a4d3e55259e05ee1f35a85.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (393, 'outline', '/ˈaʊtlaɪn/', 'outline.mp3', 'n.外形，轮廓；概要；  v.描绘，画出……的轮廓', 'd4cd973218f494e3dfba4a810d4e9e74_148831_1534823492.jpeg', 'd_16_6321_0_2_20150808230543.png', 'The girl drew an outline of the model.', '这个女孩画出了模特的轮廓。', '308b36464a3ba14ff31d7eba9b1b7502_29041_1534823485.mp3', 'out外 + line线条 → outline轮廓', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (394, 'paint', '/peɪnt/', 'paint.mp3', 'v.给…刷涂料，给……刷油漆；  n.颜料', '46891bf0f62a14cb4979215724e39fc7_88055_1535964734.jpeg', 'd_24_16489_0_4_20150808231422.png', 'The woman is painting the wall blue.', '这个女人正在把墙刷成蓝色的。', '7nmqpzmyh2l3tazflqdjd7z7ghl5vn8x.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (395, 'piece', '/piːs/', 'piece.mp3', 'n.块，碎块；篇；  v.接合', '20c4e69912c0971519b28944578bc821_85230_1573628522.jpeg', 'd_24_16613_0_4_20150808231640.png', 'The yellow cup smashed into pieces.', '这个黄杯子碎成了很多块。', 'aab93c51e71dd533_1266763402427935514_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (396, 'poll', '/poʊl/', 'poll.mp3', 'n.投票站；民意测验；  v.获得（票数）', '33d62a700ef7c888e0486e7ce9c1ee7f_193489_1564370454.jpg', 'd_107_5111_0_2_20150809011552.png', 'The voters head to the polls to cast their votes.', '选民们前往投票站投票。', 'us_The_voters_20230712182136657_2734baa40068df8542f8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (397, 'pound', '/paʊnd/', 'pound.mp3', 'n. 英镑；  v.（连续）猛击，捣碎', '4afa0af4dbf3b3b179e7f4160b5a77de_180085_1656985852-800-600.jpeg', 'd_24_18000_0_3_20150808234053.png', 'Pound sterling is the national currency of the United Kingdom.', '英镑是英国的国家货币。', 'd783dd7e51ad2b15_1266797983716256574_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (398, 'praise', '/preɪz/', 'praise.mp3', 'v.称赞，表扬；赞扬，歌颂；  n.赞美的话', 'f0705041c2698730ae595b854974ead3_84055_1577955526.jpeg', 'd_24_17110_0_4_20150808232027.png', 'She was happy because her boss praised her.', '她很开心，因为她的老板表扬了她。', 'e7a158fa6aafd6a58b0d4d895aece1fc_34366_1577955523.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (399, 'pressure', '/ˈpreʃər/', 'pressure.mp3', 'n.压力；  v.对……施加压力', '3ad8f1b631cb4375e40aedb1453db76d_177782_1525685677.jpeg', '20130301_12_39_05_823.png', 'The pressure of the giant pear is unbearable.', '这个大梨的压力实在是难以承受。', '6e9488774fc5d088_1266883328379017982_250207.mp3', 'press挤压 + ure名词后缀，表行为、状态 → pressure压力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (400, 'prior to', '/ˈpraɪər tu/', 'prior to.mp3', 'phr.在……之前', 'c4213754017bc5bcb216a13449ac574a_204002_1545461587.jpeg', '', 'Prior to a date', '女生们一般都会在约会前花时间洗头发。', 'c0a22d61b355867ee5dc1b6375b9d104_21361_1545461668.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (401, 'pronounce', '/prəˈnaʊns/', 'pronounce.mp3', 'v.发音；发表，宣布', '1afc9b9e1ef4ff4a90a8cf666db4516a_66179_1558063302.jpg', 'd_24_18368_0_4_20150808235438.png', 'Open your mouth wide when you pronounce this sound.', '发这个音时，嘴巴要张大。', 'sa_24_18368_0_8_151128180415.aac', 'pro在前 + nounce讲话，说出 → 在嘴前讲话 → pronounce发音', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (402, 'protest against', '/ˈproʊtest əˈɡenst/', 'protest against.mp3', 'phr.对……提出抗议', '2484d65afbcd6fa342a5bf2de59b7f81.jpg', '', 'They are protesting against environmental damage.', '他们正在抗议对环境的破坏。', '55fba0bcac364636a88dddb520dbffb8_45392_1593575054.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (403, 'pull at', '/pʊl æt/', 'pull at.mp3', 'phr.拉扯', '78fc05c7a216eac7f51435d6ed3d903c.jpg', '', 'She\'s pulling at her face.', '她正在扯自己的脸。', '7a1a71d908a085153ef902ffc1f9e3f6_25760_1593575100.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (404, 'rapid', '/ˈræpɪd/', 'rapid.mp3', 'adj.迅速的；急促的', '23d382a78479850af87f1f0e19a0e10a_125810_1588233474.jpg', '20140929_02_49_56_880_v3.png', 'The train is traveling at a rapid pace.', '火车正在急速行驶。', '59ed4b3fd720e5d78a9f0aea4117ede9_26026_1530862691.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (405, 'receptionist', '/rɪˈsepʃənɪst/', 'receptionist.mp3', 'n.接待员', 'e797f55c543d7d2658254b92ebf222b7_95124_1579589660.jpeg', 'd_105_8632_0_2_20150809061046.png', 'As soon as I walked in', '我一走进去，宾馆接待员就满脸笑容地表示欢迎。', 'ddcc710b2b047ac519c165e92e1f92e9_77792_1579589664.mp3', 're重复、重新 ＋ cept拿，抓，握住 ＋ ion表名词 ＋ ist从事某种职业的人 → receptionist接待员；传达员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (406, 'refer to', '/rɪˈfɜr tu/', 'refer to.mp3', 'phr.参考；适用于', 'bbd59775dcc08221cbb33b730917537b_137869.jpg', '', 'If you don\'t know a certain word', '如果你有不认识的单词，你可以参考词典。', 'd4f5f32715f1c55054e088054f0fbdeb_38851.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (407, 'reference to', '/ˈrɛfərəns tu/', 'reference to.mp3', 'n.提到；参考', 'f46738e751ee1d4133fa1f65482a80b8.jpeg', '', 'In his paper', '他在论文中参考了该领域现有的研究成果。', 'a46c393b6f71ef501688bbb762c6d2d3_29042_1620814379.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (408, 'refine', '/rɪˈfaɪn/', 'refine.mp3', 'v.改进，改善', '1bb00ebcd4c4a528e0dfeb11a1e04dd9_192936_1584612501.jpeg', '20141015_14_22_25_332_v3.png', 'She refines the design of the car to make it travel faster.', '她改进了这辆车的设计，使它行驶得更快。', 'b5cad6bf6ee6522dfe189edc3dc64dd4_50144_1584612498.mp3', 're表强调 + fine使变好 → refine改进', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (409, 'relax', '/rɪˈlæks/', 'relax.mp3', 'v.放松，休息', 'i_1_8005_0_6_151027093552-gigapixel-scale.jpg', '4ea2994fd688f61f617e573220a788ba_42294_1551843509.png', 'Taking a bath is a good way to relax.', '泡澡是一种很好的放松方式。', 'us_Taking_a_20241009153805572_96a5e659e303c6cf4e8b.mp3', 're重新 + lax松 → 重新松开 → relax放松，宽心', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (410, 'relief', '/rɪˈliːf/', 'relief.mp3', 'n.安慰；缓解；减轻；浮雕', 'a5dc82cf7954ddc7734f59886727364a_202006_1574480900.jpeg', 'd_24_5560_0_3_20150808224141.png', 'To the relief of the patient', '令这位病人感到安慰的是，医生告诉他一切都正常。', '22ggynhpg6snwd7a7j9zyd65f2c9bjka.mp3', 're再 + lief提高，变轻 → relief减轻，轻松', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (411, 'remain', '/rɪˈmeɪn/', 'remain.mp3', 'v.剩余；逗留；  link-v.保持；  n.剩余物（复数）；遗迹；残骸', 'ac42af19887c17a43745f17aee2b0ddf_195843_1532940008.jpeg', 'd_24_4975_0_4_20150808223747.png', 'Only one puppy remained in the cage as the others were sold.', '笼子里只剩下一只小狗，其他的都售出了。', 'fa48ce1e84000d4bdff155ed33fe431e_21675_1645685723.mp3', 're回 + main逗留 → 回来留下 → remain剩余', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (412, 'remember to do', '/rɪˈmɛmbɚ tu du/', 'remember to do.mp3', 'phr.记得要做某事', '7b213efd8f288466d004beb791bab9e1.jpg', '', 'Oh! I just remembered to do my homework.', '喔！我才记起来我要去做作业。', 'us_Oh_I_20241009155448989_65c6a48476380b9ed72c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (413, 'reputation for', '/ˌrepjuˈteɪʃn fɔːr/', 'reputation for.mp3', 'phr.以……闻名', 'i_1_4638_0_3_20150808122921.jpg', '', 'He has a good reputation for his athletic skills. ', '他以其体育特长而闻名。', 'us_He_has_20220609094408461_38f257f8ceb7ff86dba8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (414, 'research', ' /rɪˈsɜːtʃ/ /ˈriːsɜːrtʃ/', 'research.mp3', 'n.研究，调查；  v.研究，调查', '53d9dad40826125cd47911ff6324ae32_201564_1574825944.jpeg', '20130201_16_23_36_209.png', 'She\'s conducting some research in order to write her new book.', '为了撰写她的新书，她正在进行一些研究。', 'us_Shes_conducting_20241009155029451_4848ebe7379501ee0d49.mp3', 're表强调 + search寻找 → research研究', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (415, 'reset', '/ˌriːˈset/', 'reset.mp3', 'v.重新设定', 'a6d57fdc8f65ba7eded58e1f0e5b238e.jpg', '', 'He reset his computer after it crashed.', '电脑死机后，他重启了电脑。', '8f4ea389992a6138a9809d4a8dafbe5d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (416, 'respond', '/rɪˈspɑːnd/', 'respond.mp3', 'v.做出反应；对……有效果；回答，回复', '3_0_20160724071039_63160_c-gigapixel-scale.jpg', 'd_16_5150_0_4_20150808225045.png', 'Oh yes! I responded when the cute girl asked if I wanted a candy.', '当那个可爱的小女孩问我想不想要一颗糖的时候，我回答：“要！”', '3_0_20160724071039_37537_c.aac', 're回 + spond承诺 → 承诺回去 → 回答 → respond回答；反应', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (417, 'rest on', '/rest ɑːn/', 'rest on.mp3', 'phr.取决于，基于', '70042ec56d14d2c64dcc97f4e1832739.jpeg', '', 'Whether they go for a picnic or not rests on the weather. ', '他们是否去野餐取决于天气。', 'dece017dc325308bd1340ad8aae168a7_37184_1599550656.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (418, 'scheme', '/skiːm/', 'scheme.mp3', 'n.方案，计划；阴谋，诡计；  v.图谋，密谋', '3_66_20170718105116_33521_c-gigapixel-scale.jpg', 'd_1_5425_0_3_20150808123830.png', 'Our scheme for the next game is a 4-4-2 formation.', '我们队下一场比赛的方案是使用442阵型。', 'd2f900c3d956509f_1266883326989609948_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (419, 'see off', '/siː ɔːf/', 'see off.mp3', 'phr.为……送行，送别', 'e9aa67c63274dcd1266805ca7db73223.jpeg', '', 'She saw her family off from the window.', '她在窗边送别家人。', '3c51387a72104d6e0a23d5afa508a81e_26384_1599552991.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (420, 'selection', '/sɪˈlɛkʃən/', 'selection.mp3', 'n.可供挑选的商品', 'a9b72e3d387820bbe4fd31a955a01cf3_86379_1565603569.jpg', '20141009_02_38_42_345_v3.png', 'Our nursery offers a selection of spring flowers of many different colors.', '我们的苗圃里有各种颜色的春季花卉可供挑选。', '3bdae8d9be1ab741f7840db61d219fdc_47494_1604977596.mp3', 'se分开 + lect选择，收集 → select分开选=选择 + ion表名词 → 选择', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (421, 'shallow', '/ˈʃæloʊ/', 'shallow.mp3', 'adj.浅的；肤浅的；  v.变浅；使变浅', 'd955d810d08e995aabbc6772118aa8b4_202899_1571024487.jpeg', 'd_107_5976_0_2_20150809014709.png', 'The boy is swimming in the shallow pool.', '这个男孩在浅水池里游泳。', 'smwuff4hyr4ezg3wnp3vb235yulpxdnu.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (422, 'sharp', '/ʃɑrp/', 'sharp.mp3', 'adj.锋利的，尖锐的；  adv.锐利地', '79be0abe8e1189e74c82766d73e99f32_190454_1565685636.jpeg', 'd_99_8397_0_3_20150809021805.png', 'This knife is so sharp that it can easily slice the apple.', '这把刀好锋利啊，切苹果超级容易。', '0cf053ac6cd8a9b0_1266798140402346920_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (423, 'shortcoming', '/ˈʃɔːrtkʌmɪŋ/', 'shortcoming.mp3', 'n.短处，缺点', '3_0_20160718113324_76247_c-gigapixel-scale.jpg', 'd_105_6857_0_2_20150809060107.png', 'A shortcoming of this kind of dog is that their legs are too short.', '这种狗的缺点是它们的腿太短了。', '3_0_20160718113324_49382_c.aac', 'short短的 + coming来到 → shortcoming短处，缺点', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (424, 'shot', '/ʃɑːt/', 'shot.mp3', 'n.击球，投球；（电影中的）镜头；  adj.杂色的；  v.射击', '377aedacaf01a10e1d8436f09d805476_312508_1683704750.jpg', 'ee053121bda83056abd344116c3c4c41_47058_1539341223.png', 'Nice shot! I said as she hit the ball.', '好球！她击球时我说。', 'us_Nice_shot_20230505100153539_e393800a4ab5606875c3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (425, 'show up', '/ʃoʊ ʌp/', 'show up.mp3', 'phr.露面，出现', 'bbb9e8af1c5f40cd17575513d586f5cb.jpeg', '', 'When the singer\'s fiancee showed up on the stage', '当这名歌手的未婚妻出现在舞台上时，观众感到很惊讶。', '9mh9jud8ds4fv9xmau5eff9z3qvkb5sf.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (426, 'side', '/saɪd/', 'side.mp3', 'n.边；一边，一侧；  adj.旁边的，侧面的；  v.站在同一边', '3_0_20160520172834_78831_c-gigapixel-scale.jpg', 'd_24_17166_0_4_20150808232226.png', 'There are many trees on both sides of the river.', '小河两边的岸上有许多树。', '3_0_20160520172834_69785_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (427, 'sink', '/sɪŋk/', 'sink.mp3', 'n.水槽，洗碗池；  v.（使）下沉，（使）降低，（使）沉没', 'eb527a1a6f4daec9280217460a930baf_80071_1565281296.jpg', '20141013_23_42_45_35_v3.png', 'I am washing the dishes in the sink.', '我正在洗水槽里的餐具。', '6ck7fy8vucvytpzg2jrq799b76p2zmdc.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (428, 'smart', '/smɑːrt/', 'smart.mp3', 'adj.聪明的，机灵的；时髦的，衣着讲究的；  v.难过，烦恼', '1a6f3fd0b8d2c97ce5ad24e74e85ed54_100816_1588132185.jpeg', 'd_24_10160_0_3_20150808230353.png', 'The girl is so smart that she can solve very difficult physics problems.', '这个女孩很聪明，她能解很难的物理题。', 'us_The_girl_20240729103905028_41bfcfde07071cc9f73b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (429, 'somewhat', '/ˈsʌmwʌt/', 'somewhat.mp3', 'adv.有点儿，稍微；  pron.某物；一些', '5b38f47b78fb402657445c0973e6fc87_145290_1558596045.jpeg', 'd_1_15991_0_3_20150808132043.png', 'The old-style restaurant is somewhat pricier than the street ones.', '这家老字号饭店的价格比街边饭店的稍贵。', '5e79a3234dac9b64_1266883539359259374_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (430, 'sound', '/saʊnd/', 'sound.mp3', 'n.声音，声响；  v.听起来；  adj.正当的，有根据的', 'e925e1a2f88b383f468cd2fb919b9713_80112_1577956752.jpeg', 'd_24_17982_0_3_20150808233926.png', 'The sound coming from the speakers was very loud.', '喇叭里传出来的声音很大。', '1ad5ba9d783c5d90_1266883009151085482_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (431, 'stage', '/steɪdʒ/', 'stage.mp3', 'n.舞台；阶段', 'i_1_17971_0_4_151019102632-gigapixel-scale.jpg', 'd_16_17971_0_4_20150809013617.png', 'The students are playing music on the stage.', '学生们正在舞台上演奏音乐。', 'us_The_students_20250807163247848_dfac89a872d6bab2042d.mp3', 'sta表示“站，立” + ge表名词 → stage舞台；戏剧；阶段', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (432, 'standard', '/ˈstændərd/', 'standard.mp3', 'n.标准，规格；  adj.标准的', '3f8201f3c298694686faf06a943c9a1d_64104_1629109992.jpg', 'd_94_14336_0_4_20150809010345.png', 'Passport photos have strict standards.', '护照照片有着严格的标准。', 'a95df7641da5edab_1266883371679701684_250207.mp3', 'stand站立 + ard=hard坚硬的 → standard标准', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (433, 'stipulate', '/ˈstɪpjuleɪt/', 'stipulate.mp3', 'v.规定，明确要求；要求以……为条件', 'abe943a6a5912fbb423cbe9f4146211a_35564_1695188878.jpg', '', 'The traffic laws stipulate what everyone should do.', '交通法规规定了每个人应该做的事。', 'us_The_traffic_20230920134641217_b67fa0d072cd22e67b59.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (434, 'strategy', '/ˈstrætədʒi/', 'strategy.mp3', 'n.策略，计谋', 'fb3cb2510ae517e1727231f8a809c36f_77730_1569030559.jpg', 'd_1_9135_0_3_20150808131231.png', 'I like strategy games that require deep thinking', '我喜欢需要深思熟虑的策略性游戏，比如国际象棋。', 'sa_5_9135_0_3_20150808145054.aac', 'strat军队 + egy名词后缀 → 军队需要战略 → strategy战略；策略', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (435, 'structure', '/ˈstrʌktʃər/', 'structure.mp3', 'n.建筑物；结构；  v.精心组织', 'a3b928268b11219fe3dc104b07fef4a8_78833_1565343271.jpg', 'd_107_8099_0_2_20150809022809.png', 'There are so many new structures going up.', '许多新的建筑正在兴建。', 'sa_1_8099_0_2_20150808130419.aac', 'struct建立 + ure表名词 → structure构造；结构', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (436, 'suburb', '/ˈsʌbɜːrb/', 'suburb.mp3', 'n.郊区', 'i_1_6794_0_5_150925182448-gigapixel-scale.jpg', 'd_105_6794_0_2_20150809060028.png', 'In the suburbs', '郊区房子少，但是树多。', '863pdfwy4pgywfhau8srcl8evvprbfvz.mp3', 'sub在下面，次一等 + urb城市 → suburb郊区，郊外', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (437, 'sugar', '/ˈʃʊɡər/', 'sugar.mp3', 'n.糖；食用糖；  v.糖化；  v.加糖于', '40c1ed043e0308c3e12e34761b84955a_38840_1734930281.jpg', 'd_24_16001_0_4_20150808231018.png', 'I\'d like a spoonful of sugar in my coffee.', '我想在我的咖啡里放一勺糖。', 'us_Id_like_20241223130427101_292d806f21657d1c5c7d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (438, 'surface', '/ˈsɜːrfɪs/', 'surface.mp3', 'n.表面，表层；外表，外观；  v.浮出水面', '5ae51cc932d2500291c3ea1ddc9b499d_90192_1573712330.jpeg', 'd_24_9123_0_4_20150808230034.png', 'There is some oil on the surface of the soup.', '汤的表面有一些油。', 'qfpn5qzrfecya8lulm4qvwfnpc55wsv2.mp3', 'sur超过，在上面 + face脸面 → surface表面', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (439, 'surprise', '/sərˈpraɪz/ ', 'surprise.mp3', 'n.惊喜，意想不到（或突然）的事；惊奇，诧异；  v.出其不意地袭击；使惊奇，使诧异，使感到意外', '48ae19136a29901e9213a0c046242ea0_83819_1535523976.jpeg', 'd_69_8396_0_3_20150809002838.png', 'She had a look of surprise after she opened the gift.', '拆开礼物后，她露出了惊喜的表情。', '5ad76ec6000ea96a0920cbbb5b18ca59_23957_1621924636.mp3', 'sur突然 + prise拿住，抓住 → 突然被抓住 → surprise吃惊', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (440, 'suspicious', '/səˈspɪʃəs/', 'suspicious.mp3', 'adj.可疑的', '785f5301def90e26793432df5da0f4a0_111673_1731655810.jpg', 'd_1_7859_0_2_20150808130101.png', 'The policeman found the man\'s behavior suspicious.', '警察发现这个人的行为很可疑。', '01d5bab872d01a5c_1266883628658088560_250207.mp3', 'suspici怀疑 + ous形容词后缀 → suspicious猜疑的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (441, 'tablet', '/ˈtæblət/', 'tablet.mp3', 'n.碑，匾；药片', 'c8e9931bc36e09a39a1b3226b9b261d6_73961_1567072403.jpg', 'd_16_4748_0_2_20150808224400.png', 'This ancient tablet is from Roman times.', '这块古老的石碑源自罗马时代。', 'aep4nfachvdls2swwf3rd7amvbapsktd.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (442, 'take up', '/teɪk ʌp/', 'take up.mp3', 'phr.占据；占用；拿起；开始做；继续', '5ed927d2fd59c726b59906b569ae9361_103426_1534228233.jpeg', '', 'This car takes up two parking spaces.', '这辆车占了两个停车位。', '63d9402a05a17f20_1266883633893583796_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (443, 'television', '/ˈtelɪvɪʒn/', 'television.mp3', 'n.电视（机）', '5042c9cd77264031d68b462fd00e4d2e_115702.jpg', '20121225_20_20_19_344.png', 'We can watch the games on television.', '我们可以通过电视看球赛。', 'd4c8a16769bc60a7_1266763555333888512_250117.mp3', 'tele电 + vis看 + ion表名词 → television电视（机）', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (444, 'ticket', '/ˈtɪkɪt/', 'ticket.mp3', 'n.票，券', '8c7915dbfdca4439197232fdd69e9466_92635_1758533128.jpg', 'd_24_18149_0_4_20150808235023.png', 'They got two tickets to fly back.', '他们有两张返程的机票。', 'us_They_got_20250922172502275_597d04f2a685b80c825a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (445, 'topic', '/ˈtɑːpɪk/', 'topic.mp3', 'n.话题，主题', '3_0_20160520172938_74611_c-gigapixel-scale.jpg', 'd_105_7498_0_2_20150809060403.png', 'He wrote down a topic for us to discuss.', '他写下一个主题供我们讨论。', 'hgpe2g7zqzfhxv3cmaw23sfqevktmu6g.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (446, 'tourist', '/ˈtʊrɪst/ ', 'tourist.mp3', 'n.游客', '403a1af43af164fd747dee5475bdf156_121524_1578638050.jpg', 'd_24_16412_0_3_20150808231146.png', 'The tourists enjoyed traveling to new places.', '这些旅行者喜欢去新地方旅行。', 'pgzl5ewrjekeqr5sbn6z3f4ph5rglera.mp3', 'tour旋转；迂回 ＋ ist表示人 → tourist旅游者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (447, 'transform', '/trænsˈfɔːrm/ ', 'transform.mp3', 'v.改变，转换', '5b2b14df0120e6775598c340906c9fba_364786_1709887475.jpg', 'd_16_6349_0_5_20150808230627.png', 'Makeup transformed him into a strikingly handsome man.', '这个男人化妆爆改后变得很帅。', 'us_Makeup_transformed_20240308164511225_646f518d7d9ca86f2233.mp3', 'trans变换，转移 + form形状 → 改变形状 → transform变形', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (448, 'treaty', '/ˈtriːti/', 'treaty.mp3', 'n.条约；协议；协定', '567c7c5447c6dfdcaccaa7bda772ab72_52628_1729823301.jpg', 'd_1_5065_0_3_20150808123423.png', 'The two nations declared a ceasefire and penned a peace treaty.', '两个国家停战并签订了和平条约。', 'us_The_two_20240603155919844_953eb98aeb011da79963.mp3', 'treat处理 + y表名词 → 作出处理的文件 → treaty条约；约定', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (449, 'twin', '/twɪn/ ', 'twin.mp3', 'adj.孪生的；  n.孪生儿', '200fdd7c72b02124d53f115809c23143_437790_1611310186.jpg', '20121225_18_38_33_626.png', 'The twin baby brothers look exactly like each other.', '这对双胞胎兄弟看上去完全一模一样。', 'gks83y2bn7b32ffd5u3ylfugbbwxvgnl.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (450, 'unwilling', '/ʌnˈwɪlɪŋ/', 'unwilling.mp3', 'adj.不愿意的，不情愿的，勉强的', 'i_13_2581_0_5_160328100007-gigapixel-scale.jpg', 'd_105_2581_0_2_20150809053357.png', 'The dog is unwilling to follow its master.', '这只狗不愿意跟着它的主人走。', 'sa_13_2581_0_5_160325142049.aac', 'un不 + will愿意 + ing...的 → unwilling不愿意的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (451, 'upset', '/ˈʌpset', 'upset.mp3', 'adj.苦恼的，沮丧的，心烦的；  v.使苦恼', '265c89eedbc636606f8ddf2746b33209_141388_1538644921.jpg', 'd_16_7995_0_4_20150808232337.png', 'The little boy is upset about his test.', '这个小男孩正为考试苦恼。', '57b06a2689f65130_1266883374068181776_250207.mp3', 'up向上 + set安置好 → 把底向上放 → upset打翻', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
