INSERT INTO `words` VALUES (453, 'vary', '/ˈveri/', 'vary.mp3', 'v.相异；（根据情况）变化；使多样化', '064a7903a0cfbe8c99c1a7ea63bfad00_102844_1656491236.jpg', 'd_1_9133_0_2_20150808131229.png', 'Each cup on the table varies in color and size.', '桌上的每个杯子颜色和大小各不相同。', '65cb0f60613f80c4_1266883374341118502_250207.mp3', 'vary=vari变化 → vary改变，变化', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
