INSERT INTO `words` VALUES (455, 'vision', '/ˈvɪʒn/', 'vision.mp3', 'n.视力；视野；视觉', 'i_1_8415_0_3_20150808130728-gigapixel-scale.jpg', 'd_1_8415_0_3_20150808130728.png', 'The eye doctor said that my vision is excellent.', '眼科医生说我的视力非常好。', 'sa_1_8415_0_3_20150808130728.aac', 'vis看 + ion表名词 → vision视力，眼界', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (456, 'west', '/west/', 'west.mp3', 'n.西，西方，西部；  adj.西的，西方的；  adv.向西方', 'f1e12925fa4f0a20d4b8cac6798b42aa_76868_1541846404.jpg', 'd_24_17627_0_3_20150808233052.png', 'On the compass', '在指南针上，“W”代表西方。', 'r7r98gjjkdplea2a7umgebeej2akpwvh.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (457, 'wild', '/waɪld/', 'wild.mp3', 'adj.自然生长的，野生的；野性的；狂热的；荒芜的；疯狂的', 'c1ce40eb38cffd42f2cf24a77afc5ac1_193116_1532932136.jpeg', 'd_33_7914_0_4_20150809000600.png', 'The wild kid is making a big mess in the dining room.', '这个熊孩子把餐厅搞得一团糟。', 'fa92f30508856b3a_1266797981878561538_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
