INSERT INTO `words` VALUES (459, 'wisdom', '/ˈwɪzdəm/', 'wisdom.mp3', 'n.智慧，学问', 'dec5bc83fd01f157acf0876b128bd862_46649_1617960745.jpg', 'd_107_4451_0_2_20150809005646.png', 'The old man\'s wisdom comes from books.', '这位老人的智慧来自于博览群书。', '5d1f86160c01c1f3b09e21d754aec8fc_15562_1617960676.mp3', 'wis=wise智慧的 + dom状态或领域 → wisdom智慧', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (460, 'worth', '/wɜːrθ/', 'worth.mp3', 'adj.值……钱；  n.价值', 'i_1_6952_0_2_20150808125646-gigapixel-scale.jpg', 'd_24_6952_0_3_20150808224848.png', 'My house is worth two hundred thousand dollars.', '我的房子值二十万美元。', 'sa_1_6952_0_2_20150808125646.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
