INSERT INTO `words` VALUES (462, 'yard', '/jɑːrd/', 'yard.mp3', 'n.院子，庭院', '3_0_20170701114358_83664_c-gigapixel-scale.jpg', 'd_24_15885_0_4_20150808230723.png', 'What a large yard! We can have a barbecue.', '这个院子真大！我们可以烤烧烤。', 'a16c754646b3acdc_1266883374783027774_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
