INSERT INTO `words` VALUES (465, 'adjust to', '/əˈdʒʌst tu:/', 'adjust to.mp3', 'phr.适应', 'i_904_-904_0_1_160202150130.jpg', '', 'A week later', '一星期后，这个学生适应了新学校的生活。', 'sa_904_-904_0_1_160203154924.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (466, 'admire', '/ədˈmaɪər/', 'admire.mp3', 'v.钦佩，崇拜', '53de4ce43154cd977461525d19dbd7fd_109672_1745468659.jpg', '', 'The little boy admires the firemen and salutes them.', '小男孩很钦佩消防员并向他们敬礼。', 'qrfjgercm7fhrq4xs9trznspechl543k.mp3', 'ad关于 + mire感到惊讶 → admire钦佩', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (467, 'all the same', '/ɔːl ðə seɪm/', 'all the same.mp3', 'phr.仍然', 'af732ec8ce4f8c396f60b1ae35b8044f.jpeg', '', 'The air conditioner was on', '空调开了，但他仍然浑身冒汗。', 'nnxcwyrg84gxc5lv6wz8z93nwqauzwug.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
