INSERT INTO `words` VALUES (469, 'analyze', '/ˈænəlaɪz/', 'analyze.mp3', 'v.分析；细察', '3_0_20160718115303_50868_c-gigapixel-scale.jpg', 'd_16_10583_0_2_20150808235549.png', 'He is analyzing the company\'s monthly finances.', '他正在分析公司的月度财务情况。', '0ee13e2db06c902b191de19d8b28aa04_49952_1596784796.mp3', 'ana完全 + lyze解开 → 完全解开 → analyze分析', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (470, 'answer to', '/ˈænsər tuː/', 'answer to.mp3', 'phr.……的答案', '337cf7e46d10a98c43cfbde7ab7c092a_109751_1594692421.jpg', '', 'He quickly worked out the answer to the math problem.', '他很快算出了这道数学题的答案。', 'c52b8254c4cb61a2f0fdc43ff08880dc.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (471, 'apart from', '/əˈpɑːrt frəm/', 'apart from.mp3', 'phr.除……之外（还）', '8602b7b4573d7b568e64df3f569d619d_87862_1579340812.jpeg', '', 'This room is empty', '除了两盆绿植之外，这个房间里什么都没有。', '73f143e90ff33868_1266883379211950612_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (472, 'apologize', '/əˈpɑːlədʒaɪz/', 'apologize.mp3', 'v.认错', '039c2efa70b389d5e70cd27220c86622_150162_1549955104.jpeg', 'd_24_9537_0_4_20150808230242.png', 'The cat apologized to its owner for breaking the vase.', '这只猫为打碎花瓶而向主人道歉。', '918c63e191ada3b2201fd9c1fbf5938e_39722_1558318327.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (473, 'appetite', '/ˈæpɪtaɪt/', 'appetite.mp3', 'n.食欲', '3f58f7f5a69e25c62cd928c6e048f973_134792_1711695218.jpg', 'd_16_6368_0_2_20150808230638.png', 'His appetite was greatly stimulated by these spicy chicken feet.', '这些辣鸡爪让他食欲大开。', 'f61c299c74257f64_1266883619395054542_250207.mp3', 'ap加强动作 + pet追寻，寻求 + ite表名词 → 一再追求 → appetite胃口，欲望', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (474, 'applicant', '/ˈæplɪkənt/', 'applicant.mp3', 'n.申请人；请求者', '9be714636983d56e784f2b3c717ca944_473533_1701668162.jpg', '20141010_22_52_26_160_v3.png', 'The applicants are waiting outside before the interview.', '面试之前，申请人在外面等候。', '95ed5e1d2a04eeba_1266883010261330900_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (475, 'athlete', '/ˈæθliːt/', 'athlete.mp3', 'n.运动员，田径运动员', 'ca898361a7e6a78b50076d1c79801087_112814_1722407744.jpg', '20141010_01_11_04_763_v3.png', 'He was a great athlete who ran really fast.', '他以前是一名优秀的运动员，跑得非常快。', 'bebc460ff971b4c0_1266763558354201430_250117.mp3', 'athl比赛 + ete → 参加体育比赛的专业人士 → athlete运动员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (476, 'atomic', '/əˈtɑːmɪk/', 'atomic.mp3', 'adj.原子能的', 'i_1_6742_0_4_151022175820-gigapixel-scale.jpg', 'd_108_6742_0_2_20150809042914.png', 'A mushroom cloud formed after the atomic bomb went off.', '原子弹爆炸后，天空中出现了蘑菇云。', 'sa_1_6742_0_4_151029150948.aac', 'atom原子 + ic……的 → 原子的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (477, 'audience', '/ˈɔːdiəns/ ', 'audience.mp3', 'n.观众，听众', '0468e334c7a057b68693543efbce4422_127735_1544066656.jpeg', '', 'The audience in the conference hall stayed quiet during his speech.', '他讲话时，会议厅里的听众都很安静。', 'fc0793c350aeb07d_1266883485621791564_250207.mp3', 'audi听 + ence表名词 → 听众，观众，读者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (478, 'beginning', '/bɪˈɡɪnɪŋ/', 'beginning.mp3', 'n.开始，开端', 'd47f6c780e50a5639acdf46523539339_147185_1738912249.jpeg', 'd_16_15731_0_2_20150809000622.png', 'I won the race! I was ahead from the beginning.', '我赢得了跑步比赛！我从一开始就遥遥领先。', '51ebd9f7ddfa0bc5_1266798140692322990_250123.mp3', 'begin开始 + n + ing名词后缀 → beginning 开始', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (479, 'behavior', '/bɪˈheɪvjə(r)/ ', 'behavior.mp3', 'n.举止；行为（=behaviour）；态度', '14cd9e5ca51a20e2898e7eb050b3cfec_93000_1585124131.jpeg', 'd_24_9892_0_4_20150808230321.png', 'People\'s behavior often reflects their personal qualities.', '人们的举止通常可以体现出他们的个人素质。', '8fd5e0d479a415592f0635017e9fe091_21832_1597400313.mp3', 'be表示动作 + hav持有 + ior表名词 → 人持有的动作 → behavior举止行为', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (480, 'believe', '/bɪˈliːv/', 'believe.mp3', 'v.相信；认为', 'dd424146cd9428df7a477da23a49d426_203416_1549941554.jpeg', '5890b0a5b56848f0124e585bf245772b_21788_1539341544.png', 'Some people believe that being a social media retailer is a good way to make a fortune.', '有些人相信做微商是个发财致富的好方法。', 'mf5clch79kfzwjqzwy6vmnv8vtgtqvtx.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (481, 'bookshop', '/ˈbʊkʃɑːp/', 'bookshop.mp3', 'n.书店', 'fcfcd169e270c9f0d19f615310a898f9_200283_1574925911.jpeg', 'd_109_18204_0_2_20150809063053.png', 'He went to the bookshop to buy some books.', '他去书店买了一些书。', '785b51aa6bd9d983_1266763552822221506_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (482, 'brand', '/brænd/', 'brand.mp3', 'n.品牌；  v.加污名于', '753a24e8099287690ab04320f98d23ea_77367_1758532956.jpg', 'd_107_7275_0_2_20150809021756.png', 'The woman knows so many girls\' beauty brands.', '这个女人知道好多女孩子用的美妆品牌。', 'us_The_woman_20250922172228497_2da66cba40cf74f60186.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (483, 'break in on', '/breɪk ɪn ɑːn/', 'break in on.mp3', 'phr.打断', '3e5671d278cebf5421101c2f5887fc15.jpeg', '', 'It\'s impolite to break in on other people\'s conversations.', '打断他人的谈话是不礼貌的。', '203caa84ed1a320286038fdd28efa26f_44926_1599622405.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (484, 'by no means', '/baɪ noʊ miːnz/', 'by no means.mp3', 'phr.决不', '5598e8a2d272e7c30d18e79c7267d58f.jpg', '', 'Although he can sing very loud', '尽管他能唱得很大声，但他决不是一个好歌手。', '6665ee652412e202c94e6e1c107ac1a1.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (485, 'call forth', '/kɔːl fɔːrθ/', 'call forth.mp3', 'phr.唤起', '4dd4234aa46c8d035ed9d586916d1a77.jpg', '', 'The sale at the mall called forth customers\' urge to shop.', '商场的大减价唤起了顾客们强烈的购物欲。', 'd223382f40c584677247d1b0f26f390f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (486, 'cattle', '/ˈkætl/', 'cattle.mp3', 'n.（总称）牛，牲口', 'i_16_6168_0_4_151118144947-gigapixel-scale.jpg', 'd_24_6168_0_4_20150808224501.png', 'The cattle are eating grass on the grassland.', '牛正在草地上吃草。', 'sa_16_6168_0_4_151223155207.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (487, 'cave', '/keɪv/', 'cave.mp3', 'n.山洞，洞穴；  v.塌落', 'i_1_8126_0_8_160321115325-gigapixel-scale.jpg', 'd_16_8126_0_3_20150808232649.png', 'He went into the dark cave by himself.', '他独自一人走进了漆黑的山洞。', '1fa4f67e90911dcd_1266883527439112806_250207.mp3', 'cav洞 + e → cave山洞', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (488, 'chair', '/tʃer/', 'chair.mp3', 'n.椅子；主席（职位）', '3_0_20170928071438_9093_c-gigapixel-scale.jpg', 'd_24_19482_0_3_20150809001524.png', 'Sitting in the dentist\'s chair always fills me with fear.', '坐在牙医的椅子上总是让我充满了恐惧。', '1fe98d44afb648fa_1266763314956708796_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (489, 'chairman', '/ˈtʃermən/', 'chairman.mp3', 'n.主席，董事长', 'fc569b14cc017d6ea823026f32e0ae82_86106_1541845334.jpg', 'd_24_17358_0_4_20150808232740.png', 'The man standing in the middle is the chairman of the board.', '站在中间的那个人是董事会主席。', '9c960ca6bdbb19845a47bdec9e041aae_15091_1541845477.mp3', 'chair主席位 + man人 → chairman主席；议长', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (490, 'chief', '/tʃiːf/', 'chief.mp3', 'n.负责人，老板；首领，酋长；长官；  adj.首席的，最高级别的', 'e6fed9647e945ad1e66ae2e6f208ade1_59373_1656661676.jpg', 'd_24_3863_0_3_20150808223347.png', 'This man is the chief of the restaurant.', '这个男人是餐厅的负责人。', 'us_This_man_20220701154757411_d681c7a111670cbfe4a8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (491, 'chocolate', '/ˈtʃɑːk.lət/', 'chocolate.mp3', 'n.巧克力', '3979fbf369ba9ad6bf8e0094cb82a30f_137642_1523628968.jpg', '20141015_14_21_14_518_v3.png', 'Yum-yum! This chocolate tastes really good!', '好吃！这巧克力真好吃！', 'xc6nydcym7ktkhtyxsagr4m34w9wu8gx.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (492, 'clarify', '/ˈklærəfaɪ/', 'clarify.mp3', 'v.阐明，澄清', '7788840be25808b98fa68f3da8cb59a5_79397_1579594758.jpeg', '20121225_20_11_12_975.png', 'During class the student clarified his ideas about the book.', '在课堂上，这个学生阐明了自己关于这本书的看法。', '9948183b9879e8ae4c83fafc94c464f6_22616_1620982655.mp3', 'clar清楚 + ify表动词 → clarify澄清，弄清', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (493, 'clerk', '/klɜːrk/', 'clerk.mp3', 'n.职员；办事员；店员；  v.做文书工作', '3_0_20170930071601_52606_c-gigapixel-scale.jpg', 'd_24_10244_0_3_20150808230423.png', 'For many people', '对许多人来说，银行职员是一份稳定又体面的工作。', '3_0_20170930071601_99351_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (494, 'coach', '/koʊtʃ/', 'coach.mp3', 'n.教练；四轮大马车；  v.训练，指导', '1f6aa179ce45acce625f5b397840e855_146783_1575085583.jpeg', 'd_24_5744_0_4_20150808224322.png', 'The volleyball coach is talking to her team members.', '这位排球教练正在和她的队员们交谈。', '5xbbjzkkt7qdt8wajqmtexnzvf8qayuy.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (495, 'collect', '/kəˈlekt/', 'collect.mp3', 'v.收集，采集；领取', '8ae09eb1d49648a0da44da9a7fc3c631_94313_1565606956.jpg', 'd_24_10100_0_4_20150808230346.png', 'I like collecting old stamps.', '我喜欢收集旧邮票。', 'us_I_like_20250115134451693_278ff4380f0e93060fbf.mp3', 'col共同 + lect收 → collect收集', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (496, 'comfortable', '/ˈkʌmfərtəbl/', 'comfortable.mp3', 'adj.舒适的，舒服的', '6cb7e5880801cb2cf93ce9b067b9e87b_89083_1535081976.jpeg', '20140927_21_06_49_958_v3.png', 'The man looked so comfortable lying in the chair.', '这个男人躺在椅子上，看起来非常舒适。', '2c01ffa04d25b658fb2b8e51c8ade746_35827_1535081970.mp3', 'com共同 + fort强大，力量 + able能…的 → comfortable愉快舒适的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (497, 'communicate with', '/kəˈmjunɪˌket wɪð/', 'communicate with.mp3', 'phr.与……交流', 'cd40605cd5861d1310e5bf3cee169948.jpg', '', 'They communicate with each other by mobile phone.', '他们通过手机相互交流。', 'c2706d1fd57fbe66f2f85b648898eec3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (498, 'concern about', '/kənˈsɜrn əˈbaʊt/', 'concern about.mp3', 'phr.忧虑，担心，关心', '1684347154dfbb40ad9f306c5a7cb62c.jpeg', '', 'People are much more concerned about the environment than before.', '人们比以前更关心环境了。', '7c541e2845f8856bd33fdb4a11a4e57c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (499, 'consultant', '/kənˈsʌltənt/', 'consultant.mp3', 'n.顾问；高级顾问医师', 'c5496ec517b1c4555850d7f2dbcc800a_75393_1565341975.jpg', 'd_16_6297_0_2_20150808230524.png', 'The consultant will explain how we should run our business.', '顾问将会解释我们应该如何经营我们的事业。', 'sa_1_6297_0_2_20150808124953.aac', 'consult咨询 + ant表示人 → consultant会诊医师，专科医生；顾问', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (500, 'corn', '/kɔːrn/', 'corn.mp3', 'n.玉米；谷物，谷粒', 'i_1_5550_0_2_20150808123949-gigapixel-scale.jpg', 'd_24_5550_0_3_20150808224132.png', 'Sweet corn tastes best with salt and butter.', '吃甜玉米的时候加上盐和黄油味道最好。', '1d3e524642d2a9f03b44e957d8a1afe1_16346_1640575235.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (501, 'corporation', '/ˌkɔːrpəˈreɪʃn/', 'corporation.mp3', 'n.公司', '81e14a0474879a8c4d9e5123295a8a6e_136795_1538659478.jpg', 'd_16_6641_0_3_20150808230855.png', 'In our corporation', '在我们公司，我们会听取每个人的意见。', '2a3b60d1d8f71b7e4a4d111e5597e4a2_20107_1557478107.mp3', 'corporat(e)公司的 + ion名词后缀 → corporation公司', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (502, 'corresponding', '/ˌkɔːrəˈspɑːndɪŋ/', 'corresponding.mp3', 'adj.相应的', '3_0_20170930071225_37164_c-gigapixel-scale.jpg', '20130610_07_03_33_610.png', 'Each lock has its own corresponding key.', '每一把锁都有它对应的钥匙。', '3_0_20170930071225_52274_c.aac', 'correspond符合，通信 + ing形容词后缀 → corresponding 相应的；通信的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (503, 'cough', '/kɔːf/', 'cough.mp3', 'v.咳嗽；  n.咳嗽', '92b970eeb97772a09a87c2a5cba7cd83_173762_1577950602.jpeg', 'd_24_17652_0_4_20150808233154.png', 'He coughed badly when he was ill.', '他生病时咳嗽得厉害。', 'byzdfkeamzymw9cqmebp9xstny63cuqp.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (504, 'council', '/ˈkaʊnsl/', 'council.mp3', 'n.议会；理事会；委员会', 'd5ab75e55db78e29825fd9734ac6ae92_30840_1710998713.jpg', 'd_1_4891_0_3_20150808123117.png', 'The council members are currently holding a meeting.', '委员会成员现在正在举行会议。', 'da11911cdd501469d7ad6d76363ba7bc_32638_1579317261.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (505, 'credit', '/ˈkredɪt/', 'credit.mp3', 'n.（借钱偿还的）信誉，信用；荣誉；学分；借款；债权；  v.信赖；认为是……的功劳；记学分', 'b9ba2a18e7f897b7007d24273a4b6179_27508_1700536074.jpeg', 'd_24_3880_0_4_20150808223353.png', 'It\'s better to use a credit card than to carry cash.', '刷信用卡比携带现金要好。', 'us_Its_better_20231121110800695_ce9f6e91df52b60873a1.mp3', 'cred相信 + it名词后缀 → credit信任', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (506, 'critic', '/ˈkrɪtɪk/', 'critic.mp3', 'n.评论家', 'i_1_711_0_4_150906115624-gigapixel-scale.jpg', 'd_105_711_0_2_20150809053024.png', 'As a strict food critic', '作为一个严格的美食评论家，我觉得这个比萨还行吧。', '37cce5bda00a477e_1266883485290945112_250207.mp3', 'crit批评 + ic人 → critic批评家', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (507, 'currency', '/ˈkɜːrənsi/', 'currency.mp3', 'n.货币；流通；流行', '8ab7f2ae14c735e2429748f82855a9d5_271248_1656647111.jpg', 'd_16_5695_0_2_20150808225713.png', 'The currency of the United States of America is the US dollar.', '美国的流通货币是美元。', '58dc534cd7c514ece20c0f8e9a9e62e9_23713_1632379607.mp3', 'curr跑，发生 + ency表名词，性质状态 → 跑来跑去的钱 → 流通货币', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (508, 'cushion', '/ˈkʊʃn/', 'cushion.mp3', 'n.垫子；靠垫；坐垫；  v.减轻，缓和', '3_0_20170928071352_81561_c-gigapixel-scale.jpg', '20121225_20_12_29_725.png', 'The crown was on the red cushion. Someone must have stolen it!', '皇冠之前明明放在红色垫子上的。一定是有人把它偷走了！', 'us_The_crown_20240513134946781_1c77a9e26a30e0c0e4de.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (509, 'cycle', '/ˈsaɪkəl/', 'cycle.mp3', 'n.周期，循环；  v.骑自行车', 'i_1_9148_0_6_160305151059-gigapixel-scale.jpg', 'd_24_9148_0_4_20150808230042.png', 'The diagram shows the water cycle process.', '这张图表展示了水循环过程。', 'sa_1_9148_0_3_20150808131238.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (510, 'damage to', '/ˈdæmɪdʒ tuː/', 'damage to.mp3', 'phr.对…的损害', 'f3a8f73a9be2a0b2f416868d23358aca.jpg', '', 'An accident caused serious damage to the car.', '一场车祸对这辆车造成了严重的损害。', '154f82efaa4ff067ed9588ad08f03cda_47648_1593575614.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (511, 'dealer', '/ˈdiːlər/', 'dealer.mp3', 'n.经销商，商人，（俚）毒贩', '2a121b58d0b9ca1f24d20f4221240a11_98782_1569056310.jpg', '20140907_09_30_08_895_v3.png', 'The car dealer gave us a great deal on our new car.', '买这辆新车时，汽车经销商给了我们很大的优惠。', 'sa_2_6257_0_3_20150808150424.aac', 'deal生意 + er名词后缀：行为的主动者，做某事的人 → n.经销商，商人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (512, 'decay', '/dɪˈkeɪ/ ', 'decay.mp3', 'v.腐烂；衰退；腐朽；  n.腐烂；衰退；腐败', '71441f7f2d987498680bf66f694b5ffc_46882_1565707751.jpg', 'd_1_4750_0_2_20150808122952.png', 'These oranges have decayed on top.', '这些橘子从顶部开始腐烂了。', 'u7grdahfh2xsewddkycehawluevsv56p.mp3', 'de向下 + cay落下 → 向下掉 → decay腐烂，衰退', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (513, 'decision on', '/dɪˈsɪʒn ɑːn/', 'decision on.mp3', 'phr.……的决定', '11bec24bb1e2da2fd4a158c2b9a425ae.jpg', '', 'He had to make a decision on which way to go.', '他必须做出走哪条路的决定。', '4917e307779d828737dd8f84aa5cf54f_40352_1593585138.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (514, 'department', '/dɪˈpɑːrtmənt/', 'department.mp3', 'n.部门；司', '3_0_20160528165100_82678_c-gigapixel-scale.jpg', 'd_24_4912_0_4_20150808223637.png', 'Our company consists of three departments.', '我们公司由三个部门组成。', '109c545251e1d8f7_1266883013433514504_250207.mp3', 'de加强意义 + part部分 + ment名词后缀 → 一部分 → department部门，系', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (515, 'destruction', '/dɪˈstrʌkʃn/', 'destruction.mp3', 'n.破坏，毁灭', '2bbf2b4041c023f9e802f6a2bdf5e122_163471_1533106132.jpeg', 'd_1_5802_0_2_20150808124428.png', 'The war caused the destruction of the city.', '这场战争毁了整座城市。', '3dd3224418c871aa_1266883483994118710_250207.mp3', 'destruct破坏 + ion名词后缀 → destruction破坏', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (516, 'diameter', '/daɪˈæmɪtər/', 'diameter.mp3', 'n.直径', '3_0_20160720071108_55762_c-gigapixel-scale.jpg', 'd_1_4124_0_2_20150808122357.png', 'The worker was measuring the lumber\'s diameter.', '工人正在测量木材的直径。', '96e88abj7k4q8rkgucqx9cybtlyc4p3m.mp3', 'dia穿过，二者之间 + meter测量 → 穿过两者之间测量 → diameter直径', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (517, 'dictation', '/dɪkˈteɪʃn/', 'dictation.mp3', 'n.口述；听写', 'a618af711fba0132476206b9a4b276ef_179977_1532145455.jpeg', 'd_24_9911_0_4_20150808230327.png', 'He asked her to write down his dictation.', '他请她把自己的口述写下来。', '96fdc0785e4392adadbc52783d52ac83_84704_1594802206.mp3', 'dictat口授 + ion名词后缀 → 用嘴说的 → dictation口授，命令', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (518, 'display', '/dɪˈspleɪ/', 'display.mp3', 'v.展示；显示；陈列；  n.表现，流露；显示；陈列', '31b7f6034da81440c8b008885f0028f3_204333_1586344025.jpeg', 'd_24_5577_0_4_20150808224202.png', 'He proudly displayed the big fish he had caught.', '他自豪地展示着他钓到的大鱼。', '02291795928fd9cba59f71f91444add6_44604_1591773886.mp3', 'dis分开，否定 + play折叠 → 打开，分散 → display展示', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (519, 'distinct', '/dɪˈstɪŋkt/', 'distinct.mp3', 'adj.截然不同的；独特的；明显的；清晰的', '1426491233766-gigapixel-scale.jpg', 'd_1_5656_0_3_20150808124152.png', 'The red umbrella is distinct among the black ones.', '这把红伞在这些黑伞中显得与众不同。', 'sa_1_5656_0_3_20150808124152.aac', 'dis分开 + stinct（sting）刺，做标记 → 分开标记的，区分清楚的 → distinct独特的，清楚的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (520, 'drift', '/drɪft/', 'drift.mp3', 'v.漂流；使漂流；  n.漂流物', '3_0_20160718114240_71695_c-gigapixel-scale.jpg', 'd_1_9012_0_2_20150808131133.png', 'The boat is drifting down the river.', '船顺着河流漂去。', 'a070bfc8c58221d7_1266883628672572018_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (521, 'effort', '/ˈefərt/', 'effort.mp3', 'n.努力；艰难的尝试', '3_0_20170928071304_84327_c-manual-scale.jpg', 'd_24_7137_0_4_20150808225001.png', 'She makes efforts to do exercise so that she can keep fit.', '她努力健身以保持健康。', '5f61680ec9fc1e4c_1266883376510839688_250207.mp3', 'ef出 + fort力量 → 付出力量 → effort努力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (522, 'England', '/ˈɪŋɡlənd/', 'England.mp3', 'n.英格兰，英国', '36b7eb89fb64f0eb223672c65a795a31_122780_1541847532.jpg', 'd_24_17135_0_4_20150808232115.png', 'London is located in the south-east of England.', '伦敦位于英格兰东南部。', 'e10bf66c677aec65_1266763399640275662_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (523, 'equipment', '/ɪˈkwɪpmənt/', 'equipment.mp3', 'n.设备，器材', '5a7c7c5e3976c1b555e9e773085555c8_138409_1575362116.jpeg', 'd_24_8373_0_3_20150808225618.png', 'Students now enjoy using the exercise equipment for working out.', '现在的学生喜欢使用健身器材运动。', '5bd740708fefe36a_1266883007324314208_250207.mp3', 'equip配备，装备 + ment表名词 → equipment设备', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (524, 'essential', '/ɪˈsenʃl/', 'essential.mp3', 'adj.必不可少的，极其重要的；本质的；重要的；基本的；  n.要素；必需品', '56fa8e44fa34e8429149f94eb2f1a45c_121182_1741576082.jpg', 'd_24_4716_0_3_20150808223543.png', 'Hot pot and mahjong are essential components of Sichuan culture.', '火锅和麻将是四川文化必不可少的一部分。', 'd377a218d0a115c98483068ed1d9cc1f_47072_1535096969.mp3', 'essent存在，本质 + ial ...的 → essential必要的，本质的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (525, 'exceed', '/ɪkˈsiːd/', 'exceed.mp3', 'v.超过；胜过；超出', 'd4c5c3bf0de041ca2dce834d65986cbb_72781_1720684998.jpg', 'd_107_4184_0_2_20150809004751.png', 'The temperature is expected to exceed 90 degrees Fahrenheit today.', '今天的气温预计会超过90华氏度。', 'us_The_temperature_20240711160322009_a4dc65f6cb499780aa67.mp3', 'ex向外 + ceed去；让步 → exceed超出', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (526, 'experience', '/ɪkˈspɪriəns/', 'experience.mp3', 'n.（一次）经历，感受，体验；  v.体验，感受', '951ca3ad29c38a6a9b6f85550c3a2117_103178_1595859217.jpg', 'd_24_4900_0_4_20150808223620.png', 'That roller coaster ride was really a frightening experience.', '这趟过山车真是一次可怕的经历。', 'kch3r6q826lb29f4vzgk4h73nz6qpdpl.mp3', 'ex出 + per尝试 + ience名词后缀 → 尝试出来的东西 → experience经验', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (527, 'factor', '/fæktɚ/', 'factor.mp3', 'n.因素', '9f9d450a9aa20f3dddfc919d5062fc64_99366_1601186773.jpg', '20130510_18_29_08_141.png', 'An important factor for him when buying a car is its appearance.', '车的外观是他买车时考虑的一个重要因素。', '55c00aefbf88fb85ac49a5b58e556af0_49280_1602575671.mp3', 'fact做，制作 + or表名词，人或物 → 促使人做的东西 → factor要素；动力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (528, 'fall behind', '/fɔl bɪˈhaɪnd/', 'fall behind.mp3', 'phr.落后', 'fallbehind_7755_20231106_4a426e12.jpg', '', 'Since he can\'t roll it', '由于这个男的没办法滚动这红色的方块，所以他落后了。', 'sa_11_7755_0_2_20150808173659.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (529, 'far', '/fɑːr/', 'far.mp3', 'adv.（空间或时间）远，久远；  adj.远方的；  n.远方', '3_0_20170713071453_22185_c.jpg', 'd_24_16435_0_3_20150808231225.png', 'Though we\'re far apart', '虽然我们相隔遥远，但你永远在我心中。', '3_0_20170713071453_12000_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (530, 'feasible', '/\'fizəbl/', 'feasible.mp3', 'adj.可行的，行得通的', 'i_1_8963_0_3_20150808131101-gigapixel-scale.jpg', 'd_1_8963_0_3_20150808131101.png', 'I think your construction plan is feasible. Let\'s start to build the house!', '我觉得你的建造计划很可行，我们开始建房子吧！', 'sa_8963_1_0_2_150707113751.mp3', 'feas做 + ible能……的 → 能够做的 → feasible可行的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (531, 'fence', '/fens/', 'fence.mp3', 'n.篱笆，围栏，栅栏；  v.击剑', '20120604_04_04_50_620-gigapixel-scale.jpg', 'd_24_7259_0_4_20150808225051.png', 'The school is surrounded by a large fence.', '学校被很大的围栏围住。', '3ad1e4e9e79a828c_1266883379654863654_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (532, 'fiber', '/ˈfaɪbər/', 'fiber.mp3', 'n.纤维（物质）', '3_0_20170713071059_9502_c-gigapixel-scale.jpg', '106e883e7e88328546cfeca5d28cb126_22720_1532341943.png', 'We can see the fibers of the rope under a magnifying glass.', '在放大镜下，我们能看见这条绳子的纤维。', '3_0_20170713071059_25967_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (533, 'following', '/ˈfɑːloʊɪŋ/', 'following.mp3', 'prep.随后，在……以后', '02f456c180a485cc9e1aae65ed91d082.jpeg', 'd_24_11036_0_3_20150808230539.png', 'Following the beach volleyball', '沙滩排球之后将会有一场派对。', 'd3a5de9dd9515dc847eda03c8a6d0a3f.mp3', 'follow跟随 + ing表示行为、状态、情况及其他 → following接着的；下列的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (534, 'foreigner', '/ˈfɔːrənər/', 'foreigner.mp3', 'n.外国人', '63d6b08f959969bc266f7e6dd0026a06_122795_1732241428.jpg', 'd_24_18894_0_3_20150808235919.png', 'We have two new classmates', '我们班来了两个新同学，他们是外国人！', '0f68468bf767994c_1266883111997561486_250207.mp3', 'foreign外国的 + er名词后缀，人 → 外国人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (535, 'fountain', '/ˈfaʊntn/', 'fountain.mp3', 'n.泉水，喷泉', 'i_1_6457_0_6_150928175806-gigapixel-scale.jpg', '20130130_16_27_54_977.png', 'The fountain becomes so colorful at night.', '在晚上，喷泉变得五彩缤纷。', 'wjf5l28b6nkz5mmbyca5khgb49x682kz.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (536, 'general', '/ˈdʒenrəl/', 'general.mp3', 'adj.普遍的，总的；  n.将军', 'i_13_18578_0_2_20150808205521-gigapixel-scale.jpg', '20130130_16_14_46_554.png', 'In general', '一般来说，树木是又高又绿的，而且还有棕色的树皮。', 'zvhggjphwarc94h2w74t7f83lhmjz5cf.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (537, 'go', '/ɡoʊ/', 'go.mp3', 'v.变为', '0274a4005a74b198edd29d91b4bd50e1_93776_1595058417.jpg', 'd_16_19648_0_2_20150809023112.png', 'His hair is starting to go grey.', '他的头发开始变灰了。', 'c6c18caf21dcc2745ae1a00c352069c5_25952_1599550857.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (538, 'go along with', '/ɡoʊ əˈlɔːŋ wɪð/', 'go along with.mp3', 'phr.陪同前往', '440e6b82bee37722098e7ad911b20ba5.jpg', '', 'His sick friend couldn\'t go to the hospital alone', '他朋友生病，没办法一个人上医院，所以他陪他一起去。', '2cefa6c4169c49c882b510804d445477.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (539, 'go over', '/ɡoʊ ˈoʊvər/', 'go over.mp3', 'phr.复习，重温', '94f4fc2df2359b97c1032b6b8a239af6_198145_1566290618.jpg', '', 'After class', '这个男孩一定会在课后复习他刚学的东西。', 'ce2315462efa103e223c045452aeb443_33070_1566290612.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (540, 'gradually', '/ˈɡrædʒuəli/', 'gradually.mp3', 'adv.逐渐地，逐步地', '844c795cde6e4dbd83c43b37fc6d3cdd_96723_1579594902.jpeg', '20141014_20_21_46_962_v3.png', 'Gradually', '渐渐地，他变得越来越强壮。', '95414f6c6037d1e7_1266797983106640680_250123.mp3', 'gradual逐步的 + ly…...地 → gradually逐步地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (541, 'gratitude to', '/ˈɡrætɪtuːd tuː/', 'gratitude to.mp3', 'phr.对……的感激', 'd8f494216fd55d11a9a05ca051fa61cf.jpg', '', 'The little girl showed her gratitude to her mother.', '小女孩对她的妈妈表达了感激之情。', '58cbc6b66369e281e0dc5e54bc28905d_44192_1593585000.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (542, 'greedy', '/ˈɡriːdi/', 'greedy.mp3', 'adj.贪婪的，贪心的，贪吃的', '6d50a46595c4d7097307b9340e26481c_73377_1655374837.jpg', 'd_107_5894_0_2_20150809014439.png', 'The greedy dog also wants the bone in the water.', '这只贪婪的狗狗还想要水里的骨头。', '2xr7t36ytdm57gkafkqpkwg2b38e6eks.mp3', 'greed贪婪 + y…的 → greedy贪吃的，贪婪的，贪心的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (543, 'harvest', '/ˈhɑːrvɪst/ ', 'harvest.mp3', 'n.收成；  v.收割；获得；采集', '2e510f435be8c71f6ffcdb5c4c17ca3e_608788_1610526705.jpg', '20121225_20_25_58_283.png', 'The farmer is happy about the harvest of rice.', '农民对稻子的收成感到很高兴。', '229e7af53a672029439271164044ed8d_16973_1619331424.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (544, 'humble', '/ˈhʌmbl/', 'humble.mp3', 'adj.卑微的；谦逊的；简陋的；  v.轻松打败（尤指强大的对手）；使……谦逊，使……卑下', '5fe16b7375c309b50019509e3d090cb8_121227_1568256463.jpeg', 'd_1_4265_0_2_20150808122557.png', 'The general is of humble origin.', '那位将军出身卑微。', '1ca7817b0a986f32fe4a4af784973fad_11331_1626158030.mp3', 'hum土地 + ble形容词后缀 → 接近地面 → humble谦恭的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (545, 'hurry', '/ˈhɜːri/', 'hurry.mp3', 'n.匆忙；  v.催促；赶紧（做某事）', '719c80709297120244d3df3a4bdf5c37_182132_1535081542.jpeg', 'd_93_13034_0_4_20150809002059.png', 'He is often in a hurry to eat his breakfast.', '他总是匆忙地吃早饭。', '4f1eeb7660ee20accd4cfb455e4b2697_16189_1619339941.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (546, 'illustration', '/ˌɪləˈstreɪʃn/', 'illustration.mp3', 'n.插图', 'i_1_10023_0_3_20150808131543-gigapixel-scale.jpg', 'd_105_10023_0_2_20150809061619.png', 'The book\'s illustrations of fruits help me to recognize them.', '这本书里的水果插图帮我认出那些水果。', 'sa_1_10023_0_3_20150808131543.aac', 'il 使 + lustr =light光亮 + ation表名词 → 使...光亮 → 说明', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (547, 'imply', '/ɪmˈplaɪ/', 'imply.mp3', 'v.暗示；暗指；意味着', 'b8ebb1cbc6cf1863f89efc7dc39e8f0b_48885_1736488635.jpg', 'd_1_9263_0_2_20150808131336.png', 'The light implies that there is somebody in the house.', '灯光暗示房子里有人。', 'u45npuy2btw2pnhehvavwu5zpy75udap.mp3', 'im进入 + ply重叠，折叠 → 重叠表达 → imply 暗示，意味', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (548, 'in the world', '/ɪn ðə wɜːrld/', 'in the world.mp3', 'phr.世界上', '29195caecac3b69662b572e2ccaf3b95.jpeg', '', 'The blue whale is the largest living mammal in the world.', '蓝鲸是世界上现存最大的哺乳动物。', 'ab03528fe1906babf7068addb01cf83d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (549, 'increase in', '/ɪnˈkris ɪn/', 'increase in.mp3', 'phr.增加', 'eab3959428e5859ea7d4b37fbe741b6d.jpeg', '', 'There\'s an increase in population in recent years. ', '近年来，人口在增加。', 'd63fd3148b48e10d9b390ec55500f6d3_46496_1593574895.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (550, 'independent of', '/ˌɪndɪˈpɛndənt ʌv/', 'independent of.mp3', 'phr.无关；独立于', '0344de3c15806fcca5bdc7e417320560.jpeg', '', 'He makes money selling fruit online', '除了全职工作之外，他还在网上卖水果赚钱。', '846f58436edfc61854c702becd519d57.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (551, 'infectious', '/ɪnˈfekʃəs/', 'infectious.mp3', 'adj.传染的；具有感染力的；易传播的', '474270a38e79146b748312b64c68e9d0_173798_1552545702.jpeg', '', 'Her yawn was so infectious that everyone in the office yawned with her.', '她的哈欠极具感染力，以至于办公室里的每个人都跟着她打起了哈欠。', '5f47ae492633af78e05f8df9bc20f9da_22772_1620626894.mp3', 'in进入 + fect做 + infect做进去=传染 + ious……的 → infectious传染的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (552, 'infinite', '/ˈɪnfɪnət/', 'infinite.mp3', 'adj.无限的，无穷的；  n.无穷，无限大', 'e95aa44e8c99a9d7d4c7dcc4736edc90_45830_1565621881.jpg', 'd_107_7006_0_2_20150809021333.png', 'We live in an infinite universe that might have no boundaries.', '我们生活在一个可能没有边界的无限宇宙中。', 'us_We_live_20250407092950533_cf1fc7e068ba1b51cc3e.mp3', 'in无 + fin结束，范围 + ite有……的 → 没有范围的 → 无限的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (553, 'inspect', '/ɪnˈspekt/', 'inspect.mp3', 'v.检查，审查', '15dc00e787a67dff6f0e49c2e074dff9_198451_1575287871.jpeg', '20140929_00_24_18_85_v3.png', 'He is inspecting the shop for a hygiene check.', '他正在对这家店铺进行卫生检查。', '5kctx9ky7sqrtaecj8czj5clrw3za4km.mp3', 'in内 + spect看 → 看进去 → 视察', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (554, 'intense', '/ɪnˈtens/', 'intense.mp3', 'adj.强烈的，激烈的；紧张的；认真的；热情的，热切的', 'c6a4fc13f7c800aef8445657b1db2338_106481_1538666787.jpg', 'd_1_9898_0_3_20150808131507.png', 'People are having an intense training in the gym.', '人们正在健身房里进行着紧张的训练。', 'd5c2b0b97db52d0c8bb0d6af402aced3_13367_1539599457.mp3', 'in使 + tense延伸 → 使拉长，绷紧 → intense剧烈的，强烈的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (555, 'interfere with', '/ˌɪntərˈfɪr wɪð/', 'interfere with.mp3', 'phr.妨碍', '70a13aeb7f970521e68c04771752f436_101858.jpg', '', 'His late arrival interfered with the progress of the meeting.', '他的迟到妨碍了开会的进程。', '7c6837654c36a104685572e085e6a71a_34795.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (556, 'interference with', '/ˌɪntərˈfɪrəns wɪð/', 'interference with.mp3', 'phr.干涉，干扰', 'b282361aab5aa3904f530b787dd4ca27_157691.jpg', '', 'Interference with my sleep leaves me in a bad mood.', '睡眠被干扰让我觉得很不爽。', 'f5114525086f33417e1ec6e5a9275749_36355.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (557, 'invitation', '/ˌɪnvɪˈteɪʃn/', 'invitation.mp3', 'n.请帖，邀请函；邀请', 'a4319c3ca31cb84f93660505bd2800f1_183929_1604977189.jpg', 'd_24_8055_0_4_20150808225409.png', 'My well-prepared wedding invitation is very beautiful.', '我精心准备的结婚请柬很漂亮。', '3b89ddec03f2b656_1266883377207815086_250207.mp3', 'invit=invite邀请 + ation表行为 → 邀请', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (558, 'invite', '/ɪnˈvaɪt/', 'invite.mp3', 'v.邀请', '4dbca7887b310e7be932dd154468b40c_140878_1733120666.jpg', 'd_24_7942_0_4_20150808225250.png', 'The house agent invited us in to have a look at the house.', '房屋中介邀请我们进去看一下这栋房子。', 'dd638ada68841f3c_1266798147708300266_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (559, 'joke', '/dʒoʊk/', 'joke.mp3', 'n.笑话；  v.讲笑话，开玩笑', '983c3e3f5b9bccfafc38239233d24830_201788_1578560243.jpeg', '20121225_18_40_58_925.png', 'His jokes always make people laugh.', '他讲的笑话总是使人哈哈大笑。', '68e811cd675709af_1266797982003649028_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (560, 'kingdom', '/ˈkɪŋdəm/', 'kingdom.mp3', 'n.王国', '01dcf8ad3912cc7505270888cfbd414f_173620_1591925975.jpg', 'd_24_5015_0_3_20150808223823.png', 'The lion rules the animal kingdom with the help of his friends.', '狮子在朋友们的帮助下统治动物王国。', '2db31b8a41e98b68_1266883373374987006_250207.mp3', 'king国王 + dom状态或领域 → kingdom王国', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (561, 'launch', '/lɔːntʃ/', 'launch.mp3', 'v.发射；创办，开始从事；  n.（游艇、汽艇）下水', 'i_5_4381_0_9_160310175030-gigapixel-scale.jpg', 'd_1_4381_0_3_20150808122710.png', 'They launch the rocket into the sky.', '他们向空中发射火箭。', 'cd6e6b8ae9a2379fa0e09c10bf893701_47714_1581044985.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (562, 'leisure', '/ˈliːʒər/', 'leisure.mp3', 'n.闲暇，休闲', '82dde99cb65222220102df98bf962019_123678_1705640173.jpeg', 'd_1_5775_0_2_20150808124358.png', 'In their leisure time', '闲暇时候，她们喜欢玩棋类游戏来放松自己。', 'us_In_their_20240827094723507_43229df068ea13fedd6d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (563, 'letter', '/ˈletər/', 'letter.mp3', 'n.信；字母', 'i_13_17987_0_2_20150808205221-gigapixel-scale.jpg', 'd_24_17987_0_3_20150808233946.png', 'I love getting letters in the mailbox.', '我喜欢在邮箱里收到信。', '88e43175c0e8431f_1266763524414024558_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (564, 'local', '/ˈloʊkəl/ ', 'local.mp3', 'adj.本地的，地方的', 'd50ebabf812caeda4963dcaf173b7ad0_83821_1565342720.jpg', 'd_24_4885_0_3_20150808223607.png', 'The local people have their own clothing and culture.', '当地人有自己的服装和文化。', '6deca6b6c99b7f05_1266883115790216146_250207.mp3', 'loc地方 + al形容词后缀 → local地方的，局部的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (565, 'look back', '/lʊk bæk/', 'look back.mp3', 'phr.回顾', '3894210cb6b30dcbe45d8311b148ef82.jpg', '', 'The old man and his daughter are looking back at their fond memories.', '老人和他的女儿正在回顾他们的美好回忆。', 'e39db976bd06386285a106f3f4579264.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (566, 'lorry', '/ˈlɔːri/', 'lorry.mp3', 'n.卡车；运货汽车', 'i_1_5186_0_3_20150808123629-gigapixel-scale.jpg', 'd_109_5186_0_2_20150809054103.png', 'All the stuff was carried in the lorry.', '所有货物都搬上卡车了。', '3006727e4ad04c30_1266883526875961950_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (567, 'lung', '/lʌŋ/', 'lung.mp3', 'n.肺', 'b3cb5ab1c984eac12b4d0783719e6c53_100622_1584676743.jpeg', 'd_105_5233_0_2_20150809054545.png', 'Lungs are the organs responsible for breathing.', '肺是负责呼吸的器官。', '9zwdzjalg8wxmv9hkkby2bjhpm948l6w.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (568, 'majority', '/məˈdʒɔːrəti/', 'majority.mp3', 'n.大多数，大部分', '20120508_03_38_47_481-gigapixel-scale.jpg', 'd_16_5431_0_2_20150808225305.png', 'The majority thinks it\'s a good plan', '大多数人认为这是一个好的计划，但我不这么认为。', 'sa_47_5431_0_3_20150809005025.aac', 'major主要的 + ity表名词 → majority大多数', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (569, 'management', '/ˈmænɪdʒmənt/', 'management.mp3', 'n.管理者；经营，管理，处理', 'i_1_7833_0_3_20150808130043-gigapixel-scale.jpg', 'd_1_7833_0_3_20150808130043.png', 'The management team is having a regular meeting.', '管理部门正在开例行会议。', 'sa_1_7833_0_3_20150808130043.aac', 'manage管理 + ment表名词 → management管理', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (570, 'marvelous', '/ˈmɑːrvələs/', 'marvelous.mp3', 'adj.叹为观止的，令人惊奇的；非凡的', '8939f6fca9947a93d1a974236faf8c5f_177649_1564802071.jpeg', 'd_106_8971_0_2_20150809074801.png', 'It is the most marvelous fireworks show! the girl exclaimed.', '“这是最叹为观止的烟花表演！”这个女孩惊叹道。', 'xec399e2t6gcnm2c3zbjwppapecdcqav.mp3', 'marvel奇迹 + ous……的 → marvelous奇迹般的；了不起的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (571, 'matter', '/ˈmætər/', 'matter.mp3', 'v.要紧；有关系；  n.问题', '3_0_20170701113205_11793_c-gigapixel-scale.jpg', 'd_24_16415_0_3_20150808231150.png', 'Food', '食物、水和房子对生存来说至关重要。', '3_0_20170701113205_54775_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (572, 'mechanical', '/məˈkænɪkl/', 'mechanical.mp3', 'adj.机械的，机械学的，机械性的', 'd1372334d4da6bb67e18babc73c20665_185899_1573805968.jpeg', 'd_107_6233_0_2_20150809015334.png', 'We can use this mechanical claw to pick up dolls.', '我们可以用这个机械爪来抓娃娃。', 'tuc9p9axrkxmuw2gmycamxcbg5agra9h.mp3', 'mechanic机械工，技工 + al形容词后缀 → 机械相关的 → mechanical机械的，机械学的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (573, 'mistake for', '/mɪˈstek fɔr/', 'mistake for.mp3', 'phr.错认', '1b7a5b1352b05494c0450519c48dacb7.jpg', '', 'He mistook her for a famous actress.', '他误认为她是一位著名的女演员。', 'bac1d4443618e4a6b551e591faa90294_49359_1599537727.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (574, 'move', '/muːv/ ', 'move.mp3', 'v.移动；（使）改变位置；  n.迁居', '3_0_20160521110940_49621_c-gigapixel-scale.jpg', 'd_24_17961_0_4_20150808233751.png', 'He\'s using a truck to help him move house.', '他正用卡车帮他搬家。', '7ptxhzm725eca7pc3zbfbthl6rja7f93.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (575, 'namely', '/ˈneɪmli/', 'namely.mp3', 'adv.即，也就是', 'fe5007c8ff9dafee18935e274dae2208_62168_1572079005.jpeg', '', 'She took two classes this morning', '她今天上午上了两节课，即英语课和数学课。', '5b9037cddc1d6ac5d7457fe9e0bd59a8_43592_1572338682.mp3', 'name名字 + ly副词和形容词后缀 → 顾名思义，如名字所说 → namely即，也就是', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (576, 'nerve', '/nɜːrv/', 'nerve.mp3', 'n.神经；胆量，勇气；  v.给……以力量，使振作', '77a89575b750853a282d4853e64962d7_91062_1564370517.jpg', 'd_1_7510_0_3_20150808130002.png', 'There are many nerves in the brain.', '大脑里有许多神经。', 'ce43ba53df4a7956_1266883626281491000_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (577, 'occasion', '/əˈkeɪʒn/', 'occasion.mp3', 'n.场合，时候，活动；时机，机会', '34018208d26ef1836a4349bcba88c31e_153568_1533109671.jpeg', 'd_1_5059_0_3_20150808123416.png', 'In China', '在中国，除夕夜是重要的家庭团聚时刻。', '5afc28174c5d450e_1266883375881607792_250207.mp3', 'oc加强 + cas降临 + ion 表名词 → 突然落下的瞬间 → occasion时机；场合', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (578, 'opening', '/ˈəʊpənɪŋ/', 'opening.mp3', 'n.开口；孔，洞；开始；开幕，开幕式；职位空缺', '520871e086c3998c6d4a4515dafedebd_92908_1584608717.jpeg', 'd_24_5532_0_3_20150808224114.png', 'We can escape the cave through this opening.', '我们可以从这个开口逃出洞穴。', '4b604c7cf6b3eeb9ddc37e5709be6921_48784_1584608714.mp3', 'open开启 + ing名词后缀 → opening开幕，开口', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (579, 'operator', '/ˈɑːpəreɪtər/', 'operator.mp3', 'n.（电话）接线员', '9196f358c4c787a6b1f845bdd815fcc4_82243_1565342943.jpg', 'd_105_6312_0_2_20150809055632.png', 'Ask for the operator—she’ll know the right phone number.', '你可以询问接线员，她知道正确的电话号码。', 'sa_103_6312_0_3_20150809022928.aac', 'oper工作 + ator表示做...工作的人或物 → operator操作人员，接线员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (580, 'overweight', '/ˌoʊvərˈweɪt/', 'overweight.mp3', 'adj.超重的；  n.超重', 'd34d41da2aaf4dcd2d386aa74bb90036_67210_1635843537.jpg', 'd_16_18220_0_2_20150809015058.png', 'The forklift cannot pick up the overweight luggage.', '这辆叉车无法提起这件超重的行李。', 'us_The_forklift_20240319110730129_bf7cae7ed56ee9587e63.mp3', 'over过度 + weight重量 → overweight超重的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (581, 'partner', '/ˈpɑːrtnər/', 'partner.mp3', 'n.伙伴，搭档；配偶，伴侣；  v.成为……的合伙人', 'i_1_5068_0_4_20150808123427-manual-scale.jpg', '20141014_15_42_31_154_v3.png', 'We are all partners here. Let\'s work together to finish the job.', '我们是好搭档，让我们齐心协力完成工作吧。', 'sa_1_5068_0_4_20150808123427.aac', 'part部分，分开 + ner人 → 分开合作的人 → partner伙伴，搭档', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (582, 'pay back', '/peɪ bæk/', 'pay back.mp3', 'phr.偿还（借款等）', 'i_16_18675_0_2_20150809015909.jpg', '', 'A trustworthy friend always #pays back# the money he borrows.', '一个值得信任的朋友是有借有还的。', '7ee3957ef5b1ba24_1266797990072986470_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (583, 'pillow', '/ˈpɪloʊ/', 'pillow.mp3', 'n.枕头；  v.垫，枕着', 'i_1_6560_0_5_20150808125222-gigapixel-scale.jpg', '20121227_14_03_26_257.png', 'I love sleeping with soft pillows.', '我爱枕着软软的枕头入睡。', 'sa_1_6560_0_5_20150808125222.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (584, 'pipe', '/paɪp/', 'pipe.mp3', 'n.管子，导管', 'i_1_8014_0_2_20150808130309-gigapixel-scale.jpg', 'd_24_8014_0_3_20150808225345.png', 'These pipes are made of plastic', '这些管子是塑料做的，所以它们非常轻。', 'sa_1_8014_0_2_20150808130309.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (585, 'pleased', '/pliːzd/', 'pleased.mp3', 'adj.高兴的，满意的；  v.使高兴', '8719ef79545b8a2488fa1102b05b36a0_190189_1549943071.jpeg', 'd_24_18114_0_4_20150808234716.png', 'She is very pleased with cola and potato chips.', '她对可乐和薯片感到非常满意。', 'dy69jh8v6j8v5gt5vzufkybmwupl2q2q.mp3', 'pleas高兴 + ed形容词后缀 → pleased高兴的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (586, 'poet', '/ˈpoʊət/', 'poet.mp3', 'n.诗人', 'i_1_6149_0_5_160415143152-gigapixel-scale.jpg', '20130301_12_48_25_518.png', 'He is one of the most famous poets in Chinese history.', '他是中国历史上最著名的诗人之一。', '4cd261ff7d5ab15f_1266883483736976156_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (587, 'pool', '/pu:l/', 'pool.mp3', 'n.泳池，水塘；  v.集中资源（或材料）', '81b29ca51249c2cd5e6252dfa11cab44_98982_1586229706.jpg', 'd_24_16643_0_4_20150808231746.png', 'There is a big swimming pool in the park.', '公园里有个超大的游泳池。', 'rc87wr7eac9n2fgb2ylv7xj9j2e6wwd9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (588, 'precious', '/ˈpreʃəs/', 'precious.mp3', 'adj.珍贵的，宝贵的', 'i_1_4065_0_2_20150808122306-gigapixel-scale.jpg', 'd_16_4065_0_2_20150808223959.png', 'Precious gems like diamonds are very valuable.', '钻石之类的珍贵宝石是很贵重的。', '92dbc664c8871b18_1266883331108198976_250207.mp3', 'prec价值 + ious形容词后缀 → 有价值的 → precious珍贵的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (589, 'preference for', '/ˈprefrəns fɔːr/', 'preference for.mp3', 'phr.对……偏爱', '585be7f21d14a75b2c7e8212bf15c8f6.jpg', '', 'She has a preference for sweet food.', '她偏爱甜食。', '34025f00167b43210c4e6de124b91cf9_33440_1593586305.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (590, 'prescription', '/prɪˈskrɪpʃn/', 'prescription.mp3', 'n.处方，药方', '24d827cae9c9bdfd1aa85c3c429b5335_82445_1704248075.jpg', 'd_105_6453_0_2_20150809055756.png', 'The doctor passed the prescription to the patient.', '医生把处方递给了病人。', 'n8dm6l5fzlnuuk82xt9jrjdsfdtzhe7s.mp3', 'pre预先 + script写 + ion名词后缀 → prescription处方', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (591, 'production', '/prəˈdʌkʃn/', 'production.mp3', 'n.生产', '7c6cbda0e10b3fe2328d4207db6b3053_153554_1565691169.jpeg', 'd_109_6627_0_2_20150809054717.png', 'Thousands of cars are under production in this factory.', '数以千计的汽车在这家工厂进行生产。', '59b070a575210303260c0c9bceed22da_18697_1565691200.mp3', 'product生产 + ion名词后缀 → production生产', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (592, 'profit from', '/ˈprɑːfɪt frəm/', 'profit from.mp3', 'phr.从……得益', '294f8566625e1bbf0bee79651d750d52.jpeg', '', 'He profits a lot from stock trading.', '他在股票交易中大赚了一笔。', '1b76c9f65b574723f3e951bc4fa7efb1.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (593, 'proportion', '/prəˈpɔːrʃn/', 'proportion.mp3', 'n.比例；部分；相称；  v.使成比例；分配', 'f00c4ecbd137bde652ff020427fd7d32_102117_1699334297.jpg', 'd_1_5561_0_3_20150808124000.png', 'The proportion shows we should eat more vegetables and fruits to keep healthy.', '该比例显示，我们应该多吃蔬菜和水果来保持健康。', 'us_The_proportion_20231107132149530_fa80d15a0fa1cab69381.mp3', 'pro前面 + port 部分，分开 + ion名词后缀 → 成分其中一部分 → proportion比例', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (594, 'prove', '/pruːv/', 'prove.mp3', 'v.证明，证实', 'bf80d31f2f97ab18167914e89704e76a_100388_1604904318.jpg', 'd_24_5540_0_5_20150808224121.png', 'It takes one second to say I do', '说一句“我愿意”只用一秒，可证明它却需要一辈子。', 'fe2a3ed5b78fe0e3_1266883620897729506_250207.mp3', 'pro在前面 + ve成为 → 成为先决条件，以证实某事存在 → prove证明，证实', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (595, 'publish', '/ˈpʌblɪʃ/', 'publish.mp3', 'v.出版', '1bc9e2af3b39ef900754637e4b2a1f10_163094_1738737960.jpg', '20140927_14_52_19_666_v3.png', 'She hopes that her book will be published so everyone can buy it.', '她希望自己的书能够出版，这样每个人都可以购买。', 'd610ebdffb97f77e_1266883372280490950_250207.mp3', 'publ公众 + ish动词后缀 → 使面向公众 → publish出版', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (596, 'pull up', '/ˈpʊl ʌp/', 'pull up.mp3', 'phr.停车', '2d85083379cb5bb0a9a5f7bf18052e41.jpg', '', 'He pulled up at the traffic lights.', '他在交通信号灯前停了下来。', '93b2b8f0e8c84706207f5e46cc21ec4a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (597, 'punish', '/ˈpʌnɪʃ/', 'punish.mp3', 'v.惩罚，处罚', '2e032054cf06be06e830c90f44ba3d4b_144878_1538659087.jpg', 'd_24_8016_0_3_20150808225348.png', 'He punished the player by showing the red card.', '他亮出红牌以惩罚一名球员。', '53d65f0eea3f1be4_1266883379465267994_250207.mp3', 'pun处罚 + ish动词后缀 → punish惩罚', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (598, 'pupil', '/ˈpjuːpl/', 'pupil.mp3', 'n.学生，小学生', '3_0_20160520172355_87094_c-manual-scale.jpg', 'd_24_16051_0_4_20150808231052.png', 'The pupils are walking to school.', '小学生们走路去学校。', 'cctkqfjpw5gbjybypjgjmph9chzbuhr6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (599, 'put off', '/pʊt ɔːf/', 'put off.mp3', 'phr.推迟', 'c_i_19316_16_0_3_150723182705-gigapixel-scale.jpg', '', 'The sports meeting will be put off because of the rain.', '因为下雨，运动会将会推迟。', 'c_sa_19316_16_0_5_150810171919.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (600, 'put on', '/pʊt ɑːn/', 'put on.mp3', 'phr.穿，戴上；上演', 'c_i_wm_20120908_03_10_15_572.jpg', '', 'It is difficult for a bear to put on clothes.', '熊熊穿衣服很困难。', 'd59a6307fd726d0f_1266763526610398126_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (601, 'qualify', '/ˈkwɑːlɪfaɪ/', 'qualify.mp3', 'v.胜任，使具有资格', 'dc34ad1ab335f66106e806fb58fe053e_195406_1623812714.jpg', 'd_107_6694_0_2_20150809020748.png', 'His skills qualify him for his work.', '他的技能让他能够胜任这份工作。', 'sa_1_6694_0_3_20150808125355.aac', 'quali=quality质量 + fy动词后缀 → 使...有高质量 → qualify胜任，使具有资格', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (602, 'quarantine', '/ˈkwɔːrəntiːn/', 'quarantine.mp3', 'v.隔离；使隔离；  n.检疫期', 'fe8708f5aa2a8fab31583f2a3a1a40af_188448_1527912437.jpeg', '20140905_00_56_53_951_v3.png', 'The zombies have been quarantined in order to keep people safe.', '丧尸已经被隔离以确保人类的安全。', 'd673c7d0b7d05a6f020f8266fc2c8f99_34934_1527912442.mp3', 'quarant检疫 + ine表示抽象名词 → quarantine隔离检查', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (603, 'range', '/reɪndʒ/ ', 'range.mp3', 'n.一系列；射程；  v.排列；排成一排', '2de1b20fd9c18525bbd9c5d60bb7271a_100079_1584684636.jpg', '20130201_16_22_20_237.png', 'People use different facial expressions to show a range of emotions.', '人们用不同的面部表情来展示一系列的情绪。', 'b9f52a7bd51894eedfd9ff384d10d2aa_47988_1584684632.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (604, 'range over', '/reɪndʒ ˈoʊvər/', 'range over.mp3', 'phr.在……范围内', 'e3a19fabb9bb099c696c38f4df3e0774.jpeg', '', 'The lion ranges over 75 square miles hunting for food.', '狮子在75平方英里的范围内寻找食物。', 'a8cb1bbc8c8db31bf6cdd01cf121c7b5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (605, 'receipt', '/rɪˈsiːt/', 'receipt.mp3', 'n.收据，收条；收入；收到', 'i_1_4173_0_3_20150808122457-gigapixel-scale.jpg', 'd_16_4173_0_7_20150808224046.png', 'Check all your receipts when you pay your taxes.', '当你交税时，一定要检查所有收据。', '1d1132a14d9998d19ce8902e315a5516_16503_1629084981.mp3', 're一再，重新 + ceipt收 → receipt收据', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (606, 'reinforce', '/ˌriːɪnˈfɔːrs/', 'reinforce.mp3', 'v.加强；加固；支持', '45c6bb2302437681d0b3050c97ba8ad6_100186_1565707170.jpg', 'd_107_4122_0_2_20150809004516.png', 'We reinforced the structure of the building with steel rods.', '我们用钢筋加固了这栋建筑的结构。', 'sa_102_4122_0_3_20150809041151.aac', 're再次 + in加强 + force强大，力量 → 再次增加力量 → reinforce加强，巩固', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (607, 'request for', '/rɪˈkwest fɔːr/', 'request for.mp3', 'phr.为 ... 请求', '40f6cc16d6f25340efa3d150c5ff7f7e.jpeg', '', 'His father agreed to his request for a Superman costume. ', '他父亲同意了他想要一套超人服装的请求。', 'a57618b84f35b638fa8e8b0d36e4e737.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (608, 'resist', '/rɪˈzɪst/', 'resist.mp3', 'v.抵抗，抵制', '65c06c2c611e5e2ac32fb22d2708c4f8_147454_1535008897.jpeg', 'd_16_5696_0_2_20150808225714.png', 'The girl on a diet managed to resist the temptation of hamburgers.', '这个正在节食的女孩抵制住了汉堡包的诱惑。', 'd6a8021959f70745_1266883370835159948_250207.mp3', 're向后，相反 + sist站 → 反着站 → resist反抗，抵抗', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (609, 'resume', '/ˈrezjumeɪ/', 'resume.mp3', 'n.简历（读作/ˈrɛzəˌmeɪ/）；  v.继续说；继续进行', 'f5e3a46f9ce0351c9864c71035819be9_194374_1564727156.jpg', 'd_1_5253_0_3_20150808123714.png', 'The HR team are examining the resumes of the interviewees.', '人力资源团队正在审核应聘者的简历。', 'fe2cf3c81f9360a6_1266883007093582678_250207.mp3', 're再次 + sume拿走，取走 → resume继续进行', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (610, 'ring up', '/rɪŋ ʌp/', 'ring up.mp3', 'phr.打电话给', '3_0_20160528173751_43527_c.jpg', '', 'He rang up his friend on his cellphone.', '他用手机给朋友打了个电话。', '3_0_20160528173751_45697_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (611, 'ripe for', '/raɪp fɔr/', 'ripe for.mp3', 'phr.时机成熟，准备就绪', '834326dbb29e5ac0a28d2f8cce4fddd5.jpeg', '', 'This piece of land is ripe for industrial development.', '这块土地已经为发展工业做好了准备。', 'a590c780dd55f6eb056e74d9d4ebbdbc.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (612, 'Roman', '/ˈroʊmən/', 'Roman.mp3', 'adj.罗马的，罗马文字的，罗马人的；  n.罗马天主教的', 'c9fc93c48e8da4af53524ea6f23aa484_158347_1552535104.jpeg', 'd_103_5048_0_3_20150809012420.png', 'This is a Roman historical relic that is still standing in Rome.', '这处古罗马遗迹依然伫立于罗马。', '2a230bb1a0e3e68b650d7173d4b5a34a_32501_1552535095.mp3', 'Rom=Rome罗马 + an属于……的 → Roman罗马的，罗马人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (613, 'sailor', '/ˈseɪlər/', 'sailor.mp3', 'n.水手，海员', 'i_1_8525_0_7_151223142553-gigapixel-scale.jpg', 'd_105_8525_0_2_20150809061021.png', 'The sailor has been out to sea for several months.', '水手已经出海几个月了。', '9ec772dc73ecb69a_1266883636772756212_250207.mp3', 'sail航行 + or名词后缀，表示人 → sailor水手，海员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (614, 'secretary', '/ˈsekrəteri/', 'secretary.mp3', 'n.秘书；部长，大臣', 'f737c9db65a4da3fe21014e59b16be37_182064_1583459563.jpeg', '', 'The secretary takes phone calls', '这个秘书负责接听电话、安排会议和处理一般性事务。', 'j7xu8epwuyrxeg4xbrafchu4d7khlwdh.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (615, 'selective', '/sɪˈlektɪv/', 'selective.mp3', 'adj. 精挑细选的', 'ba44de3d4543958e95f2644934126f99_81370_1572079118.jpeg', '', 'She is very selective about the pearls used to make necklaces.', '她对用于制作项链的珍珠很挑剔。', '330f66bfaae2687c39a74c837b06bbfc_48416_1572338711.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (616, 'serious', '/ˈsɪriəs/', 'serious.mp3', 'adj.认真的，严肃的', '0cdab79cc62622353b7fd32406a17e67_101276_1538624680.jpg', 'd_37_14135_0_4_20150809012139.png', 'He is always very serious while working.', '他工作时总是很认真。', '16341222fa4c1dec_1266763523538442832_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (617, 'sew', '/soʊ/', 'sew.mp3', 'v.缝，缝纫；缝补', 'i_16_6762_0_6_151222191721-gigapixel-scale.jpg', 'd_16_6762_0_4_20150808231039.png', 'She uses the machine to sew a new dress.', '她用机器缝制一条新裙子。', 'sa_16_6762_0_6_151225162959.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (618, 'share', '/ʃer/', 'share.mp3', 'v.分享，共享；分配，均分；  n.一份，份额', '2f7001dca6d48547ec3f68431445cd46_87471_1565342562.jpg', '20130130_16_13_28_663.png', 'Would you like to share some ice cream with me?', '你想和我一起分享冰激凌吗？', 'd57h3s7utpswr7wn24srlakdmuhu5bp2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (619, 'shower', '/ˈʃaʊər/', 'shower.mp3', 'n.淋浴，淋浴器；阵雨；  v.淋浴，淋湿', 'fd830140c3cdda69412091db1300ffd7_97341_1535599269.jpeg', 'd_101_14170_0_4_20150809040320.png', 'The cat is happy to take a shower.', '小猫在快乐地洗淋浴。', '57hqmt9fnvla27h2j8a3966rqvzubnsa.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (620, 'situation', '/ˌsɪtʃuˈeɪʃn/', 'situation.mp3', 'n.形势，局面', '9e5173d566f1b62eb4990cba42291dea_180508_1611043404.jpg', 'd_24_18575_0_4_20150808235450.png', 'It\'s hard to choose which way to go in this situation.', '这种情形下很难选择该走哪条路。', '83f9c1a93a644b01_1266883326193326810_250207.mp3', 'situat位于 + ion名词后缀 → situation地理位置', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (621, 'somehow', '/ˈsʌmhaʊ/', 'somehow.mp3', 'adv.出于某种原因，不知怎么地', 'f78a06d07dba9b09d69158c047f3a859_191680_1569654251.jpeg', '20130316_19_07_19_223.png', 'He looked different somehow.', '不知怎么的，他看上去变了。', '94044a2f707b8a92_1266883487966538636_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (622, 'sometimes', '/ˈsʌmtaɪmz/', 'sometimes.mp3', 'adv.有时，间或', 'i_1_19656_0_2_20150808132713-gigapixel-scale.jpg', 'd_24_19656_0_4_20150809002414.png', 'Sometimes', '有的时候，天气每天都在变。', '0a66c7698aa8f7d0_1266763449073839080_250117.mp3', 'sometime某一时间的 ＋ s表副词 → 某一时间 → sometimes有时', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (623, 'speed', '/spiːd/', 'speed.mp3', 'n.速度，速率；  v.加速', 'e6dae6427fa7336e3c470f60b17191a6_188170_1534820816.jpeg', '20141010_21_59_53_370_v3.png', 'The train is traveling at a speed of 300 km/h.', '列车的运行速度是每小时300千米。', '70b4b671698747d0_1266763243856767966_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (624, 'spoon', '/spuːn/', 'spoon.mp3', 'n.匙，勺子，调羹；  v.用匙舀', '702ad25593f1f141c51399746ab13151_98675_1577956845.jpeg', '20141012_21_55_39_535_v3.png', 'There is a wooden spoon in the bowl.', '碗里有一只木勺子。', 'be4d30dfa03d4891e81006f52673db0a_30910_1577956842.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (625, 'steel', '/stiːl/', 'steel.mp3', 'n.钢，钢铁；  v.下决心应对（不愉快的事）；  adj.钢的，与钢有关的', 'f50e01445ecd59197a1b927a910671ef_79015_1532156624.jpeg', 'd_24_5122_0_4_20150808223931.png', 'Steel can be used to reinforce concrete in the construction of buildings.', '在建造房屋时，钢铁可以用于加固混凝土。', 'df4c6a398ca805e5846e8bf033e4445a_35386_1532156630.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (626, 'stove', '/stoʊv/', 'stove.mp3', 'n.炉子，火炉，电炉', 'i_1_8566_0_8_160323161159-gigapixel-scale.jpg', '20140929_01_45_53_450_v3.png', 'Turn off the stove', '快把炉子关掉，不然食物要煮过头了。', 'd8wgdrx5uzwqzs2vlfyvjmwwlawtbeds.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (627, 'suddenly', '/ˈsʌdənli/', 'suddenly.mp3', 'adv.突然地，猛地', 'i_24_14790_0_3_20150808230559-gigapixel-scale.jpg', 'd_24_14790_0_3_20150808230559.png', 'Suddenly', '我的朋友突然从后面给我来了个惊喜。', 'fd5f109f1925f63b_1266797983526923062_250123.mp3', 'sudden突然的 ＋ ly...地 → suddenly突然地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (628, 'surround', '/səˈraʊnd/', 'surround.mp3', 'v.包围；  n.围绕物', '7de521feffa1135f28821e412cc248bd_113394_1750846052.jpg', 'd_16_5743_0_5_20150808225812.png', 'The celebrity is surrounded by a large crowd of his fans.', '这位明星被一大群粉丝围住。', 'us_The_celebrity_20250328150731991_88e6b0ded87809d16225.mp3', 'sur在···上 + round圆的 → surround围绕', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (629, 'swing', '/swɪŋ/', 'swing.mp3', 'v.摇荡，摆动；使摇摆，使转动，使转向；  n.秋千', 'i_1_16075_0_4_20150808132204-gigapixel-scale.jpg', 'd_100_14459_0_4_20150809032650.png', 'He swings in the forest from tree to tree.', '他在丛林的树间荡来荡去。', '5lpdvlvennx7nq4uqmfyr3a3hlc38pmb.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (630, 'sword', '/sɔːrd/', 'sword.mp3', 'n.剑，刀', '257021e443e4b10d8ddd96179516b586_33321_1732247127.jpg', 'd_16_8915_0_4_20150808233516.png', 'He holds the sword and gets ready for battle.', '他握住剑，准备一战！', '6jpqyal4bg3gywqgt7u9db5pjgvepyfe.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (631, 'system', '/ˈsɪstəm/', 'system.mp3', 'n.系统；身体', 'c0185438885e2c47a0f9721564610c8d_97496_1595857200.jpg', 'd_107_15891_0_2_20150809025626.png', 'There are eight planets in our solar system.', '我们的太阳系中有八大行星。', 'da05adfaf8c5a173_1266883198922807886_250207.mp3', 'sy一起 + stem使立住 → system系统', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (632, 'take down', '/\'teik daʊn/', 'take down.mp3', 'phr.记下，写下', 'b5eb17c0e4b9632b95c5c4bc10055a46.jpeg', '', 'She is watching an online class and taking down some notes. ', '她边看网课边记笔记。', 'cc86d26592a11d30de64fbade3e6c20f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (633, 'temper', '/ˈtempər/', 'temper.mp3', 'n.脾气，性情；  v.使缓和', '33045b6bebd576cdf35d5b60228054d0_68257_1715578685.jpg', 'd_1_8406_0_3_20150808130717.png', 'Stuck in traffic for over an hour', '堵车一个多小时了，这个男人开始发火了。', 'dec61bf51b580fc4_1266883635242949330_250207.mp3', 'temper=tempor时间；节制；调节 → 不同的时间不同的心情 → temper脾气；心情；调和', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (634, 'therefore', '/ˈðerfɔːr/', 'therefore.mp3', 'adv.因此，所以', '642f69247f69e132d80d7748fab7910d_93792_1588087047.jpeg', 'd_16_4894_0_2_20150808224539.png', 'People are holding their umbrellas up; therefore', '人们都撑起了雨伞，因此外面肯定在下雨。', '4fec42ff600c2fcbf10565fe1d9dfaa6_30609_1619331598.mp3', 'there这样 + fore因为 → therefore因此', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (635, 'thirsty', '/ˈθɜːrsti/', 'thirsty.mp3', 'adj.口渴的；渴望的', 'ee0ac65ad464e4857309e56f723ac504_227670_1733120309.jpg', '20141013_02_18_15_69_v3.png', 'The girl is so thirsty wandering in the desert.', '女孩在沙漠里漫无目的地走着，渴极了。', '5ca1a3307838945c_1266763311207832118_250117.mp3', 'thirst口渴 + y……的 → thirsty口渴的，渴望的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (636, 'throw up', '/θroʊ ʌp/', 'throw up.mp3', 'phr.呕吐', '1e93c9ee2823e3699aac39604ad58a45_124543.jpg', '', 'The bad food made him throw up.', '变质的食物让他吐了。', '92e7ca60d910f14f3d6d93b035f0ab7a_32171.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (637, 'tissue', '/ˈtɪʃuː/', 'tissue.mp3', 'n.纸巾', 'a8d417cd9506a6365154d5ac7b789c0c_84815_1565343113.jpg', 'd_16_5838_0_2_20150808225926.png', 'The little girl uses a tissue when she sneezes.', '打喷嚏时，小女孩用了一张纸巾。', '109320f455099609d8f5accf2266a2f9_18227_1648606331.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (638, 'to the point', '/tu ðə pɔːɪnt/', 'to the point.mp3', 'phr.切题，扼要', '99eaaaf7fef6be37f75fe74f31bc64bc.jpeg', '', 'The teacher told students that their answers should be short and to the point.', '老师告诉学生他们的答案应该要简短而切题。', '76d088015f5d01297eea50c50449539f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (639, 'tomato', '/təˈmeɪtoʊ/', 'tomato.mp3', 'n.番茄，西红柿', '3d275da5235e83a1ed05c1c3afb1360d_83304_1574826960.jpeg', '20121225_19_13_00_990.png', 'I washed some tomatoes.', '我洗了一些西红柿。', '0e8de4ecefc7da17_1266763405664344688_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (640, 'tone', '/toʊn/', 'tone.mp3', 'n.语气', '127d5bc3134ab7608a85e480cd3eb46c_190096_1585377426.jpeg', 'd_1_11042_0_3_20150808131803.png', 'The little boy learned to use a more polite tone when speaking to his mother.', '这个小男孩学会用更礼貌的语气和母亲说话。', '252b47a8f2dedffc_1266883627457337934_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (641, 'treat', '/triːt/', 'treat.mp3', 'v.治疗；请客，款待；  n.请客', '76e7d44dfcf7c58d2893bffd7c0079fe_93259_1585144144.jpeg', 'd_24_8283_0_4_20150808225548.png', 'The doctor is carefully treating the wound on the little girl\'s leg.', '医生正在仔细治疗小女孩腿上的伤。', 'd32900f4cc625263d44a42afa43dbf88_42996_1585144137.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (642, 'tune in to', '/tun ɪn tu/', 'tune in to.mp3', 'phr.收看', '97635046e0303784772de1e08f3749f7.jpeg', '', 'He tunes in to this show every week.', '他每周都收看这个节目。', 'e220d0910a23684a79e672f90928a6b9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (643, 'turn down', '/tɜrn daʊn/', 'turn down.mp3', 'phr.拒绝做...', '64022353c8b511881ad04487f98200ca_97117_1580887652.jpg', '', 'He turned down the proposal and refused to sign it.', '他拒绝了这个提案，不愿在上面签字。', 'kvjflcs92kp72w439vkrhvzsme6rdrqv.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (644, 'turn to', '/tɜːrn tu/', 'turn to.mp3', 'phr.求助于', '29936_20120814_04_06_38_468.jpg', '', 'When I don\'t know a word', '当我遇到不认识的词时，我就求助于字典。', 'sa_32_19920_0_4_20150808235024.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (645, 'typical', '/ˈtɪpɪkl/', 'typical.mp3', 'adj.典型的，有代表性的', '3_0_20160607175900_12767_c-gigapixel-scale.jpg', 'd_1_5638_0_2_20150808124128.png', 'It\'s typical for many Japanese to eat rice this way.', '这是许多日本人吃米饭的典型方式。', '3ddfdf4e3c2efce4_1266883194976099070_250207.mp3', 'typ类型 + ical…的 → 成模式的 → typical典型的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (646, 'typist', '/ˈtaɪpɪst/', 'typist.mp3', 'n.（尤指专职）打字员', '3_0_20160520172343_62843_c-manual-scale.jpg', 'd_105_10292_0_2_20150809061706.png', 'The typist is finishing her documents.', '打字员正在完成她的文件。', '3_0_20160520172343_83367_c.aac', 'typ=type打字 + ist从事某种职业的人 → typist打字员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (647, 'undertake', '/ˌʌndərˈteɪk/', 'undertake.mp3', 'v.承担，承包', '5f69f846cd4a7a6023f9cb830af9daf5.jpg', 'd_16_4494_0_3_20150808224258.png', 'We encourage men to undertake more childcare responsibilities.', '我们鼓励男性多承担育儿的责任。', 'us_We_encourage_20241126101346199_91ca6b1c737459d7a8b7.mp3', 'under下 + take接受 → undertake从事', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (648, 'united', '/juˈnaɪtɪd/', 'united.mp3', 'adj.团结的，和谐的', 'f0150aa91cd07e8e69a9a9716eb07847_101229_1579335634.jpeg', 'd_105_11055_0_2_20150809061831.png', 'The six of us are united and working on a business plan together.', '我们六人团结一致，一起制定商业计划。', '4923b67a2811360393cd539400a5e454_49198_1579335631.mp3', 'unit单元 + ed形容词后缀 → 统一的，联合的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (649, 'up to date', '/ˌʌp tə ˈdeɪt/', 'up to date.mp3', 'phr.最近的，最新的', '60c3905471ec954de3dbc3e428a71a2e_191546_1590219037.jpeg', '', 'Newspapers keep people up to date with the latest news.', '报纸让人们了解到最近的新闻。', '8dc38f4c7aea5995b09f1b968149eacd_19951_1590219052.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (650, 'vary in', '/ˈveri ɪn/', 'vary in.mp3', 'phr.在...方面不同', '810a21386f8046ec5a1dfb9b562cd301.jpeg', '', 'These T-shirts vary in color.', '这些T恤颜色各异。', '55b921e433dff03b4e8292a06cbbcf7c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (651, 'version', '/ˈvɜːrʒn/', 'version.mp3', 'n.版本；说法', 'c009f0b52bf50d1445ecdc4d1425bc84.jpg', 'd_107_10107_0_2_20150809024916.png', 'This book has many different versions.', '这本书有很多不同的版本。', 's2atw3kwjlz65eez9c4kubmcghx6vldr.mp3', 'vers转 + ion表名词 → 把原文转换成另一版本 → version翻译，译文', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (652, 'village', '/ˈvɪlɪdʒ/', 'village.mp3', 'n.村庄，乡村', 'f28a9e7ea03d6fa69ee30bf7ecd5cf56_184236_1574766412.jpeg', '20121225_19_02_58_799.png', 'I lived in a remote mountain village.', '我住在一个遥远的小山村里。', '94aa652fb24b3f56_1266763554823973886_250117.mp3', 'vill=villa茅房，别墅 + age场所，物品 → village村庄', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (653, 'volt', '/voʊlt/ ', 'volt.mp3', 'n.伏特（电压单位）', 'f2ed6049bdd4a581d11a3629065ea9df_61780_1565331154.jpg', 'd_103_2945_0_3_20150809002747.png', 'The cable has 220 volts of electricity.', '这根电线有220伏的电。', '8138e53ab2d9c57a_1266883481926020068_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (654, 'wealth', '/welθ/', 'wealth.mp3', 'n.财富，财产；大量', '13f30a66e96362d82e98d1cea2dc155f_193692_1739003151.jpeg', 'd_24_5124_0_3_20150808223933.png', 'He is a man of great wealth.', '他是一个拥有大量财富的人。', 'us_He_is_20220905162121486_74195c2f8439f78518ec.mp3', 'weal幸福 + th抽象名词后缀 → wealth财富', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (655, 'wealthy', '/ˈwelθi/', 'wealthy.mp3', 'adj.富有的；充分的；  n.富人', '3_0_20170709071607_10117_c-gigapixel-scale.jpg', 'd_16_9279_0_2_20150808234159.png', 'I\'m so wealthy that I bathe in money.', '我太有钱了，我在钱里沐浴。', '3_0_20170709071607_4696_c.aac', 'wealth财富 + y……的 → 富裕的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (656, 'website', '/ˈwebsaɪt/', 'website.mp3', 'n.网站', '3_0_20170608071932_99180_c-gigapixel-scale.jpg', 'd_94_14730_0_4_20150809010351.png', 'The man has many websites open on his laptop.', '他在笔记本电脑上点开了许多网站。', 'rfbr53yd56swdmryltk5vxf27fwlwfrg.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (657, 'wine', '/waɪn/', 'wine.mp3', 'n.葡萄酒', 'c63094d7e5166647df0aa709d759d251_93046_1577959620.jpeg', 'd_24_17622_0_4_20150808233043.png', 'Red wine is made from high quality grapes.', '红葡萄酒是用优质葡萄酿制的。', '5641cce1e196a893_1266763403736668732_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (658, 'wolf', '/wʊlf/', 'wolf.mp3', 'n.狼（复数wolves）；残忍凶狠的人；  v.狼吞虎咽地吃', '32e84284f01c08a5598c7a0e601b865f_42976_1565694283.jpg', '20121225_18_39_32_632.png', 'Even though a wolf looks a bit like a dog', '尽管狼看起来有点儿像狗，但其实它们要危险得多。', 'tgaj7crgf79f268jcybzzfrwa7chdg4c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (659, 'absent', '/ˈæbsənt/', 'absent.mp3', 'adj.缺席的，不在场的', 'c8e4d01ce555f889624f951d7eda789f_522920_1700618748.jpg', 'd_24_7260_0_4_20150808225052.png', 'What a surprise! The best student is absent from school!', '震惊！学霸今天没来学校！', '6rxysgruw2qlnv4kvnvuztyc23kk6zc4.mp3', 'ab远离的 + sent出现 → 没有出现 → absent缺席的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (660, 'across', '/əˈkrɔːs/', 'across.mp3', 'prep.越过，横跨；  adv.横过', '20120429_04_19_11_679-gigapixel-scale.jpg', 'd_24_17611_0_4_20150808233024.png', 'She got across the stream by walking on the rocks.', '她踩在石头上穿过了小溪。', 'srq3sgmhltebdkwrd8aefr3vx5rrecvg.mp3', 'a加强 + cross交叉 → across越过，横跨', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (661, 'advertise', '/ˈædvərtaɪz/', 'advertise.mp3', 'v.为……做广告；公告；公布', '996836b5d5217e3dadd08c54400227a4_143079_1619315495.jpeg', '20141014_11_56_49_66_v3.png', 'The technology company advertises its latest phones on electronic billboards.', '这家科技公司在电子广告牌上为他们最新款的手机做广告。', '718eb9d140c27c9a5639caa4d98b2e62_45418_1563163349.mp3', 'ad再 + vert转变 + ise使…… → 转变客户想法 → advertise为……做广告', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (662, 'afraid', '/əˈfreɪd/', 'afraid.mp3', 'adj.害怕的，畏惧的', 'bed2b37fe5ab9c77c06d29466aae1f8b_109381_1541846643.jpg', 'd_24_15983_0_4_20150808230937.png', 'The dog looks afraid of the man.', '这只狗看上去害怕这个男人。', '9b6414b44cf3ff50_1266883379060431370_250207.mp3', 'af走出，在...之外 + raid友善，爱 → 远离好的情绪 → afraid害怕的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (663, 'agree', '/əˈɡriː/', 'agree.mp3', 'v. 同意，赞成', '42a3906dfe174554ad0ce7f01064eb17_83659_1595472048.jpeg', '20141010_21_50_46_477_v3.png', 'She agreed to go shopping with her friend.', '她同意和朋友一起去购物。', 'sljdfw8xvd5arwucapu4tq7xs6mgg4cc.mp3', 'a=ad去 + gree支持，欢迎 → agree同意', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (664, 'ahead of time', '/əˈhed əv taɪm/', 'ahead of time.mp3', 'phr.提前', 'f966e50ee88efb8b355cd95866eef46e.jpeg', '', 'He arrived at his friend\'s house 20 minutes ahead of time.', '他提前20分钟到达朋友家。', '02915613b84c695012c6d34b0467c25d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (665, 'airplane', '/ˈerpleɪn/', 'airplane.mp3', 'n.飞机', 'i_1_2733_0_4_150923101055-gigapixel-scale.jpg', 'd_24_2733_0_3_20150808223303.png', 'You can go through the clouds by taking airplanes. It feels so amazing!', '坐飞机可以穿过云层，那感觉太神奇了！', 'sa_1_2733_0_4_151017092958.aac', 'air空气 + plane飞机 → airplane飞机', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (666, 'all over again', '/ɔːl ˈoʊvər əˈɡen/', 'all over again.mp3', 'phr.重新', 'e5c9f95bf4612742bea00a24f120d89b.jpeg', '', 'His boss told him to do the report all over again.', '老板让他把报告重新做一遍。', 'x7dums83zert7mv6hqnfpe78cj8ahv47.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (667, 'ambition', '/æmˈbɪʃn/', 'ambition.mp3', 'n.雄心，野心', 'i_4_9010_0_4_160104144145-gigapixel-scale.jpg', 'd_50_9010_0_3_20150809015638.png', 'This powerful man\'s political ambition was to unify the three kingdoms.', '这个有权势的男人的政治野心是一统三国。', 'sa_1_9010_0_4_160109110758.aac', 'amb大 + it行走 + ion名词后缀 → 走大步 → ambition雄心，志向', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (668, 'announce', '/əˈnaʊns/', 'announce.mp3', 'v.宣布，通知', '0a44bd0d3b377fe38e442159c426dfe3_137674_1740635637.jpeg', 'd_16_6631_0_2_20150808230845.png', 'Her album was announced as the winner.', '她的专辑被宣布为获奖作品。', 'us_Her_album_20250227154005564_afa4d216bdc921413ab8.mp3', 'an加强意义 + nounce通知 → announce通告', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (669, 'annoy', '/əˈnɔɪ/', 'annoy.mp3', 'v.使烦恼，使生气', '8a00f576412381a1ab7b3b97abe594c3_147724_1731906133.jpg', 'd_24_6572_0_4_20150808224647.png', 'Talking on your phone during a movie is likely to annoy others.', '在看电影的时候打电话很可能会惹怒其他人。', '4dbdcc9c334111df9eedb07ec86baf72_53459_1533028630.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (670, 'around', '/əˈraʊnd/', 'around.mp3', 'prep.在……周围，围绕；  adv.大约，四处', 'e255f52114650a1e7916bd60175d0742_101292_1595929089.jpg', 'd_24_17900_0_4_20150808233355.png', 'They sit around the teacher.', '他们围坐在老师身边。', 'dt6rjdvwepx3ubf8v2capdtbqqaaxdhf.mp3', 'a古英语前缀 + round圆圈 → around大约，四处', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (671, 'artist', '/ˈɑːrtɪst/', 'artist.mp3', 'n.艺术家，画家', '72b4fa10deb7737054a0701c8f0db7bb_197900_1534819922.jpeg', 'd_24_7584_0_3_20150808225128.png', 'The artist is spraying colors on the wall.', '这个艺术家在朝墙上喷涂颜料。', '102100ed93bd2088_1266883006005095228_250207.mp3', 'art艺术 + ist表示从事某种职业的人 → artist艺术家，画家', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (672, 'as a result', '/æz ə rɪˈzʌlt/', 'as a result.mp3', 'phr.所以，结果是', '0017b87c8a42956cdaa2dbce22438e76_99395_1601369477.jpg', '', 'I eat too much fast food', '我吃太多快餐，结果变得很胖。', 'us_I_eat_20250206125108872_f809e8728d8dfdcca7f3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (673, 'ask for', '/æsk fɔr/', 'ask for.mp3', 'phr.询问', '23c9c7886eeb086af0c42c0eb253fd10.jpg', '', 'The tourist is asking the woman for directions.', '游客正在向那位女士问路。', '4wraslfjfuhrwyy799uxt3cuq9aceuwl.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (674, 'attention to', '/əˈtenʃn tuː/', 'attention to.mp3', 'phr.对 ... 的注意', 'da5c446bb8eb4c8a983a0617b28908b7.jpeg', '', 'The teacher told him to pay attention to his spelling.', '老师提醒他注意自己的拼写。', '824f68d84bee42d7a3d150d480b3421a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (675, 'barrier', '/ˈbæriər/', 'barrier.mp3', 'n.障碍；屏障，障碍物；隔阂', 'i_1_9256_0_3_20150808131329-gigapixel-scale.jpg', 'd_16_9256_0_2_20150808234121.png', 'There is a barrier on the road so we can\'t go this way.', '路上有障碍物，所以我们不能走这条路。', 'ee450740a4e7a8582a01fdceeb6bba00_18384_1624011127.mp3', 'barr棒，阻拦 + ier名词后缀，表示物 → barrier栅栏', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (676, 'be acquainted with', '/bi əˈkwentɪd wɪð/', 'be acquainted with.mp3', 'phr.熟悉', 'c17d91aea407ff58c74e8d2b72354cb1.jpg', '', 'He is already well acquainted with British culture.', '他已经熟知英国文化。', '8e008d50ed6e069005496f6c8af79e87.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (677, 'be concerned with', '/bi kənˈsənd wɪð/', 'be concerned with.mp3', 'phr.与……有关', 'd51714cc483f4cb28bf485db0381376e.jpg', '', 'The second chapter is concerned with the health of the elderly.', '第二章所涉及的是老年人的健康问题。', '524f2711856ef0c01376477e1488cfd7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (678, 'bear', '/ber/', 'bear.mp3', 'n.熊；（股市）看跌的人；  v.忍受，容忍；生育；带有', 'i_1_5603_0_4_151019143147-gigapixel-scale.jpg', 'd_24_5603_0_3_20150808224221.png', 'Look! The bear is eating honey.', '看！那只熊在吃蜂蜜。', 'svebn4tmhatj4relwcvp2mfgsvrd5vta.mp3', ' ', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (679, 'biology', '/baɪ\'ɑlədʒɪ/', 'biology.mp3', 'n.生物学', 'i_16_5195_0_4_151222171111-gigapixel-scale.jpg', '20130111_18_57_00_829.png', 'Biology is the study of life and living things.', '生物学是研究生命和生物的学科。', 'sa_16_5195_0_4_151225144640.aac', 'bio生物 + logy……学 → biology生物学', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (680, 'bite', '/baɪt/', 'bite.mp3', 'v. 咬，叮，蜇', '40873a0e39e82b36bdf5bba98327d773_95736_1644315973.jpg', 'd_16_6981_0_2_20150808231342.png', 'The little dog is biting its toy.', '这只小狗正在咬它的玩具。', 'gz25ubt88s6vpsv43ehbfangg7756y3e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (681, 'bond', '/bɑːnd/', 'bond.mp3', 'n.凝聚力；束缚物，联结物；  v.团结一致', 'i_1_3970_0_3_20150808122151-gigapixel-scale.jpg', 'd_16_3970_0_7_20150808223912.png', 'Family members have a strong bond. You can never tear them apart.', '家庭成员之间有着强大的凝聚力，你永远也不能拆散他们。', 'sa_1_3970_0_3_20150808122151.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (682, 'bound to', '/baʊnd tu/', 'bound to.mp3', 'phr.一定会，必然', '2f216a6f860527e984b735c653a3c4e3.jpeg', '', 'He\'s bound to hurt himself if there\'s no protection for him.', '如果没有保护，他一定会伤到自己。', '895b9a6f9f0ab67b7a0dfdf148aeb382.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (683, 'bright', '/braɪt/', 'bright.mp3', 'adj.明亮的，光线充足的', 'f6fabadf53be5da41445d01ba4cfe771_79697_1587691538.jpeg', 'd_24_15985_0_4_20150808230941.png', 'He opened the window and the room became bright.', '他打开窗户，房间就变得明亮起来了。', 'e4hxk3h9wqjz8j5fp63r9b67b56h967p.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (684, 'broom', '/bruːm/', 'broom.mp3', 'n.扫把，扫帚；金雀花', '5bb5c598bd2689b7dd52114fe5e3b3be_86023_1565321993.jpg', 'd_24_8298_0_4_20150808225557.png', 'One of my duties is to sweep the floor with a broom.', '我的任务之一是用扫帚扫地。', '4ged7rgdy3j69qcreuh3trsf9up7chj4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (685, 'bureau', '/ˈbjʊroʊ/', 'bureau.mp3', 'n.局，司，处，社，所', 'b563f7f69bce40dd9c551c94e5e9f4f8_187846_1561953026.jpg', 'd_1_6661_0_3_20150808125324.png', 'The Federal Bureau of Investigation is a government agency in the United States investigating crimes.', '联邦调查局是美国调查犯罪的政府机构。', '4d90d2aed96ef827fb3d3ce615844824_47642_1561953025.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (686, 'calculate', '/ˈkælkjuleɪt/', 'calculate.mp3', 'v.计算', '1423913358855-gigapixel-scale.jpg', '20140927_01_35_18_972_v3.png', 'Let\'s calculate the final amount.', '让我们计算一下最终的金额。', 'sa_1_6155_0_4_20150808124738.aac', 'calc石头 + ul + ate表动词 → 用小石头计数 → 计算', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (687, 'cannot', '/ˈkænɑːt/', 'cannot.mp3', 'aux.不能，不可以', 'b84738d691fa33e61ebaf4480c9a2ee4_95885_1589791799.jpeg', '', 'The boy can lift them', '这个男孩能举起它们，但他的朋友不能。', 'aab7320678f3be706ff573ed372ba7a4_17443_1589791818.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (688, 'capable of', '/ˈkeɪpəbl əv/', 'capable of.mp3', 'phr.有…能力的，可以…的', '5d341e16923df9f2eaa5d276490ccda3.jpeg', '', 'The baby is already capable of feeding himself.', '宝宝已经能够自己吃饭了。', '59b5b7e7c82c9039d3e166486e04c7d1.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (689, 'card', '/kɑːrd/', 'card.mp3', 'n.卡，卡片，贺卡，名片', 'bfd9923bb94f65bbedc345e270c26985_62034_1575287711.jpg', '20130301_10_58_05_725.png', 'Here is my card. It has my phone number and email on it.', '这是我的名片，上面有我的电话号码和邮箱地址。', 'kanj3klm9n4qw3f3umrlkulp8k8arx42.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (690, 'care for', '/kɛr fɔr/', 'care for.mp3', 'phr.照料（看）', '3bb997b2646721296077fc15037fccca_145294_1556346259.jpeg', '', 'The mother cared for her daughter when she was sick.', '妈妈在女儿生病的时候照顾她。', '7h9jlqz6xz3gfdkymkwxwgbvh8b8g8xh.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (691, 'cease', '/siːs/', 'cease.mp3', 'v.停止，结束；  n.停止，停息', 'i_1_4077_0_3_20150808122316-manual-scale.jpg', 'd_1_4077_0_3_20150808122316.png', 'The rain ceased and the rainbow showed up.', '雨停了，彩虹出现在天边。', '93zd6q3lzpg6akbp87cyqsb8z4emvyqd.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (692, 'center', '/ˈsentər/', 'center.mp3', 'n.中央，中心；  v.集中', 'i_1_10590_0_2_20150808131716-gigapixel-scale.jpg', 'd_24_10590_0_4_20150808230443.png', 'You\'ll get lots of points if you hit the center of the target.', '如果击中目标的中心，你会得很高的分数。', 'a3f92410d7c56718a3dc43380128ab42_18697_1640244568.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (693, 'centigrade', '/ˈsentɪɡreɪd/', 'centigrade.mp3', 'n.摄氏度；  adj.摄氏度的', 'c_i_wm_1425954323839-gigapixel-scale.jpg', 'd_105_10295_0_2_20150809061709.png', 'Flowers would be nicely treated at 25 degrees centigrade.', '25摄氏度对花朵（的生长）有益。', 'fm4dfhpqejcg5awnuux34n67e7kp2rdn.mp3', 'centi百 + grade级，度 → 百分度的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (694, 'choice', '/tʃɔɪs/', 'choice.mp3', 'n.选择，挑选，抉择', '21cc6a8efefcc27b7c7a547eb5fc9498_38155_1575286656.jpeg', '20130105_10_23_20_768.png', 'It\'s hard for him to make a choice between new shoes and a new game console.', '对他来说，在新鞋和新游戏机中做选择非常困难。', '27ba4208ff9f249a98cb537402a286df_47398_1575286654.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (695, 'collection', '/kəˈlekʃən/', 'collection.mp3', 'n.收藏，收藏品', '0ec6f18aaf14aecdc5a150067dec2478_123212_1736837715.jpg', 'd_16_16050_0_2_20150809001621.png', 'I own a very valuable collection of guitars.', '我拥有一些很有价值的吉他珍藏。', '5db05f3a00e097d5_1266798143816358610_250123.mp3', 'collect收集 + ion名词后缀 → collection采集，收藏', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (696, 'college', '/ˈkɑːlɪdʒ/', 'college.mp3', 'n.大学', '64795b5b01365aef97756d6c97edb963_80864_1587794807.jpeg', 'd_24_8118_0_4_20150808225512.png', 'After high school the boy went to study at college.', '高中毕业后，这个男孩进入了大学学习。', '408d707b1b862b4ebccc11f926b89b46_17600_1640244665.mp3', 'col=com一起，与 + leg选择，收集 + e → 一起做研究工作的师生 → college大学', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (697, 'come by', '/kʌm baɪ/', 'come by.mp3', 'phr.得到', '1ed25f6b863b7a9497acd585688afead.jpg', '', 'Although the book had been hard to come by', '尽管这本书很难得到，她最终还是找到了一本！', '7f71ec765ede14f6451c76280b32e820.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (698, 'compete', '/kəmˈpiːt/ ', 'compete.mp3', 'v.竞争', '298bf46db2fd913672d6361c521b3e95_78937_1565680434.jpg', 'd_107_6330_0_2_20150809015633.png', 'We compete against each other to see who\'s the fastest rider.', '我们相互竞争，想看看谁才是最快的骑手。', '9f1edc8d0df37bed_1266763401055677430_250117.mp3', 'com共同 + pete追求 → 一起追 → compete比赛', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (699, 'complicated', '/ˈkɑːmplɪkeɪtɪd/', 'complicated.mp3', 'adj.复杂的；难解的', 'c_i_wm_20120515_03_54_03_889-gigapixel-scale.jpg', 'd_107_5761_0_2_20150809013804.png', 'Math is a very complicated subject—it makes my head hurt.', '数学是一门非常复杂的学科，它让我很头疼。', 'sa_1_5761_0_4_20150808124345.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (700, 'considerate', '/kənˈsɪdərət/', 'considerate.mp3', 'adj.体贴的，考虑周到的', 'i_1_7040_0_4_150914113912-gigapixel-scale.jpg', 'd_16_7040_0_7_20150808231426.png', 'As a considerate boyfriend', '作为一个体贴的男朋友，他在她生病时无微不至地照顾她。', 'sa_1_7040_0_4_150923163620.aac', 'consider仔细思考，考虑 + ate...的 → 考虑周到的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (701, 'continuous', '/kənˈtɪnjuəs/', 'continuous.mp3', 'adj.连续的', 'a42a83e03b63d57c9e23a324252bd621_164691_1541578033.jpeg', 'd_1_6161_0_2_20150808124744.png', 'There will be three days of continuous snow.', '接下来连续三天都会下雪。', '8efe0d61df9710ad_1266883008246209156_250207.mp3', 'continu(e)持续 + ous形容词后缀 → continuous持续不断的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (702, 'contradict', '/ˌkɑːntrəˈdɪkt/', 'contradict.mp3', 'v.与……发生矛盾，与……抵触，与……对立', 'cc9264e4430c53e5aa635334c0ae7ad1_49252_1566978259.jpg', '7491d54eeae412318956dc99f8b85677_64726_1551252441.png', 'The signs contradict each other. Which way should we go?', '这些标志互相矛盾。我们应该走哪条路呢？', '3fd465a77f17dac4ad13f6ebc6af3b35_22302_1648606856.mp3', 'contra反对，相反 + dict说 → 反着说 → contradict反驳', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (703, 'contribute', '/kənˈtrɪbjuːt/', 'contribute.mp3', 'v.贡献', '138fde3f70703af76ff92160f70a73a4_100243_1656647469.jpg', 'd_107_3971_0_2_20150809003757.png', 'Many people contribute money to help people in need.', '很多人捐钱来帮助有需要的人们。', 'sa_1_3971_0_4_151017100648.aac', 'con共同 + tribute给予 → 全部给出 → contribute捐献，贡献', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (704, 'cupboard', '/ˈkʌbərd/', 'cupboard.mp3', 'n.碗橱，衣柜', 'i_24_4176_0_5_151224155051-gigapixel-scale.jpg', 'd_24_4176_0_3_20150808223451.png', 'She is taking out a bowl from the cupboard.', '她正从橱柜里拿出一个碗。', '54103de71abb2e54_1266763314758527926_250117.mp3', 'cup杯子 + board板子 → 放杯子的板子 → cupboard碗柜', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (705, 'curve', ' /kɜːrv/', 'curve.mp3', 'v.使弯曲；  n.曲线', '68882264fa501391cc31ac90b4df09b3_193517_1679289828.jpg', '20130520_01_00_12_604.png', 'Her lips curved in a smile.', '她咧嘴笑了。', 'us_Her_lips_20230320132324320_479584a8b4767d4f208f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (706, 'dare', '/der/', 'dare.mp3', 'v.敢于；  n.激将', '3_0_20170708102757_12535_c-manual-scale.jpg', 'd_24_17742_0_4_20150808233348.png', 'He dares to walk along the tightrope!', '他竟然敢走钢丝！', 'fd16e3b0be819078_1266883488330001308_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (707, 'demonstrate', '/ˈdemənstreɪt/', 'demonstrate.mp3', 'v.演示，展示；（用实例、实验）论证；示范；示威', '65d9bec0972701a92acccea36a9927a4_229595_1583392825.jpg', '', 'The salesman demonstrates how the device works on a watermelon.', '推销员在演示怎么操作切瓜神器。', '3f26b6d90a41b859865e0539393f0b2a_50588_1533104812.mp3', 'de加强 + monstr指出 + ate动词后缀 → 特别指出 → demonstrate证明', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (708, 'dependent', '/dɪˈpendənt/ ', 'dependent.mp3', 'adj.依赖的；取决于……的；  n.依赖他人者', 'e50108484efab3802e0c8acb7486ff39_98187_1565343480.jpg', 'd_1_5127_0_2_20150808123534.png', 'Ever since the accident', '那场车祸后，她的行动就一直依赖她儿子。', '72ab842673d8e86614304969e9a18e1f_28571_1559633874.mp3', 'depend依靠 + ent形容词后缀 → dependent依靠的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (709, 'disaster', '/dɪˈzæstər/', 'disaster.mp3', 'n.灾难，天灾', '3_0_20160528171854_12545_c-gigapixel-scale.jpg', 'd_24_7996_0_4_20150808225327.png', 'The unexpected disaster destroyed the whole city.', '这场意料不到的灾难摧毁了整座城市。', 'kzapfunyedundb7zqryw5wx33bf794mh.mp3', 'dis不 ＋ aster星 → 星位不正，表示有灾难 → disaster灾难，灾祸', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (710, 'echo', '/ˈekəʊ/', 'echo.mp3', 'n.回声；  v.重复', '72e323b5eaba8d22a2b339af0bd7c466_68672_1585125116.jpeg', 'd_13_14974_0_2_20150808203213.png', 'If you shout in this valley', '如果你在这个山谷里大喊，你就会听见回声。', 'f26ae046cac21d4c_1266883377837943752_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (711, 'elder', '/ˈeldər/', 'elder.mp3', 'n.长辈；  adj.年长的，年龄较大的', '62c172f8fe9ba69ac7fdeec01c4342da_194356_1578559827.jpeg', 'd_24_15986_0_4_20150808230942.png', 'The elders sat together and lovingly watched the child play.', '长辈们坐在一起，慈爱地看着孩子玩耍。', '25c3370d7f8166b0ffa770227f4944e8_46318_1578559824.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (712, 'electric', '/ɪˈlektrɪk/', 'electric.mp3', 'adj.电的，带电的', '3_0_20170928071224_42985_c-gigapixel-scale.jpg', 'd_24_17914_0_4_20150808233443.png', 'Don\'t touch these electric wires. It\'s dangerous.', '不要碰这些电线，这很危险。', 'cba65a9b04f98a72437b514601e15001_21362_1611631544.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (713, 'entirely', '/ɪnˈtaɪərli/', 'entirely.mp3', 'adv.全部地', '00203a0374a35a951341a127be428fad_123983_1588081595.jpeg', '', 'The audience consists entirely of children.', '观众全部都是小孩子。', '33865e42f6f073feea195468109ee85e_45838_1588081602.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (714, 'equivalent to', '/ɪˈkwɪvələnt tu/', 'equivalent to.mp3', 'phr.等于，相当于', '21548c47f0c10b6cab41d19d4508dcab.jpeg', '', 'They agreed that the value of three carrots was equivalent to that of five nuts. ', '他们同意三根胡萝卜的价值等同于五颗坚果的价值。', 'a85e108518ac55098b0905e00b36a119_34565_1621931515.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (715, 'eventually', '/ɪˈventʃuəli/', 'eventually.mp3', 'adv.终于，最后', 'b248525f7d467082353ee8b3bac95a37_192614_1604912673.jpg', '', 'After weeks of hard study', '经过几周的刻苦学习，他终于得到了令人满意的结果。', 'bgudw6ns5sqdkkmxbblup3vee7v8u8sy.mp3', 'eventual最后的 + ly 表示方式、程度、状态、“...地” → adv.终于；最后', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (716, 'few', '/fjuː/', 'few.mp3', 'adj.很少的，几乎没有的', '210f0232424e1d60c73700f2bfc817e2.jpeg', 'd_24_18899_0_4_20150808235939.png', 'There are very few people on the subway. ', '地铁上几乎没什么人。', 'us_There_are_20230105171506096_1829fd88c91e5e0019e6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (717, 'figure', '/ˈfɪɡjər/', 'figure.mp3', 'n.身形，身影；数字；  v.想出', '8fab4cffde1dcc98ae28fb1c74c6bc33_99937_1742867871.jpg', '', 'Their figures', '他们的身影，从背后看，完美捕捉了电影角色的精髓。', 'us_Their_figures_20250325095755122_7262f7bdf75ae0daa758.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (718, 'finance', '/ˈfaɪnæns/', 'finance.mp3', 'v.资金供给，筹措资金；  n.金融', 'i_1_3876_0_7_151223140411-gigapixel-scale.jpg', '20141011_13_32_04_917_v3.png', 'The old man financed a poor student to go to college.', '老人资助那个贫困学生上大学。', '5764d9cf81dcd0db1f415219dcfbfdd1_20108_1626251657.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (719, 'flood', '/flʌd/', 'flood.mp3', 'n.洪水；  v.淹没', '38ba635985606d8a51b10647eb232ef9_185654_1539660704.jpeg', 'd_24_9299_0_4_20150808230146.png', 'The flood submerged the village and the farm.', '这场洪水淹没了村庄和农场。', 'a1ef1c9ba5a795b1_1266883537871088582_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (720, 'for example', '/fɔr ɪɡˈzæmpəl/', 'for example.mp3', 'phr.例如，举个例子', 'ba4bedacd690de09ba400d0be513770e_77508_1579599737.jpeg', '', 'We should eat some healthy food', '我们应该吃一些健康的食物，例如苹果。', '27ac7715bea69f31_1266798138923637378_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (721, 'for good', '/fɔːr ɡʊd/', 'for good.mp3', 'phr.永远', '3_0_20160520173452_14089_c.jpg', '', 'They wanted to stay together for good.', '他们想要永远在一起。', 'qjeey95anjmwq8d6qsl8se576pr9ghc3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (722, 'forbid', '/fərˈbɪd/', 'forbid.mp3', 'v.禁止；妨碍', '994d9651280aabff3eeace34fe814cdb_97559_1594308670.jpg', 'd_16_5230_0_2_20150808225150.png', 'We forbid smoking in the restaurant.', '餐厅内禁止吸烟。', 'f32315a59c906987_1266883378329115370_250207.mp3', 'for反对；相反 + bid要求 → forbid禁止', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (723, 'fortnight', '/ˈfɔːrtnaɪt/', 'fortnight.mp3', 'n.两星期', '922b567d83339c40c0a7a1d0ae4e3338_81410_1708252208.jpg', 'd_16_8964_0_2_20150808233636.png', 'A fortnight is made up of fourteen days.', '两周就是十四天。', 'us_A_fortnight_20241009154205972_9ad3e4be04a1c076f7c2.mp3', 'fort=fourteen十四 + night夜晚 → 十四天 → fortnight两周', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (724, 'frank', '/fræŋk/', 'frank.mp3', 'adj.坦白的，直率的；清楚表明的，明显的', 'dbbec8e6c0882def136e10f282e6047b_187319_1527580353.jpeg', 'd_1_5137_0_3_20150808123543.png', 'She was frank about the food in my teeth.', '她很直率地告诉我我牙上有东西。', 'us_She_was_20220608175245665_ae6c2d8c58ae463de7e7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (725, 'get along with', '/ɡet əˈlɔːŋ wɪð/', 'get along with.mp3', 'phr.与……相处，和睦相处，关系良好', 'c_i_wm_20120928_03_38_54_534.jpg', '', 'The cute animals get along with each other.', '可爱的小动物们相处得很愉快。', 'sa_16_18633_0_5_20150809015631.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (726, 'get by', '/ɡet baɪ/', 'get by.mp3', 'phr.侥幸躲过，勉强生活', 'i_12_4684_0_2_20150808161332.jpg', '', 'He works hard all day', '他整日辛苦工作，也只能勉强生活。', 'sa_12_4684_0_2_20150808161332.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (727, 'grateful to sb. for...', '/ˈɡreɪtfl tuː ˈsʌmbədi fɔːr/', 'grateful to sb. for....mp3', 'phr.就……对某人表示感激', 'bf6035364b86ae0580a14fefbced54f6_151425_1619404138.jpg', '', 'She felt grateful to the girl for the food.', '她对女孩提供的食物表示感激。', 'us_She_felt_20241009155424377_0a7f3a050b480e446e40.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (728, 'grow', '/ɡroʊ/', 'grow.mp3', 'v.生长，成长；渐渐变得，逐渐成为', '8975f0800811e4e11ef62f99d551d12c_110392_1595060058.jpg', 'd_24_17985_0_3_20150808233937.png', 'The seed grows into a tree.', '种子长成了一棵树。', 'ptlytpl8q6wyrbtybvn2xjtycltylrf8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (729, 'high-tech', '/ˌhaɪ ˈtek/', 'high-tech.mp3', 'adj.高科技的；  n.高科技', '155c3573596db6a23d034fb8a5c3a298_101864_1594800540.jpeg', '', 'She is wearing a pair of high-tech VR glasses.', '她戴着一副高科技虚拟现实眼镜。', '68fa847098182bb9b05049e8ba805f2c_72032_1594800545.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (730, 'honorable', '/ˈɑːnərəbl/', 'honorable.mp3', 'adj.荣誉的；品德高尚的；可敬的', 'e7daf4f73c2fd400a0b1457c37f21ee8_93465_1538667772.jpg', '20130518_03_14_46_709.png', 'At this honorable moment', '在这个荣耀时刻，他获得了他的硕士学位。', 'bf5d7506c5d54b73e5d33d627cb1d0f3_17442_1538667856.mp3', 'honor荣誉 + able…的 → honorable光荣的，高尚的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (731, 'huge', '/hju:dʒ/', 'huge.mp3', 'adj.巨大的', 'i_16_16621_0_4_160406175747-gigapixel-scale.jpg', 'd_24_16621_0_3_20150808231653.png', 'There is a huge yellow duck floating on the lake.', '有一只大黄鸭漂在湖上。', '73e504307d363d17_1266883014176713498_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (732, 'hunger', '/ˈhʌŋɡər/', 'hunger.mp3', 'n.饥饿；  v.渴望', '3e18fb9da273190c2ce010aa3ed81654_84036_1573788390.jpeg', 'd_24_8125_0_4_20150808225519.png', 'He wants a hamburger to satisfy his hunger.', '他想吃个汉堡来缓解饥饿。', '6c1bc421f8356590c09c8f57d85054b9_16816_1573788410.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (733, 'imitation', '/ˌɪmɪˈteɪʃn/', 'imitation.mp3', 'n.模仿；仿制品；赝品；  adj.伪造的；仿制的', '34d8dd7a37bd0551af2b0573023a1bc4_58988_1561953217.jpg', 'd_105_9764_0_2_20150809061527.png', 'The girl applies the lipstick in imitation of her mother.', '这个小女孩模仿她妈妈抹口红。', '967e45851a25049326d4d5c123bcdb9d_31658_1561953217.mp3', 'imit表示“想象，相像” + ation 名词后缀 → 想象后制造出的 → 仿制品', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (734, 'impossible', '/ɪmˈpɑːsəbl/', 'impossible.mp3', 'adj.不可能（存在或做到）的；  n.不可能的事', '2a0afffd855200af084b8145621b226d_141906_1544067577.jpeg', 'd_109_5541_0_2_20150809054208.png', 'It\'s almost impossible for her to push that massive rock.', '她要推动那块巨大的石头几乎不可能。', 'dc96557533cee473_1266797979578838000_250123.mp3', 'im不，无，非 + possible可能的 → impossible不可能的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (735, 'in question', '/ɪn ˈkwestʃən/', 'in question.mp3', 'phr.讨论中的，正在念叨的', '0a3542c5dd3328a7f90baa0268c3d68f.jpeg', '', 'The kitten in question is sleeping behind the tree. ', '他们所讨论的那只小猫正在树后睡觉。', '1293baa0f6d58752480e5aaac67b0797.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (736, 'in step', '/ɪn step/', 'in step.mp3', 'phr.一致的', '94416053ae1c90bd1e99128d881cbd5b.jpeg', '', 'Their movements are perfectly in step. ', '他们的动作完全一致。', 'b392b2cacef1f528ff685c2f866b4a54.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (737, 'incomplete', '/ˌɪnkəmˈpliːt/', 'incomplete.mp3', 'adj.未完成的，未结束的', '9ea4ef6d30afa0064411387d62636a77_83920_1569047650.jpg', '20140816_15_55_39_828_v3.png', 'The building is still incomplete? How slow!', '这栋楼还没有建好？龟速啊！', '4mwqqnn9vqrk5wukg88ymw3fmhqnen56.mp3', 'in不 + com共同 + plete满 → incomplete不完全的，不完善的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (738, 'indifferent', '/ɪnˈdɪfrənt/', 'indifferent.mp3', 'adj.不感兴趣的，不关心的', '92b4ca9b3e368f20c8368a93e3a34aaf_137613_1628065970.jpeg', 'd_1_1542_0_2_20150808121721.png', 'The staff were indifferent about the new plan put forward by their boss.', '员工们对老板提出的新计划漠不关心。', '3af62f8837aa96bd_1266883493617097260_250207.mp3', 'in不，无，非 + different不同的 → 与众不同的 → indifferent冷漠的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (739, 'induce', '/ɪnˈduːs/', 'induce.mp3', 'v.引导，劝诱', '50593f0609abceaa1aad214305dc3d7a_62226_1569048861.jpg', '', 'The leader gave a speech to induce his staff to work harder.', '领导发表讲话，引导员工更加努力地工作。', 'us_The_leader_20240201141629306_ba15bac1020adfac5b64.mp3', 'in进入+duce引导，带来→引进去→劝诱，诱导', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (740, 'insect', '/ˈɪnsekt/ ', 'insect.mp3', 'n.昆虫', '1b5718ad99b92dae5a1f1565079243b0_73564_1569047729.jpg', 'd_24_6664_0_3_20150808224721.png', 'There are many kinds of insects', '昆虫有很多种类，例如蝴蝶、蜜蜂和蚂蚁。', 'b66d1d2dd773810f_1266763523021888060_250117.mp3', 'in进入 + sect切，割 → 昆虫一节一节如被切开一样 → insect昆虫', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (741, 'instruct', '/ɪnˈstrʌkt/', 'instruct.mp3', 'v.指导，教；指示；通知', '3f01dee3bbe32282b5b78ab9300b55e7_89151_1565343138.jpg', 'd_107_5145_0_2_20150809011710.png', 'My mom instructs me how to play golf.', '我妈妈教我怎么打高尔夫球。', '17530783fb3b7b48_1266883322827942796_250207.mp3', 'in进 + struct建立 → 把知识建立进去 → instruct指导', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (742, 'interaction with', '/ˌɪntərˈækʃn wɪð/', 'interaction with.mp3', 'phr.与……的互动', '6ee23ac03dd7f08a5576a2e302cc051d.jpg', '', 'The teacher is having an interaction with his students.', '老师正在和他的学生互动。', '0c39093687326e3d7d5904f5242adad9_44192_1593586592.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (743, 'interested', '/ˈɪntrəstɪd/', 'interested.mp3', 'adj.感兴趣的；有利害关系的', '3836eb262e2cf0380f8a632274747c96_318091_1623747991.jpg', 'd_24_19089_0_3_20150809000451.png', 'The baby seems to be interested in the school bus.', '小宝宝似乎对这辆校车很感兴趣。', 'zmchg3a56n7hgdxfje8vbgl4y887l6xz.mp3', 'interest兴趣 ＋ ed形容词后缀 → 感觉有兴趣的 → interested感兴趣的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (744, 'interpret', '/ɪnˈtɜːrprət/', 'interpret.mp3', 'v.口译；解读；解释；  v.把……理解（解释）为', '3_0_20160521111529_55082_c-gigapixel-scale.jpg', 'd_107_5652_0_2_20150809013330.png', 'I interpreted his words into English.', '我把他的话口译成了英文。', '3_0_20160521111529_64088_c.aac', 'inter相互 + pret表达 → 语言之间相互表达 → interpret口译', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (745, 'keep on', '/kiːp ɑːn/', 'keep on.mp3', 'phr.持续（进行）', 'e5dcb3be598f69311367b2c364ba8020_63314_1580884555.jpg', '', 'The rain kept on falling throughout the day.', '雨持续下了一整天。', 'ce8ee994da9f4c804c7645571180f944_40846_1580884549.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (746, 'landlord', '/ˈlændlɔːrd/', 'landlord.mp3', 'n.房东，地主，老板', '9a422715b780092091b8183d1d7f10b8_170118_1731900050.jpg', 'd_1_6151_0_3_20150808124732.png', 'A landlord receives rent from a leased property.', '房东从出租的房产中收取租金。', '0b3b51367bf55f64_1266883322130770810_250207.mp3', 'land土地 + lord主 → landlord地主', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (747, 'leap', '/liːp/', 'leap.mp3', 'v.跳跃，跃过；  n.跳跃', '9ba289b8c85613e9713b0b0c24456bcc_91523_1533029169.jpeg', 'd_1_6380_0_3_20150808125108.png', 'The man leaped from a cliff to another cliff on the sea.', '这个男人在海上从一个悬崖跳向另一个悬崖。', 'gnll9fqcx6437rq3dzydwbz27tllrfyv.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (748, 'level', '/ˈlevl/', 'level.mp3', 'n.水平，标准，等级；  v.瞄准；对准目标；  adj.等高的', 'e99c761e21983334fc98946da278dd7a_190723_1574826758.jpeg', 'd_24_17541_0_3_20150808232936.png', 'Players are separated into three levels in this game.', '玩家们在这个游戏中被分为三个等级。', '7bf12fddd376d8d2e20ba1be1b0956d1_38686_1574826755.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (749, 'lie', '/laɪ/', 'lie.mp3', 'v.躺，平卧；撒谎；  n.谎话，谎言', '907ed08cd486dc4c667323299a6c64b8_198371_1611124108.jpg', 'd_74_13274_0_4_20150809024849.png', 'She lies down on the sofa', '她放下工作，躺在沙发上休息一会儿。', '05a06f11ced9fe54_1266763552715922110_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (750, 'likewise', '/ˈlaɪkwaɪz/', 'likewise.mp3', 'adv.同样地，此外', 'i_1_4161_0_2_20150808122433-gigapixel-scale.jpg', 'd_107_4161_0_2_20150809004639.png', 'The big man hates the small man; likewise', '这个大个子讨厌这个小个子。同样地，这个小个子也讨厌这个大个子。', 'sa_1_4161_0_2_20150808122433.aac', 'like相像 + wise方向，状态 → likewise同样地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (751, 'lively', '/ˈlaɪvli/', 'lively.mp3', 'adj.富有活力的；活泼的', '5ba5186aa038f8c24717af7d0da94be9_86361_1533025877.jpeg', 'd_24_6662_0_4_20150808224717.png', 'These lively children are jumping for joy.', '这些充满活力的孩子快乐地蹦蹦跳跳。', '9a75378c9ef422d51f22d2e63242df81_40670_1533025873.mp3', 'live活 + ly表形容词 → lively活跃的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (752, 'long for', '/lɔːŋ fɔːr/', 'long for.mp3', 'phr.渴望', 'fb6492db0f253fd094ddc2b872be32dc.jpg', '', 'This football player longs for his team to win the cup.', '这位足球运动员渴望他们球队赢得奖杯。', '88vr4zcl4w8b4gpu27apqyy9lhdlwgmg.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (753, 'make for', '/meɪk fɔːr/', 'make for.mp3', 'phr.有助于', '8a9643bf7e9c1e52157950f83d0e4c5d.jpg', '', 'The large print makes for easier reading.', '大号字体使阅读更容易。', '6d1b4e6dc3c27956271cbf8323d4c60b_43438_1600070540.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (754, 'market', '/ˈmɑːrkɪt/', 'market.mp3', 'n.集市，市场；行情；销路；  v.销售', '3_0_20170928071158_11005_c-manual-scale.jpg', 'd_24_16440_0_4_20150808231234.png', 'I usually buy fruits and vegetables at the market.', '我通常在市场里买水果和蔬菜。', '97232cacb09d6596_1266883013533805324_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (755, 'marriage', '/ˈmærɪdʒ/', 'marriage.mp3', 'n.婚姻；婚礼', '2df51b64b1834e90744dd8c39db8c70b_197014_1532158316.jpeg', 'd_24_18085_0_4_20150808234435.png', 'After they exchanged rings', '交换戒指之后，这对新人迈入了婚姻。', '0e898da0dd3f167288619ccd1a81f308_32266_1532158321.mp3', 'marri=marry结婚 + age状态，总称 → marriage结婚', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (756, 'maximize', '/ˈmæksɪmaɪz/', 'maximize.mp3', 'v.取……最大值，最佳化', 'maximize_13384_20231106_ad05056e.jpg', '', 'Maximize the volume if you still can\'t hear the sound clearly.', '如果你还听不清声音，就把音量最大化。', '5_51_78_20161208111605_17690_c.aac', 'maxi大 ＋ mize使 → maximize使最大化', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (757, 'mercy', '/ˈmɜːrsi/', 'mercy.mp3', 'n.宽恕，原谅', 'bd715157eacbaced28b91167dc68e1e6_130298_1733291604.jpg', 'd_24_4363_0_4_20150808223512.png', 'He pleaded for mercy before the judge.', '他在法官面前乞求宽恕。', 'us_He_pleaded_20241204135341607_0c60fea25c9141715b6f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (758, 'metal', '/ˈmetl/', 'metal.mp3', 'n.金属，合金，金属制品；  v.（以金属）覆盖，装配', 'bd8525bf76e3fdf6c500515f453c2203_108072_1719805488.jpg', 'd_24_15992_0_4_20150808230950.png', 'He crafted her a metal rose from old airplane parts.', '他用旧飞机零件为她制作了一朵金属玫瑰。', 'us_He_crafted_20240701114510404_c668161b8d6585750ec2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (759, 'monthly', '/ˈmʌnθli/', 'monthly.mp3', 'adj.每月的，每月一次的；  adv.每月一次，按月；  n.月刊', 'i_1_6241_0_3_20150808124903-gigapixel-scale.jpg', 'd_103_6241_0_3_20150809022540.png', 'I have to keep up with my monthly house payments.', '我必须每月付清房租。', 'sa_1_6241_0_3_20150808124903.aac', 'month月 + ly形容词后缀，...的 → monthly每月的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (760, 'moral', '/ˈmɔːrəl/', 'moral.mp3', 'adj.道德（上）的，道义的；  n.道德，品行', '150a76c29de86f9879419df9efcd2697_198091_1557226418.jpeg', 'd_24_18886_0_3_20150808235850.png', 'To return the money you found or not', '捡到的钱要不要还回去，这是一个道德难题。', 'fb941b2d0d333c04c91ab2fa5d94d750_30004_1553846146.mp3', 'mor道德 + al…...的 → moral道德的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (761, 'musician', '/mjuˈzɪʃn/', 'musician.mp3', 'n.音乐家，作曲家', 'c80980f5886f096736e2fdb1ba7a5cba_44983_1557909326.jpg', 'd_16_9520_0_2_20150808234547.png', 'The musician is playing beautiful music.', '这位音乐家在演奏美妙的音乐。', 'hp5xx9zp57btqddrzqq7c54vumw6jbw3.mp3', 'mus音乐，娱乐 + ician表专家，从事某职业的人 → musician音乐家', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (762, 'near', '/nɪr/', 'near.mp3', 'prep.在......附近，靠近；  adv.近，接近；  adj.近的', 'dbe98349f4506d825553b3ca1ff4d3fc_200863_1578560721.jpeg', 'd_24_17632_0_4_20150808233119.png', 'The little boy sits near the fire.', '这个小男孩坐在靠近火堆的位置。', '4a10fd4258aae131_1266763313841855114_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (763, 'network', '/ˈnetwɜːrk/', 'network.mp3', 'n.网络；广播网，电视网；  v.建立关系网；使联网', '1425952604069-gigapixel-scale.jpg', 'd_107_5005_0_2_20150809011251.png', 'The Internet is basically a network of billions of computers.', '互联网其实就是连接数十亿台电脑的网络。', 'sa_1_5005_0_2_20150808123323.aac', 'net网 + work操作 → network网络', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (764, 'not least', '/nɑːt liːst/', 'not least.mp3', 'phr.尤其是，特别是', 'c859907df36a3846407c9e829d89d0ce.jpeg', '', 'While preparing this dish', '在准备这道料理时，最后但同样重要的是，要记得摆盘让这道菜更精致些。', '01f182c6d0430e3ab4ae6b89c9e907ec.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (765, 'numb', '/nʌm/', 'numb.mp3', 'adj.麻木的，失去知觉的；  v.使麻木', '56f2e557ddd33ccbee07cf90466a4c06_96887_1698660983.jpg', 'd_16_5413_0_5_20150808225246.png', 'My mouth is numb so I don’t feel the pain.', '我的嘴麻木了所以感觉不到疼。', 'ujsapc4l6u5zh8h97rpukh4gy59fdpxx.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (766, 'objective', '/əbˈdʒektɪv/', 'objective.mp3', 'n.目标；目的；  adj.客观的', 'i_1_5089_0_5_20150808123452.jpg', 'd_107_5089_0_2_20150809011505.png', 'My objective this year is to lose weight.', '我今年的目标是减肥。', 'sa_1_5089_0_5_20150808123452.aac', 'ob反对 + ject投掷，扔 + ive形容词后缀 → 反对扔的 → objective客观的；目标', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (767, 'ocean', '/ˈoʊʃn/', 'ocean.mp3', 'n.海洋，洋，大海', '434fa9f632f7150e30b8e37a1c4c233a_203315_1585367452.jpeg', 'd_24_16656_0_4_20150808231823.png', 'Between Asia and America lies the world\'s largest ocean—the Pacific Ocean.', '位于亚洲和美洲之间的是世界上最大的海洋——太平洋。', 'wr6efs9qz442l8v2vw8hwcamhcxntbc7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (768, 'offer', '/ˈɔfər/', 'offer.mp3', 'v.提供', 'i_24_3851_0_10_151220114705-gigapixel-scale.jpg', 'd_1_3851_0_7_151021113839.png', 'The woman offers the man a gift.', '这个女人给了男人一份礼物。', '9b4aa6566bd9faa5_1266883008721345176_250207.mp3', 'of一再 + fer带来 → 一再带来 → offer提供', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (769, 'on and off', '/ɔn ənd ɑf/', 'on and off.mp3', 'phr.断断续续地', 'onandoff_6087_20231106_7dd98049.jpg', '', 'Expect on and off thunderstorms this week.', '未来一周将会有间歇性雷阵雨天气。', 'sa_11_6087_0_2_20150808164755.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (770, 'on duty', '/ɑːn ˈdʊti/', 'on duty.mp3', 'phr.值日，值班', '9912d47fd3183e3c66badaf1121c16b7_108804_1576135323.jpeg', '', 'The student on duty has to clean the blackboard and tidy up the podium.', '值日生必须擦黑板和整理讲台。', 'us_The_student_20241009155533293_ff5f435b388ee6f19b32.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
