INSERT INTO `words` VALUES (772, 'out of practice', '/aʊt əv ˈpræktɪs/', 'out of practice.mp3', 'phr.久不练习，生疏', '31d44a4eb1b4887d5696390e8c64d84e.jpeg', '', 'He has not played the piano for years', '因为多年不弹钢琴，他的技艺已经生疏了。', 'e4bc4609f518df618fae1573dc706ecf.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
