INSERT INTO `words` VALUES (780, 'police', '/pəˈliːs/', 'police.mp3', 'n.警察，警方；  v.维持治安，管辖，监督', '3_0_20170721071214_31274_c-manual-scale.jpg', 'd_24_16448_0_3_20150808231250.png', 'We know he\'s a police because of his car and uniform.', '我们根据他的车子和制服得知他是一位警察。', 'us_We_know_20250106103551715_691705d9fed620d76625.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (781, 'pollute', '/pəˈluːt/', 'pollute.mp3', 'v.污染，弄脏；玷污，亵渎', 'aa69734cf0b2adc3ff589069d86a4d3b_164772_1565247117.jpeg', '20141013_23_15_36_199_v3.png', 'Few fish can survive in this polluted river.', '在这条受污染的河里，很少有鱼能存活下来。', '382178f6df2cd3328c58132bacccd7c3_41440_1565247114.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
