INSERT INTO `words` VALUES (783, 'prevail over', '/prɪˈvel ˈovɚ/', 'prevail over.mp3', 'phr.胜过', '9c26b51fcbe9649edfe6c5be162fe78b.jpg', '', 'He has prevailed over his opponents and won the championship.', '他战胜了对手，夺得了冠军。', '40e289999a0020a2cf795247c03cf5af_41936_1599549874.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (784, 'put out', '/pʊt aʊt/', 'put out.mp3', 'phr.扑灭，熄灯', '3_0_20160520172726_72786_c.jpg', '', 'Wow! The elephant put out the fire. What a brave firefighter!', '哇！那头大象把火扑灭了，真是一个勇敢的消防员！', '3_0_20160520172726_26004_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (785, 'qualified to do sth.', '/ˈkwɑːlɪfaɪd tuː duː ˈsʌmθɪŋ/', 'qualified to do sth..mp3', 'phr.有……的资格', 'a8780b9e491948693ada441ae0c8c5fe.jpg', '', 'He\'s qualified to be a doctor.', '他有成为一名医生的资格。', '8afe7b6462224dc9b9ccedcbd10c1146_28064_1593575952.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (786, 'rank', '/ræŋk/', 'rank.mp3', 'v.把……分等级，属于某个等级；排名；  n.等级，级别；  adj.繁茂的', 'b59bad175c318a5b88fd76966c44a3ea_193872_1538651747.jpg', 'd_24_8059_0_4_20150808225415.png', 'They rank as the champion', '他们分列冠、亚、季军。', 'us_They_rank_20241009155334938_e2c38d052ad30bf816a1.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (787, 'remember', '/rɪˈmembər/', 'remember.mp3', 'v.记得，想起', 'i_16_17974_0_5_151118114120-gigapixel-scale.jpg', 'd_99_13960_0_4_20150809022515.png', 'I still remember the day he asked me to marry him.', '我还记得他向我求婚那天的情景。', '802b5bc8345be331_1266763403010353962_250117.mp3', 're再 + member记忆 → 再记得 → remember记得，记住', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (788, 'remind sb. to do sth.', '/rɪˈmaɪnd ˈsʌmbədi tuː duː ˈsʌmθɪŋ/', 'remind sb. to do sth..mp3', 'phr.提醒某人做某事', 'f49e420153a12c95ed714b41e8d0634d.jpg', '', 'The note reminds me to play basketball at 9 o\'clock.', '这张便签提醒我在9点打篮球。', '5245fc37143181fba8f928072b5fcc14_44960_1593575163.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (789, 'representative', '/ˌreprɪˈzentətɪv/', 'representative.mp3', 'n.代表；  adj.典型的，有代表性的', '6e532fcac64f9e98b0ecda4adbf075ea_84157_1524815990.jpeg', 'd_107_7851_0_2_20150809022259.png', 'They chose her as their representative to speak for them.', '他们选她作为代表发声。', '165b35efa915f6f4_1266883633373731504_250207.mp3', 'represent代表 + ative形容词后缀 → representative代表性的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (790, 'research on', '/rɪˈsɚtʃ ɑn/', 'research on.mp3', 'phr.对...的研究', '042b9993a9b99772e4a366c19ff33c3b.jpeg', '', 'He conducted detailed research on insects.', '他对昆虫进行了详细的研究。', 'b4740371c764e9e26bd2532632ad0e54_42478_1599622787.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (791, 'respectively', '/rɪˈspektɪvli/', 'respectively.mp3', 'adv.各自；分别', '67fae1a16df2d9bd49bf6306fcd5ee52_198971_1561953140.jpg', 'd_13_5178_0_2_20150808175427.png', 'The twins', '凯特和金伯莉这对双胞胎姐妹分别收到了玩具车和洋娃娃作为礼物。', 'd24fd00ef47ebc05928821b950206005_30922_1626082054.mp3', 'respective回头看（自己）=各自的 + ly……地 → respectively各自地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (792, 'response to', '/rɪˈspɑns tu/', 'response to.mp3', 'phr.对...的反应；回答，回应', 'cfb5a6f34c61130a7b4b78365556680c.jpeg', '', 'The firefighters were praised for their rapid response to the fire.', '消防队员因对火灾的迅速反应而受到赞扬。', '5b516054ee86511bec315128f99eddc1.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (793, 'role', '/roʊl/', 'role.mp3', 'n.角色', 'b54bf79cd930d290fa84eec91a61e35a_196630_1573627189.jpeg', 'd_13_15335_0_2_20150808203345.png', 'The actress played challenging roles in many different TV series.', '这名女演员在不同的电视剧里尝试了具有挑战性的角色。', 'c81f80dc0945f4297d177832e332475c_50144_1574648535.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (794, 'royal', '/ˈrɔɪəl/', 'royal.mp3', 'adj.王室的，皇家的；盛大的，高贵的', 'i_1_10253_0_4_20150808131628-gigapixel-scale.jpg', '20141014_07_13_47_547_v3.png', 'The king wears his royal clothes.', '国王穿着他的御用衣服。', 'ec5ac967a05083a9_1266883636100487908_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (795, 'sail', '/seɪl/', 'sail.mp3', 'v.航行；  n.帆', 'ac8b33bfefb19ee6a39ed21340081339_90743_1535964794.jpeg', '20121225_18_55_55_181.png', 'The big boat sails off into the sunset.', '这艘大船朝着落日航行。', 'qccz2df657v8mn47d3bjhp4q4ul8gal2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
