INSERT INTO `words` VALUES (797, 'scatter', '/ˈskætər/', 'scatter.mp3', 'v.（使）分散，撒开，散播', '572ab139351795bfb5f88a708c103f36_189102_1564731555.jpg', 'd_107_4076_0_2_20150809004259.png', 'The kid\'s room has toys scattered all over the ground.', '儿童房里的玩具散落满地。', '20ec7a22e36aab61e122481dfebf8cd8_47916_1564731544.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (798, 'scholar', '/ˈskɑːlər/', 'scholar.mp3', 'n.学者；公费生，有奖学金的学生', 'i_1_9306_0_2_20150808131358-gigapixel-scale.jpg', 'd_16_9306_0_2_20150808234258.png', 'She\'s so young', '她很年轻，但是已经是一个小小的学者了。', 'be811d5bf0a4ff07d56618539e6532ae_19167_1596092608.mp3', 'schol学派 + ar名词后缀，人 → scholar学者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (799, 'screw', '/skruː/', 'screw.mp3', 'n.螺丝；螺旋；  v.敲诈勒索；  v.用螺钉固定', '3_0_20160718115341_50918_c-gigapixel-scale.jpg', 'd_106_6501_0_2_20150809073424.png', 'At each turn', '每转一圈，螺丝就会往这块木头里钻得更深。', 'tgbr9lxhzpdcs7bqltb4u4xm9se6sv5q.mp3', 'shr切割 + w → screw螺丝，螺旋', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (800, 'seldom', '/ˈseldəm/', 'seldom.mp3', 'adv.很少，不常', '0ec9351aecf12de87ec09e5be1fdf4d2_162625_1595058926.jpg', 'd_24_19021_0_3_20150808235956.png', 'It seldom rains in the desert.', '沙漠里很少下雨。', 'sa_16_19021_0_4_160118110809.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (801, 'set up', '/ˈsɛt ˈʌp/', 'set up.mp3', 'phr.设立，创立；（军事）训练', '96da61bcdf6d6807b7d374548cc8e1ad_251947_1701675300.jpg', '', 'We set up our tent by the shore of the lake.', '我们在湖岸边扎起了帐篷。', 'sa_32_19932_0_4_20150808235033.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (802, 'shave', '/ʃeɪv/', 'shave.mp3', 'v.剃（须发），刮脸；  n.剃须，修面', 'a82b5767c426a6b23799ec1d8ba7344f_86849_1533120663.jpeg', 'd_24_7212_0_4_20150808225030.png', 'The man is shaving in front of the mirror.', '这个男人正在镜子前刮胡子。', 'e358a4e0cb628426_1266883196851739174_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (803, 'shy', '/ʃaɪ/', 'shy.mp3', 'adj.羞怯的', '847452274a4b189ad184dd867156817b_202640_1574909505.jpeg', 'd_109_18026_0_2_20150809062850.png', 'They are both shy on the first date.', '第一次约会时，他们俩都很害羞。', '1c2a2d0fecb92c8e_1266763446820973484_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (804, 'shy of', '/ʃaɪ əv/', 'shy of.mp3', 'phr.不足，未达到', '4e7ed11ef69c0cc4ba66d1691454b1ba.jpeg', '', 'They are two players shy of a full basketball team. ', '他们还差两名队员才能组成一支篮球队。', '3607eb66fc0de3263ccf4bd6249837a9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (805, 'sincerely', '/sɪnˈsɪrli/', 'sincerely.mp3', 'adv.真诚地', 'cbc3a7f9abe5539a37be21374b2d54c6_146817_1538758308.jpg', '20130130_16_05_05_504.png', 'The robot sincerely hopes to make friends with humans.', '这个机器人真心希望和人类做朋友。', '5ca71f547ccf7f3c8f1516b71a97f1bb_20578_1596092904.mp3', 'sincere真实的 + ly副词后缀 → sincerely真诚地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (806, 'so as to', '/soʊ æz tuː/', 'so as to.mp3', 'phr.为了，以便', '3_0_20170721071439_77910_c.jpg', '', 'He dressed himself smartly so as to give a good impression to his blind date.', '他精心打扮了一番，为的是给相亲对象留下好印象。', '3_0_20170721071439_3899_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (807, 'so far', '/soʊ fɑːr/', 'so far.mp3', 'phr.到目前为止', '3_0_20170721071429_48356_c.jpg', '', 'So far', '迄今为止，我已经到过11个国家旅游了。', '3974961bdbf3bd5f_1266883320447195726_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
