INSERT INTO `words` VALUES (809, 'spider', '/ˈspaɪdər/', 'spider.mp3', 'n.蜘蛛', 'cd88048352d6acdf73f6afff1466b089_53144_1713764750.jpeg', 'd_103_8576_0_3_20150809032258.png', 'The spider weaves a web to catch flies.', '蜘蛛织网来捕捉苍蝇。', '307a6b9142c40ab5_1266883194891295484_250207.mp3', 'spi=(s)pen牵引，拉伸，旋转 + der名词后缀，做...的人或物 → 引线织网的动物 → spider蜘蛛', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
