INSERT INTO `words` VALUES (811, 'stop', '/stɑːp/', 'stop.mp3', 'v.停止；阻止；  n.车站', 'i_13_17287_0_2_20150808204713-gigapixel-scale.jpg', '20121225_18_48_18_329.png', 'The road worker held up his hand to stop the car.', '修路工人举手让车停下来。', 'fc3d22ee9d5969c7_1266763242809174980_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (812, 'strange', '/streɪndʒ/', 'strange.mp3', 'adj.奇怪的；陌生的', '293007f3571ccea2af20d9ec80fac6d9_142627_1720088206.jpg', 'd_24_18099_0_3_20150808234542.png', 'The man\'s strange look grabbed everyone\'s attention.', '这个男人奇怪的造型吸引了所有人的注意。', '3fe1cb7fd3722bd5_1266763525583121298_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (813, 'substantial', '/səbˈstænʃl/', 'substantial.mp3', 'adj.大量的', 'd8aad45cbae626812ef751e8e1451558_93306_1585145105.jpeg', '', 'The store provided substantial discounts on all clothes.', '这家店给所有衣服都打了大幅度的折扣。', '61e1351d82b22d832423bee081031f7c_21048_1626492762.mp3', 'sub下面 + stan站立 + tial形容词后缀 → 作为基本存在的 → substantial重大的，大量的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (814, 'suffer', '/ˈsʌfər/', 'suffer.mp3', 'v.感到（疼痛）', '6b2c3ca23c182026165b02c8f785aa18_70450_1732245140.jpg', '20130308_21_35_58_884.png', 'He suffers from a bad toothache.', '他牙痛得厉害。', 'us_He_suffers_20241122111232581_60c17163c6f490474c29.mp3', 'suf在下 + fer负重 → suffer承受', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (815, 'survive', '/sərˈvaɪv/ ', 'survive.mp3', 'v.幸存；艰难度过；  v.生存，活着', '6f2b19893235d3dadf2dc15f53a09ab9_133007_1534819840.jpeg', 'd_16_7586_0_2_20150808231843.png', 'The girl survived the shipwreck.', '这个女孩在海难中幸存了下来。', '43d33145fca1ae1f7d7c0574254f4bed_25648_1534819829.mp3', 'sur超过 + vive活 → survive存活', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (816, 'sympathy for', '/ˈsɪmpəθi fɔːr/', 'sympathy for.mp3', 'n.对……的同情', 'b42a80647ff2ea2ccb47b0b091555c09.jpeg', '', 'She felt great sympathy for the injured cat and bandaged its wound.', '她很同情这只受伤的猫咪，并为它的伤口做了包扎。', '343a19aae36101b1c5aba20fef9c9887.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (817, 'thanks to', '/θæŋks tu/', 'thanks to.mp3', 'phr.幸亏，由于，因为', 'd26478da21b65b71bd422686f09d95c2.jpg', '', 'The vase didn\'t break thanks to the young man catching it in time.', '幸亏年轻人及时接住了，花瓶才没有打碎。', '766c4b847926e72f1d72c364dd898c5c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (818, 'thanksgiving', '/ˌθæŋksˈɡɪvɪŋ/', 'thanksgiving.mp3', 'n.感恩节', '7842cf316c466b6dcbfbed4d2db577de_95857_1588218831.jpeg', '', 'Roast turkey is a traditional food served on Thanksgiving.', '烤火鸡是感恩节的传统食物。', '73c2f704df72b50dbd6123746012a928_58558_1588218828.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (819, 'thousand', '/ˈθaʊznd/', 'thousand.mp3', 'num.一千，一千个；许多，数以千计', '3_66_20170821175259_47634_c-gigapixel-scale.jpg', 'd_24_19562_0_3_20150809002010.png', 'I\'ve got a thousand followers online. I\'m so popular!', '我在线上有一千位粉丝。我真是太受欢迎啦！', 'eac57b98e654d530adb38a4d3bff2273_20890_1541817975.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (820, 'thus', '/ðʌs/', 'thus.mp3', 'adv.因此；这样，如此', 'eb354e6bbe4b3b3370e023889be993d3_132180_1735525494.jpg', 'd_24_19165_0_4_20150809001019.png', 'He exercises every day and thus has managed to lose some weight.', '他每天都锻炼，因此减肥成功了。', 'us_He_exercises_20241230102449521_fd9ba8bff792a91e116f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (821, 'travel', '/ˈtrævl/', 'travel.mp3', 'v.旅行；行走；走过，驶过；  n.旅行，旅游', 'c2bf48166a09015611190aa71c5ea1f5_97931_1729822736.jpg', 'd_99_14586_0_4_20150809022623.png', 'Where should I travel next?', '我接下来应该去哪儿旅行呢？', 's5dyqmxntfhjhh7dq7yy5np8b5wqpadp.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (822, 'twist', '/twɪst/', 'twist.mp3', 'v.扭；歪曲；  n.搓，扭，拧', 'i_1_2774_0_3_20150808121924-gigapixel-scale.jpg', 'd_16_2774_0_2_20150808223648.png', 'The right way to eat this biscuit is to twist it', '吃这种饼干的正确方式是扭一扭，舔一舔，再泡一泡。', 'f8a18756128224d2718c43db2b35e53f_33473_1621913901.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (823, 'umbrella', '/ʌmˈbrelə/', 'umbrella.mp3', 'n.伞，雨伞', '5b9966562669b8c86d25bd36264dc322_54032_1575286582.jpeg', 'd_99_14623_0_4_20150809022707.png', 'This umbrella is yellow.', '这把伞是黄色的。', '236qexgck3ttlpjgpx2lhdnxlgbkacf8.mp3', 'umbr阴影 + ella小东西 → 带来影子的小东西 → umbrella伞', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (824, 'unless', '/ənˈles/', 'unless.mp3', 'conj.除非，如果不；除……外', '3_0_20170707173006_67057_c-gigapixel-scale.jpg', 'd_24_19254_0_3_20150809001032.png', 'I won\'t buy you that toy unless you get a full mark.', '我不会给你买玩具的，除非你得了满分。', 'pnxk5vjrxzaxaee8sskbk67pt5awlvvs.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (825, 'unnecessary', '/ʌnˈnesəseri/', 'unnecessary.mp3', 'adj.不必要的，不需要的，多余的', 'd60472b68d01c3909b38907a4d3ab25d_139040_1731910209.jpg', 'd_13_6252_0_2_20150808190143.png', 'Grandma tidied up some unnecessary items.', '外婆整理出一些不必要的杂物。', '829xfg7wza8qb2274umadmexxu6q6v6v.mp3', 'un不 + necess必要 + ary 表示有……性质的 → unnecessary不必要的，无用的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (826, 'vibration', '/vaɪˈbreɪʃn/', 'vibration.mp3', 'n.振动；心灵感应', '97dfb6ec5a0a6278168ffe48dac4aeb3_102923_1535610466.jpeg', 'd_108_9773_0_2_20150809050454.png', 'The phone rings with a vibration.', '手机铃声伴随着一阵震动响起。', '620f5679af63d3d5_1266883634035338170_250207.mp3', 'vibr摇动 ＋ ation表名词 → vibration振动，摇动', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (827, 'visitor', '/ˈvɪzɪtər/', 'visitor.mp3', 'n.访问者，来宾', 'i_1_19457_0_5_20150808132611-gigapixel-scale.jpg', '20130301_12_52_08_496.png', 'I think we have a visitor at the door.', '我想我们有客人来了。', 'b77c296682e5efb3_1266763525793077896_250117.mp3', 'visit参观 + or表示人 → visitor参观者，观光者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (828, 'web', '/web/', 'web.mp3', 'n.蜘蛛网', 'b65f523acba4d8367050cb2a63d6de4a_193979_1607915227.jpg', '20121225_18_35_19_777.png', 'The spider makes a beautiful web.', '蜘蛛织了张漂亮的网。', 'sa_2_4823_0_2_20150808143804.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (829, 'widespread', '/ˈwaɪdspred/', 'widespread.mp3', 'adj.分布广的；普遍的，广泛的', 'b6b2c751d6cd37641159d9d99c533865_77726_1585380983.jpg', 'd_107_8259_0_2_20150809023014.png', 'My love story quickly became widespread through the Internet.', '通过网络，我的爱情故事很快就传开了。', 'sa_16_8259_0_2_20150808232748.aac', 'wide广泛的 + spread展开 → widespread分布广的，普遍的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (830, 'wish for', '/wɪʃ fɔr/', 'wish for.mp3', 'phr.希望得到，想要', '0f1a979870228b19e83a14ace2f7da27.jpg', '', 'This couple wish for a baby', '这对夫妻想要有个孩子，所以他们都在对着流星许愿。', '761bbed765aef359d4fe03ac53f1068c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (831, 'wonderful', '/ˈwʌndərfl/', 'wonderful.mp3', 'adj.极好的，精彩的；惊人的，奇妙的', 'a20f7648c733fbbfd0abfa964c90a37a_112807_1571130803.jpeg', 'd_24_17913_0_3_20150808233441.png', 'Many people have wonderful things to say about this English learning app.', '人们对这款英语学习应用有极好的评价。', 'dxw9km3lr9ujnsl2hc7gjr77tyz94hp3.mp3', 'wonder奇迹，神奇 + ful形容词后缀 → wonderful极好的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (832, 'work', '/wɜːrk/', 'work.mp3', 'v.起作用，有效果，奏效', '95bdaccbee053fc38874a85576f2c24f.jpg', 'd_24_17922_0_3_20150808233459.png', 'The medicine works! I feel well!', '这个药有效果！我感觉很好！', 'ffbcae889987bee1f27e02589d52a8b6_48992_1596781809.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (833, 'work out', '/wɝk aʊt/', 'work out.mp3', 'phr.算出；锻炼；计划；解决', 'c_i_wm_20120915_03_18_52_839.jpg', '', 'He worked out the math problem on the blackboard.', '他计算出了黑板上的那道数学题。', 'axkhzhmlppgypzu5btutvg2pqy8va9mn.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (834, 'worthy of', '/ˈwɜːrðə əv/', 'worthy of.mp3', 'phr.值得', '8398d1b1cce76b8a79dd0a87cddfe5d4.jpeg', '', 'Two points in this report are especially worthy of notice.', '这份报告中有两点特别值得注意。', '08577cca78beb9e0eb514ae02b175bda.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (835, 'would', '/wʊd/', 'would.mp3', 'v.会', '51e21f1e2c32bd356a3d45d954d26e0b.jpg', 'd_13_19658_0_2_20150808205851.png', 'He said if he earned a million dollars he would buy a house.', '他说如果他挣了一百万美元，他就会买一栋房子。', 'us_He_said_20240610223018154_b4a9aaa797bc7f0e3d2d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (836, 'abundant', '/əˈbʌndənt/', 'abundant.mp3', 'adj.大量的；丰富的', '8f18ba61e000e8f2f24fa4f88be4c109_132697_1558513964.jpeg', '20130106_14_33_54_712.png', 'Fish are abundant in the pond.', '池塘里鱼类丰富。', 'us_Fish_are_20240423145000372_b6bf5267d6065cef9797.mp3', 'ab一再 + und波动 + ant...的 → 波浪一多就溢出了 → abundant丰富的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (837, 'addict', '/ˈædɪkt/', 'addict.mp3', 'n.上瘾的人；入迷的人；  v.使沉迷，使上瘾', '6f8e73395735d57aecc107d13eb8ae42_184290_1574061331.jpeg', '', 'The boy is a cellphone addict', '这个男生对手机上瘾，不管去哪儿他都带着手机。', 'us_The_boy_20231127101303735_70614aa147e06786bda9.mp3', 'ad一再 + dict说 → 一再说起 → 对…...入迷 → addict上瘾', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (838, 'administration', '/ədˌmɪnɪˈstreɪʃn/', 'administration.mp3', 'n.管理，行政', '0b1d611cd09a99a23c599210c149ea9e_37364_1585378751.jpeg', 'd_107_16411_0_2_20150809025722.png', 'She works in the university\'s administration office.', '她在大学的行政办公室里工作。', '130339b24380a595975bcf3d2f5e40a9_19481_1585378767.mp3', 'ad表加强 + ministr管理 + ation名词后缀 → 行政，管理 → administration管理', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (839, 'advanced', '/ədˈvænst/', 'advanced.mp3', 'adj.先进的', '9322b42e02dd227eef66089e7bec0613_185887_1558511796.jpeg', 'd_107_77_0_2_20150809000254.png', 'The robot is so advanced that it can cook all kinds of meals.', '这个机器人很先进，能做各式各样的饭菜。', '3388f5e7cfd86c0442012758d01b9910_20891_1621912314.mp3', 'advanc前进 + ed……的 → 往前进的 → advanced先进的，高级的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (840, 'advantage', '/ədˈvæntɪdʒ/', 'advantage.mp3', 'n.优势', 'aaea3f5a2c5e070b5f7e87ccc8a5a21a_36703_1657001204.jpg', 'd_24_7485_0_3_20150808225112.png', 'The man with the rocket gets a huge advantage.', '坐着火箭的人占了很大的优势。', '0b2a7317bdb043cc_1266883378780548084_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (841, 'adventure', '/ədˈventʃər/', 'adventure.mp3', 'n.冒险，冒险活动', '7152f2991ca5c8effc0b355d7c12054c_285480_1583391589.jpg', 'd_24_7256_0_4_20150808225046.png', 'The boy went on an adventure in the jungle.', '这个男孩去丛林里冒险了。', '57psl46rh7g6ucnysm7alzyeefh5glvs.mp3', 'ad做…，加强… + venture冒险 → adventure冒险', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (842, 'altogether', '/ˌɔːltəˈɡeðər/', 'altogether.mp3', 'adv.总共，一共；总而言之', 'c0fbadb964694140ef9a1421a5d694f7_106630_1619323480.jpg', 'd_16_16004_0_2_20150809001439.png', 'These gifts cost me 1', '这些礼物总共花了我1000美元。', 'us_These_gifts_20240628094536313_14ab23bcaa9c142c8d06.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (843, 'apply for', '/əˈplaɪ fɔr/', 'apply for.mp3', 'phr.申请', '933693a7b3c5de69c1afae53ca21d4f1.jpg', '', 'The student is applying for membership of the University Guitar Society.', '这个学生正在申请加入大学吉他社。', '4afbbf793af37f5dd8f27a4f525804ae.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (844, 'argument', '/ˈɑːrɡjumənt/', 'argument.mp3', 'n.争吵，争论，争辩；论据，论点', 'i_1_7114_0_4_150917165616-gigapixel-scale.jpg', 'd_14_7114_0_2_20150808164203.png', 'The girl had an argument with her boyfriend about the video game.', '女孩和她的男朋友因为电子游戏争吵。', 'sa_1_7114_0_4_150923162923.aac', 'argu(e)争论 + ment名词后缀 → argument争论，辩论', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (845, 'art', '/ɑːrt/', 'art.mp3', 'n.艺术', 'b91917b74400f49a9815a18f847eac65_189199_1561953277.jpg', '20121225_18_34_40_725.png', 'Painting and dance are forms of art.', '绘画和舞蹈都是艺术的表现形式。', 'a93qbb8zmhna76r7aw69v56cc9e6xgws.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (846, 'ask after', '/æsk ˈæftər/', 'ask after.mp3', 'phr.问候', '0c0920fcc0d286d702a01cd8cc36fa7f.jpg', '', 'He was a caring grandfather who always asked after his grandchildren.', '他是一位慈爱的祖父，总是问候自己孙子孙女的健康。', '5ae99de16c73a5471cecf34d0d05cb9d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (847, 'association', '/əˌsəʊsiˈeɪʃn/', 'association.mp3', 'n.协会，联盟，社团；伙伴，关系', '08c4aec2db7444939bafac81120a4a42_202468_1718950554.jpg', '', 'The association members wanted to attract new people to join them.', '社团成员们想吸引更多的人加入他们。', '4190e8a94bb7329affce7ab9ebf7b459_31445_1621931054.mp3', 'as加强 + soci社会 + at(e)使… + ion表名词 → associate结成社会=联合 + ion表名词 → association联合', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (848, 'assume', '/əˈsuːm/', 'assume.mp3', 'v.猜想；认为；接受；  v.采取', 'i_1_5093_0_4_151221103245-gigapixel-scale.jpg', 'd_16_5093_0_2_20150808224949.png', 'I assumed that the red team would win.', '我猜红队会赢。', 'sa_1_5093_0_4_151223154315.aac', 'as加强 + sume拿取 → 主动拿起 → assume承担', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (849, 'at times', '/æt taɪmz/', 'at times.mp3', 'phr.有时', '2dcf841c3dcba0ff10d96eb671b9c9c9.jpg', '', 'Even the most gentle and easygoing man may', '即使是最温柔随和的人，有时也会发火。', 'b86f6894dd55b4a46ec04338c9d77eef.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (850, 'awake', '/əˈweɪk/', 'awake.mp3', 'adj.醒着的；  v.（使）醒来；唤起，被唤起', '3_0_20170928071504_88401_c-gigapixel-scale.jpg', 'd_24_9315_0_3_20150808230154.png', 'It\'s already 3:22 a.m.', '现在已经是凌晨3点22分了，但她还醒着。', 'nbcd9gdt8mgxa7m22ggvrr635ut8kpkv.mp3', 'a加强意义 + wake醒着 → awake唤醒，使醒', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (851, 'awful', '/ˈɔːfl/', 'awful.mp3', 'adj.糟糕的，讨厌的；极大的，极多的', 'fabb49664f491fef93eec1112f16015a_168741_1604910321.jpg', 'd_16_4392_0_2_20150808224215.png', 'There was an awful smell coming from the dustbin.', '垃圾箱里散发出一阵恶心的味道。', 'pjlwwrfxbuzquvbclud3ewbd42j8dd63.mp3', 'aw=awe敬畏 + ful形容词后缀 → 使人畏惧的 → awful糟糕的，可怕的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (852, 'beauty', '/ˈbjuːti/', 'beauty.mp3', 'n.美人；美丽的东西', 'i_1_7940_0_4_151019115022-gigapixel-scale.jpg', '', 'She is such a beauty that many people take pictures of her.', '她是个大美人，许多人为她拍照。', 'sa_1_7940_0_4_151029152236.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (853, 'bench', '/bentʃ/', 'bench.mp3', 'n.长凳；长形工作台', 'i_1_8042_0_8_160323161109-gigapixel-scale.jpg', '20141015_14_19_54_742_v3.png', 'There are many benches along the street.', '街道旁有很多长凳。', '1b7b3cb23c1a8cce_1266763243975650276_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (854, 'benefit from', '/ˈbɛnɪfɪt frəm/', 'benefit from.mp3', 'phr.得益于', '4d4406dbb3adc746212326622bbae6ac.jpg', '', 'Your body and mind can both benefit from a little exercise from time to time.', '时不时地做一些运动，你的身心都能受益。', '96b484443352de314399361f736c2947.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (855, 'blood', '/blʌd/', 'blood.mp3', 'n.血（液）；血统；  v.抽血', '533f3d74d2613d8524b15ad1e019d05c_84901_1574846102.jpg', 'd_16_18013_0_2_20150809013949.png', 'The doctor took some blood from me during my checkup.', '医生在给我检查时抽了点儿血。', 'a5028ea91ccd6bfa_1266883007041198676_250207.mp3', 'blo茁壮成长，绽放 + od → 富有生命力的事物 → blood血液', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (856, 'bore', '/bɔːr/', 'bore.mp3', 'v.使厌烦', '7f1654cb0f0eb64aa1ce39b123e645c4_120706_1522663162.jpg', '', 'The man\'s endless talking has bored his colleagues to sleep.', '这个男人冗长的讲话让同事们都厌烦得想睡觉了。', 'c0250d5d50cd56eec650cd87c33b4d71_40902_1522663120.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (857, 'break', '/breɪk/', 'break.mp3', 'v.打破，摔碎；  n.缝隙', '42a0aab817eab6a6459b0736e53438a2_197028_1604718372.jpg', 'd_93_11933_0_4_20150809001935.png', 'The football broke the glass into pieces.', '足球把玻璃打碎了。', 'b0e915b3cc2068bc353fc97ea2dc2c74_12427_1547607636.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (858, 'brick', '/brɪk/', 'brick.mp3', 'n.砖', '907cf25bcac2a0192e0200c72caef478_149009_1538659279.jpg', 'd_105_8440_0_2_20150809060952.png', 'The wall is made up of plenty of bricks.', '这面墙壁是用许多块砖头筑成的。', '3c6edbff5828552943544ab9383a8958_12271_1538659300.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
