INSERT INTO `words` VALUES (860, 'call out', '/kɔːl aʊt/', 'call out.mp3', 'phr.召集', '3e96a4dee8d0b2025c194ead6078a65e.jpg', '', 'Firefighters have been called out to the house fire.', '消防队员被召集来扑灭房屋大火。', 'cf02036a40b05c709fb354c4184e5916.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (861, 'candidate for', '/ˈkændɪdət fɔːr/', 'candidate for.mp3', 'phr. 候选人，申请者', 'b00fa9c27fcf82865cb6ce45d3f27abf.jpeg', '', 'There are three candidates for the general election.', '有三位候选人参加全国竞选。', '0c4df895303e5c131382b3acd849515d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (862, 'carbon', '/ˈkɑːrbən/', 'carbon.mp3', 'n.碳；复写纸；  adj.碳的', 'i_1_9121_0_3_20150808131224-gigapixel-scale.jpg', 'd_105_9121_0_2_20150809061312.png', 'Coal burns so easily because it contains lots of carbon.', '煤很容易燃烧是因为它含有大量的碳。', 'us_Coal_burns_20240510130726565_6c3d5e9639396c0b953a.mp3', 'carb碳 + on名词后缀 → carbon碳', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (863, 'carry', '/ˈkæri/', 'carry.mp3', 'v.运载；  n.运输，运送', 'i_16_18015_0_2_20150809013959-gigapixel-scale.jpg', 'd_68_12027_0_4_20150808234642.png', 'These two people can carry the big box together.', '这两个人可以合力搬动大箱子。', 'a1cb979aea977afc_1266883115626617562_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (864, 'cashier', '/kæˈʃɪr/', 'cashier.mp3', 'n.出纳员，收银员；  v.把……撤职；驱逐，革除，废除', 'a7df5ea5abc50ae879c9d08c96f203fd_107450_1535178517.jpeg', 'd_106_9015_0_2_20150809074858.png', 'The cashier at the supermarket is scanning each item.', '超市的收银员正在扫描每一件商品。', '49856acfe36973184662140059e72646_37654_1535178513.mp3', 'cash现金 + ier表名词，人或物 → 管理现金的人 → cashier出纳', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (865, 'cassette', '/kəˈset/', 'cassette.mp3', 'n.录像带，盒式磁带；磁带盒', 'i_1_6441_0_3_20150808125153-gigapixel-scale.jpg', 'd_105_6441_0_2_20150809055751.png', 'People used to play music with cassette tapes.', '过去人们都用磁带来播放音乐。', 'ldyhknwxsrjpq3ec9y269twc6nlbpmx9.mp3', 'cass=case盒子 + ette表名词  → 小盒子  → cassette录像带', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (866, 'cloudy', '/ˈklaʊdi/', 'cloudy.mp3', 'adj.多云的；混浊的', 'i_16_17154_0_4_151223152705-gigapixel-scale.jpg', 'd_24_17154_0_3_20150808232150.png', 'It\'s cloudy today', '今天多云，所以你看不见太阳。', 'cc29d13ec519a75e_1266763446478330526_250117.mp3', 'cloud云 + y...的 → cloudy多云的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (867, 'community', '/kəˈmjuːnəti/ ', 'community.mp3', 'n.群体，团体', '00436773220b1d3e641abad099b950e7_107331_1595919024.jpeg', 'd_107_9223_0_2_20150809024451.png', 'The largest Chinese community in this city lives in its Chinatown.', '唐人街里住着这座城市最庞大的华人群体。', '7937c8adbb7cff75_1266883490223795132_250207.mp3', 'com共同 + mun公共的 + ity状态 → 公共状态 → community社区', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (868, 'compare', '/kəmˈper/', 'compare.mp3', 'v.比较', '558788897532e9153be066dcb987fdbe_78993_1565687990.jpg', 'd_24_7110_0_4_20150808224935.png', 'It\'s smart to compare products when you go shopping.', '当你购物时，比较一下商品是很明智的。', 'e0964718a14d48d9_1266797979722361844_250123.mp3', 'com共同 + pare=par平等 → 平等放在一起 → compare对照；比较', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (869, 'complain', '/kəmˈpleɪn/', 'complain.mp3', 'v.抱怨，发牢骚', 'ef79e77fdd7a473adaf612095000d078_154683_1731900998.jpg', 'd_24_5780_0_4_20150808224340.png', 'The man complained about his neighbors being too noisy.', '这个男人抱怨他的邻居太吵。', '975d2b192ed7641b_1266883375409158746_250207.mp3', 'com共同 + plain抱怨 → 抱怨，诉苦；控告', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (870, 'conclude', '/kənˈkluːd/', 'conclude.mp3', 'v.推断出', '16d082b46875b75dda1a3a3ab4689c33_198884_1605165868.jpg', 'd_16_6115_0_4_20150808230149.png', 'The doctor concluded that she was not seriously ill', '医生推断她没什么大病，只是感冒了而已。', 'bfad496e188e5c4dbc363780a14ec0f9_35189_1621914393.mp3', 'con共同 + clude关闭 → 全部关闭 → conclude结束，总结', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (871, 'confused', '/kənˈfjuːzd/', 'confused.mp3', 'adj.困惑的，迷惑的；混乱的；  v.使困惑', '6b8cd688188ccb730ad9e1c1b111151d.jpg', '', 'I get confused when the two of you tell me different things.', '你们俩对我讲不同的事，我被搞糊涂了。', 'jdjt8hzgx69zu7t8q5hgbpkn6v7u34xq.mp3', 'con全部 ＋ fus流，泻 ＋ ed...的 → 全部流到一起 → confused困惑的，烦恼的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (872, 'congratulate', '/kənˈɡrætʃuleɪt/', 'congratulate.mp3', 'v.向（某人）道贺，祝贺', 'aa2c249591a0fed73efa0353de24886e_137184_1706683699.jpg', '20130105_10_17_47_974.png', 'My colleagues congratulated me on the promotion.', '我的同事们祝贺我升职了。', 'sa_1_8328_0_11_160224154621.aac', 'con和，一起 + gratulate致谢 → congratulate祝贺', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (873, 'congratulate on', '/kənˈɡrætʃəˌlet ɑn/', 'congratulate on.mp3', 'phr.为某事向某人祝贺', 'f188f82f2805eca3049374c8be480aaf.jpg', '', 'Everyone cheered and congratulated him on his victory.', '大家都在欢呼并祝贺他的胜利。', 'us_Everyone_cheered_20240927132849625_4236a3a2bc4c1d3a4071.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (874, 'conscious', '/ˈkɑːnʃəs/', 'conscious.mp3', 'adj.神志清醒的；意识到的；有意的', '0fa81fafa601ec9802f4df1c287bfa81_194751_1565690251.jpeg', 'd_1_3953_0_2_20150808122131.png', 'The patient was fully conscious hours after the operation.', '手术几小时后，这个病人完全清醒了。', 'df148cfa25ad5b8f83414b9a390262de_39410_1565690248.mp3', 'con全部 + sci知道 + ous形容词后缀 → conscious有意识的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (875, 'consent to', '/kənˈsɛnt tu/', 'consent to.mp3', 'phr.同意', '08905d6dbb8240a6ad7a9a77e9adc3d0.jpg', '', 'Her mother consented to her going on the roller coaster.', '她妈妈同意她去坐过山车。', 'f791d4c5d8d87f3a54b8195ed3c6c73f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (876, 'convenient', '/kənˈviːniənt/', 'convenient.mp3', 'adj.便利的，方便的，省事的', '2225d521bf6c5aa1e4c7881dacbc3f5e_63947_1706756646.jpg', 'd_24_9750_0_3_20150808230255.png', 'Utilities are convenient for everyone.', '公用设施为每个人提供了便利。', '25ea3c12a56d17fe_1266883197243120174_250207.mp3', 'con共同，全部 + ven来 + ient……的 → convenient便利的，近便的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (877, 'cooker', '/ˈkʊkər/', 'cooker.mp3', 'n.炉灶', '2798b0f3165d8ba3e9c5b3c3319b4b57_46046_1575014758.jpeg', 'd_109_19501_0_2_20150809063630.png', 'A cooker is a large device that uses gas or electricity to cook food.', '炉灶是一种用天然气或电烹饪食物的大型设备。', 'p3gknyhhrv46urb7r2fx77xkbcmc2dnj.mp3', 'cook烹饪 + er表示物 → 炊具', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (878, 'cooperate', '/koʊˈɑːpəreɪt/', 'cooperate.mp3', 'v.合作', '63104b6c9b54b378fabf0991367f7c2d_171515_1541662218.jpeg', '20141014_22_43_32_302_v3.png', 'Baicizhan cooperated with a famous brand to co-brand these new T-shirts.', '百词斩和某个著名的品牌合作推出了这些新款联名T恤。', 'c44c122d0673a700ccdc6c2e665abc9e_39413_1552553032.mp3', 'co共同 ＋ oper工作 ＋ ate使 → cooperate共同工作', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (879, 'copper', '/ˈkɑːpər/', 'copper.mp3', 'n.铜；铜色', '8dadd0f17df4e7438b80b437973fa494_81314_1565623233.jpg', 'd_108_6263_0_2_20150809042153.png', 'Chinese ancient coins were made of copper.', '中国古代钱币是铜做的。', 'b0f56c74d3396d5f_1266883614882552486_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (880, 'corridor', '/ˈkɔːrɪdɔːr/', 'corridor.mp3', 'n.走廊，回廊，通道；（沿着重要道路或河道的）狭长地带', '72b184ebb6410219d5fce33732b7f516_132692_1552896755.jpeg', '20140926_03_58_34_396_v3.png', 'The doctors and nurses are talking in the corridor.', '医生和护士正在走廊里谈话。', 'df85c9c85c62fabad07c372881a118e9_45767_1552896761.mp3', 'corr走 + idor表物 → corridor 走廊，回廊，通路', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (881, 'court', '/kɔːrt/', 'court.mp3', 'n.法院，法庭；球场；  v.招致灾祸', 'd4ba6f27ab28cc9ced716b577b11d3ac_173485_1700186734.jpeg', 'd_24_8465_0_4_20150808225732.png', 'The aim of the court is to provide justice.', '法庭致力于伸张正义。', 'us_The_aim_20231117100539023_655697b5484bd331a706.mp3', 'com一起 + hort庭院 → 一起聚集在庭院中 → court法院；法庭', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (882, 'customer', '/ˈkʌstəmər/', 'customer.mp3', 'n.顾客', '34014265ac2bd736b1cab17284201bd6_344715_1612143809.jpg', 'd_24_16062_0_4_20150808231117.png', 'Would the customer buy this pair of blue jeans?', '这个顾客会买这条蓝色的牛仔裤吗？', 'a1a30cdc4f1c2e89_1266883195708287748_250207.mp3', 'custom习惯 + er人 → 习惯进商店的人 → customer顾客', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (883, 'data', '/ˈdeɪtə/', 'data.mp3', 'n.数据；资料', 'i_1_8086_0_6_150928154914-gigapixel-scale.jpg', 'd_1_8086_0_3_20150808130404.png', 'A huge amount of data can be stored on a computer.', '一台电脑可以储存大量数据。', '548e207c02e373d18a0ecfa67c445123_18227_1595582099.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (884, 'dead', '/ded/', 'dead.mp3', 'adj.死的，无生命的', 'i_16_17615_0_5_160426125839-gigapixel-scale.jpg', 'd_24_17615_0_3_20150808233030.png', 'The fish is dead.', '这条鱼死了。', 'c11a73d7c73d73ba_1266797982324447758_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (885, 'defend', '/dɪˈfend/ ', 'defend.mp3', 'v.保卫，防守', 'a2aa13a05299c335b801eb514e37f174_84786_1617776947.jpg', 'd_24_8423_0_4_20150808225707.png', 'The three sheep worked together to defend against the wolf.', '这三只小羊齐心协力防御了大灰狼的攻击。', '727907fff1eb835d4acf8f240c50fdc3_26921_1621931540.mp3', 'de去掉 + fend打击 → 打退敌人 → defend保卫，防御', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (886, 'departure from', '/dɪˈpɑrtʃər frəm/', 'departure from.mp3', 'phr.离开；离职；背离', '5ef681ad8a4fd0ad80585501faf034ae.jpeg', '', 'In a departure from his usual choice', '不同于以往的选择，这次他点了米饭。', '412b9921d300f05594f260f80ac51888.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (887, 'disappear', '/ˌdɪsəˈpɪr/', 'disappear.mp3', 'v.消失', 'i_1_5745_0_4_151109153740-gigapixel-scale.jpg', 'd_24_5745_0_3_20150808224324.png', 'How amazing it is that he can make a bird disappear!', '他能把一只鸟变没了，真是太神奇了！', '83267e437242472c_1266883199597128524_250207.mp3', 'dis否定 + appear出现 → disappear消失', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (888, 'district', '/ˈdɪstrɪkt/', 'district.mp3', 'n.地区', 'i_16_4992_0_4_151210152451-gigapixel-scale.jpg', 'd_24_4992_0_3_20150808223800.png', 'The city is made up of four districts.', '这座城市由四个区域组成。', 'sqkwszflggjxdw5cmwfvrgk3vtvkak2s.mp3', 'di分开 + str拉紧 + ict  → 把一块区域分开  → district地区，区域', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (889, 'divide', '/dɪˈvaɪd/', 'divide.mp3', 'v.分开，划分；除以；除', 'i_1_5092_0_4_150924173942-gigapixel-scale.jpg', 'd_24_5092_0_3_20150808223915.png', 'The apple is divided into two equal parts.', '这个苹果被平分成了两半。', 'cqxb9zqdu9qbpgyypkwtm5prbfmqehwb.mp3', 'di分开 + vide分开 → 分开 → divide分开', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (890, 'domestic', '/dəˈmestɪk/', 'domestic.mp3', 'adj.国产的；国内的；家庭的；驯养的；  n.家仆；家庭纷争', '1423912419951-gigapixel-scale.jpg', '', 'I am a big fan of domestic products.', '我是国货的铁杆粉丝。', 'sa_1_5543_0_2_20150808123943.aac', 'domes屋，家 + tic形容词后缀 → 家里的 → domestic家里的；国内的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (891, 'downstairs', '/ˌdaʊnˈsterz/', 'downstairs.mp3', 'adv.在楼下，往楼下；  adj.楼下的', 'i_24_17107_0_5_151222175329-manual-scale.jpg', 'd_24_17107_0_3_20150808232023.png', 'They are running downstairs.', '他们跑着下楼。', 'a37fcea5267a449a_1266763242625608638_250117.mp3', 'down向下 + stairs楼梯 → downstairs楼下的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (892, 'draw on', '/drɔː ɑːn/', 'draw on.mp3', 'phr.利用', 'e2bd28b8129b00b2d172b4999a2deb7f.jpg', '', 'The older boy can draw on his past experience to help his little brother.', '哥哥可以利用过去的经验来帮助弟弟。', '8041b2be0251cb9c8681b11a12b21960.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (893, 'due', '/duː/', 'due.mp3', 'adj.到期的；适当的；拖欠的；  n.应有的权利', 'due_3877_20231106_a0d605f4.jpg', 'd_16_3877_0_2_20150808223745.png', 'March 3rd is the due date to pay for my VIP account.', '3月3日是到期的日子，我得给我的VIP账户充值。', 'sa_1_3877_0_4_151106173012.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (894, 'enter', '/ˈentər/', 'enter.mp3', 'v. 走进；  n.输入', 'c64a20b6cc56f689440c08f2cda7fa90_131186_1574997670.jpeg', 'd_24_19564_0_3_20150809002020.png', 'Two men and a woman are entering the building.', '两男一女正在走进大楼。', 'u4dnxv7q2ryf2s2ce8s8b58u5mumglmu.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (895, 'enthusiasm for', '/ɪnˈθuːziæzəm fɔr/', 'enthusiasm for.mp3', 'n.热情，热忱', '700283bd7d9f85ffa1b777d32129013f.jpeg', '', 'He has great enthusiasm for jazz.', '他对爵士乐抱有极大的热情。', '81761a6bbee97ef82f3444afb2d6b2bc.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (896, 'equip', '/ɪˈkwɪp/', 'equip.mp3', 'v.装备；使有能力', '4ed4978bd22d67f6f4c346aec07af4e2_193876_1538666271.jpg', 'd_107_8372_0_2_20150809023202.png', 'The worker equips himself with several items.', '这名工人身上装备了好几样东西。', 'faf9a32756427e891a5ef750658d7d5c_14151_1538666305.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (897, 'even', '/ˈiːvn/', 'even.mp3', 'adj.实力相当的', '45db1d97b3ce1a3af8efd415f0adea74_193778_1577946274.jpeg', 'd_24_17923_0_3_20150808233514.png', 'It was an even match so neither side could defeat the other.', '这是一场势均力敌的比赛，因此谁也没法打败对方。', '90e18d5499c082501a517e39c8b6a529_45238_1577946271.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (898, 'examine', '/ɪɡˈzæmɪn/ ', 'examine.mp3', 'v.检查；测验', 'd3db98a73cded8a18440930ac82d96dc_78949_1565342867.jpg', '20141012_10_16_06_213_v3.png', 'I took my dog to the vet to be examined.', '我带我的狗去兽医那里检查。', '44f9e8c6115f4d5e_1266883478605159082_250207.mp3', 'ex向外 + act做，驱使，称量 → (拼写受example影响) → examine检查，测验', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (899, 'excite', '/ɪkˈsaɪt/', 'excite.mp3', 'v.使激动，使兴奋', '1816ca86384a6ea4920046021718f1f5_107509_1538639830.jpg', 'd_24_8000_0_3_20150808225332.png', 'The message she received excited her.', '她收到的信息让她很激动。', '0a60e62b0be6cd1db4c616d937993e45_41120_1597656235.mp3', 'ex使…出自 + cite使开始工作 → excite激发', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (900, 'exciting', '/ɪkˈsaɪtɪŋ/', 'exciting.mp3', 'adj.使人激动的；令人兴奋的', '3_0_20170609071100_94982_c-gigapixel-scale.jpg', 'd_24_5177_0_4_20150808224009.png', 'How exciting! Our team won!', '太令人激动了！我们队赢了！', 'bgckpgt9tvrdz58v6hqkc273mgufwv8p.mp3', 'excit使兴奋 + ing形容词后缀 → exciting使人兴奋的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (901, 'expose to', '/ɪkˈspoz tu/', 'expose to.mp3', 'phr.面临，暴露', '3b601f929ee7c8efdebc873276403248.jpg', '', 'He exposed himself to the virus by not wearing a mask.', '他没有戴口罩，因而让自己暴露在病毒环境中。', '61fa6780b7bcf659c0e8aa49261f7cc3_22772_1619171843.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (902, 'fair', '/fer/', 'fair.mp3', 'adj.合理的，公平的；相当的，尚好的；  n.集市，市场，交易会', 'daa512226814513c088bf80c4d11ceb1_177925_1619172474.jpg', 'd_24_18880_0_4_20150808235845.png', 'Compared to that on the left', '相比左边的饮料，右边的饮料售价更合理。', '6cfb2b821f0933597f67a131b1ba642e_49352_1603273651.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (903, 'favor', '/ˈfeɪvər/', 'favor.mp3', 'v.偏爱；  n.偏爱（=favour）', '3_0_20170928071515_81446_c-gigapixel-scale.jpg', 'd_24_10586_0_3_20150808230441.png', 'I need to become more healthy', '我需要变得更健康，所以比起汉堡，我更偏好苹果。', 'us_I_need_20240222145811402_14d1d0fb65c1b898fcbf.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (904, 'festive', '/ˈfestɪv/', 'festive.mp3', 'adj.庆祝的，喜庆的，欢乐的，节日似的', 'festive_1163_20231106_865f507c.jpg', '20140727_04_33_57_6_v3.png', 'The festive atmosphere was enhanced by the brilliant firework display.', '绚丽烟花的绽放增强了节日的喜庆气氛。', '3_0_20160910070620_33773_c.aac', 'fest节目+ive...的 → 表演节目的日子 → 节日 → 节日的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (905, 'fix', '/fɪks/', 'fix.mp3', 'v.修理；  n.方位确定，定位', 'i_24_16637_0_5_151222151923-gigapixel-scale.jpg', 'd_93_12718_0_4_20150809002027.png', 'He is fixing the car.', '他在修车。', 'sa_24_16637_0_5_151224133208.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
