INSERT INTO `words` VALUES (915, 'growth', '/ɡroʊθ/', 'growth.mp3', 'n.生长，成长，增长', '4a54a154e13995e996a7aa81b5248207_186275_1535527509.jpeg', 'd_24_8264_0_4_20150808225545.png', 'The marks on the wall show the growth of the girl.', '墙上的标记展现了女孩的成长。', 'ec0401f2930508866dd458dbf9e53408_32956_1535527505.mp3', 'grow成长 + th名词后缀 → growth生长，增长', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (916, 'hammer', '/ˈhæmər/', 'hammer.mp3', 'n.锤子；  v.锤击', 'c_i_wm_20150612_144455_1_7010-gigapixel-scale.jpg', 'd_16_7010_0_2_20150808231421.png', 'I used a big hammer to push in the nail.', '我用锤子来把钉子敲进去。', 'f372c06324494e4c_1266883525621733966_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (917, 'hardship', '/ˈhɑːrdʃɪp/', 'hardship.mp3', 'n.艰难，困苦', '8ec5d16de577c4813ce2922f7b18bbf4_138656_1605172785.jpg', 'd_105_1371_0_2_20150809053153.png', 'He\'s currently suffering severe financial hardship.', '他当下正面临着严重的经济困难。', '3_0_20170709071357_81143_c.aac', 'hard艰难的 + ship表情况 → 苦难', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (918, 'harm', '/hɑːrm/', 'harm.mp3', 'n.伤害，损害；  v.伤害', 'e1ea1b30f2506e9ae4e37a3b65da2c58_29912_1656929334.jpg', 'd_24_6152_0_4_20150808224451.png', 'Eating too much sweet food does harm to your teeth.', '吃太多甜食对你的牙齿有害。', 'tcrqcznqw3axbkhgn9ca3x7ykrf2zb4x.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (919, 'hopeful', '/ˈhoʊpfl/', 'hopeful.mp3', 'adj.怀有希望的', 'af88c3a8a29957995a76b6db90d3ba72_148488_1587090827.jpeg', 'd_24_7257_0_4_20150808225048.png', 'She gives a hopeful smile before the result is announced.', '结果出来之前，她带着满怀希望的笑容。', '75d8e66cac2535b25c5f274169242662_36330_1587090824.mp3', 'hope希望 + ful形容词后缀 → hopeful有希望的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (920, 'hospital', '/ˈhɑspɪtl/', 'hospital.mp3', 'n.医院', '6b9f256c53d761d4125ce5b43595559a_113319_1522830148.jpg', '20121225_20_14_27_398.png', 'The patient was taken to the hospital for treatment.', '病人被带进医院进行治疗。', '746a771bc3d843be_1268213313387381424_250930.mp3', 'hospit客人 + al名词词尾 → 客气对待病人的地方 → hospital医院', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (921, 'improve', '/ɪmˈpruːv/', 'improve.mp3', 'v.提高；改进，改善', '6de0d4cf1f695b46099ac09d0d34da42_168401_1605169056.jpg', 'd_24_5033_0_4_20150808223837.png', 'The grades show that her English has improved a lot.', '这些分数说明她的英语提高了很多。', '8djhcudpmb4na3jppzp5hkqbzm84xn8d.mp3', 'im强化前缀 + prove利润，有利 → 增加有利之处 → improve提高，改善', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (922, 'in proportion to', '/ɪn prəˈpɔːrʃən tu/', 'in proportion to.mp3', 'phr.与……成比例', '603096f85e854be2428f7730a293081b.jpeg', '', 'These employees are paid in proportion to how many years of experience they have.', '这些员工的工资与他们有多少年的工作经验成比例。', 'f5d7cc8627c392a53dcc7d365e5aed3b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
