INSERT INTO `words` VALUES (925, 'inevitable', '/ɪnˈevɪtəbl/', 'inevitable.mp3', 'adj.不可避免的，必然的', 'b2d9c998d521f1eeae7c1adf1e1f1a02_68965_1726639295.jpg', 'd_107_2692_0_2_20150809002949.png', 'It is inevitable for people to get old.', '人变老是不可避免的。', 'sa_1_2692_0_3_20150808121913.aac', 'in不 + evit避免 + able形容词后缀', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (926, 'instinct', '/ˈɪnstɪŋkt/', 'instinct.mp3', 'n.本能，天性；天分，天资；直觉', 'i_1_5443_0_2_20150808123845-gigapixel-scale.jpg', 'd_1_5443_0_2_20150808123845.png', 'Even well-fed cats will kill mice because of their hunting instincts.', '即使喂得很饱的猫也会捉老鼠，因为它们有捕食老鼠的天性。', 'sa_1_5443_0_2_20150808123845.aac', 'in内 + stinct刺激 → 内在的刺激 → instinct本能 ', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (927, 'institution', '/ˌɪnstɪˈtuːʃn/', 'institution.mp3', 'n.机构；制度；惯例；习俗', '7dc29108029d724ef601e047ae083488_100488_1586855860.jpeg', 'd_16_5551_0_5_20150808225427.png', 'This English language training institution is very popular with parents and their children alike.', '这家英语培训机构很受家长和孩子们的欢迎。', 'aceac3a76a9fa4ec5e462fe7b0f79944_32176_1619316555.mp3', 'in在......里 + stitut建立 + ion名词后缀 → institution机构', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (928, 'instrument', '/ˈɪnstrəmənt/ ', 'instrument.mp3', 'n.乐器；工具', 'c5ab7b76dfdb50c7405fba86cc14436a_92391_1595927754.jpg', 'd_24_6131_0_4_20150808224441.png', 'Guitar', '吉他、小提琴、鼓和钢琴都是乐器。', 'fvdwqtlwnlxjsjkgd8cdr38k3jfwcfqe.mp3', 'in内 + stru=struct建立 + ment表名词 → 内部结构 → instrument仪器；工具', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (929, 'intelligence', '/inˈtelɪdʒəns/', 'intelligence.mp3', 'n.智力；理解力；情报', '33c4069e0a0fd7547d22b11a9b7a5077_77954_1704700249.jpg', '20130130_16_11_19_798.png', 'Einstein was a man of great intelligence.', '爱因斯坦是一个智商很高的人。', 'ca9vapguu9gawrwlbnkzmpmfhb5mgaxu.mp3', 'intel在…中间 + lig选择，收集 + ence名词后缀 → 从中选出好的 → 智力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (930, 'international', '/ˌɪntərˈnæʃnəl/', 'international.mp3', 'adj.国际的，世界的', '0b9978aa78a422df3412f6bd27d0e578_148974_1701672863.jpeg', 'd_24_7882_0_4_20150808225159.png', 'All of them are international students from different countries.', '他们都是来自不同国家的国际学生。', '10628fcd347a9865_1266763445327342460_250117.mp3', 'inter在…之间，相互 + national国家的 → international国际的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
