INSERT INTO `words` VALUES (932, 'kindness', '/ˈkaɪndnəs/', 'kindness.mp3', 'n.亲切；友好行为', '6f3f9a5aae2062bdcb183a9030ba2a17_91111_1565342795.jpg', 'd_24_6781_0_3_20150808224755.png', 'She showed kindness to her cat.', '她对她的猫很亲切。', 'sa_1_6781_0_2_20150808125455.aac', 'kind仁慈的 + ness表名词 → kindness仁慈', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
