INSERT INTO `words` VALUES (944, 'neck', '/nek/', 'neck.mp3', 'n.脖子，颈；  v.搂脖子亲嘴；  v.（与……）搂着脖子亲吻', '60f1ae777082f555ac4c5d8c10ca37db_169863_1739345671.jpg', 'd_95_13521_0_4_20150809012811.png', 'Duck neck is so spicy and yummy.', '鸭脖又辣又好吃。', 'v2rdgf5nygnk3gnp4qyrvnn4lwzd53w3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (945, 'on account of', '/ɑːn ə\'kaʊnt əv/', 'on account of.mp3', 'phr.因为', 'onaccountof_6086_20231106_1b4a3d5d.jpg', '', 'He crashed his car again on account of his drinking.', '因为喝酒，他又撞坏了他的汽车。', '3_72_20170930175030_11564_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (946, 'on condition that', '/ɑːn kənˈdɪʃn ðət/', 'on condition that.mp3', 'phr.如果', '3d147344124ef1b001fadf370196fb5f_155465_1596445675.jpeg', '', 'He\'ll go to the party on the condition that his friend wears the funny trousers.', '如果他的朋友穿上那条搞笑的裤子，他就会去参加派对。', '6651066dc3dc6d85c1f1c660e40a0ad3_32849_1621930677.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (947, 'on one\'s guard', '/ɑːn wʌnz ɡɑːrd/', 'on one\'s guard.mp3', 'phr.警惕', '3385de4f550c9ddbf4bdb54c870dbc04.jpeg', '', 'A strange noise coming from the bushes put him immediately on his guard.', '灌木丛里传来的奇怪声响使他立即警惕了起来。', 'd8321c05d7dbce71052cb67f52088e8b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (948, 'on second thoughts', '/ɑːn ˈsekənd ˈθɔːts/', 'on second thoughts.mp3', 'phr.经重新考虑', '48edd7b048cd802675ff51047ef50fd5.jpeg', '', 'He was about to choose A', '他本来要选A，经重新考虑后，他选了C。', '42cda69f2849acbb_1266883628082899802_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (949, 'otherwise', '/ˈʌðərwaɪz/', 'otherwise.mp3', 'adv.否则', '576259d9b0009a26f40a65ec913b9a15_112864_1538649399.jpg', '20121225_19_52_54_533.png', 'Take care! Otherwise you will fall down!', '小心！不然你会摔倒！', '83aa834fb8c941e88c3b25ecbca43e3d_15719_1538649432.mp3', 'other另外的 + wise方向，状态 → otherwise要不然', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (950, 'out of place', '/aʊt əv pleɪs/', 'out of place.mp3', 'phr.不合适的', '1ee544fac0ce1cd978633cc1ddfaff51.jpeg', '', 'This book is obviously out of place.', '这本书显然放错位置了。', 'cd46cc94b7cab200a92d30163b880b11.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (951, 'overcoat', '/ˈoʊvərkoʊt/', 'overcoat.mp3', 'n.长大衣', 'i_13_17126_0_2_20150808204425-gigapixel-scale.jpg', 'd_24_17126_0_4_20150808232051.png', 'This overcoat keeps me warm and comfortable in winter.', '这件大衣让我冬天保持温暖和舒适。', 'd3a2bc440c430706e66aa6f9a6b59d14_19481_1619333364.mp3', 'over在上，在外 + coat衣服 → 在衣服上的衣服 → overcoat外套', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (952, 'own', '/oʊn/', 'own.mp3', 'v.有，拥有', '2cb99327343ed725d0ab88c28cb6e5ad_99972_1604299844.jpg', 'd_24_17368_0_4_20150808232745.png', 'This boy once owned a black cat.', '这个男孩曾经拥有一只黑色的猫。', '1_-1_20160421163342_38742_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (953, 'paper', '/ˈpeɪpər/', 'paper.mp3', 'n.纸；试卷，论文；  v.贴墙纸', 'i_13_17973_0_3_20150808205207-gigapixel-scale.jpg', '20121225_19_55_07_642.png', 'I like to make notes on a small piece of paper.', '我喜欢在小纸片上做笔记。', 'ddabab392ff8c774_1266763445488298884_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (954, 'partly', '/ˈpɑːrtli/', 'partly.mp3', 'adv.部分地，在一定程度上', '0109fcf8c54a1286a506cbb1119c3d08_49216_1522723554.jpg', 'd_16_5047_0_2_20150808224853.png', 'This droid is partly functional having lost an arm.', '失去了一只手臂，这个机器人只有部分功能可用了。', '8sq5yz8myh2wmpkxhqngn56cgqk99dmy.mp3', 'part部分 + ly表副词 → partly部分地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (955, 'passive', '/ˈpæsɪv/', 'passive.mp3', 'adj.被动的；消极的；  n.被动语态', '1e2e37c3f926f807e46c076dab1f732f_176369_1586424203.jpg', 'd_13_11462_0_2_20150808202939.png', 'Passive smoking causes great harm to children and pregnant women.', '被动吸烟会对儿童和孕妇造成很大的伤害。', '3_0_20170928071324_16324_c.aac', 'pass忍受，受苦 + ive表形容词 → passive消极的；被动的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (956, 'performance', '/pərˈfɔrməns/', 'performance.mp3', 'n.表演，演出；表现；执行；性能', '8364703d5eb1b904f24db98517cc8659_120302_1573808243.jpeg', '20130301_12_58_40_241.png', 'Their music was great. I really loved the performance.', '他们的音乐听起来很棒，我很爱这场演出。', 'a2dd5f5e3659bc51a7f7128895f82aef_20891_1597830546.mp3', 'perform表演 + ance表名词 → performance表演', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (957, 'poster', '/ˈpoʊstər/', 'poster.mp3', 'n.海报', '1f5ec7c07329f31cf5643d2f4035c32b_64051_1656921021.jpg', '20141011_13_30_35_664_v3.png', 'They are hanging up a poster.', '他们正在挂一张海报。', '93f3be4122cef387_1266798139116006284_250123.mp3', 'post招贴，海报 + er名词后缀 → poster招贴画，海报', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (958, 'preliminary', '/prɪˈlɪmɪneri/', 'preliminary.mp3', 'adj.初步的，预备的；  n.预赛；预考，初试；初步措施', '7ef5a391f7db7427bb71eeaf211e25bb_91745_1569036207.jpg', 'd_1_4032_0_7_150906163008.png', 'The preliminary drawings of the building are already finished.', '建筑的初步图稿已经完成。', 'us_The_preliminary_20230406103554400_b86e1c24d6fbb0175d51.mp3', 'pre预先 + limin门槛，限制 + ary形容词后缀 → 入门以前 → preliminary初步的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (959, 'prevent from', '/prɪˈvent frɒm/', 'prevent from.mp3', 'phr.阻止，制止', '61b3f03e019944d785db4de104e15dad.jpg', '', 'He wears a mask to prevent himself from catching the virus.', '他戴着口罩以防感染病毒。', 'bbdb622f1471b589c435c6c8d526593d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (960, 'primary', '/ˈpraɪˌmeri/', 'primary.mp3', 'adj.初等教育的；最初的；首要的；  n.首选；<美>初选', 'i_16_4970_0_4_151117190132-gigapixel-scale.jpg', 'd_24_4970_0_3_20150808223741.png', 'Children usually go to primary school at the age of 6.', '通常小孩子6岁就上小学了。', 'sa_16_4970_0_4_151217151826.aac', 'prim第一，主要的 + ary形容词后缀 → 第一的，最开始的 → primary最初的；根本的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (961, 'primitive', '/ˈprɪmətɪv/', 'primitive.mp3', 'adj.原始的；简陋的；  n.原始人', '3465a2af3ca164dd28759d6345968806_242720_1728454123.jpg', '20140926_21_29_06_808_v3.png', 'Primitive men made fire by themselves since they had no electricity.', '原始人没有电，只能自己生火。', 'c_sa_4064_1_0_6_150810171735.aac', 'prim=prime最初的，原始的 + itive形容词后缀 → primitive原始的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (962, 'principle', '/ˈprɪnsəpl/', 'principle.mp3', 'n.原则', 'i_1_7113_0_2_20150808125754-gigapixel-scale.jpg', 'd_16_7113_0_2_20150808231456.png', 'Our business success is based on four fundamental principles.', '我们生意的成功基于四项基本原则。', 'sa_1_7113_0_2_20150808125754.aac', 'prin第一，首要 + ciple拿，抓紧 → principle原则', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (963, 'provide', '/prəˈvaɪd/', 'provide.mp3', 'v.提供，供给', 'a0bdb5423d4b9df9f9da382f62109db4_177387_1535083364.jpeg', '20121227_14_04_24_187.png', 'This restaurant provides free juice.', '这家餐厅提供免费果汁。', '4265413d9c78fe309b00b30fadcbedff_30346_1535083359.mp3', 'pro提前 + vid看 + e → 提前看好 → provide预备；提供', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (964, 'public', '/ˈpʌblɪk/', 'public.mp3', 'adj.公共的；公然的；  n.公众，民众', '1691006137af5d66738ef56a094451f1_162874_1573717595.jpeg', 'd_94_13860_0_4_20150809010216.png', 'There are many non-smoking signs in public places.', '公共场所有许多禁烟标志。', '53117f0796fc528e_1266883007981595510_250207.mp3', 'publ人民 + ic...的 → public公开的，公众的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (965, 'qualified for', '/ˈkwɑːlɪfaɪd fɔːr/', 'qualified for.mp3', 'phr.适于作(有担任...的资格)', '04dba8b956ee233930f30f87ba9396d4.jpeg', '', 'From the three applicants', '在三名申请者中，他被认为是最有资格胜任这项工作的。', 'e5fb11f2a57fe66ef85d306902f3dbc2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (966, 'quick', '/kwɪk/', 'quick.mp3', 'adj.迅速的，快捷的', '21bfd17ec4d6a8fdcbacff31c639664a_250266_1738995119.jpg', '20121225_20_04_04_312.png', 'The rescue team were quick to save people from the earthquake.', '搜救队迅速救援地震中的人们。', 'cca9b1ca80d45771_1266883010359876306_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (967, 'read of', '/riːd əv/', 'read of.mp3', 'phr.从报刊上了解到', '3dec2cc12defd028fa045d94db460236.jpeg', '', 'He read of the traffic accident in the newspaper. ', '他从报纸上知道了这起交通事故。', '5c89349a8c6ba69fad937b71483fc86c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (968, 'receive', '/rɪˈsiːv/', 'receive.mp3', 'v.收到，得到', '5084f4c32374a1a4b0246b3969c2a3f9_60788_1617764357.jpg', 'd_95_13924_0_4_20150809012843.png', 'I received a thank-you note from my good friend.', '我从好朋友那里收到了一张感谢卡。', 'euuwyarbb2r2l43dvjv4shqpt9fm2qfs.mp3', 're再 + ceiv抓，拿 + e后缀 → 再次拿到 → receive得到，收到', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (969, 'record', '/riˈkɔrd/', 'record.mp3', 'v.录制；  n.记录', '9f0f6c0f4477caaa4a38d6f5e58dc33d_85960_1617763149.jpg', 'd_24_8098_0_3_20150808225439.png', 'They record themselves dancing on the stage.', '她们用摄像机录制自己跳舞的过程。', 'uflqczw684yl7h62rs6kdjwyqm698kn3.mp3', 're再 + cord心脏 → 一再放在心上 → record记录', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (970, 'relate to', '/rɪˈleɪt tu/', 'relate to.mp3', 'phr.与...有关', 'f26f92e328379d29cdf5435c94387780.jpeg', '', 'A lot of people\'s favorite summer activities seem to relate to water. ', '许多人最喜欢的夏日活动似乎都和水有关。', '594c880b9a051d9d880f9f03a456ce41.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (971, 'representative of', '/ˌreprɪˈzentətɪv əv/', 'representative of.mp3', 'phr.表示（代表……的特征）', 'cca1689c0a57a0fc6343886145a0422d.jpeg', '', 'Mr. Milk', '牛奶先生是该饮料集团的代表，他正在食品大会上发表演讲。', '4396e57e9d352a7fc4ed71f7b7b7986c_44590_1599622213.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (972, 'resistant', '/rɪˈzɪstənt/', 'resistant.mp3', 'adj.有抵抗力的', 'i_1_6772_0_4_20150808125453-gigapixel-scale.jpg', 'd_105_6772_0_2_20150809060020.png', 'This watch is resistant to water.', '这块手表具有防水性能。', '04a6f5dd8bc4417030399727d10a84f0_12271_1597651771.mp3', 're向后，相反 + sist站 + ant…的 → 站在反方向上 → resistant抵抗的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (973, 'review', '/rɪˈvjuː/', 'review.mp3', 'v.复习；回顾；  n.复习', '3ad3c3471d04001e9bcf4f689a8b689a_183194_1733203298.jpg', 'd_24_4360_0_3_20150808223510.png', 'The girl is reviewing her homework for tomorrow\'s important test.', '那个女孩在为明天的重要考试复习。', 'b83t9fmpw6526pyaahcl395m32wzkncg.mp3', 're再、重复 + view看 → review再检查，复习', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (974, 'run out of', '/rʌn aʊt ɒv/', 'run out of.mp3', 'phr.用完', '0ea0cd9e186719e59247305a11806d26_159990.jpg', '', 'I have completely run out of money.', '我把钱花光了。', '8d58364a031cadd80d6b0e539ea84543_30271.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (975, 'salt', '/sɔːlt/', 'salt.mp3', 'n.盐，食盐；  adj.含盐的，腌制的；  v.加盐于，用盐腌', '9dd24f8a752bcf409089f070889746e4_143620_1549957388.jpeg', 'd_24_18142_0_3_20150808234943.png', 'Adding salt gives the dish more flavor.', '加盐可以让菜肴更有滋味。', '1591a26feab621ea_1266883013850454544_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (976, 'scan', '/skæn/', 'scan.mp3', 'v.扫描；细看；  n.浏览', '0a87513c7068ac0b2e161fa35fc8fc47_198848_1579340129.jpeg', 'd_16_4097_0_2_20150808224018.png', 'He is scanning the Chinese character for collecting cards.', '他正在扫描这个汉字来集卡。', 'us_He_is_20241009154114201_e756026961f755cab5f8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (977, 'scare', '/sker/', 'scare.mp3', 'v.使害怕，惊吓；  n.惊恐，恐慌', '4fd006edf16251379247e0d701933793_136982_1529379501.jpeg', '20141012_10_18_07_52_v3.png', 'The one thing that scares me most is giant mice.', '最让我害怕的一样东西就是巨大的老鼠。', '8f8f3c6aedf2ff3f0c26ae8206b9f110_41432_1576144637.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (978, 'select', '/səˈlekt/', 'select.mp3', 'v.选择，挑选；  adj.精选的，选择的', '26615267cce547213be72e8c7ddf0554_151644_1722233507.jpg', 'd_16_5031_0_2_20150808224834.png', 'Which dress do you think I should select?', '你觉得我应该选哪条裙子？', '2329c39e23f24cf3_1266883478730463916_250207.mp3', 'se分开 + lect选 → 选出分开 → select选择', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (979, 'sequence', '/ˈsikwəns/', 'sequence.mp3', 'n.顺序，次序；一系列，一连串', '177684abeb19debf1a80ba405f6e0599_102637_1730085528.jpg', 'd_1_5654_0_2_20150808124149.png', 'Arrange the files in sequence.', '按顺序排列文件。', 'us_Arrange_the_20241028111834079_28f143cd55d47d87afc4.mp3', 'sequ跟随 + ence名词后缀 → sequence连续发生，连续', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (980, 'shall', '/ʃæl/', 'shall.mp3', 'v.提供建议或征求意见，要不要？', '3_0_20170703171759_66733_c-gigapixel-scale.jpg', '', 'Shall we dance together?', '我们一起跳个舞吧？', 'ua5hbtj6bltjg48tae6b8utcbpcb2wpa.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (981, 'silly', '/ˈsɪli/', 'silly.mp3', 'adj.傻的，愚蠢的；  n.（通常指小孩子）淘气鬼；傻孩子', '27294a08be0564c56faf6757d0c826e8_128844_1538648661.jpg', '20140929_02_52_53_317_v3.png', 'He looks so silly with his head in his clothes.', '他把头缩进衣服里，看起来真傻。', 'e09dca2e77614432_1266763243153218240_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (982, 'skilled', '/skɪld/', 'skilled.mp3', 'adj.熟练的，有技能的；需熟练技术的', '3_0_20170928071501_21305_c-gigapixel-scale.jpg', 'd_107_8054_0_2_20150809022721.png', 'The man is skilled at dealing with all kinds of things.', '这个男人可以熟练地处理各种事务。', '3_0_20170928071501_15400_c.aac', 'skill技术 + ed有……的 → 有技术的 → 熟练的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (983, 'sock', '/sɑːk/', 'sock.mp3', 'n.短袜；  v.重击', '6b4e936c8e0f652d4940c5eb790a34dc_87336_1535955294.jpeg', 'd_16_18163_0_2_20150809014824.png', 'She is wearing socks of two different colors on her feet.', '她脚上穿着两只不同颜色的袜子。', '137dd50c5b6f6766_1266763240298207852_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (984, 'solve', '/sɑːlv/', 'solve.mp3', 'v.解决，处理', '78df51ccc0bdba86138e88243cf9242f_128555_1684117255.jpg', 'd_24_8442_0_3_20150808225723.png', 'He helped the girl solve the math problem.', '他帮女孩解答了这道数学题。', 'b9b2631e0dec58dd803e245d871441b8_14622_1620267304.mp3', 'so反身代词 + lv松开，分开 + e → solve解决', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (985, 'soul', '/soʊl/', 'soul.mp3', 'n.灵魂；中心人物；  adj.熟悉黑人的', 'f883f4cf51d22dd0dfe97df8f4322cf1_98507_1540953465.jpg', 'd_16_6130_0_2_20150808230218.png', 'Piano and drum are the core musical instruments in soul music.', '钢琴和鼓是灵魂乐的核心乐器。', 'f2115af7c01b8e1d053455a7aef7c03d_17913_1540954246.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (986, 'southern', '/ˈsʌðərn/', 'southern.mp3', 'adj.南部的，南方的', '9a8aab27cd9f6f9f31c46104c842a73d_106932_1578562138.jpeg', 'd_109_19563_0_2_20150809063714.png', 'He lives in the southern part of the city.', '他住在城市的南边。', 'c304797470b5183b5fbff5cb403f0fe1_13368_1590491549.mp3', 'south南 + ern...方向的 → 南方的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (987, 'spacecraft', '/ˈspeɪskræft/ ', 'spacecraft.mp3', 'n.宇宙飞船', '1425952816542-gigapixel-scale.jpg', 'd_105_10290_0_2_20150809061704.png', 'The spacecraft is used to explore the unknown area in space.', '宇宙飞船是用来探索宇宙中的未知区域的。', 'dfgdy54cuge3h3y92kqqs9d9echt2jxb.mp3', 'space宇宙 + craft太空船 → spacecraft航天器，宇宙飞船', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (988, 'speed up', '/spid ʌp/', 'speed up.mp3', 'phr.加快速度', '3_0_20160521101018_9953_c.jpg', '', 'My bicycle can speed up within a second.', '我的自行车能在一秒内加快速度。', '3_0_20160521101018_6160_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (989, 'spread', '/spred/', 'spread.mp3', 'v.抹，敷；伸开，伸展', '52ad6490296280c2a868e4b9a10528ac_80508_1535093579.jpeg', 'd_24_9110_0_4_20150808230031.png', 'I like to spread butter on the bread before making a sandwich.', '做三明治之前，我喜欢在面包上涂点黄油。', 'bb3a74006fcd2423aeb5b319a5389f5e_40003_1535093556.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (990, 'stain', '/steɪn/', 'stain.mp3', 'n.污渍，污迹；  v.弄脏；玷污；染色', '0a56b5cd75bda6f45dc2371e9915254c_91864_1534217092.jpg', '20130111_18_57_43_696.png', 'Oh dear! Look at that big red stain on his shirt.', '天哪！看他衬衫上那一大块红色的污渍。', '9a28f75b6f3901c13e81a895f9a318fb_37052_1534217070.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (991, 'step up', '/step ʌp/', 'step up.mp3', 'phr.加快', '94c94ca6766006ff7a4b2dd996b86798.jpeg', '', 'She stepped up her training as the race came closer.', '比赛临近时，她加强了训练。', 'us_She_stepped_20240108101021221_02b7a3d81c79fd448348.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (992, 'stereotype', '/ˈsteriətaɪp/', 'stereotype.mp3', 'n.老套的模式，陈规；  v.对……产生成见', 'i_2_8206_0_8_151222161939-gigapixel-scale.jpg', '', 'There are three typical stereotypes of South Korean TV shows.', '韩剧有三种经典的套路。', 'sa_2_8206_0_8_151225172745.aac', 'stereo立体 + type模式 → stereotype陈规，老套', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (993, 'stupid', '/ˈstuːpɪd/', 'stupid.mp3', 'adj.愚蠢的，笨的', 'i_16_16530_0_6_160425145836-gigapixel-scale.jpg', '20130301_12_43_04_438.png', 'The donkey made a stupid mistake.', '这头驴犯了一个愚蠢的错误。', 'ae8be791122d95a1_1266763315092609716_250117.mp3', 'stup笨，麻木 ＋ id形容词，“如…的” → stupid笨的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (994, 'table', '/ˈteɪbəl/', 'table.mp3', 'n.桌子；表格；  v.搁置', '20120507_04_22_37_939-gigapixel-scale.jpg', 'd_24_17175_0_4_20150808232242.png', 'The meeting room had a large table big enough for fifteen people to sit around.', '这间会议室有一个大桌子，足够坐下十五个人。', 'sa_13_17175_0_2_20150808204508.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (995, 'task', '/tæsk/ ', 'task.mp3', 'n.任务，工作；作业', 'd3de2b57d5031d75fabc9b6ba613c895_125528_1738983227.jpg', 'd_24_18018_0_4_20150808234238.png', 'I\'m so happy—there isn\'t a single task on my to-do list!', '我很高兴，我的任务列表上已经没有任务了！', 'sa_13_18018_0_2_20150808205248.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (996, 'tear', '/ter/', 'tear.mp3', 'v.撕裂，撕碎（读作/ter/ ）；  n.眼泪（读作/tɪr/）', 'i_1_4795_0_3_20150808123032-gigapixel-scale.jpg', 'd_24_4795_0_3_20150808223554.png', 'The broken-hearted man tore the photo into pieces.', '这个心碎的男人撕碎了照片。', 'us_The_brokenhearted_20230105100343908_54c2ed4c2b6bd2b18dbe.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (997, 'tempt', '/tempt/', 'tempt.mp3', 'v.诱惑；吸引', '1e98efd955146b4152be04a33816d283_196082_1587465730.jpeg', 'd_101_14494_0_4_20150809040327.png', 'The squirrel is easily tempted by the acorn.', '这只松鼠很容易被一颗橡子引诱。', 'e826f70d650c609aac9e793ae1a472a4_48358_1591086293.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (998, 'tip', '/tɪp/', 'tip.mp3', 'n.小费；  v.给小费', '966d131da5dbb6235d0e4aa65b7933a8_83230_1599444587.jpeg', 'd_16_8048_0_7_20150808232451.png', 'He gave the porter a 5-dollar tip.', '他给了那名行李员五美元的小费。', 'da41ad8ed6557a31_1266883372517731278_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (999, 'trade', '/treɪd/', 'trade.mp3', 'n.贸易，商业；  v.经商，交易', 'fa44c94cbf4e5b59f388ac73ff686976_87036_1522665188.jpg', 'd_16_18883_0_3_20150809020419.png', 'International trade has become a major source of income for this company.', '国际贸易成了这家公司的一项主要收入来源。', 'egc4vf28ws4sj2j8afnr83pjyfgfl2xu.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1000, 'traffic', '/ˈtræfɪk/', 'traffic.mp3', 'n.交通，车流；信息流量', '2e3a73215d86639a8fe595730c9d0e13_192245_1533108429.jpeg', 'd_24_5581_0_4_20150808224207.png', 'The cars are hardly moving in the traffic jam.', '车子在交通堵塞中艰难地移动着。', '0350dd0bfa45d4b9_1266763450957781532_250117.mp3', 'tra=trans穿过 + ffic摩擦 → 在相互摩擦中穿过 → traffic交通，车流，流量', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1001, 'translate', '/trænsˈleɪt/ ', 'translate.mp3', 'v.翻译；转换', '3f5d2e09c179b92dd34c4df71422ec96_136052_1686117525.jpeg', 'd_24_6998_0_3_20150808224906.png', 'The girl used a phone app to translate this phrase into English.', '女孩用一款手机应用程序把这个短语翻译成了英文。', '4fd1560b63155382_1266883114391067326_250207.mp3', 'trans交换 + late拿出，带出 → 交换拿出 → translate翻译；转化', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1002, 'unfair', '/ˌʌnˈfer/', 'unfair.mp3', 'adj.不公平的', 'aac9ca86a235ad2c8a5fbdffc141f985_166318_1538664762.jpg', 'd_109_8056_0_2_20150809055333.png', 'This is unfair! Why is he more important than us!', '这不公平！凭什么他比我们更重要！', 'kcmbf9j73jc9dn9fv7stkqyar2knhr3n.mp3', 'un不 + fair公平的 → unfair不公平的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1003, 'universe', '/ˈjuːnɪvɜːrs/ ', 'universe.mp3', 'n.宇宙，天地万物', '56b4aaec335fa3e6cbe1bdc66b3f5e9f_100807_1588089119.jpeg', 'd_109_6164_0_2_20150809054518.png', 'There are a lot of stars in the universe.', '宇宙中有很多星星。', 'kzjbyv663nre4x8ehukujdn74u3hweea.mp3', 'uni一个 + vers转向 + e → 统一旋转 → universe宇宙', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1004, 'unlike', '/ˌʌnˈlaɪk/', 'unlike.mp3', 'prep.不像；和……不同；  adj.不同的', '305c0899ca9aedd989ab570265473fc3_152280_1640576664-gigapixel-scale.jpg', '20141012_10_59_12_380_v3.png', 'One of these people is unlike the others.', '这些人中，有一个和其他人不同。', 'us_One_of_20220711110028896_e642e6ec654853c2c4a0.mp3', 'un不 + like像 → unlike与……不像、不同', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1005, 'upstairs', '/ˌʌpˈsterz/', 'upstairs.mp3', 'adv. 往楼上，在楼上；往高处；  adj.楼上的', 'i_16_18157_0_4_20150809014803-gigapixel-scale.jpg', 'd_24_18157_0_4_20150808235052.png', 'The dog ran upstairs to eat his food.', '狗狗上楼去吃食物。', 'cbhbpnt2utbd7kky3d3zqa8ant4xvsrk.mp3', 'upstair在楼上 ＋ s表副词 → upstairs在楼上，往楼上', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1006, 'upward', '/ˈʌpwərd/', 'upward.mp3', 'adv.向上地；  adj.向上的', '659c271f6a71d0b0f85c14a06e87b77f_97744_1579599962.jpeg', '20141012_07_26_20_110_v3.png', 'The pilot tried to pull the aircraft into an upward climb.', '飞行员试着驾驶飞机向上爬升。', '76a3a2a3e8289734c6dc92f2c1b56c1b_38254_1579599959.mp3', 'up向上 + ward向... → upward向上的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1007, 'useful', '/ˈjuːsfl/', 'useful.mp3', 'adj.有用的，有益的', '2d9f4fbee0227a1473eb4795a5dceadc_60993_1750751606.jpg', 'd_24_17489_0_3_20150808232848.png', 'A Swiss Army knife contains many different useful tools.', '一把瑞士军刀有许多不同且实用的工具。', 'sa_1_17489_0_2_20150808132353.aac', 'use用 + ful可…的 → useful有用的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1008, 'usual', '/ˈjuːʒuəl/', 'usual.mp3', 'adj.通常的，惯常的', '4d30bd254dfa70dd8ef3156f592a7b39_99782_1717652132.jpg', 'd_24_17137_0_4_20150808232119.png', 'As per usual', '通常，他下午就开始犯困。', '3_0_20170721071748_70620_c.aac', 'usu用 + al...的 → 平时经常用的 → usual通常的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1009, 'voyage', '/ˈvɔɪɪdʒ/', 'voyage.mp3', 'n.航海，航行；  v.航海；航行', '20120505_03_35_12_850-gigapixel-scale.jpg', 'd_16_6783_0_2_20150808231050.png', 'The ship Titanic sank on its first voyage.', '“泰坦尼克号”在首航中便沉没了。', '699d46c3145c04d1_1266883371076660120_250207.mp3', 'voy道路 + age表状态 → 一直在路上 → voyage航海，航行', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1010, 'young', '/jʌŋ/', 'young.mp3', 'adj.初期的', 'f5bf00740e7d9f305cc21386f541a62a.jpg', 'd_24_17236_0_4_20150808232444.png', 'Our company is quite young', '我们公司很新，于一个月前成立。', 'c4d67655d736c2a7e510d20abc70b058.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1011, 'academic', '/ˌækəˈdemɪk/', 'academic.mp3', 'adj.学术的；学院的；理论的；  n.学者', 'd59ebd90dee900c99165f34b21a8d501_106864_1585116328.jpeg', 'd_107_4781_0_2_20150809010721.png', 'This academic meeting has both students and professors.', '这次学术会议有学生也有教授。', '93e28ca801f3b4ebbb84299b45e8b866_20735_1626143667.mp3', 'academ学术 + ic……的 → 学院的;学术的;学究的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1012, 'access to', '/ˈækses tu/', 'access to.mp3', 'phr.进入', 'fdb44f92848f9b70af63ca1706b0e8be.jpeg', '', 'Access to the building is by card only.', '只有用磁卡才能进入这栋楼。', '94ccdb436ec29959c129ed75fa8d355a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1013, 'accompany', '/əˈkʌmpəni/', 'accompany.mp3', 'v.陪伴；为……伴奏（或伴唱）', 'd6a1a38398ad5a6c4a07ea30a6f2eebd_84622_1565343544.jpg', 'd_16_5451_0_2_20150808225322.png', 'I always accompany my children to their school.', '我总是陪着我的孩子去学校。', '245a436eb3742584_1266883322758126228_250207.mp3', 'ac使 + company做伴 → accompany陪伴', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1014, 'actor', '/ˈæktər/ ', 'actor.mp3', 'n.演员，男演员', '4538bc094362990071ae0e1901c41d67_76572_1565680572.jpg', 'd_16_8035_0_5_20150808232440.png', 'An actor has to be able to show different expressions.', '演员必须能展现出不同的表情。', '2ntmf8mlduzt6rm7x53bzyqtkbcwllxr.mp3', 'act表演 + or名词后缀：人 → actor演员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1015, 'adapt', '/əˈdæpt/', 'adapt.mp3', 'v.适应；改编', '1f8276bec2950f165d546a29111d1e9f_99673_1584602496.jpeg', 'd_16_16013_0_2_20150809001525.png', 'This animal changes its color to adapt to its new surroundings.', '这只动物为适应新环境改变自身的颜色。', 'af4db610ffa1b69d98fdd30f711dbbf0_45876_1584602493.mp3', 'ad朝向 + apt适应 → adapt使适合', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1016, 'adjust', '/əˈdʒʌst/', 'adjust.mp3', 'v.调整，调节；适应', '1026a82e6ff3fe1dc669818af4e00897_41805_1565342898.jpg', 'd_107_4094_0_2_20150809004402.png', 'It\'s too hot in the room; I\'ll adjust the temperature.', '房间里太热了，我调节一下温度。', 'bgupw4pmd6t5wr7kslrkf296m96sj67w.mp3', 'ad做…，加强… + just正确 → 弄正确 → 调整', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1017, 'admit', '/ədˈmɪt/', 'admit.mp3', 'v.承认；准许进入', 'ae65f3985facb2fd0e3b403315839618_73813_1731898393.jpg', 'd_16_5061_0_2_20150808224908.png', 'The boy admitted that he broke the vase.', '小男孩承认是他弄碎了花瓶。', '69f9e7fe954b927f_1266883485996985174_250207.mp3', 'ad去，往 + mit送，放出 → 送来 → admit许可进入', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1018, 'advise', '/ədˈvaɪz/', 'advise.mp3', 'v.建议；劝告，忠告', '859837cbf36a8a4dae678d114b9b8406_140739_1642666109.jpg', 'd_24_8299_0_3_20150808225600.png', 'My friend advised me to use this app when I failed the English exam.', '当我的英语考试不及格时，我的朋友建议我用这个应用程序。', '79004df4bd0447cd_1266883374335175454_250207.mp3', 'ad朝向 + vise看见 → 看向某人 → （向某人）建议，劝告', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1019, 'after all', '/ˈæftər ɔːl/', 'after all.mp3', 'phr.毕竟，终究', '04f6bb90f30a43c4336e02498c31d661_118932_1538760543.jpg', '', 'He is just a little dog after all', '别再骂它了，毕竟它只是个小狗啊。', 'd5pw9u7b33yp82hcawp642j5wer5qmrj.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1020, 'approve', '/əˈpruːv/', 'approve.mp3', 'v.正式核准，称许；赞成；满意', '5c9126787d07dfff2d233d12b7665391_58656_1568879750.jpg', 'd_16_5073_0_2_20150808224923.png', 'They all approve of my good performance.', '他们都称许我良好的表现。', 'sa_1_5073_0_4_160224153157.aac', 'ap加强 + prove证明 → approve承认，赞成', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1021, 'arise from', '/əˈraɪz frʌm/', 'arise from.mp3', 'phr.起因于', '7d53fa152acf2ec27b6c82438b5b396c.jpg', '', 'His toothache arose from eating too many sweets.', '他的牙疼是由吃太多甜食引起的。', '9249ceac3c16939f3ff67453a168b365.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1022, 'aside from', '/əˈsaɪd frəm/', 'aside from.mp3', 'phr.除...以外', '858f10f2607a54d1a40a44df0fda755f.jpg', '', 'Aside from himself', '除了他自己，会议室里只有另外三个人。', 'c1ef7fbd942eb8a92fb3bf4be93ab755.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1023, 'at last', '/æt læst/', 'at last.mp3', 'phr.终于', 'fa3173fa6cb095e0617230b5e6bcb3eb_107413_1590217497.jpeg', '', 'The shoes he was waiting for arrived at last.', '他等待的鞋子终于到了。', '393e85797a9293f80d619ebbe1bb890a_48228_1590217494.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1024, 'atmosphere', '/ˈætməsfɪr/ ', 'atmosphere.mp3', 'n.大气层；空气；氛围，气氛', '64c0be4556b1cb5c4f9acb64f9c90937_101089_1584674462.jpeg', 'd_16_5078_0_5_20150808224929.png', 'The Earth\'s atmosphere absorbs part of the sun\'s energy.', '地球大气层吸收太阳的部分能量。', 'l8yba7l9b5t2qmsrpkktylvj926pudhm.mp3', 'atmo蒸汽 + sphere范围 → 大气层；空；气氛', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1025, 'badly', '/ˈbædli/', 'badly.mp3', 'adv.严重地', 'd0bd6547754b9eceb09d5e66e4f7679a_100316_1604026682.jpg', 'd_24_5112_0_4_20150808223924.png', 'The boy was badly injured.', '男孩受了很严重的伤。', 'us_The_boy_20240115095114158_bb7b7961123a72b2c662.mp3', 'bad坏的 + ly副词后缀 → badly恶劣地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1026, 'basic', '/ˈbeɪsɪk/', 'basic.mp3', 'adj.基础的，最简单的', '032b72794ce1876c91450a5d0db20e7e_154284_1574836704.jpeg', 'd_24_17995_0_3_20150808234032.png', 'The brand\'s bags came in both basic and limited editions.', '这一品牌的包既有基础款也有限量款。', 'edb7b11cc3066d57541fadfa84903c81_48478_1574836702.mp3', 'bas=basis基础 + ic形容词，...的 → basic基本的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1027, 'bathroom', '/ˈbæθruːm/', 'bathroom.mp3', 'n.浴室，盥洗室', '4f3deb9b4725aadcdb80ab07aa11642e_64964_1575017066.jpeg', '20130301_11_00_30_105.png', 'This bathroom contains a washbasin', '这个浴室有一个洗脸盆，一个马桶和一个淋浴器。', '7ff5db5c70c8c395_1266883014840703522_250207.mp3', 'bath洗澡 + room房间 → bathroom 浴室', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1028, 'be about to', '/biː əˈbaʊt tu/', 'be about to.mp3', 'phr.即将', '606fc4ac20b03631105bf8c0946e8a3d.jpg', '', 'The meeting is about to begin.', '会议即将召开。', '25ca7558a60b95b3467b5daeed013ab4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1029, 'beg', '/beɡ/', 'beg.mp3', 'v.乞求，恳求', 'eefc22b8120d92f40710b1cf5d88c2ac_198764_1533110268.jpeg', 'd_24_7880_0_4_20150808225155.png', 'The little dog is begging his master for food.', '这只小狗正在向主人乞求食物。', 'ae8605c21c837d93_1266883322787748502_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1030, 'bomb', '/bɑːm/', 'bomb.mp3', 'n.炸弹；  v.轰炸，投弹于……', 'a60498e5f0d41aeeddfa37f6b00a999f_45322_1587457678.jpeg', 'd_105_8002_0_2_20150809060651.png', 'This bomb will explode any minute!', '这个炸弹随时都会爆炸！', '4728be6cf3fe5fda_1266883618498304718_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1031, 'borrow', '/ˈbɔːrəʊ/', 'borrow.mp3', 'v.借，借入', '44165888902cf5570c479f20500ed243_76255_1739257237.jpg', 'd_24_17297_0_4_20150808232632.png', 'He borrowed money from his friend and promised to pay it back next week.', '他向朋友借了钱并承诺下周还。', 'zjfdsagsy4xjqryckqgc2n4ajg6577ym.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1032, 'bowling', '/ˈboʊlɪŋ/', 'bowling.mp3', 'n.保龄球', '3_0_20160520173617_77371_c-gigapixel-scale.jpg', '20141010_01_18_22_523_v3.png', 'I am teaching my son how to play bowling.', '我正在教我儿子怎样打保龄球。', '8875b5272116ba79501472732f5d43e8_14779_1625796953.mp3', 'bowl球 + ing后缀 → bowling保龄球', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1033, 'broadcast', '/ˈbrɔːdkæst/', 'broadcast.mp3', 'n.广播或电视节目；  v.播放，广播', 'ee9b9c8780b16f5242c7056f053eaa99_98317_1580882782.jpg', 'd_107_8450_0_2_20150809023414.png', 'A broadcast is a program', '广播电视节目是指在收音机里或在电视上播放的节目、表演或演说。', 'y5k6v7ajnvufhvmuaaln4rarpfwbns2j.mp3', 'broad宽广 + cast投射 → 广播', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1034, 'by accident', '/baɪ ˈæksɪdənt/', 'by accident.mp3', 'phr.意外地', '3_0_20170713071710_90294_c.jpg', '', 'I stood on a banana peel by accident and slipped over.', '我意外地踩到香蕉皮滑倒了。', '629lyy3tz9zbk8rer8y6tpsj5gdht82f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
