INSERT INTO `words` VALUES (1036, 'cart', '/kɑːrt/', 'cart.mp3', 'n.手推车，运货马车；  v.用车装载', '107946e030dad5a19d07bdc371c3e746_94441_1579596643.jpeg', 'd_1_6373_0_2_20150808125101.png', 'Carts are useful for carrying goods in the supermarket.', '在超市里用手推车装商品很方便。', '098e0c6bfc8a2042d5428973f8ea703a_45238_1579596639.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1037, 'certificate', '/sərˈtɪfɪkɪt/', 'certificate.mp3', 'n.合格证书，文凭；证明，证明书（读作/sərˈtɪfɪkɪt/）', 'bf80edc1f088e033619697817f979d8d_72421_1579335503.jpeg', 'd_107_7981_0_2_20150809022509.png', 'He passed the exam and got the certificate.', '他通过了考试并获得了证书。', 'k6fypc2raxgqdlhvcn42teku7pnn9gqa.mp3', 'certify证明 + cate表名词 → certificate证件', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1038, 'chat', '/tʃæt/', 'chat.mp3', 'n.闲谈，聊天；  v.闲谈，聊天', '352340f86ef2401151732006f2203ba5_104705_1583392301.jpg', '20130106_14_33_48_857.png', 'They usually have a chat while drinking coffee.', '他们通常在喝咖啡时闲聊。', '696wgc9pjqnj7dnhht9ahu6hsdgfsp8m.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1039, 'chemistry', '/ˈkemɪstri/', 'chemistry.mp3', 'n.化学', 'e964069d05503ad2e33fd3c7027e9af6_82622_1577950217.jpeg', 'd_94_12085_0_4_20150809005955.png', 'Children like to learn chemistry through experiments.', '孩子们喜欢通过做实验学习化学。', '0292921dfd2bb2de_1266797982414363154_250123.mp3', 'chemist化学家 + ry表名词 → chemistry化学', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1040, 'church', '/tʃɜːrtʃ/', 'church.mp3', 'n.教堂', 'bc1e53d72e35c0af9adbeb5728a9382d_89006_1577950289.jpeg', 'd_24_17284_0_3_20150808232601.png', 'The church is located in a beautiful suburb.', '教堂位于一处美丽的郊区。', 'fdb669bf5069ca321505fcbd6dc46a75_34798_1577950286.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1041, 'clause', '/klɔːz/', 'clause.mp3', 'n.条款；从句', '3954cf7d6799b7b78a9391c46b31ddbf_183412_1564370410.jpg', '20130606_21_54_11_404.png', 'The tenant will sign the tenancy agreement after checking every clause.', '房客核对完每条条款后才会签署租房合同。', '592ddb1489717616dcdad28b78055eda_41524_1564370410.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1042, 'competent', '/ˈkɑːmpɪtənt/', 'competent.mp3', 'adj.有能力的', 'ad806ea1186f99b0aca37b5538fb7820_39127_1715912783.jpg', 'd_107_6692_0_2_20150809020744.png', 'She\'s a competent worker and is good at her job.', '她是一个有能力的员工，并且擅长她的工作。', 'sa_1_6692_0_2_20150808125352.aac', 'com共同 + pet追寻，寻求 + ent……的 → competent有资格的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1043, 'consequence', '/ˈkɑːnsɪkwens/ ', 'consequence.mp3', 'n.结果；重要性', 'a105309654fae487cdeba3398fd9e709_136907_1734331001.jpg', 'd_16_8402_0_7_20150808232958.png', 'The consequence of eating too much junk food is getting fat.', '吃太多垃圾食品的后果就是长胖。', 'j65ct52l4brgtrnv4n48a7mskg9cba3g.mp3', 'con一起 + sequ跟随  + ence名词后缀 → 随之而来的事物 → consequence后果', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1044, 'consumer', '/kənˈsuːmər/', 'consumer.mp3', 'n.用户', 'ced4036052c5bbb2ef5b22fc9a22c87c_179438_1533108955.jpeg', 'd_1_5098_0_2_20150808123502.png', 'The consumers buy many goods from the supermarket.', '消费者从超市里购买许多商品。', '54f0fee74af5e6a51989febc536d9c93_17914_1596094938.mp3', 'con全部 + sum拿取 + er人 → consumer消费者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1045, 'cook', '/kʊk/', 'cook.mp3', 'n.厨师；  v.烹饪；煮，烧', '7dd5ab06ec14f6bb9f33ce67f72b4420_121980_1701076418.jpeg', 'd_24_7955_0_4_20150808225306.png', 'She is a great cook. Look at all this delicious food!', '她是个很棒的厨师。看看这些美食！', 'us_She_is_20250704163434643_f269bd6ba95fa09429d6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1046, 'crime', '/kraɪm/', 'crime.mp3', 'n.犯罪活动；罪行', 'crime_5014_20231106_437ff922.jpg', 'd_16_5014_0_5_20150808224812.png', 'The police are investigating the crime scene.', '警方正在调查犯罪现场。', '3_0_20170714071406_90058_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1047, 'dedicate...to', '/ˈdedɪkeɪt tu/', 'dedicate...to.mp3', 'phr.把（时间、力量等）用在……', '61a11ca2761bab8cf2b71b5c96253468_171472.jpg', '', 'She dedicated her time to working and being a mother.', '她把时间用于工作和带孩子上。', 'af2f8eec9072d9e289dc030219e920a9_34639.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
