INSERT INTO `words` VALUES (1049, 'democracy', '/dɪˈmɑːkrəsi/', 'democracy.mp3', 'n.民主制度；民主国家；民主主义；民众', 'c_20150410_171145_11_5110.jpg', 'd_1_5110_0_2_20150808123516.png', 'Voting is an important part of democracy.', '投票是民主制度的一个重要部分。', '05126c4fb2654f5f0dd0a5036f28ee15_15876_1617937333.mp3', 'demo人民 + cracy统治 → democracy民主政治', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1050, 'departure', '/dɪˈpɑːrtʃər/', 'departure.mp3', 'n.离开', '8439f5dec9782a333a8d60b82b9eca27_192074_1579337326.jpeg', 'd_16_6189_0_2_20150808230338.png', 'His departure from home made his family sad.', '他离开了家，这使其家人感到悲伤。', '5d14d2de2a3bff688f9b7eb039279541_82531_1594797366.mp3', 'depart出发 + ure名词后缀 → departure离开，出发', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1051, 'difference between', '/ˈdɪfrəns bɪˈtwiːn/', 'difference between.mp3', 'phr.……之间的差别', '490f842ba7948cf23e2cacc13629a441.jpg', '', 'The difference between these two apples is color.', '这两个苹果之间的差别在于颜色。', 'e5d0d62d1df9cd412f913c000790f080_47648_1593585089.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1052, 'diplomat', '/ˈdɪpləmæt/', 'diplomat.mp3', 'n.外交官，外交家；有交际手腕的人，圆滑的人', '48554bc1562f5f4bec2bb1f8d2ee1478_197767_1558938694.jpeg', '', 'The diplomat represents his country to make agreements with other countries.', '外交官代表他的国家与他国达成协议。', '34d7b4b52e0c5ec9dd2eccf1d4afc6d1_50526_1569640769.mp3', 'diploma公文 + t=ate表名词 → diplomate的简化 → diplomat外交官，外交家', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1053, 'dish', '/dɪʃ/', 'dish.mp3', 'n.菜肴；碟，盘子', 'ae72a60e1c4d7dac781bbfbe8194f92d_89459_1577936579.jpeg', 'd_24_17296_0_4_20150808232630.png', 'Add a slice of lemon to flavor the dish.', '加上一片柠檬为这道菜肴调味。', 'a4160e0431110bdfe518aa4408c19a21_35230_1577936574.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1054, 'dislike', '/dɪsˈlaɪk/', 'dislike.mp3', 'v.不喜欢；  n.反感，厌恶', 'i_1_8494_0_6_151019152616-manual-scale.jpg', '20121225_19_46_17_913.png', 'She really dislikes vegetables.', '她真的不喜欢蔬菜。', 'sa_1_8494_0_6_151102160716.aac', 'dis否定 + like喜欢 → dislike不喜欢', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1055, 'distinguish', '/dɪˈstɪŋɡwɪʃ/', 'distinguish.mp3', 'v.区别，识别', 'i_16_3980_0_2_20150808223919-gigapixel-scale.jpg', 'd_16_3980_0_2_20150808223919.png', 'It\'s easy to distinguish the blue man from the gray men.', '我们很容易就能把这个蓝色的人从一群灰色的人中辨别出来。', 'sa_16_3980_0_2_20150808223919.aac', 'dis分散，分开 + tingu=ting做标记 + ish动词后缀 → 分开做标记 → distinguish区别', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1056, 'diverse from', '/daɪˈvɜːrs frəm/', 'diverse from.mp3', 'phr.和 ... 不一样', 'aba948f15ffcbe905e2e92e15d6e67ad_55673_1707018865.jpg', '', 'Their ideas are diverse from mine.', '他们的想法和我的不一样。', 'us_Their_ideas_20240204115428669_60894d55c1b11a48cbf2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1057, 'draw in', '/drɔː ɪn/', 'draw in.mp3', 'phr.车进站，到达', '9419c1f887f22560ae61d1ea2aa99a55.jpg', '', 'The train is drawing in and people are waiting at the platform.', '火车进站了，人们正在站台上等着。', '2995801063493c24664ad55a1612434c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1058, 'drive', '/draɪv/', 'drive.mp3', 'v.驾车，开车', 'e2a8d6c1ddd3c0b97fbd3a77decdfea1_109707_1535528636.jpeg', '20141010_21_47_23_249_v3.png', 'The man is driving along the coast.', '这个男人沿着海边开着车。', '4942a7e3702a8a44_1266763405144927080_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1059, 'drunk', '/drʌŋk/', 'drunk.mp3', 'adj.喝醉了的；陶醉的，兴奋的；  n.醉汉，酒鬼', 'f45cb9f412c05e362c003e35d9a3be10_181932_1538757149.jpg', 'd_16_8041_0_4_20150808232444.png', 'A drunk man passed out on the sofa.', '一个喝醉的男人在沙发上昏睡过去。', 'a0f100a32f8ec4d0_1266883527398107982_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1060, 'duplicate', '/ˈduːplɪkeɪt/', 'duplicate.mp3', 'n.复制品；  v.重复（读作/ˈduːplɪkeɪt/）；  adj.完全一样的', '563e873986212f08d5ebce1e28625d95_46502_1725005755.jpg', '20140814_10_54_56_711_v3.png', 'There are several rows of pottery duplicates. ', '这里有好几排陶器的复制品。', 'us_There_are_20240830161430912_fa8bca5ee2a20e59e731.mp3', 'du二，双 + plic折 + ate使，造成 → 折成相同的两份 → duplicate加倍，复制', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1061, 'election', '/ɪˈlekʃn/', 'election.mp3', 'n.选举', 'd9539fbcee0778da94b5e2946a041377_142780_1590334781.jpg', 'd_100_12534_0_4_20150809032452.png', 'In an election', '在选举中，我们决定谁来当我们的领导人。', '146d91dc179d00a5_1266883636735990514_250207.mp3', 'e出 + lect选择，收集 + ion名词后缀 → election选举', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1062, 'else', '/els/', 'else.mp3', 'adv.另外，其他', '0f34d7f942862614deec9b3041a60662_92698_1565254386.jpg', '20121225_19_05_21_445.png', 'I\'m happy', '我很高兴，但是别的家伙都苦着一张脸。', '5f4ec5a657f426aa_1266763403597601338_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
