INSERT INTO `words` VALUES (1064, 'formula', '/ˈfɔːrmjələ/', 'formula.mp3', 'n.公式，方程式；配方奶粉；准则，方案；方法', '68e4cb08b23fefc5ea36ed4e448eae00_94294_1565343124.jpg', 'd_107_5783_0_2_20150809013912.png', 'The boy learned many math and science formulas at a young age.', '这个男孩很小的时候就学会了很多数理公式。', '35f618bbe29be5ca94c0d185bfa2fb6d_21675_1625793955.mp3', 'form形式 + ula表名词 → 形成模式的 → formula公式', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1065, 'fortune', '/ˈfɔːrtʃən/', 'fortune.mp3', 'n.运气', '4261f80127d98e9e1f75afcb02d45353_77857_1538624217.jpg', '20130130_16_24_17_820.png', 'What a good fortune! I won the first prize.', '运气真好！我中了一等奖。', 'sa_1_6228_0_5_150914160335.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1066, 'frequency', '/ˈfriːkwənsi/', 'frequency.mp3', 'n.（声波或电磁波振动的）频率；频繁', '1425952771587-gigapixel-scale.jpg', 'd_105_7495_0_2_20150809060359.png', 'The sounds had a high frequency.', '声音的频率很高。', 'sa_1_7495_0_2_20150808125950.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
