INSERT INTO `words` VALUES (1068, 'graduation', '/ˌɡrædʒuˈeɪʃn/', 'graduation.mp3', 'n.毕业，毕业典礼', 'd077a84e99b5f4b2669c55b8522e173e_98509_1580884076.jpg', 'd_16_17558_0_4_20150809011419.png', 'They stand in line and wait for their graduation ceremony.', '他们排着队，等待毕业典礼开始。', '873a1ce8e8db509e3a4c3f0ef1bd4092_39790_1580884082.mp3', 'grad步，级 + uat=ate做… + ion名词后缀 → 使升级并走出 → graduation毕业', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1069, 'great', '/ɡreɪt/', 'great.mp3', 'adj.伟大的', 'ccd44aa8ae3daf6828bfe64a6646cb7d.jpeg', 'd_24_16434_0_4_20150808231223.png', 'Vincent van Gogh is one of the greatest painters in the history of Western art.', '梵高是西方艺术史上最伟大的画家之一。', 'f1ae6fd6ecc0bf25a60e17bcaeebf877_42358_1600311314.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1070, 'halt', '/hɔːlt/', 'halt.mp3', 'v.使停止；  n.停住，终止', '3_0_20160720071052_47943_c-gigapixel-scale.jpg', 'd_1_4061_0_2_20150808122303.png', 'You should halt when you see a policeman make this gesture.', '看到警察做出这个手势时，你应该止步。', '3_0_20160720071052_28506_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1071, 'headquarters', '/ˈhedkwɔːrtərz/', 'headquarters.mp3', 'n.总部，总局；司令部，指挥部', 'e74cc2192c251c63c3eff4473560c9cb_130605_1583132753.jpeg', 'd_108_6163_0_2_20150809042029.png', 'The building is the headquarters of the family firm.', '这座大楼是该家族公司的总部。', 'ba87fdf9d75fa39769640c9a13a0dcf3_46044_1583132751.mp3', 'head头 + quarter使驻扎 + s表地点 → 头脑聚集的地方 → 司令部；总部', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1072, 'hold up', '/hoʊld ʌp/', 'hold up.mp3', 'phr.举起；(在逆境中) 保持良好状况', 'i_16_17363_0_5_20150809010144.jpg', '', 'They work together to hold up the ball.', '他们合作举起了球。', 'sa_16_17363_0_5_20150809010144.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1073, 'housewife', '/ˈhaʊswaɪf/', 'housewife.mp3', 'n.家庭主妇', 'd2eb1335bcc5f98e512e329ed5ce6be8_179180_1538579645.jpg', '', 'The housewife is ironing the clothes with her child.', '这个家庭主妇正在和她的孩子一起熨衣服。', 'b454c645bc14dced_1266763310634588710_250117.mp3', 'house屋子 + wife妻子 → 家庭主妇 → housewife家庭主妇', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1074, 'ignorant of', '/ˈɪɡnərənt ʌv/', 'ignorant of.mp3', 'phr.不知道', 'a38a8251719c75c432c7dbfff518c816.jpeg', '', 'He continued on his way', '他继续赶路，对前面潜伏的危险一无所知。', '5f7a8b68cc74900c0315ac44c21a61a5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1075, 'immigrant', '/ˈɪmɪɡrənt/ ', 'immigrant.mp3', 'n.移民，外侨；  adj.移民的；迁入的', 'e71decc39a12fd4d660a2a6c867675f6_45774_1706759669.jpg', 'd_1_4241_0_4_20150808122547.png', 'Immigrants bring cultural diversity.', '移民带来了文化多样性。', 'vx5dzx26kk66vnhwmzbgsapkm5ebmm9k.mp3', 'im向内，进入 + migr迁移 + ant表示人；形容词 → immigrant外来的移民；移入国内的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1076, 'in sight of', '/ɪn saɪt ʌv/', 'in sight of.mp3', 'phr.看得见', '908d82e0800b6d35769b61c733723339.jpeg', '', 'He climbed to the hilltop and finally came in sight of the house.', '他爬上山顶，终于看到了那所房子。', 'db42d06ccb1512f4b26337008807305c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1077, 'index', '/ˈɪndeks/', 'index.mp3', 'n.指数；指标；  v.附以索引，编入索引', '3_0_20160718114857_68209_c-gigapixel-scale.jpg', 'd_107_8354_0_2_20150809023127.png', 'The stock index rises and falls all the time. Invest cautiously.', '股票指数总是起伏不定，投资请谨慎。', '3_0_20160718114857_36813_c.aac', 'in进入 + dex显示，宣告 → index指数', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1078, 'indicate', '/ˈɪndɪkeɪt/', 'indicate.mp3', 'v.表明', '3_49_20170309174623_66091_c-gigapixel-scale.jpg', 'd_16_9896_0_2_20150808234850.png', 'Can you guess what the line chart indicates?', '你能猜到这张折线图说明了什么吗？', 'us_Can_you_20240717132935960_60c62f6e445144247bea.mp3', 'in进入 + dic说话，断言 + ate使，造成 → 说进去 → indicate指示，指明', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1079, 'ingredient', '/ɪnˈɡriːdiənt/ ', 'ingredient.mp3', 'n.（烹调的）原料；（构成的）要素', '515ec3b8b18e91163500af63125e473a_98745_1594801776.jpeg', 'd_1_4125_0_2_20150808122359.png', 'Flour is the main ingredient of bread.', '面粉是面包的主要原料。', '66e87852ba50ba8ffe36ee63ed26d719_59360_1594801788.mp3', 'in进入 + gred走 + ient → 走进去的，成为其中一部分 → ingredient成份，因素', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1080, 'invade', '/ɪnˈveɪd/', 'invade.mp3', 'v.侵略，侵入；渗透', '29859443eed913ef831d0e1b35a2d946_200705_1565689722.jpeg', 'd_1_5871_0_3_20150808124534.png', 'The wolves invaded the goat family.', '狼群入侵了山羊家族。', '21640fab6660e0b8cb2352886aa80118_13211_1565689764.mp3', 'in进 + vad行走 + e → 走进去 → invade侵略', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1081, 'involved', '/ɪnˈvɑːlvd/', 'involved.mp3', 'adj.被卷入的；有关的', 'ee0cfc12333646dc67d0e03765f414c4_200491_1534822240.jpeg', 'd_1_9140_0_2_20150808131236.png', 'Maybe he shouldn\'t have gotten himself involved in the boys\' fight.', '或许他不该让自己卷入男孩们的打斗之中。', '9da793757ff4c63e03eae92eeb64348a_44179_1534822234.mp3', 'involve包含，牵涉 + d=ed形容词后缀 → involved有关的，卷入的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1082, 'Italy', '/ˈɪtəli/', 'Italy.mp3', 'n.意大利', '3923820391a5d78ecf93605f6467030b_191968_1541820831.jpg', 'd_24_17563_0_4_20150808232954.png', 'I love Italy for the food and sightseeing.', '我喜欢意大利的美食和美景。', 'sa_109_17563_0_2_20150809062258.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1083, 'jet', '/dʒet/', 'jet.mp3', 'n.喷气式飞机；  v.乘坐喷气式飞机；  adj.喷气式（发动机）推进的', '92cc7bce38e8f532886f62e38c7336b1_27820_1565706336.jpg', 'd_105_9283_0_2_20150809061410.png', 'Most long-distance travel is done by jet plane.', '大多数长途旅行会使用喷气式飞机。', 'c5ff2d369fd720ce_1266883005512571442_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
