INSERT INTO `words` VALUES (1085, 'laundry', '/ˈlɔːndri/', 'laundry.mp3', 'n.洗衣物，洗衣物的活；要洗的衣服', 'c1fc263a489fb5c066c00ddfe766366b_97280_1579337195.jpeg', '20141009_19_01_30_925_v3.png', 'The young man is doing laundry at home.', '这个年轻人正在家洗衣服。', '8157f02bc0b04510ad2f5fc3af128a2d_27238_1579337192.mp3', 'laund=launder洗衣 + ry场地 → 洗衣房', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1086, 'lead to', '/liːd tuː/', 'lead to.mp3', 'phr.导致', '440539ac0fdf5c0ce4f46bb8c3baf50d_152785.jpg', '', 'Eating like that will surely lead to obesity.', '像那样吃是一定会导致肥胖的。', '36e412d152881eaeb7ff11347b27ce8c_36043.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1087, 'leadership', '/ˈliːdərʃɪp/', 'leadership.mp3', 'n.领导，领导地位；领导能力', '2c53a33f7d44a4fc67af65db5cd52757_21359_1710998442.jpg', 'd_105_5072_0_2_20150809054410.png', 'Under his leadership', '他们在他的领导下登上了山顶！', '75d2b7c6f7a2d4018725fc529a29a830_31698_1573871623.mp3', 'lead 带领 + er 表人 + ship资格 → leadership领导', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1088, 'lesson', '/ˈlesn/', 'lesson.mp3', 'n.课，一课时；单元，课程', '80fbf43428cc87bd326336065d61102e_110986_1750750645.jpg', 'd_24_17148_0_3_20150808232141.png', 'The girl is taking a tennis lesson.', '这个女孩正在上网球课。', '3_0_20170608071807_70727_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1089, 'lest', '/lest/', 'lest.mp3', 'conj.惟恐；以免；担心', '74ef48ef0e740823e3e414b37e4b7831_87676.jpg', '', 'She set many alarms the previous night', '她睡前设了超多闹钟，以免再次迟到。', 'us_She_set_20240522131508423_07ce79f84248dd1cb862.mp3', 'les=less更少的 + t=the → the less that比...少 → lest唯恐，以免', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1090, 'mankind', '/mænˈkaɪnd/', 'mankind.mp3', 'n.人类；男人', 'fb9f8af23bb2d5962b81ac2cf7158929_113536_1533105805.jpeg', '', 'Mankind\'s duty is to protect the Earth for future generations.', '人类的责任是为后代保护地球。', 'fed576088b579ef29aedd889535ccd97_56852_1533105794.mp3', 'man人 + kind 种类 → mankind人类', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1091, 'manner', '/ˈmænər/', 'manner.mp3', 'n.（复数）礼仪，礼貌；态度，举止', 'a7a7e74760fc74225cca5d8cf0b29098_83709_1732243800.jpg', '20130307_16_03_47_468.png', 'It\'s bad manners to speak while you are eating.', '一边吃饭一边说话是不礼貌的举止。', '2557cc479b08ead588d09f25bc573439_13524_1547607813.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1092, 'march', '/mɑːrtʃ/', 'march.mp3', 'v.行军，前进；  v.使行军；  n.行军，游行示威', '579022d5b0aa94d9300108f7c49c8202_195634_1541833741.jpg', 'd_100_13356_0_4_20150809032542.png', 'The music band is marching on the street for festival celebration.', '为了庆祝节日，这支乐队正在街上游行。', 'c4638e58578287b6_1266883371118451362_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1093, 'meantime', '/ˈmiːntaɪm/', 'meantime.mp3', 'n.同时；期间；  adv.在此期间', '74d808b2b694ba82c6bbcd49435ff7df_137499_1524887352.jpeg', 'd_1_6670_0_3_20150808125332.png', 'The movie starts in 10 minutes; in the meantime', '电影还有十分钟才开场，在此期间我们先去买点爆米花吧。', 'us_The_movie_20221010161158635_18ac0bcf7967c635034f.mp3', 'mean平均 + time时间 → meantime当时，在那当中，同时', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1094, 'medium', '/ˈmiːdiəm/', 'medium.mp3', 'adj.中等的；中号的；适中的；  n.手段，方法；媒介；材料', 'i_1_5153_0_3_20150808123558-gigapixel-scale.jpg', 'd_16_5153_0_2_20150808225050.png', 'I\'d like a medium-sized television.', '我想要一台中等尺寸的电视机。', 'us_Id_like_20240628132519031_601ca7efb6e9acb890d0.mp3', 'medi中间 + um表名词 → medium中间物，媒介', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1095, 'mild', '/maɪld/ ', 'mild.mp3', 'adj.清淡的；温暖的；轻微的', '3_18_20161130152239_39236_c-gigapixel-scale.jpg', 'd_24_8212_0_4_20150808225526.png', 'I would love a bowl of mild chicken soup right now.', '我现在想要一碗清淡的鸡汤。', 'jub2tl5qlxqzge86kueg3qu7n4h4a6v9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1096, 'modern', '/ˈmɑːdərn/ ', 'modern.mp3', 'adj.当代的，现代的，现代化的', '20120507_04_47_51_555-gigapixel-scale.jpg', 'd_24_17286_0_4_20150808232615.png', 'Smart phones are common tools in modern life.', '在现代生活中，智能手机是常用的工具。', 'fb3e8021c8806f5a_1266763523657149274_250117.mp3', 'mod采取适当措施，以某种方式 + ern形容词后缀 → modern现代的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1097, 'mostly', '/ˈmoʊstli/', 'mostly.mp3', 'adv.大多', '2b501237debc4c3be8606cd040701f9e_50625_1585132205.jpeg', '', 'The cake is mostly made of cream.', '这个蛋糕大部分是奶油做的。', '66d4b0c0492ccf71eebca9d6ea8991cb_13055_1629791094.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1098, 'multiple', '/ˈmʌltɪpl/', 'multiple.mp3', 'adj.许多的；  n.倍数', '179bfb5323c9dc555f930b6a87980eef_37287_1754557146.jpg', 'd_107_6174_0_2_20150809015141.png', 'We can see the multiple colors of the lipsticks on her arms.', '我们可以看到她手臂上多种多样的口红颜色。', '825d4ec6a7bc700c62e8e4e1e3a76352_20735_1626492190.mp3', 'multi很多 + ple满 → 多的 → multiple多功能的，多样的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1099, 'nearly', '/ˈnɪrli/', 'nearly.mp3', 'adv.将近，几乎，差不多', 'd956b716157a96755a4c5e523f3527b2_86349_1565255562.jpg', 'd_109_19597_0_2_20150809063755.png', 'The ball nearly went in!', '那个球差点儿就进了！', 'fc88a0146f6f3177_1266763523146754888_250117.mp3', 'near接近 + ly……的 → nearly差不多；密切地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1100, 'nuclear', '/ˈnuːkliər/', 'nuclear.mp3', 'adj.核能的；原子能的；细胞核的', '1425889285081-gigapixel-scale.jpg', '20121225_20_40_30_365.png', 'A single nuclear power plant can provide energy for the whole city.', '一个核电站能为一整座城市提供能源。', 'ad08a071f3eee1d7934c06a87b89a112_23713_1625812469.mp3', 'nucleus核 + ar形容词后缀 → nuclear核能的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1101, 'observe', '/əbˈzɜːrv/', 'observe.mp3', 'v.观察；说，评论', 'b695f68ece4c01a7fa2ec24e11ea5a49_146842_1557481029.jpeg', 'd_16_10142_0_2_20150808235125.png', 'The little girl is observing the goldfish carefully.', '小女孩正在仔细观察那条金鱼。', '106cea0f25b55711_1266883373877123602_250207.mp3', 'ob在...之前 + serve照看，保证安全 → observe观察', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1102, 'on business', '/ɑːn ˈbɪznɪs/', 'on business.mp3', 'phr.出差', '5f3fe0b781ad8502575e09d0ccd45688_182387_1590215805.jpeg', '', 'He is travelling to another city on business.', '他正要去另一个城市出差。', '8c5024eaff91f7ce_1266883615953148594_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1103, 'on fire', '/ɑːn faɪr/', 'on fire.mp3', 'phr.着火', '8496500f7059c9157187587bf389d9ab_100947_1590218447.jpeg', '', 'This car is on fire.', '这辆车着火了。', 'cce51b2c4634271a_1266883490079288248_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1104, 'on hand', '/ɔn hænd/', 'on hand.mp3', 'phr.手头现有', '0d8db510a0fd21209a4a763ffb0ee2a7_69128_1562987260.jpg', '', 'I have about 500 dollars on hand.', '我手头现有500美元。', '57c3a80437d3d7cdf40abc655c6e97d2_13524_1562987298.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1105, 'on the point of', '/ɑːn ðə pɔːɪnt əv/', 'on the point of.mp3', 'phr.正要……的时候', '7061df4975d4f8a966831e0535163bfb.jpeg', '', 'She was on the point of saying something to him when the phone rang. ', '她正要对他说些什么的时候，电话响了。', 'c361f2e638b6c7c3f82baa69416626e4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1106, 'once in a while', '/wʌns ɪn ə waɪl/', 'once in a while.mp3', 'phr.偶尔', '81b420fea984ae035c99c74bd27f04d7.jpeg', '', 'He cooks dinner himself every once in a while. ', '他偶尔会自己下厨。', 'f8b417142a2c2af7bc1e47b6e9d40f51.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1107, 'organize', '/ˈɔːrɡənaɪz/', 'organize.mp3', 'v.整理；组织；安排；筹办', 'b63da0acb1b1e8f7615754b40d6e549b_194226_1595470507.jpg', 'd_16_5570_0_4_20150808225453.png', 'He is trying to organize the papers. ', '他在努力整理文件。', '19ebc439693bc7662db2bb16374295de_40832_1595301758.mp3', 'organ器官 + ize动词后缀 → organize组织，整理', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1108, 'original', '/əˈrɪdʒənl/', 'original.mp3', 'adj.最初的，原始的，原来的', '35f2e5b3c66d0f09410b3b4f37d88e73_129839_1701051168.jpg', '', 'This is the original manuscript of the famous novel.', '这是这部著名小说的原稿。', 'sq575v6beqg5ybxcb6qc3t2rwxntsudc.mp3', 'origin起源 + al形容词后缀 → original原始的，独创的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1109, 'out of breath', '/aʊt əv breθ/', 'out of breath.mp3', 'phr.喘不过气', '52f9460b9f6f2b1f87123424c86a4414_112701_1605088232.jpg', '', 'I’m out of breath after a long run.', '长跑以后我上气不接下气。', '47e8e5f7e0fbf02068fbd3c2b2b369c0_20322_1574412864.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1110, 'out of order', '/aʊt əv ˈɔːrdər/', 'out of order.mp3', 'phr.出毛病，运转不正常', '3_0_20170712071814_21009_c.jpg', '', 'He is angry because the washing machine is out of order.', '他有点生气，因为洗衣机出毛病了。', 'e5aa35ba1e04d863_1266883008451947402_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1111, 'owner', '/ˈoʊnər/', 'owner.mp3', 'n.所有者，物主，主人', 'i_69_13618_0_4_20150809003437-gigapixel-scale.jpg', 'd_93_13618_0_4_20150809002144.png', 'She is the owner of the milk tea shop.', '她是这家奶茶店的店主。', 'sa_69_13618_0_4_20150809003437.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1112, 'payment', '/ˈpeɪmənt/', 'payment.mp3', 'n.付钱；报酬', '3_0_20160624145542_48386_c-gigapixel-scale.jpg', 'd_1_5050_0_3_20150808123406.png', 'The clever dog made the payment for the bone itself.', '这只聪明的狗自己购买了骨头。', '3_0_20160624145542_86355_c.aac', 'pay付款 + ment表示行为、行为的过程或结果 → 支付，支付的款项', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1113, 'personality', '/ˌpɜːrsəˈnæləti/', 'personality.mp3', 'n.性格', 'i_1_4389_0_3_20150808122718-gigapixel-scale.jpg', 'd_107_4389_0_2_20150809005522.png', 'Although they\'re twins', '尽管他们是双胞胎，但他们的性格大不相同。', 'sa_1_4389_0_3_20150808122718.aac', 'person人 + ality状态，性质 → personality人格，个性', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1114, 'positive', '/ˈpɑːzətɪv/', 'positive.mp3', 'adj.积极的，乐观的；阳性的；  n.正数', 'i_1_7118_0_3_20150808125758.jpg', 'd_16_7118_0_2_20150808231501.png', 'He faces every situation with a positive attitude.', '不管面对什么情形，他的心态都很积极。', '29d35a6d1297a185_1266883528869436032_250207.mp3', 'posit肯定 + ive形容词后缀 → positive肯定的；积极的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1115, 'pray', '/preɪ/', 'pray.mp3', 'v.祈祷，祈求，企盼；请求，恳求', '97a216fdca3aac5973bd52aa7a8fbb62_460196_1724395242.jpg', '0e01634a89b88da26a3005459ee4f0f8_9767_1551253549.png', 'She prays for lifelong health and well-being for herself and her family.', '她祈祷自己和家人一生平安顺遂。', 'us_She_prays_20240823144045261_6b686a98a4a8c1715e32.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1116, 'prejudice against', '/ˈprɛdʒədɪs əˈɡenst/', 'prejudice against.mp3', 'phr.使抱偏见，使怀成见', '0f4c739ecc8b8133c360c570f5c00efe.jpeg', '', 'The fox prejudiced against the tiger because of the scars on him.', '狐狸因为老虎身上的伤疤而对其持有偏见。', '302543051b35de1ee895dc522260c45c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1117, 'pretty', '/ˈprɪti/', 'pretty.mp3', 'adj.漂亮的，俊俏的；  adv.很，颇，相当', '57804350eb6b46d38664cd23fe25822e_62301_1656663898.jpg', 'd_24_16058_0_3_20150808231100.png', 'This puppy is so pretty.', '这条小狗真好看。', 'us_This_puppy_20220708093927732_5958c01a94d0d1e04349.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1118, 'princess', '/ˈprɪnses/', 'princess.mp3', 'n.公主；王妃', 'i_1_8431_0_2_20150808130746-gigapixel-scale.jpg', 'd_105_8431_0_2_20150809060945.png', 'The princess had a pet pony.', '公主有一匹宠物马。', 'v2l3px92zm5yetl6zd2fr7plmanftsts.mp3', 'princ王子 + ess表示女性（人）或雌性（动物） → princess公主，王妃', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1119, 'prohibit', '/prəˈhɪbɪt/', 'prohibit.mp3', 'v.禁止', '0d64656711b8caafe6ca2de65738df14_111955_1605152562.jpg', 'd_107_6570_0_2_20150809020439.png', 'The law prohibits spitting in public.', '该法令禁止在公共场合随地吐痰。', '70de2ec23200c5de_1266883320097975102_250207.mp3', 'pro向前，提前 + hibit拿住，握住 → 在前面拿住 → prohibit阻止，禁止', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1120, 'pull', '/pʊl/', 'pull.mp3', 'v.拉，拖，扯，拔；  n.拉力', '4ae43ffee35a15f0deed8f8042fa632b_180107_1573713472.jpeg', 'd_24_8386_0_3_20150808225630.png', 'The team began to pull on the rope.', '这个队开始拉绳子了。', 'us_The_team_20250514133214484_cf88c0411f91d4ccf578.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1121, 'put away', '/pʊt əˈweɪ/', 'put away.mp3', 'phr.放好；收起来；储存', '5f7e3f8d62c67461497eb8245c7d0cac_101213_1579331363.jpeg', '', 'He finally made the bed and put away the clothes.', '他终于整理了床铺、放好了衣服。', 's7t5egfnjeuqdjp7sjsl8rk8yj689qsn.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1122, 'quickly', '/ˈkwɪkli/', 'quickly.mp3', 'adv.迅速地，快速地', '3_0_20170614071334_69142_c-gigapixel-scale.jpg', 'd_24_19085_0_4_20150809000427.png', 'She runs and eats so quickly.', '她跑步和吃饭都超快。', 'e58e93276fb9ff6c_1266797979923622908_250123.mp3', 'quick迅速的 + ly表副词 → quickly迅速地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1123, 'rat', '/ræt/', 'rat.mp3', 'n.老鼠，耗子', 'eb08fed88291d3f01b1812b90455142f_77706_1750743499.jpg', '20140929_02_45_21_780_v3.png', 'Look! The three rats are waving to us.', '看，这三只老鼠在跟我们挥手。', 'sa_16_15468_0_5_151126160307.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1124, 'reason', '/ˈriːzn/', 'reason.mp3', 'n.原因，理由；  v.论证，推理，劝说', 'cfd01f405bae532f09ce3e6c7e6066c2_189942_1719804190.jpg', 'd_64_13921_0_4_20150809011741.png', 'The reason why he\'s late for school is that he stayed up late doing homework last night.', '他迟到的原因是昨晚熬夜写作业了。', '9cce065461229977_1266883322531523462_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
