INSERT INTO `words` VALUES (1126, 'reform', '/rɪˈfɔːrm/', 'reform.mp3', 'n.革新，变革；改良；  v.革新；改良', '9867b089787492bf75b70b03f027cd99_62401_1524210514.jpg', '20130307_15_59_28_763.png', 'The first emperor of Qin unified currency as part of his reforms.', '秦始皇在其改革中统一了货币。', '17eb90f2e95302b8f7b971429294a881_31601_1621930773.mp3', 're再次 + form形状 → 再形成 → reform改造', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1127, 'relative', '/ˈrelətɪv/', 'relative.mp3', 'n.亲戚，家人，亲属；同类事物；  adj.相对的', 'i_1_7125_0_154_160418120240-gigapixel-scale.jpg', '3_18_20161015102342_23645_c.png', 'The family tree shows all my relatives.', '这张家谱展示了我所有的亲戚。', '3e507624208afb81_1266763403911060032_250117.mp3', 'relat=relate联系 + ive名词后缀，表人 → 亲戚', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1128, 'remedy for', '/ˈremədi fɔːr/', 'remedy for.mp3', 'n. 对……的补救；对……的治疗方法', '4e9ca10f4f924aac8bf90da01269fe5e.jpeg', '', 'This pill is an excellent remedy for a headache.', '这种药丸是治疗头痛的良药。', 'c076104293669984244f0e54d0e0e6e2_33728_1599550268.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1129, 'repeat', '/rɪˈpiːt/', 'repeat.mp3', 'v.重复；重做；  n.复制；重奏', 'f585a2df435c18645c696debb0e3d0e9_179847_1605152912.jpg', 'd_24_5671_0_4_20150808224249.png', 'Sorry', '抱歉，我听不到你说的话。你可以重复一下刚才说的话吗？', 'nncbm72jj8wszkzpjcmtlq65dgma6t3b.mp3', 're再，重新 + peat追寻，努力 → 重新努力一次 → repeat重复，重做', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1130, 'respond to', '/rɪˈspɑːnd tuː/', 'respond to.mp3', 'phr.（对某种治疗）有良好反应', '178ab13810dcc72e2fbcb19fbd8d7603.jpeg', '', 'He has responded well to his recent hair loss treatment.', '他最近的脱发治疗效果显著。', 'f79d62cfe932c9eb5bd58b885b75b2ba.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
