INSERT INTO `words` VALUES (1133, 'return', '/rɪˈtɝːn/', 'return.mp3', 'v.返回；归还', 'i_13_17970_0_2_20150808205205-gigapixel-scale.jpg', 'd_24_17970_0_4_20150808233834.png', 'Return to where you came from.', '从哪儿来回哪儿去。', 'vcd42rcywt9xh5jsvearzh3pxtmtdxcg.mp3', 're回，向后 + turn转 → return回来，返回', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1134, 'ridiculous', '/rɪˈdɪkjələs/', 'ridiculous.mp3', 'adj.可笑的，荒谬的', '377ef99bb408469c0780c336896dd177_102973_1699412783.jpg', 'd_107_2291_0_2_20150809002534.png', 'He amused the audience with his ridiculous look.', '他用自己的滑稽模样来逗乐观众。', 'cgetfkt8dtwec4ewh347qawu89lelgqx.mp3', 'ridi取笑 + cul + ous表形容词 → ridiculous可笑的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
