INSERT INTO `words` VALUES (1138, 'run', '/rʌn/', 'run.mp3', 'v.管理，运营（公司等）', 'a74b33ce9315fe6b62f0c289e97f5f98.jpg', 'd_43_17954_0_3_20150808234635.png', 'For a while', '她曾有一段时间在经营餐馆。', 'ba923441960ece33_1266883012082772976_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
