INSERT INTO `words` VALUES (1140, 'servant', '/ˈsɜːrvənt/', 'servant.mp3', 'n.佣人，仆人', 'i_24_16512_0_4_20150808231455-gigapixel-scale.jpg', 'd_57_14138_0_4_20150809005533.png', 'The servant served them with drinks.', '这个佣人给他们送上了饮料。', 'sa_24_16512_0_4_20150808231455.aac', 'serv服务，保持 ＋ ant表示人 → servant仆人；公务员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
