INSERT INTO `words` VALUES (1143, 'sky', '/skaɪ/', 'sky.mp3', 'n.天空；  v.将……击向空中', '8ccafa8c6c466890cd392fed1ef3322b_98995_1588138133.jpeg', 'd_24_19456_0_3_20150809001316.png', 'There are white clouds in the blue sky.', '蓝蓝的天空中飘着白色的云朵。', '5xs9kprd3t4pkpgkegp2d8chfpe2but4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1144, 'snack', '/snæk/', 'snack.mp3', 'n.零食，小吃，快餐', 'snack_6502_20231106_6b891361.jpg', '20130130_16_17_44_384.png', 'I\'ve prepared a few snacks for you to enjoy before dinner.', '我准备了一些零食供你在晚餐前享用。', 'sa_1_6502_0_4_20150808125208.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1145, 'special', '/ˈspeʃl/', 'special.mp3', 'adj.特别的；附加的，额外的', '4c03f6b4d10ed6696b8600ad5422e76b_83404_1744097560.jpg', 'd_24_17951_0_4_20150808233714.png', 'Their wedding anniversary was a very special day to them.', '结婚纪念日对他们来说是特别的一天。', '002660370dcdcb21_1266763402509113884_250117.mp3', 'speci种类 + al…的 → 比其他种类好的 → special特别的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1146, 'square', '/skwɛr/', 'square.mp3', 'n.广场；正方形；  v.把……弄成正方形；  adj.正方形的', 'f38c8083e4ecd0492435457180385198_102125_1582792203.jpeg', 'd_24_4635_0_3_20150808223539.png', 'This square is a nice', '这个广场安静宜人，是个散步的好地方。', 'mz57rr3spnj5d93yzn96x45h4exmmby7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1147, 'stock', '/stɑːk/', 'stock.mp3', 'n.股票', 'i_13_3874_0_7_160105191617-gigapixel-scale.jpg', 'd_107_3874_0_2_20150809003257.png', 'Many types of stocks are displayed on the large screen.', '大屏幕上显示着多种类型的股票。', 'sa_1_3874_0_7_160111154713.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1148, 'suffer from', '/ˈsʌfər frʌm/', 'suffer from.mp3', 'phr.遭受，患病', 'i_32_19996_0_4_20150808235123.jpg', '', 'The lady #suffers from# a toothache.', '这个女士遭受牙疼的折磨。', 'sa_32_19996_0_4_20150808235123.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1149, 'summary', '/ˈsʌməri/', 'summary.mp3', 'n.摘要，总结；  adj.简略的，概要的', '3_0_20170713071252_51112_c-gigapixel-scale.jpg', 'd_107_6139_0_2_20150809015043.png', 'I made a summary of this article.', '我对这篇文章做了一下总结。', '8e25fb26f4c2d13d5dbc629d9133bf9a_11487_1618197230.mp3', 'summ总数 + ary表名词 → 内容总和 → summary摘要', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1150, 'superficial', '/ˌsuːpərˈfɪʃl/', 'superficial.mp3', 'adj.表面的；肤浅的；微不足道的；  n.表面文章', '8b8d3e541e642031796e7c30495fd7a8_201373_1534219206.jpeg', 'db8e32275b62f65c05994bca377fc8f7_72703_1551253240.png', 'The house may look new', '这栋房子看起来很新，但这只是表面现象。', 'b233978cb1dd84456f8525b016b3d77c_37654_1534219202.mp3', 'super在…上面 + fic做 + ial形容词后缀 → 在表面上做 → 肤浅', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1151, 'sympathetic', '/ˌsɪmpəˈθetɪk/', 'sympathetic.mp3', 'adj.有同情心的，同情的；赞同的，支持的', '4787cdb5f1a584b065f7c92a9ad38e5b_98362_1732085649.jpg', 'd_107_4083_0_2_20150809004315.png', 'The lady feels sympathetic towards the beggar', '这位女士很同情这个乞丐，所以给了他一些钱。', '0dbc111ca91f29cb_1266883321269824350_250207.mp3', 'sym共同 + path感情 + etic形容词后缀 → sympathetic同情的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1152, 'tell from', '/tel frʌm/', 'tell from.mp3', 'phr.看出', '9b0ccee57d7ed3699a8ec253989a23ca.jpeg', '', 'She could tell from his expression that he was angry.', '她从他的表情看出他生气了。', '7ec45f56287c6a3086da62cabc5f9e72_41326_1600071436.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1153, 'tendency', '/ˈtendənsi/', 'tendency.mp3', 'n.趋向，趋势，倾向', 'i_13_3954_0_4_160105191225-gigapixel-scale.jpg', 'd_16_3954_0_2_20150808223857.png', 'There is an increasing tendency in our sales.', '我们的销量有增长的趋势。', 'us_There_is_20240314094056607_33920c7b9e2f325a1b67.mp3', 'tend倾向 + ency名词后缀；状态 → tendency倾向', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1154, 'tender', '/ˈtendər/', 'tender.mp3', 'adj.温柔的；柔弱的，脆弱的；嫩的；  n.煤水车；  v.提出（希望对方接受的意见等）', '57dee93d63539ad906acb0ad9197476d_63195_1565342778.jpg', 'd_14_5989_0_2_20150808162813.png', 'You have to be soft and tender with the baby.', '你得对婴儿温柔呵护。', 'd97d14f3f92c8edad730641ed5a02cab_13054_1538651389.mp3', 'tend伸，伸出 + er形容词后缀 → 刚伸出的嫩芽 → tender嫩的，柔软的，温柔的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1155, 'text', '/tekst/', 'text.mp3', 'n.正文，原文，课文；  v.发送短信', '510f62e6d2a76d5370b71032e48e42f4_118121_1595468529.jpeg', '20141012_19_16_12_917_v3.png', 'Mary is reading the text before answering the exam question.', '在回答考试问题前，玛丽正在阅读正文。', '5186cbc950a782890d7f5d3c38ebdf20_48080_1595468534.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1156, 'think of', '/θɪŋk ɑv/', 'think of.mp3', 'phr.认为，看法；想起，考虑', 'c_i_wm_20120923_03_40_50_116.jpg', '', 'He wants to think of something that can change him.', '他想要想出一些能改变他自己的东西。', 'sa_16_17584_0_5_20150809011620.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1157, 'think of...as', '/θɪŋk əv æz/', 'think of...as.mp3', 'phr.把...看作', '762cb8dddf6823aa0b40dcac405a228d.jpeg', '', 'He thinks of the Mona Lisa as the best painting in the history of art.', '他把《蒙娜丽莎》视为艺术史上最优秀的画作。', '9a39a4efd87a327188616f8b4a0edd6f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1158, 'toilet', '/ˈtɔɪlət/', 'toilet.mp3', 'n.马桶', 'i_16_17121_0_4_151223185153-gigapixel-scale.jpg', 'd_24_17121_0_4_20150808232043.png', 'The boy is cleaning the toilet.', '那个男孩正在清洗马桶。', 'pgpmvhsqu4cpyn7ex48l8dg29v27a6el.mp3', 'toil网 + et小词后缀 → 用作梳妆台台布的小块薄麻布 → 梳洗引申到马桶', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1159, 'top', '/tɑːp/', 'top.mp3', 'n.顶部，顶端；  adj.（位置、级别或程度）最高的；  v.达到顶端', '4dee01a48129aa5c6c9dec109d50ce1b_88585_1574910513.jpeg', '20121225_19_18_53_437.png', 'He stands on the top of the mountain.', '他站在山顶上。', '8f6fae98bf490d15def9ad43c0d37902_13055_1596092068.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1160, 'totally', '/ˈtoʊtəli/', 'totally.mp3', 'adv.完全地，全部地，彻底地', '3_0_20170712071415_21141_c-gigapixel-scale.jpg', 'd_16_17332_0_4_20150809005939.png', 'The moon is totally blocking the sun\'s light.', '月球完全阻挡了射到地面的阳光。', '6bcc54f60522ce0bcbe5fcdbe97f7f5e_48800_1597657391.mp3', 'tot合计 + ally...地 → totally完全地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1161, 'triangle', '/ˈtraɪæŋɡl/', 'triangle.mp3', 'n.三角形', '6672885333440cee349ad226df27a43b_44501_1557977623.jpeg', 'd_105_6412_0_2_20150809055738.png', 'A triangle has three angles and three sides.', '三角形有三个角和三条边。', 'jwtbm5vq5m437zd96njarylptk8nakub.mp3', 'tri三 + angle角 → triangle三角形', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1162, 'truth', '/truːθ/', 'truth.mp3', 'n.真相，事实', '11ab1a63fa6060595aecca35a5831f6f_150468_1534153154.jpeg', 'd_96_14603_0_4_20150809014435.png', 'The truth is that the Batman is actually just the cat\'s shadow.', '真相是这个“蝙蝠侠”只是这只猫的影子。', 'uxdvftxmvhtyk6wq6xvanenmdeg5s5ue.mp3', 'tru相信，真实 + th抽象名词 → truth事实，真理', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1163, 'uncertain about', '/ʌnˈsɜːrtn əˈbaʊt/', 'uncertain about.mp3', 'phr.对...不确知的', 'e83a86ac12ab023aa3d79b76c794de78.jpeg', '', 'He is uncertain about which way he should go.', '他不确定自己该走哪条路。', 'us_He_is_20241009154346761_545f00002fc8244f2448.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1164, 'unprecedented', '/ʌnˈpresɪdentɪd/', 'unprecedented.mp3', 'adj.前所未有的，空前的，无前例的', 'd7304edd9bf9ee59975cc5a17e6f10fe_201075_1584535447.jpeg', '', 'In 1903', '1903年，莱特兄弟进行了一次前所未有的飞行。', '1f825168ea5b68bae9b6fa5e1a1b6a80_48118_1584535444.mp3', 'un不，没有 + pre预先 + ced走 + ent形容词后缀 + ed形容词后缀 → 无先例的，空前的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1165, 'used', '/juːst/', 'used.mp3', 'adj.旧的', '3_0_20170614071231_25807_c.jpg', 'd_24_17664_0_3_20150808233232.png', 'My phone is used', '我的手机用旧了，但我不打算换新的。', '3_0_20170614071231_428_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1166, 'vanish', '/ˈvænɪʃ/', 'vanish.mp3', 'v.消失；突然不见；消灭；  v.使消失；使不见', '9ea57d6fdc31ccad217ea81c73d1c5a8_188292_1584960634.jpeg', 'd_107_5459_0_2_20150809012656.png', 'The magician waved the wand and the woman vanished.', '魔术师挥动了一下魔杖，那位女士就消失了。', 'c5hxwdtekdyv6hrud87huuvz6da7j7vy.mp3', 'van空 + ish动词后缀 → 凭空消失了 → vanish突然不见，消失', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1167, 'various', '/ˈveəriəs/', 'various.mp3', 'adj.各种各样的，不同的', '79e2040d8fa362c8b549358caf3195b1_141056_1540798907.jpg', 'd_16_10294_0_2_20150808235435.png', 'We saw various types of fish during our dive.', '潜水时，我们看到了各种各样的鱼。', '33a938124ffa6d60_1266883627371572040_250207.mp3', 'vari变化 + ous形容词后缀 → various不相同的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1168, 'verify', '/ˈverɪfaɪ/', 'verify.mp3', 'v.查证，证明，证实', '7eb153030ea625b650abe9345d965481_60285_1524824766.jpeg', 'd_13_6932_0_2_20150808192748.png', 'This card can verify the man\'s identity.', '这个证件可以证实此人的身份。', '90c88d792573f89dfd800441bbfd576d_34799_1524824792.mp3', 'veri真实 ＋ fy使... → 使真实 → verify核实', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1169, 'wall', '/wɔːl/', 'wall.mp3', 'n.墙；  v.堵塞；用墙围住', '3_0_20160603095433_19540_c-gigapixel-scale.jpg', 'd_24_17994_0_4_20150808234028.png', 'This wall is made up of oddly shaped bricks.', '这道墙由形状不规则的砖砌成。', '3_0_20160603095433_65216_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1170, 'weekday', '/ˈwiːkdeɪ/', 'weekday.mp3', 'n.工作日，平日', '716bf1e04d3de62b595127a3b9df814f_159397_1577936350.jpeg', 'd_109_17022_0_2_20150809061608.png', 'He works on weekdays', '他在工作日上班，从星期一上到星期五。', 'b8011c7ca87136d6d8e26fd5ac9f0773_39118_1577936348.mp3', 'week一周 + day日子 → 一周里除了周末 → 工作日', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1171, 'western', '/ˈwestərn/', 'western.mp3', 'adj.有西方特征的；  n.西部影片', 'eda1f0688ec0b1bc133679904ec62b05_54407_1695009040.jpg', '20141005_02_19_33_15_v3.png', 'I decided to wear a western style wedding dress.', '我决定穿西式婚礼裙。', 'us_I_decided_20231008095225028_5badf84166e4522aa4c9.mp3', 'west西方 + ern……方向的 → western西方的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1172, 'widely', '/ˈwaɪdli/', 'widely.mp3', 'adv.广泛地，普遍地', 'e96fcc7078a446a107a8b34f3969dec1_200834_1587477228.jpg', '', 'The color red is widely used during the Spring Festival celebrations.', '欢度春节时，处处可见红色。', '5rrpbewjlhqagkg6x8xkjrxssv2z4qxg.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1173, 'withdrawal', '/wɪðˈdrɔːəl/', 'withdrawal.mp3', 'n.取款；退股', 'withdrawal_2643_20231106_ddcb809b.jpg', '', 'I made a withdrawal from my bank account.', '我从我的银行账户里取了一笔钱。', '3_0_20160720071217_47189_c.aac', 'with向后，相反 + draw拉 + al表名词后缀 → withdrawal撤退', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1174, 'withstand', '/wɪðˈstænd/', 'withstand.mp3', 'v.忍受；抵挡', '695dda12f4aa41ee559989a82ba04ef9_187465_1556345953.jpeg', '20141013_14_47_45_846_v3.png', 'We all have to withstand our own pressures in life.', '我们都不得不承受各自的生活压力。', '8f9efd0304d3beccbfed787c8def5383_43679_1556345969.mp3', 'with向后，相反 + stand站 → 向相反的方向站 → withstand抵抗，反抗', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1175, 'above all', '/əˈbʌv ɔl/', 'above all.mp3', 'phr.首先', 'fa994757ce4b66e606281c5413fe57fc_84118_1713162324.jpg', '', 'Above all', '”首先，要准时！“ 我们的英语老师说道。', 'sa_16_17841_0_5_160513094300.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1176, 'add...to...', '/æd tu/', 'add...to....mp3', 'phr.往……加入……', 'i_37_20155_0_3_20150809012551.jpg', '', 'Add some sugar to your coffee to make it sweeter.', '给你的咖啡加点糖让它更甜。', 'sa_37_20155_0_3_20150809012551.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1177, 'and so forth', '/ənd soʊ fɔːrθ/', 'and so forth.mp3', 'phr.等等，诸如此类', 'b1c00dc14d5244dc5ca00bcb444ff69f_146570.jpg', '', 'We discussed everything— when to go', '我们讨论了全部细节-什么时候走，去看什么等等。', 'aeb586025ec3552db6eadfff06e1b41f_43531.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1178, 'angry', '/ˈæŋɡri/', 'angry.mp3', 'adj.愤怒的', 'i_69_11707_0_4_20150809003220-manual-scale.jpg', '729f7c376ebdb2afbffdf1d58dbd1f9c_28110_1539341565.png', 'The phone call makes him very angry.', '这通电话让他非常生气。', '68d494bf716907a0_1266883001922399224_250207.mp3', 'angr痛苦 + y表形容词 → angry愤怒的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1179, 'apartment', '/əˈpɑːrtmənt/', 'apartment.mp3', 'n. <美>公寓', '20120511_04_33_57_559-gigapixel-scale.jpg', 'd_16_9286_0_4_20150808234226.png', 'We have rented an apartment; time to buy some furniture.', '我们租了一套公寓，现在该去买些家具了。', '991a12393a7ce84dc0ef047447b4cd6b_46256_1597654044.mp3', 'apart分离的，分开的 + ment名词后缀 → 楼房分隔开住的地方 → 一套公寓房间', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1180, 'appeal to sb. for sth.', '/əˈpiːl tuː ˈsʌmbədi fɔːr ˈsʌmθɪŋ/', 'appeal to sb. for sth..mp3', 'phr.呼吁，恳求', 'fe0f704592f01cf88b50212a9a650551.jpg', '', 'She appeals to us for protecting forests.', '她呼吁我们要保护森林。', '62f4d5ba78a6abe5db16ae2fcec85c9e_44576_1593575230.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1181, 'arouse', '/əˈraʊz/', 'arouse.mp3', 'v.唤起', '365ac9dfd5057d84ca99f60ecf91017e_70000_1707019155.jpeg', '', 'Being aroused from sleep is the beginning of his day.', '从梦中醒来是他一天的开始。', 'us_Being_aroused_20240204115923507_30c7455c70a5e0b4214a.mp3', 'a在...的 + rouse唤醒 → arouse唤起', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1182, 'as a rule', '/æz ə rʊl/', 'as a rule.mp3', 'phr.通常', '0472be1b89b03a6c0f4508d40df79dce.jpg', '', 'As a rule', '通常情况下，他每天晚上8点给妈妈打电话。', 'f2a6a5453cb93c01b68d729521450596.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1183, 'at all times', '/ət ɔl taɪmz/', 'at all times.mp3', 'adv.无论何时；经常，一直', '8b65f5e2c6d66e421ef0ac7d274ec0e0_44055_1584955544.jpeg', '', 'The lost-and-found center is staffed at all times.', '这个失物招领中心无论何时都有工作人员。', '25d0c17ca0f814b6dba18938557b3e7f_49298_1584955653.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1184, 'attribute to', '/əˈtrɪbjut tu/', 'attribute to.mp3', 'phr.把……归因于', 'a326d61129b61787d738610bfe8eeaa2.jpeg', '', 'He attributed his cold to the changeable weather. ', '他将自己的感冒归因于多变的天气。', 'bcdd6531f90828049a2b77a1e5f8a0f6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1185, 'balance between', '/ˈbæləns bɪˈtwiːn/', 'balance between.mp3', 'phr.……之间的平衡', '0634d848ab1a5075a7e55d4a7d62ddba.jpg', '', 'We should find a balance between work and health.', '我们应该找到工作和健康之间的平衡。', '711c5cfdf2850782977b018a0af94d5f_50336_1593575447.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1186, 'barrier to', '/ˈbæriər tuː/', 'barrier to.mp3', 'phr.……的障碍', 'bf030d552aff4a59f0da6a4d76bbd1f9_109578_1707015987.jpg', '', 'Lack of confidence is a barrier to success.', '缺乏自信是通向成功的阻碍。', 'us_Lack_of_20240204104814595_1a8bf52665848b140790.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1187, 'basket', '/ˈbæskɪt/', 'basket.mp3', 'n.篮，篓，筐', '8ec1893510f00fcc55b251aa3b02f36b_98272_1574842207.jpg', '20130301_10_53_25_37.png', 'I always use this basket to pack food for a picnic.', '我经常用这个篮子来装野餐的食物。', 'gtffs6pg92wkermpdvu5qdtbkefm63e3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1188, 'be accused of', '/bi əˈkjuzd ʌv/', 'be accused of.mp3', 'phr.被指控，被控诉', '6e5bba9fc2a5c617aeeb0d7e6a97d3bc.jpg', '', 'He was accused of theft.', '他被指控盗窃。', 'd7b26bd0abb5dcbcfb60cdb588b05c3a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1189, 'beneficial to', '/ˌbenɪˈfɪʃl tuː/', 'beneficial to.mp3', 'phr.对…有益，对…有利', 'a156da27593026373b0d31f1a86d9e00.jpeg', '', 'A healthy balanced diet is beneficial to health. ', '平衡的膳食对身体健康有益。', 'a40edb140ed2444e364c061addb4f47d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1190, 'bitter', '/ˈbɪtər/', 'bitter.mp3', 'adj.味苦的；带来痛苦的；严寒的', '5df8699778ae5a08945f26cf0206a412_56079_1732253329.jpg', 'd_46_11876_0_4_20150809004056.png', 'The coffee is so bitter for the kid.', '咖啡对小孩来说太苦了。', '8rylzbu3293evvc2dfwjlfm5gprvdjrm.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1191, 'bowl', '/boʊl/', 'bowl.mp3', 'n.碗；（保龄球等运动使用的）木球', '14d846e88e3923d44b7322046d4dd893_43513_1575012009.jpg', 'd_24_18155_0_4_20150808235044.png', 'The four bowls are in four different colors.', '这四个碗分别有四种不同的颜色。', '156edd0e546f2527_1266763312234125908_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1192, 'breakfast', '/ˈbrekfəst/', 'breakfast.mp3', 'n.早餐；  v.吃早饭', '6a201d218b1300853134d06e2733185c_193310_1527237505.jpg', '20130315_17_32_28_592.png', 'Breakfast is the most important meal of the day.', '早餐是一天中最重要的一餐。', 'f0a940494d308bb4_1266741765613050586_250113.mp3', 'break中断 + fast斋戒 → 中断斋戒进食 → breakfast早饭', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1193, 'bring forward', '/brɪŋ ˈfɔrwərd/', 'bring forward.mp3', 'phr.提出；提前', '3acb09339015c78be327b21ff2c428d1_161415.jpg', '', 'She is always bringing forward new ideas in meetings.', '她总是可以在会议中提出新的想法。', '9841bf534d38f484215657150c3aef20_37291.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1194, 'broad', '/brɔːd/', 'broad.mp3', 'adj.宽阔的；  n.宽阔部分', '7ed30a80d90c8cfb931b97f9b3f7e054_90812_1602226155.jpg', 'd_16_8268_0_2_20150808232757.png', 'This road is broad enough for many cars to drive on.', '这条道路足够宽，可以容纳很多车行驶。', 'sa_16_8268_0_4_151223154516.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1195, 'business', '/ˈbɪznəs/', 'business.mp3', 'n.事务', 'b4be2d21713a1a810689e1e107924ea3.jpeg', 'd_24_15897_0_3_20150808230733.png', 'What she does to relax herself is her own business.', '她做什么来放松自己是她自己的事。', 'ae6b45a2f94205ef_1266763558498359882_250117.mp3', 'busi=busy忙碌的 + ness性质，表名词 → 对某事很关心、焦虑 → business事务；生意', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1196, 'button', '/ˈbʌtn/', 'button.mp3', 'n.按钮，开关；  v.扣上纽扣', 'i_1_7262_0_4_150926142753-gigapixel-scale.jpg', 'd_109_7262_0_2_20150809055029.png', 'Press the button to turn off the computer.', '按这个按钮关掉电脑。', 'z6824cuy4febwd8ggqvsbzx4bk4p55up.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1197, 'by far', '/baɪ fɑːr/', 'by far.mp3', 'phr.到目前为止', 'dc808eb25c03b81204e888bf414a5e8a.jpg', '', 'This is by far the fastest he has ever run 100 meters.', '这是迄今为止他跑100米最快的一次。', '60ac6bda43df80b16d2d402877ce1409.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1198, 'call off', '/kɔːl ɔːf/', 'call off.mp3', 'phr.取消', '888cbcf96b7ccececbb7a68b196c867f_86499_1573899797.jpeg', '', 'The flight #was called off# because of bad weather.', '航班因恶劣天气而被取消了。', '49c68fefe89cfedb_1266883488143727280_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1199, 'cancel', '/ˈkænsl/', 'cancel.mp3', 'v.取消；废除', '3_0_20170930071443_26188_c-gigapixel-scale.jpg', 'd_24_16015_0_4_20150808231039.png', 'I cancelled my shopping order.', '我取消了我的购物订单。', '177c3de75dcb9c95_1266883374041029144_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1200, 'caring', '/ˈkerɪŋ/', 'caring.mp3', 'adj.关怀的，体贴的', '405c3ce4a02891892d0f34e6de38b14b_103462.jpg', '', 'The hospital aims to provide a caring environment.', '这家医院以提供充满关怀的环境为目标。', '884f2a323d00395912e0f45140996aba_29728.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1201, 'certain', '/ˈsɜːrtn/', 'certain.mp3', 'adj.有把握的；肯定的，必然的', 'd2955a5ab07d078d796eed4f9a291389_198040_1575019707.jpeg', 'd_24_17416_0_4_20150808232750.png', 'The man is certain the milk will spill out everywhere.', '那个男人确信牛奶会洒得满地都是。', '40b28d05bf1319314bf200bb817a2d5a_40414_1575019704.mp3', 'cert确实 + ain形容词后缀 → certain确实的，一定的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1202, 'channel', '/ˈtʃænl/', 'channel.mp3', 'n.频道，电视台；  v.引导', 'd63efcec91f0f5c7a22bd9c7d5c2feb2_148181_1701049464.jpg', 'd_24_5121_0_3_20150808223930.png', 'We can use the remote control to change channels.', '我们可以用遥控器来换频道。', 'dwze78a6wlfnxs4f953h6fv8v7wfjybc.mp3', 'chann管道 + el表名词 → channel航道；渠道；频道', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1203, 'cheque', '/tʃek/', 'cheque.mp3', 'n.支票', '077330bb6187efb68161fb296a776bbe_184850_1729761411.jpg', '', 'The boss is signing the cheque.', '老板在开支票。', 'us_The_boss_20250310112213193_7655383bc82c7cadbdd0.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1204, 'clockwise', '/ˈklɑːkwaɪz/', 'clockwise.mp3', 'adj.顺时针方向的；  adv.顺时针方向地', 'cfefada9461e9bc9643182389e42af5f_104604_1583833992.jpeg', '20140725_11_43_06_247_v3.png', 'The man is walking around the garden in a clockwise direction.', '那个男人以顺时针方向在花园里散步。', 'bc087e1ba0a7c555018f04eae5d92195_49644_1583833988.mp3', 'clock时钟 + wise方向，状态 → clockwise顺时针的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1205, 'coin', '/kɔɪn/', 'coin.mp3', 'n.硬币；  v.铸造（硬币）', '6d7c4329eb726c9272f9a2c2687b23a2_33445_1657792633.jpg', 'd_24_16164_0_4_20150808231134.png', 'This coin is worth ten cents.', '这枚硬币值10美分。', 'c415f760ecb2fc53_1266883195117087736_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1206, 'comparable', '/ˈkɑːmpərəbl/', 'comparable.mp3', 'adj.类似的，比得上的，可比较的', 'i_1_6236_0_3_20150808124858-gigapixel-scale.jpg', 'd_107_6236_0_2_20150809015344.png', 'The two dogs are comparable in size and strength.', '这两条狗在大小和强壮程度方面都不相上下。', 'sa_1_6236_0_3_20150808124858.aac', 'compar=compare比较，对照 + able形容词后缀，可……的 → (to)比得上的；(with)可比较的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1207, 'complex', '/kəmˈpleks/  ', 'complex.mp3', 'adj.复杂的，难解的；复合的（读作/kɑmˈplɛks/）；  n.情结', 'fb06f881b584c5334d8671efc245f8c4_181369_1564733430.jpg', 'd_107_5433_0_2_20150809012525.png', 'He has no clue about how to solve this complex case.', '他对如何解决这个复杂的案件毫无头绪。', '8zrpaeqaeu854ern45rbppaqags8lwgw.mp3', 'com共同 + plex重叠 → 全部重叠 → complex复杂的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1208, 'computer', '/kəmˈpjutər/', 'computer.mp3', 'n.计算机，电脑', '08b4e47d852b6bbf75167533b2ed8863_55792_1541817632.jpg', 'd_24_17984_0_3_20150808233934.png', 'Why is there only a white background on the computer screen?', '为什么电脑屏幕上只有一个白色的背景？', 'a4765c20c07b6508_1266763401858013712_250117.mp3', 'com一起 + pute估计，精简 + r → 通过计算确定 → computer计算机，电脑', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1209, 'constant', '/ˈkɑːnstənt/', 'constant.mp3', 'adj.持续不断的；不变的；  n.常数，恒量', '08c0ce370ba7b7979c2780a968210cab_165858_1527578233.jpg', 'd_24_10379_0_3_20150808230437.png', 'The baby needs his mother\'s constant attention.', '这个婴儿需要妈妈时刻的照料。', '3d1102ee899d16325364dda673c0c86a_17905_1527578078.aac', 'con始终 + stant站立 → 始终站着 → constant不变的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1210, 'crew', '/kruː/', 'crew.mp3', 'n.（有专门技术的）一组工作人员，（飞机、轮船等的）全体工作人员', '42755bc981c23ea228dba4871da2f37d_83996_1570703023.jpeg', '20141007_02_43_52_681_v3.png', 'This is a picture of the crew and the aircraft.', '这是一张机组人员与飞机的合影。', '5fe67476fa5a7060e1a91accaf6b63f9_33070_1591775674.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1211, 'curtain', '/ˈkɜːrtn/', 'curtain.mp3', 'n. 窗帘；  v.装帘子，遮掉', 'bbbaa202e0f156c631c7a97db767d44c_137447_1728453714.jpg', 'd_24_6340_0_4_20150808224605.png', 'Look! A little girl is hiding behind the curtain!', '看！有个小女孩正躲在窗帘后面！', '648730eeee87538d_1266763558409186136_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1212, 'dentist', '/ˈdentɪst/', 'dentist.mp3', 'n.牙医', 'd81f1ff527ff66e480567265588f5425_68751_1569056051.jpg', '20141011_23_51_16_591_v3.png', 'The dentist cleaned my teeth.', '牙医清洗了我的牙齿。', '9c14ec59fca5535e_1266763446984202924_250117.mp3', 'dent牙齿 + ist人 → dentist牙科医生', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1213, 'devoted', '/dɪˈvoʊtɪd/', 'devoted.mp3', 'adj.热衷的，致力于…的', 'a79b47bd2eff77857a624b40c6789d4d_218771_1682605916.jpg', '', 'They are devoted to delivering an outstanding performance.', '他们致力于献上出色的表演。', 'us_They_are_20231219164558119_70e6346059fdfc880b33.mp3', 'de使成…、作成…、或仅作加强意义 ＋ vot=vow，表示”发誓“ ＋ ed形容词后缀 → devoted投入的，深爱的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1214, 'disconnect', '/ˌdɪskəˈnekt/', 'disconnect.mp3', 'v.断开，拆开，使分离', '5b83a79f138ee0e722b3f1f5f116b7c0_34116_1701762655.jpg', '20140807_05_00_27_248_v3.png', 'The phone company disconnected my phone service because I didn\'t pay my bill.', '电话公司切断了对我的服务，因为我没有付我的账单。', 'axrm5xfwkgs4rlsku53fyxdmbjfy4y8a.mp3', 'dis分开 + con共同 + nect连结 → 拆开，分离', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1215, 'discussion', '/dɪˈskʌʃn/', 'discussion.mp3', 'n.讨论，谈论', '2541bf234a8a0f3a768c1126b7164555_68699_1535524600.jpeg', '20141015_05_35_54_260_v3.png', 'The teacher and kids are in a discussion about the Earth.', '老师和孩子们在进行一场关于地球的讨论。', '7a37bf9de946745479b99c66eafb4e0c_36349_1535524499.mp3', 'discuss讨论 + ion名词后缀 → discussion讨论', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1216, 'distinguish from', '/dɪˈstɪŋɡwɪʃ frʌm/', 'distinguish from.mp3', 'phr.区分，辨别', '00d9ae608aff1a0ec577c852a8d8f993.jpg', '', 'Only the owner can distinguish her pet dog from the other.', '只有主人能把她的宠物狗和另一只狗区分开。', '4a3c3f32b39901982b843ca89fd64de7_25673_1621931007.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1217, 'dose', '/doʊs/', 'dose.mp3', 'n.（药的）剂量，用量，一剂；  v.给……服药', '406438bf3161fcc32d082fb8cc170845_88095_1586767981.jpeg', 'd_107_4057_0_2_20150809004210.png', 'The doctor is telling the patient the recommended dose of his medicine.', '医生正在告诉病人药物的推荐剂量。', 'a8be3bc30bf4f5db660f16c34a35bdfd_46130_1586767986.mp3', 'do给，被“给”的+se名词后缀，物品→饮用药量 → 一剂药，一剂', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1218, 'dynamic', '/daɪˈnæmɪk/', 'dynamic.mp3', 'adj.有活力的，有生机的；  n.动力', '995bdc235746585e5572d066e3ef5513_49349_1595060748.jpg', '20141010_21_48_35_408_v3.png', 'This young lady is very dynamic.', '这位年轻的女士很有活力。', 'f4e8e50d776d9962_1266883629959064448_250207.mp3', 'dynam=power，表示“力量” + ic…的 → dynamic有活力的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1219, 'employee', '/ɪmˈplɔɪiː /', 'employee.mp3', 'n.雇员', '3_0_20160528171118_81231_c-gigapixel-scale.jpg', 'd_105_5040_0_2_20150809054349.png', 'The employee felt very happy when his boss praised him.', '听到老板表扬他，这位员工感到很高兴。', 'lj6jsnyzhlleve8zarjyqltsb5cs2thc.mp3', 'employ雇用 + ee人 → employee雇员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1220, 'endless', '/ˈendləs/', 'endless.mp3', 'adj.没完没了的；漫无目的的', 'ebeb044b17fbff63bdf724309820e95e_39934_1565691724.jpg', '20140929_02_51_35_721_v3.png', 'This road seems endless—are we nearly there yet?', '这条路看起来没有尽头啊，我们快到了吗？', 'j3bb22zh47vdsl8gjy5bprckpjd68vga.mp3', 'end结束 + less无…的 → endless无止境的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1221, 'everyday', '/ˈevrideɪ/', 'everyday.mp3', 'adj.日常的，每天的', '3_52_20170512152902_6642_c-gigapixel-scale.jpg', 'd_24_19145_0_4_20150809000919.png', 'Doing exercise and keeping a healthy diet have become my everyday life.', '做运动和坚持健康的饮食已经成了我的日常生活。', '3_41_20170518115143_5896_c.aac', 'every每个的 + day天 → everyday每天的，日常的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1222, 'execute', '/ˈeksɪkjuːt/', 'execute.mp3', 'v.处决；完成（动作）；实行；执行（计划）', 'i_4_4172_0_4_151224094303-gigapixel-scale.jpg', 'd_107_4172_0_2_20150809004715.png', 'This pathetic bird is going to be executed by the cruel hunter.', '这只可怜的小鸟将要被残酷的猎人处决了。', 'sa_1_4172_0_4_151231175316.aac', 'ex向外 + (s)ec跟随，相接 + ute → 一步接一步的执行 → 实施，将……处死', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1223, 'fall back on', '/fɔl bæk ɔn/', 'fall back on.mp3', 'phr.求助于，转而依靠', 'fallbackon_7674_20231106_f4e5b2de.jpg', '', 'When I lost my job', '当我失去工作时，我不得不出去讨钱。', 'sa_11_7674_0_2_20150808173200.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1224, 'February', '/ˈfebrueri/', 'February.mp3', 'n.二月（略作Feb.）', 'bf35f48539f147e6799228ec139f5e0f_160099_1550301567.jpeg', 'd_24_19565_0_3_20150809002027.png', 'February is a special month and only has 28 days this year.', '二月份是一个特殊的月份，这一年的二月份仅有28天。', 'b8c684534b6cbc72_1266763403688192832_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1225, 'feedback', '/ˈfiːdbæk/', 'feedback.mp3', 'n.反馈', 'f5a896bb004196863756109b6736b970_96491_1538661764.jpg', 'd_107_4163_0_2_20150809004645.png', 'A man gave his feedback by ticking a smile box.', '一个男人通过在笑脸框里打钩给出了反馈。', '2a2cba7442406bb4a88c770d22e42ba7_16973_1538661777.mp3', 'feed向…提供 + back返回 → feedback反馈', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1226, 'finish', '/ˈfɪnɪʃ/', 'finish.mp3', 'v.吃完，喝完', '204ff07609c40acd53723d9d19907131.jpeg', 'd_24_16622_0_3_20150808231655.png', 'She has finished her meal.', '她吃完了这一餐。', 'ff61362798cda9ee81284348261bfef9.mp3', 'fin结束，范围 + ish单词后缀 → finish完成，结束', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1227, 'fit', '/fɪt/', 'fit.mp3', 'v.使适合；  n.匹配，相配；合身；  adj.合适的', '11010d0df3fa4b777c42a8cbb8830d6a_61187_1590507515.jpg', 'd_24_2762_0_4_20150808223309.png', 'Let\'s put the last piece in. It fits perfectly!', '让我们把最后一块放进去。它非常合适！', 'bc2e6e181755f7d3545e410b6f298b48_21048_1590507539.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1228, 'France', '/fræns/', 'France.mp3', 'n.法国', '3e9f2e100b35f38fffb371b728e9e717_18465_1654667155.jpg', 'd_24_17520_0_4_20150808232920.png', 'This is the national flag of France. ', '这是法国国旗。', 'us_This_is_20220608134403909_b26eba759f066ee1254f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1229, 'gate', '/ɡeɪt/', 'gate.mp3', 'n.大门', '76bc2f9a1a3b4a58e38b237930722343_84959_1577952124.jpeg', 'd_24_17320_0_4_20150808232658.png', 'The gate with beautiful patterns is made of iron.', '这道有着美丽花纹的大门是铁制的。', 'azv5a263x8zy8x9mk9q27pa6ytg3a45d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1230, 'genius', '/ˈdʒiːniəs/', 'genius.mp3', 'n.天才；天资，天赋', '3_0_20160718114753_20706_c-gigapixel-scale.jpg', 'd_107_1262_0_2_20150809001736.png', 'The musical genius was a composer even in childhood.', '这位音乐天才小时候就是作曲家了。', 'df632009ead21f40_1266883483517999658_250207.mp3', 'gen=gene出生 + ius  → 出生就有  → genius天才', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1231, 'get down', '/ɡet daʊn/', 'get down.mp3', 'phr.弯下身 (坐下、跪下、趴下)', 'd67ef38497a29cdae805745e950f016c_80124_1590215908.jpeg', '', 'The police told the criminal to get down on the ground.', '警察要求这个罪犯趴倒在地。', 'ghwx3vzgshe4q99ax69z8yqnlt8ndq34.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1232, 'go through', '/ɡoʊ θruː/', 'go through.mp3', 'phr.浏览，查阅；通过，完成；经历', '07dc83034de21ffeaa5b2602ac558beb_32573_1580883683.jpg', '', 'He is going through his textbooks to find the right answer.', '他正在翻阅课本寻找正确答案。', '8c567a01e3badf9d2cd48c5b6dea1dd4_35182_1580883652.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1233, 'golden', '/ˈɡoʊldən/', 'golden.mp3', 'adj.金黄色的；特别的，美好的', '3_0_20170707155139_14182_c-gigapixel-scale.jpg', 'd_24_17276_0_3_20150808232546.png', 'This is a golden egg.', '这是一枚金蛋。', 'rkvvj4lfx9bbg9x88c9pnu6nvfs5bmdu.mp3', 'gold金子 + en由…制成的 → golden金色的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1234, 'goods', '/ɡʊdz/', 'goods.mp3', 'n.货物，商品', '20120719_03_43_35_534-gigapixel-scale.jpg', 'd_24_8116_0_4_20150808225508.png', 'The goods are sent to us every day.', '每天，这些货物都会被寄送给我们。', '738eb7faa3e4dd0d_1266883369553779322_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1235, 'guilty', '/ˈɡɪlti/', 'guilty.mp3', 'adj.内疚的；负罪的', 'd6b27480e81e34afe70392ab4a8dc7eb_145064_1535527792.jpeg', 'd_24_7944_0_3_20150808225253.png', 'The dog felt very guilty for destroying the living room.', '这只狗因为破坏了客厅而感到很内疚。', 'lt7pqyn9uvzdkw3knwqxctzd9ln7u2e6.mp3', 'guilt内疚 + y...的 → guilty内疚的；有罪的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1236, 'horror', '/ˈhɔːrər/', 'horror.mp3', 'n.惊恐，震惊；令人惊恐的事', 'abb6b657c189a4aee7c01363ad81e7d8_63421_1588125129.jpeg', '20121225_19_39_49_360.png', 'He screamed in horror when he saw the monster.', '看到怪物时，他惊恐地尖叫了起来。', '3b60df0976a7fe38293e4a0d55adc6fa_39142_1588125754.mp3', 'horr（因惊吓或发怒）毛发竖起 + or引申词义厌恶 -> horror惊恐', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1237, 'horse', '/hɔːrs/', 'horse.mp3', 'n.马；马科动物', 'c6a9128c10f139af41452c4a8eceeb19_110460_1578967769.jpg', '20121225_18_22_58_732.png', 'The black horse is running on the beach.', '这匹黑马正在沙滩上奔跑。', 'bfd64157737b728f_1266763314527492770_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1238, 'hunger for', '/ˈhʌŋɡər fər/', 'hunger for.mp3', 'phr.渴望', '89e72fc34702d89fa687b64a96c626e9.jpeg', '', 'He hungers for victory.', '他渴望胜利。', 'a2a593db1ecb16907a164aaf03749df7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1239, 'in place of', '/ɪn pleɪs əv/', 'in place of.mp3', 'phr.代替', 'e3cc6216d67ae6f9e5438f7af8b266a7.jpeg', '', 'She used milk in place of cream', '她用完了奶油，就用牛奶来代替。', 'b16d1b88584c3eb9_1266883533836364710_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1240, 'in the distance', '/ɪn ðə \'dɪstəns/', 'in the distance.mp3', 'phr.在远处', 'c7d5b7e8d34fb4ded27e041f858a6c0b.jpg', '', 'There\'s an island in the distance.', '远处有一座岛。', '80dc7e289639f63b789120e33f59fb07.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1241, 'information', '/ˌɪnfɚˈmeɪʃn/', 'information.mp3', 'n.信息', 'e76fb046d294c1b501c6fc2045416c72_129115_1736406685.jpg', 'd_24_15896_0_3_20150808230730.png', 'The Internet is my main source of getting information about other countries.', '因特网是我获取其他国家信息的主要来源。', '689b93031d5d25eb_1266883321863187312_250207.mp3', 'inform通知 + ation动作化名词后缀 → information 信息', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1242, 'journey', '/ˈdʒɜːrni/ ', 'journey.mp3', 'n.（尤指长途）旅行，旅程；  v.旅行', 'ff0f4c10faf9e88c39ba71559c226306_94270_1565621543.jpg', 'd_24_5085_0_3_20150808223907.png', 'The family is going on a journey soon.', '这家人马上要去旅行。', '777lw378q7mjft2bd6zr9pmqdpb6neyn.mp3', 'journ日期 + ey表名词 → 按日期计算的行程 → journey旅行，旅程', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1243, 'kite', '/kaɪt/', 'kite.mp3', 'n.风筝', 'f3ace07220c3820aae97019fa717ad9a_94297_1577953983.jpeg', '20121225_19_02_09_484.png', 'The little boy is running to fly his colorful kite.', '这个小男孩正跑着放他的彩色风筝。', 'a55e13e8fb202a2a_1266741632804215430_250113.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1244, 'land', '/lænd/', 'land.mp3', 'n.陆地，土地；大地；  v.（使）着陆', 'i_16_16454_0_5_160427153423-gigapixel-scale.jpg', 'd_24_16454_0_3_20150808231315.png', 'This land is covered with green grass.', '这片土地上长满了青草。', 'xgw9plnpd8wzdzqbj3nm8l7n8n7m5n9c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1245, 'language', '/ˈlæŋɡwɪdʒ/ ', 'language.mp3', 'n.语言，语言文字', '868d355042f5dcbbfec09ab7a144cb62_45626_1619338933.jpg', 'd_24_15910_0_4_20150808230755.png', 'People from different countries speak different languages.', '不同国家的人讲不同的语言。', 'sa_16_15910_0_7_160427135952.aac', 'langu语言 + age表示状态、情况及其他 → language语言，语言课程', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1246, 'living', '/ˈlɪvɪŋ/', 'living.mp3', 'n.生活，生计', 'bbf4cb9ea882d889b28419bceb7470ea.jpeg', 'd_16_19478_0_2_20150809022151.png', 'He makes shoes for a living.', '他靠制作鞋子为生。', '7d54cc05c75dcbec7d79ad3e770687a8.mp3', 'liv生活 ＋ ing名词后缀 → living生活，生计', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1247, 'look on', '/lʊk ɑːn/', 'look on.mp3', 'phr.旁观', '37af4201eb90ea9144f20aa6061aa744.jpg', '', 'They\'re at the marathon', '他们在兴奋地看着马拉松比赛。', '8308db4067aa8691_1266883535524244400_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1248, 'look through', '/lʊk θrʊ/', 'look through.mp3', 'phr.浏览，查看', 'e81ab8dfae497a62bab44391d106250a_189825_1559617495.jpeg', '', 'She is looking through the books on the shelves.', '她在浏览书架上的书。', '3_0_20160520172515_20931_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1249, 'loud', '/laʊd/', 'loud.mp3', 'adj.大声的，吵闹的', 'i_16_16652_0_3_20150809003518-gigapixel-scale.jpg', 'd_24_16652_0_4_20150808231815.png', 'Shut up! Your voice is too loud.', '闭嘴！你太吵了。', '9qpec4azqqtrnmsmrzyfbapp9v3lb8mn.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1250, 'low', '/loʊ/', 'low.mp3', 'adj.低的，矮的，少的；低下的', 'i_13_19567_0_2_20150808205811-gigapixel-scale.jpg', 'd_24_19567_0_4_20150809002037.png', 'When temperatures are this low', '当气温这么低时，最好待在室内。', '834d62ea49be5782_1266797983232404270_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1251, 'mine', '/maɪn/ ', 'mine.mp3', 'n.矿，矿山；  v.开采，采矿；  pron.我的（所有物）', '20120514_03_32_30_985-manual-scale.jpg', 'd_24_8401_0_3_20150808225649.png', 'Will he find any gold in the mine?', '他能在矿里找到金子吗？', '49d4ef67dcefa35a_1266883482558814740_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1252, 'mouse', '/maʊs/', 'mouse.mp3', 'n.鼠', '947cfb1d186366dd30e6b155bb79f3bb_90617_1561616456.jpg', '20140929_02_47_00_317_v3.png', 'The mouse lives in a hole in the wall.', '这只老鼠住在一个墙洞里。', 'aa63618e30819d6f_1266741632865643408_250113.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1253, 'normal', '/ˈnɔːrml/', 'normal.mp3', 'adj.正常的，一般的', 'c4d17adae7c72beafde96a0be52a049c_126775_1718179859.jpg', 'd_24_8110_0_3_20150808225500.png', 'I was glad when the doctor told me my heart beat was normal.', '当医生告诉我我的心跳是正常的时候，我非常开心。', 'd6efe4fff94fb360_1266763524971715186_250117.mp3', 'norm规则，规范 + al形容词后缀 → 有规范的 → normal正常的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1254, 'nowadays', '/ˈnaʊədeɪz/', 'nowadays.mp3', 'adv.现在，当今', '3_0_20170924071145_75058_c-gigapixel-scale.jpg', '94799928ad35548bbe853a4643b72483_21188_1586935471.png', 'Nowadays', '如今，智能手机比这种旧手机先进多了。', '6e88ed79924bf00d2f90b9d42a3958cd_25280_1622427055.mp3', 'nowaday现在 + s表副词 → 现今，当今', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1255, 'on time', '/ɑn taɪm/', 'on time.mp3', 'phr.准时', '50aa65ddabae93dc5659ad73c87f6887_42537_1580884940.jpg', '', 'I\'m very satisfied with the service. My express delivery arrived on time.', '我对这次服务很满意，我准时拿到了包裹。', 'fdb045047f85cada_1266883010128882636_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1256, 'ordinary', '/ˈɔːrdəˌneri/', 'ordinary.mp3', 'adj.普通的，平常的', 'fe5c721dd828d69fd47758bf119f0388_42979_1732507247.jpg', 'd_24_7488_0_3_20150808225115.png', 'I\'m just an ordinary man.', '我只是一个普通的男人。', '27b89abd818a449d_1266763558569728588_250117.mp3', 'ordin排列，安排 + ary → 按安排定好的 → ordinary普通的，平常的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1257, 'over and over again', '/ˈoʊvər ənd ˈoʊvər əˈɡen/', 'over and over again.mp3', 'phr.反复，多次重复', '8dbdeb12c12badefd434d8c537f88441_105132_1580871462.jpg', '', 'He said no over and over again.', '他一遍又一遍地说不。', 'f604ea329ca2e491e240b570abb909b9_44302_1580871456.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1258, 'pardon', '/ˈpɑːrdn/', 'pardon.mp3', 'v.赦免，原谅，宽恕；  excl.请再说一遍；  n.赦免，原谅', 'i_16_18174_0_4_151120164307-gigapixel-scale.jpg', 'd_24_18174_0_4_20150808235137.png', 'The emperor pardoned the prisoner.', '皇帝赦免了那个囚犯。', 'us_The_emperor_20250205135718182_eb31fd64ce509804df17.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1259, 'part', '/pɑːrt/', 'part.mp3', 'v.分离，分开', '82892848124058cc83835d397d2bec78.jpeg', 'd_24_17666_0_4_20150808233235.png', 'She parted the curtains and looked out. ', '她拉开窗帘向外看。', '744aecfaa62a03c4aa3a5be7574871ee.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1260, 'pick up', '/ˈpɪk ˈʌp/', 'pick up.mp3', 'phr.搭载；拿起，捡起；获得，学会', 'd0565ddc808ec9ae4683722bcc7e8e7b_177217_1605494886.jpg', '', 'The woman is waiting in the car to pick up her kid after school.', '这位女士在车里等着接她的孩子放学。', '42e4f5722bbceb8bf05928ef437340eb_20735_1605494793.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1261, 'pile', '/paɪl/', 'pile.mp3', 'n.一堆；  v.堆积', '2cc8d4528eec9bd6e9060eac5c44e58b_139684_1733302418.jpg', 'd_16_9258_0_2_20150808234125.png', 'What a tall pile of books!', '多么高的一摞书啊！', 'd3b8086e02a232b1_1266883372103195336_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1262, 'planet', '/ˈplænɪt/', 'planet.mp3', 'n.行星', '3_0_20170712071226_33189_c-gigapixel-scale.jpg', 'd_109_16666_0_2_20150809061545.png', 'There are 8 major planets in our solar system.', '太阳系中有八大行星。', 'zqlnmky3frbfdpknakh3gtldfcem8wfr.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1263, 'plunge into', '/plʌndʒ ˈɪntu/', 'plunge into.mp3', 'phr.跳入', 'd0084b56f720cafbbd913327ca87460f_187598.jpg', '', 'He plunged into the sea with a loud splash.', '他咚地一声跳进了海里。', '533f335ffe76c23201b816e911e831bc_33079.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1264, 'polar', '/ˈpoʊlər/', 'polar.mp3', 'adj.南极的，北极的；截然对立的，正好相反的；极地的', 'ffd9adefc1fab7972ec7aa135f687e21_115268_1569046515.jpeg', '', 'Penguins and polar bears live in polar regions.', '企鹅和北极熊住在极地地区。', '1611b21db63d84112680620b742bce38_37882_1569046512.mp3', 'pol(e)极点 + ar……的 → polar南（北）极的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1265, 'policy', '/ˈpɑːləsi/', 'policy.mp3', 'n.政策，方针；保险单', 'e8345af063e69f2ad2152047c935a378_94993_1534834944.jpeg', 'd_24_7876_0_4_20150808225151.png', 'The policy in this company forbids employees to have relationships with each other.', '这家公司的政策禁止员工之间谈恋爱。', '0a0890d4574e53d60bcc606d5f466411_28258_1625801767.mp3', 'polic国家，城市 + y名词后缀 → 用以管理国家的依据 → policy政策', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1266, 'put down', '/pʊt daʊn/', 'put down.mp3', 'phr.放下', 'i_16_19289_0_6_160425162629.jpg', '', 'I put down my schoolbag on the desk.', '我把书包放在了桌上。', 'zuqmtl86qa2v2rztxep7tqytksvu4frk.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1267, 'recall', '/rɪˈkɔːl/', 'recall.mp3', 'v.回想起，记起，回忆', 'cb97d581eeb07e814635f702232eb0ec_196857_1585057872.jpeg', 'd_1_5741_0_2_20150808124321.png', 'Looking at the photo', '看着这张照片，她回忆起和丈夫的旧时光。', '9901d54f5e18dec9751ad8f724bb9379_23399_1623740413.mp3', 're回，向后 + call呼唤 → recall召回，回忆', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1268, 'remarkable', '/rɪˈmɑːrkəbl/', 'remarkable.mp3', 'adj.显著的，非凡的，卓越的', 'a6f2a4d0d76aa08c3dcba08cbc7c819d_75113_1585144523.jpeg', 'd_13_3933_0_2_20150808163353.png', 'Alex\'s performance has been remarkable in recent months.', '亚历克斯这几个月的业绩非常出色。', 'ymrp3ejsx8tvbk7frqk4uahb9k77px5v.mp3', 're再 + mark记号，符号 + able能...的 → 再做记号 → remarkable值得注意的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1269, 'resident', '/ˈrezɪdənt/', 'resident.mp3', 'n.居民；住院实习医师；  adj.居住的', 'i_1_9102_0_3_20150808131210-gigapixel-scale.jpg', 'd_105_9102_0_2_20150809061259.png', 'The residents here like to interact with each other.', '这儿的居民喜欢相互交流。', '04f49176699079a2_1266883524871433008_250207.mp3', 'resid=reside居住 + ent人 → resident居民', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1270, 'result', '/rɪˈzʌlt/', 'result.mp3', 'n. 结果，成效；  v.导致', '363234c30472cc621ef20c730c0b200e_192358_1564802513.jpg', 'd_24_17170_0_4_20150808232232.png', 'He was pretty excited after knowing his exam results.', '他在得知自己的考试成绩后非常开心。', 'us_He_was_20240407131314696_4465a986fb927afb658e.mp3', 're反问 + sult跳 → 反馈回来 → result结果', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1271, 'retain', '/rɪˈteɪn/', 'retain.mp3', 'v.保持，保留，保存', '9df768894b0817b29763c2edd0974c4b_193507_1532938382.jpeg', 'd_1_8197_0_2_20150808130451.png', 'Hot water can retain its heat for hours in the vacuum cup.', '热水能在保温杯里保持温度好几个小时。', '0b1bca17c2c1c77306429edb25d99f83_47978_1532938385.mp3', 're回 + tain握住 → 拿回来 → retain保留', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1272, 'revolution', '/ˌrevəˈluːʃn/', 'revolution.mp3', 'n.革命，改革；旋转', 'a96bcbb1923fe5ca8a0563cbf070902b_67197_1559026769.jpg', '20130201_16_30_45_850.png', 'A revolution in science and technology has changed the way that we communicate.', '科技革命已经改变了我们的通信方式。', 'da44af38c5e84a66aa1c13acca5f60b6_39918.mp3', 're重新 + volut旋转，卷 + ion名词后缀 → 重新旋转 → 革命，变革', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1273, 'sad', '/sæd/', 'sad.mp3', 'adj.难过的，悲伤的，忧愁的', 'b22a7e98edbcd34cced93114b1dc1adb_195295_1575017352.jpeg', 'd_24_18137_0_4_20150808234918.png', 'The lonely dog is sad because the owner is on holiday.', '因为主人外出度假，所以这只孤独的狗很悲伤。', '4e5d09f8873b38de_1266763241974356638_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1274, 'security', '/sɪˈkjʊrəti/', 'security.mp3', 'n.安全；保护措施', 'f81808b6fe095581ca69571964c5b3e1_105640_1706509270.jpg', 'd_16_8363_0_5_20150808232847.png', 'You must go through the security check at the airport.', '在机场，你必须通过安全检查。', 'sa_1_8363_0_7_160106104628.aac', 'secur安全的 + ity名词后缀 → security安全；证券', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1275, 'sell', '/sel/', 'sell.mp3', 'v.出售，卖', '454412d14a8b3cf37371fbb16384de03_90470_1575010001.jpeg', 'd_24_17144_0_3_20150808232132.png', 'She sells eggs on the street.', '她在这条街上卖鸡蛋。', '75c72b2a5707a9c7_1266797984500460360_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1276, 'seminar', '/ˈsemɪnɑːr/', 'seminar.mp3', 'n.研讨会；研究班', 'e3caf096050fb1f370f45a55f5b9418e_160764_1534822520.jpeg', 'd_16_6741_0_2_20150808231031.png', 'A teacher and some students are holding a math seminar.', '一位老师和一些学生正在开数学研讨会。', '358e0d19140842a6aa34b27a51016380_19951_1621924029.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1277, 'separate', '/ˈseprət/', 'separate.mp3', 'adj.分开的；独立的；  v.使分开，分离', '687d938b1046c41269418317fe91f0ec_81755_1538664417.jpg', '20121225_19_18_50_691.png', 'The couple face to separate directions.', '这对夫妻面朝不同的方向。', 'c0bb7580f986dd0a383162c48ee1e05a_12898_1538664442.mp3', 'separ分离 + ate形容词后缀具有...的 → separate分离的；个别的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1278, 'separate from', '/ˈsepəreɪt frəm/', 'separate from.mp3', 'phr.分离，分隔', 'dc3c8e6f1f03263e5fac4cdb51b1aee0.jpeg', '', 'The wall separates the couple from each other.', '这堵墙把这对夫妻隔开了。', 'dfcb39a973bccb3ded90761d79365e74_15249_1619169725.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1279, 'set', '/set/', 'set.mp3', 'n.一套，一副，一批；  adj.固定的，规定的，固执的；  v.（小心地）放置', '3_0_20160520173241_19771_c-gigapixel-scale.jpg', 'd_24_18842_0_4_20150808235835.png', 'Many girls own a set of makeup.', '很多女孩子有成套的化妆品。', 'a88ef9b2efb02538757c46738bfb51e4_43232_1597653904.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1280, 'silence', '/ˈsaɪləns/', 'silence.mp3', 'n.寂静，无声，沉默；  v.使沉默', '8378fd02039dc5b96138c05d8a7e73e2_241977_1622108764.jpeg', '20130130_16_09_33_340.png', 'They sat face to face in silence.', '他们默然对坐。', '887a13fe30b61f72_1266883007754775406_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1281, 'simple', '/ˈsɪmpl/', 'simple.mp3', 'adj.简单的，易于理解的；无经验的', '033491567031b8d10da91feffebe240b_58576_1729734336.jpg', 'd_24_17245_0_4_20150808232514.png', 'You can solve this problem—it\'s simple!', '你可以解决这个问题的，它很简单！', '098886e657e8dfda_1266883012143897328_250207.mp3', 'sim一个，一起 + ple重叠 → 只有一个重叠在一起 → simple简单的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1282, 'since', '/sɪns/', 'since.mp3', 'conj.由于；自从；  prep.后来；  adv.从……以来', '27007422763b8e10a3a556323134e332.jpg', '', 'The ground is quite wet since it rained yesterday. ', '由于昨天下雨了，所以地面非常潮湿。', '98c0e5fcdd0404a3c27e6fbf6bdfee51.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1283, 'sleep', '/sliːp/', 'sleep.mp3', 'v.睡觉；  n.睡觉，睡眠', 'f7e72839c88c5a56761dd9988dbec992_110024_1590336672.jpg', 'd_24_16631_0_4_20150808231724.png', 'She is sleeping on the bed.', '她正在床上睡觉。', '88de5c919f852950_1266798141014891190_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1284, 'smuggle', '/ˈsmʌɡl/', 'smuggle.mp3', 'v.走私', 'fa1d6d3a3d1062fe6c2b83506ca4a516_141075_1732000374.jpg', '1ca754d4bfafb4038cdce67bc383ee01_122837_1551251877.png', 'They often smuggle things at night.', '他们常常在夜晚走私物品。', 'us_They_often_20241119151209612_3648f9494adf2a537758.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1285, 'somewhere', '/ˈsʌmwer/', 'somewhere.mp3', 'pron.某个地方；  adv.某处，某地', '84bddd41a6aa003ea61d57ce2d968218_91467_1558496521.jpg', 'd_24_19046_0_3_20150809000056.png', 'He is searching for somewhere to take a holiday.', '他正在寻找度假的地方。', 'rh9tcamd8jb9tc973ndx89k2lwyfdkgq.mp3', 'some某个 + where哪里 → somewhere在某处', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1286, 'sphere', '/sfɪr/', 'sphere.mp3', 'n.球；领域', 'i_1_4132_0_2_20150808122407-gigapixel-scale.jpg', 'd_1_4132_0_2_20150808122407.png', 'The world is not flat; it is a sphere.', '世界不是平的，而是一个球体。', 'sa_1_4132_0_2_20150808122407.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1287, 'splendid', '/ˈsplendɪd/', 'splendid.mp3', 'adj.壮观的，辉煌的，华丽的', 'i_1_4066_0_4_160201115040-gigapixel-scale.jpg', '', 'The palace looks really splendid at night.', '这座宫殿在夜晚看起来格外壮丽。', 'sa_1_4066_0_4_160204145318.aac', 'splend光辉 + id形容词后缀 → splendid辉煌的，华丽的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1288, 'sponsor', '/ˈspɑːnsər/', 'sponsor.mp3', 'v.赞助；做……的保人；  n.赞助人', '549424f1ae4a8d9658dd7f1adaa20882_54672_1654738993.jpg', 'd_107_5990_0_2_20150809014752.png', 'He sponsored the businessman to implement his good idea.', '他资助这个商人实施他的好点子。', 'us_He_sponsored_20241009155309754_fcdc845c32d39d8b294a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1289, 'study', '/ˈstʌdi/', 'study.mp3', 'v.研究', 'c14b53942e74e637754b65c203684ec0.jpeg', 'd_24_17945_0_4_20150808233642.png', 'She is studying the potential risks of genetic engineering.', '她正在研究基因工程的潜在风险。', 'us_She_is_20250108152018044_dea9751de5d7d60879ac.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1290, 'suggest', '/səˈdʒest/', 'suggest.mp3', 'v.建议，提议；使人想起', 'i_1_8364_0_4_20150808130622-gigapixel-scale.jpg', 'd_24_8364_0_3_20150808225614.png', 'You look terrible! I suggest you go to see a doctor.', '你看起来糟透了！我建议你去看医生。', '97chph6hqg6pm2ellpptxuxs9vult9ea.mp3', 'sug在下面 + gest带来，产生 → 从下面带上来 → suggest建议', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1291, 'target', '/ˈtɑrɡɪt/', 'target.mp3', 'n.靶子；目标；  v.瞄准', '126703cd555b3ff430db540fa7fdca0f_72655_1565342191.jpg', '20130106_14_38_36_133.png', 'Yes! I hit the target', '太好了！我击中了靶子，正中靶心！', 'sa_1_16061_0_2_20150808132155.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1292, 'tell', '/tel/', 'tell.mp3', 'v.识别', '13d6e35bebe742b832fb839283e79193.jpg', 'd_24_16449_0_4_20150808231252.png', 'She can tell that the bread is not edible anymore.', '她能识别出这个面包已经不能食用了。', '88fa9290ac478953dbe0824fae015da0_50638_1599536735.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1293, 'truck', '/trʌk/', 'truck.mp3', 'n.卡车；载重汽车', 'eacbad2b0f1832282fa0e41337dde780_185928_1605151939.jpg', '20121225_20_36_32_510.png', 'Trucks are usually large and can carry a great amount of goods.', '卡车通常很大，可以运载大量的货物。', 'xmg55r93hbd9cvvgf2sxjy8tmcc68vc6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1294, 'uniform', '/ˈjuːnɪfɔːrm/', 'uniform.mp3', 'n.制服，军服；  adj.相同的，统一的', 'i_1_7588_0_2_20150808130014-gigapixel-scale.jpg', 'd_16_7588_0_2_20150808231846.png', 'The nurses wear white uniforms when they work.', '护士们工作的时候穿着白色的制服。', '467d80871ad6bc5b_1266883374522805032_250207.mp3', 'uni一个，单一 + form形状 → uniform制服', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1295, 'unique', '/juˈniːk/', 'unique.mp3', 'adj.独一无二的，独特的，特别的', '1179adfccabce9bcf23e84c5523cf4c1_100042_1588924235.jpeg', '', 'This square apple looks unique in a pile of round ones.', '这个方苹果在一堆圆苹果中显得独一无二。', '38b6c978058aec1a_1266883491849001474_250207.mp3', 'uni一个 + que形容词后缀 → unique独立无二的，独特的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1296, 'utilize', '/ˈjuːtəlaɪz/', 'utilize.mp3', 'v.利用；使用', '3_0_20160718113808_44054_c-gigapixel-scale.jpg', 'd_107_9548_0_2_20150809024711.png', 'It\'s better to utilize waste than to throw it away.', '废物再利用总比把它扔掉要好。', '3_0_20160718113808_85884_c.aac', 'ut用 + ilize动词后缀，……化 → utilize利用', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1297, 'violent', '/ˈvaɪələnt/', 'violent.mp3', 'adj.暴力的，粗暴的；强烈的，猛烈的', 'd90fe1deb038ee02e565de0c3b17bd50_34745_1582879798.jpeg', 'd_16_4390_0_2_20150808224213.png', 'Some violent pictures in this cartoon will have a negative effect on the boy.', '这部动画片中的一些暴力画面会对这个男孩产生负面影响。', 'yfu65jc52a7vkr2v3qucu8pll3fz2nwk.mp3', 'viol暴力 + ent形容词后缀 → violent暴力的，粗暴的 ', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1298, 'virtual', '/ˈvɜːrtʃuəl/', 'virtual.mp3', 'adj.（计算机）虚拟的；实质上的；十分接近的', '09f5e4ceb940fd1bebb93916fb5cfce3_74794_1656998143.jpg', 'd_107_5657_0_2_20150809013351.png', 'They are driving a virtual car.', '他们正在驾驶一辆虚拟汽车。', 'us_They_are_20220705131027654_8cc8cd2da77c75ef4e53.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1299, 'wait for', '/weɪt fɔːr/', 'wait for.mp3', 'phr.等候，等待', 'i_16_18699_0_4_151222174119.jpg', '', 'People are waiting for a bus at the bus stop.', '人们正在车站等车。', '6dba07872d0b9cc4_1266763556006046492_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1300, 'warm', '/wɔːrm/', 'warm.mp3', 'adj.温暖的；  v.使温暖', 'd1f65f93e0347f5c2080d43c04102b3e_202158_1656491208.jpg', 'd_24_17192_0_4_20150808232326.png', 'The weather cooled off', '天气变凉了，所以我们生火取暖。', 'd04fd8f018bbadea_1266763449528790006_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1301, 'warn', '/wɔːrn/', 'warn.mp3', 'v.警告，告诫', 'i_13_19581_0_4_160318142712-gigapixel-scale.jpg', 'd_24_19581_0_4_20150809002147.png', 'The sign warned the bone about the danger of being eaten.', '这个标牌警告骨头有被吃掉的危险。', '64b8ec394786359f_1266883322188618368_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1302, 'willing', '/ˈwɪlɪŋ/', 'willing.mp3', 'adj.愿意的，心甘情愿的', '3_0_20170930071654_70555_c.jpg', '1dec742e794df3e0f4e7601441681fd7_19245_1551253448.png', 'The man is willing to be at his boss\'s service.', '这个人愿意听从老板的吩咐。', '3_0_20170930071654_74333_c.aac', 'will愿意 + ing名词后缀 → willing愿意的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1303, 'wing', '/wɪŋ/', 'wing.mp3', 'n.翅膀，翼；  v.飞行', '10a6996c6396358e342845cccdda3be2_221481_1717652610.jpg', 'd_24_5770_0_3_20150808224336.png', 'Mommy', '妈妈，我想要那个带蝴蝶翅膀的洋娃娃。', '62dcdef9b464357c_1266797979101256412_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1304, 'wit', '/wɪt/', 'wit.mp3', 'n.智力，才智；机智', 'i_1_10261_0_5_20150808131632-gigapixel-scale.jpg', '20140808_15_30_37_235_v3.png', 'The wit of that little boy fascinates us.', '那个小男孩的机智让我们感到惊叹。', 'us_The_wit_20241009155322134_041cc55eded1a688f64a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1305, 'yield to', '/jiːld tu/', 'yield to.mp3', 'phr.屈服于', 'dc938219bebf62086f81be78d665c743.jpeg', '', 'He yielded to the temptation after half an hour.', '半小时后，他还是屈服于诱惑之下。', 'bcd21ebe721a011329af7c42d5d752a1_45550_1599622554.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1306, 'able', '/ˈeɪbl/', 'able.mp3', 'adj.能够……的，可以...的；有能力的', '3_0_20170930071307_74741_c-gigapixel-scale.jpg', 'd_24_17422_0_3_20150808232758.png', 'Now he is able to walk without the help of crutches.', '现在他能够脱离拐杖走路了。', '7082a1c1d997c0dd91a78b8b2e7dacc6_17914_1640242962.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1307, 'according to', '/əˈkɔːrdɪŋ tuː/', 'according to.mp3', 'phr.根据，按照', 'i_1_11461_0_4_151112115956-gigapixel-scale.jpg', 'd_105_11461_0_2_20150809061900.png', 'According to the law', '根据法律，你的罪名成立。', '5aa9e363013eb711_1266883111756126858_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1308, 'actual', '/ˈæktʃuəl/', 'actual.mp3', 'adj.实际的，真实的', 'i_1_8352_0_25_160406174014-gigapixel-scale.jpg', 'd_16_8352_0_4_20150808232844.png', 'I refused the red packet', '我拒绝了那个红包，但事实上我想要它。', '456a98bc45ce31f5_1266883633628425136_250207.mp3', 'act行动 + ual形容词后缀 → actual现实的，现行的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1309, 'anger', '/ˈæŋɡər/', 'anger.mp3', 'n.怒火，怒气；  v.激怒，使生气', '90a73905d162075f4b798469d7931f42_118221_1732159415.jpg', '20130311_16_48_45_358.png', 'The man was stuck in traffic', '这名男子被堵在路上，怒火中烧。', 'us_The_man_20241121112328332_7ff171689dedd7ad9065.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1310, 'annoying', '/əˈnɔɪɪŋ/', 'annoying.mp3', 'adj.使恼怒的；使生气的；讨厌的', 'i_4_9342_0_3_20150808180318.jpg', '20140721_23_25_32_650_v3.png', 'The constant crying of our neighbor\'s baby is starting to get annoying.', '邻居家宝宝持续不断的哭声开始变得特别烦人了。', '636fdb134cbf80f8_1266883484935019080_250207.mp3', 'annoy恼人的+ing形容词后缀 → 恼人的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1311, 'answer for', '/ˈænsər fɔːr/', 'answer for.mp3', 'phr.对……负责，(为所做的不好或错误的事) 付出代价', '3_0_20170709071611_49286_c.jpg', '', 'This man must answer for his careless driving.', '这个男人必须为自己的粗心驾驶负责。', '3_0_20170709071611_6864_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1312, 'applicable to', '/ˈæplɪkəbl tuː/', 'applicable to.mp3', 'phr.适用于，能应用于', '5820ced2428be42845f79fbd9b94ee69.jpeg', '', 'The law is applicable to everyone.', '这部法律适用于所有人。', '2d7f809ffffbe3e80eb7a99a8d6fce9e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1313, 'argue', '/ˈɑːrɡjuː/', 'argue.mp3', 'v.争论', '088e0493ad8a61054967ca6bc0f745e0.jpg', 'd_24_5558_0_4_20150808224139.png', 'The workers are arguing about a problem.', '员工们在争论一个问题。', '52cbd235028bc8bd2e625091b73bf3a2_13995_1620808433.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1314, 'arm', '/ɑːrm/', 'arm.mp3', 'n.手臂；上肢；臂状物；  v.供给，提供', '978a74db838b2c3d1b2bc8aa32b356df_90986_1535082098.jpeg', '20141011_13_31_49_513_v3.png', 'She is showing how strong her arm is.', '她正在展示她那强壮的手臂。', 'gu44cqw3xcv39khladpjcr4cm59qyxkn.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1315, 'arrange', '/əˈreɪndʒ/', 'arrange.mp3', 'v.整理；改编（乐曲）；筹备，安排；达成协议；安排', 'ce3c6ada47c71fc05eb823f9c005bf18_154576_1682605734.jpg', '', 'It\'s time to arrange the pile of clothes in the wardrobe.', '是时候把衣柜里的这堆衣服整理一下了。', 'bcec96c8a03b05d84c1b7dc8100e4a73_47744_1603252015.mp3', 'ar使 + range排列 → 使排列好 → arrange安排', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1316, 'at intervals', '/ət ˈɪntevls/', 'at intervals.mp3', 'phr.不时地', 'e5a272674a70ed412c0236dc3e72e874.jpg', '', 'It is forecast to snow at intervals this week. ', '天气预报说这星期会不时地下雪。', '2dc423a59e4759f2fac39b91125b2a97_44398_1599622262.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1317, 'autumn', '/ˈɔːtəm/ ', 'autumn.mp3', 'n.秋天', 'i_24_16494_0_7_151221175204-gigapixel-scale.jpg', 'd_24_16494_0_4_20150808231429.png', 'Leaves turn yellow in the autumn.', '秋天，叶子都变黄了。', 'us_Leaves_turn_20250627172128070_cd06022aa49216edf18d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1318, 'benefit', '/ˈbenɪfɪt/', 'benefit.mp3', 'n.利益，好处；  v.得益于', '3_0_20170721071239_67764_c-gigapixel-scale.jpg', 'd_16_8113_0_2_20150808232626.png', 'Jogging has a lot of benefits to people\'s health.', '慢跑对人体健康有诸多好处。', 'jzbrjnrxg66vjtetsewdaw5zy69cbz2b.mp3', 'bene善，好 + fit做 → 做事后的好处 → benefit利益，好处', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1319, 'bored', '/bɔːrd/', 'bored.mp3', 'adj.感到厌倦的，感到无聊的', '1da6538be4e2a5c1ab5fff22b7c7a50a_99503_1538714786.jpg', 'd_105_17120_0_2_20150809062233.png', 'They are bored of having a meeting.', '他们对开会感到厌烦。', '3erdqj3ju3a4824khu2yebk7ttvhhmey.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1320, 'breathe', '/briːð/', 'breathe.mp3', 'v.呼吸', '3412b3f8cf09b212db21f1a50a2eb30a_100527_1584157426.jpeg', 'd_93_11941_0_4_20150809001940.png', 'She breathes deeply to relax herself when doing yoga.', '她做瑜伽时用深呼吸的方式来放松自己。', '409a48b23a6c5a8f_1266763557269428786_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1321, 'by mistake', '/baɪ mɪˈsteɪk/', 'by mistake.mp3', 'phr.错误地', 'fb5205ba3accfd2930cb32061190182d_192514_1590215825.jpeg', '', 'He took someone else\'s umbrella by mistake.', '他错拿了别人的伞。', '1ed44bb23e9d9c5553e8334f3af9ba0f_47296_1590215823.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1322, 'cargo', '/ˈkɑːrɡoʊ/ ', 'cargo.mp3', 'n.货物', 'i_1_5260_0_4_20150808123718-gigapixel-scale.jpg', 'd_108_5260_0_2_20150809040351.png', 'This machine loads the cargo onto the ship.', '这台机器把货物装载到船上。', '5cf519fb9c9d214e_1266883636676549360_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1323, 'cartoon', '/kɑːrˈtuːn/', 'cartoon.mp3', 'n.卡通（片），动画片', 'c43aff3b79521d8a3723efe6c2af16c5_186785_1532153925.jpeg', '20140929_02_23_18_547_v3.png', 'Almost every kid loves to watch cartoons!', '几乎所有小孩子都喜欢看卡通片！', 'd4f4hufbmfzcq4m54xtd62mnalxrjbtc.mp3', 'cart一张纸 + oon表名词 → 画在纸上的 → cartoon动画片；漫画', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1324, 'cash', '/kæʃ/', 'cash.mp3', 'n.现金；  v.付（或收）现款', 'ab952b3390edb1094a56904871b82b2d_185332_1573789801.jpeg', 'd_16_8378_0_2_20150808232921.png', 'The woman behind the counter said she takes cash only.', '柜台后面的女人说她只接受现金。', 'x2srnvezgg2uf5uclyltrufem2wd6fja.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1325, 'cause', '/kɔːz/', 'cause.mp3', 'v.引起，导致，造成，使发生；  n.原因，理由', 'i_1_15259_0_4_151019105036-gigapixel-scale.jpg', 'd_24_15259_0_4_20150808230640.png', 'Smoking can cause lung cancer.', '吸烟可致肺癌。', 'ba9c349812e7b335_1266883526635969116_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1326, 'ceiling', '/ˈsiːlɪŋ/', 'ceiling.mp3', 'n. 天花板', '3_0_20170701114014_54931_c-gigapixel-scale.jpg', '20130105_10_18_51_398.png', 'Look at my bright pink ceiling! It\'s so girly!', '看我亮粉色的天花板！多么少女！', 'c9c0ecd5cfa12f20_1266797982842596126_250123.mp3', 'ceil装天花板 + ing名词后缀 → ceiling 天花板', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1327, 'Christmas', '/ˈkrɪsməs/', 'Christmas.mp3', 'n.圣诞节', 'ff0612695a5409d6a772d27563c412b2_86259_1532160875.jpeg', 'd_16_16625_0_4_20150809003307.png', 'Christmas is a traditional holiday in Western countries.', '圣诞节是西方国家的传统节日。', 'us_Christmas_is_20240704132627966_3de139601cc41d0a108d.mp3', 'Christ基督 + mas(s)圣餐 → 为纪念耶稣诞生吃圣餐 → Christmas圣诞节', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1328, 'cinema', '/ˈsɪnəmə/', 'cinema.mp3', 'n.电影院；电影，影片', '85dfde868fa14a032645f5a228b02f2f_61685_1545363374.jpeg', 'd_99_12106_0_4_20150809022211.png', 'The cinema has a massive screen.', '这家影院有一个巨幕。', 'cek2uj6wu7ecgge5w9ale27z5x3x4dc6.mp3', 'cine移动、电影 + ma表结果和产物 → cinema影院', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1329, 'citizen', '/ˈsɪtɪzn/', 'citizen.mp3', 'n.公民；市民；居民', 'i_1_5165_0_4_150925175518-gigapixel-scale.jpg', 'd_105_5165_0_2_20150809054513.png', 'I have become a Chinese citizen who has the right to vote after turning eighteen.', '十八岁以后，我就成为一个享有选举权的中国公民了。', 'us_I_have_20230726170315659_479634ca301bb5be2316.mp3', 'citiz=city城市 + en表名词 → citizen公民', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1330, 'compatible with', '/kəmˈpætəbl wɪð/', 'compatible with.mp3', 'phr.（系统、想法、信仰）兼容的，能和谐相处的', '382b72b0bb6745669ae689a3e47d9696.jpeg', '', 'This set of headphones is compatible with any mobile device.', '这副耳机适用于所有移动设备。', '2d507f66d96afbff3db946dccfd0ce95.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1331, 'compose', '/kəmˈpoʊz/', 'compose.mp3', 'v.创作', 'dd9a9f91a1458efec78f4023f00b6d1c_117413_1702257596.jpg', 'd_1_4018_0_2_20150808122236.png', 'The man composes new songs on his keyboard.', '这位男士在他的键盘上创作新歌。', 'ttvartwebrur26l4y76g26lfdeaplpmz.mp3', 'com一起 + pose放 → compose组成，构成；创作', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1332, 'confess', '/kənˈfes/', 'confess.mp3', 'v.（向神父或上帝）忏悔；承认，坦白', '3_0_20160521111508_83634_c-gigapixel-scale.jpg', '809c06ecc4df3583a2212381cdbf117c_43543_1539341493.png', 'Father', '神父，我在此忏悔我所有的罪行。', 'vffx8fhsmukeb9kz87376nfwkmh5hwsn.mp3', 'con全部 + fess说 → 全部说出 → confess承认，坦白', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1333, 'consider', '/kənˈsɪdər/', 'consider.mp3', 'v.考虑，细想；认为，把...看作', 'i_1_9893_0_3_20150808131500-gigapixel-scale.jpg', 'd_24_9893_0_3_20150808230322.png', 'I will consider your offer', '我会考虑你给的职位，但我觉得我能找到一个更好的。', 'd464e34de9d74c74acc3bcb5c64885ef_30197_1621915006.mp3', 'con有关 + sider星座 → 对星座的观察 → consider考虑', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1334, 'contrary', '/ˈkɑːntreri/', 'contrary.mp3', 'adj.对立的，相反的；叛逆的', '6f42335aa7f3e384d524ef60ba36aec1_34203_1732158045.jpg', 'd_16_10110_0_2_20150808235120.png', 'The lady and the man hold contrary views.', '这位女士和这位男士持有相反的意见。', 'a83598230f6f4f4a_1266883481578461936_250207.mp3', 'contr反对，相反 + ary形容词后缀 → contrary相反的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1335, 'crucial', '/ˈkruːʃl/', 'crucial.mp3', 'adj.关键的，至关重要的；决定性的', '9634046c61ed87ae1b899a3212dda34a_64965_1669630908.jpg', 'd_107_4491_0_2_20150809005749.png', 'This crucial round will decide who will win the game.', '这个关键回合将决定谁会赢得比赛。', 'bt72gkche9cqt9b9ztmwksyccy577utd.mp3', 'cruc十字形，交叉 + ial具有...性质的 → 十字路口 → crucial关键的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1336, 'demand', '/dɪˈmænd/', 'demand.mp3', 'v.强烈要求，坚决要求；  n.需求，需要', '980f031df1cf953833edb7671e51b56b_140925_1561953007.jpg', 'd_24_8112_0_3_20150808225503.png', 'He has always demanded some unreasonable things from his children.', '他总是向子女们提出一些无理的要求。', 'rh58yst3vn4dagy4lpg6d9namndrccq4.mp3', 'de加强 + mand命令 → demand要求', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1337, 'deposit', '/dɪˈpɑːzɪt/', 'deposit.mp3', 'v.存钱；  n.存款', 'a01dbcb0789fa4ce3b69a04cb9d1827a_66211_1565343158.jpg', 'd_12_4031_0_2_20150808155044.png', 'I deposit money in my piggy bank when I get money.', '当我有钱时我会往我的存钱罐里存钱。', 'ff4da2c30d4235c95474ea4174e1c515_19638_1619330915.mp3', 'de下 + posit放 → deposit储存', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1338, 'depth', '/depθ/', 'depth.mp3', 'n.深度；深处；深刻', '1425952623513-gigapixel-scale.jpg', 'd_24_6121_0_4_20150808224435.png', 'These fish dived to a depth of 150 meters.', '这些鱼潜至水下150米深处。', '70c9c0d68ef6f765_1266797983621622586_250123.mp3', 'dep深的 + th名词后缀 → depth深度', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1339, 'devil', '/ˈdevl/', 'devil.mp3', 'n.恶魔；淘气鬼', '4434d3bca55ef5319d55c486b5e48f74_131151_1561953090.jpg', '20140718_20_59_51_801_v3.png', 'These little devils with horns and tails are making threatening gestures.', '这些长着角和尾巴的小恶魔正在张牙舞爪。', 'us_These_little_20240206131229611_e08675a6bcc2bdcc139b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1340, 'discharge', '/disˈtʃɑrdʒ/', 'discharge.mp3', 'v.放电；  n.释放', 'a6548c13d699ce0f469fa84971be9a08_181157_1583136244.jpeg', 'd_2_4088_0_8_20150808142519.png', 'The electric eel can discharge and use its current against smaller fish.', '电鳗可以放电并利用电流对付更小的鱼。', '6c0738c438b08f228e8c8aa9433455bd_47388_1583136241.mp3', 'dis取消 + charge充电 → discharge放电', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1341, 'discovery', '/dɪˈskʌvəri/', 'discovery.mp3', 'n.发现', '69a07cb81506d6d155797a3c581fc810.jpg', 'd_24_6144_0_3_20150808224446.png', 'The discovery of liquid water on Mars is exciting to us.', '在火星上发现液态水是一件激动人心的事。', 'e0151f533875d0e3e11f3b78937b0b74_28325_1621931761.mp3', 'discover发现 + y名词后缀 → discovery发现', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1342, 'distinction between', '/dɪˈstɪŋkʃn bɪˈtwiːn/', 'distinction between.mp3', 'phr.……之间的差别', '6937af9795f23f000387a49d9c1c072e.jpg', '', 'The distinction between these two eggs is size.', '这两个蛋之间的差别在于大小。', '2784356d3b7314327ebe4e77136b9101_46496_1593585064.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1343, 'downtown', '/ˈdaʊntaʊn/', 'downtown.mp3', 'adj.市中心的，商业区的，闹市区的；  adv.在市中心', '3_0_20170608071159_14429_c-gigapixel-scale.jpg', 'd_24_9016_0_3_20150808225951.png', 'At night', '在晚上，市中心的街道依旧繁华。', '3_0_20170608071159_39567_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1344, 'edition', '/ɪˈdɪʃn/', 'edition.mp3', 'n.版，版本，版次', 'b13d6202e3b596af99a374443f702ec3_179508_1585122240.jpeg', 'd_105_6170_0_2_20150809055526.png', 'The dictionary is now in its third edition', '这本字典现在是第三版，于2017年出版。', '2a318c5baaad12dcb3e5136d025c0c80_48442_1585122236.mp3', 'edit编辑 + ion名词后缀 → 编成的样本 → edition版，版本', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1345, 'embarrass', '/ɪmˈbærəs/', 'embarrass.mp3', 'v.使尴尬', '5f6e6cc6b8d513125630db500c4d8108_244789_1709194610.jpg', 'adfd7c86555dbfe42dbd3db207ab228d_46570_1551843768.png', 'He embarrassed himself when he didn\'t have enough funds to cover the payment.', '买单时显示余额不足，他非常尴尬。', 'us_He_embarrassed_20240409113409840_b8f9e195a17965952160.mp3', 'em进入…之中，包围 + barrass套子 → 进入套子 → embarrass使难堪', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1346, 'engineer', '/ˌendʒɪˈnɪr/', 'engineer.mp3', 'n.工程师；技师；火车司机；  v.设计；建造', '3_0_20170930071545_24640_c-gigapixel-scale.jpg', '20130130_16_18_39_197.png', 'The two engineers are discussing their new building plans.', '这两个工程师正在讨论新的建筑计划。', 'ca5f0a1b0c437a4a_1266798140159077286_250123.mp3', 'engine发动机 + er人 → engineer工程师', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1347, 'evidence', '/ˈevɪdəns/ ', 'evidence.mp3', 'n.证物；证据，证明；  v.证明', '5b95a8cc765e6bffb2c0977f10be1624_78420_1565344265.jpg', 'd_16_8082_0_4_20150808232530.png', 'Keep every piece of evidence to help us solve the crime.', '保留所有的证据来帮助我们破案。', 'sa_1_8082_0_2_20150808130401.aac', 'e出 + vid看 + ence表名词 → 明显的证据 → evidence证据，证人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1348, 'exception', '/ɪkˈsepʃn/', 'exception.mp3', 'n.例外', '35d228100965181b47f98516a03ced84_199777_1584422350.jpeg', 'd_1_2768_0_2_20150808121922.png', 'Most of the buildings are modern', '这些大多是现代建筑，不过这座四合院是唯一的例外。', 'acb57d89d6fbe0d8377fde040c5da877_45598_1584422346.mp3', 'ex出 + cept拿，抓，握住 + ion名词后缀 → exception除外', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1349, 'feather', '/ˈfeðər/', 'feather.mp3', 'n.羽毛', 'b681a9d21786f6637a39c042bb2511c6_147500_1734316706.jpg', 'd_24_8485_0_4_20150808225737.png', 'This beautiful hat is made of feathers.', '这顶漂亮的帽子是羽毛做的。', 'sk9h3nty5t9a9ekyjcq33cumwuy7ylgv.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1350, 'graduate', '/ˈgrædʒuˌeɪt/', 'graduate.mp3', 'v.毕业；渐渐变为（读作/ˈgrædʒuˌeɪt/）；取得学位；授予学位；  n.毕业生；大学毕业生；  adj.毕业的；研究生的（读作/ˈgrædʒuət/）', '16f467d2aafc27b9edd0b3e5fd2d4b54_110832_1565685057.jpg', 'd_107_5192_0_2_20150809011816.png', 'She graduated from university after four years\' unforgettable life.', '经过四年难忘的大学生活，她毕业了。', '78d596640c6d6f3fd56929a18be25b34_21832_1538624410.mp3', 'grad步 + uate使 → 完成所有步骤 → graduate毕业', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1351, 'greet', '/ɡriːt/', 'greet.mp3', 'v.问候，招呼', 'i_1_2696_0_4_20150808121914-gigapixel-scale.jpg', '20121225_18_22_46_596.png', 'This gentleman takes his hat off to greet people.', '这位绅士摘下他的帽子，向人们问好。', '3d1c9e9313e6519d_1266883321100393056_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1352, 'hungry', '/ˈhʌŋɡri/', 'hungry.mp3', 'adj.饥饿的', '3_0_20170712071350_53361_c-gigapixel-scale.jpg', '20130308_21_34_41_594.png', 'I\'m not really hungry', '我不是很饿，给我一小块比萨就好。', 'trftpv7cynz6thevcl5shn5ttucb92sz.mp3', 'hunger饥饿 + y形容词后缀 → hungry饥饿的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1353, 'hunt', '/hʌnt/', 'hunt.mp3', 'v.打猎；搜索；  n.搜寻', 'f597d5d943aafd0f16bb46ebcd979eba_112821_1535525223.jpeg', 'd_24_8011_0_3_20150808225342.png', 'The man is hunting a reindeer.', '这名男子正在狩猎驯鹿。', 'lhdbshjcyhculfagy3kl6sbdcgg9pm6s.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1354, 'hurry up', '/ˈhɜːri ʌp/', 'hurry up.mp3', 'phr.赶快，快点', '9565d7474f6df5cba9ccd7ed45689d9f_96513_1580884469.jpg', '', 'He has to hurry up', '他得快点，否则就赶不上公共汽车了。', '749faec6054b93c1_1266763246029744922_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1355, 'identify with', '/aɪˈdentəˌfaɪ wɪð/', 'identify with.mp3', 'phr.认同', '40339ed7fb928f91a83b54ed9cb78a1a.jpg', '', 'She felt she could really identify with the story\'s character.', '她觉得她能与故事里的角色产生共鸣。', '8cfc71eed189d67a44388f7d607d7cf0_41072_1599550183.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1356, 'impression', '/ɪmˈpreʃn/', 'impression.mp3', 'n.印象，感觉，感想；压痕', '176ea515c6df2a3dffa3c0c83c81374e_81620_1745199906.jpg', 'd_24_7491_0_3_20150808225121.png', 'She left a good impression on the interviewer.', '她给这位面试官留下了好印象。', '2047b725ed51c563_1266883634003073724_250207.mp3', 'im在...内 + press压 + ion名词后缀 -> impression印象', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1357, 'initiative', '/ɪˈnɪʃətɪv/', 'initiative.mp3', 'n.主动权，主动性；首创精神；倡议', '5cf76985c960549c63cfa01e5c6a494e_186896_1571125831.jpeg', 'd_1_5144_0_3_20150808123550.png', 'Her boyfriend took the initiative and cleaned up after they all had dinner.', '她男朋友在他们吃完晚饭后主动打扫了卫生。', 'us_Her_boyfriend_20241009164013907_6c48c0029a097c23dff4.mp3', 'in进入 + it行走 + iat开始 + ive名词后缀 → initiative主动', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1358, 'job', '/dʒɑːb/', 'job.mp3', 'n.责任', 'e68a40ebb07e36046426d65aad1c60ed.jpeg', '20121225_20_03_04_722.png', 'It is my job to put the books back on the shelves.', '我的责任是把书放回书架上。', '8ce04877af0884ab6a86bd80994d6fbe.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1359, 'knock', '/nɑːk/', 'knock.mp3', 'v.敲击；  n.敲，敲门', '5b29f8baa965e148f6571a372a3c5650_76755_1574911955.jpeg', 'd_24_16012_0_3_20150808231037.png', 'Before entering', '进去之前，你应该先敲门。', '34de6f0ed2faddb9_1266797981909277184_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1360, 'knowledge', '/ˈnɑːlɪdʒ/', 'knowledge.mp3', 'n.知识，学识', '3efc6942373665b0ca3b259c0dc7ce2e_166686_1709522744.jpg', 'd_94_13220_0_4_20150809010100.png', 'Children are able to learn more quickly and retain more knowledge than adults.', '相比大人，小孩子学得更快，记的知识更多。', 'cbda55bea24d7644_1266883372570073818_250207.mp3', 'know知道 + ledge框架 → knowledge知识', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1361, 'laugh at', '/læf æt/', 'laugh at.mp3', 'phr.嘲笑', 'a4a2ef3207da7408d11a1bd5f12b417e_83866_1538756037.jpg', '', 'My friend just couldn\'t stop laughing at me.', '我的朋友止不住嘲笑我。', 'hpz76archwt4wnjruyw3x4dtweaulfky.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1362, 'leader', '/ˈliːdər/', 'leader.mp3', 'n.领导', 'ceaeb2f87b4dccbac7d91ae38b960e60_135443_1572415599.jpeg', 'd_94_13247_0_4_20150809010111.png', 'The workers are happy to follow and work for their team leader.', '员工们乐意跟随他们的小组领导工作。', 'f82zafluvxumncl3nwy4bwunq8dp4xr2.mp3', 'lead领导 + er人 → leader领袖，领导', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1363, 'long', '/lɔːŋ/', 'long.mp3', 'v.渴望，极想', '8c03b8edef160b3efbcc93d0e1edbeaa_87408_1723018695.jpg', 'd_24_17667_0_3_20150808233238.png', 'The students long to do well in the college entrance examination.', '学生们渴望在高考中取得好成绩。', 'us_The_students_20240807161827464_ec94a35a6195d4cddaf9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1364, 'loyal', '/ˈlɔɪəl/', 'loyal.mp3', 'adj.忠心的，忠诚的；（顾客）忠实的；  n.忠臣', '1d45edf670c23ad34cc4c3f25bad2b1d_76297_1565693718.jpg', '', 'Dogs are always loyal to their owners.', '狗总是对它们的主人很忠心。', 'sa_1_4060_0_2_20150808122302.aac', 'loy法律 + al表形容词 → loyal忠心的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1365, 'maybe', '/ˈmeɪbi/', 'maybe.mp3', 'adv.可能，大概，也许', '3_0_20170709071411_58194_c-gigapixel-scale.jpg', 'd_24_19595_0_3_20150809002258.png', 'Maybe your cat is in that box.', '你的猫可能在那个盒子里。', '3_0_20170709071411_25019_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1366, 'mean', '/miːn/', 'mean.mp3', 'adj.吝啬的', '3_0_20170713071210_37121_c-gigapixel-scale.jpg', 'd_93_13387_0_4_20150809002126.png', 'He\'s too mean to share his snacks with me.', '他太吝啬了，不肯把零食分给我吃。', '3_0_20170713071210_61622_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1367, 'monument', '/ˈmɑːnjumənt/ ', 'monument.mp3', 'n.纪念碑；历史遗迹，遗址', 'fbea45d84463b0694bf4d6ac59776c04_188425_1538643828.jpg', 'd_24_6771_0_4_20150808224751.png', 'The Washington Monument stands in the center of Washington', '华盛顿纪念碑矗立在华盛顿特区中心。', 'us_The_Washington_20250917164512780_a69fc66da929f4468c09.mp3', 'monu警告，提醒 + ment名词后缀 → 提醒的东西 → 纪念碑', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1368, 'mysterious', '/mɪˈstɪriəs/ ', 'mysterious.mp3', 'adj.神秘的', 'ad8471835996fa0a91b1e9ab62f86f54_161505_1605170138.jpg', 'd_1_6680_0_3_20150808125341.png', 'Oh my God! A mysterious man is running in my yard!', '天哪！一个神秘人正在我的院子里跑！', '860fc31e6307ea963dea183693d74042_37648_1605170144.mp3', 'mystery神秘 + ious表形容词 -> mysterious神秘的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1369, 'natural', '/ˈnætʃrəl/', 'natural.mp3', 'adj.自然的', 'd29653bfabe24c7243ad4af788e37255_194266_1578560625.jpeg', 'd_24_17180_0_4_20150808232253.png', 'There are more green trees in the natural environment than in the urban environment.', '自然环境中的绿树比城市环境中的多。', 'aa1462874065a51285c041de8e6692ea_43822_1578560619.mp3', 'natur自然 + al形容词后缀…...的 → natural自然（界）的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1370, 'naturally', '/ˈnætʃrəli/', 'naturally.mp3', 'adv.自然地，天然地', '3_66_20170714114457_2074_c-gigapixel-scale.jpg', 'd_103_5120_0_3_20150809013006.png', 'Some people have naturally frizzy hair.', '有的人天生卷发。', '3_66_20170714114457_74216_c.aac', 'natur=nature自然 + ally副词后缀 → 自然地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1371, 'neglect', '/nɪˈɡlekt/', 'neglect.mp3', 'v.疏于照料，忽视；疏漏；不予重视，疏忽；  n.疏忽，忽视', '5ccd91c6f0d60f09c76c8d3777b3b7b1_32999_1565692312.jpg', '', 'The parents neglected their child and kept quarrelling.', '那对父母忽视了他们的孩子，一直在吵架。', 'e656cc7f53bb8cf39748f78dd77438d2_24737_1621914848.mp3', 'neg没有 + lect选 → 没有选出来 → neglect疏忽', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1372, 'none', '/nʌn/', 'none.mp3', 'pron.没有（一人或一物）；  adv.毫不', 'f13a2148bc9cf8c32637742f81cffd00_190721_1574839085.jpeg', 'd_24_16422_0_4_20150808231152.png', 'I wish I could offer you some cake but there\'s none left.', '我很想请你吃蛋糕，但是没有了。', '40e83831c59d7298735fc68f918c64a6_38686_1574839082.mp3', 'n=no没有 + one一个人 → none没有一个人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1373, 'nutrient', '/ˈnuːtriənt/ ', 'nutrient.mp3', 'n.营养物；  adj.营养的', '941c27d2f7f857c98894ea07430b4ee7_100044_1585131507.jpeg', '20140817_05_53_27_58_v3.png', 'Apples contain many healthy nutrients for the body.', '苹果含有许多有益身体健康的营养成分。', 'eae1d61cb3be535f2f1880b95831a450_48564_1585131504.mp3', 'nutri营养+ent表名词 → 营养品', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1374, 'occupy', '/ˈɑkjupaɪ/', 'occupy.mp3', 'v.占据，占领；任职，执政', 'bf6c7af06fe8a5703c26f02ec6eb7190_72015_1617776128.jpg', 'd_24_9143_0_4_20150808230038.png', 'The mouse almost occupies the whole chair. ', '这只老鼠几乎把整把椅子都给占了。', 'us_The_mouse_20240428151926182_70d2bc753fe3fb65c282.mp3', 'oc再次 + cupy抓 → 抓住地盘 → occupy占领', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1375, 'on board', '/ɑːn bɔːrd/', 'on board.mp3', 'phr.在船上', 'ce001d57586bba82b3a4b2c83e43b1dd_100306_1590218560.jpeg', '', 'There are a lot of goods on board the ship.', '船上有很多货物。', 'lt928zezarcrmfrlrhwgsuqke7btjwlh.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1376, 'pack', '/pæk/', 'pack.mp3', 'v.收拾，打包；把......包起来；塞满，挤满；  n.行李；背包；小盒，小包；群', '1_0_20170114160857_67913_c-gigapixel-scale.jpg', 'd_24_5593_0_3_20150808224217.png', 'The boy is packing his clothes for the trip.', '这个男孩在打包旅行需要的衣物。', '1_0_20170114160857_28976_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1377, 'parent', '/ˈperənt/', 'parent.mp3', 'n.根源，母体', '6d46325ee833d392fcdee83a0afaea25.jpeg', 'd_24_17975_0_4_20150808233848.png', 'New shoots appear from the parent plant.', '新芽从母株上生长出来。', 'db163e2df30a0c06072b09007450ea59_44398_1600307700.mp3', 'par生产，生出孩子 + ent表名词 → parent父母', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1378, 'petrol', '/ˈpetrəl/', 'petrol.mp3', 'n.<英>汽油', 'i_1_8030_0_4_150919110011-gigapixel-scale.jpg', 'd_24_8030_0_4_20150808225358.png', 'Please fill my car up with petrol! the driver said.', '司机说：“麻烦给我的车加满油！”', '02fe8288bda8fafe_1266883629723245184_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1379, 'player', '/ˈpleɪər/', 'player.mp3', 'n.参赛选手，队员', 'f24851a389a38ebd5cb063b822ce3aaf_55892_1565320013.jpg', '20141013_08_13_02_745_v3.png', 'I am a player on my local basketball team.', '我是本地篮球队的队员。', '6c6c19e5a50f622a_1266763311251827520_250117.mp3', 'play比赛，游戏 + er表人 → player选手，队员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1380, 'poison', '/ˈpɔɪzn/', 'poison.mp3', 'n.毒物，毒药，毒素；  v.毒死，毒害', 'i_1_8498_0_2_20150808130827-gigapixel-scale.jpg', 'd_16_8498_0_2_20150808233146.png', 'Don\'t drink that poison. It will kill you.', '不要喝那瓶毒药，它会把你毒死的。', 'sa_1_8498_0_2_20150808130827.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1381, 'polite', '/pəˈlaɪt/', 'polite.mp3', 'adj.有礼貌的', 'ac18e567c088a761985df5a3fc0edcdd_62317_1751597437.jpg', 'd_24_8218_0_3_20150808225529.png', 'This polite girl gave her seat to an old lady.', '这个有礼貌的女孩把自己的座位让给了一位老太太。', 'e6e0be6ffe093c6b_1266883323512400800_250207.mp3', 'pol光滑 + ite…的 → polite有礼貌的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1382, 'power', '/ˈpaʊər/', 'power.mp3', 'n.力量；  v.提供动力', '392a14079ad34564ba4f82cf3442c9a1_106468_1656988592.jpg', 'd_24_17274_0_3_20150808232543.png', 'He has great power to lift such a heavy barbell.', '他力气很大，能举起如此重的杠铃。', 'us_He_has_20220704154038939_1d6297c66b072ce14a63.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1383, 'president', '/ˈprezɪdənt/', 'president.mp3', 'n.总统；院长', '20120907_03_07_54_690.jpg', 'd_24_16590_0_4_20150808231614.png', 'All of them are American presidents.', '他们都是美国总统。', '53207f28c1bd7bec225429cf1d8a1ee0_13525_1649759433.mp3', 'presid=preside主持，担任主席 + ent人 → president总统', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1384, 'proof', '/pruːf/', 'proof.mp3', 'n.证据，证明；  v.校对', '1bf287893b1392862d910886f2b525f2_274398_1700790259.jpeg', 'd_1_6162_0_4_20150808124745.png', 'The surveillance cameras provided clear proof of many cases.', '监控摄像头为许多案件提供了明确的证据。', 'us_The_surveillance_20231124094517084_d04106d2e9f2e65467e5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1385, 'question', '/ˈkwestʃən/', 'question.mp3', 'v.怀疑', 'd9b31fbb856897cf1669115a05aa6c98.jpeg', 'd_24_16445_0_3_20150808231245.png', 'The woman raised her hand and questioned what the man was saying. ', '那个女人举起手，质疑男人所说的内容。', 'e47135b7d3fd2615f5a5fdaa4d65e271.mp3', 'quest寻求，询问 + ion名词后缀 → question疑问', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1386, 'quiet', '/ˈkwaɪət/', 'quiet.mp3', 'adj.安静的；  n.安静，平静；  v.使安静，平静', '6e997ead32f0c96a22469c15b861beb0_178772_1524038810.jpg', 'd_95_13892_0_4_20150809012827.png', 'Please be quiet.', '请保持安静。', '10862d7bc05bf616_1266763522084219690_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1387, 'race', '/reɪs/ ', 'race.mp3', 'n.（速度上的）比赛；  v.参加竞赛', '20120522_05_13_21_311-gigapixel-scale.jpg', 'd_24_5531_0_4_20150808224112.png', 'It was fun participating in the race.', '参加赛车比赛真的很好玩。', '5fa49a3bf507453b_1266763450477074958_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
