INSERT INTO `words` VALUES (1389, 'reach', '/riːtʃ/', 'reach.mp3', 'v.抵达；（大或长等）足够达到，发展到', 'fffc71a67dbd3f1cbd5086bb4deebff8_104789_1736415780.jpg', 'd_24_2780_0_4_20150808223315.png', 'Using the red ladder', '我能用这架红色的梯子登上顶部。', '72d0cd84d10bc3ec_1266883380263234382_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
