INSERT INTO `words` VALUES (1393, 'revise', '/rɪˈvaɪz/', 'revise.mp3', 'v.修改；温习（功课）', '3e42393e08b759388ebae4a56a03c4bc_197876_1588924641.jpeg', 'd_107_4581_0_2_20150809010132.png', 'She is revising her paper according to the advice given by her teacher.', '她正在根据老师给的意见修改论文。', '10f373db8b57d9626ea31f8b5a6ae9d7_49908_1588924639.mp3', 're一再，重新 + vise看 → 再看一遍 → revise修正', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
