INSERT INTO `words` VALUES (1400, 'single', '/ˈsɪŋɡl/', 'single.mp3', 'adj.单个的；未婚的；单身的；  n.单程票', '7339ef3fcb248bcb6594f88f51d2aebc_70842_1590166921.jpg', 'd_24_17967_0_4_20150808233827.png', 'There is a single shoe on the ground.', '地上有一只单独的鞋。', 'a7394129d09c92a7_1266883375443237468_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1401, 'society', '/səˈsaɪəti/', 'society.mp3', 'n.社会；社团', '8089e1a5e9fec2e55b2b87887e724136_101951_1599446483.jpeg', 'd_24_17673_0_3_20150808233249.png', 'In a modern society many people can live peacefully.', '在现代社会中，许多人都可以和平地生活。', 'd6f6b7c5ef2d4c8c_1266883324640603058_250207.mp3', 'socie=social社会 + ty表名词 → society社会，社团', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
