INSERT INTO `words` VALUES (1403, 'stick', '/stɪk/', 'stick.mp3', 'v.粘贴；  n.棍，棒，条', '4fd3d48685a691dfeb1c5595bb9199cb_198262_1575283764.jpeg', 'd_24_7953_0_3_20150808225304.png', 'The woman is sticking a paper-cut on the window.', '这位女士正将一张剪纸贴在窗户上。', 'us_The_woman_20240628181640548_b2e639930e13ed0403f4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1404, 'strong', '/strɔːŋ/', 'strong.mp3', 'adj.强壮的', 'dd5d2bf01676960ecd505faab1f59376_42744_1564370491.jpg', 'd_24_17177_0_3_20150808232246.png', 'The strong man has a muscular body.', '这个强壮的男人有着一身健壮的肌肉。', 'b0570be2631eb88126088c2caf783e9f_26340_1564370491.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
