INSERT INTO `words` VALUES (1407, 'tooth', '/tuːθ/', 'tooth.mp3', 'n.牙齿；齿状物', '5cfc2d1c10a15b54f0842594061fa585_64083_1760346998.jpg', '20121225_20_10_05_528.png', 'Every tooth was straight and white.', '每颗牙齿都整齐洁白。', '1a7f5083fb4d4387_1268213312524534732_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1408, 'transparent', '/trænsˈpærənt/', 'transparent.mp3', 'adj.透明的，清澈的', '9e3deaf67c0ddfd48b66e3020000496f_40852_1694662933.jpg', 'd_107_6424_0_2_20150809020054.png', 'These glasses are transparent.', '这些玻璃杯是透明的。', 'us_These_glasses_20230914114222246_731dcedfcc486ed1ee24.mp3', 'trans横过，超过 + par出现 + ent形容词后缀 → 横穿某物能看见 → transparent透明的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1409, 'unhappy', '/ʌnˈhæpi/', 'unhappy.mp3', 'adj.不幸福的，不快乐的', '8624877d4a49aebe7a567429e33cd6a7_85773_1538665931.jpg', 'd_16_8052_0_2_20150808232455.png', 'He showed us that he was unhappy.', '他向我们表示他不开心。', 'fe415e9899e5929b_1266883197651757862_250207.mp3', 'un不，没有 + happy快乐 → unhappy不快乐的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1410, 'vacation', '/vəˈkeɪʃn/', 'vacation.mp3', 'n.假期；  v.度假', '3d4798087054bdd2cacaa3e7529e3fa9_157978_1523592440.jpg', 'd_24_6021_0_3_20150808224429.png', 'The girl took a vacation on the beach.', '这个女孩在海边度假。', '008ee3772ac15864_1266883009567108022_250207.mp3', 'vac空 + ation表名词 → vacation假期', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1411, 'validity', '/vəˈlɪdəti/', 'validity.mp3', 'n.有效（性），效力', 'i_2_6666_0_3_20150808151714-gigapixel-scale.jpg', '23caa250168e3343bbf687f06b0e7583_56507_1724836956.jpg', 'Nobody questioned the validity of the judge\'s ruling.', '没有人质疑法官判决的有效性。', 'sa_2_6666_0_3_20150808151714.aac', 'valid有效的 + ity表名词 → validity正确（性）；有效（性） ', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1412, 'valuable', '/ˈˈvæljuəb(ə)l/', 'valuable.mp3', 'adj.宝贵的，有价值的；  n.（复数）贵重物品', 'i_1_5123_0_2_20150808123529-gigapixel-scale.jpg', 'd_16_5123_0_2_20150808225023.png', 'My grandfather left me valuable jewelry.', '我的祖父给我留下了贵重的珠宝。', 'd6d8fdf410444879_1266883198622849606_250207.mp3', 'valu=value价值 + able形容词后缀 → valuable有价值的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1413, 'variable', '/ˈveriəbl/', 'variable.mp3', 'adj.易变的，可变的；  n.变量，可变物', 'i_1_3961_0_2_20150808122140-gigapixel-scale.jpg', 'd_107_3961_0_2_20150809003716.png', 'You can\'t predict the weather here—it\'s too variable.', '你不能预测这里的天气，它实在是太多变了。', 'sa_1_3961_0_2_20150808122140.aac', 'vari=vary变化 + able形容词后缀 → 易变的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1414, 'via', '/ˈvaɪə/', 'via.mp3', 'prep.经过，通过', 'a4c28cce68917710e2e6e7e0ea2080f8_80640_1585124018.jpeg', 'd_107_4380_0_2_20150809005446.png', 'We left Guangzhou', '我们离开了广州，乘大巴经武汉去北京。', '86d6dc2f78a68cf1708e03b9bdb88bbe_24653_1585124069.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1415, 'visual', '/ˈvɪʒuəl/', 'visual.mp3', 'adj.视力的，视觉的', 'i_1_5151_0_4_150909144051-gigapixel-scale.jpg', 'd_107_5151_0_2_20150809011729.png', 'The debate over the dress color is actually a visual trick.', '关于裙子颜色的争论实际上是一个视觉游戏。', 'la2db4dcqvykwk7kpw676brdlufldwhc.mp3', 'vis看 + ual表形容词 → visual视觉的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1416, 'whenever', '/wenˈevər/', 'whenever.mp3', 'conj.无论何时', '3_0_20170930071436_81865_c-gigapixel-scale.jpg', 'd_24_19278_0_3_20150809001142.png', 'You can call customer service whenever you want.', '无论何时，你都可以呼叫客服。', '36563dcc2087813d_1266883619496111056_250207.mp3', 'when何时 + ever究竟 → whenever无论何时，随时', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1417, 'witness', '/ˈwɪtnəs/', 'witness.mp3', 'n.目击者；  v.目击，亲眼看见', 'i_16_8980_0_10_151116161639-gigapixel-scale.jpg', 'd_16_8980_0_7_20150808233652.png', 'The little girl is the only witness of the accident.', '小女孩是这场事故的唯一目击者。', 'sa_16_8980_0_10_151211170442.aac', 'wit智慧 + ness表名词 → 目击者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1418, 'worse', '/wɜːrs/', 'worse.mp3', 'adv.更坏地，更恶劣地；  adj.更坏的，更恶劣的；  n.更坏的事，更恶劣的事', 'c4eda27befa91e3f2132d0eabad11ed9_126793_1605251447.jpg', 'd_109_9156_0_2_20150809055850.png', 'The company is performing worse and worse.', '这家公司的业绩越来越差。', '4c4d3c9d2c5fe29b9ee488e5fd90520c_40409_1533549687.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1419, 'wrap', '/ræp/', 'wrap.mp3', 'v.裹，包，捆', 'i_1_9253_0_4_150914112827-gigapixel-scale.jpg', 'd_1_9253_0_2_20150808131326.png', 'She wrapped the gift with some colorful paper.', '她用彩色的纸把礼物包了起来。', 'c9a199f107562942_1266883379269294616_250207.mp3', 'wr=wer拧 + ap  → wrap裹，包，捆', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1420, 'accommodation', '/əˌkɑːməˈdeɪʃn/', 'accommodation.mp3', 'n.住宿，膳宿；调解；住处，停留处', 'e2717417f1bc0cb188f4a88bc2f1f5cb_204695_1579315911.jpeg', '20130308_21_35_20_745.png', 'Most universities provide wonderful accommodations for students these days.', '现在，几乎所有大学会为学生提供良好的住宿环境。', '01c84dd05dc5ad822942cca3bc8eee4a_47398_1579315907.mp3', 'accommodat(e)使适应，容纳 + ion名词后缀 → accommodation住所', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1421, 'accomplish', '/əˈkɑːmplɪʃ/', 'accomplish.mp3', 'v.（通过努力）完成；实现', '73354f2510c93e22a08dc2fda9b746c4_66765_1584955492.jpeg', 'd_16_6371_0_2_20150808230643.png', 'She is so happy to have accomplished her weight-loss goal.', '她很高兴完成了自己的减肥目标。', '8941a749b11d2af49eeb2d5319714af7_44402_1584955518.mp3', 'ac使 + complish填满 → 已经填满的 → accomplish完成', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1422, 'addition to sth.', '/əˈdɪʃn tu ˈsʌmθɪŋ/', 'addition to sth..mp3', 'phr.增加', 'a15283008700b792186a31b3b0ccf2fc.jpg', '', 'They had a new addition to the family just recently.', '他们家里刚刚添了一口人。', '39b4244e3ca951e75b667875f8e6cdce_24581_1621914736.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1423, 'admission to', '/ədˈmɪʃn tuː/', 'admission to.mp3', 'phr.……的许可', '265620b276c5343dcaf7ce3f81d2947a.jpg', '', 'He just got the admission to that college.', '他刚刚收到那所大学的入学许可。', '204e879aefd3019deb001df031e95cb8_40736_1593575245.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1424, 'adopt', '/əˈdɑːpt/ ', 'adopt.mp3', 'v.收养', 'e83300e658747232c038dc39652b8174_192056_1564736056.jpg', 'd_16_7581_0_2_20150808231836.png', 'The couple adopted a child from the orphanage.', '这对夫妻从孤儿院收养了一个孩子。', '4043edce5fbd6a74cc00251334329152_44896_1564736047.mp3', 'ad做…，加强… + opt选择 → 选出来 → adopt采纳，收养', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1425, 'affection for', '/əˈfekʃn fɔːr/', 'affection for.mp3', 'phr.对……的感情', '25cb29da587f7674301f72fbe6c1fe4c.jpg', '', 'He showed deep affection for his wife.', '他对妻子表现出深深的感情。', '315568d9e7d3ac81271d35fbe7f7946d_13995_1619159438.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1426, 'African', '/ˈæfrɪkən/', 'African.mp3', 'adj.非洲的，非洲人的；  n.非洲人', '988eb9372a5b7bdfaa79bd18a301d832_190997_1564370580.jpg', 'd_24_19280_0_3_20150809001153.png', 'African specialties include instruments', '非洲的特色包括乐器、野生动物还有钻石。', '647bf9257e6f66436c1cb792ea938dd3_36626_1564370580.mp3', 'Afric非洲的 + an表属于…的 → African非洲的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1427, 'alone', '/əˈloʊn/', 'alone.mp3', 'adj.单独的；  adv.独自地', '243013195d2c4468155e4f33192c0ea8_82224_1577952615.jpeg', 'd_24_17990_0_3_20150808234000.png', 'Seesaws are not very fun when you\'re alone.', '当你孤身一人时，跷跷板就不那么有趣了。', '0e3c7657f8b45b98_1266883013486729738_250207.mp3', 'al全部的，完全的 + one一个 → alone单独的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1428, 'ancient', '/ˈeɪnʃənt/', 'ancient.mp3', 'adj.古代的', 'a58f2072831594ac8ded68f9802c4308_96115_1565342482.jpg', 'd_24_5064_0_3_20150808223852.png', 'These ancient statues are over 2', '这些古代雕像有2 000多年的历史。', 'a9262c1c7fbb3eb8_1266883379204741650_250207.mp3', 'anci古老 + ent……的 → ancient古代的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1429, 'anxiety for', '/æŋˈzaɪəti fɔːr/', 'anxiety for.mp3', 'phr.焦虑，担忧', '7ce3eba67c6d11279a8c332614883340_86076_1707014856.jpg', '', 'The students showed anxiety for the exam.', '学生们对考试感到焦虑。', 'us_The_students_20240204104720213_30dd2c3394c77118aef7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1430, 'at best', '/æt best/', 'at best.mp3', 'phr.充其量', 'b0043dada52acf47c855475893db0f31.jpg', '', 'He would only get a D at best if he kept skipping class.', '如果他继续翘课的话，他最多只能得一个D。', '301526b10163bd274878623bbf6929d3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1431, 'at heart', '/æt hɑːrt/', 'at heart.mp3', 'n.本质上', 'ac480388d94d331cae7900f2eb497107.jpg', '', 'Despite his appearance', '不看他的外表，他本质上很和善。', '1533f8a5c5f4209ce1c6c3da93fec1c8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1432, 'at home', '/ætˈhoʊm/', 'at home.mp3', 'phr.在家', '6a95ffc7284d6af6c147da616a602f03.jpg', '', 'He usually exercises at home. ', '他一般在家里做锻炼。', '823a21d10a7e1d62e5dce1157e652c15.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1433, 'battery', '/ˈbætəri/', 'battery.mp3', 'n.电池（组）', 'i_1_7283_0_4_151110145524-gigapixel-scale.jpg', 'd_105_7283_0_2_20150809060331.png', 'My phone is out of battery. It\'ll shut off soon.', '我的手机没电了，很快就会关机。', 'ef8f2f62852f5671_1266883627792968530_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1434, 'behave', '/bɪˈheɪv/', 'behave.mp3', 'v.表现得体', '18133f8f62c1e6d095ee50a19c8fb831_139671_1549942807.jpeg', '20121225_18_36_35_761.png', 'The boy\'s mother asked him to behave himself and not be rude.', '男孩的妈妈让他守规矩些，不要粗鲁。', 'rh83ene2sz2uapt5had6s3vsjt2xnph4.mp3', 'be使 + have持有 → 一个人拥有的动作 → behave举止端正', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1435, 'blackboard', '/ˈblækbɔːrd/', 'blackboard.mp3', 'n.黑板', '147726e0ef3943c634b5e4367fd0048e_69676_1541839482.jpg', 'd_94_11879_0_4_20150809005940.png', 'She is the student on duty today', '她是今天的值日生，所以她要擦黑板。', 'b8c39d45fcb43b071b46413697f73687_23398_1541839591.mp3', 'black黑色的 + board板子 → blackboard黑板', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1436, 'brush', '/brʌʃ/', 'brush.mp3', 'n.画笔，笔刷；小冲突；  v.掠过', '5c221ad0e1f62ee226d31c867feb9f8b_130757_1583398735.jpg', '20141015_14_20_40_405_v3.png', 'Brushes of different sizes may be applied in different situations.', '不同尺寸的画笔可以用于不同的情况。', '54f21f1ab3ae3b4a_1266883112478092170_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1437, 'butter', '/ˈbʌtər/', 'butter.mp3', 'n.黄油，奶油；奉承话；  v.涂黄油于……上', '4d9c6ca8b71ffacb4d2791e0fce0253a_78878_1585132101.jpeg', 'd_24_17150_0_3_20150808232145.png', 'She usually has bread with butter for breakfast.', '她早餐经常吃黄油面包。', 'f905d757372777b0_1266763449697852148_250117.mp3', 'but牛 + ter奶酪 → 牛奶加工而成的乳酪 → butter黄油', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1438, 'by the way', '/baɪ ðə weɪ/', 'by the way.mp3', 'phr.顺便说一下', '3_0_20170723071312_36421_c.jpg', '', 'Can I check in online? And by the way', '我可以网上办理入住吗？顺便问一下，无线网密码是多少呢？', '3_0_20170723071312_31148_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1439, 'Canada', '/\'kænədə/', 'Canada.mp3', 'n.加拿大', 'i_24_17331_0_5_151128113347-gigapixel-scale.jpg', 'd_24_17331_0_3_20150808232716.png', 'This is the national flag of Canada.', '这是加拿大的国旗。', '618d17debd6442b9_1266763400435444710_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1440, 'civil', '/ˈsɪvl/', 'civil.mp3', 'adj.民用的，公民的；国内的；有礼貌的，客气的', '996b31866585af3b652f4eb7767d8b0e_114997_1656646295.jpg', 'd_107_7843_0_2_20150809022245.png', 'A civil aircraft is used for taking passengers.', '民用飞机用于载客。', '899fde059cf0445df72d55aaf22d5932_19324_1625726150.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1441, 'classify', '/ˈklæsɪfaɪ/', 'classify.mp3', 'v.把……分类', 'i_1_5390_0_4_151105142639-gigapixel-scale.jpg', 'd_107_5390_0_2_20150809012326.png', 'The color of the bin is what classifies the type of garbage.', '垃圾箱的颜色可以区分垃圾的类型。', 'havxzn7c9t9fp3m4s6fka57fbtjgt47a.mp3', 'classi=class分类 + fy使成为... → 把...分类', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1442, 'cloth', '/klɔːθ/', 'cloth.mp3', 'n.（一块）布；衣料，布料', '2b6192be5dc69470b559eb58539a5930_180712_1565150108.jpg', 'd_24_10161_0_4_20150808230355.png', 'The shop sells different kinds of cloth.', '这家商店出售各式各样的布料。', '6db6b5c0afdd2121_1266883487935998858_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1443, 'clothe', '/kloʊð/', 'clothe.mp3', 'v.穿衣', 'd8701992987d767b221e36d2f2e42070_164002_1523599995.jpg', '', 'The mum clothed the baby.', '妈妈给宝宝穿上衣服。', 'sa_1_492_0_4_151017100434.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1444, 'combine', '/kəmˈbaɪn/', 'combine.mp3', 'v.混合，联合', 'f5b630952767f6aa9cec65295f2ee68b_56074_1566899206.jpeg', '37923017f8a6f95f0306ffedbf6d05cb_12677_1567148816.png', 'Combine yellow and blue', '把黄色和蓝色混合起来，你就会得到绿色。', '7099efa5e6f65e5304d6ebab062c4cb0_17757_1566899235.mp3', 'com与...一起 + bin成对地 + e → combine联合', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1445, 'commercial', '/kəˈmɝːʃl/', 'commercial.mp3', 'n.商业广告；  adj.贸易的', '3ca3f4b7a84484f595241e09a08054d7_84842_1654740778.jpg', 'd_107_7131_0_2_20150809021509.png', 'The kids are watching a TV commercial of fast food.', '孩子们正在看快餐的电视广告。', 'us_The_kids_20220609100939063_59ba8f492c250791187c.mp3', 'com共同 + merc交易 + ial...的 → 共同交易的 → 商业的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1446, 'contain', '/kənˈteɪn/', 'contain.mp3', 'v.包含，含有，容纳', 'ce814537e3d276bf6351e4ecca43ca38_107759_1558511178.jpeg', 'd_24_9894_0_3_20150808230324.png', 'Sea water contains salt.', '海水含有盐分。', '016cb71008e3c156_1266763524689058412_250117.mp3', 'con一起 + tain握住 → contain包容，包含', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1447, 'copyright', '/ˈkɑːpiraɪt/', 'copyright.mp3', 'n.版权，著作权', 'eb0dcb6bea04fcfcfc03aa245bc8dc81_68242_1656930192.jpg', 'd_1_8371_0_4_20150808130631.png', 'He sold the copyright on his book to the large publishing house.', '他把书的版权卖给了那家大型出版社。', '865af78a80e77951c4341ab6b6db8840.mp3', 'copy复制，复印 + right权利 → copyright版权，著作权', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1448, 'count on', '/kaʊnt  ɔːn/', 'count on.mp3', 'phr.依靠', 'ecd8bb1a575b12646523e940f060b382_574602_1701678521.jpg', '', 'Since I lost my ability to walk', '自从我失去了行走能力，我每天都在依靠我的女儿。', 'us_Since_I_20241009160010422_3ee62e295d9156461aac.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1449, 'critical', '/ˈkrɪtɪkl/', 'critical.mp3', 'adj.危急的；爱挑剔的', 'aa910a6aae63959e94dbf76d0dcd2f4c_132381_1726280850.jpg', 'd_1_3890_0_3_20150808122019.png', 'The injured man was in a critical condition so doctors rushed him to the emergency room.', '这位伤者情况危急，因此医生们赶紧把他送到了急诊室。', '08b8c4476667a8eb1cb5f19e7f1c8972_33587_1619339754.mp3', 'critic批评家 + al表形容词 → critical挑剔的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1450, 'cut in', '/kʌt ɪn/', 'cut in.mp3', 'phr.插嘴', 'c7c645744cd6774c070da867933d3fa3.jpg', '', 'The manager had to cut in as his junior staff was explaining it wrong.', '经理不得不插嘴打断下属，因为他的解释有误。', '814d48ee1f5ed879ea5eff6fd39b445f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1451, 'death', '/deθ/', 'death.mp3', 'n.死亡；毁灭', '2ffb973bfe7f17fc6fe6bfd37476bf2c_175067_1575361254.jpeg', 'd_24_17173_0_4_20150808232238.png', 'Mr. Egg is crying over the death of his friend.', '蛋先生为他朋友的死而哭泣。', 'vuycx997nxemp6ywu6vyh3e4e9dqbhep.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1452, 'definition', '/ˌdefɪˈnɪʃn/', 'definition.mp3', 'n.定义，释义；（轮廓等）清晰', '936d6b067fe3c4883fe3b5b935ff8dc1_132460_1693905608.jpg', 'd_105_5630_0_2_20150809054927.png', 'The dictionary contains the definition of thousands of words.', '字典包含了成千上万个词的释义。', 'us_The_dictionary_20230905172014229_93a2038804328e019eec.mp3', 'de使…成为 + fin界限 + ition名词后缀 → 划出界限 → 定义 ', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1453, 'deny', '/dɪˈnaɪ/', 'deny.mp3', 'v.否认', 'efbdebdeabcd37753be091ca390878c9_79710_1594796482.jpeg', 'd_1_8017_0_4_20150808130312.png', 'The little boy denied breaking the window.', '小男孩否认是他打破了窗户。', '12cc76794b60d188_1266883330501925426_250207.mp3', 'de向下 + ny=neg否决 → deny否认', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1454, 'desire', '/dɪˈzaɪər/', 'desire.mp3', 'n.渴望；欲望；愿望；要求', 'i_1_5052_0_4_150829150424-gigapixel-scale.jpg', 'd_24_5052_0_5_20150808223843.png', 'The cat is filled with the desire to eat the fish.', '这只猫心里充满了想要吃掉这条鱼的渴望。', 'sa_1_5052_0_4_150906151920.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1455, 'despair of', '/dɪˈspɛr ʌv/', 'despair of.mp3', 'phr.对……失去希望', 'f7163135fac16cbd954a91fbdd93c8c1.jpeg', '', 'The man lost in the desert despaired of finding water.', '在沙漠中迷路的男人对找到水不抱希望了。', 'fec64608a8bd29f7bbd548045ef02100.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1456, 'diamond', '/ˈdaɪəmənd/', 'diamond.mp3', 'n.钻石；方块牌；菱形；棒球场的内场', 'cc9d8d16e897fe09d8fd1e15e4671755_100508_1594801876.jpeg', 'd_24_5197_0_3_20150808224022.png', 'The diamond is shining brightly.', '这枚钻石闪闪发光。', 'dd40ea2454fb07da_1266883325467974348_250207.mp3', 'diam=adam强硬的，不屈服的 + ond → 坚硬的石头 → 钻石', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1457, 'dim', '/dɪm/', 'dim.mp3', 'adj.暗淡的；  v.（使）变暗淡', '24947e0eaa4bdd391219aa398de5993e_132780_1543910460.jpeg', 'd_24_6364_0_5_20150808224615.png', 'This lamp gives out a dim light.', '这盏灯发出一束微弱的亮光。', '50cf8a072819eafbf373e45d7fe50815_9762_1543910617.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1458, 'disadvantage', '/ˌdɪsədˈvæntɪdʒ/', 'disadvantage.mp3', 'n.不利地位，不利条件，弱点', '2e715459495b491308b5fd437848ad9c_85433_1576131796.jpeg', 'd_105_9213_0_2_20150809061339.png', 'When the books fell', '当书掉落时，不像矮个男孩，高个男孩处于不利地位。', '0712f9ce13e5f7dc_1266883486498138980_250207.mp3', 'dis不，非 + advantage优点 → disadvantage缺点', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1459, 'disagree', '/ˌdɪsəˈɡriː/', 'disagree.mp3', 'v.不同意，有分歧，持不同意见', '3_0_20170713071653_37854_c.jpg', 'd_24_8487_0_4_20150808225741.png', 'She disagreed with his advice.', '她不赞同他提出的建议。', '3_0_20170713071653_8567_c.aac', 'dis否定 + agree赞同 → disagree不同意', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1460, 'disappoint', '/ˌdɪsəˈpɔɪnt/', 'disappoint.mp3', 'v.使失望，使受挫折', 'c_20150605_102154_1_8046-gigapixel-scale.jpg', '20130130_16_11_40_670.png', 'The exam result disappointed him.', '考试成绩让他很失望。', 'sa_1_8046_0_4_160318092612.aac', 'dis不 + appoint预约 → 失约 → 失望 → 使失望；受挫折', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1461, 'discount', '/ˈdɪskaʊnt/', 'discount.mp3', 'n.折扣（读作/ˈdɪskaʊnt/）；  v.打折（读作/dɪsˈkaʊnt/）', 'e497579fff3451800f9247b82d1989a6_88279_1582271372.jpeg', '20141011_04_25_29_896_v3.png', 'We can buy many goods with great discounts during sales.', '我们可以在打折季买到很多打折商品。', 'a4acf5cca2080ab367a8d9a906d8dea1_20578_1610436814.mp3', 'dis取消 + count数量 → 取消一些金钱的花费 → discount折扣', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1462, 'do without', '/dʊ wɪðˈaʊt/', 'do without.mp3', 'phr.没有...也行', 'cefde0021370f038af545a7450b2631a.jpg', '', 'He left his bus pass at home but could do without it.', '他把公交卡忘在家里了，但没带也行。', '072057fd075ee27dfbb788dffb66ff9b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1463, 'doubtful', '/ˈdaʊtfl/', 'doubtful.mp3', 'adj.怀疑的，疑惑的', '762991ca85c3ff2952c032b1e18b5d66_195110_1575267533.jpeg', 'd_1_4148_0_2_20150808122424.png', 'I\'m doubtful about the true value of the painting.', '我对这幅画的真实价值表示怀疑。', 'b20412e075dbbef6_1266883491573640162_250207.mp3', 'doubt怀疑 + ful形容词后缀 → doubtful怀疑的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1464, 'either', '/ˈiːðər/ /ˈaɪðər/', 'either.mp3', 'det.二者之一；（两者中的）各方；  adv.也（用于否定句或短语后）', '3_0_20160528174705_53406_c-gigapixel-scale.jpg', 'd_24_19594_0_4_20150809002252.png', 'The girl is choosing between getting either a cat or a dog.', '这个小女孩正在考虑是要一只狗呢，还是猫呢？', '0ee1b32229b31080_1266883326612167392_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1465, 'engage', '/ɪnˈɡeɪdʒ/', 'engage.mp3', 'v.加入，参加（活动）；（军队）交战', 'ccb5e7178621fe30fdfa891c6214d5cd.jpg', 'd_107_3972_0_2_20150809003801.png', 'She used to work out alone', '她过去常常独自锻炼，但现在参与集体跑步。', 'd0f238b50a6cee3e_1266883378616118254_250207.mp3', 'en进入，使 + gage承诺 → 使人承诺（以加入）→ engage加入，参加', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1466, 'engineering', '/ˌendʒɪˈnɪrɪŋ/', 'engineering.mp3', 'n.工程；工程师行业', '6ae5e70dd6c4875a4eaef713dcb0993e_98437_1649729595.jpg', 'd_105_5070_0_2_20150809054406.png', 'All the workers are trying to solve the engineering problem.', '所有工人都尝试着解决这个工程问题。', 'sa_1_5070_0_45_160505165141.aac', 'engineer工程师 + ing表名词 → engineering工程、工程师行业', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1467, 'enough', '/ɪˈnʌf/', 'enough.mp3', 'det.足够的；  adv.足够地；  pron.很多', '3_0_20170614071056_99100_c-gigapixel-scale.jpg', 'd_24_17167_0_5_20150808232227.png', 'No', '别给我夹菜了，已经够多了。', 'xe5c77ntw99lv949nk35eatjyjj5px5p.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1468, 'expect', '/ɪkˈspekt/', 'expect.mp3', 'v.期待', '2a28367d363f6da033af69b2cbf956d0_79147_1585129960.jpeg', 'd_24_8092_0_4_20150808225433.png', 'The little rabbit is expecting the girl to feed it carrots.', '小兔子正期待着女孩喂它吃胡萝卜。', 'c73eeaefd84263e9_1266883373873605384_250207.mp3', 'ex出 + pect=spect看 → 看出去 → expect期待', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1469, 'football', '/ˈfʊtbɔːl/', 'football.mp3', 'n.<英>足球', 'i_76_12760_0_4_20150809030914-gigapixel-scale.jpg', 'd_93_12760_0_4_20150809002033.png', 'He loved football from a young age.', '他从小就热爱足球。', '73358e21d8dede5d_1266763311996644186_250117.mp3', 'foot脚 + ball球 → football足球比赛；足球', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1470, 'fork', '/fɔːrk/', 'fork.mp3', 'n.叉，餐叉', '2cc85d246f9f8fe1c359385296b76963_95174_1600309088.jpg', 'd_24_8486_0_5_20150808225739.png', 'The fork is usually placed on the left side of the plate.', '餐叉通常被放在餐盘的左侧。', '7b0b89daedc6089b_1266763403075496750_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1471, 'French', '/frentʃ/', 'French.mp3', 'adj.法国的；法国人的；  n.法语', '79bba61c6e4f9a7dab50b0a58cb1b7b7_182575_1532165010.jpeg', 'd_93_12787_0_4_20150809002039.png', 'These icons are all closely related to French culture.', '这些图标都与法国文化密切相关。', '6284ff7611c74ab5aa492756e7b537bb_20428_1554715302.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1472, 'gain', '/ɡeɪn/', 'gain.mp3', 'v.获得；  n.增加', '3_0_20170723071127_19316_c-gigapixel-scale.jpg', 'd_16_5062_0_7_20150808224910.png', 'We can gain valuable knowledge by reading books.', '我们能通过阅读获得宝贵的知识。', '3_0_20170723071127_67300_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1473, 'gather', '/ˈɡæðər/', 'gather.mp3', 'v.集合；  n.聚集', '82baeff4ab06d1bfb8b295b7aecb44b5_117621_1617778604.jpg', 'd_16_5800_0_2_20150808225903.png', 'People gather around to listen to the girl\'s beautiful singing.', '人们聚在一块，听女孩美妙的演唱。', '9fc84f3e01ab0d46145607b89a083da2_107872_1617778596.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1474, 'generally', '/ˈdʒenərəli/', 'generally.mp3', 'adv.普遍地，广泛地 ；一般地，通常；笼统地，概括地', '946c47dd698916a471ac92af3f082b68_189604_1605150243.jpg', 'd_105_9088_0_2_20150809061241.png', 'The weather this week will be generally rainy.', '这个星期的天气普遍有雨。', 'sa_1_9088_0_3_20150808131154.aac', 'gener出生 + ally……地 → 出生具有普遍性 → 通常地；通常强调普遍性', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1475, 'get away', '/ɡet', 'get away.mp3', 'phr.离开，逃脱', 'getaway_6064_20231106_73b1b795.jpg', '', 'The little girl runs as fast as possible to get away from danger.', '为了逃脱危险，小女孩尽最大努力跑开。', '96a7a7b5e2b5ae40_1266883481000303328_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1476, 'glove', '/ɡlʌv/', 'glove.mp3', 'n.手套', 'i_1_8290_0_4_150924173532-gigapixel-scale.jpg', 'd_24_8290_0_4_20150808225553.png', 'Gloves keep my fingers warm in winter.', '手套使我的手指在冬天很暖和。', '45369d5db6165144_1266763405111220834_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1477, 'headache', '/ˈhedeɪk/', 'headache.mp3', 'n.头痛；令人头痛的事', 'de9570545a33510aecbd90df8952f10d_71368_1574847047.jpeg', 'd_24_16018_0_4_20150808231044.png', 'The man is suffering from a headache.', '这位男士正在遭受头痛的折磨。', '98265e46cd5a6934_1266763402948160296_250117.mp3', 'head头 + ache疼痛 → headache头痛', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1478, 'health', '/helθ/', 'health.mp3', 'n.健康', 'i_16_19546_0_11_160428094041-gigapixel-scale.jpg', 'd_24_19546_0_5_20150809001921.png', 'Eating lots of fruits and vegetables is good for your health.', '多吃蔬菜水果对你的健康是有益的。', 'sa_16_19546_0_11_160428094006.aac', 'heal未受伤的，完好的 + th抽象名词后缀 → health健康', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1479, 'house', '/haʊs/', 'house.mp3', 'n.公司', 'd9ebe1bbae990d57011f02e7dbb271c1.jpeg', 'd_24_17158_0_4_20150808232158.png', 'They work in a publishing house. ', '他们在一家出版社工作。', '6b0959672cb21db384bce7c3b32bf65c_18497_1621928104.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1480, 'indeed', '/ɪnˈdiːd/', 'indeed.mp3', 'adv.的确，当然，确实', '3_0_20170703171711_34327_c-gigapixel-scale.jpg', 'd_24_19588_0_4_20150809002219.png', 'I indeed lost sleep last night.', '我昨晚的确失眠了。', '3_0_20170703171711_38868_c.aac', 'in在...内 + deed行为 → indeed的确', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1481, 'intention', '/ɪnˈtenʃn/', 'intention.mp3', 'n.目的，意图', '492223bb5e8259d6e48ddae0346b58e4_120699_1732171705.jpg', '99b7c1594b29b39c6058f25ec82242e2_71742_1539341415.png', 'I have an intention of buying a house', '我一心想买房，所以我现在必须开始存钱了。', '84d39699fab2e44e_1266883488617638820_250207.mp3', 'intent意图 + ion表名词 → 有意图做某事 → intention有意图，故意', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1482, 'kiss', '/kɪs/', 'kiss.mp3', 'v.吻，接吻；  n.吻', 'e085d0e3a70ac84498b89dad6259dc12_125250_1734689541.jpg', '', 'The man kissed his wife goodbye before heading off to war.', '这个男人在出征前吻别了他的妻子。', 'us_The_man_20241220181225815_daee37a8cd73c0559e57.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1483, 'lead', '/liːd/', 'lead.mp3', 'v.领导，带领，率领；  n.领先地位', '1e2166afbf8cf57232a1e61cffdcecc0_45038_1574839551.jpg', '20121225_20_08_44_2.png', 'Few people lead; many people follow.', '少数人领导；多数人跟随。', 'sa_13_16465_0_2_20150808204010.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1484, 'lifetime', '/ˈlaɪftaɪm/', 'lifetime.mp3', 'n.一生，终生，寿命', '6cb50abd473d431d9759c89c7ff9a85e_201153_1574910347.jpeg', '20141013_22_44_46_418_v3.png', 'They remained close friends throughout their whole lifetime.', '她们是一生一世的好朋友。', '8884e87de298093a590587af1a0ebbb0_30382_1574910345.mp3', 'life生命 + time时间 → lifetime一生', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1485, 'male', '/meɪl/', 'male.mp3', 'n.男性，雄性；  adj.男性的，雄性的', '8566144d57ddfcd05728f278fac31493_100820_1588080536.jpeg', 'd_24_9224_0_3_20150808230128.png', 'The restroom on the right is for males.', '右侧是男洗手间。', '23859cd0825eab64012a1f6f52c15548_46915_1588080542.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1486, 'meeting', '/ˈmiːtɪŋ/', 'meeting.mp3', 'n.会议', '7698cc31ab8641caac0844832904a322_116398_1701680954.jpeg', 'd_24_17172_0_3_20150808232235.png', 'The business group is having a meeting.', '那个商业团队正在开会。', 'f3dea5859907a58c_1266763554992970488_250117.mp3', 'meet开会 + ing名词后缀 → meeting聚集，会合', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1487, 'microphone', '/ˈmaɪkrəfoʊn/', 'microphone.mp3', 'n.话筒，麦克风', 'd759ebc648897eef425c19c7d9948e13_63796_1565342067.jpg', 'd_1_8074_0_2_20150808130356.png', 'The woman speaks with her microphone.', '这位女士用麦克风讲话。', '5b63a79cd0574703_1266883523080903238_250207.mp3', 'micro小 + phone声音 → 小声音变大声音 → microphone麦克风', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1488, 'minimum', '/ˈmɪnɪməm/', 'minimum.mp3', 'adj.最少的，最低（限度）的；  n.最低限度，最小量', '015e15523c331a231c8245613ac98f73_19197_1619342222-gigapixel-scale.jpeg', 'd_107_3902_0_2_20150809003400.png', 'In theory', '理论上说，最低温度是零下273.15摄氏度。', '3_0_20171001071145_23491_c.aac', 'minim小 + um名词后缀，表物 → minimum最小量', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1489, 'mislead', '/ˌmɪsˈliːd/', 'mislead.mp3', 'v.把……带错路，使误入歧途', '1ec8fc19a8353bb6b76e3d3ebea602a8_144899_1538647275.jpg', '20141014_11_15_10_761_v3.png', 'The wrong map misleads him to the suburbs.', '这张错误的地图使他误入郊区。', 'd20deb5fd56bce15a5db6ea94aa019fb_13211_1538647292.mp3', 'mis错误，坏 + lead领导 → mislead使误入岐途', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1490, 'native', '/ˈneɪtɪv/ ', 'native.mp3', 'adj.本地的；与生俱来的；  n.本地人；土著', 'd50ebabf812caeda4963dcaf173b7ad0_83821_1565342720.jpg', 'd_16_6160_0_2_20150808230253.png', 'The native people are wearing their own traditional clothes.', '当地人穿着自己的传统服装。', 'us_The_native_20220701111140752_8660153e3594c79ba15f.mp3', 'nat出生 + ive名词后缀 → native本地人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1491, 'necessarily', '/ˌnesəˈserəli/', 'necessarily.mp3', 'adv.必定', '80fd462150a2443de3691153d4ec10de_195383_1585378392.jpeg', '', 'The biggest diamond in the shop necessarily commands the highest price.', '这家店里最大的这颗钻石必定售价最贵。', '5fa46dd86894d376ac9f8baa43d32e28_25907_1585378419.mp3', 'necessari必要的 + ly表示如...的、有...特征的 → necessarily必然，必定', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1492, 'on schedule', '/ɑːn ˈskedʒʊl/', 'on schedule.mp3', 'phr.按预定时间', '5_48_105_20161119175444_60404_c.jpg', '', 'The flight from Moscow arrived on schedule but all the others are delayed.', '只有来自莫斯科的航班按时到达，其他航班全体延误。', '5_51_78_20161220102549_24039_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1493, 'once', '/wʌns/', 'once.mp3', 'conj.一旦，一...就', '7ce6cd523178cabb5793a984ac79ae85.jpeg', 'd_24_17901_0_4_20150808233358.png', 'Once they knew the price of that house', '他们一知道那房子的价格，就决定买下它。', '6fda63356b4d693c528130c4ebe35a93_49630_1599536695.mp3', 'on=one一 + ce次 → 一次', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1494, 'organization', '/ˌɔːrɡənəˈzeɪʃn/', 'organization.mp3', 'n.组织，体制，团体，机构', 'i_24_16593_0_4_20150808231619-gigapixel-scale.jpg', 'd_107_16593_0_2_20150809025736.png', 'I\'m the leader of this organization.', '我是这个组织的领导。', 'sa_24_16593_0_4_20150808231619.aac', 'organ器官，组织 + ization表名词，发展过程 → organization组织', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1495, 'pass', '/pæs/', 'pass.mp3', 'v.给，传递；通过；  n.飞机或人造卫星等的一次掠过', 'c37d9ebccca8601daa27caee9a3b3361_54356_1575008162.jpg', 'd_37_13644_0_4_20150809012134.png', 'Pass me the stick. Quick!', '把棒子递给我，快！', 'd4934bf973d73868_1266763405634612086_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1496, 'pass on', '/pæs ɑn/', 'pass on.mp3', 'phr.传播，传给', 'ef688dd274b4b729a84bbe6a56990226_639275_1679911091-800-600.jpg', '', 'It\'s possible to pass on the virus to others through the air.', '这种病毒可能会通过空气传播传染他人。', 'us_Its_possible_20230327175821564_1903eaceb7ce1032ee65.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1497, 'past', '/pæst/', 'past.mp3', 'prep.经过；  adv.经过；  adj.过去的，结束的；  n.过去', '3_0_20170721071730_39663_c-gigapixel-scale.jpg', 'd_24_19577_0_4_20150809002122.png', 'She walked past me without stopping.', '她从我面前走过去，连停都没停。', 'npzlmmg9h97bm4aguajg4dwe5ap87mtn.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1498, 'permit', '/ˈpɜrˌmɪt/', 'permit.mp3', 'v.允许，许可；  n.执照（读作/ˈpɜrˌmɪt/）', 'i_13_6167_0_7_160104122244-gigapixel-scale.jpg', 'd_24_6167_0_3_20150808224500.png', 'Only the invited are permitted to enter the room.', '只有受邀人士才被允许进入这个房间。', 'a8202555a403c26e_1266883323329424284_250207.mp3', 'per始终 + mit送，放出 → 始终放出来 → 许可', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1499, 'playground', '/ˈpleɪɡraʊnd/', 'playground.mp3', 'n.操场，游乐区，（学校或公园中的）游戏场', '9e8e41902b76b4ee57d1d8563b0a5d47_200874_1523513428.jpg', '20130105_10_21_55_457.png', 'The students are having fun on the playground after class.', '下课后，学生们在操场上玩耍。', 'z336jtmtmdmusvclavpd6hakcb7x87az.mp3', 'play比赛 + ground场地 → playground操场，运动场', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1500, 'prefer', '/prɪˈfɜːr/', 'prefer.mp3', 'v.更喜欢', 'i_1_7585_0_3_20150808130010-gigapixel-scale.jpg', 'd_24_7585_0_3_20150808225130.png', 'The girl prefers vegetables to cake.', '比起蛋糕，小女孩更喜欢蔬菜。', '7c2ef188c4ec669b_1266797985961695814_250123.mp3', 'pre预先 + fer拿，携带 → 预先带好 → prefer更喜欢', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1501, 'prevent', '/prɪˈvent/', 'prevent.mp3', 'v.防止，阻止', '1f1709e023af78f180ce8f0c9ffeffd6_179858_1605085890.jpg', '20130316_16_34_25_579.png', 'The mother prevented her child from eating sweets.', '妈妈不让她的小孩吃糖。', '4427c00143150b51_1266883370482641794_250207.mp3', 'pre预先 + vent来 → 抢先一步，防止别人 → prevent防止，阻止', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1502, 'price', '/praɪs/', 'price.mp3', 'n.价格，价钱；  v.标价', 'i_13_17174_0_2_20150808204506-gigapixel-scale.jpg', '20121225_19_06_22_873.png', 'I like to go shopping during sales when the prices are low.', '我喜欢在打折的时候去买东西，那个时候价格很便宜。', '94fe11a29765910e_1266798145541483488_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1503, 'print', '/prɪnt/', 'print.mp3', 'v.印刷；  n.印刷，印刷字', 'cddc17720ee9966cab1e_2e2fe82b195a2d702a90_250913.jpg', 'd_24_16003_0_4_20150808231022.png', 'We print a million copies of newspaper every day.', '我们每天要印刷一百万份报纸。', '0a9815ef30119a5ebebbfd2c86cb25e0_25049_1621931885.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1504, 'promote', '/prəˈmoʊt/ ', 'promote.mp3', 'v.升职；促进；宣传；促销', '20da3201df4bf712b97fb0258e9bc433_178949_1696661779.jpg', 'd_107_4743_0_2_20150809010513.png', 'He was very good at his job', '他工作表现很棒，所以他的老板让他升职了。', 'us_He_was_20231007145701240_213bfbf351f8367f1e71.mp3', 'pro向前，在前 + mot动 + e → 向前动 → promote促进', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1505, 'proposal for', '/prəˈpoʊzl fɔːr/', 'proposal for.mp3', 'phr.提案，提议', 'd689a66aa2bf60172565f9ffad03a3d2_161669.jpg', '', 'I am ready to present my proposal for the development of our company.', '我准备好对公司的发展提出建议。', 'us_I_am_20240716135520759_370505a3420c0453a2c6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1506, 'put in', '/pʊt ɪn/', 'put in.mp3', 'phr.花费（时间）', '7b795a736863267da911705264836330.jpg', '', 'She\'s putting in a lot of work improving her French.', '她在提高法语上投入了很多时间和精力。', '60a667dbf0afdfad31ca55830a60063d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1507, 'refuse', '/rɪˈfju:z/', 'refuse.mp3', 'v.拒绝，谢绝；抵制；  n.废料', '2d700ab1efa1522ce7a38493117755fa_125682_1739513228.jpg', 'd_24_5571_0_3_20150808224153.png', 'This boy is refusing to eat vegetables.', '这个男孩子正拒绝吃蔬菜。', 'tvd5duuc7pvlpypq7rzexenyt5g3q9mc.mp3', 're回 + fuse流，泻 → 向回流 → refuse拒绝', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1508, 'republic', '/rɪˈpʌblɪk/', 'republic.mp3', 'n.共和国，共和政体', 'ef5bbcd13a042b8a6e79236c859b7c0e_132607_1639821241.jpg', '', 'France is a republic.', '法国是一个共和国。', '302b01c05a279f56e5676f665686ab04_9607_1639822681.mp3', 're事情，事务 + public公众  → 与公众相关的事务  → republic共和国', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1509, 'respective', '/rɪˈspektɪv/', 'respective.mp3', 'adj.分别的；各自的', '3_0_20170930071251_79982_c-gigapixel-scale.jpg', 'd_1_15262_0_2_20150808132014.png', 'After the party', '派对结束后，我们回到了各自的房间。', 'mbs6xkchccabzwffawvl9z2fwmlvyf8r.mp3', 're回 + spect看 + ive形容词后缀 → 回头看自己 → respective各自的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1510, 'retire', '/rɪˈtaɪər/', 'retire.mp3', 'v.退休；退役', 'i_1_7961_0_4_150923094451-gigapixel-scale.jpg', 'd_16_7961_0_2_20150808232244.png', 'My grandfather retired at 60 and raised a bird.', '我爷爷60岁退休，并养了一只鸟。', 'sa_1_7961_0_4_151017114354.aac', 're回，向后 + tire拉 → 拉回去撤离 → retire退休', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1511, 'root', '/ruːt/', 'root.mp3', 'v.生根；  n.根，根茎，根部', 'c520c0c44136000c8d6620dc2bc49d34_127135_1706765760.jpg', 'd_16_6171_0_2_20150808230321.png', 'The tree deeply roots in the soil.', '这棵树深深地扎根于土壤之中。', 'us_The_tree_20221028163609929_72700a149a887c5a4d60.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1512, 'Russian', '/ˈrʌʃn/', 'Russian.mp3', 'adj.俄罗斯的，俄语的；  n.俄罗斯人，俄语', 'd26af847e30d381a70fa704bfa036daf_170109_1575612651.jpeg', '', 'This poster consists of Russian cultural icons.', '这张海报由俄罗斯文化象征构成。', 'ly8uu57kltaaqn4t6vjqtaesum3s4yxk.mp3', 'Russi(a)俄罗斯 + an形容词词缀 → Russian俄罗斯的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1513, 'saving', '/ˈseɪvɪŋ/', 'saving.mp3', 'n.（复数）储蓄金，存款；节省，节约；（复数）积蓄，储蓄', '2eee548d168db5686ad501d5dbab2dac_146463_1538642245.jpg', 'd_1_7980_0_3_20150808130240.png', 'I put all of my money into savings instead of spending it.', '我把我所有的钱都放在储蓄金里，而不花掉。', '182c5b8a257ff08eb748001076824d1d_18540_1648794947.mp3', 'sav(e)节省 + ing名词后缀 → saving节省', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1514, 'scientist', '/ˈsaɪəntɪst/ ', 'scientist.mp3', 'n.科学家', '12dcb6b16f279a451ce22270f225730c_191113_1575014379.jpeg', 'd_24_17277_0_4_20150808232549.png', 'They are distinguished scientists in the fields of biology and physics.', '他们是生物和物理领域杰出的科学家。', '97eb6f6556519c49_1266798142277725134_250123.mp3', 'scient有知识的 + ist从事某种职业的人 → scientist科学家', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1515, 'selfish', '/ˈselfɪʃ/', 'selfish.mp3', 'adj.自私的', 'dd9032df7b4df8286e68368ac6797879_54246_1656664318.jpg', 'd_16_8543_0_2_20150808233223.png', 'He\'s so selfish', '他太自私了，总是独占着玩具。', '4dk4a7fkzerzfgsle76evsuwmhulm2e4.mp3', 'self自己 + ish形容词后缀 → selfish自私的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1516, 'send', '/send/', 'send.mp3', 'v.发送；送，寄', '535090bfbee080f15c8f7520ea2b8bc8_63312_1577956217.jpeg', 'd_24_18088_0_4_20150808234450.png', 'She sent a message to her friend.', '她给她的朋友发了一条信息。', '8dw9v9yb7zp8ssba3a8qlbg2tbdwfuvu.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1517, 'shelter', '/ˈʃeltər/', 'shelter.mp3', 'n.隐蔽处，躲避处；庇护；  v.遮蔽，庇护', '1f768b12ddc352c7288069f494579057_300637_1619683963.jpg', 'd_16_4783_0_2_20150808224424.png', 'Someone used branches to make a shelter in the woods.', '有人用树枝在树林里搭了个躲避处。', 'cf15cc5f06a273165b344a45ff125366_16032_1540609926.mp3', 'shel盾 + ter群，队 → shelter躲避处', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1518, 'shipment', '/ˈʃɪpmənt/', 'shipment.mp3', 'n.装载的货物；装船；装运；装货量', 'i_2_9985_0_3_20150808162818-gigapixel-scale.jpg', '20140908_23_54_57_215_v3.png', 'I\'m waiting for the shipment coming from India.', '我在等待从印度运来的货物。', 'sa_2_9985_0_3_20150808162818.aac', 'ship船 + ment表名词 → shipment装船，装运', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1519, 'sick', '/sɪk/', 'sick.mp3', 'adj.生病的，有病的；  n.病人；  v.呕吐', 'da3b2da9a7aa17edd30ccaabd93706c0_86526_1577956409.jpeg', 'd_24_18124_0_4_20150808234758.png', 'The sick boy fell asleep in the bed.', '这个生病的男孩在床上睡着了。', '0e92ba0b451357aa_1266763445289376380_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1520, 'silver', '/ˈsɪlvər/', 'silver.mp3', 'n.银，银子；  adj.银色的', '3_0_20170714071210_37915_c-gigapixel-scale.jpg', 'd_24_5074_0_3_20150808223859.png', 'I got a silver medal', '我得了一枚银牌，这意味着我拿了第二名。', '3_0_20170714071210_10636_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1521, 'similar', '/ˈsɪmələr/', 'similar.mp3', 'adj.相似的；类似的', '0ce91e8d2b62bf4adb4cf780d1c55973_68942_1565607969.jpg', 'd_75_14182_0_4_20150809025957.png', 'These two girls are very similar.', '这两个女孩长得很像。', '8776384ef24a872d_1266883322556013198_250207.mp3', 'simil一样 + ar……的 → similar同样的，相似的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1522, 'slice', '/slaɪs/', 'slice.mp3', 'v.把……切成片；大幅度削减；切开；  n.片，薄片，切片', '9fdc9e59029bece945d087d6d51a1659_99391_1582794650.jpeg', '20140929_03_03_33_366_v3.png', 'The man thinly sliced the beef.', '这个男人把牛肉切成了薄片。', '38a7f6418fcbc2be_1266883007278307934_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1523, 'slope', '/sloʊp/', 'slope.mp3', 'n.斜坡；  v.倾斜', '79e70be8d4037e3552e730dc6d97c8f2_85537_1579339492.jpeg', 'd_107_5982_0_2_20150809014724.png', 'This little slope is for people in wheelchairs.', '这个小斜坡是供坐轮椅的人使用的。', '7731409e5b6c7c57765df60ffba4b947_36958_1579339489.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1524, 'smell', '/smel/', 'smell.mp3', 'n.气味；  v.嗅，闻（......的气味），闻到', '0bab59e9e59775a64c383c1a32186bab_88850_1562120783.jpg', 'd_16_7962_0_2_20150808232245.png', 'The smell of this flower is so good.', '这花的气味真是好闻。', '408543341d5b05e9_1266883001355033328_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1525, 'software', '/ˈsɔftwer/', 'software.mp3', 'n.软件', '38fe822da8448977e537656b0626a70c_116465_1590164118.jpeg', '20130308_21_34_34_975.png', 'You can download different kinds of software onto your computer.', '你可以把不同类型的软件下载到电脑上。', '555xx4akajwetk9k7m5fxg3ds6peaj7z.mp3', 'soft软的 + ware物件 → software软件', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1526, 'spectator', '/ˈspekteɪtər/', 'spectator.mp3', 'n.观众；目击者', '8c27f11536e446124e1517042fb55701_89862_1594868892.jpeg', 'd_2_5867_0_6_150906163322.png', 'Thousands of spectators watched the tennis match.', '成千上万的观众观看了这场网球比赛。', 'bf712c10ab3c704ccab7d9681068ace9_55311_1599468201.mp3', 'spect看 + ator名词后缀：人 → 看的人 → spectator观众', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1527, 'split', '/splɪt/', 'split.mp3', 'n.裂缝；劈裂，劈开；碎片；  v.分开', '5fe10554b5f1c353f7d0ef794bd8fdb0_157418_1540526013.jpg', 'd_16_4382_0_2_20150808224206.png', 'There\'s a split on the wall.', '墙上有一条裂缝。', '0619f2e2889fc8fd7704cb9a4b7d507b_7881_1540526025.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1528, 'substance', '/ˈsʌbstəns/', 'substance.mp3', 'n.物质；实质', 'i_1_9105_0_2_20150808131212-gigapixel-scale.jpg', '20130510_18_40_06_254.png', 'Substances like water have three different forms.', '像水这样的物质们有三种不同的形态。', '5904e06d42ded277_1266883377713732300_250207.mp3', 'sub下面 + st站立 + ance表名词 → 站在下面的东西 → substance物质；本质', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1529, 'successful', '/səkˈsesfl/', 'successful.mp3', 'adj.有成就的；出人头地的', '3_0_20160520172614_86281_c-gigapixel-scale.jpg', '20141012_07_29_06_37_v3.png', 'He was a successful businessman and brought great changes to our phones.', '他是一位成功的商人，给我们的手机带来了极大的变化。', '3_0_20160520172614_43362_c.aac', 'suc在下面 + cess行走，前进 + ful…的 → success成功 + ful…的 → successful成功的，有成就的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1530, 'surgery', '/ˈsɜːrdʒəri/', 'surgery.mp3', 'n.外科手术', '4a7bc40e19e07c1b883595deb18b5bb6_100593_1584957229.jpeg', '20130510_18_18_37_886.png', 'They are performing surgery on a patient now.', '他们正在给一位病人做外科手术。', 'yava8ucp5qazkwe5amqj8swmsrkb9ypy.mp3', 'surger=surgeon外科医生 + y名词后缀 → surgery外科，外科手术', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1531, 'systematic', '/ˌsɪstəˈmætɪk/', 'systematic.mp3', 'adj.系统的，有条理的', '4bdad3d11b3ed2acc0d358db66a093e8_192793_1621937452.jpg', 'd_107_4048_0_2_20150809004133.png', 'Baicizhan offers a systematic way of learning English.', '百词斩提供了一套系统性的学习英语的方法。', 'us_Baicizhan_offers_20241009155634557_42446bc7697a671caeb5.mp3', 'system系统 + atic…的 → 有系统的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1532, 'take', '/teɪk/', 'take.mp3', 'v.花费（时间）', '0248cd89ca0a54cc9a6da10455fe9050.jpg', 'd_24_17663_0_4_20150808233231.png', 'It takes twenty-five minutes to prepare this dish.', '做这道菜要花费二十五分钟。', '07474071dde7adcab7ccff1cc5ed0b09.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1533, 'tall', '/tɔːl/', 'tall.mp3', 'adj.身材高的，高大的', 'i_16_19097_0_2_20150809021054-gigapixel-scale.jpg', 'd_24_19097_0_3_20150809000537.png', 'How did you grow so tall?', '你是怎么长到这么高的？', '695229309dfff789_1266763313587792780_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1534, 'team', '/tiːm/', 'team.mp3', 'n.队，组', 'ce1176242bab32b1d2c1f9e5196331f1_161242_1542594766.jpeg', '20121225_18_22_54_517.png', 'These handsome guys are members of a high school basketball team.', '这些帅小伙儿是一个高中篮球队的队员。', 'kglfufw4z8fhfccqnfwkgljpsqecujfq.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1535, 'vitamin', '/ˈvaɪtəmɪn/', 'vitamin.mp3', 'n.维生素', 'i_1_7841_0_3_20150808130044-gigapixel-scale.jpg', 'd_105_7841_0_2_20150809060515.png', 'Fruits such as oranges and grapes are rich in vitamin C.', '橙子、葡萄这类水果富含维生素C。', 'lawcu3j9pk8zf3fdc6779j85rvaw3ylf.mp3', 'vita生命 + min小要素 → 生命要素 → vitamin维生素', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1536, 'volume', '/ˈvɑːljəm/', 'volume.mp3', 'n.音量；数量；容量；册，卷', 'i_1_5051_0_9_151009142130-gigapixel-scale.jpg', '20141014_14_39_23_349_v3.png', 'I turned the volume up to listen to the radio.', '我把收音机音量调大来听广播。', 'b538be48d475dd4bfc559170eacc00ce_15719_1623116917.mp3', 'vol旋转，卷 + ume表物 → 卷起来的东西 → volume卷，册', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1537, 'wide', '/waɪd/', 'wide.mp3', 'adj.宽阔的；广泛的；  adv.尽可能远地', '921cb168ab176fbc33baa9d30da0f0a2_72926_1590480059.jpg', 'd_24_16477_0_3_20150808231358.png', 'The sofa is wide enough for many people.', '这张沙发很宽，足够坐很多人。', 'ffdf11c162374886_1266798140264503970_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
