INSERT INTO `words` VALUES (1539, 'write off', '/raɪt ɔːf/', 'write off.mp3', 'phr.报废', '1b8d5808772537be81797e841c8cdd0c.jpeg', '', 'This car was completely written off.', '这辆车完全报废了。', '956096f82faa0eb77a3f8a5f64d2849c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1540, 'zone', '/zoʊn/', 'zone.mp3', 'n.地带，空间，地区，区域，范围', '950dd05c1315ebcf95ec11c670700f19_66949_1644212246.jpg', 'd_107_7497_0_2_20150809022032.png', 'Our school is in this zone.', '我们学校在这个区域。', 'g7dzd7mbem59d25pagw7svcvb6v2sulv.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1541, 'acquaintance', '/əˈkweɪntəns/', 'acquaintance.mp3', 'n.相识的人，熟人；认识', 'fc4d84994bbaf38fbf0c3010174c703e_110447_1587883431.jpeg', 'd_16_8554_0_2_20150808233228.png', 'He met an old acquaintance at his friend\'s wedding.', '他在朋友的婚礼上遇见了一位老熟人。', '255a1239ae4a1930_1266883487547939478_250207.mp3', 'acquaint熟悉 + ance名词后缀 → acquaintance认识，熟人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1542, 'action on', '/ˈækʃn ɑːn/', 'action on.mp3', 'phr.对……的行动', 'ecbd2760eecc887e699306e5da806da2.jpg', '', 'They are taking action on the environmental problem.', '他们正在对环境问题做出行动。', '3e7cba1f488e69a26fc2021b298c3414_49952_1593575193.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1543, 'active', '/ˈæktɪv/', 'active.mp3', 'adj.积极的，主动的；起作用的，有效的', 'ba421d71e889967b8ccde7dab0b8aaf2_189543_1578568538.jpeg', 'd_24_5002_0_3_20150808223811.png', 'Students should take an active approach to studying.', '学生们应该采取积极有效的学习方法。', '5eb17a366032f3a9_1266883197202770722_250207.mp3', 'act行动 + ive有…...性质的 → active积极的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1544, 'add', '/æd/', 'add.mp3', 'v.加，增加', '15f214334755fb518a799ada14d90113_426860_1609986838.jpg', 'd_24_19023_0_4_20150809000005.png', 'Add some milk to the bowl.', '往碗里加点牛奶。', 'e68265db9a3728d2_1266883005416647476_250207.mp3', 'ad往，到 + d给予 → add加，增加', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
