INSERT INTO `words` VALUES (1546, 'asleep', '/əˈsliːp/', 'asleep.mp3', 'adj.睡着的，睡熟的', '20150528_171820_16_16654-gigapixel-scale.jpg', 'd_24_16654_0_5_20150808231819.png', 'The cat and the dog fell asleep in the bed.', '猫和狗在一张床上睡着了。', 'qufvfz92vwejv2vuhad35wpnm5fd9yzd.mp3', 'a表强调 + sleep睡觉 → asleep睡着的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1547, 'assign to', '/əˈsaɪn tu/', 'assign to.mp3', 'phr.分派给', '7f65fd93c265d21b3d9353e4589c346a.jpg', '', 'The manager assigned him to work on reception. ', '经理指派他去做接待工作。', '2cf6a951c15b34bfe6ebd88d770a486b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1548, 'at hand', '/æt hænd/', 'at hand.mp3', 'phr.在手边， 在附近', '6eb2901a636c3b6395ab07156c472e35.jpg', '', 'He always keeps a dictionary at hand when he writes.', '他写作时手边总备有一本字典。', 'c88281618f75da0473bf95ec2ad8493c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
