INSERT INTO `words` VALUES (1550, 'bible', '/ˈbaɪbl/', 'bible.mp3', 'n.(the Bible)《圣经》；权威书籍', 'i_1_8250_0_2_20150808130532-gigapixel-scale.jpg', 'd_103_8250_0_3_20150809031526.png', 'The Bible is the holy book of the Christian religion.', '《圣经》是基督教的圣书。', 'sa_1_8250_0_2_20150808130532.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1551, 'build up', '/bɪld ʌp/', 'build up.mp3', 'phr.逐步增加（增强），逐渐增进', '3_0_20170723071319_67401_c.jpg', '', 'Lifting weights has built up his strength.', '举重逐步增强了他的力量。', 'us_Lifting_weights_20250212140015375_2ed2149f53243d9c2b9a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1552, 'cancer', '/ˈkænsər/', 'cancer.mp3', 'n.癌症；（迅速蔓延的）恶劣的或危险的事物', '7d57960cfab2e1d1e8a48a8769b84fda_102833.jpg', 'd_24_9183_0_3_20150808230056.png', 'Smoking may cause lung cancer.', '吸烟可能会导致肺癌。', '3d8405d8756f0228750e8c00720174f4_10703_1538466662.mp3', 'canc=kar艰难，严重 + er名词后缀，人或物 → 严重的疾病 → cancer癌症', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1553, 'case', '/keɪs/', 'case.mp3', 'n.箱，盒；容器；套；案件；  v.踩点', 'i_114_17160_0_2_20150809071432-gigapixel-scale.jpg', 'd_94_12031_0_4_20150809005950.png', 'He always takes the black case to work.', '他总是带着个黑箱子去上班。', 'us_He_always_20240702153545039_103773475755fee3ff50.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1554, 'cigarette', '/ˈsɪɡəret/', 'cigarette.mp3', 'n.香烟，纸烟，卷烟', 'dff90fc690534a53e7f48d5e301fdf87_37969_1558774883.jpg', 'd_24_8034_0_4_20150808225401.png', 'Cigarettes are bad for your health.', '香烟对你的健康有害。', 'sa_24_8034_0_4_20150808225401.aac', 'cigar雪茄 + ette小的 → 比雪茄小 → cigarette香烟', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1555, 'comfort', '/ˈkʌmfərt/', 'comfort.mp3', 'v.安慰；使舒适；  n.舒适', 'i_1_8420_0_4_160321100811.jpg', 'd_24_8420_0_4_20150808225703.png', 'The woman tries to comfort her crying daughter.', '那个女人试图安慰正在哭泣的女儿。', 'sa_1_8420_0_4_160321100831.aac', 'com共同 + fort加强 → 精神强大 → comfort安慰', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
