INSERT INTO `words` VALUES (1560, 'decision', '/dɪˈsɪʒn/', 'decision.mp3', 'n.决定', '8db4f560e2eb830c82c945105350f544_88340_1585122790.jpeg', 'd_24_16460_0_4_20150808231326.png', 'Facing three paths in the forest', '面对森林中的三条小道，他决定走左边那条。', '1f70d9844f69372a976f81b01ff16f4c_45758_1585122787.mp3', 'deci决定 + sion名词后缀 → decision决定', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1561, 'deer', '/dɪr/', 'deer.mp3', 'n.鹿（单复数同形）', 'fdb4863ad99c15da6a505bdb8b5601e7_197038_1565693485.jpeg', '20130301_10_58_09_411.png', 'The girl with food was immediately surrounded by deer.', '拿着食物的小女孩被小鹿们迅速围住了。', '8743hmzmcwnveatkgmzk7menxzyjzpey.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1562, 'delegate to', '/ˈdɛlɪˌɡet tu/', 'delegate to.mp3', 'phr. 授权，委派（做）', '75e4be4298d489de520ba65fe6dd6722_91692_1733735659.jpg', '', 'He was delegated to represent the company at the annual conference.', '公司委派他作为代表出席年度会议。', 'ce0bf9a5b41bade530e2971baae7ca5b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1563, 'discover', '/dɪˈskʌvər/', 'discover.mp3', 'v.找到', '93405cfc281e1cb42aca7a56969077b8_81760_1595315173.jpeg', 'd_24_15945_0_3_20150808230928.png', 'The expert discovered a vase from the Tang dynasty.', '这名专家发现了一个唐朝的花瓶。', 'g2u75cmaqtn6aqut7qh22pyldngbp8ge.mp3', 'dis相反 + cover盖 → 把盖揭开 → discover发现', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1564, 'donkey', '/ˈdɔːŋki/', 'donkey.mp3', 'n.驴；傻瓜', '9d787c9485ae35c66a9d58e5af6f7055_112831_1538646553.jpg', '20140929_02_34_16_210_v3.png', 'The donkey is trying to eat a carrot.', '这头驴子正在努力吃一根胡萝卜。', '7aa60274192c470f_1266883374181821206_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1565, 'earth', '/ɜːrθ/', 'earth.mp3', 'n.地球；陆地', 'e438b58bbc31e56cf0e7c88d3f324342_110447_1656918412.jpg', 'd_73_12507_0_4_20150809023309.png', 'This is what the Earth looks like from the outer space.', '这就是地球从外太空看到的样子。', 'us_This_is_20220811094818000_9b21f3615b4f758f562d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1566, 'editor', '/ˈedɪtər/', 'editor.mp3', 'n.（报刊、杂志的）编辑；主编', 'b91d18c9bb7bba6206b4d6fede5141af_89554_1573703373.jpeg', 'd_24_5132_0_4_20150808223938.png', 'The video editor is using special computer software to do his work.', '这位视频编辑正在用特殊的电脑软件工作。', 'us_The_video_20250904095440445_e0cf0db36a3de87532d7.mp3', 'edit编辑 + or表示人 → editor编者，编辑', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1567, 'equality', '/iˈkwɑːləti/', 'equality.mp3', 'n. 同等，平等；【数】等式', 'aee78caa96e0435ed196ec5c64991e9a_95366_1579335714.jpeg', 'd_16_1056_0_7_20150808223336.png', 'This picture shows the equality between men and women.', '这张照片显示了男性与女性的平等。', '4f1b100b2c6aa601accf90bf502efbcc_43078_1579335712.mp3', 'equal相等的 + ity名词后缀 → equality平等', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1568, 'error', '/ˈerər/', 'error.mp3', 'n.错误，过失', 'c_i_wm_20120716_03_08_13_204-gigapixel-scale.jpg', 'd_16_6640_0_5_20150808230854.png', 'If you make an error', '如果你写错了，擦掉重写就好了。', '33074d118e4cc56660ba20d86a5fa0ab_28637_1621924274.mp3', 'err错误 + or行为，状况 → error错误', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1569, 'excited', '/ɪkˈsaɪtɪd/', 'excited.mp3', 'adj.兴奋的；激动的', 'f8b532505eb971f1f992683307ae9c9f_84841_1577951786.jpeg', 'd_24_19120_0_3_20150809000733.png', 'He was excited to win the computer game.', '他因为玩电脑游戏获胜而兴奋不已。', '73ecc1363026a2c4_1266883325994883800_250207.mp3', 'excit使兴奋 + ed形容词后缀 → excited 兴奋的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1570, 'excuse', '/ɪkˈskjuːs/', 'excuse.mp3', 'n.理由，借口（读作/ɪkˈskjuːs/）；  v.原谅', 'a7679d91f86ebaa12465c2eb80349d81_84529_1595469040.jpeg', 'd_95_12616_0_4_20150809012750.png', 'He made up a stupid excuse for not doing homework.', '他为没做作业编了个愚蠢的借口。', '6962b6a55072c3086cdaec6973c9c50c_46496_1595469046.mp3', 'ex远离 + cuse指控 → 逃脱指控 → excuse借口', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1571, 'explore', '/ɪkˈsplɔːr/', 'explore.mp3', 'v.探险', '32be82c6f358a08ef726c028012e9c33_67315_1585381369.jpg', 'd_24_6193_0_3_20150808224519.png', 'They will explore the dark cave.', '他们即将探索这个漆黑的洞穴。', '5sq2dqkwyyrzcvvqujqzgke48dfq8grp.mp3', 'ex出，向外 + plore哭泣，叫喊 → explore探险', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1572, 'farm', '/fɑːrm/', 'farm.mp3', 'n.农场，饲养场；  v.种田，经营农牧业', '4274cd2d834fc22e6327c97b67219275_89470_1577951852.jpeg', 'd_24_19561_0_4_20150809002003.png', 'The farmer keeps a lot of animals on his farm.', '这个农民在农场里养了很多动物。', '21cc6e96aa984115_1266883014976231974_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1573, 'force', '/fɔrs/', 'force.mp3', 'v.强迫；推动；用力移动或强行打开某物；  n.力量；武力；势力', 'd457672372c357e620abf8a08f8e4ac1_101621_1647853537-gigapixel-scale.jpg', 'd_24_16591_0_4_20150808231616.png', 'The child is being forced to have breakfast.', '这个孩子正被迫吃早饭。', 'ebbd14098c768025_1266883378774891008_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1574, 'give off', '/ɡɪv ɔːf/', 'give off.mp3', 'phr.释放', '5_44_190_20170329105452_33316_c.jpg', '', 'The fireplace gives off a lot of heat to keep their feet warm.', '壁炉散发出很多热量，让他们的脚都温暖起来。', 'ae81143b59e531bc3b1c77290f6ea4b7_21205_1626058669.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1575, 'gun', '/ɡʌn/', 'gun.mp3', 'n.枪，炮', '3_0_20160520173048_98283_c-gigapixel-scale.jpg', '20121225_19_28_45_858.png', 'The man looks cool with a gun in his hand.', '这个拿枪的男人看起来太酷了。', '3_0_20160520173048_6110_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1576, 'habit', '/ˈhæbɪt/', 'habit.mp3', 'n.习惯', '20121014_03_37_14_104.jpg', 'd_97_12913_0_5_20150809015852.png', 'Make a habit of washing your hands after using the bathroom!', '要养成上完厕所就洗手的习惯。', 'e563b42e4fc8b406_1266883536659372750_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1577, 'hand', '/hænd/', 'hand.mp3', 'v.递，交', 'dcd80731b162e0ca0b8f0e96329bb59a.jpeg', 'd_24_17932_0_3_20150808233542.png', 'She handed the gift to her friend.', '她把礼物交给了她的朋友。', 'f4de6323881c97e9c19f88a8491ce225.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1578, 'hesitate', '/ˈhezɪteɪt/ ', 'hesitate.mp3', 'v.踌躇；顾虑', '3_0_20170930071303_91472_c-gigapixel-scale.jpg', 'd_1_8256_0_2_20150808130538.png', 'I hesitated when my boyfriend showed me the ring.', '当我男朋友拿出戒指时，我犹豫了。', '6ebd246c3917b3e3_1266883531569933208_250207.mp3', 'hes粘+ itate表动词 → hesitate脚被粘住，犹豫', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1579, 'hospitable', '/ˈhɑːspɪtəbl/', 'hospitable.mp3', 'adj.好客的；有利的', '4637f8fad8bab09603df72c88e0dec73_201895_1569568032.jpeg', '20140911_17_03_04_459_v3.png', 'He was very hospitable to the guests when they came to his house.', '有人来访时，他表现得十分好客。', 'ca38001fe354f2a0c221d7c3a923430c_44302_1569568029.mp3', 'hospit客人 ＋ able形容词后缀，…的 → 待客，好客 → hospitable好客的，招待周到的，殷勤的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1580, 'hostel', '/ˈhɑːstl/', 'hostel.mp3', 'n.旅社，招待所（尤指青年旅社）；临时收容所', 'a2b41b6278c0fdbabb72d2dff2544c9e_168337_1701917787.jpg', '20140807_23_18_16_515_v3.png', 'It was cheaper to stay at the youth hostel.', '住青旅会更便宜。', 'sa_50_19844_0_4_20150809020308.aac', 'host客人 + el表地点 → hostel旅店', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1581, 'idea', '/aɪˈdiːə/', 'idea.mp3', 'n.想法，主意', '3e4302aafcdb90560debcfddbea98caa_83643_1577953784.jpeg', 'd_24_16453_0_4_20150808231259.png', 'He came up with a good idea to solve that problem.', '他想到了一个好主意来解决那个问题。', 'a3a2deb9dcc222a2e8b2d423f3d7e118_38254_1577953782.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1582, 'illustrate', '/ˈɪləstreɪt/', 'illustrate.mp3', 'v.（用示例、图画等）说明，解释', 'i_1_4775_0_7_160201113945-manual-scale.jpg', 'd_1_4775_0_3_20150808123014.png', 'Our manager illustrated the sales with colorful charts.', '我们的经理用一些彩色的图表解释了我们的销售量。', 'f63c6fa9493348b8_1266883526397811286_250207.mp3', 'il=in在内，进入 + lustr照亮 + ate表动词  → 照亮内部（大脑） → illustrate举例说明，阐明', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1583, 'in difficulty', '/ɪn ˈdɪfɪkəlti/', 'in difficulty.mp3', 'phr.遭遇苦难，身处困境', '99b0994aa12e197452f624de4118d9b9.jpeg', '', 'Seeing that he was #In some difficulty#', '看到他处境困难，她主动帮了一把。', '9ae0f4af61f957539ce15987f027a832.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1584, 'inch', '/ɪntʃ/', 'inch.mp3', 'n.英寸；少许，少量；  v.（使）缓慢地移动；使渐进', 'df3f027ed64c3b8decf82814b6d72ba1_68206_1578637633.jpg', 'd_24_16011_0_3_20150808231035.png', 'An inch is about two and a half centimeters.', '一英寸大约是2.5厘米。', '48fdbd5cbf669a40_1266797979493620458_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1585, 'incline', '/ˈɪnˌklaɪn/', 'incline.mp3', 'n.倾斜，斜坡，斜面（读作/ˈɪnˌklaɪn/）；  v.使倾斜，使倾向于（读作/ɪnˈklaɪn/）', 'i_1_4130_0_4_151019151408-gigapixel-scale.jpg', 'd_11_4130_0_2_20150808150416.png', 'The small ball is on an incline and could hit the big ball.', '小球在斜面的一端，可能会撞向大球。', 'us_The_small_20241009155149969_dd02257b4ac58297ff2e.mp3', 'in使 + clin倾斜 + e → incline 倾斜，斜坡', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1586, 'India', '/\'ɪndɪə/', 'India.mp3', 'n.印度', '3_0_20160603100741_6216_c-gigapixel-scale.jpg', 'd_24_17560_0_3_20150808232952.png', 'India has a long history and a rich unique culture.', '印度历史悠久，拥有着丰富且独特的文化。', '3_0_20160603100741_967_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1587, 'innocent of', '/ˈɪnəsnt əv/', 'innocent of.mp3', 'phr.无罪的，清白的', '7ecfa400ee14be7c1e7ad2821f7caef0.jpeg', '', 'The judge ruled that he was innocent of any crime.', '法官判定他没有犯罪。', '731db03d78fc1423948b698170386c87.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1588, 'install', '/ɪnˈstɔːl/', 'install.mp3', 'v.安装，安置', '9df667b0cd94e315f31e42ac0fe04c93_85277_1565343173.jpg', 'd_1_4015_0_2_20150808122232.png', 'The man installed a ceiling fan.', '这个男人把吊扇装上了。', '6c0f3ab1080a1e8a_1266798148428782312_250123.mp3', 'in进 + stall放 → 放进去 → install安装', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1589, 'interpretation', '/ɪnˌtɜːrprɪˈteɪʃn/', 'interpretation.mp3', 'n.口译；理解，解释', 'i_1_7583_0_3_20150808130008-gigapixel-scale.jpg', 'd_108_7583_0_2_20150809043826.png', 'His English-Chinese interpretation is strange; I doubt if it is correct.', '他将英文翻译成了很奇怪的中文，我怀疑他翻得不对。', 'sa_1_7583_0_5_150914160929.aac', 'inter在…之间，相互 + pret预先 + ation名词后缀 → 相互之间预先了解 → interpretation口译；解释', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1590, 'keep up', '/kiːp ʌp/', 'keep up.mp3', 'phr.赶上；保持；不落后于', '966e3c49ff0f87c1f2fd82411aeb12e8_156307_1545460191.jpeg', '', 'The man is so fast that he can keep up with the horse!', '那个人跑得很快，他都快赶上马了。', 'bb09dbcdf221e98c65d12a410f314c7c_36323_1525685596.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1591, 'key', '/kiː/', 'key.mp3', 'n.钥匙；  adj.关键的，主要的', 'b259d2b82ee4c45219aeba9373e4c91b_67854_1577953930.jpeg', 'd_24_17183_0_4_20150808232259.png', 'The man in the white T-shirt is holding his keys.', '穿白色T恤的男人拿着他的钥匙。', 'b6e92d98f966637a_1266763239882468206_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1592, 'large', '/lɑːrdʒ/', 'large.mp3', 'adj.大的；大量的，大规模的', '3bb33430ee5d6ca49b580ddc64b6f1a1_86050_1577954087.jpeg', 'd_24_17931_0_3_20150808233539.png', 'She has a very large cup.', '她有一个非常大的杯子。', 'ae3e274bf00e2898_1266763449640397818_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1593, 'last', '/læst/', 'last.mp3', 'adj.最后的，仅剩下的；最近的，上一个的；  v.持续，坚持；  pron.最后的东西（或人）；  adv.最近，上次', '3_0_20170708102557_27052_c-gigapixel-scale.jpg', '20121225_19_49_07_593.png', 'We need one last piece to finish the puzzle.', '我们只需最后一块图案就能完成拼图。', '7wpjup92pxnnuvajq6h4kzuad4l9upst.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1594, 'leave off', '/liv ɑf/', 'leave off.mp3', 'v.（使）停止', 'leaveoff_8131_20231106_97daaa29.jpg', '', 'If you want to be healthy', '如果你想要健康，就戒烟。', 'sa_11_8131_0_2_20150808174118.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1595, 'let alone', '/let əˈloʊn/', 'let alone.mp3', 'phr.更别说，更不用说', 'dc047c459aa394dab4737a889e5718b9_125131_1669801932.jpg', '', 'His cabin is uninhabitable in summer', '他的小屋连夏天都不好住', 'us_His_cabin_20221130175214576_147ccbae24b0a414e7ce.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1596, 'mainland', '/ˈmeɪnlænd/', 'mainland.mp3', 'n.大陆；  adj.大陆的', '1acbefc891397f236598cefe76d65cb7_117234_1656645731.jpg', '20141015_00_47_54_383_v3.png', 'The mainland of this country is an island.', '这个国家的大陆是一个岛屿。', 'us_The_mainland_20220701112220658_cee2bbb6e38d976d4885.mp3', 'main主要的 + land陆地 → mainland大陆', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1597, 'motivate', '/ˈmoʊtɪveɪt/', 'motivate.mp3', 'v.激励；成为……的动机；促进；促使；激发', 'af53e72dbd04dd087941944a1f71c29e_151127_1543904448.jpeg', 'd_107_5480_0_2_20150809012749.png', 'Praise from a teacher can always motivate students.', '来自老师的夸赞经常能激励学生。', '489f1f3fbf6d5974a3dfd91d2145e9b1_41275_1570866476.mp3', 'motiv运动的 + ate表动词 → motivate促动；激励，激发', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1598, 'name', '/neɪm/', 'name.mp3', 'v.给……取（或命）名', 'e649b6db121a60cc128765146081221a_83981_1590140731.jpg', 'd_24_17940_0_3_20150808233622.png', 'What should we name our new baby?', '我们应该给我们的新宝宝取什么名字？', '5638b78653977c46_1266763400121330652_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1599, 'national', '/ˈnæʃnəl/ ', 'national.mp3', 'adj.国家的，民族的；  n.（某国的）公民', 'i_13_17273_0_2_20150808204655-gigapixel-scale.jpg', '20121225_18_22_29_947.png', 'Baseball is the national game of the U.S.', '棒球是美国的国民运动。', 'sa_13_17273_0_2_20150808204655.aac', 'nat出生的 + ion名词后缀 + al…的 → 出生地的 → national国家的，民族的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1600, 'obesity', '/oʊˈbiːsəti/', 'obesity.mp3', 'n.肥胖', '031a83cf0746006be168e4934e2e4166_157047_1587636248.jpeg', '', 'The man suffers from obesity and lives an unhealthy lifestyle.', '那个患有肥胖症的男人过着一种不健康的生活。', '1074b0ff5d8e88c3ba6891ae3aa4964d_47394_1587636245.mp3', 'obes肥胖的 + ity 指具备某种性质 → n.肥胖，肥大', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1601, 'official', '/əˈfɪʃl/', 'official.mp3', 'n.官员；  adj.公务的，公职的；官方的，正式的', '485c50d49a6913f393b7648ce543f9b5_47091_1653966933.jpg', 'd_24_8120_0_4_20150808225516.png', 'The government official signed an important document at his desk.', '政府官员在桌上签署了一个重要文件。', 'df3c8452aea46b81_1266883522808404546_250207.mp3', 'offic官方的 + ial属于……的 → 官方的，法定的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1602, 'opponent', '/əˈpoʊnənt/', 'opponent.mp3', 'n.对手，敌手，对抗者；  adj.对立的；敌对的', 'i_1_6294_0_4_150919105803-gigapixel-scale.jpg', 'd_107_6294_0_2_20150809015521.png', 'The boxer punched his opponent severely！', '这个拳击手痛击对手！', '29897bfdca40c300_1266883493672671792_250207.mp3', 'op反 + pon放置 + ent形容词后缀 → 反着放 → 对立的；对手', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1603, 'patience with', '/ˈpeɪʃns wɪð/', 'patience with.mp3', 'phr.对……有耐心', '006f4466349489fc64c9a2a8c8a657b1.jpeg', '', 'Compared with others', '与其他人比起来，他对他的话痨朋友更有耐心。', 'us_Compared_with_20240428112440500_a45a4d02b031c17e826d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1604, 'permission', '/pərˈmɪʃn/ ', 'permission.mp3', 'n.允许，同意', '59731a6372be3a6272adbfbd30ca270c_98091_1583140176.jpeg', 'd_107_8292_0_2_20150809023051.png', 'My mother gave me her permission to go to the party.', '我母亲允许我去参加聚会。', '08040db619dce3e0_1266883320614595406_250207.mp3', 'permi=permit允许 + ssion名词后缀 → permission允许，同意', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1605, 'piece together', '/pis təˈɡɛðɚ/', 'piece together.mp3', 'phr.拼合(拼凑)', '3e2fc8280df7cba5cf50d98dc0a01e55.jpg', '', 'Piece together the puzzle to see the whole picture.', '把拼图拼好来看完整的图像。', 'us_Piece_together_20241009151201551_2ddde4ab4863836d32bd.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1606, 'point out', '/pɔɪnt aʊt/', 'point out.mp3', 'phr.指出', 'd798f302cf123fe8e2a39044023e33e7_80376.jpg', '', 'He #points out# a mistake in the book.', '他指出书中的一个错误。', 'e3795268fbb26c61_1266883625435683358_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1607, 'point to', '/pɔːɪnt tu/', 'point to.mp3', 'phr.表明，显示', '3_0_20170721071414_27372_c.jpg', '', 'Her expression points to the fact that she receives good news.', '她脸上的表情表明她收到了好消息。', '5439b2470c1d1f666796543acea61ac9_18853_1540627053.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1608, 'poor', '/pɔːr/', 'poor.mp3', 'adj.贫穷的', 'i_13_17981_0_2_20150808205214-gigapixel-scale.jpg', 'd_24_17981_0_4_20150808233922.png', 'The poor homeless man begged for money on the street.', '这个可怜的无家可归的男人在街上乞讨。', 'sa_13_17981_0_2_20150808205214.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1609, 'progressive', '/prəˈɡresɪv/', 'progressive.mp3', 'adj.逐步的，渐进的；  n.进步人士', 'i_1_6280_0_4_20150808124937-gigapixel-scale.jpg', 'd_107_6280_0_2_20150809015454.png', 'He has made progressive improvements in his grades.', '他在学习成绩上步步高升。', 'e517aecd7a4de936_1266883617277500096_250207.mp3', 'pro向前 + gress走 + ive表形容词 → progressive进步的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1610, 'recover from', '/rɪˈkʌvər frəm/', 'recover from.mp3', 'phr.从……中恢复', '628d2bc994a9051047a7ac8e0ae0c20c.jpeg', '', 'He has fully recovered from the virus.', '他已经彻底从病毒感染中康复了。', '3d8ed9cc582064c1bb1cd0f5042fe235.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1611, 'refrigerator', '/rɪˈfrɪdʒəreɪtər/', 'refrigerator.mp3', 'n.冰箱，冷藏库', '3_0_20160521111047_74231_c-gigapixel-scale.jpg', 'd_24_9340_0_3_20150808230200.png', 'Mom put a pot of soup into the refrigerator.', '妈妈把一锅汤放进了冰箱。', '3_0_20160521111047_92667_c.aac', 're加强意义 + friger冷的 + (at)or表示物 → 可以重复使食品冷冻的东西→ refrigerator冰箱，冷藏库', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1612, 'register with', '/ˈrɛdʒɪstər wɪð/', 'register with.mp3', 'phr.向……登记', 'aa16171f8aba4a17c83bfa40fe333563.jpeg', '', 'People are required to take their insurance card with them when registering with a doctor.', '人们被要求带上保险卡，才能在医生那里注册登记。', 'f26512ba3373b8967d144eced625ca12.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1613, 'reject', '/rɪˈdʒekt/', 'reject.mp3', 'v.拒绝，拒绝接受；抵制', '158e2ec655b45c4dcd613ba9fd5d6bfc_102615_1733118607.jpg', 'd_16_5683_0_2_20150808225702.png', 'The girl rejected an incoming call from an unknown number.', '这个女孩拒绝了一个未知号码打来的电话。', 'us_The_girl_20241202135010509_9d9d989cc5a69ec55c4a.mp3', 're回 + ject投掷，扔 → 扔回来 → reject拒绝', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1614, 'resistant to', '/rɪˈzɪstənt tu/', 'resistant to.mp3', 'phr.对...有抵抗力的，（尤指对变化和新思想）抗拒的', 'f02b5b0e13bd775c48c502f52fb7bf31.jpeg', '', 'Gene editing has made the apple more resistant to the disease.', '基因编辑增强了苹果对这种病害的抵抗力。', 'f83a135980269f59e751dc73bffc766d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1615, 'sauce', '/sɔːs/', 'sauce.mp3', 'n.酱，调味汁', '5ebc7f0321c510beb441a1f078012a7a_99263_1579334314.jpeg', '20141009_05_23_47_502_v3.png', 'Each bowl on the table contains a different sauce.', '桌上的每个碗里都装着不同的酱汁。', '7g7r7xxjcvwe7ufzkwtdraryeu6k3y64.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1616, 'save', '/seɪv/', 'save.mp3', 'v.储蓄；节省；  n.（守门员的）救球', '1425952772230-gigapixel-scale.jpg', 'd_24_17193_0_4_20150808232328.png', 'You have to try to save money for an emergency.', '你应该试着存点钱，以备不时之需。', '166412c7ad6172179e56f0a4a0a5e236_16660_1647498369.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1617, 'seed', '/siːd/', 'seed.mp3', 'n.种子，籽；种子选手', '10cf780298088e2294e2b77a070dc31d_84971_1577956145.jpeg', 'd_24_6286_0_3_20150808224551.png', 'The bowl is filled with pumpkin seeds.', '碗里装满了南瓜种子。', '58ccb78e5d1b5dc4371eaf6e75d6d64d_30910_1577956142.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1618, 'select from', '/sɪˈlekt frəm/', 'select from.mp3', 'phr.从……中挑选', 'e718d06d64485dec99f962aade130730.jpeg', '', 'He was selected by the company from the group of applicants.', '他是公司从一群求职者中挑选出来的。', '94813d6612dc039a4559804d64522fe8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1619, 'share with', '/ʃer wɪð/', 'share with.mp3', 'phr.与……分享', '07222b63ce951c23ef79e34d49214e2f.jpeg', '', 'People can share files with each other using their mobile phones.', '人们可以通过手机互相共享文件。', 'us_People_can_20241009153928961_72c680bca5685e33cafa.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1620, 'specification', '/ˌspesɪfɪˈkeɪʃn/', 'specification.mp3', 'n.规格，具体要求', '435899a406413c76f6814fdc6aa78310_75186_1678698103.jpg', '', 'The construction of the house complies with certain specifications.', '这座房子是按规格建造的。', 'sa_2_4105_0_4_151225171636.aac', 'specific具体的 + ation表名词 → specification具体说明', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1621, 'stereo', '/ˈsterioʊ/', 'stereo.mp3', 'adj.立体声的；  n.立体声（装置）', '3_66_20170717102708_6316_c-gigapixel-scale.jpg', 'd_1_5297_0_2_20150808123739.png', 'Music fans love listening to music on a hi-fi stereo system.', '音乐爱好者喜欢用高保真立体声设备听歌。', 'us_Music_fans_20241009155600861_fe29e1e3d80b263a4e26.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1622, 'subway', '/ˈsʌbweɪ/', 'subway.mp3', 'n.地铁', '60cb7c8f5a9c3cc5c5311d4f511563d0_190850_1588090849.jpeg', 'd_24_9483_0_3_20150808230236.png', 'He takes the subway to work every day.', '他每天乘地铁上班。', 'hcvussb99kpcv734ddmjnvclvrm84eab.mp3', 'sub在下 + way道路 → subway地下通道，地铁', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1623, 'suggestion', '/səˈdʒestʃən/', 'suggestion.mp3', 'n.建议，意见；细微的迹象', '55b44972c89127dcd8ea81c2c7c02255_97869_1595471877.jpeg', 'd_24_2480_0_4_20150808223229.png', 'The shopping guide gives her some suggestions about the skirt.', '导购给了她一些选裙子的建议。', '29e297d1a7179ba1_1266883485391280734_250207.mp3', 'sug=sub在下面 + gest带来，产生 + ion表名词 → 从下面产生的建议 → suggestion建议，意见', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1624, 'tank', '/tæŋk/', 'tank.mp3', 'n.大容器，大罐', 'i_1_7964_0_6_151019155603-gigapixel-scale.jpg', '20141009_02_38_21_459_v3.png', 'The man is checking the large yellow tank.', '这个人正在检查这个黄色的大罐子。', 'sa_1_7964_0_6_151102171859.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1625, 'temple', '/ˈtempl/', 'temple.mp3', 'n.庙宇，神殿；太阳穴', '3_0_20160720070810_91866_c-gigapixel-scale.jpg', '20121225_19_45_42_358.png', 'People usually go to temples to pray for good fortune.', '人们经常去寺庙祈求好运。', '55bcf6f2f13df4fb_1266883626830944834_250207.mp3', 'tem切割，隔断 + ple → 被独立隔断的地方 → temple庙宇', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1626, 'territory', '/ˈterətɔːri/ ', 'territory.mp3', 'n.地区，领土；属地', 'i_1_8208_0_3_20150808130459-gigapixel-scale.jpg', '3ded10992e6b801eb993bba3caad4b29_26534_1539341213.png', 'The dog\'s pee helps to mark its territory.', '狗狗通过撒尿来标记自己的领土。', 'a9b12a8249e0cf6b56eec2c7624b2610_23152_1571218754.mp3', 'territ=terr土地 + ory场所、范围 → 地的范围 → territory领土', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1627, 'thick', '/θɪk/', 'thick.mp3', 'adj.厚的；稠的，浓的', 'edfdb6d1ea7b2b05055860b799fb45e7_96591_1736314901.jpg', 'd_24_17336_0_4_20150808232723.png', 'The study material for the final exam is surprisingly this thick!', '期末考试要复习的资料居然有这么厚！', 'rtkhj88frzrbjp2ddd4g77reuuhe358a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1628, 'thirsty for', '/ˈθɜːrsti fɔːr/', 'thirsty for.mp3', 'phr.渴望 ...', '1f749a05f483269e2d716d4679aa516f.jpeg', '', 'Despite already having a PhD', '尽管已经有了博士学位，他仍然渴望学习更多的知识。', '51b6eef5d5b451f6a8000e5e166b9d52.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1629, 'time', '/taɪm/', 'time.mp3', 'n.时间；（完成竞赛）所用的时间；  v.安排……的时间；  adj.时间的', '10333cd6781f2dac4c13caae6ef876da_63286_1736821645.jpg', 'd_24_17654_0_4_20150808233158.png', 'Look at the time! I\'m late again! My boss is going to kill me.', '看看时间！我又迟到了！我老板会杀了我的。', '7u6e9egykmwgpdr4mkt5ngw7x4lxqz9z.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1630, 'tin', '/tɪn/', 'tin.mp3', 'n.罐头', 'i_114_5063_0_2_20150809063853-manual-scale.jpg', 'd_105_5063_0_2_20150809054403.png', 'The kids like using tins as telephones.', '孩子们喜欢拿罐子当电话。', 'sa_114_5063_0_2_20150809063853.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1631, 'transport', '/trænsˈpɔrt/', 'transport.mp3', 'v.运输，运送；  v.使产生身临其境的感觉；  n.运输工具', 'd659bbcd3ff8248fd33603f5de06bc45_196469_1605146466.jpg', 'd_16_8377_0_2_20150808232919.png', 'Airplanes', '飞机、轮船、火车和卡车是运输货物的方式。', '4a165afd840277b7_1266883616083782570_250207.mp3', 'trans转移 + port运 → transport运输', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1632, 'tray', '/treɪ/', 'tray.mp3', 'n.盘，碟，托盘', 'i_1_6683_0_2_20150808125344-gigapixel-scale.jpg', 'd_1_6683_0_2_20150808125344.png', 'He brought three glasses of water on a tray.', '他用托盘端过来三杯水。', 'sa_1_6683_0_2_20150808125344.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1633, 'unemployment', '/ˌʌnɪmˈploɪmənt/', 'unemployment.mp3', 'n.失业；失业人数', '3_0_20160528173446_12940_c-gigapixel-scale.jpg', 'd_107_5030_0_2_20150809011332.png', 'He lost his job in the wave of unemployment.', '在失业浪潮中，他丢掉了工作。', '3_0_20160528173446_3626_c.aac', 'un不 + employ雇佣 + ment表示行为、行为的过程或结果 → unemployment失业', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1634, 'universal', '/ˌjuːnɪˈvɜːrsl/', 'universal.mp3', 'adj.普遍的，全体的；广泛适用的；  n.普遍原则', '1423912179481-gigapixel-scale.jpg', 'd_16_7152_0_5_20150808231556.png', 'Electronic devices such as cellphones are universal now.', '如今像手机这样的电子设备已经得到了普及。', '82310214800d1f061cf404df125bb8d5_49712_1597716805.mp3', 'uni一个 + vers=versus转变 + al具有...性质的 → 变成一个的 → universal普遍的，全体的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1635, 'urgent', '/ˈɜːrdʒənt/', 'urgent.mp3', 'adj.急迫的', 'i_103_8031_0_3_20150809030955-gigapixel-scale.jpg', 'd_16_8031_0_2_20150808232435.png', 'The cat’s most urgent need now is to pee.', '这只猫现在迫切需要上厕所。', 'us_The_cats_20250106123131410_ef5fa4aeee34bdb776d5.mp3', 'urg紧急 ＋ ent具有...性质的 → urgent紧急的；强求的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1636, 'vehicle', '/ˈviːəkl/', 'vehicle.mp3', 'n.车辆', '2c7266c94054007fab3b4110c1361ae2_89216_1566893876.jpg', 'd_24_3918_0_3_20150808223410.png', 'The vehicle drove off with a container.', '那辆车载着一个集装箱开走了。', 'us_The_vehicle_20240914135323697_99a5de08b1e298de26e0.mp3', 'veh带来 + icle=le表名词 → 开车把人带来 → vehicle车辆，机动车', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1637, 'venture', '/ˈventʃər/', 'venture.mp3', 'v.冒险；  n.（商业）冒险', 'i_1_4025_0_5_150919160438-gigapixel-scale.jpg', '20130510_18_19_54_110.png', 'The boys venture deep into the forest.', '男孩们深入森林冒险。', 'sa_1_4025_0_7_150923124637.aac', 'vent来 + ure表名词 → 来冒险一试 → venture冒险', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1638, 'watch out for', '/wɑːtʃ aʊt fɔːr/', 'watch out for.mp3', 'phr.密切注视，当心，提防', '881643163c69457b8cadc696785eb458_167950.jpg', '', 'Watch out for the banana skin!', '小心踩到地上的香蕉皮！', '2d8f17eab0ccce3e2d074f2069c994b8_26215.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1639, 'wave', '/weɪv/', 'wave.mp3', 'n.海浪，波浪；挥手；  v.挥手，招手', 'i_1_7960_0_4_150917172622-gigapixel-scale.jpg', 'd_24_7960_0_4_20150808225308.png', 'The waves are washing off the drawing on the beach.', '海浪就快把海滩上的画冲掉了。', 'rl6a5jca65kstge4mz77384u4kwr4vdu.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1640, 'wet', '/wet/', 'wet.mp3', 'adj.湿的；  v.把……弄湿', 'ebe8b98bf57077de0d9ae47dcdaece02_106418_1724989850.jpg', '20121225_20_04_26_333.png', 'He got wet because of the rain.', '因为下雨，他被淋湿了。', 'c31ea6a3dc74d16b_1266763449783900920_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1641, 'whisper', '/ˈwɪspər/', 'whisper.mp3', 'v.小声说，耳语，低语；低声低语地讲，悄悄地说；  n.私语', 'ba6c97bf552eff16fffc0d5de85f25bc_179878_1538641625.jpg', 'd_16_8021_0_2_20150808232422.png', 'The little boy is whispering something to his grandfather.', '这个小男孩正和他的爷爷说悄悄话。', '3f74a5614d4c69a0_1266883485246860092_250207.mp3', 'whisp轻语 + er表拟声动作 → whisper低语，作沙沙声', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1642, 'with the exception of', '/wɪð ðə ɪkˈsepʃən əv/', 'with the exception of.mp3', 'phr.除...之外', '3673069a030bf9f9703b4507e3861dc6.jpeg', '', 'All of these fruit are orange', '除了苹果是绿色的，所有的水果都是橙色的。', '54159b8ed031f04ddb9df6cd5707229c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1643, 'workshop', '/ˈwɜːrkʃɑːp/', 'workshop.mp3', 'n.车间，工场，工作室', 'a7cf9bd47dc968f7ac25d894dc11162e_63409_1565706178.jpg', '20141011_16_53_14_816_v3.png', 'I left my car at the workshop for repair.', '我把我的车留在车间修理。', 'lavsjdzkvruwdx3tswqhtkvq4h2vzkfz.mp3', 'work工作 + shop工厂 → workshop车间', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1644, 'worry', '/ˈwɜːri/', 'worry.mp3', 'v.（使）焦虑，（使）烦恼；  n.烦恼，焦虑，担忧', 'i_24_18112_0_6_151128140525-gigapixel-scale.jpg', '20121225_19_08_10_923.png', 'Being in the hospital makes him worry about money.', '在医院住院让他很担忧钱的问题。', 'sa_24_18112_0_6_151221001115.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1645, 'absent from', '/ˈæbsənt frʌm/', 'absent from.mp3', 'phr.缺席', '2da01f21efb536b83a67add9b5b8345c.jpeg', '', 'He was a little worried about his colleague who was unexpectedly absent from work.', '他的同事突然缺勤了，这让他有些担心。', 'c08b642b981fa405a9a866d75e46d315.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1646, 'acquire', '/əˈkwaɪər/', 'acquire.mp3', 'v. （通过努力、能力）获得；学到；得到', 'cbff097644a425c4a18b4d862a98f0e5_107084_1701159927.jpg', 'd_107_5109_0_2_20150809011548.png', 'The little boy acquired knowledge of the universe from observing.', '小男孩通过观察学到了关于宇宙的知识。', 'us_The_little_20231128162554865_b36454ed46bef7079b72.mp3', 'ac加强 + quir寻求，询问 + e → acquire取得，学到', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1647, 'admission of', '/ədˈmɪʃn əv/', 'admission of.mp3', 'phr.承认……', '98afb98fe804cec6c6a3cbd6e33202b4.jpg', '', 'She gave her sister an admission of guilt for breaking the vase.', '她向姐姐承认是她打碎了花瓶的错误。', 'us_She_gave_20241009155213327_5a11cabb16b8bd9b020e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1648, 'age', '/eɪdʒ/', 'age.mp3', 'n.年龄；  v.（使）变老', '3_0_20170703171757_27444_c.jpg', 'd_24_19077_0_4_20150809000346.png', 'These are people of different ages.', '这些是不同年龄段的人。', '3_0_20170703171757_27721_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1649, 'all of a sudden', '/ɔːl əv ə ˈsʌdn/', 'all of a sudden.mp3', 'phr.突然，冷不防', '6f03097519ae43117fd352596b1f2ac1.jpeg', '', 'All of a sudden', '一只猫突然跳出来，吓了他一跳。', 'ba036b3138b2b0044e6dfc01b0297614_44384_1596771761.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1650, 'appetite for', '/ˈæpɪtaɪt fɔːr/', 'appetite for.mp3', 'phr.对……的欲望', 'eed767ef3b05c1a98ffb610e7ee3a326.jpeg', '', 'The little boy has a strong appetite for acquiring knowledge. ', '这个小男孩有强烈的求知欲。', '0dce46c6d880531a766e1d6b31221494.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1651, 'apply to', '/əˈplaɪ tu/', 'apply to.mp3', 'phr.运用于', '8f4e9cdc87ecbb18ed049d561a54f1a8.jpg', '', 'He applied the principle of the lever to move the large stone.', '他运用杠杆原理来移动那块大石头。', 'c3807f3e877c0911d14d53abf6624209.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1652, 'appropriate', '/əˈprəʊpriət/', 'appropriate.mp3', 'adj.合适的，适当的；  v.挪用；拨款；私占', '3d31f05fcf9f935a788e6af62c1d194a_68237_1701051212.jpeg', '20130307_16_02_59_289.png', 'We should connect the appropriate puzzles into a whole.', '我们应该将适当的拼图拼成一块。', 'us_We_should_20231127101509738_a681160b86a529541167.mp3', 'ap=ad到 + propri正确的 + ate形容词后缀 → appropriate合适的，适当的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1653, 'ashamed of', '/əˈʃemd ʌv/', 'ashamed of.mp3', 'phr.对……感到羞耻，惭愧，难为情', '6e9bac97997ccd20a2c789569d5f488d.jpeg', '', 'He was ashamed of himself for getting the lowest score in the exam.', '他因考试得了最低分而感到羞愧。', '3e397490e9b15cf36d216933bcbb2498_26847_1620813123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1654, 'at first sight', '/æt fɜːrst saɪt/', 'at first sight.mp3', 'phr.乍一看', '4cc040907d30029ed0997744a628f810.jpg', '', 'This math problem looks easy at first sight', '这道数学题乍一看很容易，但实际上很难。', 'bf304380f65802b77b21c7664afb234f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1655, 'be disappointed with', '/bi ˌdɪsəˈpɔɪntɪd wɪð/', 'be disappointed with.mp3', 'phr.对……失望', '59c7dc8a45d60d2fbad6e5f7dca9f524.jpeg', '', 'He\'s so disappointed with his performance in the race. ', '他对自己在比赛中的表现感到很失望。', 'ebdf2ba5e7a69b4e80c9ab9aaa3d3459_49184_1593574409.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1656, 'bend', '/bend/', 'bend.mp3', 'v.（使）弯曲，把...弄弯；  n.弯曲，弯曲处', '87f1ea5f80e0ed5d1b8bc1bf836f7cbe_22918_1565684746.jpg', 'd_16_7280_0_2_20150808231741.png', 'First bend to the right', '先向右弯曲，再向左弯曲。', 's576dkh8m3za6q4safyd5yzyb8zuvb2q.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1657, 'blend', '/blend/', 'blend.mp3', 'v.混合；把……混成一体；  n.混合物', 'i_1_5291_0_6_150924173848-gigapixel-scale.jpg', '20141014_02_49_39_414_v3.png', 'Blend the flour and the water with a spoon.', '用勺子把面粉和水混到一起。', '9b2ffb021268121ccee1ec2dbedb4f51_22518_1597134686.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1658, 'boring', '/ˈbɔːrɪŋ/', 'boring.mp3', 'adj.无聊的，乏味的；令人厌烦的，令人讨厌的；单调的', '7e9ce69461cbc5ce891fd3b8dcd7a8dc_126377_1701768753.jpeg', 'd_16_17116_0_4_151204221025.png', 'I\'ve done my boring homework — now can I go outside and play?', '我已经完成无聊的作业了，现在我可以出去玩了吗？', 'sa_1_17116_0_2_20150808132321.aac', 'bor无聊 + ing名词后缀，表状态 → boring令人厌烦的，乏味的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1659, 'both', '/boʊθ/', 'both.mp3', 'pron.两者（都）；  conj.既…且…；  det.两者的；两个', 'bab4bbff71a7630ff5fc965ae616839c_65753_1753844500.jpg', '', 'Both of them are outstanding.', '他们两个人都很优秀。', '3_0_20170615071141_88058_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1660, 'burden', '/ˈbɜːrdn/', 'burden.mp3', 'n.负担；  v.使负重，装载；烦扰', 'ea23deec84088b4ca96f9f5a34652da0_159908_1538714730.jpg', '20141011_04_37_35_995_v3.png', 'His working burden is too heavy', '他的工作负担太沉重了，让他不得不投降。', 'c9d1e31d17d404ba08a773a8d43fac60_19951_1538714745.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1661, 'character', '/ˈkærəktər/', 'character.mp3', 'n.角色；品质', 'f69de9850138a1276283760f14c12a20_562201_1712812758.jpg', 'd_24_7111_0_3_20150808224937.png', 'He dressed up as a character from a classic fairy tale.', '他打扮成了经典童话故事中的角色。', 'us_He_dressed_20240411131928904_5a8a49c8339c3f54d382.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1662, 'consult with', '/kənˈsʌlt wɪð/', 'consult with.mp3', 'phr.请教', '8861b6562b3266ca83aa6f775f113a4e.jpg', '', 'The businesswoman is consulting with the expert about whether to enter this market.', '女商人正在和专家商议是否进入这个市场。', '526780c569911a4a597234ee8ca57a11.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1663, 'continent', '/ˈkɑːntɪnənt/', 'continent.mp3', 'n.大陆，陆地，洲', '2cd98027c227fe51e645af5bf43adf8d_231155_1656647049.jpg', '20130105_10_20_34_839.png', 'The continents were closer to each other in the past.', '在过去，各大洲之间的距离都比较近。', 'ffcf40420f80fc5d_1266798140433980072_250123.mp3', 'con共同 + tin握，持 + ent名词后缀：物 → 保持连在一起的陆地 → continent大陆，陆地，大洲', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1664, 'convenience', '/kənˈviːniəns/', 'convenience.mp3', 'n.方便；便利设施', '158a080d6e6d69f804963988212268b0_121600_1695180225.jpg', 'd_107_5486_0_2_20150809012801.png', 'We have provided seats for the convenience of our customers. ', '为方便顾客我们备有座位。', 'us_We_have_20230920112350201_9e58bab6eae6fd550c31.mp3', 'con全部 + veni来 + ence表名词 → 全部能来没有障碍 → convenience方便', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1665, 'copy', '/ˈkɑpi/', 'copy.mp3', 'v.抄写；  n.副本，拷贝', '4e36379fdd5f1ff70f8836e354b39eab.jpeg', 'd_24_17195_0_4_20150808232330.png', 'He is copying the picture from the book.', '他正在临摹这本书上的图画。', 'a886ca1de7b08c6de4e238a4a84b0006.mp3', 'co和，与 + py权力，财富，资源 → copy抄写', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1666, 'creative', '/kriˈeɪtɪv/', 'creative.mp3', 'adj.有创造力的', 'cd432016eb358d407b3211e9ddd4d868_179092_1579337553.jpeg', 'd_1_5794_0_2_20150808124420.png', 'She is a very creative person', '她是一个很有创造性的人，尤其是画画的时候。', 'xdz226g3psnf58gn5fxcja36ww4hvyev.mp3', 'cre增长，产生 + ative形容词后缀，具有……性质的 → creative有创造性的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1667, 'daily', '/ˈdeɪli/', 'daily.mp3', 'adj.每日的，日常的；  n.日报', 'i_1_9161_0_2_20150808131246-gigapixel-scale.jpg', 'd_24_9161_0_3_20150808230047.png', 'I like to read the daily paper every morning.', '我喜欢在每天早上读日报。', 'sa_1_9161_0_2_20150808131246.aac', 'dai日子，白天 + ly副词后缀 → daily每日的，日常的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1668, 'dangerous', '/ˈdeɪndʒərəs/ ', 'dangerous.mp3', 'adj.有危险的，不安全的', 'b451febba1d22985ebac99e3040d9a5f_116547_1590137344.jpg', 'd_24_16064_0_3_20150808231118.png', 'It\'s very dangerous to open the car door without looking back.', '不看后面就打开车门是很危险的。', '7tlsak9zuhxvpbvafjzbwcenv3x2bugm.mp3', 'danger危险 + ous……的 → 有危险的 → dangerous危险的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1669, 'date', '/deɪt/', 'date.mp3', 'n. 日期，日子；  v.给……注明日期', 'ff93aca8ce4748e1203330b0caba4197_101335_1574841290.jpg', '20130130_16_27_01_86.png', 'What\'s the date today?', '今天是几号？', 'e4b155c60ccd34b5_1266763449668447228_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1670, 'deep', '/diːp/', 'deep.mp3', 'adj.深的；  adv.深深地', '20120924_03_29_43_89-gigapixel-scale.jpg', 'd_93_12352_0_4_20150809002004.png', 'No one has found the ship\'s treasure because it lies deep under the sea.', '没有人能找到船里的宝藏，因为它处于大海中很深的地方。', '280f9036bf9e163d9f35f4eb681439d1_22929_1640588221.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1671, 'defense', '/dɪˈfens/', 'defense.mp3', 'n.防御，防护', '5e9b62487e44d23003dc93b87a8f620a_51282_1584500750.jpeg', 'd_24_7052_0_3_20150808224915.png', 'The iron fence built by the shepherd is a great defense against the wolf.', '牧羊人建造的铁栅栏可以有效地防狼。', '5dvdv9sfxa7tvnpkpyye66hvzw6dychp.mp3', 'de去掉 + fens打击 + e → 去掉打击 → 打退敌人 → defense保卫', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1672, 'derive', '/dɪˈraɪv/', 'derive.mp3', 'v.源自；获得；得自', 'f4299d22187364031bb33934da7d862a_85187_1584008087.jpeg', 'd_107_5161_0_2_20150809011749.png', 'The English word teacher derives from the root word teach.', '英文单词“teacher”一词来源于词根“teach”。', 'd207b35f9a9a6e8a6c005d9f726e4337_21048_1596859328.mp3', 'de离开 + riv河流 + e → 派生，得出', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1673, 'dessert', '/dɪˈzɜːrt/', 'dessert.mp3', 'n.餐后甜点', 'i_13_7295_0_6_160105190707-gigapixel-scale.jpg', 'd_24_7295_0_3_20150808225110.png', 'I’d like to have some dessert with a cup of tea after dinner.', '吃完晚饭后，我还想吃些甜点、喝杯茶。', '29971b0ee506471f_1266763404053338694_250117.mp3', 'des去掉，取消 + sert服务 → 停止正餐服务，上甜点 → dessert甜点', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1674, 'diary', '/ˈdaɪəri/', 'diary.mp3', 'n. 日记', '12ed311d6854d3d017c7fd1637761be0_47740_1656985158.jpg', 'd_13_6251_0_2_20150808190140.png', 'The girl keeps a diary every day.', '这个女孩每天都写日记。', '86d5f80a32540b92_1266883003114609166_250207.mp3', 'di日子 + ary表名词 → diary日记', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1675, 'different', '/ˈdɪfrənt/', 'different.mp3', 'adj.分别的，不同的', 'i_16_17487_0_4_151123145002-gigapixel-scale.jpg', 'd_100_12403_0_4_20150809032447.png', 'The red tomato looks so different from others.', '红色的西红柿看起来与其他的如此不同。', 'nezrgr4a43xfluwq9muph7cjausew9ww.mp3', 'differ相异 ＋ ent...的 → 相异的 → different不同的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1676, 'direction', '/dəˈrekʃn/  /daɪˈrekʃn/', 'direction.mp3', 'n.方向，方位', 'b278e0a49dfc32672d53725fa8108ef8_101683_1587434094.jpeg', 'd_24_7104_0_3_20150808224928.png', 'There are two different directions', '这里有左和右两个不同的方向。', '6w4bz3ysezgyvgajyx6gxy47sxmszbws.mp3', 'di通过 + rect正，直 + ion名词后缀 → 通过正确的道路 → direction指示，指引，说明，指导', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1677, 'drawing', '/ˈdrɔːɪŋ/', 'drawing.mp3', 'n.绘图，图样', '1426145616073-gigapixel-scale.jpg', 'd_109_8266_0_2_20150809055456.png', 'That\'s a simple drawing of a big head man.', '那是一张简笔画，画的是一个大头男人。', 'd932b937934932b6_1266763315456531140_250117.mp3', 'draw画 + ing名词后缀 → 画画 → drawing图画', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1678, 'earnings', '/ˈɜːrnɪŋz/', 'earnings.mp3', 'n.工资；收入；收益', '6f92b6b7b5f396c1f7c2d130a2f375b9_113300_1544584495.jpg', '', 'A rise in his online business earnings made him excited.', '网络业务收入的增长让他兴奋不已。', '893c5604ec0a036cd9c769b7cc458410_18070_1544584512.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1679, 'embarrassed', '/ɪmˈbærəst/', 'embarrassed.mp3', 'adj.尴尬的，窘迫的，觉得难堪的', 'e2cf41168c5100e8889c0c38aabd196f_185002_1588088278.jpeg', '', 'The student is very embarrassed about being disciplined in front of his classmates.', '这名学生因为在同学面前受到训诫而感到十分尴尬。', 'e18a6b83b0e86818_1266883113962744748_250207.mp3', 'em使…进入状态 + barrass套子 + ed形容词后缀 → 进入套中 → embarrassed难堪的，尴尬的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1680, 'essay', '/ˈeseɪ/', 'essay.mp3', 'n.论文；随笔；  v.尝试', '59584eb12f96329af9f164c58be78c56_193140_1605163167.jpg', '20140927_08_51_32_126_v3.png', 'The girl is busy writing her essay right now.', '这个女孩正忙着写她的论文。', '8d7311d0d6eb01e2_1266883375341284176_250207.mp3', 'ess=ex向外 + ay启动，开动 → essay企图', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1681, 'ever', '/ˈevər/', 'ever.mp3', 'adv.曾经；始终；究竟；在任何时候', '0d29c53e136e837f647e7e2445d905a1_183011_1623037042.jpg', 'd_24_19026_0_3_20150809000009.png', 'Have you ever been on a hot air balloon?', '你曾经坐过热气球吗？', '99310c8c2cebdb43_1266763402042911508_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1682, 'exhaust', '/ɪɡˈzɔst/', 'exhaust.mp3', 'v.使筋疲力尽；耗尽；详尽论述；  n.排气装置；废气', 'd205efcf28fde11aa0e8704c0e536217_107870_1538661074.jpg', '20141014_07_38_44_603_v3.png', 'Doing housework exhausts me.', '做家务让我筋疲力尽。', '8f1f49e495804797170d72ba860b5e25_9607_1538661090.mp3', 'ex完全 + haust抽出 → exhaust用尽，耗尽', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1683, 'fact', '/fækt/', 'fact.mp3', 'n.事实，现实', '3_0_20170707160313_50511_c-gigapixel-scale.jpg', 'd_24_18895_0_3_20150808235924.png', 'My photo proved the fact that the ghosts weren\'t real.', '我的照片证明了一个事实：这些鬼都是假的。', '3_0_20170707160313_35019_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1684, 'favorite', '/\'feɪvərɪt/', 'favorite.mp3', 'adj.最爱的（同favourite）；  n.最喜爱的人或物', 'i_24_7085_0_4_20150808224917-gigapixel-scale.jpg', 'd_24_7085_0_4_20150808224917.png', 'Apples are the little girl’s favorite fruit.', '苹果是那个小女孩最爱的水果。', 'sa_24_7085_0_4_20150808224917.aac', 'favor喜爱 + ite表名词或形容词 → 最喜欢的人或物 → favorite最喜爱的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1685, 'federal', '/ˈfedərəl/', 'federal.mp3', 'adj.联邦政府的；联邦制的', '23d65c6b242fdf020a1318da720c8657_159139_1538667156.jpg', 'd_24_5136_0_4_20150808223940.png', 'This building is the sign of the federal government of the USA.', '这座建筑是美国联邦政府的标志。', '3f52c49b145ddb3e127f16b999c82103_21675_1648794475.mp3', 'feder=league联盟 + al表形容词 → federal联盟的，联邦的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1686, 'fellow', '/ˈfeloʊ/', 'fellow.mp3', 'n.家伙，男人；  adj.处于相同情况的，同类的；  v.使…与另一个对等，使…与另一个匹敌', 'f6fbcd933ecf06b249b9a5a945fda814_73411_1565341852.jpg', 'd_16_10167_0_2_20150808235155.png', 'Those two fellows are celebrating their success.', '那两个男人在庆祝他们的成功。', 'sa_1_10167_0_2_20150808131610.aac', 'fe钱 + llow放下 → 在合资企业中放下钱财的人 → fellow同事，伙伴', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1687, 'fortunately', '/ˈfɔːrtʃənətli/', 'fortunately.mp3', 'adv.幸运地，幸亏', '076ccabec092fe27f70d85dda0509aa5_94112.jpg', 'd_103_9260_0_3_20150809033219.png', 'Fortunately', '太幸运了，他中了彩票，那可是100万啊！', 'd8a4d6db0697470a4576accd36efaa01_33678.mp3', 'fortun=fortune力量，运气一个 + ate表示有……性质的 + ly表示如……的、有……特征的 → fortunately幸运地，幸亏', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1688, 'fur', '/fɜːr/', 'fur.mp3', 'n.毛皮', 'caa33f54c66b5b69fe75a4aa33f27d20_49959_1565623715.jpg', '20130130_16_07_55_507.png', 'A fur coat is very warm', '毛皮外套很温暖，但也很昂贵！', '2k2vnrvys3fc8s4v3ntgykqbd9b73ts3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1689, 'grief', '/ɡriːf/', 'grief.mp3', 'n.悲伤，悲痛', 'ceaa3d44091fd0cdb077b5fb2e0ea8ff_141975_1587692420.jpg', '20140721_06_36_30_210_v3.png', 'He was filled with grief when he heard the bad news about his daughter.', '当他听到关于女儿的坏消息时，他悲伤不已。', 'us_He_was_20230713153302142_4a5e894803d4af270bae.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1690, 'hang', '/hæŋ/', 'hang.mp3', 'v.悬挂', '397a49bdfc9b0fb6b22ec2775357f918_166895_1538641543.jpg', 'd_24_7987_0_4_20150808225321.png', 'A luxurious drop lamp is hanging on the ceiling.', '一盏奢华的吊灯挂在天花板上。', 'e7846d4d5dbbc68e_1266798138569415288_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1691, 'hole', '/hoʊl/', 'hole.mp3', 'n.洞；孔；坑；裂口；  v.钻孔', '50f53ba76d1d9fa9549d83aaf0431a60_85418_1535180251.jpeg', 'd_16_8413_0_2_20150808233025.png', 'The hole in the tree trunk is the home of the small animal.', '树干上的洞是这只小动物的家。', 'fbf9cff4c290a24c_1266883376549550734_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1692, 'ideal', '/aɪˈdiːəl/', 'ideal.mp3', 'adj.理想的；完美的；空想的；观念的；  n.理想；典范；目标', '61256e97c09765e67628c10df76f438c_106322_1575258421.jpeg', 'd_1_4490_0_2_20150808122817.png', 'An ideal weekend is to lie on the sofa', '一个理想周末是躺在沙发上看电视、吃零食。', 'us_An_ideal_20240628115309717_8c4b8e779a8cb978f697.mp3', 'ide思想，观点 + al名词后缀 → 对未来的想法 → ideal理想的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1693, 'illegal', '/ɪˈliːɡl/', 'illegal.mp3', 'adj.非法的', '4a44859d9be22e8607cbb13335ea4b09_79140_1733117020.jpg', 'd_107_6185_0_2_20150809015154.png', 'Occupying a bus lane is illegal.', '占用公交车道是违法的。', 'd8ywg42zn5b9uccd9jfz43jdebampxd8.mp3', 'il不，无 + legal合法的 → illegal非法的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1694, 'incorrect', '/ˌɪnkəˈrekt/', 'incorrect.mp3', 'adj.错误的，不正确的', 'dbdf0447609e8d13ac44ee4375337e99_201038_1569654815.jpeg', 'd_105_17327_0_2_20150809062313.png', 'Incorrect standing posture is bad for your health.', '不正确的站姿有害你的健康。', 'scj7tmk2zahubcq2qqdyfqlvabewft2r.mp3', 'in不 + cor共同 + rect正确 → incorrect不正确的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1695, 'infect', '/ɪnˈfekt/', 'infect.mp3', 'v.传染，感染；使受影响', 'c_i_wm_20120307_03_23_58_822-manual-scale.jpg', 'd_107_1560_0_2_20150809001946.png', 'You are sick! Put the mask on', '你生病了！ 把口罩戴上，不然你会传染给别人的。', 'sa_1_1560_0_3_20150808121722.aac', 'in进入 + fect做 → 做进去，传染进去 → infect传染，感染', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1696, 'ink', '/ɪŋk/', 'ink.mp3', 'n.墨水，油墨', 'e9c94353209a290e84802783967ee666_83967_1575365077.jpg', 'd_45_13096_0_4_20150809002320.png', 'I used ink to write some nice Spring Festival wishes.', '我用墨水写了些春节祝福。', '676ee70a6b2c1f0bc5f32c80e9958db2_37241_1575364938.mp3', 'in使... + k烧 → ink墨水', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1697, 'innocent', '/ˈɪnəsnt/', 'innocent.mp3', 'adj.天真的，单纯的', '9eb49d0b1715ad09100d488eaf50a927_262833_1711160551.jpg', 'd_24_5811_0_4_20150808224349.png', 'The innocent smiles of the close friends displayed their pure happiness.', '这对密友天真无邪的笑容里流露出纯粹的幸福。', '4b962e7681dc8982_1266883622338648824_250207.mp3', 'in无 + noc伤害，毒 + ent形容词后缀 → innocent无害的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1698, 'leaf', '/liːf/', 'leaf.mp3', 'n.叶', '71a5b8cd0a406861c4469247d3a9e28a_84495_1574839228.jpg', 'd_94_13248_0_4_20150809010117.png', 'The picture shows different kinds of leaves.', '图片里展示了各种各样的树叶。', '5a9ec9473199eaeb8c53e32851f6b07c_35987_1574839317.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1699, 'limited', '/ˈlɪmɪtɪd/ ', 'limited.mp3', 'adj.有限的；被限制的', '1d3de5d1d9d9d7648a456c34327101e4.jpg', 'd_1_8367_0_2_20150808130626.png', 'On this diet', '在这项饮食计划中，你只能吃一点点食物。', 'sa_1_8367_0_2_20150808130626.aac', 'lim门槛，限制 + it放出 + ed形容词后缀 → 放出限制 → limited有限的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1700, 'master', '/ˈmæstər/', 'master.mp3', 'n.大师，能手；主人；硕士；  v.精通；  adj.主要的；精通的', 'fe7f83ddcca867bdc79daaba54f4b33e_110848_1532080826.jpg', 'd_24_7490_0_4_20150808225119.png', 'Practicing every morning makes him a master.', '每天早晨的苦练成就了他的大师地位。', '64173369f50790b37b737ded94e48c84_19305_1532080526.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1701, 'medal', '/ˈmedl/', 'medal.mp3', 'n. 奖牌，勋章', 'i_1_4190_0_2_20150808122515-gigapixel-scale.jpg', 'd_13_4190_0_2_20150808165641.png', 'These gold medals are symbols of honor.', '这些金牌是荣誉的象征。', '77cbbf75289869a5_1266763527368649662_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1702, 'meet', '/miːt/', 'meet.mp3', 'v.满足', 'e0e92bd7e338abd36de990e0fea38ccc.jpeg', 'd_24_17285_0_4_20150808232614.png', 'This production chain ensures that the supply of milk meets the demands.', '这条生产链保证了牛奶的供应满足需求。', '08a519971446b8d623b3b98ac1a388b8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1703, 'merchandise', '/ˈmɜrtʃənˌdaɪs/', 'merchandise.mp3', 'n.商品，货品（读作/ˈmɜrtʃənˌdaɪs/）；  v.推销，经营（读作/ˈmɜrtʃənˌdaɪz/）', '0054c4a5b84c7ee8b28735982dce68a8_94536_1586770572.jpeg', '20140820_22_15_50_683_v3.png', 'The merchandise in this store is neatly folded and well presented.', '这家店里的商品叠得整整齐齐，展示得很清楚。', '30bee12994efc9c59ed5d9785001df15_47604_1586770570.mp3', 'merchand=merchant商人 + ise表名词 → 商人的东西 → 商品', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1704, 'necessity', '/nəˈsesəti/', 'necessity.mp3', 'n.必需品', '9e1ea26ef7fbae95b730ed95921ac2d3_204682_1573806103.jpeg', '20130510_18_16_15_893.png', 'Air conditioner is an absolute necessity in this climate.', '在这种气候下，空调是绝对的必需品。', 'b83c6ffdc39fccde45556daca7a1d561_19638_1644544065.mp3', 'necess不可或缺的 + ity名词后缀 → necessity必要性；必需品', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1705, 'note', '/noʊt/', 'note.mp3', 'n.笔记，记录；  v.注意', '3_0_20160520173038_5684_c-gigapixel-scale.jpg', 'd_24_17188_0_4_20150808232319.png', 'This board is covered with notes we left before. ', '告示板上贴满了我们之前留下的便条。', 'e34acf3cf2b82e2e3776ec6298e78b70_23645_1621927833.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1706, 'nursery', '/ˈnɜːrsəri/', 'nursery.mp3', 'n.托儿所', 'cd0931b4c67ae8957ef3f967b081e654_94886_1575009082.jpg', '20141013_03_00_11_16_v3.png', 'I drop off my kids at the nursery before I go to work.', '上班之前，我把孩子们送去了托儿所。', 'sa_1_4071_0_6_20150808122313.aac', 'nurse照顾 + ry名词后缀 → nursery托儿所', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1707, 'obligation', '/ˌɑːblɪˈɡeɪʃn/', 'obligation.mp3', 'n.义务，责任', '55f08d6e536c3d2440fdec64f5180124_41771_1584956743.jpeg', 'd_1_6194_0_3_20150808124818.png', 'If you want to own a pet', '如果你想拥有一只宠物，你就必须履行所有的相关义务。', '3a2a6806d07d677acc72c4e2ba4ab934_38138_1584956729.mp3', 'obligat使负义务 + ion名词后缀 → 有义务 → obligation责任', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1708, 'obvious', '/ˈɑːbviəs/', 'obvious.mp3', 'adj.明显的，显而易见的', 'c65cd21ef2d6bfe8c952796aba373d3e_86655_1595470133.jpeg', 'd_16_4482_0_2_20150808224254.png', 'It is obvious that he ate the cake.', '很明显是他吃了蛋糕。', 'c008ccafffbea649_1266763556588247584_250117.mp3', 'ob逆，倒，加强状态 + vi=way道路 + ous形容词后缀 → 在路上逆行很容易被发现 → obvious明显的，显而易见', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1709, 'occasional', '/əˈkeɪʒənl/', 'occasional.mp3', 'adj.偶然的', 'i_1_9098_0_3_20150808131206-gigapixel-scale.jpg', 'd_107_9098_0_2_20150809024215.png', 'The lucky farmer\'s discovery of the treasure was occasional.', '那个幸运的农民偶然发现了宝藏。', 'sa_1_9098_0_3_20150808131206.aac', 'oc使 ＋ cas落下 ＋ ion名词后缀 ＋ al…的 → occasional偶然的，非经常的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1710, 'on the spot', '/ɑːn ðə spɑːt/', 'on the spot.mp3', 'phr.马上', 'a6ccbd66902748759be1127cabda74c3.jpeg', '', 'After he saw the accident', '目睹车祸发生后，他立刻拨打了急救电话。', '313fdeb3b1bcbb93158729d015d4c51e_31289_1621930587.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1711, 'operate on', '/ˈɑːpəreɪt ɑn/', 'operate on.mp3', 'phr.给……动手术', '2a2016e2f5ac05905220f6a9a2ef8d42.jpg', '', 'The doctors are operating on his knee.', '医生们正在给他的膝盖做手术。', '852fddd7ea660a1f0fdd114cd86469fb.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1712, 'Pacific', '/pəˈsɪfɪk/', 'Pacific.mp3', 'n.太平洋', '4d8d1cad359b4ac6667f3a2505124cd1_128230_1654656078.jpg', '', 'The Pacific Ocean is the largest ocean in the world. ', '太平洋是世界上最大的海洋。', 'us_The_Pacific_20220609094924230_38237fcf0e83a379c1a2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1713, 'pain', '/peɪn/', 'pain.mp3', 'n.痛，痛苦；努力，劳苦', '6e6c3d99ee90519cddaaea15ccdf7125_59474_1561953082.jpg', '20130105_10_18_59_929.png', 'He is suffering great pain in his neck and back.', '他感觉脖颈和后背特别疼。', '4rm6fezyb5j5zse73e7hlrbnpt685vks.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1714, 'panel', '/ˈpænl/', 'panel.mp3', 'n.讨论小组，专家咨询组；仪表板；面板；  v.镶嵌', '7e94382563e9b3aab86ced0364d81eb0_133976_1565685210.jpg', 'd_1_3928_0_2_20150808122104.png', 'The candidate was selected by the panel.', '候选人是由讨论小组选出的。', 'sa_103_3928_0_3_20150809003419.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1715, 'paw', '/pɔː/', 'paw.mp3', 'n.爪', '55b7fc40ae38f73b1f5c80a478eb3639_85875_1535178207.jpeg', '20140929_02_44_19_465_v3.png', 'The cat used its paws to hold the man\'s hand.', '猫咪用爪子握住了这个男人的手。', 'd5f9d14a55c340be_1266883488708844226_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1716, 'possible', '/ˈpɑːsəbl/', 'possible.mp3', 'adj.可能', '679d22858b196d4da83e729c94d790d1_158096_1523504014.jpg', 'd_24_19274_0_3_20150809001129.png', 'The base tries to find out if it\'s possible there are aliens in the universe.', '这个基地试图弄清宇宙中是否有外星人存在。', '5jwvp4bzaqku6mz9b3mubct6pm3p2wtc.mp3', 'poss能够的 + ible能...的，表形容词 → possible可能的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1717, 'proceed', '/proʊˈsiːd/', 'proceed.mp3', 'v.前进，行进；  n.收入，获利', 'i_1_5094_0_4_151009181401-gigapixel-scale.jpg', 'd_1_5094_0_2_20150808123459.png', 'The girl proceeded only after the traffic light turned green.', '绿灯亮起之后，这个女孩才开始往前走。', 'sa_1_5094_0_4_160224175833.aac', 'pro向前 + ceed行走，前进 → 向前走 → proceed前进', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1718, 'proportional to', '/prəˈpɔːrʃənl tuː/', 'proportional to.mp3', 'phr.与...成比例', '4978db1c74daadbef872f2dd096d8533.jpeg', '', 'The number of teachers appointed is proportional to the total number of students. ', '指定的教师人数与学生总数成正比。', 'f005e1f90e6a169c38673a2a991b008f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1719, 'prospect', '/ˈprɑːspekt/', 'prospect.mp3', 'n.前景，展望；有前途的人；  v.对……进行仔细调查（读作/ˈprɑːspekt/）', '362e8d26bc05172a0ff887ab405d2581_63793_1566801863.jpg', 'd_1_3945_0_2_20150808122123.png', 'She has excellent career prospects with her diverse skills and experience.', '凭借多样的技能和经验，她拥有广阔的职业前景。', 'us_She_has_20240911175141649_0548c9265941bda82a90.mp3', 'pro向前，在前 + spect看 → 向前看 → prospect前景', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1720, 'protect from', '/prəˈtekt frəm/', 'protect from.mp3', 'phr.保护...不受', '12fdf7e139f3c3e0e10e51a768a9f6ed.jpeg', '', 'Her umbrella is protecting her from the sun.', '她的伞在保护她不被太阳晒伤。', '704ac0a0930f3f53c87c82e7ba385b2e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1721, 'put over', '/pʊt ˈovɚ/', 'put over.mp3', 'phr.耽搁', '78d1eb1fc2ba5b25ad3872451b88f548.jpg', '', 'The match was put over to the next week due to the storm.', '由于暴风雨，比赛推迟到下周举行。', 'f01a9b154f1fa4084188d71a9868bef2_51519_1599537658.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1722, 'relation', '/rɪˈleɪʃn/', 'relation.mp3', 'n.关系，联系', 'i_1_9086_0_4_151019161121-manual-scale.jpg', 'b87609b5fcbe3fb09ff07a7bcbb66a78_20566_1539341290.png', 'They have built a business relation; they\'re partners from now on.', '他们建立了商业关系；从现在开始，他们就是合作伙伴了。', 'sa_1_9086_0_4_151102170016.aac', 'relat=relate关联 + ion名词后缀 → relation关系；联系；家属', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1723, 'relevant to', '/ˈrɛləvənt tu/', 'relevant to.mp3', 'phr.与……有关', '061355b119a29514770ed87c8b24facd.jpeg', '', 'They are trying to let young people know that politics is closely relevant to them too.', '他们想让年轻人知道政治也与他们密切相关。', 'us_They_are_20221026175431696_dddcb2dc481df8fbe0ab.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1724, 'resort to', '/rɪˈzɔːrt tuː/', 'resort to.mp3', 'phr.（在别无办法的情况下）诉诸于，采用', '4549a551f4916accf33cc1fc56dd046c.jpeg', '', 'When his cousin didn\'t answer his call', '他的表妹不接电话，他只好到她家去了。', 'cadfcce18ee6da314e621cb67c4bd3be_44878_1599550763.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1725, 'seem', '/siːm/', 'seem.mp3', 'v.似乎，好像，看来', 'i_1_18610_0_3_20150808132432-gigapixel-scale.jpg', 'c1ceb97716cdeb79a4494d15606e42fb_86500_1539341265.png', 'Judging by the clouds', '根据这云层判断，似乎要下雨。', 'f497320f159c7ec9_1266763525306428296_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1726, 'seize', '/siːz/', 'seize.mp3', 'v.抓住，逮捕', '8629e9aba2fc5a8fe97738b6246c55fe_196928_1538759314.jpg', 'd_16_6274_0_2_20150808230455.png', 'They seized one another by the wrist.', '他们相互抓住了对方的手腕。', '4f9f8c48105c90e8_1266883484080188194_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1727, 'shame', '/ʃeɪm/', 'shame.mp3', 'n.羞愧；  v.使羞愧（或惭愧）', '856a003b8a7db4039ed4565e2222dd5e_187104_1578562026.jpeg', 'd_24_17294_0_3_20150808232627.png', 'He felt a deep sense of shame because he cheated in the exam.', '他因考试作弊而深感羞愧。', 'f8350c52f9f3d0d9_1266883626207959604_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1728, 'station', '/ˈsteɪʃn/', 'station.mp3', 'n.车站；站，局；  v.安置，驻扎', '8c9c595d22412d9076228c9206fed533_90662_1533120045.jpeg', 'd_24_4968_0_3_20150808223739.png', 'The train at the station is about to leave.', '车站里停着的火车快要出发了。', '6857917253dec762_1268213311985894052_250930.mp3', 'sta=stand站 + tion表名词 → (车)站，台', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1729, 'submission', '/səbˈmɪʃn/', 'submission.mp3', 'n.屈服，服从；提交，呈递', 'submission_2470_20231106_ffd2fbe8.jpg', '20140726_21_18_32_894_v3.png', 'The knight kneeled and handed over his sword to show his submission.', '这位骑士单膝跪地并交出自己的宝剑以示屈服。', '3_0_20160624150021_8526_c.aac', 'sub下面 + miss送，放出 + ion名词后缀 → 放在下面 → submission屈服', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1730, 'suit', '/suːt/', 'suit.mp3', 'n.西服，套装；服装；诉讼；  v.适合；满足……需要；相配', '6b0deed98f6990660a15c613e86997cd_101952_1601456287.jpg', 'd_24_5572_0_3_20150808224156.png', 'The businessman is wearing a gray suit.', '这位商人穿着一套灰色的西装。', '63b358c61c583cf4_1268213308576645772_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1731, 'tailor', '/ˈteɪlər/', 'tailor.mp3', 'n.裁缝；  v.调整……使适应；定做', 'i_4_9337_0_7_151221114625-manual-scale.jpg', 'd_24_9337_0_3_20150808230158.png', 'The tailor measured him for a new suit.', '裁缝为他量身定做了一套新西装。', 'sa_1_9337_0_7_160407100736.aac', 'tail剪，割 + or表名词 → tailor裁缝', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1732, 'technical', '/ˈteknɪkl/', 'technical.mp3', 'adj.技术的，工艺的', '6d07be2439c4565f615a4db06ca5ce34_92443_1579333863.jpeg', '20121225_18_24_00_794.png', 'She is responsible for answering technical questions.', '她负责解答技术问题。', '2d5d7a67cf8f035b480231bf3b89b978_41638_1579333860.mp3', 'techn技术，能力 + ical形容词后缀 → technical技术上的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1733, 'test', '/test/', 'test.mp3', 'n.测验，测试', 'i_13_17315_0_2_20150808204732-gigapixel-scale.jpg', 'd_24_17315_0_3_20150808232647.png', 'If you study for the test', '如果认真准备了，考试会很简单。', '5c6ba6ef4aa63fd8_1266883002337942016_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1734, 'thermometer', '/θərˈmɑːmɪtər/', 'thermometer.mp3', 'n.温度计', '0918ac8187a2ac19af10145667f8671f_84346_1535177533.jpeg', 'd_1_8977_0_2_20150808131118.png', 'The man used a thermometer to take his temperature.', '这个男人用一支温度计来测量体温。', 'sjrfvehqzmlhued8j7gx7f6nn2rrsw2c.mp3', 'thermo热 + meter计量，测量 → thermometer温度计，寒暑表', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1735, 'thread', '/θred/', 'thread.mp3', 'n.线', '3_0_20160528175847_6200_c-gigapixel-scale.jpg', 'd_24_18165_0_4_20150808235114.png', 'I can use these colorful threads to make knitted scarves.', '我能用这些五颜六色的线织成围巾。', '3_0_20160528175847_20799_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1736, 'tongue', '/tʌŋ/', 'tongue.mp3', 'n.舌头；  v.吹奏管乐器', '3_0_20160520172945_55082_c-manual-scale.jpg', 'd_99_14553_0_4_20150809022618.png', 'The boy sticks out his tongue to make a face to me.', '男孩伸出舌头来对我做鬼脸。', '7lwub2s7qplsjarw3hfzy67d3lf4m3nl.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1737, 'tough', '/tʌf/', 'tough.mp3', 'adj.健壮的；棘手的', '107fa78d8494ee09938fc3334e0fda32_36538_1732160239.jpg', 'd_16_5751_0_4_20150808225822.png', 'She is a tough and ambitious athlete. ', '她是一位健壮且有抱负的运动员。', 'us_She_is_20241121113715465_c666ad9149a078d5b8ef.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1738, 'tower', '/ˈtaʊər/', 'tower.mp3', 'n.塔，楼塔；  v.高耸', '582261b8b007c3a14dd841480435d7c5_90413_1577958641.jpeg', 'd_13_18133_0_2_20150808205343.png', 'All the lights of this tower will be on at night.', '一到晚上，这座塔的灯就会被全部点亮。', 'bw3czfhlarwsumdw6q73jrnpg4pqy646.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1739, 'tradition', '/trəˈdɪʃn/ ', 'tradition.mp3', 'n.传统，风俗，惯例', '3_0_20170713071124_81688_c-gigapixel-scale.jpg', 'd_16_6963_0_2_20150808231324.png', 'Dragon Boat Festival has many different traditions.', '端午节有许多不同的传统习俗。', 'cp8s682u6dpkvuuvplu626ak9yh5htvg.mp3', 'tra过 + di给 + tion名词后缀 → 一代一代地传递 → tradition传统', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1740, 'truly', '/ˈtruːli/', 'truly.mp3', 'adv.真诚地，衷心地', '65742e78e8da331c821baac6e795ffc5_119618_1538648478.jpg', 'd_103_17371_0_3_20150809035032.png', 'I truly love you from the bottom of my heart!', '我真心爱你，从心底里爱你！', 'b3f12cc23d43aa3c6816b3040de41932_13837_1538648517.mp3', 'tru=true真实 + ly表副词 → truly真正地，确实地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1741, 'vegetable', '/ˈvedʒtəbl/', 'vegetable.mp3', 'n.蔬菜；  adj.蔬菜的，植物的', 'b781a39ca2708b036059f4130b7aa3ab_202327_1523872862.jpg', '20121225_19_58_40_718.png', 'These are just a few of the fresh', '这只是我花园里一部分新鲜成熟的蔬菜。', '5bd9392dc3f1609b_1266763450509667094_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1742, 'visible', '/ˈvɪzəbl/', 'visible.mp3', 'adj.可见的', '418a874b261d24c6254063f8e4f288ae_54763_1565073226.jpeg', 'd_1_5753_0_4_20150808124336.png', 'The cake is visible in the right box.', '右边盒子里的蛋糕是可见的。', '0bcac03575097892a6567b016e147607_13525_1624074200.mp3', 'vis看 + ible形容词后缀，可…的 → visible看得见的，可见的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1743, 'wake', '/weɪk/', 'wake.mp3', 'v.醒来，唤醒', 'b593ddc7a46fc42a156b7f0fafca9f63_108267_1732262736.jpg', '20121225_19_21_25_938.png', 'The alarm woke up the man.', '闹钟把男人吵醒了。', 'us_The_alarm_20241122160538207_b5ceb887258cd6e52606.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1744, 'with respect to', '/wɪð rɪˈspekt tu/', 'with respect to.mp3', 'phr.关于', 'a4b987d54b2395806b7e1785a6cb3f0b.jpeg', '', 'The child has very little choice with respect to what they eat at home.', '对于家里吃什么饭菜，这个孩子基本上没什么选择。', '7b5b28a3ce340435aaad9386e1f6770a_22772_1619317851.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1745, 'without', '/wɪˈðaʊt/', 'without.mp3', 'prep.没有，不', '4a40d3c1cdcb25df844e7822b5b19cda_41221_1753760160.jpg', 'd_24_17316_0_3_20150808232649.png', 'I feel so lonely without you.', '没有你我感觉好孤单。', 'us_I_feel_20250729113606285_e73025b6c96832c730a2.mp3', 'with和，与 + out离开，不在  → without没有', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1746, 'aboard', '/əˈbɔːrd/', 'aboard.mp3', 'adv.在（交通工具）上；  prep.在（交通工具）上', 'f8eb50801187a9330f1aba7e1bfe7e1b_222729_1625817618.jpg', 'd_107_8238_0_2_20150809022946.png', 'In Thailand', '在泰国，一些女性经常在船上做饭。', '5592bea122f7da01f349468afabfb569_21989_1631341890.mp3', 'a在...上面 + board木板 -> aboard在（交通工具）上', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1747, 'accept', '/əkˈsept/', 'accept.mp3', 'v.接纳，认可；接受（所提供或给予的物品）', '4e4b6f53c3968a2dab4a401230869501_178376_1532942833.jpeg', '', 'She accepted his marriage proposal.', '她接受了他的求婚。', 'ae7762a35fb5d2bc_1266883331223169852_250207.mp3', 'ac一再 + cept拿 → accept接受，承认', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1748, 'accumulate', '/əˈkjuːmjəleɪt/', 'accumulate.mp3', 'v.积攒，积累', 'i_1_6434_0_3_20150808125146-gigapixel-scale.jpg', 'd_107_6434_0_2_20150809020114.png', 'He accumulates wealth for future use.', '他积累财富以供将来使用。', 'us_He_accumulates_20231127160117941_130f486a37c17fc5150e.mp3', 'ac(ad)=to', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1749, 'accurate', '/ˈækjərət/', 'accurate.mp3', 'adj.准确的，正确的', '8a6b82069a1d791242d5e671d21cdc23_40107_1565278137.jpg', 'd_107_7842_0_2_20150809022240.png', 'I never miss my target because my aim is so accurate.', '我从未脱靶，因为我瞄得很准。', 'd545b9013f5ab3e9_1266883491562806012_250207.mp3', 'ac加强语气 + cur关心 + ate形容词词尾 → 去关注、关心，不马虎大意 → accurate准确的；精确的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1750, 'alternative', '/ɔːlˈtɜrnətɪv/', 'alternative.mp3', 'adj.可供选择的；  n.可供选择的事物', '57b819a230077653df7cf4b09171b4bd_195543_1530590796.jpeg', 'd_16_7106_0_2_20150808231446.png', 'She provides an alternative choice for the girl who wants to buy a diamond ring.', '她给那个想买钻戒的女生提供了另一种选择。', '068ac18602044e50_1266883538548185832_250207.mp3', 'altern另外的 + ative形容词/名词后缀 → alternative替换的，替换物', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1751, 'amazing', '/əˈmeɪzɪŋ/', 'amazing.mp3', 'adj. 令人惊奇的，令人惊喜的', '20121103_16_20_44_341-gigapixel-scale.jpg', 'd_24_11008_0_3_20150808230536.png', 'The sunrise is so amazing!', '日出美得惊人！', 'e4816514784ec01e_1266798138094824306_250123.mp3', 'amaz=amaze惊异 + ing形容词后缀 → amazing令人惊异的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1752, 'among', '/əˈmʌŋ/', 'among.mp3', 'prep.在……中间，在……之中', 'd7bd41edb0c65c1eba2e67a9a336b765_177357_1595472254.jpeg', '20121225_18_34_43_799.png', 'There is an apple among the other fruits.', '这个苹果在这些水果之中。', '59cff849fa64bbec51dd73b89b852689_57039_1599530856.mp3', 'a在...上 + mong揉捏，合身 → among处于...中，在...中间', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1753, 'anxiety', '/æŋˈzaɪəti/', 'anxiety.mp3', 'n.焦虑', '029d444bf987f76fd49ff004bf2cb50d_190399_1570870763.jpeg', '20141014_12_37_12_693_v3.png', 'The boy is full of anxiety before the new school term begins.', '在新的学期开始之前，这个男孩焦虑万分。', 'e9f443a738b7c96d32d005c59ebcb82b_46256_1572406883.mp3', 'anxi焦虑 + e + ty名词后缀 → anxiety焦虑', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1754, 'apart', '/əˈpɑːrt/', 'apart.mp3', 'adv.分离地，分开地；  adj.分隔的，拆开的，撇开的', 'c_c_i_wm_20121122_16_58_02_236-gigapixel-scale.jpg', '20130106_14_35_19_87.png', 'They set one man apart from the rest.', '他们把一个人与其他人分开了。', 'sa_1_5713_0_3_20150808124249.aac', 'a=ad去，向 + part授予，分配 → apart分离，分开', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1755, 'area', '/ˈeriə/', 'area.mp3', 'n.面积', '4fbc4d7619d58baa3cdb4e238e8c669e_72058_1750821339.jpg', 'd_24_15898_0_3_20150808230735.png', 'The area of the office is about 40 square meters.', '办公室的面积大约是40平方米。', '8duet73hp7v9ycbduyqvxag5s6ktz54n.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1756, 'arrangement', '/əˈreɪndʒmənt/', 'arrangement.mp3', 'n.布置；准备，筹备；排列；安排', '0a82416e68c7e0352a49b8cd42e95a59_598687_1610012411.jpg', '20141011_21_12_25_307_v3.png', 'There was a comfortable arrangement of tables for outdoor dining.', '户外用餐的餐桌布置得很舒适。', 'jvwdgw6gau7e57lcgw93hepewf78prpr.mp3', 'arrange安排 + ment名词后缀 → arrangement排列，布置', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1757, 'Asian', '/ˈeɪʒn/', 'Asian.mp3', 'adj.亚洲的；  n.亚洲人', 'ee165f8c5e9966514090e089e24f4ddf_95505_1656928616.jpg', '1743c217ba283de50efc1ef8bea62b66_49276_1544669551.png', 'This is a happy Asian family.', '这是一个幸福的亚洲家庭。', 'us_This_is_20220704175648262_89a0fac5b0922ed32d97.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1758, 'at all costs', '/æt ɔːl kɔsts/', 'at all costs.mp3', 'phr.不管多大代价，无论如何', 'i_910_-910_0_1_160310141844.jpg', '', 'I am willing to exchange for the rare medicine at all costs.', '我愿意不惜一切代价换取那粒珍贵的药。', 'sa_910_-910_0_1_160323144823.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1759, 'because of', '/bɪˈkɔːz əv/', 'because of.mp3', 'phr.因为；由于', 'bf612610001cd0da6deac3718730048f_62683_1752653032.jpg', '', 'I got sick because of the cold and the rain.', '因为天冷和这场雨，我生病了。', 'b10c9daf85adb1e8_1266797983944825404_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1760, 'berth', '/bɜːrθ/', 'berth.mp3', 'n.停泊处；【口语】职业；  v.使停泊', 'berth_315_20231106_dfa6457e.jpg', '20140731_09_59_54_378_v3.png', 'A large boat anchored in the berth.', '一艘大船在泊位内停下来。', 'us_A_large_20241009164011319_5b7ca6ba9aee7f87538d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1761, 'blame', '/bleɪm/', 'blame.mp3', 'n.指责；  v.把……归咎于', '155da3239fd097ac9a3fcc950980112f_70225_1731907472.jpg', '', 'I always get all the blame', '我总是受到所有的责备，但我从没有做错过任何事。', 'sa_1_4388_0_4_20150808122717.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1762, 'blouse', '/blaʊs/', 'blouse.mp3', 'n.短上衣；女式衬衫；宽松的工作服；  v.宽松下垂', '3_0_20170930071631_50561_c-gigapixel-scale.jpg', '', 'The off-shoulder blouse is on trend nowadays.', '这种露肩短上衣最近很流行。', 'us_The_offshoulder_20250825173918559_6db028f470e6abd48fbd.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1763, 'brief', '/briːf/', 'brief.mp3', 'adj.简洁的，简短的；  n.摘要；  v.简单汇报', 'i_16_7817_0_4_151119154319-gigapixel-scale.jpg', 'd_16_7817_0_2_20150808231945.png', 'The brief letter explains why she wants to quit.', '这封简短的信解释了她为何想辞职。', 'd86qrttlfh8pds7j233sujw8ssda2vjp.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1764, 'casual', '/ˈkæʒuəl/', 'casual.mp3', 'adj.随便的；  n.临时工', 'd63e45169f5bd617dfdde2da58273d0f_160902_1538666335.jpg', '20130106_14_38_10_780.png', 'She prefers casual clothing when hanging out on the street.', '在街上闲逛时，她偏好休闲的穿着。', '06f8bc2fcae48d5d21775d24ea37889e_18069_1538666371.mp3', 'cas落下 + ual……的 → 突然降临的，不是安排好的 → casual偶然的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1765, 'century', '/ˈsentʃəri/', 'century.mp3', 'n.世纪，百年', 'i_13_17955_0_2_20150808205149-gigapixel-scale.jpg', 'd_24_17955_0_4_20150808233729.png', 'I think that 2012 is the greatest year of the 21st century so far.', '我认为，到目前为止，2012年是21世纪最好的一年。', 'sa_13_17955_0_2_20150808205149.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1766, 'chicken', '/ˈtʃɪkɪn/', 'chicken.mp3', 'n.鸡肉；  v.畏缩不前；  adj.胆小的', '9912202bb0632ca43123cf2ed375e499_85735_1595468779.jpeg', '20121225_20_14_48_663.png', 'He cooked chicken for dinner.', '他晚餐做了鸡肉。', 'd3df1884a16968f6_1266763552784865984_250117.mp3', 'chick小鸡 + en名词后缀 → chicken小鸡', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1767, 'china', '/ˈtʃaɪnə/', 'china.mp3', 'n.瓷，瓷器', 'f961075379365e12b11f3a1f15385ea9.jpg', '', 'This is a beautiful china teacup and teapot.', '这是一套精美的瓷茶杯与茶壶。', '6e54dd6644e0245f7c885b833f682b01.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1768, 'classic', '/ˈklæsɪk/', 'classic.mp3', 'adj.典雅的，老式的；经典的；高雅的；  n.经典著作；文豪；优秀典范', '3_0_20160528174902_77927_c-gigapixel-scale.jpg', '20141013_01_30_16_745_v3.png', 'The decoration style of the room is classic.', '房间的装修风格是古典式的。', '3_0_20160528174902_51861_c.aac', 'class阶级 + ic表示人 → 高等阶级之人 → classic古典作家', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1769, 'climate', '/ˈklaɪmət/', 'climate.mp3', 'n.气候；（社会思想等的）趋势', '3_0_20171001071553_32801_c-gigapixel-scale.jpg', 'd_24_8428_0_3_20150808225715.png', 'Climates differ from place to place', '气候随着地域和季节的不同而变化。', '4b84c56a5481af67_1266763399758109392_250117.mp3', 'clim区域 + ate表名词  → 不同区域的气候  →climate气候', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1770, 'comment about', '/ˈkɑːment əˈbaʊt/', 'comment about.mp3', 'phr.……的看法', '518f14290e3fd45f29cc9e94ecb1675e.jpg', '', 'The man is giving a comment about the game.', '这人正在对这场比赛发表看法。', 'ba28fb5a62fd67e5e61de65121fc5cbf_41504_1593575809.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1771, 'committee', '/kəˈmɪti/', 'committee.mp3', 'n.委员会；全体委员', 'b857bb09a0c5c55607812cabd4dac57a_189705_1565938928.jpg', 'd_16_3844_0_2_20150808223714.png', 'The committee members come to the meeting to make decisions for the group they represent.', '委员会成员们代表着他们各自的组织来开会做决议。', 'be9a78679f9c4a12ef5fafd0b73e3dac_34565_1621931238.mp3', 'com集合，团结 + mitt(mittere)解放 + ee名词后缀，受动者 → committee委员会', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1772, 'common to', '/ˈkɑːmən tuː/', 'common to.mp3', 'phr.常见', '7c3465a9b5f5932b9d57bee5238c91c7.jpg', '', 'It\'s common to get fat.', '长胖很常见。', '672a4148eb3d50e87a29338b9615761c_25376_1593584164.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1773, 'communication', '/kəˌmjuːnɪˈkeɪʃn/', 'communication.mp3', 'n.通信，交流；沟通方式；信息', '2857bbece9b773904147c832bcf40873_45668_1732161309.jpg', 'd_24_3885_0_3_20150808223355.png', 'They like to use cell phones for communication.', '他们喜欢用手机来交流。', 'ad1546b502422ae948a3f07988d6b361_44192_1597655932.mp3', 'communi通常，一般 + cation名词后缀 → 共同的事物 → communication通信，交流', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1774, 'compromise between', '/ˈkɑːmprəmaɪz bɪˈtwiːn/', 'compromise between.mp3', 'n.... 之间的折中办法', '681dc05f6a82dfd54a6794fe8f7cdfa7.jpeg', '', 'The child made a compromise between what he wanted and what his mother wanted.', '这个孩子在自己的意愿和他妈妈的要求之间找到了一个折中点。', '221ca624ad73cd0f22a3f248d9801000.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1775, 'considerable', '/kənˈsɪdərəbl/', 'considerable.mp3', 'adj.相当大的；重要的；可观的', '3761546f6cbc194497e8521cf5550e56_49150_1584003830.jpeg', 'd_1_3866_0_2_20150808121958.png', 'Students have considerable pressure in their final year of university.', '学生们在大学的最后一年有相当大的压力。', '6469cb98cc3ea86fb9d1ccf44916883f_46688_1594981015.mp3', 'consider考虑 + able可……的 → 需要考虑的很多 → considerable相当大的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1776, 'coordinate', '/koʊˈɔrdəˌneɪt/', 'coordinate.mp3', 'v.使协调，使一致，调整；  n.坐标；  adj.并列的', 'eee5e4031a824307eeef0636d249bea9_46646_1709194529.jpg', 'd_107_4427_0_2_20150809005625.png', 'The dancers coordinated their moves so they could deliver a wonderful performance.', '舞者们动作协调一致，呈现出精彩的表演。', 'us_The_dancers_20240229161515123_cb19d82ac5fd20a4190e.mp3', 'co共同 + ordin顺序 + ate动词后缀 → 顺序相同 → coordinate协调，同等的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1777, 'crazy for', '/ˈkrezi fɔr/', 'crazy for.mp3', 'phr.渴望', 'e19c078d714ea2d32fb9c4860c523a34.jpeg', '', 'He\'s crazy for some fried chicken right now. ', '他现在很想吃点炸鸡。', '923418dcd284bba4eb66f652db47fc44.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1778, 'cube', '/kjuːb/', 'cube.mp3', 'n.立方体，立方', '92d50405c73d4385ebb4a32e726dfba3_40831_1565341756.jpg', 'd_13_6524_0_2_20150808191349.png', 'A cube is a three-dimensional square.', '立方体是个三维正方体。', 'sa_1_6524_0_2_20150808125214.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1779, 'danger to', '/ˈdeɪndʒər tuː/', 'danger to.mp3', 'phr.危害， 威胁', 'be2ebb16f6bc55c06ac6bce613f6f640.jpg', '', 'Smoking is a danger to health.', '吸烟危害健康。', '16b27959a467ac339f5931747f78f345_31136_1593574490.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1780, 'dawn', '/dɔːn/', 'dawn.mp3', 'n.黎明；  v.开始', '62610c6a23a2d8ec45c6c99d147bb2b5_157759_1536129011.jpeg', 'd_16_746_0_2_20150808223312.png', 'The rooster standing in the field crows at dawn.', '站在田野里的公鸡在黎明时分打鸣。', 'edfeea29118d0ab9e4ab502d49b89d68_23801_1621932136.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1781, 'deal', '/diːl/', 'deal.mp3', 'n.协议；交易；成交；  v.处理，应对；  quant.大量', '3_0_20170608072004_64540_c.jpg', 'd_24_17977_0_3_20150808233856.png', 'We reached a deal and shook hands.', '我们达成了协议，握了握手。', '3_0_20170608072004_5281_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1782, 'decade', '/ˈdekeɪd/', 'decade.mp3', 'n.十年，一个年代', 'c_20150605_102028_1_3927-gigapixel-scale.jpg', 'd_107_3927_0_2_20150809003525.png', 'People can change a lot after a decade.', '十年会给人带来很大的变化。', 'sa_1_3927_0_4_151017111813.aac', 'dec=deca十 + ade名词后缀，表状态 → 十年', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1783, 'decrease in', '/dɪˈkriːs ɪn/', 'decrease in.mp3', 'phr.缩小；减少', 'bc8317fe5fdd04f170fa1b2c47dc289c.jpg', '', 'There has been a decrease in my piggy bank savings.', '我的存钱罐里的存款已经减少。', 'us_There_has_20241009151600065_8e67147fbcfbfe3239f3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1784, 'delivery', '/dɪˈlɪvəri/', 'delivery.mp3', 'n.递送', '0d150f029ae0265b00f1ff38748be946_126193_1605166220.jpg', '20141010_23_10_06_403_v3.png', 'The delivery service aims to deliver each package as quickly as possible.', '投递服务旨在尽快派送每个包裹。', '2673789550cd25d54f7b902e60677582_57374_1533104128.mp3', 'de完全 + liver释放 + y形容词后缀 → 快递;投递;交付;分娩', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1785, 'despite', '/dɪˈspaɪt/', 'despite.mp3', 'prep.尽管，不顾', 'i_5_4925_0_4_160130171601-gigapixel-scale.jpg', 'd_13_4925_0_2_20150808173553.png', 'Despite the windy day', '尽管风很大，这名记者仍然在户外工作。', '850024de4db6b82b_1266883530037746328_250207.mp3', 'de向下 + spite看向，观察  → despite尽管', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1786, 'determine', '/dɪˈtɜːrmɪn/', 'determine.mp3', 'v.做决定', '4087a07725e03800b7eb3644bcb6713f_144170.jpg', 'd_107_4994_0_2_20150809011237.png', 'The chubby dog determines to lose weight.', '这只胖狗下定决心要减肥。', 'us_The_chubby_20240206094643147_40dae81eeb65ec6ef0b6.mp3', 'de加强动作 + termin界限 + e → 加强界限 → determine下决心', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1787, 'disappointed at', '/ˌdɪsəˈpɔɪntɪd æt/', 'disappointed at.mp3', 'phr.对......失望', '1dbb23ed9c4d6268e35f4a42a82e9776.jpeg', '', 'He felt quite disappointed at his test score. ', '他对他这次的考试成绩失望透顶。', '8d72c565eb434df47e331b57f493559c_46736_1593574700.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1788, 'distant', '/ˈdɪstənt/', 'distant.mp3', 'adj.遥远的', '64769894ef81d5a1a2b2133f71820e99_24334_1565604867.jpg', 'd_24_6137_0_3_20150808224444.png', 'The destination is still distant.', '目的地还很远。', '3b11d4d112a2a14464236ff80640cced_12585_1629705311.mp3', 'di分开 + stant站立 → 分开站 → distant有距离的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1789, 'document', '/ˈdɑːkjʊmənt/', 'document.mp3', 'n.文件，公文；  v.记录；证明（读作/ˈdɑkjuˌmɛnt/）', 'i_1_5620_0_4_150926145520-gigapixel-scale.jpg', 'd_24_5620_0_3_20150808224231.png', 'He checks out the document before signing it.', '在签署文件之前，他仔细检查了一遍。', '625a6d534c857a62_1266883478325910182_250207.mp3', 'docu=doc教 + ment名词后缀 → 用来告诉别人的东西 → document文件，公文', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1790, 'drag', '/dræɡ/', 'drag.mp3', 'v.拖，拉，拽，扯；（时间或事件）拖沓；  n.拖', 'c0d061973f5efd40adea6361cb4adac5_71042_1538643757.jpg', 'd_24_7248_0_4_20150808225039.png', 'You can drag this picture from this folder to the other.', '你可以把图片从这个文件夹拖进另一个文件夹里。', '36f91db6382927f2_1266883529931795334_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1791, 'duration', '/duˈreɪʃn/', 'duration.mp3', 'n.持续时间', '7401dfdef1f1dea5030b134603b772e3_116086_1656657065.jpg', 'd_107_16535_0_2_20150809025732.png', 'The duration of this exam is two hours.', '这场考试的时长是两个小时。', '5ed2168247edf816a3e72e6ddd0801ed_48214_1588139309.mp3', 'dur持久 + ation名词后缀，表状态 → 持久的状态 → duration持续时间', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1792, 'east', '/iːst/', 'east.mp3', 'n.东方；  adj.朝（或向）东方的；  adv.在东方', 'i_24_17902_0_5_151211105301-gigapixel-scale.jpg', 'd_24_17902_0_3_20150808233400.png', 'The sun rises from the east.', '太阳从东边升起。', '9wgy7z3k4tfguxcjdvz4eg9nvcbe8ee9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1793, 'efficiency', '/ɪˈfɪʃənsi/', 'efficiency.mp3', 'n.效率；功效；功率；性能', '255a3b668f36221094f7db65fcdb74af_204584_1569049369.jpeg', 'd_1_5135_0_2_20150808123541.png', 'He believes writing with three pens together can improve efficiency.', '他认为用三支笔一起写可以提高效率。', '77c9b4ad4bfb9eb50f93b665bf290964_43728_1569049366.mp3', 'ef出 + fic做 + iency表名词 → 做出事情 → efficiency有效率', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1794, 'emphasis', '/ˈemfəsɪs/', 'emphasis.mp3', 'n.重点；强调；重要性', '3_0_20160607180831_71620_c-gigapixel-scale.jpg', 'd_1_5049_0_2_20150808123405.png', 'The word has been highlighted to provide emphasis.', '标亮单词，以示重点。', '3_0_20160607180831_36430_c.aac', 'em进入 + phasis显示 → 进入显示 → emphasis强调', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1795, 'emphasis on', '/ˈɛmfəsɪs ɑn/', 'emphasis on.mp3', 'phr.着重于，强调；重读，重音', 'ad9f037a2a58f5751fdac3ce6b4e1d4c.jpeg', '', 'This housekeeping manager puts special emphasis on neatness.', '这位家政经理特别强调整洁。', '8edbe120c87e23cdf438d75b8190d14b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1796, 'enormous', '/ɪˈnɔːrməs/ ', 'enormous.mp3', 'adj.巨大的；（范围、程度）极大的；庞大的', '0989faf58d6d3c2e7ae683c2963f8a6a_184868_1535008510.jpeg', 'd_1_5669_0_2_20150808124208.png', 'The little girl was shocked by the enormous dog.', '小女孩被这只巨大的狗震惊了。', 't4aex9w7u64vj2nelvphgl7txk4v5rxv.mp3', 'e出 + norm规则，规范 + ous形容词后缀 → 超出了正常状态 → enormous巨大的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1797, 'enrol', '/ɪnˈroʊl/', 'enrol.mp3', 'v.参加，注册，登记，入学；  v.登记，使加入，把……记入名册', 'a25599de3e8af86a6bda494946a6be37_166035_1726305922.jpg', 'd_13_8314_0_2_20150808195132.png', 'I\'m thinking about enrolling for membership at the gym.', '我想注册成为健身房的会员。', 'sa_5_8314_0_2_20150808144738.aac', 'en做，放入 + rol=roll卷，册 → enrol参加，登记', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1798, 'essential to', '/ɪˈsɛnʃəl tu/', 'essential to.mp3', 'phr.对...极其重要的，必不可少的', '00556f252c59b7f26fe9384cc04b2031.jpeg', '', 'Sunlight is essential to the healthy growth of most plants. ', '太阳光对大部分植物的健康生长至关重要。', '0715a26461694ef2860c355c8bb406e2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1799, 'exactly', '/ɪɡˈzæktli/', 'exactly.mp3', 'adv.精确地，准确地，确切地', 'i_9_6967_0_4_160204170357-gigapixel-scale.jpg', 'd_16_6967_0_2_20150808231330.png', 'I want all my grass to be exactly the same height.', '我要我的草都完全一样高。', '292396d7e57243bf_1266763555408292620_250117.mp3', 'exact精确的 + ly副词后缀 → exactly精确地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1800, 'existence', '/ɪɡˈzɪstəns/', 'existence.mp3', 'n.存在；生活方式', 'd384e9746c88b72b2eddd63a878fa45e_201996_1575259706.jpeg', 'd_16_5545_0_2_20150808225418.png', 'These fossils prove the existence of dinosaurs.', '这些化石证明了恐龙的存在。', '3b49de888e7191aa63690ba3a213bd11_39118_1575259704.mp3', 'exist存在 + ence名词后缀 → existence存在', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1801, 'fade', '/feɪd/', 'fade.mp3', 'v.逐渐消失；  n.淡入，淡出', '906333bc41f112c864b70c086f8b4b71_35866_1565705096.jpg', 'd_107_4108_0_2_20150809004435.png', 'The trees were fading away into the mist.', '树渐渐消失在薄雾中。', 'sa_1_4108_0_3_20150808122343.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1802, 'faithful', '/ˈfeɪθfl/', 'faithful.mp3', 'adj.忠诚的，忠实的', 'i_4_10568_0_5_151222172151-gigapixel-scale.jpg', '20140927_02_21_04_674_v3.png', 'Dogs are the most faithful pets you can have.', '狗是你可以拥有的最忠诚的宠物。', '4d6f1709ec156b55_1266883003332123156_250207.mp3', 'faith忠诚 + ful表形容词 → faithful忠诚的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1803, 'flight', '/flaɪt/', 'flight.mp3', 'n.航班；空中航行', '3fec345a27f838d615e6d42134bf8464_80164_1583400242.jpeg', 'd_24_6636_0_4_20150808224700.png', 'The flight information is shown on the big screen.', '航班信息显示在大屏幕上。', 'fc55eac93443d8d8bcc60c469d32a9cc_77216_1594799116.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1804, 'fly', '/flaɪ/', 'fly.mp3', 'v.飞，飞行，飞翔；  n.蝇，苍蝇', '20120523_05_11_20_221-gigapixel-scale.jpg', '20140926_21_29_27_675_v3.png', 'I\'d like to fly up towards the sun', '我想像老鹰一样高高飞向太阳。', 'gzk98kb67hug2rg64utwkn4hlvqwj4n3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1805, 'fool', '/fuːl/', 'fool.mp3', 'n.笨蛋，傻瓜；  v.玩弄', 'i_1_7267_0_4_150919094940-gigapixel-scale.jpg', 'd_24_7267_0_3_20150808225101.png', 'He is such a fool that he can\'t answer this question.', '他连这个问题都答不出，真是个傻瓜。', '5b3a8e0a0096f2df_1266883621137525732_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1806, 'for the better', '/fɔːr ðə ˈbetər/', 'for the better.mp3', 'phr.好转', 'c592197da93b86308f64967f27d20c71.jpg', '', 'He believed that this guide would help him change his life for the better.', '他相信这本指南将会帮助改善他的生活。', 'd1a89a4425bb8fc962806609b1a210f4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1807, 'fortunate', '/ˈfɔːrtʃənət/', 'fortunate.mp3', 'adj.幸运的，吉利的', '3dffd77a2879794e4f7ab887efbe3367_57191_1700203453.jpeg', 'd_24_6308_0_4_20150808224553.png', 'People believe that four-leaf clover is a fortunate symbol.', '人们认为四叶草是幸运的象征。', 'us_People_believe_20231207094851256_3eeb81989bc01a43a679.mp3', 'fortun=fort运气 + ate…的 → fortunate幸运的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1808, 'German', '/ˈdʒɜːrmən/', 'German.mp3', 'adj.德国（人）的；  n.德语', 'd53ce18d82c474dc1b2bd6f5cbdd4fd4_78353_1656922066.jpg', 'd_24_4950_0_3_20150808223712.png', 'Pretzel is a type of German bread.', '椒盐卷饼是一种德国面包。', '076cc1b294a8a616_1266763401222401018_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1809, 'glass', '/ɡlæs/', 'glass.mp3', 'n.玻璃杯', 'ec7edf732e301e7e31c972e8f32090c9_77712_1575363260.jpeg', 'd_24_18017_0_4_20150808234234.png', 'I like collecting glasses of all shapes and sizes.', '我喜欢收集各种形状、大小的玻璃杯。', '90b6dc369c147f49_1266763242102741666_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1810, 'graph', '/ɡræf/', 'graph.mp3', 'n.（曲线）图，图表', 'i_1_6645_0_3_20150808125311-gigapixel-scale.jpg', 'd_105_6645_0_2_20150809055855.png', 'He is sitting in front of a computer and reading a lot of graphs.', '他正坐在电脑前看各种图表。', '0af47f5ce8651e442be1ddd50852b1e2_21205_1625797819.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1811, 'gross', '/ɡroʊs/', 'gross.mp3', 'adj.总的，毛重的；  n.总量，总额；  adv.总共地', '1425952792513-gigapixel-scale.jpg', 'd_107_4506_0_2_20150809005847.png', 'The gross cost for all these things is very high.', '这些东西的总成本很高。', 'sa_1_4506_0_2_20150808122834.aac', 'gross=great大 → gross总共的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1812, 'ground', '/ɡraʊnd/', 'ground.mp3', 'n.地，地面', '71ac56b94fd37b2b97b882be2d8dc7d4_99507_1577952268.jpeg', 'd_24_15915_0_3_20150808230818.png', 'The man is lying on the ground.', '这个男人正躺在地上。', 'cpwwcz6xwcg35ebh5lmqwj6spk4v3tuw.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1813, 'guidance', '/ˈɡaɪdns/', 'guidance.mp3', 'n.指导，引导', '61f3bd4d5f78d4666abdd334a7f1c1d3_140598_1731316311.jpg', 'd_16_7966_0_3_20150808232251.png', 'The coach is giving the players some guidance.', '教练正在给球员们提供指导。', 'us_The_coach_20241118104612333_e05f1d46344f46d24360.mp3', 'guid(e)指南 + ance名词后缀 → guidance指导', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1814, 'hall', '/hɔːl/', 'hall.mp3', 'n.会堂，礼堂', '9c2a4777bfbb9f6209d8608d396b2e2b_94744_1577952395.jpeg', 'd_24_15926_0_4_20150808230839.png', 'The conference hall with red chairs is empty.', '这个配有红色椅子的会堂空空荡荡的。', 'll39sswxd5jq2mwdyh8vkqy6plv5k972.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1815, 'harmful', '/ˈhɑːrmfl/', 'harmful.mp3', 'adj.有害的', '4a5521238f79d4378e006aaf69c5cd63_134284_1588084460.jpeg', 'd_16_7159_0_4_20150808231616.png', 'Poor posture can be very harmful to one\'s back.', '错误的坐姿对人的背部非常有害。', 'e91ce3392dcee033_1266883490119396282_250207.mp3', 'harm伤害 + ful形容词后缀 → harmful有害的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1816, 'heart', '/hɑːrt/', 'heart.mp3', 'n.心，心脏', 'b5228738748b999af8e5be437a5d76fb_113600_1522660815.jpg', 'd_24_16467_0_3_20150808231340.png', 'I gave you my heart. Treat it nicely', '我把心给你了，请好好待它。', 'yzlhcfw37vsvzdl9yfesc6mgytvxdzev.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1817, 'holiday', '/ˈhɑːlədeɪ/', 'holiday.mp3', 'n.节日，假期', '3_0_20170701114340_42786_c-manual-scale.jpg', 'd_24_15941_0_4_20150808230922.png', 'People are enjoying their holiday from work.', '人们享受着他们的假日。', '3qgvyvam3nuqt6znrag4lvqfhzp3en27.mp3', 'hol神圣 + i + day日子 → holiday节假日', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1818, 'horsepower', '/ˈhɔːrspaʊər/', 'horsepower.mp3', 'n.马力', 'eadcf461f53522ffedaf2a9e0aadc972_169144.jpg', 'd_103_11502_0_3_20150809034345.png', 'The maximum output of this engine is two hundred horsepower.', '这台发动机的最大输出功率是200马力。', '8ed7da15f1f3fa7f_1266883539605892054_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1819, 'identify', '/aɪˈdentɪfaɪ/', 'identify.mp3', 'v.识别出；认出；确定，鉴定', 'fc4cc194fe4dfaafdaae7c2ca3a59f15_269546_1734420277.jpg', 'd_107_5627_0_2_20150809013223.png', 'Your fingerprints are so unique that they can help the police identify you.', '你的指纹是独一无二的，所以它们可以帮助警察识别出你的身份。', 'abeflxs9zvfgb72jg8zkdpynjus8u5wz.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1820, 'in addition to', '/ɪn əˈdɪʃən tu/', 'in addition to.mp3', 'phr.除……之外（还）', '5_48_105_20161121144306_62902_c.jpg', '', 'In addition to dessert', '除了甜点外，他还点了一杯咖啡。', 'dfc2107a9467fb15_1266883375015090758_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1821, 'in no time', '/ɪn noʊ taɪm/', 'in no time.mp3', 'adv.立刻', '1df41bf01827e1c3ad82c22ec09a3281_86447_1588922814.jpeg', '', 'My father is not far away from me', '我父亲离我不远，所以他应该马上就能到。', 'asjf2n5tmevv9z35x3mx7stchnnzujf8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1822, 'in the end', '/ɪn ðə end/', 'in the end.mp3', 'phr.最后，终于', 'b15e63946e76bb17a20ee3faa6df144d_176422_1605082970.jpg', '', 'In the end', '最终，每个奔跑者都是赢家。', '9da82ab87736457c_1266883326376782806_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1823, 'increase', '/ɪnˈkriːs/', 'increase.mp3', 'v.增加，增长，增多', 'eab3959428e5859ea7d4b37fbe741b6d_100051_1584956000.jpeg', 'd_24_4915_0_3_20150808223642.png', 'The population has increased dramatically in recent years.', '近年来，人口急剧增加。', 'd16dac3bc52fcb7e_1266883530116455066_250207.mp3', 'in向内 + crease生长 → increase增加', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1824, 'industry', '/ˈɪndəstri/', 'industry.mp3', 'n.工业，产业', '9a18e9ea43a551094a1e9368d7b830aa_102404_1565282215.jpg', 'd_24_4903_0_4_20150808223624.png', 'Heavy industry is important for our economy. ', '重工业对于我们的经济很重要。', 'd1a36879c66c3e8215162bbd552f8e23_17130_1619333714.mp3', 'indu在..中 + stry构建，传播 → 在...中建设 → industry工业，勤劳', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1825, 'kick', '/kɪk/', 'kick.mp3', 'v.踢；踢腿；  n.踢', 'b1ae16de587a3b4d0b02f0c1590f39dd_110017_1732849376.jpg', '20140929_22_20_43_878_v3.png', 'The soccer player kicked the ball into the net. Goal!', '这个足球运动员把球踢进了网里，得分了！', 'px45g8759d93wed6qw8bgaezq3l4x89h.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1826, 'lay', '/leɪ/', 'lay.mp3', 'v.搁放，放置；铺放；下蛋；躺（lie的过去式）', '3_0_20160723070823_65121_c-gigapixel-scale.jpg', 'd_94_13243_0_4_20150809010105.png', 'The mother carefully lays the baby on the bed.', '妈妈小心地把婴儿放到床上。', '50e017c851a9fb67_1266883371191458470_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1827, 'leave behind', '/liv bɪˈhaɪnd/', 'leave behind.mp3', 'phr.遗留', 'efa1156bf1b29f223e2c9069d9e50e6e.jpg', '', 'He was in such a hurry leaving the house that he left his phone behind.', '他急匆匆地出门，把手机忘在了家里。', '708decec5c2011a1db9970a5cd9d9e68.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1828, 'licence', '/ˈlaɪsns/', 'licence.mp3', 'n.许可证，执照', '5e8470fbcb35a6e94467c66ebc998393_131838_1701674832.jpeg', 'd_16_4732_0_2_20150808224353.png', 'See! I told you I have a driving licence!', '看吧！我都跟你说了我有驾照的！', '3_0_20170721071602_10782_c.aac', 'licen=allow允许 + ce → licence特许，许可证', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1829, 'loaf', '/loʊf/', 'loaf.mp3', 'n.一条（面包）；  v.虚度光阴', '3506c13f535c2eaffae5ec17a643c3a9_183592_1556346201.jpeg', 'd_16_6526_0_2_20150808230755.png', 'The loaf of bread has been cut into slices.', '这条面包被切成了很多片。', 'a8fd9a707a27c2a1_1266763450214865412_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1830, 'look for', '/lʊk fɔr/', 'look for.mp3', 'phr.寻找', 'd3ee2c0060b1d8e9ed989348e9d23b60_118869_1701675863.jpeg', '', 'Is this the right place to look for science fiction novels?', '这是找科幻小说的地方吗？', 'f808e3993e546764_1266763399788800980_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1831, 'look forward to', '/lʊk ˈfɔːrwərd tu/', 'look forward to.mp3', 'phr.（兴奋地）盼望，期待', '44960653a7b4d23e2751314dae40c377_171457_1588931039.jpeg', '', 'He is looking forward to seeing her after receiving her reply.', '收到她的回复后，他就一直盼望着能见到她。', '25ed699799b11e9f_1266763553638669016_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1832, 'look in', '/lʊk ɪn/', 'look in.mp3', 'phr.顺便拜访', '0a00879ba16188ea38ae0667e1d9faa3.jpg', '', 'He looked in on his grandmother on his way to the shops.', '他在去商店的路上顺便看望了他的奶奶。', 'db76d8bf1a937e1c610c56114eec2de0.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1833, 'lovely', '/ˈlʌvli/', 'lovely.mp3', 'adj.美丽的，可爱的；令人愉快的', 'i_13_15994_0_2_20150808203625-gigapixel-scale.jpg', 'd_24_15994_0_3_20150808230954.png', 'The baby had lovely eyes.', '宝宝有一双可爱的眼睛。', 'ae95a7ca291e7331_1266763242290895526_250117.mp3', 'love爱 + ly表形容词 → lovely可爱的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1834, 'manager', '/ˈmænɪdʒər/ ', 'manager.mp3', 'n.经理，管理人', '4ba3f72d1d04ed8f4f92be306547c5b1_127021_1577936198.jpeg', 'd_24_15920_0_3_20150808230828.png', 'The manager has three employees under her.', '这名经理手下管理着三名员工。', 'ur8gfk5r5arzgh4kru4b2rmkzbn5z3zj.mp3', 'man手 + age表名词 + er表人 → 用手进行管理的人 → manager经理', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1835, 'mask', '/mæsk/', 'mask.mp3', 'n.面具；遮蔽物；伪装；  v.隐藏；掩盖，掩饰；伪装', 'dbd6a6c35de2a51752f191ef3cabcdb3_114176.jpg', 'd_24_5449_0_4_20150808224053.png', 'When he took his mask off', '当他摘下面具时，我看见了他完全不同的面貌。', '4v5entc8qx5dqqwewbsacxjdqddqrpy3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1836, 'memorial to', '/məˈmɔːriəl tuː/', 'memorial to.mp3', 'phr.对……的纪念物', 'ea27592475ad988ddec67fc7916fd4c5.jpg', '', 'The statue is a memorial to Kongzi.', '这是一座孔子的纪念雕像。', '1b5adcc80a80ad128f28d7722ec7c8a0_40352_1593586461.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1837, 'merchant', '/ˈmɜːrtʃənt/', 'merchant.mp3', 'n.商人；批发商', 'c_i_wm_20120311_03_35_44_783-gigapixel-scale.jpg', 'd_16_1841_0_7_20150808223432.png', 'The fruit merchant gave me a good price on tomatoes.', '水果商给我的西红柿价格很实惠。', 'e0dd12eef8602a6892ea74335097fc99_25049_1621925112.mp3', 'merch交易 + ant表示人 → merchant商人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1838, 'mystery', '/ˈmɪstəri/ ', 'mystery.mp3', 'n.神秘（感）', 'e5ac30ebbbbcd2247d5ae7a083aa375f_88026_1617763343.jpg', 'd_1_9746_0_3_20150808131442.png', 'Why did it turn green? It\'s a mystery. ', '为什么它变绿了？这是一个谜。', '8dcebab625e549695701531e7ca1a16d_95352_1617763335.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1839, 'necessary', '/ˈnesəseri/', 'necessary.mp3', 'adj.必需的，必要的；  n.必需品', 'i_114_17418_0_2_20150809071834-gigapixel-scale.jpg', 'd_24_17418_0_4_20150808232753.png', 'A boat is necessary to get across the river.', '要过河就得有船。', 'sa_114_17418_0_2_20150809071834.aac', 'necess必要 + ary表示有……性质的 → necessary必要的；必然的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1840, 'objection', '/əbˈdʒɛkʃn/', 'objection.mp3', 'n.反对，异议', '3_0_20160528171009_9131_c-gigapixel-scale.jpg', 'd_1_6686_0_4_20150808125347.png', 'His objection made the other man feel unhappy.', '他的反对让另一个人感到不开心。', 'us_His_objection_20230905095005880_085ca3b8f2bd5430ea77.mp3', 'ob反对 ＋ ject投掷，扔 ＋ ion名词后缀 → objection反对', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1841, 'opposite to', '/ˈɑːpəzɪt tuː/', 'opposite to.mp3', 'phr.与……相反，截然不同', '6fabf2213585f90815e450a560dce6d3.jpeg', '', 'The outcome of the movie was opposite to what he had expected.', '这部电影的结局和他预料的相反。', '6c5406511c2515083fb6cac002974c68_27533_1621930637.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1842, 'ox', '/ɑːks/', 'ox.mp3', 'n.公牛', 'i_1_6238_0_4_20150808124901-gigapixel-scale.jpg', '20141010_01_19_02_459_v3.png', 'The strong ox is angry now.', '这头强壮的公牛现在很生气。', '4tzlrs9sbq9tbtxykfxvv7ry4e53kra8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1843, 'parallel', '/ˈpærəlel/', 'parallel.mp3', 'adj.平行的；相似的；  n.平行线；相似物；  v.与……相似；与……匹配', 'c030caba864f9c26cc9cc0c7b9687b70_159897_1552543908.jpeg', 'd_16_5710_0_2_20150808225729.png', 'The boy drew parallel lines in his exercise book.', '这个男孩在他的练习本上画平行线。', '69f359c50fcbb8e6289850f24f994abd_27473_1552543928.mp3', 'para在旁边 + llel互相 → parallel平行的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1844, 'paste', '/peɪst/', 'paste.mp3', 'v.粘贴；  n.糊状物，糨糊', '3_41_20161205114906_43676_c-manual-scale.jpg', 'd_1_8769_0_2_20150808130937.png', 'I\'m pasting wallpaper to the wall.', '我正在把墙纸粘贴到墙上。', 'bf4guxfgxn5zgscv37cfhbs8azan79vf.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1845, 'phase', '/feɪz/', 'phase.mp3', 'n.（月亮的）变相；盈亏；方面；阶段，时期', 'cb8ad21b06b8964f1df4f91c08daba31_33161_1565282036.jpg', '20141011_16_52_59_844_v3.png', 'The moon will pass through all of its phases in about one month.', '在大约一个月的时间里，月亮会呈现出所有的月相变化。', 'sa_1_5646_0_4_20150808124138.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1846, 'pocket', '/ˈpɑːkɪt/', 'pocket.mp3', 'n.口袋，兜，衣袋；  adj.袖珍的', 'i_1_8425_0_4_151019114435-gigapixel-scale.jpg', 'd_24_8425_0_3_20150808225710.png', 'I put my phone into my pocket.', '我把手机放进我的口袋里了。', 'n7gd5kpdtv3u7bale5w2rm443xg2svak.mp3', 'pock袋 + et=ellus小  → 小袋子  → pocket口袋', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1847, 'policeman', '/pəˈliːsmən/', 'policeman.mp3', 'n.警察(pl. policemen)', '3_0_20170712071803_37136_c-gigapixel-scale.jpg', '20121227_14_01_14_882.png', 'The policeman is chasing a thief.', '警察正在抓小偷。', '76967cbfef37bd11_1266763315028777650_250117.mp3', 'police警察 + man人 → policeman警察', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1848, 'polish', '/ˈpɑlɪʃ/', 'polish.mp3', 'v.磨光，擦亮；润饰，使优美；  n.完美；  adj.（Polish）波兰语的（读作/ˈpoʊlɪʃ/）', '028cd71c711b09dc8192f6d278927bf3_114966_1738813678.jpg', 'd_16_2677_0_2_20150808223612.png', 'The car needs to be polished regularly.', '这辆车需要定期抛光。', '5b13ebc38eb69058cce295a307961e54_36527.mp3', 'pol光滑 + ish动词词尾 → polish抛光，擦亮', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1849, 'process', '/ˈprɑːses/ ', 'process.mp3', 'n.步骤，过程；进程；  v.加工；处理', '9f13bbddd96fa9093f53fea1f914cdff_199746_1534219039.jpeg', 'd_24_8351_0_4_20150808225610.png', 'Follow the process to create a cute paw-shaped ice cream.', '按照这个步骤来做可爱的爪爪冰激凌吧。', '2ce1b57eff29cf1e_1266883620632877798_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
