INSERT INTO `words` VALUES (1851, 'reason with', '/ˈriːzn wɪð/', 'reason with.mp3', 'phr.说服，与…讲道理', '22fd9b6124143f3c9e7bc79be25ca70a.jpeg', '', 'Although he didn\'t want to', '他不想去游泳，但他妈妈还是和他讲道理，直到他同意。', '1565397da7530a2593a78032d568356e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1852, 'remedy', '/ˈremədi/', 'remedy.mp3', 'v.治疗；恢复；补救；  n.治疗；补救；矫正', '1dee6fa34d195e27e3a59b22f51aded3_201615_1584612618.jpeg', 'd_107_4513_0_2_20150809005925.png', 'He took some pills to remedy his cough.', '他吃了一些药丸来治疗咳嗽。', 'b6b720562aa99e3f92f6e157213707ca_47056_1584612616.mp3', 're再 + med救治 → 再次救治 → remedy治疗，补救', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1853, 'renew', '/rɪˈnuː/', 'renew.mp3', 'v.更新', '9bdc9bd637ece3e0aefcbede358786b2_185240_1538759249.jpg', 'd_107_6669_0_2_20150809020658.png', 'My landlord renewed my lease at the end of the year.', '我的房东在年底续签了我的租约。', 'ed6e887863a59c4bfb315a0ea648e44d_15562_1538759263.mp3', 're再次 + new使变新，恢复 → renew更新', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1854, 'report to', '/rɪˈpɔːrt tuː/', 'report to.mp3', 'phr.向 ... 报到', '7d77d8c2e81aca08e6fc6e1c72932139.jpeg', '', 'During this particular time', '在这个特殊时期，旅客需要到特定酒店报到。', 'ea216068686d744eb78f421b3ead909a_40352_1599550041.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
