INSERT INTO `words` VALUES (1857, 'respect', '/rɪˈspekt/ ', 'respect.mp3', 'n.敬重；  v.敬重，尊敬', '558e7afe25ec218012afa638f7ee84fa_89125_1701068672.jpg', 'd_16_10983_0_2_20150808235834.png', 'They bow to their customers as a sign of respect.', '他们会对客人鞠躬，以示尊重。', 'gnp392swg7zuea7wer79bqmq3gg8nhgs.mp3', 're再 + spect看 → 再看一眼 → respect尊敬', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
