INSERT INTO `words` VALUES (1869, 'slight', '/slaɪt/', 'slight.mp3', 'adj.轻微的，微小的；纤细的，瘦弱的；少量的；  n.轻视，蔑视', '3_0_20161224072553_80165_c-gigapixel-scale.jpg', 'd_16_4715_0_4_20150808224345.png', 'There\'s a slight imperfection on this antique teapot.', '这个古董茶壶上面有一个小瑕疵。', '3_0_20161224072553_14842_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
