INSERT INTO `words` VALUES (1873, 'struggle', '/ˈstrʌɡl/', 'struggle.mp3', 'v.奋斗，拼搏；挣扎；  n.奋斗；斗争', '3_0_20170721071249_61096_c-gigapixel-scale.jpg', 'd_24_8414_0_4_20150808225657.png', 'She\'s struggling to reach the top of the cliff.', '她为了自己登顶的目标而奋斗。', '3_0_20170721071249_5054_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
