INSERT INTO `words` VALUES (1875, 'threat', '/θret/', 'threat.mp3', 'n.威胁，恐吓', '3_66_20170815103510_57402_c-gigapixel-scale.jpg', 'd_1_5596_0_2_20150808124043.png', 'The big guy is making a threat to the man in blue.', '这个大块头正在威胁那个穿蓝衣服的人。', '848128d2b1c1bbf1848b794b3968e0a5_24800_1524818022.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1876, 'university', '/ˌjuːnɪˈvɜːrsəti/', 'university.mp3', 'n.大学', 'e921a4dd3f81aea611904b28391a2040_139938_1559036104.jpeg', 'd_24_15914_0_4_20150808230816.png', 'Tsinghua University is one of the most famous universities in China.', '清华大学是国内最知名的大学之一。', 'r6t3khmzxg2nestet5m57jeyqbapvsvq.mp3', 'univers宇宙 + ity名词 → 由宇宙引申为知识，知识之地 → university大学', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1877, 'usage', '/ˈjuːsɪdʒ/', 'usage.mp3', 'n.使用，用法', '78ab8f2067752fc6ea2710424b796976_182096_1558596187.jpeg', '20140911_14_28_40_911_v3.png', 'The teacher wrote the correct usage of the word on the board.', '老师在黑板上写了这个单词的正确用法。', '7c5fd738447fb619e369d511301135f7_25985_1621930519.mp3', 'us用 + age状态 → 用的状态 → usage用法；惯例', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1878, 'utility', '/juːˈtɪləti/', 'utility.mp3', 'n.用途，功用；  adj.通用性的', 'i_1_6979_0_3_20150808125711-gigapixel-scale.jpg', 'd_1_6979_0_3_20150808125711.png', 'A Swiss Army knife isn\'t a thing of beauty', '瑞士军刀不是什么好看的东西，但它确实有它的用途。', 'us_A_Swiss_20230724130102398_f4bf3568a0b1abfe0f4a.mp3', 'util用 + ity名词后缀，状态 → utility公用事业，有用', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1879, 'wool', '/wʊl/', 'wool.mp3', 'n.（羊等动物的）毛', 'i_1_6267_0_3_20150808124923-gigapixel-scale.jpg', 'd_24_6267_0_3_20150808224541.png', 'Lend me your wool please. I\'ll make a pretty sweater for you.', '借我点儿你的羊毛，我要给你织一件漂亮的毛衣。', 'bde1f71a6d3e2078_1266883011644447468_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1880, 'accent', '/ˈækˌsɛnt/', 'accent.mp3', 'n.口音，腔调；重音符号；  v.强调（读作/ækˈsɛnt/）', '3de83978d45f3db83812148e6376e7c5_195625_1574927939.jpeg', 'd_24_18591_0_4_20150808235521.png', 'The word \'tomato\' is pronounced differently in British and American accents.', '\'番茄\'在英式口音和美式口音中的发音不同。', 'us_The_word_20241009160146348_1c02cfabb22bbfa9e534.mp3', 'ac=ad去，向 + cent唱歌 → 说话像唱歌 → accent口音；重音', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1881, 'accident', '/ˈæksɪdənt/', 'accident.mp3', 'n.不测，事故；意外遭遇', '819786c2f7fe6c3ae01556a6d85310c5_166667_1545460954.jpeg', 'd_24_7908_0_3_20150808225214.png', 'An accident happened', '鸡蛋意外摔倒，然后碎了。', 'jhp4hes66yreyn4g5jspz4m6czmvuvhs.mp3', 'ac强调 + cid降下 + ent为名词词尾 → 偶然降临的事 → accident偶然的事，意外', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1882, 'add up to', '/æd ʌp tu/', 'add up to.mp3', 'phr.总计', '5gjt6jnngl7uc8pqu3jkla2tvgbz84u7.jpg', '', 'One and one add up to two.', '一加一等于二。', 'sa_105_17355_0_2_20150809062326.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1883, 'all the time', '/ɔl ðə taɪm/', 'all the time.mp3', 'adv.一直；始终', 'allthetime_9054_20231106_ed66cfad.jpg', '', 'We\'re open all the time', '我们一直开着门，所以你可以随时来。', 'fb0b31652bc28391_1266798144953101274_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1884, 'America', '/ə\'merɪkə/', 'America.mp3', 'n.美国；美洲', 'c0a2b74ba567808ff35b42cd5bbcd4d2_32178_1656664005.jpg', 'd_24_17551_0_4_20150808232941.png', 'Statue of Liberty is a famous symbol of America.', '自由女神像是美国著名的象征。', '9219e17cdec6387b_1266763448913844958_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1885, 'apologize to sb. for sth.', '/əˈpɑːlədʒaɪz tuː ˈsʌmbədi fɔːr ˈsʌmθɪŋ/', 'apologize to sb. for sth..mp3', 'phr.为某事向某人道歉', '5f975ea877dbf2d6728c9530230559e6.jpg', '', 'This little girl apologized to him for spilling ice cream on his pants. ', '这个小女孩为不小心把冰激凌溅到他裤子上向他道歉。', '450f51b45fc146f692d5195417ee9c95.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1886, 'April', '/ˈeɪprəl/', 'April.mp3', 'n.四月（略作Apr.）', 'c7f47635e0ef96cc9220128b9a09c5d8_146882_1578568364.jpeg', 'd_24_19580_0_4_20150809002142.png', 'Everything turns green in April as a result of all the rain it brings.', '四月带来了充沛的雨水，令万物呈现一派绿意。', 'ae05852f258dfae7_1266763399828888274_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1887, 'beautiful', '/ˈbjuːtɪfl/', 'beautiful.mp3', 'adj.美丽的，美好的', '3_0_20160520173316_1670_c-gigapixel-scale.jpg', 'd_24_18081_0_4_20150808234416.png', 'She looks beautiful in her new black shirt.', '她穿着新买的黑色衬衫，真好看。', 'xal6as73rb2f8b3f82dtyv3tewv7a8sj.mp3', 'beauti美丽 + ful……的 → beautiful美的，美丽的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1888, 'bread', '/bred/', 'bread.mp3', 'n.面包；食物', 'ce632d110daa6495d574c60b7ec65151_60293_1760080893.jpg', '20141015_14_20_21_629_v3.png', 'There is nothing more delicious than freshly baked bread.', '没有什么能比刚烤出来的面包更美味的了。', '5ad53e5a39199c48_1268213310566056890_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1889, 'celebrate', '/ˈselɪbreɪt/', 'celebrate.mp3', 'v.庆祝，庆贺；赞美', '46dc953b8b1254c925a738bc4369c580_641132_1710210487.jpeg', 'd_24_16671_0_4_20150808231845.png', 'The e-sports team is celebrating their championship victory.', '这支电竞队正在欢庆夺冠时刻。', 'd8ad3c45c6f8e678_1266883377823963858_250207.mp3', 'celebr庆祝 + ate表示做… → celebrate庆祝；歌颂', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1890, 'cell', '/sel/', 'cell.mp3', 'n.细胞；小隔间', 'b98a40f09a141ffe2d62c9b7d9806dc7.jpg', 'd_16_7124_0_2_20150808231520.png', 'White blood cells help protect our body.', '白细胞可以保护我们的身体。', 'zfamxde3vh2ldp4l9ag2ennvmlycbe2d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1891, 'central', '/ˈsentrəl/', 'central.mp3', 'adj.中心的；主要的', 'i_1_8353_0_2_20150808130615-gigapixel-scale.jpg', 'd_24_8353_0_3_20150808225611.png', 'We should all meet at a central point.', '我们都应该去中心点那儿碰头。', 'f7062e4740c2770a_1266763555192679176_250117.mp3', 'centr中心 + al形容词后缀 → central中心的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1892, 'ceremony', '/ˈserəmoʊni/', 'ceremony.mp3', 'n.典礼', '0e2037b804c18b9c1f9f9ce1086e92ca_183613_1663064776.jpg', '', 'The student was awarded her certificate during the graduation ceremony.', '这位毕业生在毕业典礼上被授予毕业证书。', '5b4e8a4c4dc890ab773ae004d251f3e9_45392_1574653011.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1893, 'close', '/kləʊz/', 'close.mp3', 'v.关闭；  adj.关闭的；亲密的；  adv.（空间或时间上）接近地，靠近地；  n.结束（读作/kloʊz/）', '9c035ca081bd38f061efff2a86209660_59793_1753695958.jpg', 'd_24_17283_0_3_20150808232559.png', 'The man is closing the door.', '这个人正在关门。', 'a54af692a6746ad7_1266883198964816464_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1894, 'conduct', '/kənˈdʌkt/', 'conduct.mp3', 'v.指挥；传导；进行；带领；  n.行为；引导（读作/ˈkɑnˌdʌkt/）', '6bec9c59f879d7ba4d15e6aee6ea1d91_83838_1522741368.jpg', 'd_16_9113_0_2_20150808233825.png', 'He is conducting an orchestra.', '他正指挥着一支交响乐团。', 'f223a22493b25ae3d7dfe596561853f9_25152_1522741384.mp3', 'con共同 + duct引导，带来 → 引导大家一起做→conduct指挥', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1895, 'country', '/ˈkʌntri/', 'country.mp3', 'n.国家', '7499b48537f161f96029c8c3dde7de81_211185_1656646350.jpg', 'd_24_17334_0_4_20150808232721.png', 'Each country has its own national flag.', '每个国家都有自己的国旗。', 'bnv8259bvfj5fmc3yabemq6sfsmwlp9p.mp3', 'counter相对，相反 + y名词后缀 → 相对于他国而言的本国土地 → country国家', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1896, 'cursor', '/ˈkɝːsər/', 'cursor.mp3', 'n.光标；（计算尺的）【计】游标，指针', '3_0_20160718114932_61899_c.jpg', '', 'Move the cursor and click OK', '移动光标并点击“确认”，你就可以登录进系统了。', '3_0_20160718114932_75410_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1897, 'desert', '/ˈdezərt/', 'desert.mp3', 'n.荒漠，沙漠（读作/ˈdezərt/）；  v.离弃（读作/dɪˈzɜːt/）', 'i_1_6343_0_4_151009181305-gigapixel-scale.jpg', 'd_24_6343_0_4_20150808224607.png', 'I finally found water in the desert.', '我终于在沙漠里找到水了。', 'e6c2f77eec5b05ab_1266883114947226560_250207.mp3', 'de分开 + sert加入，插入 → 不再加入 → desert离开', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1898, 'destroy', '/dɪˈstrɔɪ/', 'destroy.mp3', 'v.摧毁', '96b46bc10ccc0ca56cf6419c9b2e12f4_148761_1573805648.jpeg', 'd_24_6124_0_4_20150808224437.png', 'My dog destroyed my sofa.', '我的狗毁掉了我的沙发。', 'kfa4jx5j6hqpcngz9harnupl23smyg87.mp3', 'de向下，表否定 + stroy建立 → destroy毁灭', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1899, 'detect', '/dɪˈtekt/ ', 'detect.mp3', 'v.探测；察觉', '2f2d4cf20d8f9294cba57ea41009caf6_166817_1706770143.jpg', 'd_1_9011_0_3_20150808131131.png', 'The dog can detect drugs with its nose.', '狗可以用它的鼻子探测毒品。', '7dce604d06289f94_1266883525098429002_250207.mp3', 'de打开 + tect遮盖 → detect发觉，侦查', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1900, 'devote...to', '/dɪˈvot tu/', 'devote...to.mp3', 'phr.献身', 'b3aef102ddc7c7fec0320580ea059c86_160874.jpg', '', 'The monk devoted his life to his faith.', '这个僧人将他的一生都献给了信仰。', 'afbbd69c1a46901a9861c81793f70b3c_32923.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1901, 'disorder', '/dɪsˈɔːrdər/', 'disorder.mp3', 'n.混乱；紊乱；  v.使紊乱', '3_0_20160603095606_11585_c-gigapixel-scale.jpg', '20140819_11_21_07_329_v3.png', 'The room was in a state of disorder.', '这个房间混乱不堪。', '3_0_20160603095606_49849_c.aac', 'dis无 + order顺序 → 没有顺序 → 混乱', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1902, 'doubt', '/daʊt/', 'doubt.mp3', 'v.怀疑；  n.怀疑；疑惑，疑问', '3_49_20170228113124_64059_c-gigapixel-scale.jpg', 'd_24_9177_0_3_20150808230053.png', 'I really doubt whether aliens exist.', '我很怀疑外星人是否真的存在。', '0459f6e45ffb3d65_1266883322725161618_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1903, 'dough', '/doʊ/', 'dough.mp3', 'n.生面团', 'e33bf5f8a9802ebdb32a1c82ad6f9543_60063_1584517718.jpeg', '', 'Dough is a mixture of flour and water.', '生面团是面粉和水的混合物。', 'a9c11876fda2a6b3edb8337dd018bd46_31342_1584517715.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1904, 'driver', '/ˈdraɪvər/', 'driver.mp3', 'n.驾驶员，司机', 'f2dfe256f8426f4629bb0dab09e3fb97_88988_1577950947.jpeg', 'd_24_17729_0_3_20150808233332.png', 'The driver with a beard is very handsome.', '这位留着胡子的司机非常帅气。', '89cef2e276ca1101_1268213316053516994_250930.mp3', 'driv驾驶 + er表示人 → driver驾驶员，司机', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1905, 'duty', '/ˈduːti/', 'duty.mp3', 'n.责任，义务，本分', '377faf0a5a529b5cb8ae902e0ca40313_72142_1557221547.jpeg', 'd_101_12503_0_4_20150809040233.png', 'Everyone should carry out his duty conscientiously when at work.', '每个人在工作时都应该认真履行自己的职责。', 'f0350f2c3679c21735e57f8bafdc0c73_22615_1557221669.mp3', 'du=de离开 + ty有 → 有责任所以不能离开 → duty责任，义务', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1906, 'edge', '/edʒ/', 'edge.mp3', 'n.（悬崖、峭壁的）边缘；  v.（使）徐徐移动；给……开刃，使锐利', 'i_1_16055_0_4_160109171339-gigapixel-scale.jpg', 'd_100_12518_0_4_20150809032449.png', 'The chicken is so afraid when standing on the edge.', '站在悬崖边上时，小鸡感到非常害怕。', 'sa_1_16055_0_4_160111180021.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1907, 'enjoy', '/ɪnˈdʒɔɪ/', 'enjoy.mp3', 'v.享受……的乐趣，欣赏，喜爱', 'b926da25c59a863dc9c67ee535ac5443_48664_1736749066.jpeg', '', 'A birthday party should be an event everyone can enjoy.', '生日派对应该是每个人都能享受的事情。', '2e614808250e9af2_1266883377176992434_250207.mp3', 'en进入 + joy高兴 → 做高兴的事 → enjoy享受', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1908, 'envelop', '/ɪnˈveləp/', 'envelop.mp3', 'v.包围，包上；  n.信封（同“envelope”）', '0010f0999c6fcda7aa0ba89df8b4c047_100718_1586589974.jpg', '', 'The sea envelops the island.', '大海包围着这座小岛。', 'uk_The_sea_20250722160808886_67a64cbeed335831a68a.mp3', 'en在...里面 + velop包裹起来 → envelop包住', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1909, 'expensive', '/ɪkˈspensɪv/', 'expensive.mp3', 'adj.昂贵的，价格高的', '5139fbbd373278cd97dd0ce5d75fcfb3_77362_1736822335.jpg', '20141013_18_57_27_446_v3.png', 'These are so expensive! You shouldn\'t have bought them for me. ', '这些太贵重了！你不该买给我的。', '972fc71cea242e0607c63de323f897f1_23399_1619332848.mp3', 'ex出 + pens花费 + ive形容词后缀 → 要花钱的 → expensive昂贵的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1910, 'faith in', '/feθ ɪn/', 'faith in.mp3', 'n.对……的信心；宗教信仰', '4f7a35df2141e3509a3e405696a0c50d.jpeg', '', 'He had a strong faith in the health benefits of garlic.', '他坚信大蒜对健康有益。', '600aa5013d49c1b602738d8ee2aef7c8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1911, 'fame', '/feɪm/', 'fame.mp3', 'n.名声，声誉；  v.使有名，使著名', '3_0_20170930071557_12527_c-manual-scale.jpg', 'd_24_6001_0_4_20150808224419.png', 'The actor enjoys fame and loves the attention it brings him.', '这位男演员沉浸在名望中，并享受着由此带来的关注度。', '3_0_20170930071557_90387_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1912, 'handwriting', '/ˈhændraɪtɪŋ/', 'handwriting.mp3', 'n.笔迹', 'i_16_18192_0_4_151201094037-gigapixel-scale.jpg', 'd_24_18192_0_3_20150808235227.png', 'His beautiful handwriting is easy to read.', '他漂亮的笔迹清晰易读。', '010e35c0592efa43_1266763554299075304_250117.mp3', 'hand手 + writing写 → handwriting笔迹，书法', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1913, 'hide', '/haɪd/', 'hide.mp3', 'v.躲藏', '081d6482f7e15d3e0a66f20b7ec9bcbb_49567_1728438017.jpg', 'd_93_12976_0_4_20150809002043.png', 'The boy is hiding inside the big box.', '男孩就藏在这个大箱子里。', '2ab6122a62cc7d7c_1266883112050862978_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1914, 'immigrate', '/ˈɪmɪɡreɪt/', 'immigrate.mp3', 'v.移居入境', '994a2d07757c45ee7fac4b616e72a169_127569_1544604402.jpg', '', 'He is filling in the visa application form and plans to immigrate.', '他正在填写签证申请表，准备移民。', 'd32a9c2ff4466dee8b9c837eb831e0e1_20108_1544604429.mp3', 'im向内 + migrate移居 → immigrate移居国内', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1915, 'improvement', '/ɪmˈpruːvmənt/', 'improvement.mp3', 'n.改进，改善，进步', 'i_1_9096_0_2_20150808131204-gigapixel-scale.jpg', 'd_1_9096_0_2_20150808131204.png', 'I hope our sales show some improvement soon.', '我希望我们的销售很快会有所改善。', 'xxd73kq7xs43nzemq4z327a8s2fh2ufk.mp3', 'improve改善 + ment名词后缀 → improvement 改善', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1916, 'injury', '/ˈɪndʒəri/ ', 'injury.mp3', 'n.受伤，伤害；损伤', '43f3924800dd681aa3f10fccf4e6cd7b.jpg', 'd_107_7147_0_2_20150809021526.png', 'The man picked up a knee injury when playing soccer.', '踢足球时，这个男人的膝盖受伤了。', 'ea03c5150c8266c7_1266883493399190054_250207.mp3', 'in不，相反 + jur公正，法律 + y表名词 → 违背法律的不公正行为 → injury伤害', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1917, 'insight', '/ˈɪnsaɪt/', 'insight.mp3', 'n.深刻的理解，洞察力', 'i_1_4092_0_3_20150808122328-manual-scale.jpg', 'd_107_4092_0_2_20150809004352.png', 'He really has an insight into math.', '他对数学真的有很深刻的见解。', 'sa_1_4092_0_7_151017113239.aac', 'in进入 + sight眼光 → 眼光看进去 → 洞察力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1918, 'instead of', '/ɪnˈstɛd əv/', 'instead of.mp3', 'phr.代替，作为...的替换', '3_0_20170713071259_64168_c.jpg', '', 'This little girl sings with a comb instead of a microphone.', '这个小女孩用梳子代替话筒唱歌。', 'd61d227a68f25399_1266883378435087088_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1919, 'introvert', '/ˈɪntrəvɜːrt/', 'introvert.mp3', 'n.内向的人，内弯（内翻）的东西；  v.使内翻，使内向，使内省', '3_0_20161103071434_86038_c.jpg', '', 'The introvert is covered with invisible walls.', '内向的人被无形的墙包裹起来.', 'ac62cb8114dacb90f5af3514b03de0bc_16033_1637567762.mp3', 'intro向内，入内 + vert转 → 向内转 → introvert内向', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1920, 'judgment', '/\'dʒʌdʒmənt/', 'judgment.mp3', 'n.判决，审判；判断', 'c_20150603_144147_1_5162-gigapixel-scale.jpg', 'd_24_5162_0_4_20150808223957.png', 'The court will make fair judgments.', '法院会做出公平的判决。', 'sa_1_5162_0_2_20150808123609.aac', 'judg判断 + ment名词后缀 → judgment判断，判断力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1921, 'least', '/liːst/', 'least.mp3', 'det.最少的，最小的；  adv.最少地，最小地', 'c4b328c0b55c805c42fc2f9bd4311917_91491_1720506634.jpg', 'd_109_18733_0_2_20150809063144.png', 'Of all the desserts', '在所有的甜点中，她最不喜欢冰淇淋。', 'us_Of_all_20240709145426537_d0674151e6c2fbed4834.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1922, 'liable for', '/ˈlaɪəbəl fɔːr/', 'liable for.mp3', 'phr.（在法律上）有义务，有责任', '3fc43c8493aed2e31744354b679453d4.jpeg', '', 'The cat\'s owner was liable for the damage his cat had caused. ', '猫的主人对猫造成的损失负有责任。', 'da702094aa9dcde55cd039cc6dd3edb8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1923, 'likely', '/ˈlaɪkli/', 'likely.mp3', 'adj.有可能的；适合的；  adv.很可能', '3_0_20170614071245_97297_c-gigapixel-scale.jpg', 'd_24_15280_0_4_20150808230642.png', 'It\'s likely that after thunder', '打雷后可能要下雨了。', '3_0_20170614071245_8934_c.aac', 'like可能 + ly……的/地 → likely可能的，很可能', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1924, 'mend', '/mend/', 'mend.mp3', 'v.修理，缝补', '8f5d9ea45b2adf025650c66325de496b_114993_1535946460.jpeg', 'd_24_9195_0_3_20150808230123.png', 'The man is trying to mend the damaged roof.', '这个男人正在尝试修补被损坏的屋顶。', '73d10c0976d6d9f691c5fee7c8c40b04_35305_1535946456.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1925, 'observation', '/ˌɑːbzərˈveɪʃn/', 'observation.mp3', 'n.观察；遵守', '29934695fe754cc6a17868d2ef887ebc_254125_1656661228.jpg', 'd_107_6142_0_2_20150809015052.png', 'Telescope observation revealed many secrets about the star.', '望远镜观测揭开了关于这颗恒星的许多秘密。', 'usmx3f3al9hg9tw4ygbu7ygphq4ltmhr.mp3', 'ob在前 + serve观看 + tion名词后缀 → observation观察，遵守', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1926, 'pause', '/pɔːz/', 'pause.mp3', 'v.暂停播放；暂停，中止；  n.中止，暂停', '93eae8833a6d6facf4d31cf4d1652f91_36412_1654159044.jpg', 'd_24_6190_0_3_20150808224516.png', 'I clicked on the screen and paused the video.', '我点击按钮暂停了视频。', 'us_I_clicked_20220602170701721_f8fc826fbb8b52c7e1e1.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1927, 'probably', '/ˈprɑːbəbli/', 'probably.mp3', 'adv.或许，大概', '5a9eea3bad8f49b4c338cd0351389ab2_125056_1542598547.jpeg', '20121227_14_02_18_478.png', 'It will probably rain later', '一会儿很有可能要下雨，所以我带了雨伞。', '3_0_20170703171752_87980_c.aac', 'probab=probable可能的 + ly表副词 → probably或许，大概', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1928, 'pronunciation', '/prəˌnʌnsiˈeɪʃn/', 'pronunciation.mp3', 'n.发音', '3_0_20170712071133_98584_c-gigapixel-scale.jpg', 'd_94_13845_0_4_20150809010210.png', 'These different mouth shapes can help us practice our pronunciation.', '这些不同的嘴型能够帮助我们练习发音。', '362fee4537ea4ed4efb70edaf34f79ee_23242_1619318570.mp3', 'pro在前 + nunci讲话，说出 + ation名词后缀 → pronunciation发音', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1929, 'quite', '/kwaɪt/', 'quite.mp3', 'adv.很，非常', '680589ba52760965caefb93bbc7e27c2_74089_1738813791.jpg', 'd_24_18603_0_4_20150808235534.png', 'The girl in the front is quite tall compared to the girl behind.', '和后面的女孩相比，前面那个女孩相当高。', 'us_The_girl_20250206115031489_3a8c2903dcb359f19229.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1930, 'reality', '/riˈæləti/', 'reality.mp3', 'n.现实，实际', '17294b9dc400054d8a3e994ff03ce443_196143_1588230014.jpeg', '20121225_19_39_21_621.png', 'The photo without filter makes me realize the reality.', '没有滤镜的照片使我认清了现实。', 'a82d266db97afd87_1266883374167448094_250207.mp3', 'real真实的 + ity名词后缀 → reality现实，真实', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1931, 'repair', '/rɪˈper/', 'repair.mp3', 'v.修理；补救；  n.维修', '8f6e9072e9987489711c7c14f85ec426_85922_1533091695.jpeg', 'd_16_6227_0_2_20150808230426.png', 'My mobile phone is being repaired at a phone store.', '我的手机正在一家手机店里维修。', 'eb7284aaafb4de4d_1266883113718340272_250207.mp3', 're再 + pair回到最初状态 → 重新恢复正常 → repair修理', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1932, 'right', '/raɪt/', 'right.mp3', 'n.权利', 'be45264517ccaee43dafb01ef86081b6.jpeg', 'd_24_17660_0_4_20150808233224.png', 'They have the right to vote.', '他们享有选举权。', '71825262aae41f930c01f01d4b1c31e6_18176_1599551082.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1933, 'routine', '/ruːˈtiːn/', 'routine.mp3', 'n.常规；  adj.例行的，惯例的', '6fbbe6d02c0fe3acefdbe296f5dd661b_95646_1580887047.jpg', 'd_16_3946_0_2_20150808223850.png', 'Going to school and reading books are parts of her daily routine.', '上学和看书是她日常生活的一部分。', '753714d21bba396a665a2349e7cb4754_46283_1580887366.mp3', 'rout(e)路线 + ine形容词后缀 → 路线设置好的 → routine常规的，例行的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1934, 'sample', '/ˈsæmpl/', 'sample.mp3', 'n. (用于检验、分析的) 试样，样品；  adj.样品的，作为例子的；  v.抽样检查；抽取……的试样', 'c62c4a59033f400664830ed798aa5857_48023_1597128823.jpg', 'd_1_5084_0_2_20150808123446.png', 'I\'ll need a sample of your blood to see if you\'re sick.', '我需要你的血样来确定你是不是生病了。', 'p8xpyq5373uy7ktd2ef4crhvhj5nbgxd.mp3', 's分开 + ample拿 → 分开拿出 → sample标本', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1935, 'scale', '/skeɪl/', 'scale.mp3', 'n.天平，磅秤；刻度，尺度，标度；等级，级别，等级体系；鳞片，鳞状物；规模；水垢，牙垢；  v.攀登；按比例决定；称重；刮鳞，剥落', '15a58f903a7e98fef4f1d79fc9715af4_106232_1532938557.jpeg', '20140928_05_05_03_8_v3.png', 'Stand on the weighing scale to get your weight.', '站在体重秤上来测你的体重吧。', 'b0ce4f1aa5bad29a485ab5dde6e6f9e8_15092_1619159554.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1936, 'sense', '/sens/', 'sense.mp3', 'n.感官；  v.觉得，意识到', 'i_1_8083_0_5_150917170033-gigapixel-scale.jpg', 'd_24_8083_0_3_20150808225421.png', 'I\'m blind', '我是盲人，但是我能用我的触觉来读这本书。', '0a72de05facd8f7fb323d4e5a56dbb29_24810_1619163961.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1937, 'sensitive to', '/ˈsensɪtɪv tu/', 'sensitive to.mp3', 'phr.对……敏感', 'a71dbc5ce3a73cbc46273e3b1d7295b8.jpeg', '', 'He is very sensitive to being touched.', '他对被触碰太敏感了。', 'ee531dfc7e19d24ce99ae281a2fd04a8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1938, 'shake', '/ʃeɪk/', 'shake.mp3', 'v.摇动；  n.摇；颤抖', '9d7efc1c99d690c3d3a70661f6ca8cba_111076_1574847164.jpeg', 'd_24_17035_0_4_20150808231951.png', 'Shake the bottle well before drinking.', '饮用前请摇晃瓶子。', 'd56e57f093ebd961_1266883493566962218_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1939, 'shine', '/ʃaɪn/', 'shine.mp3', 'v.照耀，闪光；  n.光泽，光', 'da79e1a9b0016cdd5d0d7b77c035953c_95234_1588088214.jpeg', 'd_24_19576_0_3_20150809002117.png', 'The sun is shining in the sky.', '太阳在天空中熠熠闪光。', '0729825fef79c680_1266763401481530114_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1940, 'stay', '/steɪ/', 'stay.mp3', 'v.保持；继续是', 'd01a864fef391648f8d13376110fc248.jpg', 'd_24_17185_0_4_20150808232314.png', 'Some shops stay open 24 hours a day.', '一些商店24小时营业。', '9ed0c93f694de5c6_1266883376637368978_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1941, 'steal', '/stiːl/', 'steal.mp3', 'v.偷盗，窃取；  n.便宜货', '9516b2be0bb783144dfff68da61622ef_87789_1535955248.jpeg', 'd_24_18166_0_4_20150808235119.png', 'The thief is trying to steal his wallet.', '小偷正试图偷他的钱包。', '9cd54b0750977248_1266883329231334148_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1942, 'sufficient', '/səˈfɪʃnt/', 'sufficient.mp3', 'adj.足够的，充足的；充分的', '43ada66227caaeac10f15102a165d4a7_173206_1595058482.jpg', 'd_1_4735_0_3_20150808122941.png', 'The animal has sufficient food for the winter.', '这只动物有充足的食物来过冬。', '53cd0c4eeb9318e7_1266883490961447658_250207.mp3', 'suffic足以 + ient形容词后缀 → sufficient 足够的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1943, 'swim', '/swɪm/', 'swim.mp3', 'v.游泳；眩晕；  n.游泳', 'e9f21b7daed87f4e16c2deb395d74c28_89093_1574928455.jpg', '20121225_19_52_49_596.png', 'She can swim like a fish! Look at her!', '看看她！她能像鱼一样游泳！', '2892f883eeba73de_1268213313053410254_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1944, 'throw away', '/θroʊ əˈweɪ/', 'throw away.mp3', 'phr.扔掉', '48c11b2a01383c6973dc62853f760d71.jpg', '', 'The man is throwing away the can.', '那个男人正在扔掉易拉罐。', '0497d20bdf26dedf_1266763552654601160_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1945, 'till', '/tɪl/', 'till.mp3', 'prep.直到……才；  conj.直到……才；  v.翻地，耕地；  n.放钱的抽屉', '9184cd8fe22fdf46f5567303fde52bef_95707_1639640558.jpeg', 'd_109_5114_0_2_20150809054024.png', 'He continued working till night.', '他一直工作到了晚上。', 'd2aa2a6e497c5e1fcec8394d9a950090_12585_1639640526.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1946, 'understand', '/ˌʌndərˈstænd/', 'understand.mp3', 'v.理解，明白', 'fa66caa23e7d5ae4ba49a46a81c86db5_81867_1732521840.jpg', 'd_24_17345_0_4_20150808232735.png', 'Ha! I understand now!', '哈！我现在懂了！', 'sa_24_17345_0_4_20150808232735.aac', 'under在下面 + stand站立、立场 → 同一立场的 → understand理解，明白', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1947, 'vain', '/veɪn/ ', 'vain.mp3', 'adj.徒劳的；徒然的，没用的；自负的', '3_0_20170930071326_19544_c-gigapixel-scale.jpg', 'd_16_5353_0_2_20150808225231.png', 'Throw away the chocolate', '扔掉那块巧克力，不然你为减肥所做的努力就白费了。', '3_0_20170930071326_28649_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1948, 'virtually', '/ˈvɜːrtʃuəli/', 'virtually.mp3', 'adv.几乎；实际上', 'ffd2b01dede902aa5cbe91c8fdf7b537_42278_1565705257.jpg', 'd_1_5103_0_2_20150808123508.png', 'The screen is so vivid that the pictures were virtually right there in front of me.', '屏幕里的东西那么栩栩如生，仿佛那些画面实际上就在我的眼前。', 'sa_1_5103_0_2_20150808123508.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1949, 'weigh', '/weɪ/', 'weigh.mp3', 'v.称重', '9472793a33ac3c931fefb83edc167993_61920_1577959317.jpeg', '20121225_19_11_21_620.png', 'Please weigh the apples and pears for me.', '请替我称一下苹果和梨的重量。', '25c2a117ba8bcbcf_1266883530446953120_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1950, 'wheat', '/wiːt/', 'wheat.mp3', 'n.小麦', '27204d2c84f4c7275fa40dba3e8dcc17_93933_1574838690.jpeg', 'd_24_17152_0_3_20150808232149.png', 'The golden wheat rippled in the breeze.', '金黄色的小麦在微风中荡漾。', '8zxylvqtan6u38jthc8xwv6hw9v3pza5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1951, 'work at', '/wɜːrk æt/', 'work at.mp3', 'phr.致力于', 'b7d515187589c3e4ba128567716cd2b3.jpeg', '', 'She keeps working at the violin', '她坚持拉小提琴，随着时间的推移而不断进步。', 'b3fc950a955c6b55f47f4b0b10a7a798_45166_1600070604.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
