INSERT INTO `words` VALUES (1960, 'current', '/ˈkɜːrənt/', 'current.mp3', 'adj.当前的，现在的；流动的；  n.水流', 'bedb29f83ff694aa5b3a9104f48fb1b0_273878_1706073970.jpg', 'd_1_7476_0_2_20150808125937.png', 'I can get all the current news instantly on my cellphone.', '我可以在手机上迅速获取所有的时事新闻。', '3_0_20160724071017_31817_c.aac', 'curr跑，发生 + ent具有……性质的 → 跑的 → current流动的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1961, 'damage', '/ˈdæmɪdʒ/', 'damage.mp3', 'v.破坏；  n.损坏，毁坏，破坏', 'bd5874043e46d035ac3fc6ae6086798f_98845_1601202883.jpg', 'd_16_16048_0_2_20150809001611.png', 'My car was badly damaged after hitting the tree.', '我的车在撞上树后严重损坏了。', 'xhytawluvyemntx787gjjeugdvtq43zd.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1962, 'debate', '/dɪˈbeɪt/', 'debate.mp3', 'n.辩论；讨论，争论；  v.辩论；议论', '29544917dbe7ce31d028b11dc042cc07_26605_1732158775.jpg', 'd_107_5534_0_2_20150809012914.png', 'The debate begins.', '辩论开始了。', '71cbc857968569cf_1266883377127730090_250207.mp3', 'de否定，相反 + bat打，击 + e → 持对方相反的观点而与之进行口头上的攻击 → 反驳，辩论', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1963, 'dialog', '/ˈdaɪəlɔːɡ/', 'dialog.mp3', 'n.对话（=dialogue）', '4245d39283583d7d82875f15684fc9bd_101455_1594801590.jpeg', 'd_109_6271_0_2_20150809054605.png', 'The two sides entered into a peace dialog.', '双方进行了一次和平对话。', '03d261af8524469764eba6cad8f107aa_66848_1594801594.mp3', 'dia穿过，之间 + log说话 → dialog对话', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1964, 'dirty', '/ˈdɜːrti/', 'dirty.mp3', 'adj.肮脏的，有灰尘的；  v.弄脏，玷污；  adv.不公平地，不诚实地', '81668dd99dd39045d5aa276dbae5dcc2_100206_1583140084.jpeg', 'd_24_18153_0_4_20150808235035.png', 'His hands are very dirty.', '他的手很脏。', 'a0c95bcee50b6892_1266763241553439644_250117.mp3', 'dirt灰 + y表形容词 → dirty肮脏的，有灰尘的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1965, 'distinct from', '/dɪˈstɪŋkt frəm/', 'distinct from.mp3', 'phr.与……截然不同，差别明显', '4f963796e497cc3c95647ce8076441dd.jpeg', '', 'The two rooms\' styles are very distinct from each other.', '这两个房间的风格明显不同。', 'a7bb9e3d4f3bb0c74938e9c0d2563617_21205_1619166271.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1966, 'dumpling', '/ˈdʌmplɪŋ/', 'dumpling.mp3', 'n.饺子', '3c00dd6f1c2d2df8ff5cbfe3a1c15e8f_127816_1575018672.jpeg', 'd_76_12499_0_4_20150809030858.png', 'I enjoy eating Chinese dumplings for lunch.', '我喜欢午饭吃饺子。', 'sa_64_12499_0_4_20150809011612.aac', 'dump无秩序的累积 + ling名词后缀，表示小 → 无秩序地累积的小东西 → dumpling饺子；团子', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1967, 'during', '/ˈdʊrɪŋ/', 'during.mp3', 'prep.在…期间', '1425952698348-gigapixel-scale.jpg', 'd_24_17421_0_3_20150808232757.png', 'It\'s rude to talk on the phone during dinner.', '在吃晚餐时打电话很没礼貌。', '3386f57d77a49116_1266883009192242094_250207.mp3', 'dur持久 ＋ ing构成介词 → during在…期间', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
