INSERT INTO `words` VALUES (1993, 'teenager', '/ˈtiːneɪdʒər/', 'teenager.mp3', 'n.（13～19岁的）青少年', '5059d868aea96cf892cf87880a6e55ed_89958_1595314350.jpeg', 'd_109_8476_0_2_20150809055627.png', 'Teenagers are always full of energy.', '青少年总是充满了能量。', 'd56a39bea4280dd8_1266883001095445228_250207.mp3', 'teen青少年 + age年龄 + r=er表人 → teenager青少年', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1994, 'telescope', '/ˈtelɪskoʊp/', 'telescope.mp3', 'n.望远镜；  v.缩短，精简；（使）套入；  adj.套筒的，伸缩式的', '4005dd4b8a20a8a292d8f32adba605ab_107407_1535180358.jpeg', 'd_105_8610_0_2_20150809061038.png', 'You can see many distant stars through the telescope.', '通过望远镜，你可以看到许多遥远的星星。', 'ztgn855dhjft72jfdsx6fg95bm3dqgzz.mp3', 'tele远，传送 + scope看 → 看远方 → 望远镜', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (1995, 'think over', '/θɪŋk ˈoʊvər/', 'think over.mp3', 'phr.仔细考虑', '49661f61d99bdcc47b526c3394f0d277_133410.jpg', '', 'I need to think over whether this plan could be implemented.', '我要仔细考虑下这个计划能否实行。', 'a0b7cd665794b9bce2cd4aa30f1ba485_37759.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
