INSERT INTO `words` VALUES (2000, 'unable', '/ʌnˈeɪbl/', 'unable.mp3', 'adj.不能的', 'i_13_17194_0_2_20150808204541-gigapixel-scale.jpg', 'd_16_17194_0_4_20150809004936.png', 'What to do? Obviously I\'m unable to climb these stairs in my wheelchair!', '我该怎么办？很明显我坐在轮椅上不能爬楼梯！', 'a25235d761690c73_1266883479264406426_250207.mp3', 'un不 + able能够…的 → unable不能的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2001, 'wherever', '/werˈevər/', 'wherever.mp3', 'conj.无论在哪里', 'i_1_17370_0_2_20150808132337-gigapixel-scale.jpg', 'd_109_17370_0_2_20150809062140.png', 'Wherever you want your package to go', '无论你想让你的包裹去哪儿，我们都能送达。', '2wf7hezamvy9bn7vaavv3vz43tnes4t2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
