INSERT INTO `words` VALUES (2013, 'chemical', '/ˈkemɪkl/', 'chemical.mp3', 'n.化学品，化学物质；  adj.化学的，与化学有关的', 'chemical_5090_7e70fca6d1_231213.jpg', '20121225_19_41_25_841.png', 'The scientist drew up some clear liquid chemical with a dropper.', '科学家用滴管吸取了一些透明的液体化学物质。', 'us_The_scientist_20250103133532133_fd5f0f5ec3ff93144499.mp3', 'chem化学 + ical……的 → chemical化学的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2014, 'classical', '/ˈklæsɪkl/', 'classical.mp3', 'adj.古典的；传统的；正统的；权威的', '1425952540371-gigapixel-scale.jpg', '', 'I love classical music.', '我热爱古典音乐。', '918d0857ca677fd0_1266883322863922062_250207.mp3', 'classic典型的 + al形容词后缀 → classical古典的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
