INSERT INTO `words` VALUES (2027, 'in other words', '/ɪn ˈʌðər wɜrdz/', 'in other words.mp3', 'phr.换句话说', '3_0_20170723071222_32486_c-gigapixel-scale.jpg', '', 'Time is money. In other words', '时间就是金钱，换句话说，节约时间就是节约金钱。', '3_0_20170723071222_85637_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
