INSERT INTO `words` VALUES (2031, 'leg', '/leɡ/', 'leg.mp3', 'n.腿，腿部', '678a4a3fc4466394e0fed1e05746cdc4_74737_1617763810.jpg', 'd_24_16470_0_4_20150808231345.png', 'This App can make the dog\'s legs look longer.', '这款应用能让狗狗的腿看起来更长。', '92604b973c56342a_1268213311612994500_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2032, 'little', '/ˈlɪtl/', 'little.mp3', 'det.几乎没有', 'afd0f47e995e56a7f3497721586b1dad.jpeg', 'd_24_17267_0_3_20150808232537.png', 'He paid little attention to what she was saying.', '他几乎没有注意她在说什么。', 'a170340c71f7a10d16b5d096c8e86a52.mp3', 'lit小的 + tle形容词后缀 → little小的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2033, 'meanwhile', '/ˈmiːnwaɪl/', 'meanwhile.mp3', 'adv.同时，与此同时；  n.其间', '9c135b4fd8ce4888d7e411b982ec25ab_83928_1729828154.jpg', '20130307_16_04_13_192.png', 'The hare decided to take a rest; meanwhile', '兔子决定休息一下，与此同时，乌龟还在继续前进。', 'cec4cdc4bb03df6f_1266883378874309124_250207.mp3', 'mean用意 + while同时 → meanwhile同时，当时', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2034, 'modification', '/ˌmɑːdɪfɪˈkeɪʃn/', 'modification.mp3', 'n.改造，修改', '4cba77889718fcd4740c37f6e58d5012_166419_1534152812.jpeg', '', 'He\'s making a big modification to the car.', '他正在对车子进行一次大的改造。', 'us_Hes_making_20241009154204280_994cec591644a450460b.mp3', 'mod方式，模式，风度 + ification名词后缀 → 修正', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2035, 'motion', '/ˈmoʊʃn/', 'motion.mp3', 'n.运动，移动', 'i_1_5091_0_3_20150808123455-gigapixel-scale.jpg', '', 'The slow motion clearly shows how he dodges the bullets.', '慢动作清楚地展现了他是如何躲过子弹的。', 'sa_1_5091_0_3_20150808123455.aac', 'mot=move移动 + ion名词后缀 → motion运动', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2036, 'oppose', '/əˈpoʊz/', 'oppose.mp3', 'v.反对；反抗', '3_45_20161215145233_89615_c-gigapixel-scale.jpg', 'd_16_5781_0_2_20150808225850.png', 'The boy opposes his father\'s smoking and tells him to stop.', '男孩反对父亲吸烟，并告诉他不要抽了。', 'sa_1_5781_0_4_20150808124405.aac', 'op反 + pose放 → oppose反对', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2037, 'overtime', '/ˈoʊvərtaɪm/', 'overtime.mp3', 'adv.加班地；超过规定时间地；  n.【体】加时赛', '9bd890609d8e48d111094aa3d40bddd2_99644_1585039214.jpeg', '20140824_01_48_36_211_v3.png', 'He often works overtime to get the job done.', '他经常加班来完成工作。', '192c93a371f46b09c49249b1709b1a4f_45118_1585039218.mp3', 'over过度 + time时间 → 加班时间；延长时间；[体]加时赛', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2038, 'plastic', '/ˈplæstɪk/', 'plastic.mp3', 'n.塑料，塑料制品；  adj.塑料的', '93c44e2e10b5d518fb5b9ea709c48906_45473_1732690861.jpg', '20141013_08_11_02_51_v3.png', 'All of this food packaging is made of plastic.', '这些食品包装都是塑料做的。', '17ff91bdc463cd52_1266763450901441312_250117.mp3', 'plast塑造 + ic……的 → 可塑的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2039, 'pleasure', '/ˈpleʒər/', 'pleasure.mp3', 'n.愉快，乐事', '92253523bceaef6647d2265f751d8cc4_90563_1577946191.jpeg', 'd_24_18761_0_4_20150808235718.png', 'The little girl takes pleasure in eating cakes.', '这个小女孩从吃蛋糕中获得快乐。', 'f573cb2f85494846_1266883330909121334_250207.mp3', 'pleas=please令人高兴的 + ure名词后缀，表行为、状态 → pleasure愉快', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2040, 'popularity', '/ˌpɑːpjuˈlærəti/', 'popularity.mp3', 'n.受欢迎，人气高', '1d9793107ead78e02dcf01d550e47c20_194067_1569050221.jpeg', '', 'His popularity is higher now than ever before.', '比起从前，他现在要受欢迎得多。', 'f5a5297bd149fa1a1076780adbab9010_44720_1595475385.mp3', 'popul人民 + ar……的 + popular流行的 + ity表名词 → popularity流行', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2041, 'position', '/pəˈzɪʃn/', 'position.mp3', 'n.姿势；职位；  v.安置', 'i_39_13786_0_4_20150809015711-gigapixel-scale.jpg', 'd_94_13786_0_4_20150809010159.png', 'He says he thinks better in that position', '他说他保持那种姿势时能更好地思考，但是我不是很确定他能做到。', 'sa_39_13786_0_4_20150809015711.aac', 'posit放(本身是一个单词，意为“认为，肯定”) + ion名词后缀 → 放出的[立场] → position立场', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2042, 'properly', '/ˈprɑːpərli/', 'properly.mp3', 'adv.适当地；得体地', '3_0_20170707172706_9027_c-gigapixel-scale.jpg', 'd_24_18892_0_4_20150808235914.png', 'It\'s important to adjust your sitting posture properly.', '适当地调整坐姿很重要。', 'us_Its_important_20241012133033632_6041368dba94df0f2e0d.mp3', 'proper恰当的 + ly...地 → properly正确地；恰当地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2043, 'recognize', '/ˈrekəɡnaɪz/', 'recognize.mp3', 'v.认出，辨别', 'c2565f84418093240b53f45117716437_1671810_1681096377-800-600.jpg', '20140929_02_50_28_780_v3.png', 'The little boy recognized his mother in the photo.', '小男孩认出了照片里的妈妈。', '1efdc2b09293d3b6_1266883013675100942_250207.mp3', 're再，重新 + cogn知道 + ize使 → 再次知道 → recognize认出来', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2044, 'regardless', '/rɪˈɡɑːrdləs/', 'regardless.mp3', 'adv.不顾；  adj.不顾的，不管的', '70ea264a28ffc443f41ee9925e1e45ce_185385_1538624633.jpg', '20130510_18_36_42_648.png', 'She goes running regardless of the cold weather.', '不论天气有多冷，她都去跑步。', 'us_She_goes_20241009153941811_8ad554073db6ef395b79.mp3', 'regard注意 + less表形容词，无……的 → regardless不注意的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2045, 'replace', '/rɪˈpleɪs/', 'replace.mp3', 'v.代替，接替；放回', 'i_1_5590_0_89_160406180717-gigapixel-scale.jpg', 'd_16_5590_0_2_20150808225524.png', 'Gradually', '机器人逐渐代替了工厂的工人。', 'sa_1_5590_0_89_160407100413.aac', 're重新 + place放，地方 → 重新放 → replace代替', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2046, 'satellite', '/ˈsætəlaɪt/ ', 'satellite.mp3', 'n.人造卫星', '6a5a0f3d403881271780462cdf0cf1b5_74990_1565706979.jpg', '20140929_02_54_10_427_v3.png', 'This space satellite transmits TV signals to Earth.', '这颗人造卫星把电视信号传输到地球。', 'sa_1_9251_0_4_20150808131325.aac', 'sate足够，全部 + llite去 → 全速前进 → 跟随者，随从follow → 人造卫星', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2047, 'second', '/ˈsekənd/', 'second.mp3', 'n.秒；第二名；  adv.第二，其次', '80ff0a7738546a69aec11b45a996a262_43624_1576913604.jpeg', 'd_16_15893_0_3_20150809000652.png', 'This digital clock is able to tell the time to the exact second.', '这个数字时钟能精确到秒。', 'e3f919482d8c9b70_1266798146422877156_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2048, 'secret', '/ˈsiːkrət/', 'secret.mp3', 'n.秘密；  adj.秘密的', '1eb5435c4439456c796792d3eef3c535_167162_1538581231.jpg', 'd_24_8096_0_4_20150808225436.png', 'The little girl is telling her mother a secret.', '这个小女孩正在告诉她的妈妈一个秘密。', 't345cz9g6g2escdlkfunjyfwzd4p5tsc.mp3', 'se分开 + cret区别 → 分开来放 → secret秘密', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2049, 'see', '/siː/', 'see.mp3', 'v.了解，领会', 'bc950b166519752030a9feec5dd2d967.jpeg', 'd_24_19466_0_3_20150809001402.png', 'I see your point now.', '我现在明白你的观点了。', 'us_I_see_20240204104357564_e3e0ab80e36e9da53c37.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2050, 'several', '/ˈsevrəl/', 'several.mp3', 'det.几个，一些；  adj.各自的，分别的', '3_0_20160520172224_49836_c-gigapixel-scale.jpg', 'd_24_15906_0_4_20150808230750.png', 'I have several apples for you!', '我给你准备了几个苹果！', '87439d39571811d3_1266883002843900678_250207.mp3', 'se分离 + veral准备好 → several各自的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2051, 'Spanish', '/ˈspænɪʃ/', 'Spanish.mp3', 'adj.西班牙的', '4c218751a55ad99e6882dd9c1261e4bd_105619_1695607892.jpg', 'd_24_10205_0_3_20150808230419.png', 'Bullfighting', '斗牛、海鲜饭和弗拉门科舞这些都与西班牙文化息息相关。', 'twdvd2wgycqa8ydd5xvmf3hl6c47awgn.mp3', 'span西班牙 + ish某国的 → Spanish 西班牙的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2052, 'star', '/stɑːr/', 'star.mp3', 'n.星，恒星', 'i_1_19476_0_2_20150808132622-gigapixel-scale.jpg', 'd_24_19476_0_3_20150809001458.png', 'There are many happy stars.', '这里有很多快乐的星星。', 'vykgplmgvjh5ds7kyqgdgardk6ptdsu7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2053, 'strengthen', '/ˈstreŋθn/', 'strengthen.mp3', 'v.增强', '3_0_20170709071219_77331_c-gigapixel-scale.jpg', 'd_16_4192_0_2_20150808224102.png', 'She keeps training every day to strengthen her arms.', '她每天坚持锻炼来使手臂变强壮。', 'cb76836d515597d4d90175cb47c955e4_18070_1619159685.mp3', 'strength力量 + en动词后缀  → strengthen加强', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2054, 'switch', '/swɪtʃ/', 'switch.mp3', 'n.开关', '82955db910b688a66500320619acb50f_22614_1565706516.jpg', '20130106_14_39_02_207.png', 'There are so many switches in your home! Which one turns on the lights?', '你家有这么多开关，哪一个能把灯打开？', 'sa_1_5750_0_4_20150808124332.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2055, 'take a fancy to', '/teɪk ə ˈfænsiː tu/', 'take a fancy to.mp3', 'phr.喜欢', 'aadb0fc7919a10b77be6c8a451462021.jpg', '', 'He takes a fancy to motorbikes.', '他喜欢摩托车。', '6fdd240ee0e1d3861ee5346b9d81a885_32288_1593575147.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2056, 'translation', '/trænsˈleɪʃn/', 'translation.mp3', 'n.译本；翻译；转变', '4ae0c7495b50ef5b84aa1a47736a6523_148883_1561953098.jpg', 'd_105_7261_0_2_20150809060315.png', 'The little boy is trying to do some translation exercises.', '这个小男孩正尝试着做一些翻译练习。', 'p2e2uggj275jp3t6l85sjqm7zkz7hcw2.mp3', 'translat=translate翻译 + ion表行为，状态 → 翻译', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2057, 'trust', '/trʌst/', 'trust.mp3', 'v.信任，相信；盼望，希望；  n.委托', '3_0_20160520172734_4287_c-gigapixel-scale.jpg', '20121225_19_13_51_81.png', 'My boss trusts me so much. I can\'t let him down.', '我的老板那么信任我，我不能让他失望。', 'f3d4361dddbd2933_1266883376360544900_250207.mp3', 'tru坚固，坚定 + st表名词  → （坚定地）相信  → trust信任', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2058, 'undo', '/ʌnˈduː/', 'undo.mp3', 'v.松开，解开', 'fe8f4d32004a23db6f9dacf61f231db1_33312_1565706225.jpg', 'd_16_4793_0_2_20150808224432.png', 'At the end of the day', '一天结束后，这个男人松了松领带。', 'sa_1_4793_0_2_20150808123030.aac', 'un除去，解开 + do做 → undo取消，解开', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2059, 'unexpected', '/ˌʌnɪkˈspektɪd/', 'unexpected.mp3', 'adj.想不到的，意外的', '3_0_20160520170014_72995_c-gigapixel-scale.jpg', 'd_107_7154_0_2_20150809021552.png', 'Something unexpected happened when they were posing.', '当他们在摆造型的时候，让人意想不到的事情发生了。', '3_0_20160520170014_31119_c.aac', 'un不 ＋ expect期望 ＋ ed“...的” → unexpected想不到的，意外的，突然的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2060, 'unite', '/juˈnaɪt/', 'unite.mp3', 'v.团结，联合', '5beefeb882a304c504c06c2b8d637a8a_197283_1584528101.jpeg', 'd_107_4906_0_2_20150809011036.png', 'Humans across the globe should unite in their efforts to fight the virus.', '全人类应该团结起来共同抗击病毒。', '0d7fb758cf73c331a93767095aba5ea4_47090_1584960397.mp3', 'uni一个，单一 + te动词后缀，促成 → unite团结，合并', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2061, 'victory', '/ˈvɪktəri/', 'victory.mp3', 'n.胜利', 'ee211ab838f1978d818108a94a96855f_75730_1577959200.jpeg', 'd_96_14692_0_4_20150809014446.png', 'The V-shaped gesture is the symbol of victory.', 'V形手势是胜利的象征。', '14ddbd52025eb13c378ecbf6cbf47fc0_16189_1597394342.mp3', 'vict征服，战胜 + ory表名词 → victory胜利', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2062, 'warm up', '/ˈwɔːrm ʌp/', 'warm up.mp3', 'phr.变暖', 'a516764f45fc963c38102628d9de8700.jpeg', '', 'He breathed into his hands to warm them up.', '他朝手哈气让手暖和起来。', '8gmq5www9s3p7k2gxrszgrmdkgrzj4u3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2063, 'write', '/raɪt/', 'write.mp3', 'v.（以文字）表明', '43b32703c133a0b84b5e47fbab566fa8.jpg', 'd_24_18010_0_4_20150808234148.png', 'The price of this shirt is written on the label. ', '标签上写明了这件衬衫的价格。', '63ba3ea4bed14c31737e4c8de61b1cd5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2064, 'action', '/ˈækʃn/', 'action.mp3', 'n.行为；  v.务必对……进行处理', 'a3c55d670da3399c42c63c9296d69f93_189691_1673247934.jpg', 'd_24_4899_0_4_20150808223619.png', 'It is a polite action to offer your seat to old people.', '给老人让座是一种有礼貌的行为。', 'fea11592d81d1418eeef47f0d66e7deb_15719_1538649175.mp3', 'act行动 + ion表行为，情况 → action行为', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2065, 'alike', '/əˈlaɪk/', 'alike.mp3', 'adj.相像的；相同的，类似的', '1e7c4a823eb277a622f4b6d0883b2d34_213940_1685068638.jpg', 'd_101_7265_0_3_20150809035513.png', 'The two dogs are a lot alike.', '这两只狗长得很像。', '80e3638d23a6cd32_1266883373572598782_250207.mp3', 'a加强意义 + like相像 → alike相同的（地）', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2066, 'army', '/ˈɑːrmi/', 'army.mp3', 'n.陆军，军队，部队', '971763e83061f607f70b04e6d5ed6273.jpg', 'd_75_11752_0_4_20150809025930.png', 'The army is standing on the grass.', '这支军队正站在草地上。', '3a3d6b0e3bb71cd4_1266883007370865502_250207.mp3', 'arm武器，装甲 + y表名词 → 有武器、装甲的人 → army陆军，军队 ', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2067, 'at a time', '/æt ə taɪm/', 'at a time.mp3', 'phr.每次', '08c352e75c9d2f957282ac4328c59445.jpg', '', 'She only takes one pill at a time.', '她一次只服用一粒药。', '83355afcbaeb7f4b04db1fbb83dceb50.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2068, 'bill', '/bɪl/', 'bill.mp3', 'n.账单', 'i_24_16022_0_5_151222144024.jpg', 'd_24_16022_0_3_20150808231048.png', 'The waiter said', '服务员说：”这是您的账单，先生。“', 'sa_24_16022_0_5_151224114452.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2069, 'coat', '/koʊt/', 'coat.mp3', 'n.外套，大衣', '4b1f939f5d067bc4d7268b6f2de710e1_87561_1738834155.jpg', '20121225_20_18_45_72.png', 'Worried that the host might catch a cold', '她担心主持人着凉，让她穿上厚外套。', 'us_Worried_that_20250113172220552_cabd8fb7d6a77686d795.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2070, 'comparison', '/kəmˈpærɪsn/', 'comparison.mp3', 'n.比较；比较等级；对照；比喻', 'i_1_5709_0_3_20150808124246-gigapixel-scale.jpg', 'd_107_5709_0_2_20150809013544.png', 'I made a comparison between the two houses.', '我将这两栋房子做了比较。', 'sa_1_5709_0_3_20150808124246.aac', 'compar=compare比较 + ison表名词 → comparison比较', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2071, 'delight', '/dɪˈlaɪt/', 'delight.mp3', 'n.快乐；高兴事；  v.使快乐', 'b018cb3315240c9c2dedf5519fb75a39_45705_1710210094.jpeg', 'd_24_6180_0_3_20150808224509.png', 'The boy takes great delight in mountain biking.', '这个男孩以山地骑行为乐。', 'us_The_boy_20240312102117919_6354e07fed6c0df60868.mp3', 'de完全地 + light诱惑 → 完全将其迷惑住 → delight使高兴', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2072, 'differ with', '/ˈdɪfɚ wɪð/', 'differ with.mp3', 'phr.与……不同', 'e788bd8c2cfd95e3146f483aad8c35a3.jpg', '', 'These two men\'s directions differ with each other.', '这两个男人的方向各不相同。', '43ae17d505b9a08fbf24077508dcd484.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2073, 'difference', '/ˈdɪfrəns/', 'difference.mp3', 'n.差别', 'ebabcf903995c4a42fa83e38f95c084e_74033_1617768004.jpg', '', 'There is a big difference between the dog\'s two hairstyles.', '这只狗的两种发型差异很大。', '25c9d784e68e34e3738c89b3a7b72c5c_117888_1617767996.mp3', 'differ不同 + ence名词后缀 → difference差异', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2074, 'direct', '/dəˈrekt/', 'direct.mp3', 'adj.笔直的；直达的；直接的；  v.指导，引导；  adv.直接地，径直地', 'd8ad62d2c8a67ea45ec7523577adfb2e_129644_1578622509.jpg', 'd_24_9087_0_5_20150808225958.png', 'The road in the middle is more direct than the other two.', '中间这条路比其他两条更笔直。', '34b6faade7db96ebd104df2a98320fa5_24425_1621914698.mp3', 'di使...变成 + rect直 → direct直接；直接的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2075, 'disclose', '/dɪsˈkloʊz/', 'disclose.mp3', 'v.公开，揭露，泄露', 'i_1_6390_0_4_160309113412-gigapixel-scale.jpg', 'd_1_6390_0_2_20150808125114.png', 'He disclosed the classified secret to the public.', '他把机密公之于众了。', 'sa_1_6390_0_4_160308094530.aac', 'dis相反 + close关闭 → 与关闭相反，暴露 → disclose揭发，揭露', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2076, 'disturb', '/dɪˈstɜːrb/', 'disturb.mp3', 'v.打扰；使烦恼', '196c1dd367bb09409cba28659c27d13d_105935_1732264019.jpg', 'd_24_7266_0_4_20150808225059.png', 'My cute puppy often disturbs me while I\'m working.', '我可爱的小狗经常在我工作的时候打扰我。', 'us_My_cute_20250303100939161_442bd2eb7c5077df446a.mp3', 'dis分开 + turb骚乱 → 分开了 → disturb扰乱，打扰', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2077, 'divorce', '/dɪˈvɔːrs/', 'divorce.mp3', 'n.离婚，离异；  v.离婚', '1e6d4487f6485ae6124b39b83271e75e_191731_1533110153.jpeg', '20130106_14_37_10_540.png', 'The couple have agreed to get a divorce.', '这对夫妻已经同意离婚了。', '816947ea7dac7e09_1266883480717077438_250207.mp3', 'di使…变成、分开 + vorce=vert转 → 从伴侣身边转开 → 离婚', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2078, 'double', '/ˈdʌbl/ ', 'double.mp3', 'adj.两倍的，成双的，成对的；  v.使……翻倍', 'b6cb1309aa0aa345b6dec776fca065b9_100870_1587797665.jpeg', 'd_16_8381_0_2_20150808232926.png', 'The hamburger in the middle is a double cheeseburger.', '中间的汉堡包是一个双层芝士堡。', 'dadbc03723f558c0_1266763557302807354_250117.mp3', 'doub二，双 + le反复 → 反复两倍 → double 翻倍', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2079, 'event', '/ɪˈvent/', 'event.mp3', 'n.活动（指演出、体育比赛、聚会等）', 'i_1_4957_0_3_20150808123227-gigapixel-scale.jpg', 'd_24_4957_0_4_20150808223719.png', 'The university\'s sports meeting is a popular event.', '大学运动会是很受欢迎的一项活动。', 'd9y6r3tc4p3qkckgqerjqw4w9r2dtq5y.mp3', 'e向外 + vent到来 → event事件 ', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2080, 'firm', '/fɜːrm/', 'firm.mp3', 'n.事务所；  v.使牢固，使稳固；  v.变稳固；  adj.牢固的，稳固的；  adv.稳固地', '1423913080547-gigapixel-scale.jpg', 'd_16_6630_0_2_20150808230844.png', 'These lawyers decided to create their own firm.', '这些律师决定创立自己的事务所。', 'b6687a282329371810974edc8307bcd3_23489_1621913820.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2081, 'flexible', '/ˈfleksəbəl/', 'flexible.mp3', 'adj.易弯曲的，柔软的', '4cdd959f131b9c678730c508b03e1041_106859_1538623615.jpg', 'd_107_7499_0_2_20150809022037.png', 'The pencil is flexible enough to be knotted.', '这支铅笔非常柔软，甚至可以打成结。', 'btw2dhy76rc3ec5psxcztssczyl4q8zu.mp3', 'flex弯曲 + ible能……的 → 易曲的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2082, 'hobby', '/ˈhɑːbi/ ', 'hobby.mp3', 'n.业余爱好', 'i_1_15333_0_4_150919160209-manual-scale.jpg', '20130301_12_36_28_982.png', 'Fishing is my hobby', '我的爱好是钓鱼，所以我周末常去湖边。', '9d8d7221ee44324d_1266883622852602868_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2083, 'intend', '/ɪnˈtend/', 'intend.mp3', 'v.打算', 'db6026afebf4b0ac0b2991993cdd2563_90611_1617778347.jpg', 'd_100_13126_0_4_20150809032530.png', 'The boy intends to use the money he saved to buy a new skateboard.', '男孩打算用存下来的钱买一块新的滑板。', '9f7268395b3f9002_1266883377516293052_250207.mp3', 'in内 + tend伸展；扩大 → 内心伸出 → intend打算', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2084, 'kilogram', '/ˈkɪləɡræm/', 'kilogram.mp3', 'n.千克；公斤', 'd4c1c267cc016da91dad2bafd7aa47f2_193057_1585132026.jpeg', 'd_105_10804_0_2_20150809061752.png', 'One kilogram is equal to two catties.', '一千克等于两斤。', 'us_One_kilogram_20241009151410548_9e7c0af82cc2f427973a.mp3', 'kilo一千 + gram克 → kilogram一千克，公斤', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2085, 'kilometer', '/kɪˈlɑ:mɪtər/', 'kilometer.mp3', 'n.千米，公里', 'c602f14be2db3b86ca6515b53ae75796_255996_1739156273.jpg', 'd_109_10805_0_2_20150809060135.png', 'The service area is roughly ten kilometers away from us.', '服务区域离我们大约有10公里。', 'us_The_service_20250210105818575_caef20e6de3ba4ac7b58.mp3', 'kilo一千 + meter米 → kilometer一千米，公里', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2086, 'knock out', '/nɑːk aʊt/', 'knock out.mp3', 'phr.摧毁', 'a02ecc2feb7e5faa34aa78a9277ddd16_194490_1701674241.jpeg', '', 'He knocked out the bricks.', '他摧毁了这些砖头。', 'sa_906_-906_0_1_160229153734.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2087, 'leave', '/liːv/', 'leave.mp3', 'v.留下', '49eabf13272c2f5c2f7d42b41740177c.jpeg', 'd_24_17242_0_4_20150808232456.png', 'There was some trash left in the stadium after the match.', '比赛结束后，体育场内留下了一些垃圾。', 'a3f57214d67254b1e7df5966296e3147.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2088, 'luggage', '/ˈlʌɡɪdʒ/', 'luggage.mp3', 'n.行李；衣箱', '28e72d10055ce2dbba1b838af49a2631_116415_1736835085.jpg', 'd_16_6808_0_2_20150808231117.png', 'College students may bring a lot of luggage with them when they go home for vacation.', '大学生放假回家可能会带很多行李。', 'us_College_students_20250114141141653_d90cb2a874a3017ac14d.mp3', 'lug拖，拽 + 双写g + age表名词 → luggage行李', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2089, 'needle', '/ˈniːdl/', 'needle.mp3', 'n.针；针状物；指针', 'i_1_9291_0_4_20150808131352-gigapixel-scale.jpg', 'd_24_9291_0_4_20150808230143.png', 'All you need to sew clothing is a needle and thread.', '你缝衣服所需要的就是针和线。', 'sa_1_9291_0_4_20150808131352.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2090, 'neighbor', '/\'neɪbə/', 'neighbor.mp3', 'n.邻居，邻人（=neighbour）', 'bb69293bb593d419fc505ee3f94de516_100496_1532165156.jpeg', 'd_93_13524_0_4_20150809002138.png', 'We live in the same apartment block', '我们住在同一栋楼，所以我们是邻居。', 'a61c8af018ecab64c165b63a39ec608c_29926_1532165162.mp3', 'neigh附近 + bor居民 → neighbor邻居', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2091, 'nonsense', '/ˈnɑːnsens/', 'nonsense.mp3', 'n.废话，胡说', '68efe33b2e9b57b6e516d1e175d23450_26482_1732007120.jpg', 'd_1_7855_0_2_20150808130057.png', 'What you\'re saying is nonsense.', '你说的话就是胡话。', 'us_What_youre_20241119170523187_8c6d9ac75c20d6e21abb.mp3', 'non无 + sense感觉，意义 → nonsense无意义', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2092, 'nut', '/nʌt/', 'nut.mp3', 'n.坚果', '062e02c078291a3b627f57efed998811_80941_1576573855.jpeg', '20141015_16_16_27_866_v3.png', 'Nuts are a source of vitamin E for the body.', '坚果是人体所需维生素E的一个来源。', '55845d8b3c55c415_1266797979861036024_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2093, 'on a small scale', '/ɑːn ə smɔːl skeɪl/', 'on a small scale.mp3', 'adv.小规模地', '5_48_105_20161102165005_37642_c.jpg', '', 'To test the side effect of this fertilizer', '为了测试这种化肥的副作用，我们小规模地使用了它。', '5_51_78_20161103165634_19423_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2094, 'paragraph', '/ˈpærəɡræf/', 'paragraph.mp3', 'n.（文章的）段，节', 'i_1_2030_0_4_20150808121804-gigapixel-scale.jpg', 'd_109_2030_0_2_20150809053420.png', 'Please summarize the main point of this paragraph.', '请总结这一段的大意。', 'sa_1_2030_0_4_20150808121804.aac', 'para旁、靠近、外 + graph=write，表示写，图 → 靠近图表旁边的文字 → (文章的)段，节', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2095, 'party', '/ˈpɑːrti/', 'party.mp3', 'n.派对，聚会；政党，党派', '71fdb834260eb7b2ce557379aec485bb_94510_1574847313.jpg', 'd_24_17929_0_3_20150808233532.png', 'Everyone had a great time at my birthday party.', '在我的生日聚会上每个人都玩得很开心。', '8868633a9bbaa76a_1266763558311144276_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2096, 'percentage', '/pərˈsentɪdʒ/', 'percentage.mp3', 'n.百分比', 'cad582fda688576882c6523b03854c3b_73207_1595058977.jpg', 'd_107_6145_0_2_20150809015057.png', 'The percentage of the green part is 60%.', '绿色部分的百分比为60%。', 'us_The_percentage_20240918133050032_0f5e6752a8c4836399e4.mp3', 'percent百分之几 + age状态，总称 → 百分比', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2097, 'plentiful', '/ˈplentɪfl/', 'plentiful.mp3', 'adj.丰富的', '731569829ccacc1cc5665130d5024452_87263_1535083173.jpeg', 'd_107_9190_0_2_20150809024439.png', 'The fruits and vegetables are plentiful!', '水果和蔬菜好丰富啊！', 'bff4ee9884e72bfa_1266883622422469370_250207.mp3', 'plenti=plenty足够 + ful…的 → plentiful丰富的，充足的，大量的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2098, 'point', '/pɔɪnt/', 'point.mp3', 'n.意义', 'cbc731ffe811f80aa42b8ea6e589570e.jpeg', 'd_77_13757_0_4_20150809033323.png', 'What was the point of playing the piano to a cow?', '对牛弹琴的意义何在？', '8f72eb63c88d4c376a5668e5ce65c802_17600_1619318103.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2099, 'private', '/ˈpraɪvət/', 'private.mp3', 'adj.私人的', 'eebbb218ca0f7207764e4e65ee5dc1b5_174712_1524887965.jpeg', '16226846e348da3aaf101b3e2a49039c_26666_1539341301.png', 'Do not enter! This is Mr. Dog\'s private property.', '禁止进入！这是狗先生的私人住宅。', '2ce260c760f315ec_1266883326337264596_250207.mp3', 'priv个人的 + ate使成为 → 私人的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2100, 'realize', '/ˈriːəlaɪz/', 'realize.mp3', 'v.认识到，意识到（=realise）', '3_52_20170616103016_40757_c-gigapixel-scale.jpg', 'd_24_4995_0_3_20150808223803.png', 'So that\'s how the word is spelled! the little boy finally realized.', '“原来这个单词是这样拼写的！”小男孩终于意识到了这一点。', 'x6knhzmcmrj5uptbqhuy8ttdkhvcdhsu.mp3', 'real真实的 + ize表动词 → realize实现', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2101, 'room', '/ruːm/', 'room.mp3', 'n.空间； 房间', '91dca0b22f75c693de5727258c9b5fc3.jpeg', 'd_24_16441_0_3_20150808231237.png', 'There was enough room in the van for the suitcase.', '车里有足够的地方放行李箱。', '0dafe276a82e7bf738430b9588ddb524_57519_1600141816.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2102, 'scarcely', '/ˈskersli/', 'scarcely.mp3', 'adv.几乎不', '6f6568a9fd367bdec991c1dca7a52a12.jpg', '', 'His grandfather can scarcely hear his grandson speaking. ', '他祖父听力不好，几乎听不到他孙子说的话。', 'b585f9163f2b85e00d21def2ddd531e0_41936_1599550816.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2103, 'singular', '/ˈsɪŋɡjələr/', 'singular.mp3', 'adj.单独的，单个的；非凡的，显著的', '912320d44da7c6d2add20754e6fb1bdd_30042_1588921016.jpeg', 'd_106_16020_0_2_20150809075355.png', 'There is a singular red flower amongst a bed of yellow ones.', '在黄色的花丛中有一朵红色的花。', 'f6a50d3bc5ccdfc4861e4a41720b62e8_46952_1588921013.mp3', 'singul=single单一 + ar……的 → singular单独的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2104, 'soft', '/sɔːft/', 'soft.mp3', 'adj.软的，柔软的；细嫩的，光滑的；  n.柔软的东西；  adv.柔软地，柔和地', '3_0_20170708103313_51212_c-gigapixel-scale.jpg', 'd_24_18012_0_4_20150808234157.png', 'This material looks so soft.', '这种材质看起来很柔软。', 'c52f2smb284rx7sfter8w3qkncd3k3l3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2105, 'sole', '/soʊl/', 'sole.mp3', 'n.脚底，鞋底，袜底；  adj.独有的；  v.给（鞋）换底', '52c5f59385ccbcfe81fec023ee477bcd_136639_1544066229.jpeg', 'd_107_15251_0_2_20150809025607.png', 'She is having the sole of her foot massaged.', '她正在按摩足底。', '3a9b2adb7fef0eb2a479267a59e89fae_40144_1569642304.mp3', 'sol单独 ＋ e → sole单独的，唯一的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2106, 'specimen', '/ˈspesɪmən/', 'specimen.mp3', 'n.标本', 'd8f6cc844d394a79bcdbafbc02a629c5_34744_1587653081.jpeg', '', 'This exhibit contains various different specimens of butterfly.', '这件展览品中包含了各种不同的蝴蝶标本。', '54d7d57d87c140d9c5eb11ce9bc11025_44916_1587653078.mp3', 'speci仔细看 + men人 → 需要人仔细观察的东西 → specimen样本', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2107, 'spill', '/spɪl/', 'spill.mp3', 'v.使流出，涌流；（人群）涌出；  n.溢出，溅出', 'i_1_6020_0_5_20150808124649-gigapixel-scale.jpg', '20130301_12_39_56_823.png', 'Oh no! I\'ve spilled the green nail polish.', '哦不！我把这瓶绿色的指甲油弄洒了。', 'sa_1_6020_0_5_20150808124649.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2108, 'stand up for', '/stænd ʌp fɔr/', 'stand up for.mp3', 'phr.维护', 'i_911_-911_0_1_160321160102.jpg', '', 'She has stood up for women\'s rights for a long time.', '她长时间维护女性的权利。', 'us_She_has_20250428102435753_798c3fe089f92cc0e684.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2109, 'stroke', '/stroʊk/', 'stroke.mp3', 'n.击打；一击，一次，一举；中风；笔画；  v.轻抚', 'bc1d3a142b5b5310c29a1bcbb13b07a5_99339_1582792259.jpeg', 'd_1_4805_0_2_20150808123042.png', 'He hit the ball cleanly with a beautiful stroke.', '他利落地击球，打出漂亮的一击。', 'a1ca89b4192609a08a5ae138f758ed3c_50512_1582792250.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2110, 'surrender to', '/səˈrendər tu/', 'surrender to.mp3', 'phr.屈服，投降', '0e4accbd1b972ce3e667d3722e5a2684.jpeg', '', 'He finally surrendered to temptation and ate the cupcake. ', '他最终屈服于诱惑，吃掉了那个纸杯蛋糕。', '8568a30c612405b6c7c30f4074ebce10_45598_1600070714.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2111, 'sympathize with', '/ˈsɪmpəˌθaɪz wɪθ/', 'sympathize with.mp3', 'phr.同情', 'e5e61081f2af09bef0406eb6d1bbb140.jpeg', '', 'She can sympathize with him because she knows what it\'s like to have a headache.', '她对他表示同情，因为她知道头痛是什么感觉。', '2946f8294cb5e758d7bbf757ec8f1f5d_44734_1600071465.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2112, 'symphony', '/ˈsɪmfəni/', 'symphony.mp3', 'n.交响乐', 'bf507fdd7c9a02c6a0170ff704ef01a0_156850_1747278871.jpg', 'd_105_5284_0_2_20150809054611.png', 'A symphony needs many musicians to play different instruments.', '交响乐需要很多音乐家演奏不同的乐器。', 'epd9hm8qp2fautjcm7vpnjgrl3svhg9j.mp3', 'sym共同 +  phon 声音 + y 状态，行为 → symphony交响乐', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2113, 'touch', '/tʌtʃ/', 'touch.mp3', 'v.触，碰，摸；  n.触觉', '5da99fef3e4e9a7b321547a22aea18f0_200521_1524119517.jpg', 'd_100_14559_0_4_20150809032700.png', 'He is touching her belly to feel the baby moving.', '他想摸摸她的肚子来感受宝宝的移动。', '1a6dd812a1f82e74_1266883008678746774_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2114, 'veteran', '/ˈvetərən/', 'veteran.mp3', 'n.老兵；退役军人；  adj.经验丰富的；老练的', '32aa3afe6dbda7ca1d1f4ab12dd6f262_74791_1715310198.jpg', '4d9f17b297fbd4c52684fb0938eb31a2_47606_1551253335.png', 'This veteran has fought in many wars.', '这位老兵曾多次参战。', '4a596a809f982155eec530550b526759_23032_1564370564.mp3', 'veter老 + an名词后缀，表示人 → veteran老兵', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2115, 'vital', '/ˈvaɪtl/', 'vital.mp3', 'adj.必不可少的，至关重要的；有活力的', '4f045b5d69773e08bdd7fe9c8bce5e44_195904_1556332232.jpeg', 'd_16_3901_0_2_20150808223805.png', 'Water is vital to living beings.', '水对生物来说是必不可少的。', '0be40ab81c95805ab0fc49330466a001_38459_1556332237.mp3', 'vit生命 + al形容词后缀 → vital有活力的；重要的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2116, 'whether', '/ˈweðər/', 'whether.mp3', 'conj.是否', '3_0_20170721071407_91758_c-gigapixel-scale.jpg', 'd_24_19275_0_4_20150809001136.png', 'The mother still doesn\'t know whether it\'s a boy or a girl.', '这位母亲还不知道宝宝是男是女。', '2ca77b0670a44002_1266883116401449706_250207.mp3', 'whe=who谁 + ther比较级后缀 → 是两人中的谁 → whether是否', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2117, 'word for word', '/wɜːrd fɔːr wɜːrd/', 'word for word.mp3', 'phr.逐字地', '66aee8b434d9edcc70a405efa1a69b16.jpeg', '', 'She is writing down his speech word for word.', '她正在逐字记下他的演讲。', '34a57fae17f092d801e01d0c439149b3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2118, 'account', '/əˈkaʊnt/ ', 'account.mp3', 'n.账目，账户；  v.做出说明（或解释）；把……视作', 'i_2_3849_0_4_151221103005-gigapixel-scale.jpg', 'd_16_3849_0_2_20150808223720.png', 'I have no money in my bank account.', '我的银行账户里没有钱。', 'sa_1_3849_0_4_160111175558.aac', 'ac去 +count计算 → 去计算 → account算账，账目', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2119, 'activity', '/ækˈtɪvəti/', 'activity.mp3', 'n.活动；行动；活性', 'e4ee32e37cbde88518ae6922ec30a119_233155_1683704545.jpg', 'd_107_4939_0_2_20150809011125.png', 'They all like outdoor activities.', '他们都喜欢户外活动。', 'us_They_all_20230505095817190_0fbe0d8309c5fc3c05c1.mp3', 'act行动，做 + ivity名词后缀 → 活动 → activity活动', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2120, 'anywhere', '/ˈeniwer/', 'anywhere.mp3', 'adv.任何地方，无论何处', '14281ad834d880524096bc8027c4a685_94523_1656920205.jpg', 'd_16_19052_0_2_20150809020752.png', 'You can connect to the internet from anywhere in the world.', '你可以从世界上的任何地方连接到互联网。', '61282ee3e6076a4a_1266883009426119348_250207.mp3', 'any任何 + where哪里 → anywhere无论何处', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2121, 'application to', '/ˌæplɪˈkeɪʃn tuː/', 'application to.mp3', 'phr.给……的申请', '18ebe1f16e87540f4d496437679828b0.jpg', '', 'This is an application to a college.', '这是给一所大学的申请书。', '776566938929bb2108de4371dc34db47_36512_1593575386.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2122, 'argument about', '/ˈɑːrɡjumənt əˈbaʊt/', 'argument about.mp3', 'phr.关于……的争吵', 'd4d3285a90109e9555006220c1c3643d.jpg', '', 'They are having an argument about who broke the vase.', '他们在为是谁打碎了花瓶而争吵。', '238480080f669a267a221ab31464511a_44576_1593575411.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2123, 'arrangement for', '/əˈreɪndʒmənt fɔːr/', 'arrangement for.mp3', 'phr.对……的安排', '10184b69910805ddf2a144a8384e5f9c.jpg', '', 'Here is my upcoming arrangement for my exercise.', '这是我即将进行的锻炼安排。', 'us_Here_is_20241009154150706_72e126e30b95785b897c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2124, 'at a loss', '/æt ə lɔːs/', 'at a loss.mp3', 'phr.困惑', '5ca00dfd64c0b29d824780179fff01ff.jpg', '', 'The teacher was at a loss when her student couldn\'t answer the simple question.', '当发现她的学生解不出这个简单的问题时，老师困惑不解。', 'c888be4be5d28d6cfa14f5abd9eb1d8a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2125, 'attention', '/əˈtenʃn/', 'attention.mp3', 'n.专心，注意力', '33365742c2aaa9b25a2cc79909546ea0_171857_1552618524.jpeg', '20130301_10_55_37_603.png', 'Only one student in the class was paying attention to what the teacher was saying.', '班上只有一个学生在专心听老师讲课。', 'wv3qddljbac3vsrkz42bwyrjlxvcy6ap.mp3', 'attent关注 + ion名词后缀 → attention注意力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2126, 'author', '/ˈɔːθər/', 'author.mp3', 'n.作者，作家', 'e15b8814c452e25f42107f05c1e3c514_152062_1564805223.jpg', 'd_24_8087_0_4_20150808225425.png', 'Lu Xun is the author of this book.', '鲁迅是这本书的作者。', '17551713f108529e2af6bcc15bc0b617_12114_1595059801.mp3', 'auth增加，创造 + or表人 → 创作的人 → author作者，作家', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2127, 'award', '/əˈwɔːrd/', 'award.mp3', 'n.奖品；奖学金；  v.授予；奖励', '8e47eedf0179f2d12e3bb81847963753_99076_1604025309.jpg', 'd_107_4919_0_2_20150809011105.png', 'The actress got an award for her movie.', '这个女演员凭其电影赢得了这个奖项。', 'sa_16_4919_0_4_151209161026.aac', 'a=ex向外 + ward看 → award奖品', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2128, 'belief in', '/bɪˈlif ɪn/', 'belief in.mp3', 'phr.对……的信仰', '0af000bc12ec4fcd31ee1a99f47d769d.jpeg', '', 'Many children\'s belief in Santa Claus stops when they become adults.', '许多孩子都相信圣诞老人的存在，但他们长大后就不信了。', 'b8dcc7fa2c437388a352d6c209c9d9f2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
