INSERT INTO `words` VALUES (2131, 'coke', '/koʊk/', 'coke.mp3', 'n.可乐', 'i_2_19065_0_2_20150808165803-gigapixel-scale.jpg', 'd_24_19065_0_3_20150809000242.png', 'There\'s nothing like a cold Coke on a hot summer\'s day.', '在炎热的夏天，没什么比得上来一杯冰可乐。', 'sa_2_19065_0_2_20150808165803.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2132, 'crash', '/kræʃ/', 'crash.mp3', 'v.碰撞；猛撞；  n.撞车', '100916a85b1a99ed8ea2d7de283bb75e_90049_1596610603.jpeg', '20121225_18_55_38_366.png', 'The car behind crashed into the one ahead.', '后面的车撞上前面那辆车了。', '33d3c2cdb5fa9def_1266883331309284160_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
