INSERT INTO `words` VALUES (2134, 'drop', '/drɑːp/', 'drop.mp3', 'v.落下；  n.降低；滴状物', 'i_1_8392_0_3_20150808130701-gigapixel-scale.jpg', 'd_24_8392_0_3_20150808225635.png', 'I accidentally dropped my phone. So upset!', '我不小心把手机弄掉了。真难过！', 'rbhz97tj3ly63m8v6pxc7vte8spza9c3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2135, 'elderly', '/ˈeldərli/', 'elderly.mp3', 'adj.年老的，年纪较大的', 'elderly_3904_20231106_95aed86e.jpg', '20141011_04_27_56_711_v3.png', 'No one offered a seat to the elderly man.', '没有人给老人让座。', 'fe0450cbe781cf71_1266883627655015246_250207.mp3', 'elder年长的 + ly……的 → elderly过了中年的，稍老的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
