INSERT INTO `words` VALUES (2137, 'enterprise', '/ˈentərpraɪz/', 'enterprise.mp3', 'n.企业（或事业）单位，公司', '2f7abb8b6010aa68f923230cc488f4bc_87135_1625813867.jpg', 'd_107_3919_0_2_20150809003506.png', 'This small enterprise specializes in milk.', '这家小企业专营牛奶。', 'f68d9bc753978bfb4d0aa6336e9219d1_16503_1631341463.mp3', 'enter进入 + prise拿住，抓住 → 进入抓住 → enterprise事业，进取心', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2138, 'especially', '/ɪˈspeʃəli/', 'especially.mp3', 'adv.尤其；异常地', '3_0_20170707172821_14731_c-gigapixel-scale.jpg', 'd_24_19160_0_4_20150809000948.png', 'The little girl loves drinking juice', '小女孩很爱喝果汁，尤其是橙汁。', 'q7wrcbed3hva3jb3jh243aam9sx5f7w5.mp3', 'especial特别的 + ly副词后缀 → especially特别地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2139, 'extremely', '/ɪkˈstriːmli/', 'extremely.mp3', 'adv.极其，非常', '42d2f3e20c23d416c96305cd4a182379_193043_1573719715.jpeg', '20130601_09_27_01_430.png', 'Compared with the Earth', '和地球相比，太阳非常大。', '43322c316ff8047a_1266883380544187226_250207.mp3', 'extreme极端的 + ly表副词 → 过分地，极端地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2140, 'foot', '/fʊt/', 'foot.mp3', 'n.脚；底部；  v.步行；  v.走在……之上', '2aec50acb09f54ecfc811aabc0d3d89f_89115_1574765062.jpg', '20130301_11_02_35_757.png', 'She is lying in the sun with bare feet.', '她光着脚躺在阳光下。', '33ec4441d11a5828b456258e4076a1e1_43394_1584788781.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2141, 'gentleman', '/ˈdʒentlmən/', 'gentleman.mp3', 'n.绅士；有教养的人', '3_0_20170608072108_85981_c-manual-scale.jpg', 'd_24_18760_0_3_20150808235658.png', 'Thank you. You are really a gentleman.', '“谢谢。您真是一位绅士。”', 'us_Thank_you_20240826095531347_66f3e86a7244be8f686e.mp3', 'gentle温和的 + man人 → gentleman绅士；有教养的人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2142, 'get over', '/ɡet ˈoʊvər/', 'get over.mp3', 'phr.熬过', 'b166df9525ac1062374356a486c13895_116691_1584083687.jpeg', '', 'She was heartbroken when she broke up with her boyfriend', '她和男朋友分手后十分伤心，但她最终熬了过去。', '73c0680b4271bfd107b1d7bde50b7eb2_47216_1584083685.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2143, 'guest', '/ɡest/', 'guest.mp3', 'n.客人，宾客', 'bd40c74cbc37703d23fbc8f5b178dffe_95249_1729064562.jpg', 'd_24_16000_0_4_20150808231017.png', 'We are waiting at the door for the arrival of our guests.', '我们在门口等待客人的到来。', 'a9a00e7e4f45af8c_1266883114211322800_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2144, 'high', '/haɪ/', 'high.mp3', 'adj.（标准、质量等）高的，好的', 'e0db53b40ee98d996db82556c0aac086.jpeg', 'd_24_17300_0_3_20150808232637.png', 'That\'s a high performance computer.', '那是一台高性能计算机。', '67134ae5767d828bf0ec8f0eeecbd25d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2145, 'however', '/haʊˈevər/', 'however.mp3', 'adv.然而，不过；无论如何，不管多么', '3_0_20170703171944_40508_c-gigapixel-scale.jpg', '20130316_19_05_43_863.png', 'He got a great test score; however', '他考了个好成绩，然而他还是不开心。', 'ddd9308ae9d91c9f_1266883371221953440_250207.mp3', 'how怎样 + ever永远，表强调 → however然而；不管怎样', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2146, 'important', '/ɪmˈpɔːrtnt/', 'important.mp3', 'adj.重要的，重大的', '3_0_20170721071232_80296_c-gigapixel-scale.jpg', '20121225_20_35_09_409.png', 'You have an important message.', '你有一条重要的消息。', '8d8ce34d41e49aae_1266883195085237238_250207.mp3', 'import重要的 + ant具有…性质的 → important重要的；有势力的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2147, 'in addition', '/ɪn əˈdɪʃən/', 'in addition.mp3', 'phr.除此之外，另外', 'e32975b6ee8a1623dd65da91f3ba63a5_153466_1736407084.jpg', '', 'He was a great boyfriend. In addition', '他是一个优秀的男朋友。除此之外，他还知道急救知识。', 'bhbbqlhxljc5d7csulejt5p7dml8et49.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2148, 'in turn', '/in tɜrn/', 'in turn.mp3', 'phr.依次', 'c876c3c7b7c0d8a79b07e92673c186fa_184434_1701672948.jpeg', '', 'We got on the bus in turn.', '我们依次上公交车。', 'sa_911_-911_0_1_160323152019.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2149, 'instant', '/ˈɪnstənt/', 'instant.mp3', 'n.瞬间；  adj.立即的', 'i_1_1604_0_7_160111141848-manual-scale.jpg', 'd_24_1604_0_4_20150808223149.png', 'The mother caught her baby the instant he fell.', '那位母亲在孩子掉下的瞬间接住了他。', 'sa_1_1604_0_7_160111141828.aac', 'in进入 + st站立 + ant…的 → 站进来的 → instant紧急的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2150, 'interfere', '/ˌɪntərˈfɪr/', 'interfere.mp3', 'v.干涉，妨碍', '7d62902d546723cf4d2ec2b31be571cf_119941_1538667370.jpg', 'd_107_9270_0_2_20150809024539.png', 'Let it fall. Don\'t interfere with the process.', '让它倒下去。别去干涉这个过程。', 'e45723ca6a9c2b56_1266883376715160216_250207.mp3', 'inter在…之间 + fer带来，拿来 + e → interfere干涉，干预；妨碍', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2151, 'internal', '/ɪnˈtɝːnəl/', 'internal.mp3', 'adj.体内的，内部的；  n.内部器官', '0dacc4238ddb8bfcea6a52743f056407_100555_1585039092.jpeg', '20140912_00_19_52_400_v3.png', 'The picture shows humans\' major internal organs.', '这张图展示了人体主要的内脏器官。', '39822cc346ca96608ef5d3699d364d67_45832_1585039089.mp3', 'intern=inter在…之内 + al属于...的 → internal内的；国内的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2152, 'judge', '/dʒʌdʒ/', 'judge.mp3', 'n.法官；裁判员；  v.判决，审判', 'fac9dac265d3380a423d2601fe710bb4_83116_1532162816.jpeg', 'd_52_13193_0_4_20150809025315.png', 'The judge will decide whether you are guilty or not.', '法官会决定你到底有没有罪。', '487a371913a66c420e95e8da252aadd4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2153, 'means', '/miːnz/', 'means.mp3', 'n.方法，手段', 'f6e87ec63f20d195fdb5d2adeb5ba45f_201040_1585122361.jpeg', 'd_107_10082_0_2_20150809024904.png', 'Students travel to school by many means', '学生去学校的方式有很多种，例如坐公交或者步行。', '45cd0e833eb898233c4d68344f17fd67_47214_1585122365.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2154, 'measure', '/ˈmeʒər/', 'measure.mp3', 'v.测量，度量；估量；  n.措施，方法；测量，尺寸；计量标准', 'dfd075841d3e516fc662804b6e395665_83598_1617766956.jpg', 'd_24_5538_0_3_20150808224119.png', 'The boy is measuring the size of the turtle.', '男孩正在测量这只乌龟的大小。', '32v8dgyjaeqaj7f3pu6umfd77fy7l8gk.mp3', 'meas计量，测量 + ure名词后缀 → measure测量，测定', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2155, 'nation', '/ˈneɪʃn/', 'nation.mp3', 'n.民族，国家', 'i_1_9193_0_3_20150808131301-gigapixel-scale.jpg', 'd_24_9193_0_3_20150808230100.png', 'These flags represent different nations.', '这些国旗代表着不同的国家。', 'sa_9193_1_0_2_150707152444.mp3', 'nat出生的 + ion名词后缀 → 出生之处 → nation国家', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2156, 'object to', '/əbˈdʒekt tu/', 'object to.mp3', 'phr.反对', '4b21e7fe40e7fb088df14e6b0359ed88_188321_1530862920.jpeg', '', 'The public object to this policy.', '公众反对这项政策。', 'c55fd1e203b2155d94de23981ee39d20_23530_1530862882.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2157, 'rather', '/ˈræðər/', 'rather.mp3', 'adv.相当', '52d48720d8d76188bbf5bcd92c47b3cc.jpeg', 'd_24_19763_0_4_20150809002943.png', 'It\'s rather cold today.', '今天相当冷。', 'e9843a82b43685a1_1266797989778860900_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2158, 'reputation', '/ˌrepjuˈteɪʃn/', 'reputation.mp3', 'n.名誉，名声', '753b006e167641ddfc47fe9aedcf0794_187237_1735610399.jpg', 'd_16_4638_0_2_20150808224338.png', 'He has a good reputation among sportsmen since he always wins.', '因为经常赢得比赛，所以他在运动员当中有很高的声誉。', '374037d7d728679a_1266883379171973648_250207.mp3', 're再 + put想起 + ation名词后缀 → 让人再想起 → reputation声誉', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2159, 'run into', '/rʌn ˈɪntə/', 'run into.mp3', 'phr.撞上', 'i_909_-909_0_1_160321150357.jpg', '', 'Suddenly the car was out of control and #ran into# the wall.', '突然间他的车失控了，撞到了墙上。', 'sa_909_-909_0_1_160323163348.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2160, 'short', '/ʃɔːrt/', 'short.mp3', 'adj.短的；  adv.缺少，未达到；  n.电影短片', 'b1ee811da8a793b73619c5d613f0f286_75284_1565603408.jpg', 'd_24_19141_0_4_20150809000906.png', 'Short hair is in style now.', '现在很流行短发。', '9b80153cbf6f49bd_1266741633496865438_250113.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2161, 'succeed in', '/səkˈsid ɪn/', 'succeed in.mp3', 'phr.取得成功', '5_48_105_20161117151744_26161_c.jpg', '', 'After years of hard work', '经过多年的艰苦努力，他终于在音乐领域取得了成功。', '3dd1d0b20ca9e1ec9578d184a1387076_27318_1622427368.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2162, 'tackle', '/ˈtækl/', 'tackle.mp3', 'v.对付，处理，解决（难题）；（足球等比赛中）阻截；  n.阻截', 'd42cbb1bd9d46e4da869f78a8183f4bc_77177_1701051569.jpg', 'd_1_4030_0_4_20150808122244.png', 'The firefighters are tackling the blaze.', '消防队员们正在努力扑灭大火。', 'us_The_firefighters_20231219180634443_adb44a7c6ec9fb4dc835.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2163, 'take to', '/teɪk tu/', 'take to.mp3', 'phr.喜欢', '14164a52c9afd5174757fb963d827261.jpeg', '', 'Everyone immediately took to the new classmate who seemed very friendly.', '每个人都立刻喜欢上了那位看起来很友好的新同学。', '6770690fdfa5c1d9_1266883377870428886_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2164, 'tax', '/tæks/ ', 'tax.mp3', 'n.税，税款；  v.征税', 'bfc44253e41656f7f60245d999255217_109283.jpg', 'd_16_8095_0_2_20150808232549.png', 'The amount of tax people pay to the government depends on their income.', '人们向政府纳税的数额取决于他们的收入。', 'e5c66e93ecf7d060c2970a2e06a22d48_19480_1538469066.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2165, 'tense', '/tens/', 'tense.mp3', 'adj.紧张的；  v.变得紧张；  n.时态', 'i_1_7157_0_4_151029115835-gigapixel-scale.jpg', 'd_107_7157_0_2_20150809021601.png', 'I feel really tense about the coming exam.', '我真的对即将来临的考试感到紧张。', 'sa_1_7157_0_4_151109165806.aac', 'tense=tens伸展 → 绷紧的，紧张的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2166, 'tsunami', '/tsuːˈnɑːmi/', 'tsunami.mp3', 'n.海啸', 'i_903_-903_0_1_160202114310-gigapixel-scale.jpg', '', 'Get away from the beach! The tsunami is coming!', '快离开海滩！海啸来了！', '87w2tckq2cljaqkr42r78adkavttzr24.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2167, 'tutor', '/ˈtuːtər/', 'tutor.mp3', 'n.家庭教师，指导教师；  v.当……的家庭教师', '47d65757d460b1cda5820dcb1d958255_86755_1535178417.jpeg', '20141010_07_08_09_789_v3.png', 'The tutor is helping the little boy with his homework.', '这个家庭教师正在辅导小男孩的功课。', 'cf55d97c9195bfec4a59a00afdc31e19_32956_1535178412.mp3', 'tut保护 + or人 → tutor保护人，导师，教师', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2168, 'well', '/wel/', 'well.mp3', 'adj.健康的', '9509da56217106fcdeb17ab5d0b1bdf3_34040_1587627988.jpeg', 'd_16_19545_0_2_20150809022535.png', 'Both my parents are very well.', '我的父母都很健康。', 'f55e6df32a961b3a_1266763315372338122_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2169, 'abstract', '/ˈæbstrækt/', 'abstract.mp3', 'adj.抽象的；  n.摘要', '5d7d4a5730f80e4f95142e994d006aa3_73012_1584954770.jpeg', '20141014_23_02_38_333_v3.png', 'Abstract art is often difficult to understand.', '抽象艺术通常让人难以理解。', '791227c59eb26cb69b7ce3b515b47c7b_47858_1584954884.mp3', 'abs向外 + tract拉 → abstract提取，抽象', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2170, 'although', '/ɔːlˈðoʊ/', 'although.mp3', 'conj.虽然，尽管，即使', '1fde11ba3cec65471928341f2f88517a_121487_1538586063.jpg', 'd_24_19591_0_4_20150809002235.png', 'Although it is a rainy day', '尽管这是一个雨天，小姑娘还是玩得很开心。', '5a7fa389c62d741e_1266883487588330368_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2171, 'appoint', '/əˈpɔɪnt/', 'appoint.mp3', 'v.委派，任命；确定，约定', 'i_16_191_0_11_151117100748-gigapixel-scale.jpg', 'd_107_191_0_2_20150809000441.png', 'My boss has appointed me to manage this project.', '我的老板已任命我来管理这个项目。', 'sa_16_191_0_11_151124153408.aac', 'ap加强 + point指 → appoint指定；任命', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2172, 'arise', '/əˈraɪz/', 'arise.mp3', 'v.起床，起身；由……引起，发生', 'i_103_3937_0_3_20150809003459-gigapixel-scale.jpg', 'd_16_3937_0_2_20150808223841.png', 'He arises at 7 a.m. every morning.', '他每天早上7点起床。', 'sa_103_3937_0_3_20150809003459.aac', 'a加强意义 + rise升起 → arise起来，升起', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2173, 'attach to', '/əˈtætʃ tu/', 'attach to.mp3', 'phr.束缚，系上，附加', '5_44_190_20170324162912_86890_c.jpg', '', 'Many people #are attached to# their mobile phones and can\'t live without them.', '许多人被手机束缚住，不能离开手机生活。', '5_51_403_20170417101739_83059_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2174, 'besides', '/bɪˈsaɪdz/', 'besides.mp3', 'prep.除……之外（还）；  adv.此外', '3_0_20160520172941_55722_c-gigapixel-scale.jpg', 'd_24_16010_0_3_20150808231032.png', 'As the winner', '作为胜利者，我除了得到奖杯外，还获得了一大笔钱。', 'c97c318ba2d3b495_1266883375537630042_250207.mp3', 'be构成介词 + side边 + s表副词 → besides此外，而且', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2175, 'biological', '/ˌbaɪəˈlɑːdʒɪkl/', 'biological.mp3', 'adj.生物学的', '823c9ab533da61bbe3f3b2fc5d20b3cf_204714_1583477590.jpeg', '', 'Biological science is concerned with research of animals', '生物科学涉及对动物、植物和微生物的研究。', '48f814871a649988a3847e9f0ee99a52_35338_1583477587.mp3', 'bio生物 ＋ logical...学的 → biological生物学（上）的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2176, 'birth', '/bɜːrθ/', 'birth.mp3', 'n.分娩，出生', 'fd3e13e0021dfea59e8b35a44726d870_195706_1578568831.jpeg', '20121225_18_34_02_904.png', 'With the doctor\'s help', '在医生的帮助下，这位母亲顺利产下一个婴儿。', '6np4zf9ckqqbx6mkh5ue86mef2b8wfpt.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2177, 'commodity', '/kəˈmɑːdəti/', 'commodity.mp3', 'n.商品，货物', 'f3c82c9c2b0cf165233a077bfdfa6cf5_80150_1535595851.jpeg', '20140915_23_27_12_40_v3.png', 'You can find many commodities in supermarkets.', '你可以在超市看到各种各样的商品。', '75db9ed5fab2c04fe3f69a70d9df50da_34522_1535595846.mp3', 'com共同 + mod方式，模式，风度 + ity名词后缀 → 有共同模式的东西 → 商品', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2178, 'correspond', '/ˌkɔːrəˈspɑːnd/', 'correspond.mp3', 'v.相似', '4013582fc088a1fbff038f0f324f4695.jpg', 'd_16_4394_0_2_20150808224219.png', 'The clothes of the mother and the daughter correspond closely.', '这对母女的衣服极其相似。', 'd55e8a1177b7401efd999ab50c9283d3_45262_1600307888.mp3', 'cor共同 + respond回应 → 相互回应 → correspond通信，符合', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2179, 'correspond with', '/ˌkɔːrəˈspɑːnd wɪθ/', 'correspond with.mp3', 'phr.与……通信', 'ac76fd0eced11790b3080cfc06a2d693_176405_1561953080.jpg', '', 'The couple used to correspond with each other.', '这对夫妇过去常常互相通信。', '59fd425ad0d0421f71478bd7092642ad_24314_1561953080.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2180, 'decrease', '/dɪˈkriːs/', 'decrease.mp3', 'v.减少；  n.减少', 'i_33_4181_0_4_20150808235450-gigapixel-scale.jpg', 'd_107_4181_0_2_20150809004735.png', 'Our sales have decreased for the last two years', '过去两年我们的销售额都在减少，现在我们没钱了。', 'sa_33_4181_0_4_20150808235450.aac', 'de向下 + crease增长 → 向下增加 → 减少', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2181, 'directly', '/daɪˈrektli/', 'directly.mp3', 'adv.直接地，径直地', '3_0_20160607180027_20258_c-gigapixel-scale.jpg', 'd_13_8282_0_2_20150808195056.png', 'Why take the long way while you can walk directly to the company?', '既然你能径直走去公司，为什么还要绕远路？', 'e69e5d276b9208f2b4b7c673f70742da_21989_1610447766.mp3', 'di使...变成 + rect直 + ly…地 → direct直接的 + ly...地 → 直接地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2182, 'discharge from', '/dɪsˈtʃɑrdʒ frʌm/', 'discharge from.mp3', 'phr.允许离开', 'e45b57d475a9635485da0037921e4a26.jpg', '', 'The doctor agreed to discharge her from the hospital.', '医生同意让她出院了。', 'efe3f3f76d3c4f210018a400d1f489c4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2183, 'economist', '/ɪˈkɑːnəmɪst/', 'economist.mp3', 'n.经济学家', '006dc4714bad6905e1ea827c3ac4e6ad_185501_1570781927.jpeg', '', 'This famous economist is often referred to as the Father of Economics.', '这位著名的经济学家常被称作“经济学之父”。', '409bee93cb7849a519df6029020799c3_43798_1570781924.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2184, 'expand', '/ɪkˈspænd/', 'expand.mp3', 'v.扩大；膨胀；详细展开', 'f633bbe1b0d12e4b09bafc4deaefc63f_32179_1656994221.jpg', 'd_16_4509_0_2_20150808224306.png', 'Our business is expanding across the whole country.', '我们的业务正在全国范围内扩大。', 'dhdwbduhl48gxdlmsbs2zj97lafx9pea.mp3', 'ex出 + pand展开，膨胀 → expand伸展', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2185, 'explanation', '/ˌekspləˈneɪʃn/', 'explanation.mp3', 'n.解释，说明', 'cfd0c6c98cf4cbd40651daf9c9334a05_181826_1585133120.jpeg', 'd_16_7919_0_2_20150808232129.png', 'The boy is giving his explanation for why he arrived late for school.', '男孩正在解释他上学迟到的原因。', '4b42ba7e49b51465_1266883322080483966_250207.mp3', 'explan=explain解释 + ation名词后缀，表行为 → explanation说明，解释', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2186, 'fall in with', '/fɔːl ɪn wɪð/', 'fall in with.mp3', 'phr.和...一致', '035b962b367f7a6a72c5a1a9625db129.jpg', '', 'His views on coffee fall in with mine.', '他对咖啡的看法和我的一致。', 'd03e0d337b2d80ce11cc2e1d58589d0e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2187, 'favorable', '/ˈfeɪvərəbl/', 'favorable.mp3', 'adj.赞同的，称赞的', 'ad304fb373312f9b9425e28c14be6059_116760_1696643506.jpg', 'd_107_11508_0_2_20150809025426.png', 'My colleagues are favorable to my creativity.', '我的同事们对我的创意交口称赞。', 'us_My_colleagues_20231007095153108_07274e0b8b9a0be770a7.mp3', 'favor赞同 + able……的 → favorable赞同的，有利的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2188, 'fever', '/ˈfiːvər/', 'fever.mp3', 'n.发热', '5039be49982b815658a611d15f1519e6_91053_1575012753.jpeg', '20130130_16_22_39_433.png', 'The girl is sick and has a high fever.', '这个女孩生病了并且发高烧。', '43e19a61062a6f4e_1268213314148844504_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
