INSERT INTO `words` VALUES (2221, 'visa', '/ˈviːzə/', 'visa.mp3', 'n.签证', '9ee3d0d5eb58cc9dc1de2ccfe41960b5_53938_1573885332.jpeg', '20140718_15_37_07_154_v3.png', 'I\'ve got my visa ready', '我拿到了我的签证，现在我可以环游世界啦！', 'efda90e7cbbc66ce264c55ea324afdd2_44960_1603269761.mp3', 'vis看 + a → 审视，审查 → 审查后的签证 → visa签证，签准', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
