INSERT INTO `words` VALUES (2223, 'worthy', '/ˈwɜːrði/', 'worthy.mp3', 'adj.值得……的，配得上……的', '3eec8409502ec66d9ae6c8cb745a2813_140789_1718616112.jpg', 'd_16_9186_0_2_20150808233955.png', 'She is worthy of respect as she sacrificed herself for others.', '她舍己为人的精神值得尊敬。', 'us_She_is_20240617170825162_a0842938a05c3523aace.mp3', 'worth价值，价格 + y形容词后缀 → worthy值得...的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
