INSERT INTO `words` VALUES (2225, 'advance', '/ədˈvæns/', 'advance.mp3', 'n.预先；进步，进展；增长；  v.提前；提升；预付', 'b433eff0b71d3e90a9cd290779932cf4_168181_1732170966.jpg', 'd_16_5629_0_5_20150808225611.png', 'He finished his homework in advance.', '他提前做完了作业。', '7af1edf43601e8e382997b6a2e5f3983_18930_1576219159.mp3', 'ad离开 + vance前面的 → advance提升', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
