INSERT INTO `words` VALUES (2227, 'bound', '/baʊnd/', 'bound.mp3', 'adj.必然的；有义务的；受约束的，（在法律或道德上）有义务的；  v.束缚；跳跃着前行；  n.跳跃；范围；界限', '11a309647ece145269b4ad9c9d19833b_194339_1587651611.jpeg', 'd_12_348_0_2_20150808150745.png', 'The prisoner is bound to face his execution.', '这个犯人必然会面临死刑。', '1776216476334da0701cee0ca6bc943f_17287_1587651632.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2228, 'campus', '/ˈkæmpəs/', 'campus.mp3', 'n.校园', 'c8894c78da2bcdfc89921a3be12d48ad_94363_1578555883.jpeg', 'd_1_4327_0_3_20150808122634.png', 'On our campus', '在我们的校园里，我们可以坐在草坪上做小组作业。', 'd621f550b09937865e26a5c756caa6e7_23086_1619341419.mp3', 'camp田野 + us用 →用田野建造学校→ campus校园', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2229, 'commerce', '/ˈkɑːmɜːrs/', 'commerce.mp3', 'n.商业，贸易', '6ef53b754a956125a465b7f7e34b3eac_43456_1538581986.jpg', 'd_107_6291_0_2_20150809015513.png', 'The commerce mode is completely changed by online platform.', '商业模式完全被线上平台的出现改变了。', 'wsq8y6h6vuqtnstbcjf75vew7bz5fpzh.mp3', 'com共同 ＋ merce交易 → 共同交易 → commerce商业', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2230, 'commit', '/kəˈmɪt/', 'commit.mp3', 'v.犯（罪）；进行 (自杀)；承诺', '83005c0f080d886a0499599b0432ff92_183171_1595060930.jpg', 'd_16_9165_0_2_20150808233921.png', 'The fox committed a crime and was sent to prison.', '狐狸犯了罪，并被抓进了监狱。', '164429110b4f2ce9_1266883634394540994_250207.mp3', 'com一起 + mit释放，抛出 → 某种行为的宣泄 → commit承诺，自杀', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2231, 'crisis', '/ˈkraɪsɪs/', 'crisis.mp3', 'n.危机；危急关头，存亡之际', 'bec48fc2662328355be77331fe19c278_41665_1584004320.jpeg', '20130311_16_48_14_173.png', 'He found himself in a crisis after disturbing the beehive.', '他扰动了蜂窝，然后发现自己陷入了危机。', '7a8b5cc7821b5143f1edcdf10210e1c9_49272_1584004317.mp3', 'cris判断，分辨 + is → 需要作出判断的时刻 → crisis危机时刻', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2232, 'differ', '/ˈdɪfər/', 'differ.mp3', 'v.相异，不同于', '151ffd64290794eae2ae9762b4e2fccf_62043_1565342599.jpg', 'd_16_4884_0_2_20150808224522.png', 'The red paper guy differs from the others in color.', '这个红纸人的颜色不同于其他人。', '317f0023d3b8389c_1266883330973150008_250207.mp3', 'di分开 + ffer运行 → differ不同', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2233, 'dream', '/driːm/', 'dream.mp3', 'n.梦；  v.做梦', 'a90ed5af4c80028cffb8c79eb95fff2c_186550_1704957748.jpeg', 'd_24_2710_0_4_20150808223250.png', 'In my dream', '我在梦里去了夏威夷海滩。', '2q5fjny3td7uyv6bj7upzmcexu4zp4fk.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2234, 'electricity', '/ɪˌlekˈtrɪsəti/', 'electricity.mp3', 'n.电，电力；电流；电学', '778473bc1683b8338244d02f4785c8b2_172322_1590139835.jpg', 'd_24_5690_0_4_20150808224258.png', 'He touched the socket with a wet finger and the electricity gave him a shock.', '他用湿的手指碰到了插座，被电到了。', '69d8d176a2ceb388e162c8bcfde0f070_38051_1532154992.mp3', 'electric电的 + ity名词后缀 → electricity电力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2235, 'environment', '/ɪnˈvaɪrənmənt/ ', 'environment.mp3', 'n.自然环境；生活或工作环境；工作平台', 'd62ed563c69519254808335893bc7625_97013_1595468882.jpeg', 'd_107_4929_0_2_20150809011118.png', 'They are picking up trash to keep the environment clean.', '为了保持环境整洁，他们正在捡垃圾。', 'f7a94a42bd0c07b9ba9278ad7ae08ed9_45056_1595929657.mp3', 'environ包围，环绕 + ment表名词 → environment环境', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2236, 'Europe', '/ˈjʊrəp/', 'Europe.mp3', 'n.欧洲', '631429169e8e00bb624f26b9d6b36c27_98126_1588138722.jpeg', '20130301_11_03_43_809.png', 'All these famous buildings are in Europe.', '这些有名的建筑都在欧洲。', 'l7ah8pvqp2v9nxet3q5dmfb76yshv7ec.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2237, 'familiar', '/fəˈmɪliər/', 'familiar.mp3', 'adj.熟悉的，通晓的；不拘礼节的；亲密的；随便的；  n.密友；常客；高级官吏的家属', 'i_1_5592_0_3_20150808124038-gigapixel-scale.jpg', 'd_24_5592_0_4_20150808224215.png', 'Its owner\'s voice is very familiar to the dog.', '狗对它主人的声音很熟悉。', '011b046353a877fb_1266883484720409390_250207.mp3', 'famili家庭 + ar……的 → familiar熟悉的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2238, 'field', '/fi:ld/', 'field.mp3', 'n.田野，田地；运动场', '4aec393c8b2cff24cec626c270ae3c32_87721_1577951976.jpeg', 'd_24_17178_0_3_20150808232248.png', 'There is a large field around the farm house.', '农舍周围有一大片田野。', '7af6e909faf9a32a_1266763241935166108_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2239, 'fold', '/foʊld/', 'fold.mp3', 'v.折叠；彻底失败；合拢；  n.折叠；褶皱', 'i_1_9300_0_3_20150808131357-gigapixel-scale.jpg', 'd_24_9300_0_3_20150808230148.png', 'I fold the pink paper to make a paper heart.', '我将这张粉色的纸折叠成一颗纸心。', 'v9cqbnes78sj43ur7b4gkv5jzuwzla2a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2240, 'foreign', '/ˈfɔːrən/', 'foreign.mp3', 'adj.外国的，外来的', 'i_24_15913_0_7_151220120241-gigapixel-scale.jpg', 'd_24_15913_0_4_20150808230800.png', 'Our English teacher is from a foreign country.', '我们的英语老师来自外国。', 'sa_24_15913_0_7_160104160123.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2241, 'get off', '/ɡet ɑf/', 'get off.mp3', 'phr.从…下来；把手拿开', 'eba96540810a5f56f5a4b6aa803863d6_100349_1736136083.jpg', '', 'After several hours on a plane', '数小时的飞行之后，乘客们很开心终于可以下飞机了。', 'us_After_several_20250224104512630_54b3aa86db6bd91e5b37.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2242, 'give in', '/ɡɪv ɪn/', 'give in.mp3', 'phr.投降', '3_0_20160718113040_98789_c-gigapixel-scale.jpg', '', 'He finally gave in to me and admitted that I\'m the winner.', '他最终向我投降，并承认我赢了。', '3_0_20160718113040_42700_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2243, 'imagine', '/ɪˈmædʒɪn/ ', 'imagine.mp3', 'v.想象，幻想；设想，猜想；认为', 'a45e5ff85f093e3cef8f002491b44818_91276_1734420410.jpg', '20130130_16_11_04_314.png', 'The girl imagines a universe in the book.', '小女孩想象书中有宇宙。', 'mvrj5gq7h6mqurna68cgwbutluvc9hf7.mp3', 'imag=image图像 + ine……的 → 有关图像的 → imagine想象', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2244, 'in accordance with', '/ɪn əˈkɔːrdəns wɪð/', 'in accordance with.mp3', 'prep.按照', '84697c6a9da9b8e29c01ebf48fb7c6a9.jpg', '', 'In accordance with his last wish', '遵照他的遗愿，人们把他安葬在了河边。', '7b420b43b9056c7536818607752def80_22772_1619320961.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2245, 'investigate', '/ɪnˈvestɪɡeɪt/ ', 'investigate.mp3', 'v.调查，查明', 'b38bbf79872dc72088cc42131f5a111b_188033_1585038841.jpeg', 'd_13_5828_0_3_20150808183904.png', 'He\'s investigating the footprints', '他正在研究脚印，寻找线索来帮助破案。', 'r3frkkd4k77f53zubqwbzgqmmxcs9t9x.mp3', 'in进入 + vestig脚印，踪迹 + ate动词后缀 → 根据踪迹调查 → 调查', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2246, 'keep up with', '/kip ʌp wɪð/', 'keep up with.mp3', 'phr.跟上，紧跟', '5_44_346_20161125123528_17887_c.jpg', '', 'The two men are trying to keep up with the man riding the bike.', '后面的两个人在试着跟上这个骑自行车的人。', 'd7b8cf86c2ce93e0_1266883625415125782_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2247, 'liberation', '/ˌlɪbəˈreɪʃn/', 'liberation.mp3', 'n.解脱，解放', 'f020dcd766f79452facb75807ed332bc_58163_1541843300.jpg', 'd_109_1733_0_2_20150809053402.png', 'The man finally got his liberation.', '这个男人终于得到了解放。', '2fd8cfab47e562db61cbce89354f134b_13995_1625735593.mp3', 'liber自由 + ation名词后缀 → 使自由 → liberation解放；释放', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2248, 'link', '/lɪŋk/', 'link.mp3', 'n.链接；  v.连接', 'db68cfea12c068e419b4af9d0e06036d_128898_1570871985.jpeg', '20141012_00_24_57_509_v3.png', 'Click the link and buy the backpack from this online store.', '点击链接来这个线上商城买个双肩包吧。', '0812358687e71ff085a4bd13d075ed95_20421_1619148680.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2249, 'liver', '/ˈlɪvər/', 'liver.mp3', 'n.肝脏', '3931e52dfb28b90767c6f7cc65721b44_119350_1538759045.jpg', 'd_105_6283_0_2_20150809055619.png', 'The largest internal organ in a human body is the liver.', '人体最大的内脏是肝脏。', '41e54d38593e661669aad65d6892c247_16815_1555296243.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2250, 'mess', '/mes/', 'mess.mp3', 'n.凌乱，脏乱，杂乱；肮脏；困境，混乱；  v.弄脏，弄乱；随地便溺', 'b0cd804463a4171ec1e9ba163a537afe_126943_1538666491.jpg', '20141013_21_14_26_598_v3.png', 'The living room is in a mess after a party.', '一场聚会后，客厅里乱糟糟的。', '2f7e01a27b930f434dc8013453d12fed_12740_1538666520.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2251, 'minister', '/ˈmɪnɪstər/', 'minister.mp3', 'n.部长，大臣', 'i_1_3839_0_2_20150808121932-gigapixel-scale.jpg', 'd_105_3839_0_2_20150809053424.png', 'The government minister is giving a speech.', '政府部长在演讲。', 'be7376a14357780a_1266883370593004420_250207.mp3', 'mini小 + ster名词后缀，人 → 小人 → 古代大臣称自己是“小人” → minister部长，大臣', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2252, 'moreover', '/mɔːrˈoʊvər/', 'moreover.mp3', 'adv.此外，而且', 'd257e0796ba12dadd1d9647e356487b5_76878_1538757192.jpg', 'd_107_3909_0_2_20150809003425.png', 'His work is busy; moreover', '他工作很忙，此外，还有一个面试和两通电话在等着他。', '4c830129f80fcb12d3a1470423998f03_31549_1629710266.mp3', 'more此外 + over越过 → moreover再者，此外', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2253, 'municipal', '/mjuːˈnɪsɪpl/', 'municipal.mp3', 'adj.市政的；市的', '949dfa8e8ceceb41cb7a09040805b97d_87935_1522722736.jpg', '', 'This beautiful building is home to the municipal government of San Francisco.', '这个漂亮的建筑是旧金山市政府所在地。', '1b2ddd983c2f8f0333fbf09f55922ca6_45738_1522722728.mp3', 'muni为社区提供的服务，职责 + cip抓，拿 + al表形容词 → municipal市政的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2254, 'notice', '/ˈnoʊtɪs/', 'notice.mp3', 'n.告示，通知；  v.注意到，意识到', 'i_1_10978_0_4_150917171931-gigapixel-scale.jpg', 'd_24_10978_0_3_20150808230520.png', 'The girl puts the notice on the bulletin board.', '女孩把告示张贴在公告栏上。', 'bc306464994a0bd5_1266883015073290794_250207.mp3', 'not知道 + ice名词后缀 → notice 通知', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2255, 'out of the question', '/aʊt əv ðə ˈkwestʃən/', 'out of the question.mp3', 'phr.不可能', '5_44_190_20170329105554_28585_c.jpg', '', 'It is out of the question for him to finish his work tonight.', '他今天晚上不可能完成手头上的工作。', '5_51_403_20170422112721_33551_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2256, 'patience', '/ˈpeɪʃns/ ', 'patience.mp3', 'n.耐心，忍耐', '278c6f366fabb2c71f528cacfc76279f_184335_1604977903.jpg', 'd_24_9309_0_3_20150808230153.png', 'Fishing is a sport that requires a lot of patience.', '钓鱼是一项很需要耐心的运动。', '7d100a4b9c2c48ad_1266883635883650008_250207.mp3', 'pati忍受 + ence表示性质、状态 → 能忍受 → patience忍耐，容忍，耐心', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2257, 'popular', '/ˈpɑːpjələr/', 'popular.mp3', 'adj.大众喜爱的，广受欢迎的', 'f8299728c76f7bf843d86fdc24a37871_744012_1610615439.jpg', 'd_24_6956_0_3_20150808224851.png', 'This guy is so popular. He received thousands of likes on social media.', '这个人非常受欢迎，他在社交媒体上收到了数千个“赞”。', '52ryherqaxn9wkfvkdat38t53dax5syr.mp3', 'popul=people人 + ar形容词后缀 → 被很多人喜欢的 → popular受欢迎的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2258, 'pose', '/poʊz/', 'pose.mp3', 'n.姿势；装腔作势，伪装；  v.摆造型；  v.主张，提出；引起，导致，造成', 'd1832fcbb5e4dff3e29928ca51f65f00_118650_1624069786.jpg', 'd_107_5988_0_2_20150809014749.png', 'The model made a pose in front of the camera.', '模特在镜头前摆出了一个姿势。', '5ysku4wueaq9cp4mk8mn53rzxmdvuwjq.mp3', 'pos放 + e → 摆放造型 → pose姿势', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2259, 'prosperous', '/ˈprɑːspərəs/', 'prosperous.mp3', 'adj.富裕的；茁壮生长的', 'c2b38f2b920615ff239f57fe1d656a70_198218_1538668349.jpg', 'd_107_8519_0_2_20150809023511.png', 'Look at his fancy car! He might be a prosperous man.', '看看他的豪车！他可能是个有钱人。', '47d8d371d9f528473b5b4850d3160be7_20108_1538668374.mp3', 'pro向前 ＋ sper希望 ＋ ous形容词后缀 → 带着希望向前 → prosperous兴旺的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2260, 'quake', '/kweɪk/', 'quake.mp3', 'v.震动；颤抖', '3_0_20160607175207_80521_c-gigapixel-scale.jpg', 'd_105_2171_0_2_20150809053308.png', 'I can feel the floor quaking.', '我能感觉到地面在震动.', 'us_I_can_20220808181437025_c40b2401bcd58f59d0ee.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2261, 'quality', '/ˈkwɑ:ləti/', 'quality.mp3', 'n.质量；  adj.优质的', 'e13a0121260c57bc577edfb0527ec358_30494_1733123254.jpg', 'd_24_7847_0_3_20150808225143.png', 'The quality of this spoon is too terrible!', '这勺子的质量太差了！', '0ec977c92930bfce_1266797979750718194_250123.mp3', 'qual资格 + ity表名词 → quality质量；品质，特性', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2262, 'raise', '/reɪz/', 'raise.mp3', 'v.举起，抬高；提升；筹集，筹（钱）；增加；提高', 'i_1_6959_0_3_20150808125654-gigapixel-scale.jpg', 'd_24_6959_0_4_20150808224853.png', 'The kitten raises his friend up to steal the fish.', '这只小猫咪把朋友举起来偷鱼。', '775028e535de15f1_1266883375284050518_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2263, 'rest', '/rest/', 'rest.mp3', 'n.休息，休息时间；剩余部分；  v.休息，放松', 'bf6a46b58f513eaef5a2bf095c7ae13f_79084_1578627947.jpg', 'd_24_15916_0_4_20150808230819.png', 'On Sunday I like to sleep late and get more rest.', '星期天我喜欢睡懒觉，多休息会儿。', '204407cc1fb8b3ca_1266763526258928550_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2264, 'result from', '/rɪˈzʌlt frəm/', 'result from.mp3', 'phr.起因于', '5affcc9b5bf4464b99b52f28cf9a013b_118419_1680748217.jpg', '', 'His big belly #resulted from# his bad eating habits.', '他的大肚子是由他的不良饮食习惯导致的。', '5beafcac820a01f6a5aee63dfccb0187_36043.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2265, 'rise', '/raɪz/', 'rise.mp3', 'v.升起，上升，上涨；  n.增长', 'a4751f11f2f0db931558d821b55eb60b_87061_1701057134.jpg', 'd_24_15929_0_4_20150808230846.png', 'The bright sun rises on the horizon.', '明亮的太阳从地平线上升起。', '0c4ad61432989462_1266798141923678918_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2266, 'scarce', '/skers/', 'scarce.mp3', 'adj.缺乏的，不足的；稀少的，罕见的；  adv.仅仅，几乎不', '3_0_20160720070914_38182_c-gigapixel-scale.jpg', '20130616_01_34_35_532.png', 'Oil is becoming increasingly scarce on Earth.', '地球上的石油已经变得越来越匮乏了。', '3_0_20160720070914_16295_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2267, 'shirt', '/ʃɜːrt/', 'shirt.mp3', 'n.（尤指男式的）衬衫', 'i_67_14153_0_4_20150809024201-gigapixel-scale.jpg', 'd_93_14153_0_4_20150809002221.png', 'He always has to wear a shirt and tie to work.', '他总是穿衬衫打领带去工作。', 'e11fbe7c433126ed_1268213309702685332_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2268, 'spade', '/speɪd/', 'spade.mp3', 'n.铁锹，铲子', 'i_1_6908_0_3_20150808125627-gigapixel-scale.jpg', '20121225_20_32_40_949.png', 'A farmer uses a spade to remove soil easily.', '农夫用铁锹就能轻松地把土铲起来。', 'sa_1_6908_0_3_20150808125627.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2269, 'speech', '/spiːtʃ/', 'speech.mp3', 'n.演说，讲话，发言', '3_0_20171001071354_98227_c-manual-scale.jpg', 'd_24_18086_0_4_20150808234439.png', 'The public speaker looks confident during his speech.', '这位发言人在他演讲时看上去胸有成竹。', '526266481ee5303e_1266883009823026114_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2270, 'stranger', '/ˈstreɪndʒər/ ', 'stranger.mp3', 'n.陌生人', '3_0_20160718113129_16835_c-gigapixel-scale.jpg', 'd_24_17031_0_4_20150808231944.png', 'Kids', '小朋友，小心拿糖给你吃的陌生人！', 'c7fc2523560f2ae0_1266883373098162930_250207.mp3', 'strang陌生的 + er人 → stranger陌生人；新来者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2271, 'sunshine', '/ˈsʌnʃaɪn/', 'sunshine.mp3', 'n.日光，日照', '4326e7d636c20c33192b0dfb097dd34b_31883_1565679441.jpg', 'd_24_15949_0_3_20150808230933.png', 'The sunshine broke through the clouds.', '阳光穿透了云层。', '28fbcdc82c2d4a1607818c74dc514323_31416_1580894757.mp3', 'sun太阳 + shine光亮 → sunshine日光，日照', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2272, 'teller', '/ˈtelər/', 'teller.mp3', 'n.出纳员', '0bb46e63d2f6b91ed8f8a29d53ea5763.jpg', '', 'Tellers deal with customers face-to-face in the bank', '银行出纳员与客户面对面打交道，包括给出和收取现金。', '57cde37b13954575bde14962b52c8016.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2273, 'touch on', '/tʌtʃ ɑːn/', 'touch on.mp3', 'phr.涉及', '55d5c5d23c4b66dac736706f40ba28b1.jpeg', '', 'His talk touched on rising house prices.', '他的讲话涉及房价上涨的问题。', '0e258c061008d20ebf2906507b4f137a_49678_1599550253.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2274, 'toward', '/tɔːrd/', 'toward.mp3', 'prep.向；朝；对于', 'i_2_19286_0_6_160427105950-gigapixel-scale.jpg', 'd_24_19286_0_3_20150809001159.png', 'The little girl is walking toward her father.', '这个小女孩正向爸爸走去。', 'bwv6x8vzrf65j59e4e37cdbt5hdfmvxj.mp3', 'to朝，向 + ward副词后缀，表方向 → toward向', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2275, 'turn', '/tɜːrn/', 'turn.mp3', 'v.使变成', 'c8970703d9d8436b34dae6af2a4f2d04.jpg', 'd_16_17674_0_2_20150809012400.png', 'Green leaves turn yellow in autumn.', '秋天，绿叶变成黄色。', 'us_Green_leaves_20251014095244129_69944ffe92642feb9c48.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2276, 'virtue', ' /ˈvɜːrtʃuː/', 'virtue.mp3', 'n.美德，高尚的道德', '40beb1946fcd29a56d52fde7d0f6d75a_195619_1571130758.jpeg', 'd_107_2609_0_2_20150809002848.png', 'Her kindness is a virtue she shows every day.', '她的美德体现在日常善举之中。', '66545d0576a080fe_1266883486642514792_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2277, 'voice', '/vɔɪs/', 'voice.mp3', 'n.声音；发言权；  v.表达', '5ae67e35983eea615e78fca484348264_90088_1534227927.jpeg', 'd_24_17938_0_4_20150808233616.png', 'Many smart phones have a voice recognition function.', '很多智能手机都有语音识别功能。', 'e8d6943a9e019bf96ba3c058afd837da_36871_1534227921.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2278, 'above', '/əˈbʌv/', 'above.mp3', 'prep.在……之上；过于，超出；  adj.上面的，上述的；  adv.在……上面，上文中，上述', '3aa3a1f3353ecb92f84b2d8c0b7b8345_159499_1577945115.jpeg', 'd_24_17939_0_4_20150808233620.png', 'The bird is flying above the water.', '鸟儿在水面上飞行。', 'c98804c0242c0a0e_1266763522188859938_250117.mp3', 'a在...上面 + bo位于，靠近 + ve高 → above在...之上', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2279, 'absolute', '/ˈæbsəluːt/', 'absolute.mp3', 'adj.绝对的；完全的', '9e4b0278a3512dbcd3bd952d05906f58_201840_1595579413.jpg', 'd_16_7926_0_2_20150808232142.png', 'Marx thought that motion is absolute', '马克思认为运动是绝对的，而静止是相对的。', '15de17fd12b69e14cadff2697fca57a2_25750_1648193756.mp3', 'ab离开 + solute松开，分离 → 不会放手的 → absolute绝对的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2280, 'at most', '/æt moʊst/', 'at most.mp3', 'phr.至多，最多', '9e1868384e120be7edf75d2e632a6d4b_115605_1701669003.jpg', '', 'According to research', '根据研究，小孩子最多能在一节课上集中注意力20分钟。', '5_51_411_20170427193031_39382_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2281, 'available', '/əˈveɪləbl/', 'available.mp3', 'adj.可获得的，可用的', '068f0418fcd566667a1abccf2d373bc9_100987_1604024803.jpg', 'd_24_3837_0_3_20150808223332.png', 'The receptionist told me that there was only one room available.', '前台接待员告诉我只有一个房间可以入住。', '3_0_20170930071209_22377_c.aac', 'avail利用 + able能……的 → 能够利用的；可得到的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2282, 'back up', '/bæk ʌp/', 'back up.mp3', 'phr.援助', 'cea641307e892b5faa8c61ab68e69e6c.jpg', '', 'His colleagues backed him up when he needed help.', '当他需要帮助时，同事们都来支援他。', '56c33d339c23dd0db7b3073b53863fc7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2283, 'believe in', '/bɪˈliv ɪn/', 'believe in.mp3', 'phr.相信', '2d2fd3bd5561e22f884a95dc6a9572e6_78977_1545127243.jpg', '', 'Believe in yourself and you\'ll have a promising future.', '相信自己，你会有一个美好的未来。', '7eb98d4e52b10eeb_1266883374811032374_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2284, 'catch up with', '/kætʃ ʌp wɪð/', 'catch up with.mp3', 'phr.赶上', '9ed17d739baade460ac782ab6399c6aa_203154_1605178571.jpg', '', 'I finally caught up with other people.', '我终于赶上了别人。', '5b24262177402985_1266883371928279744_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2285, 'characteristic of', '/ˌkærəktəˈrɪstɪk əv/', 'characteristic of.mp3', 'phr.……的特征', 'e4eea4d6f57527d9631277d93ac8d334.jpg', '', 'Monkeys have some characteristics of humans.', '猴子有一些人类的特征。', '1c2d5333b6b35ce3164e2d9610f83a2d_38432_1593584206.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2286, 'convert to', '/kənˈvɚt tu/', 'convert to.mp3', 'phr.兑换为', 'f8e8b86566876c3dd1f18208116bb194.jpg', '', 'She converted her euros to American dollars.', '她把欧元兑换成了美元。', 'ca067ff43e181167f208caa83caeddf9_17757_1619166655.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2287, 'convey', '/kənˈveɪ/', 'convey.mp3', 'v.传送，运送', 'i_1_9120_0_4_150923093833-gigapixel-scale.jpg', 'd_107_9120_0_2_20150809024315.png', 'The belt conveys the luggage to the passengers.', '传送带将行李运出来给乘客。', '9df2bf39e1e4408e2077bacdf62bd5ab_16816_1625730960.mp3', 'con共同，一起 + vey路，移动 → 一起在路上移动 → convey运输', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2288, 'cope with', '/koʊp wɪð/', 'cope with.mp3', 'phr.应付，对付，克服', '5_44_185_20170329165322_31941_c.jpg', '', 'How can I cope with all this dirty laundry?', '我该怎么应付这堆脏衣服呢？', '5_51_411_20170427193659_6971_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
