INSERT INTO `words` VALUES (2290, 'critical of', '/ˈkrɪtɪkl əv/', 'critical of.mp3', 'phr.挑剔', 'a5cd75d949b2092d7721d16c63c26f12.jpg', '', 'My boss is always critical of my work.', '我的老板总是对我的工作很挑剔。', 'afb57b1cf4e3a4addaf35671f871b0a8_36512_1593576140.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2291, 'declare', '/dɪˈkler/', 'declare.mp3', 'v.宣布，宣告', '1425952623095-gigapixel-scale.jpg', 'd_16_3913_0_2_20150808223814.png', 'I now declare this meeting open.', '我现在宣布本次会议开始。', '7c43875fe3e3458d_1266883380888361598_250207.mp3', 'de加强 + clare（拉丁语）澄清 → declare表明，声明', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2292, 'doubtful about', '/ˈdaʊtfl əˈbaʊt/', 'doubtful about.mp3', 'phr.对 ... 有怀疑，不能确定的', 'b3a765aa93b6ab667a6701c8ca3da6af.jpeg', '', 'The judge is doubtful about raising which sign. ', '这位评委还不能确定举哪块牌子。', '0332763476577f9421ffe89480175d45_42094_1599622326.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2293, 'dull', '/dʌl/', 'dull.mp3', 'adj.枯燥的，沉闷的', '6c36378d2a84d8886a57cf6a96a4f0fd_52929_1538812285.jpg', '20141010_01_10_10_8_v3.png', 'The TV show is so dull that it makes him feel sleepy.', '这档电视节目很无趣，让他想睡觉。', 'us_The_TV_20250605111709842_647aa8f953d1b949087c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2294, 'eager', '/ˈiːɡər/', 'eager.mp3', 'adj.热切的，渴望的，急不可耐的', 'i_16_9275_0_5_151207155122-gigapixel-scale.jpg', 'd_16_9275_0_2_20150808234151.png', 'The kids are eager to eat the cake on the table.', '孩子们急不可耐地想要吃掉桌上的蛋糕。', 'sa_16_9275_0_5_151125155541.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2295, 'energy', '/ˈenərdʒi/', 'energy.mp3', 'n.活力；精力；能量；能源', '7c9ce256e8c915664eb4ab2f25c546e3.jpg', 'd_24_17140_0_5_20150808232125.png', 'The man is full of energy every morning.', '这个人每天早晨都精力充沛。', '19502ba1f4425a4659e1d67ad77c0798.mp3', 'en在...上 + ergy功 → energy 能量', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2296, 'estimate', '/ˈestɪmeɪt/', 'estimate.mp3', 'v.估价，估计；  n.估价，估计', 'e3f66c2db689193fb01ffb78479d523a_198334_1619317374.jpeg', 'd_1_3905_0_3_20150808122032.png', 'The man is estimating the value of the watch.', '这个男人在给这块手表估价。', '6ae1ed4fd834a9a9_1266883482062334950_250207.mp3', 'estim估计 + ate动词后缀 → estimate估计', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2297, 'extent', '/ɪkˈstent/', 'extent.mp3', 'n.程度；长度', '3_0_20160720070447_4363_c-gigapixel-scale.jpg', 'd_1_7819_0_2_20150808130030.png', 'The extent of the damage from the earthquake is massive.', '这场地震的破坏程度太大了。', 'd400c871260b2e0d_1266883630360976006_250207.mp3', 'ex出 + tent伸展 → 伸出去的范围 → extent范围', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2298, 'fall through', '/fɔːl θrʊ/', 'fall through.mp3', 'phr.失败', '3503d18d47b4b88e17353358da4bfd69.jpg', '', 'His vacation plans fell through because of the forest fire.', '他的度假计划因为森林火灾而泡汤了。', '3eb419ba3a31219b4733916786ae02ee.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2299, 'feed on', '/fid ɔn/', 'feed on.mp3', 'phr.以……为食', 'feedon_10239_20231106_3294fb53.jpg', '', 'I like to feed on whatever my master feeds me.', '我喜欢吃我的主人给我的任何食物。', 'sa_4_10239_0_2_20150808183616.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2300, 'film', '/fɪlm/', 'film.mp3', 'n.电影；薄层；  v.拍摄，拍摄电影', '813fe991f5c57f1891d62c5641bed830_180002_1620986328.jpeg', 'd_24_18014_0_3_20150808234220.png', 'This film tells of a love story that happened on a ship.', '这部电影讲述了一个发生在船上的爱情故事。', '09adee2ae6c2a255_1268213313644741586_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2301, 'free', '/friː/', 'free.mp3', 'adj.自由的；  v.使自由，解放；  adv.自由地', 'i_13_19030_0_2_20150808205625-gigapixel-scale.jpg', '6bca1d1eb914abee3234edcb55796cfd_30865_1551253558.png', 'After quitting my job', '辞职以后，我感觉自己像一只逃出鸟笼的鸟。', '49b6641f0c155f47_1266883323652561574_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2302, 'frighten', '/ˈfraɪtn/', 'frighten.mp3', 'v.使惊恐，使害怕', 'frighten_5819_20231106_744940fe.jpg', 'd_24_5819_0_3_20150808224353.png', 'My brother jumped out of the closet and frightened me.', '我的弟弟从衣柜里跳出来，吓到我了。', 'us_My_brother_20240318133102594_a2b0272056844080ee1a.mp3', 'fright惊恐 + en使… → frighten使惊恐', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2303, 'generous', '/ˈdʒenərəs/', 'generous.mp3', 'adj.慷慨大方的；丰富的', '6262c0bb71b897815904d44e6e0ed094_67482_1658730866.jpg', '20141013_00_45_02_57_v3.png', 'The generous guy just gave the poor man some money. ', '这个慷慨大方的人刚给了这个穷人一些钱。', 'us_The_generous_20220725143556165_01fb3053588c91a52060.mp3', 'gener出生，产生 + ous形容词后缀 → [不断]产生 → generous丰富的，慷慨的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2304, 'gift', '/ɡɪft/', 'gift.mp3', 'n.天赋；礼物，赠品', '7ec5628c2e88de8165351819c2dcd36a.jpeg', '20140926_21_29_43_369_v3.png', 'She has a gift for math.', '她有数学天赋。', 'eeb47cfdbe95692feb36e8aea5801c5d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2305, 'goat', '/ɡoʊt/', 'goat.mp3', 'n.山羊', 'i_1_6817_0_6_151031123111-gigapixel-scale.jpg', '20121225_20_17_20_378.png', 'I love my pet goat even though it eats everything.', '我爱我的宠物山羊，尽管它什么都吃。', '00e256c3ea83b376_1266741813624024060_250113.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
