INSERT INTO `words` VALUES (2307, 'grocer', '/ˈɡroʊsər/', 'grocer.mp3', 'n.食品杂货商', 'i_1_1318_0_3_20150808121701-manual-scale.jpg', 'd_105_1318_0_2_20150809053147.png', 'This grocer is very nice', '这个食品杂货商超好，他总是给我打折。', 'sa_1_1318_0_3_20150808121701.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
