INSERT INTO `words` VALUES (2310, 'hit', '/hɪt/', 'hit.mp3', 'v.命中，击中；完成（指标）；  n.很受欢迎的人（或事物）', '8fafd655e552a6297634f4cbf97654a4_84784_1577953542.jpeg', 'd_24_17717_0_4_20150808233300.png', 'The man was hit by the ball.', '这个男人被球砸中了。', 'p7bzjqht4vntpzfvnb5q2bz89nx78u5m.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2311, 'in case of', '/ɪn keɪs əv/', 'in case of.mp3', 'phr.以防，万一', 'i_908_-908_0_1_160226155801.jpg', '', 'I brought an umbrella in case of rain.', '我带了一把伞，以防下雨。', 'sa_908_-908_0_1_160301100858.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2312, 'industrial', '/ɪnˈdʌstriəl/', 'industrial.mp3', 'adj.工业的；产业的', '21dfa7b1acdd653123ce89a21335820c_109539_1617778166.jpg', 'd_107_4946_0_2_20150809011138.png', 'The industrial area gives out lots of smoke every day.', '这个工业区每天排放大量浓烟。', 'df4a08f6f0a941f2e7c36e637b3e8ae2_116636_1617778151.mp3', 'industrial=industry工业 + ial有...性质的 → a.工业的；产业的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2313, 'installment', ' /ɪnˈstɔːlmənt/', 'installment.mp3', 'n.分期付款；部分；安装，安置', '1423913327148-gigapixel-scale.jpg', '', 'I have to pay for my car in monthly installments.', '我用每月分期付款的方式买了车。', 'sa_2_11416_0_2_20150808163952.aac', 'in不 + stall停止 + ment名词后缀→ 不停地送钱 → installment分期付款', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2314, 'Italian', '/ɪˈtæliən/', 'Italian.mp3', 'adj.意大利的；  n.意大利人', '88a4c6f0cc3bfee2572f4af79eb4d186_182001_1526613545.jpg', '20121225_20_09_31_805.png', 'Many people are fond of Italian food.', '许多人喜欢意大利食物。', 'sa_1_10216_0_4_160125101752.aac', 'Itali意大利 + an...的/人 → Italian意大利的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2315, 'keyboard', '/ˈkiːbɔːrd/', 'keyboard.mp3', 'n.键盘', '20150528_172527_1_18030-gigapixel-scale.jpg', '20121225_20_27_19_60.png', 'I can\'t focus on my work with such a lovely keyboard.', '这么可爱的键盘简直让我不能专心工作了。', 'hkmn33s3a5yp62j68wfqdfdu2jn4radq.mp3', 'key键 + board板子 → keyboard键盘', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2316, 'lane', '/leɪn/', 'lane.mp3', 'n.小径', '20120430_04_12_44_272-gigapixel-scale.jpg', 'd_105_3925_0_2_20150809053536.png', 'This lane will lead you to cross the forest.', '这条小径会带你穿过森林。', 'sa_1_3925_0_3_20150808122059.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2317, 'late', '/leɪt/', 'late.mp3', 'adv.迟，晚', '24450867581fa119723ab83d242f5848.jpeg', '20121225_18_23_13_972.png', 'She stayed up late working.', '她工作到很晚。', '5612fe2c771db197_1266763524488801138_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2318, 'Latin', '/ˈlætn/', 'Latin.mp3', 'n.拉丁语；  adj.拉丁的', '3e6db669a235735a60f70d0696fe22d3_96965_1580891017.jpg', '', 'Latin is a language which the ancient Romans used to speak.', '拉丁语是古罗马人使用的语言。', 'a1c3086ad7227449_1266883485436128068_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2319, 'learn', '/lɜːrn/', 'learn.mp3', 'v.得知', '89c228f093dba1bfc27cc20c189363f1.jpeg', 'd_24_18076_0_3_20150808234339.png', 'He just learned about the earthquake from the newspaper.', '他刚刚从报纸上得知了地震的新闻。', '2d392031d8c16e91fcdd6b39b290a642_44782_1600311348.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2320, 'loan', '/loʊn/', 'loan.mp3', 'n.贷款；  v.借贷', 'bbf3e712e06211727cc0cb236e7c0f4d_93909_1584087943.jpeg', 'd_107_3926_0_2_20150809003521.png', 'He is applying for a loan so that he can afford to buy the house.', '他正在申请一笔贷款，这样他就买得起房子了。', 'd3794aee1397ef6861d980e5b244e7ea_47220_1584087941.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2321, 'married to', '/ˈmærid tuː/', 'married to.mp3', 'phr.和 ... 结婚，致力于…的', '020bde834adc05615b539e1d4bb9f339.jpeg', '', 'He\'s a teacher who is married to his job.', '他是一位教师，一心扑在自己的工作上。', '27a916e95491f06d630db35f90db4032.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2322, 'meaning', '/ˈmiːnɪŋ/', 'meaning.mp3', 'n.意思，含义', 'i_1_1821_0_4_151030112118-gigapixel-scale.jpg', 'd_24_1821_0_3_20150808223200.png', 'This word has so many different meanings.', '这个单词有很多不同的意思。', 'sa_1_1821_0_4_151109160320.aac', 'mean意思 + ing表示行为、状态、情况及其他 → meaning意义，意思', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2323, 'meat', '/miːt/', 'meat.mp3', 'n.肉，肉类（“肉类”复数meats）', 'b25eda17c8c099e7041cc5d4731c5631_45972_1760080908.jpg', 'd_24_17638_0_3_20150808233129.png', 'Vegetables are fine', '蔬菜是不错，但是我还是更喜欢吃肉。', 'c7582404de165854_1268213308860154798_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2324, 'most', '/moʊst/', 'most.mp3', 'pron.大部分', '45f37c8faa27338ec5e760d631296be2.jpg', 'd_24_19272_0_3_20150809001117.png', 'Most of the balloons are green.', '大多数气球是绿色的。', 'b16c191528a3a3188466d5e110b08494_49088_1596781772.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2325, 'motor', '/ˈmoʊtər/', 'motor.mp3', 'n.马达，发动机', 'i_1_7927_0_3_20150808130149-gigapixel-scale.jpg', 'd_24_7927_0_4_20150808225240.png', 'This is the motor of the four-wheel drive.', '这是这辆四驱车的马达。', 'sa_1_7927_0_3_20150808130149.aac', 'mot移动，动 + or表示物 → motor发动机，电动机', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2326, 'movement', '/ˈmuːvmənt/', 'movement.mp3', 'n.动作；（交响乐的）乐章', 'c08b7675667404e419406adeb3859f9d_100605_1601198802.jpg', 'd_24_4928_0_3_20150808223655.png', 'Dancing is the art of movement.', '舞蹈是动作的艺术。', 'a1d7846052e40a93_1266883482623978490_250207.mp3', 'move动 + ment表名词 → movement运动', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2327, 'multiply by', '/ˈmʌltəˌplaɪ baɪ/', 'multiply by.mp3', 'phr.乘以', '903091cf864af3ab7c17ba6a1239a6b0.jpg', '', 'Two multiplied by three is six.', '2乘以3等于6。', 'fcf60fa8458c3d78da7364dbeedfef03.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
