INSERT INTO `words` VALUES (2329, 'objection to', '/əbˈdʒekʃn tuː/', 'objection to.mp3', 'phr.反对…', '60e07c874ff656a1dab57498456bb29d.jpg', '', 'She showed her objection to the other teacher\'s words.', '她对另外一位老师的话表示反对。', '5eb78d811c578266938893d80a0c8f93_45344_1593586402.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2330, 'open', '/ˈoʊpən/', 'open.mp3', 'adj.开放的，空缺的', 'c722f9db0fe124aa0bd7ec4d91614f2e.jpeg', 'd_24_17281_0_3_20150808232556.png', 'The job is still open for applicants.', '这个职位仍对应聘者开放。', '99ccbaf94a5043fda946865fef1f2dc3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
