INSERT INTO `words` VALUES (2332, 'origin', '/ˈɔːrɪdʒɪn/', 'origin.mp3', 'n.起源；由来，来源；出身', 'c07b3ea667e624205994561d439d2529_97826_1568713253.jpg', 'd_16_4941_0_2_20150808224641.png', 'The origin of humankind is still mysterious', '虽然人类的起源仍然是谜，但是我们认为我们的祖先生活在树上。', 'a4861627ff10b981b77e3887b868b1d1_30765_1551840746.mp3', 'origin=orig升起，开始 → [生命]开始 → origin起源', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2333, 'particular', '/pərˈtɪkjələr/', 'particular.mp3', 'adj.特别的，不寻常的；格外的；挑剔的，讲究的；  n.细节', '65756825034e5f10cd34b153493fa09f_67445_1690777999.jpg', '3_66_20170717143412_9993_c.png', 'I chose five particular people.', '我选出了五个与众不同的人。', 'e0c18fd1de07eae5_1266883008929377186_250207.mp3', 'partic少量 + ular形容词后缀 → particular特别的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2334, 'plant', '/plænt/', 'plant.mp3', 'n.植物；发电厂；  v.种植', '2c578abb65ac403d7c8388f4dd06b197_79175_1577955248.jpeg', '20121227_13_57_52_400.png', 'There are many different kinds of green plants.', '这里有许多不同种类的绿色植物。', 'e78941e2e8340b60_1266883492873067032_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2335, 'plumber', '/ˈplʌmər/', 'plumber.mp3', 'n.管道工，水管工人', 'i_4_2092_0_5_151218161526-gigapixel-scale.jpg', '20140828_20_08_17_480_v3.png', 'The plumber is trying to fix the sink.', '水管工正在修理水槽。', 'dreltzyskwyun5hh8cxvn3n3yay7uxcm.mp3', 'plumb铅锤 + er人，不少管道用铅做成 → 修管道的人 → plumber管道工', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2336, 'product', '/ˈprɑːdʌkt/', 'product.mp3', 'n.产品，制品；产物', 'dfe0fb9550bde4509a4de098ed7803de_147598_1610697213.jpg', 'd_24_4918_0_4_20150808223646.png', 'These products are made of milk.', '这些产品都是由牛奶制成的。', 'ccjalwagm8esakgesbg7b72mr6umq8vv.mp3', 'pro向前 + duct引导，带来 → 引出的东西 → product产物，产品', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2337, 'pull out', '/pʊl aʊt/', 'pull out.mp3', 'phr.退出', '22a58b2ced2ab9b4991da5ab883a60d8_390103_1613718892.jpg', '', 'After the battle', '交战后，部队坐直升机撤退了。', 'sa_50_20419_0_3_20150809020340.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2338, 'ratio', '/ˈreɪʃioʊ/', 'ratio.mp3', 'n.比率，比例', 'i_1_3957_0_4_20150808122136-manual-scale.jpg', 'd_107_3957_0_2_20150809003710.png', 'The ratio of boys to girls is about 2 to 1 in the club.', '这个社团的男女比率大概是2比1。', '8cade1d17aab871df492cf11785a0dc1_22616_1628478007.mp3', 'rati=rate比率 + o表名词，状态 → ratio比率，比', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2339, 'recent', '/ˈriːsnt/', 'recent.mp3', 'adj.最近的', 'cc54fe71593c66da4d4a808569a9e1bf_187308_1750038815.jpg', '9ba79b361a5c855b035a0c003b7eeb50_27758_1565766970.png', 'These are my recent photos.', '这些是我最近拍的照片。', '3_0_20170713071517_30705_c.aac', 're再 + cent新鲜的，年轻的 → recent最近的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2340, 'region', '/ˈriːdʒən/', 'region.mp3', 'n.地区，区域，地带；身体部位', '52776ce96b22e64fb7972777c7123710_167436_1573871423.jpeg', 'd_1_8210_0_4_20150808130503.png', 'Milk is produced in these regions.', '这些地区生产牛奶。', '0fcc19a9d7a5f07400b85668ad260268_26590_1573871420.mp3', 'reg统治 + ion名词后缀 → 统治区域 → 辖区 → region地区', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2341, 'site', '/saɪt/ ', 'site.mp3', 'n.场所；现场；网站；  v.选址', '3_0_20170930071518_61779_c-gigapixel-scale.jpg', 'd_1_4969_0_2_20150808123241.png', 'Builders are working at the construction site.', '建筑工人们正在工地上干活。', '3_0_20170930071518_41275_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2342, 'skate', '/skeɪt/', 'skate.mp3', 'v.滑冰，溜冰，滑（滑板）；  n.冰鞋', 'a406aee2392bf0bd4bdfbf609cff01b9_78154_1577956461.jpeg', 'd_24_19163_0_3_20150809001006.png', 'The little boy is skating by himself.', '这个小男孩一个人在滑冰。', 'qhzfca9ywq7z5w8ntdn3xhp3fgv4tvy6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2343, 'skip', '/skɪp/', 'skip.mp3', 'v.跳跃，跳过；  v.略过；遗漏；  n.跳跃，蹦跳；跳读；省略', '2b8bb59538d2ea48bef175b3e1f2baf1_115768_1538726368.jpg', 'd_107_4828_0_2_20150809010904.png', 'The girl is exercising with a skipping rope.', '这个小女孩正在练习跳绳。', 'kcz8wm68qhnvsnemcqkccr5sd3xh3x6f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2344, 'stair', '/ster/', 'stair.mp3', 'n. 楼梯', 'f512a3224e877bd98538bd5f2407d3c0_89129_1579315766.jpeg', 'd_16_16507_0_2_20150809002655.png', 'The stairs ascend in a graceful curve.', '这个楼梯呈优美的曲线上升。', '7f03d738d9c60168b66b78c8cc83c87b_32638_1579315763.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2345, 'start', '/stɑːrt/', 'start.mp3', 'v.开办，开动', '50e8403f2e0d260c055c827ed78073fd.jpg', 'd_24_17171_0_4_20150808232234.png', 'The couple has started their own flower shop.', '这对夫妻开了一家花店。', '8328112d4143747a102f45c3f50e4c20.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2346, 'stick to', '/stɪk tu/', 'stick to.mp3', 'phr.坚持，遵守，粘附在…上，紧跟，紧随', '3629aa4d323552344a2403c0b2432219_169943_1559619574.jpeg', '', 'This blogger always sticks to the same format when posting online.', '这个博主一直很坚持自己的发博风格。', '901f5319ae535c71b22b373b817ca652_24810_1559619603.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2347, 'sudden', '/ˈsʌdn/', 'sudden.mp3', 'adj.突然的，忽然的', '3_0_20170701113046_35129_c.jpg', 'd_24_15925_0_4_20150808230837.png', 'The boy was scared by the sudden burst of the balloon.', '气球突然爆了，吓了男孩一跳。', 'd29f755dd0a3944a_1266883006767737676_250207.mp3', 'sud达到 + den去 → 突然到来的事情 → sudden立即，突然', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2348, 'superior', '/suːˈpɪriər/', 'superior.mp3', 'n.上级；  adj.（级别/重要性）更高的', '3_0_20170930071608_91003_c-gigapixel-scale.jpg', 'd_16_6235_0_2_20150808230432.png', 'The people on the left have to listen to their superior.', '左边的人得听从他们的上司。', '9bb436b7772c0f61_1266883375192627792_250207.mp3', 'super在上面 + ior表形容词，较…的 → superior在上面的，超越的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2349, 'sweater', '/ˈswetər/', 'sweater.mp3', 'n.毛衣，厚运动衫，羊毛衫，针织套衫', '87afc7c8d32aaa2c0f3f3948dc0f7c77_85429_1565341903.jpg', '20121225_20_02_41_746.png', 'She likes this red sweater. It can keep her warm.', '她喜欢这件红色毛衣。它能帮她保暖。', 'c00f0425597ca366_1266883008508484240_250207.mp3', 'sweat汗 + er表物 → 穿着会出汗的 → sweater厚运动衫', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2350, 'symptom', '/ˈsɪmptəm/', 'symptom.mp3', 'n.症状；征兆', '3_0_20170714071402_44634_c-gigapixel-scale.jpg', 'd_16_5727_0_2_20150808225748.png', 'Flu symptoms include a headache', '流感的症状包括头痛、嗓子痛和发烧。', 'f9c86629fa28eec99ed1c85ca68711fe_22302_1597400182.mp3', 'sym一起 + ptom落下 → symptom症状', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2351, 'tap', '/tæp/', 'tap.mp3', 'n.水龙头；  v.监听，窃听 (电话)', '772cb8badc9a632f00a474a3597508df_38384_1565281015.jpg', '20140929_02_27_18_773_v3.png', 'Water flows from the tap.', '水从水龙头流出来。', 'dcgcvjcxnkj3axlxzdwfmps3n6aydsrf.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2352, 'torch', '/tɔːrtʃ/', 'torch.mp3', 'n.手电筒；火把，火炬', 'e879a423a71207aee138d0e8bf6e2e70_100385_1579336580.jpeg', 'd_105_6383_0_2_20150809055724.png', 'He is holding up a flaming torch to throw light on the wall.', '他正举着燃烧的火把将墙面照亮。', 'lxqqy6q4py4k65q8vu3cs6gymj653tkw.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2353, 'tour', '/tʊr/', 'tour.mp3', 'v.旅游；做巡回演出；  n.巡游', '3_0_20170928071139_21809_c-manual-scale.jpg', 'd_24_15946_0_3_20150808230929.png', 'The family is planning to tour around the world together.', '这家人正计划一起环游世界。', 'xbqr2tgwcc5qa44bc5m2w37vstm3u65h.mp3', 'tour=turn旋转；迂回 → 转着玩 → tour旅游', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2354, 'transit', '/ˈtrænzɪt/', 'transit.mp3', 'n.运输；  v.运送；通过', '72dc4282e9ea3e639328ebe08f1a4966_93852_1636364978.jpg', '20140917_21_45_21_730_v3.png', 'This truck is used for transit between the two cities.', '这辆卡车用于在这两个城市之间运输货物。', '4a8ca3ba2387c542e9ffe81015c1956b_45728_1595061618.mp3', 'trans越过 + it走 → 越过……走 → transit 运送，通行', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2355, 'whole', '/hoʊl/', 'whole.mp3', 'adj.整个的；  n.整体；  adv.完全，整个', 'a38aa2fea295fbdab35888402a1cfe99_196586_1578563434.jpeg', 'd_24_17608_0_3_20150808233018.png', 'The boy ate the whole watermelon by himself.', '男孩自己吃了一整个西瓜。', 'ju8yj87zzu7j6t2cvblgj9ujvgtmjz5w.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2356, 'abandon', '/əˈbændən/', 'abandon.mp3', 'v.抛弃；放弃；沉湎于（某种情感）', 'c6abc3672d1d58d870c18221c9af5768_178377_1557391527.jpeg', '20141012_23_15_47_238_v3.png', 'He had to abandon his car in the desert.', '他不得不把自己的车子抛弃在沙漠中。', '03ba3d37db9f4ac4_1266883373993405198_250207.mp3', 'ab去 + ban被命令 + don表名词 → 一直被别人命令，放弃自我 → abandon抛弃，放弃 ', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2357, 'ability', '/əˈbɪləti/', 'ability.mp3', 'n.才能，能力', 'c4a8a7e7685f687467f93966e13c102d_57435_1724052351.jpg', 'd_24_10977_0_3_20150808230519.png', 'He has the ability to run on water.', '他可以在水上跑。', '69e567b322e13944_1266883378829220354_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2358, 'about', '/əˈbaʊt/', 'about.mp3', 'adv.附近，大约，转向，左右，周围；  prep.在附近，关于，在……周围，忙于', '4c380f34e6eaea00d452dfcab4bbc07d_145474_1564370535.jpg', 'd_24_19684_0_4_20150809002518.png', 'The lipstick costs about 220 yuan.', '这口红的售价大约是220元。', '3cf189daeccf24d3_1266763522722519602_250117.mp3', 'a在...上面 + bo位于，靠近 + ut在...外面 → 某事物的各个方面 → about附近，周围，有关', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2359, 'absorb', '/əbˈzɔːrb/', 'absorb.mp3', 'v.吸收', '86601bc9b66d68cf4728f4b5c524014c_184461_1532162009.jpeg', '20141011_13_27_30_268_v3.png', 'Plants absorb water from the soil.', '植物从土壤中吸收水分。', '89802a926857328b756046aad532820a_23842_1532162015.mp3', 'ab离开 + sorb吸收 → absorb吸收到', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2360, 'acceptable', '/əkˈseptəbl/ /ækˈsɛptəbəl/', 'acceptable.mp3', 'adj.尚可的，差强人意的 ', '5e229c2f65694906c7689424b252d421_99204_1585365266.jpeg', '', 'The mayor\'s policies have managed to reduce air pollution to acceptable levels.', '市长的政策成功地将空气污染降到了可以接受的程度。', 'us_The_mayors_20240115140520405_de63907e1958ce2b6d48.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2361, 'allow', '/əˈlaʊ/ ', 'allow.mp3', 'v.允许，准许，许可；同意给', 'i_1_9916_0_2_20150808131526-gigapixel-scale.jpg', 'd_24_9916_0_3_20150808230333.png', 'The green light allows you to go.', '绿灯（表示）允许你通行。', 'us_The_green_20240628094337025_bb43116d5c9303faa50a.mp3', 'al=ad去，向 + low表扬 → allow允许', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2362, 'assistance', '/əˈsɪstəns/', 'assistance.mp3', 'n.帮助；援助；补助', '3_0_20170111071106_69870_c-gigapixel-scale.jpg', 'd_16_10985_0_5_20150808235843.png', 'I climbed up the hill with the assistance of my friend.', '在我朋友的帮助下，我爬上了山。', '3_0_20170111071106_44271_c.aac', 'assist帮助 + ance名词后缀 → assistance援助', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2363, 'at no time', '/ət noʊ taɪm/', 'at no time.mp3', 'n.决不', 'c7a41e3d22f2ac4feeb3b05c848dce79.jpg', '', 'At no time should people sacrifice wild animals for their own selfish desires.', '人们绝不能为了私欲而牺牲野生动物。', '2f3980298e581d934ca74e8369e58978.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2364, 'basis', '/ˈbeɪsɪs/', 'basis.mp3', 'n.基础', 'i_1_6628_0_3_20150808125254-gigapixel-scale.jpg', 'd_107_6628_0_2_20150809020600.png', 'The English alphabet is the basis of written English.', '英文字母是书面英语的基础。', 'c4c9f003ce502c88e87c0fc3c2a6884f_24737_1621930967.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2365, 'bay', '/beɪ/', 'bay.mp3', 'n.海湾，港湾', '5335d4479aa782c9769422e2df8c1b05_99277_1565256891.jpg', 'd_105_5719_0_2_20150809055051.png', 'The bay cuts into the land and makes a perfect place to go swimming.', '嵌入陆地的海湾正是绝佳的游泳场所。', '9k7vdyl987sj8nfjq5bwvblmac2ufb6f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2366, 'before long', '/bɪˈfɔːr lɔːŋ/', 'before long.mp3', 'phr.不久以后', 'i_34_19918_0_4_20150809004130.jpg', '', 'It\'s 2012 right now', '现在是2012，不久以后将是2013。', 'sa_34_19918_0_4_20150809004130.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2367, 'beyond question', '/biˈɑnd ˈkwɛstʃən/', 'beyond question.mp3', 'phr.无可争辩，毫无疑问', '5_44_190_20170329110629_79313_c.jpg', '', 'Working through the night', '他在深夜加班，他对工作的投入毫无疑问！', '5_51_411_20170427192211_34123_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2368, 'blow', '/bloʊ/', 'blow.mp3', 'v.吹，吹动，吹气；爆炸；  n.打击，殴打', 'i_9_2714_0_4_160320221500-gigapixel-scale.jpg', 'd_24_2714_0_4_20150808223255.png', 'The kid likes to blow bubbles.', '这个小孩喜欢吹泡泡。', 'f4de7ee4b955349b_1266798138157738870_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
