INSERT INTO `words` VALUES (2370, 'change', '/tʃeɪndʒ/', 'change.mp3', 'n.改变，变化；零钱', '33eb3fb1e8a1a907221542bf1f796399_142119_1732176418.jpg', 'd_24_17165_0_4_20150808232224.png', 'His change in grade is really significant!', '他的成绩变化真的非常显著！', 'us_His_change_20241121160653096_9f369c7d6735036f7ff9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2371, 'charity', '/ˈtʃærəti/', 'charity.mp3', 'n.慈善机构（或组织）；仁慈；施舍', 'ae517288565d03c9e82a5045f253c69f.jpeg', 'd_1_5726_0_3_20150808124305.png', 'The charity aims to help people in need.', '这个慈善机构旨在帮助有需要的人。', 'an6lmakaspms6pgpsyl8dryn75vjbg8z.mp3', 'char爱 + ity表名词 → 对每个人都很爱护 → charity慈善', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2372, 'comply with', '/kəmˈplaɪ wɪð/', 'comply with.mp3', 'phr.遵从', '647d7def96e4f06673eabd40c98e3553_182620_1545127313.jpg', '', 'The dog complies with instructions from the owner.', '这只狗遵从主人的指令。', '431bf2ef66cd8112ddf9e013e990d361_15092_1545127383.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
