INSERT INTO `words` VALUES (2374, 'consulate', '/ˈkɑːnsələt/', 'consulate.mp3', 'n.领事馆；领事职位', '2a187603969b651f29440ae3b1fed1b6_195533_1522721895.jpg', '2018ed8709447fd3a09f03e5f0c5197f_208467_1551250412.png', 'The large brick-red building is a British consulate in Japan.', '这栋高大的砖红色建筑是英国在日本的一座领事馆。', '0363630a23f074a1e53f54a9682a8627_47120_1596785216.mp3', 'consul领事 + ate名词后缀：表地位或职能 → consulate领事馆', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2375, 'contact with', '/ˈkɑnˌtækt wɪð/', 'contact with.mp3', 'phr.与……有交往（联系）', '525d1834d4aaf3ae82d45e28447906b1.jpeg', '', 'We finally got in contact with the rescue team. ', '我们终于和救援队取得了联系。', '6204fc2ec71e33d8b0a0e299615a929c_43808_1593574451.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2376, 'cotton', '/ˈkɑːtn/', 'cotton.mp3', 'n.棉花', 'i_16_18152_0_4_160201114552-gigapixel-scale.jpg', 'd_94_12259_0_4_20150809010016.png', 'Cotton feels soft and can be ideal for clothing.', '棉花摸起来很柔软，可以用来制作衣服。', 'e5ffelp983hjacfj6p6jfs4gwcky3wvz.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2377, 'count', '/kaʊnt/', 'count.mp3', 'v.计算；认为；数数', 'i_1_6939_0_3_20150808125634-gigapixel-scale.jpg', 'd_24_6939_0_4_20150808224835.png', 'I try to count sheep when I want to fall asleep.', '当我想睡觉的时候，我就尝试着数绵羊。', 'ed66b2c05d4a71da_1266883370337262218_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2378, 'describe', '/dɪˈskraɪb/', 'describe.mp3', 'v.描述', '5b74e9a9c9de83cb3db54b7ed79fd71c_171032_1595232037.jpg', 'd_24_4922_0_4_20150808223650.png', 'She described her missing child to a passer-by.', '她向一位路人描述她走失的孩子的模样。', '596d8d5be0db8f9d_1266763312592411232_250117.mp3', 'de表加强 + scribe写 → describe描写', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2379, 'desirable', '/dɪˈzaɪərəbl/', 'desirable.mp3', 'adj.有吸引力的', 'i_1_835_0_4_160318142549-gigapixel-scale.jpg', 'd_107_835_0_2_20150809001259.png', 'The foodie girl finds fried chicken desirable.', '这位“吃货”女生觉得炸鸡很有吸引力。', '8da393072dc814b044b89d7c6ed50d4e_17443_1649402891.mp3', 'desir=desirede渴望 + able能……的 → 值得要的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2380, 'destructive', '/dɪˈstrʌktɪv/', 'destructive.mp3', 'adj.毁灭（性）的，破坏（性）的', 'd7f742efb9ea9435f38ff38ae81c3c1f_202809_1588931694.jpeg', 'd_106_844_0_2_20150809063838.png', 'The destructive winds caused serious damage to the houses.', '这破坏力极强的风严重损坏了房屋。', '027da2e38a4e4809dabe98c0e2656b0e_46452_1588931689.mp3', 'de毁  +struct建立 + ive……的 → destruct毁灭 + ive……的 → 毁灭(性)的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2381, 'effectively', '/ɪˈfektɪvli/', 'effectively.mp3', 'adv.有效地', 'e52ddf4347c1932d7ede920b8433413c_102653_1584956387.jpeg', '', 'The candy stopped the baby from crying very effectively.', '糖果非常有效地让小宝宝停止了哭泣。', 'f3fd44cc4fbd4b6c09ad81a77335b79e_42098_1584956392.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2382, 'everywhere', '/ˈevriwer/', 'everywhere.mp3', 'adv.到处；处处', '3_0_20170608072129_58903_c-gigapixel-scale.jpg', 'd_24_19056_0_3_20150809000140.png', 'The world is so big. I just want to go everywhere.', '世界那么大，我想到处去看看。', '5avgrfr8wlsf5p3rhts6y852s9tdcblb.mp3', 'every每 + where地方 → everywhere处处', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2383, 'fond', '/fɑːnd/', 'fond.mp3', 'adj.喜欢的，喜爱的', 'efb6c08d9a38dfe0e2682dd9d4a82ac1_356253_1701068763.jpg', 'd_24_6745_0_4_20150808224741.png', 'He was fond of his girlfriend', '他很喜欢自己的女朋友，一看见她就笑。', 'us_He_was_20231127150620762_c27c3fcba9e64a7119fc.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
