INSERT INTO `words` VALUES (2385, 'gentle', '/ˈdʒentl/', 'gentle.mp3', 'adj.温柔的，文雅的', 'bbcc225e080051c56491bb47fd31bcf9_82752_1724641802.jpg', 'd_24_3896_0_3_20150808223357.png', 'He was very gentle and gave me his coat.', '他很绅士，把他的外套给我了。', 'jrz6rjg7zdfmy46xhnmgk2n7uvf9ydla.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2386, 'give rise to', '/ɡɪv raɪz tu/', 'give rise to.mp3', 'phr.引起，发生', 'i_12_16839_0_2_20150808184848.jpg', '', 'A combination of elements could give rise to success.', '成功是由多种因素组合促成的。', 'us_A_combination_20250211204420741_8e104e3e321c91efb371.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2387, 'global', '/ˈɡloʊbəl/', 'global.mp3', 'adj.全球的', 'i_1_5701_0_4_20150808124238-gigapixel-scale.jpg', '20141011_04_45_00_718_v3.png', 'With the Internet', '有了互联网，我们可以和全世界的朋友联系。', '99bea32dd2158099c9025c42e26f89ae_21048_1618197787.mp3', 'glob地球 + al……的 → global全球的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2388, 'hold back', '/hoʊld bæk/', 'hold back.mp3', 'phr.阻挡，抑制，控制', 'holdback_4849_20231106_f45d3307.jpg', '', 'I\'m trying to hold back my anger.', '我正尝试抑制我的怒火。', 'sa_11_4849_0_3_20150808154523.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2389, 'immediately', '/ɪˈmiːdiətli/', 'immediately.mp3', 'adv.马上，立即', '7949d7ea42b104b26462e1bcdda3e2d4_84186_1575287305.jpg', 'd_109_4959_0_2_20150809053834.png', 'Yes', '“是，长官。我马上就来！”', '25a2549f3f06baf1_1266883007800716144_250207.mp3', 'immediate立即的 + ly…地 → immediately立即，马上', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2390, 'in a sense', '/ɪn ə sens/', 'in a sense.mp3', 'phr.从某种意义上说', '17606c2e87203935f6c807603c4dcf9b.jpg', '', 'In a sense', '从某种意义上说，互联网把世界缩小了。', 'ead621c0b66de40efafbf98449959578.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2391, 'in detail', '/ɪn dɪˈteɪl/', 'in detail.mp3', 'phr.详细地', '5_44_190_20170329105259_6307_c.jpg', '', 'The speaker is talking in detail about his company.', '演讲者在详细地介绍他的公司。', '5_51_411_20170427192141_7442_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2392, 'inappropriate', '/ˌɪnəˈproʊpriət/', 'inappropriate.mp3', 'adj.不适用的，不适合的', '3653222b23dc78013224143d3cd8f2e0_121976_1534219480.jpeg', '6d5e0f0515855b1fd92badadd7939049_38665_1551251599.png', 'It seems both fish tanks are inappropriate for the fish.', '似乎两个鱼缸对于鱼来说都不合适。', '676bf0d6596c5f730b7c64923ba22f57_42091_1534219475.mp3', 'in不 ＋ ap加强 ＋ propri恰当的 ＋ ate...的 → inappropriate不合宜的，不适当的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2393, 'inform', '/ɪnˈfɔːrm/', 'inform.mp3', 'v.告知，通知', '1b60532dbf9aa961eed7b4b923d19781_104946_1586764641.jpeg', 'd_16_4888_0_2_20150808224529.png', 'She excitedly informed us that she was getting married next week.', '她兴奋地告诉我们她下周就要结婚了。', '98d53f1f38213cc2_1266883380397583184_250207.mp3', 'in进 + form形状 → 进入形式 → inform正式通知', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2394, 'invisible', '/ɪnˈvɪzəbl/ ', 'invisible.mp3', 'adj.隐身的，隐形的', '99e94cd05e39a132a0907168f5abf838_147110_1538640430.jpg', 'd_11_1655_0_4_20150808144641.png', 'In the movie', '在电影里，他拥有隐身的能力。', 'us_In_the_20240619152854000_1a0e00ac4345ccfff217.mp3', 'in不 + vis看 + ible形容词后缀 → 看不见的，无形的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2395, 'league', '/liːɡ/', 'league.mp3', 'n.社团；联盟；  v.使……结盟，与……联合', 'i_1_1713_0_4_20150808121736-manual-scale.jpg', 'd_24_1713_0_4_20150808223153.png', 'You are so good! You should join our soccer league!', '你很厉害！你应该加入我们的足球社团！', 'sa_1_1713_0_4_20150808121736.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2396, 'nod', '/nɑːd/', 'nod.mp3', 'v.点头', '3ce8b11b511c0b8ad1226518323e4d78_114590_1709190002.JPG', '20121225_20_40_41_872.png', 'To nod in agreement', '点头同意时，要稍微前倾头部。', '283e2431a4a2a5eb_1266883328336222972_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2397, 'on purpose', '/ɒn', 'on purpose.mp3', 'phr.故意', '705808497e5ee9c4b2905f6670dda0a0_149555_1737954695.jpg', '', 'The football player committed the foul on purpose to prevent the goal from being scored.', '这个球员故意犯规防止对方进球得分。', '293da904dab36885_1266883479170624408_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2398, 'overcome', '/ˌoʊvərˈkʌm/', 'overcome.mp3', 'v.克服；战胜', 'd433fb556ca84c4a2a7ab1107a828ec0_74021_1578561151.jpeg', 'd_21_3988_0_2_20150808190650.png', 'The passenger overcame his fear of taking a flight.', '这位乘客克服了他坐飞机的恐惧。', '089a13c155b0b5e35f20426e833d0783_18854_1624072894.mp3', 'over在上 + come来 → 来到上面 → overcome战胜，克服', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2399, 'painter', '/ˈpeɪntər/', 'painter.mp3', 'n.画家', '4d265a642a29eaccd84e8989c0578322_166864_1595472309.jpeg', 'd_109_6706_0_2_20150809054741.png', 'The painter is painting a picture.', '画家正在画画。', 'hp6k2x8lulngu5vbyewu93ppx7rxjdwv.mp3', 'paint画画 + er表人 → 漆工，画家，绘画者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2400, 'politics', '/ˈpɑːlətɪks/', 'politics.mp3', 'n.政治，政治事务；政纲', '3289f69ed5528c6b8003469227c0e75a_164619_1564825485.jpg', 'a5fbb6f60797542e8803008db3923347_28926_1539341311.png', 'He is so keen on politics that he participates in many public events.', '他是如此热衷于政治，因此他参加了很多公众活动。', 'a135c232a5bf7e3b93ab8b54630f1f8f_46100_1564825473.mp3', 'polit城市，公民 + ics与...有关的 → politics政治', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2401, 'preserve', '/prɪˈzɜːrv/ ', 'preserve.mp3', 'v.贮存，保鲜；保存；保护', 'i_1_2776_0_3_20150808121925-gigapixel-scale.jpg', 'd_16_2776_0_2_20150808223652.png', 'You can preserve food by putting it into the refrigerator.', '你可以把食物放进冰箱保鲜。', 'sa_1_2776_0_3_20150808121925.aac', 'pre预先 + serve保持 → 预先保留 → preserve保存', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2402, 'professor', '/prəˈfesər/ ', 'professor.mp3', 'n.教授', '3ef37c490ff3db6da4c3e2d101d15eb4_94603_1565165059.jpg', 'd_24_7924_0_4_20150808225238.png', 'The man standing in front of the whiteboard is a professor.', '站在白板前的男人是一位教授。', '36b95e4038a892c1bb0b1acae8fd57b8_45306_1565165054.mp3', 'pro在前面 ＋ fess说 ＋ or人 → 在前面说话的人 → professor教授', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2403, 'program', '/ˈproʊɡræm/ ', 'program.mp3', 'n.程序；  v.编写程序', 'i_1_11506_0_4_150923093344-gigapixel-scale.jpg', '', 'Leave me alone! I’m trying to write a program on the computer.', '别理我！我正尝试在电脑上写代码。', 'rv88bkhprvhqfe63jzqshczrccxglr26.mp3', 'pro在前 + gram写，图 → 在前面写好 → program计划；提纲', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2404, 'provision', '/prəˈvɪʒn/', 'provision.mp3', 'n.必需品；（法律等的）条款', '3_0_20160718113745_54902_c-gigapixel-scale.jpg', 'd_107_3868_0_2_20150809003235.png', 'We set out with enough provisions to last the trip.', '我们带上足够维持整场旅行的必需品后就出发了。', '3_0_20160718113745_10188_c.aac', 'pro提前 + vis看 + ion名词后缀 → provision预备', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2405, 'recommendation', '/ˌrekəmenˈdeɪʃn/', 'recommendation.mp3', 'n.推荐，介绍', 'df0d5c00d2368bed402451b12eed6596_108758_1584612445.jpeg', 'd_1_3979_0_2_20150808122200.png', 'He accepted the waiter\'s recommendation and ordered dumplings.', '他接受了服务员的建议，点了饺子。', '513a3dfc568e1cc8923fc5db23b92bf0_43688_1584612442.mp3', 'recommend推荐 + ation表名词 → recommendation推荐', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2406, 'reduce', '/rɪˈduːs/', 'reduce.mp3', 'v.减少，减小，降低', '0dabe69d793a21c7d01f3fed443cf84d_106318_1621911671.jpg', 'd_24_4988_0_4_20150808223759.png', 'The price of this phone is reduced to ¥998 in the sale.', '这款手机的价格在促销中降至998元。', 'fc187df2f872735a_1266883330010426140_250207.mp3', 're向后 + duc引导 → 向后引导 → reduce减少；缩小；降低', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2407, 'relieve', '/rɪˈliːv/', 'relieve.mp3', 'v.减轻', '9323453d0b5d25b3fe9081bf0151c634_138885_1538665078.jpg', 'd_1_6284_0_2_20150808124941.png', 'A nice massage will relieve your back pain.', '舒服的按摩可以缓解你背部的疼痛。', '38efc71186f4ed21_1266883615347682214_250207.mp3', 're再 + lieve提高，变轻 → 再轻 → relieve减轻', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2408, 'remark on', '/rɪˈmɑːrk ɑːn/', 'remark on.mp3', 'phr.谈论', 'cb973771c969f5ee7df4990c9be51f9f.jpeg', '', 'His friends are remarking on his change in appearance. ', '他的朋友们在谈论他外表的变化。', '7dcc09d1ecf8298d15688321033a5227_45166_1599622959.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2409, 'responsibility', '/rɪˌspɑːnsəˈbɪləti/ ', 'responsibility.mp3', 'n.责任，义务', '77b15231044679b36722d07b4f7215e1_70057_1617356911.jpg', 'd_16_6968_0_2_20150808231332.png', 'We have a responsibility to take care of our parents.', '我们有责任照顾父母。', 'sa_1_6968_0_2_20150808125701.aac', 're再、重复 ＋ spons承诺 ＋ ibility抽象名词词尾 → responsibility责任，责任心；职责，义务', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2410, 'risk', '/rɪsk/', 'risk.mp3', 'v.冒……的危险；  n.风险', 'ba2833b1249731cf8a4788ef11e4af6d_87723_1577955874.jpeg', '20140929_20_10_25_208_v3.png', 'The fireman risks his life by rushing into the fire.', '消防员冒着生命危险冲进火场。', '76516cab67d36db8_1266883482841099008_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
