INSERT INTO `words` VALUES (2412, 'skirt', '/skɜːrt/', 'skirt.mp3', 'n.裙子；  v.装边于', 'bada26c2c6bfb4512f0ba93b62c19937_83592_1522662853.jpg', '20121225_18_46_31_669.png', 'Her red skirt matches well with her red sunglasses.', '她的红色裙子和红色太阳镜很搭。', '282778f1e262521f_1268213310843732636_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2413, 'slow', '/sloʊ/', 'slow.mp3', 'adj.缓慢的；  v.（使）慢下来，（使）减速；  adv.缓慢地', 'fadbc4ca0c1f83e14b55ea78c34e3656_81739_1701138894.jpg', 'd_24_17619_0_4_20150808233038.png', 'The video loading speed is very slow.', '视频加载速度很慢。', 'e0e1b7a68e0c28e4_1266763313442630532_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2414, 'sophisticated', '/səˈfɪstɪkeɪtɪd/', 'sophisticated.mp3', 'adj.精密的；老练的；高雅时髦的，很有品位的', 'a92902b9e1e54bf168f6402fa84fbc98_102152_1564370462.jpg', '20141011_04_40_14_427_v3.png', 'This machine is quite sophisticated.', '这台机器是非常精密的。', 'zt62uajsktkuxm4fm8nggskkgba9jg9a.mp3', 'soph智慧 + istic……的 + at＝ate做，造成 + ed……的 → 有智慧的 → sophisticated老于世故的，精致复杂的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
