INSERT INTO `words` VALUES (2416, 'surroundings', '/səˈraʊndɪŋz/', 'surroundings.mp3', 'pl.周围的事物', 'febb40085699d8ec5b8ead0d38aab211_122770_1565252228.jpg', 'd_105_6691_0_2_20150809055929.png', 'The village\'s surroundings are mostly forests and green lands.', '村庄的周围主要是森林和绿地。', 'sa_1_6691_0_2_20150808125350.aac', 'sur随后 + round圆圈 + ings表名词 → surroundings周围的事物，环境', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2417, 'swallow', '/ˈswɑ:ləʊ/ ', 'swallow.mp3', 'v.吞下；  n.一次吞咽的量', '9210d103cd46ebd529f8ac8cb4f8b17f_195124_1588086711.jpeg', 'd_13_7281_0_2_20150808193604.png', 'She always lifts her head when swallowing pills.', '她总是会在吞药片的时候抬起头。', 'f03ae942840bceda85619590e2620f4d_49942_1588086715.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
