INSERT INTO `words` VALUES (2420, 'trend', '/trend/', 'trend.mp3', 'n.时尚；趋势；趋向，动向；  v.倾向；走向；转向；使趋向', 'd14b4861029f315cc907d30fe9312100_83275_1565342751.jpg', 'd_107_5778_0_2_20150809013854.png', 'The new trend is for girls to wear very colorful clothing.', '女孩儿们现在流行穿多彩的服饰。', 'sa_1_5778_0_2_20150808124402.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2421, 'tune', '/tuːn/', 'tune.mp3', 'n.曲调，旋律，曲子；调音', 'i_38_7274_0_3_20150809013410-gigapixel-scale.jpg', 'd_16_7274_0_2_20150808231733.png', 'Sure', '当然，我会为你弹奏一曲。', 'nb82rnq3exe9kctmg6ztmzh4ksgdjvgr.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
