INSERT INTO `words` VALUES (2424, 'violence', '/ˈvaɪələns/', 'violence.mp3', 'n.暴力，暴行', 'i_1_6635_0_6_150919175927-gigapixel-scale.jpg', 'd_16_6635_0_2_20150808230848.png', 'The youngsters shouldn\'t settle the problem by using violence.', '年轻人不该用暴力解决问题。', '2eec0a434e5650e3598653fb7cb19bab_21832_1558667831.mp3', 'viol力量 + ence表名词  → 暴力，暴行', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2425, 'virus', '/ˈvaɪrəs/', 'virus.mp3', 'n.病毒；病毒性疾病', 'a8689b98af252c97de6f73a2a88bd67e_173297_1527747198.jpg', 'd_109_5964_0_2_20150809054439.png', 'This virus is really dangerous.', '这种病毒真的很危险。', 'ch6kyftltq8zqelya3kb2dtpahsmh8bp.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2426, 'withdraw', '/wɪðˈdrɔː/', 'withdraw.mp3', 'v.取款；撤退', '79c8b019113440bfd714540658e16c3f_48880_1566808974.jpg', '20141011_13_56_18_577_v3.png', 'I\'d like to withdraw 500 dollars from the machine.', '我想从这台机器里取500美元。', 'sa_1_5844_0_4_20150808124513.aac', 'with向后，相反 + draw拉 → 向相反拉 → withdraw撤消，撤退', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2427, 'approach', '/əˈproʊtʃ/', 'approach.mp3', 'v.靠近；接近；  n.接近；途径；方法', 'i_1_3848_0_6_151222155933-gigapixel-scale.jpg', '20141011_00_59_31_945_v3.png', 'The ship is approaching the shore at a high speed.', '这艘船正以很快的速度靠近岸边。', 'sa_4_3848_0_5_151225144630.aac', 'ap一再 + proach接近 → approach接近', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2428, 'bare', '/ber/ ', 'bare.mp3', 'adj.赤裸的；  v.使裸露，暴露', 'bare_5824_20231106_87dcb881.jpg', 'd_16_5824_0_2_20150808225919.png', 'He is running around in bare feet.', '他正赤着脚到处跑。', '3_0_20170930071451_40859_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2429, 'base', '/beɪs/', 'base.mp3', 'n.根基；底座；  adj.卑鄙的', 'i_1_4909_0_3_20150808123137-gigapixel-scale.jpg', 'd_1_4909_0_6_151019181100.jpg', 'A firm base is very important for building a house.', '稳固的根基对于建造房屋十分重要。', 'sa_1_4909_0_3_20150808123137.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2430, 'become', '/bɪˈkʌm/', 'become.mp3', 'v.变成', '20c9c91875fe4adc58e4bcbe9ad60ad8_59997_1702632162.jpg', 'd_24_17085_0_3_20150808231954.png', 'The bud became a beautiful rose.', '花蕾变成了美丽的玫瑰。', '6c04dfad105510f2_1266763526411889576_250117.mp3', 'be成为，变得 + come到达，出现 → become变成', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2431, 'bottom', '/ˈbɑːtəm/', 'bottom.mp3', 'n.水底；底部；尽头；末端；臀部；  adj.底部的', '20120508_03_34_22_462-gigapixel-scale.jpg', 'd_24_5557_0_3_20150808224138.png', 'Have you ever seen the bottom of the ocean?', '你见过海底吗？', 'uelkjcwkszeu9w3ttdhb2fejed688rdv.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2432, 'break through', '/breɪk', 'break through.mp3', 'phr.突破', '73536f019ad1a3f3131cad0301f25c27_135076.jpg', '', 'The man\'s punch managed to break through the wall.', '这个男人的拳头成功打破了这面墙。', 'b389ee7e7e20c62cbc9b1ec201d75a53_31675.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2433, 'burn out', '/bɜːrn aʊt/', 'burn out.mp3', 'phr.（火）燃尽，烧完自灭', 'i_906_-906_0_1_160225151916.jpg', '', 'The fire burnt out before reaching the end of the match.', '火还没烧到火柴的底部就燃尽了。', 'sa_906_-906_0_1_160229151441.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2434, 'care', '/ker/', 'care.mp3', 'n.照顾，照料', 'i_24_16450_0_5_151220020702-gigapixel-scale.jpg', 'd_74_12023_0_4_20150809024817.png', 'The nurse is taking care of the old man.', '这名护士正在照顾老人。', 'us_The_nurse_20240422170257129_b159b128d964ff368fc8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2435, 'cast', '/kæst/', 'cast.mp3', 'v.投，掷；投射（光）；投票；选定演员；  n.投掷物；铸件；演员表', 'af37b0855b62c04c6638cb825977ef03_128952_1538648889.jpg', 'd_16_5607_0_5_20150808225544.png', 'He\'s going to cast that rock at the seaside.', '他准备在海边把石块投掷出去。', 'us_Hes_going_20241009155139960_0cf863ab666497506481.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2436, 'characteristic', '/ˌkærəktəˈrɪstɪk/', 'characteristic.mp3', 'n.特点，特征，特色；特征；特色；  adj.典型的；特有的；独特的', '374b5592a3cf9201d0a70e836d6a034b_64628_1657590686.jpg', '', 'The main characteristic of an elephant is its long trunk.', '大象最大的一个特点就是长鼻子。', '3_0_20161224070810_36947_c.aac', 'character特点 + istic名词后缀 → characteristic特征，特色', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2437, 'choose', '/tʃuːz/', 'choose.mp3', 'v.选择，挑选', '20120720_03_38_53_199-gigapixel-scale.jpg', 'd_66_8384_0_3_20150809021235.png', 'You should choose healthy food if you don\'t want to get fat.', '如果你不想长胖，你就应该选择健康的食物。', '2646f6f58727140c_1266883006949841490_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2438, 'come up', '/kʌm ʌp/', 'come up.mp3', 'phr.升起；发芽', '1b5b372734f6b7562d41712787a48412_168614_1588910285.jpg', '', 'The sun comes up from the sea.', '太阳从海面上升起。', 'a5319a27a7d45be821fbf32e53ff1e80_36688_1583835006.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2439, 'come up to', '/kʌm ʌp tu/', 'come up to.mp3', 'phr.朝…走过来', 'i_906_-906_0_1_160302144326.jpg', '', 'The baby girl is coming up to her father.', '小女孩正在朝着他的父亲走来。', 'sa_906_-906_0_1_160302144226.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2440, 'commission', '/kəˈmɪʃn/', 'commission.mp3', 'n.委员会；佣金；任务；权限；委任；  v.委任', '5dd3535ca1d11a07dd599492e6e511dc_53399_1720070393.jpg', 'd_1_4958_0_2_20150808123228.png', 'The State Health Care Commission meets once every month to make policy.', '州立卫生保健委员会每个月都会碰一次头来制定政策。', '1def38764d1d42a5113a575010b48877_24653_1619322284.mp3', 'com共同 + miss送 + ion名词后缀 → 共同选出的人 → commission委员会', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2441, 'company', '/ˈkʌmpəni/ ', 'company.mp3', 'n.陪伴；公司；  v.陪伴', '63c4b153ee4166ab8b96b6147f4f0fcd.jpeg', '20130105_10_25_14_930.png', 'The girl enjoys her father\'s company.', '这个女孩喜欢父亲的陪伴。', 'a912bb444b9c375ca1472173a543be57_28112_1599552055.mp3', 'com一起 + pany面包 → 一起吃面包 → company陪伴', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2442, 'conserve', '/kənˈsɜːrv/', 'conserve.mp3', 'v.保护，保存', 'e64c1ca6c7ebca8b33bfe1bddba3d155_196309_1569031136.jpeg', '20140723_23_04_09_190_v3.png', 'Let\'s conserve wildlife in the area.', '让我们一起保护这个地区的野生动物。', '3kbttl5wux9qf2elxjxzhaheyadwa7ju.mp3', 'con全部 + serve服务，保持 → 全部保持下来 → 保存', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2443, 'consul', '/ˈkɑːnsl/', 'consul.mp3', 'n.领事', '256485f01e2a5352e0fa0393ba0f1380_61986_1561953139.jpg', '', 'As the Zebra consul', '作为斑马国的领事，他是斑马国在鹿国的代表。', 'c088e6acf64fd1aa8b64fc1d47107871_43754_1561953138.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2444, 'cut', '/kʌt/', 'cut.mp3', 'v.切', 'bd87677f0781e071980150bfd7d73708_90035_1565251201.jpg', 'd_13_19080_0_2_20150808205644.png', 'I like the way he cuts my hair.', '我喜欢他给我剪的头发。', 'qg6wkeujfluahpkn575uvezws65ydg5l.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2445, 'define', '/dɪˈfaɪn/', 'define.mp3', 'v.给（词、短语等）下定义；界定，解释', '466e8cfcd11cb82fae182578a84502a1_118695_1695619262.jpg', 'd_1_7883_0_2_20150808130114.png', 'Many believe achieving success defines the American Dream.', '许多人认为“取得成功”能定义美国梦。', 'zekhkw4bl3mrryel7e98w5lke3742xkt.mp3', 'de加强语意 + fine边界 → define下定义', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2446, 'doubt about', '/daʊt əˈbaʊt/', 'doubt about.mp3', 'phr.怀疑', 'e3708f6a5e5d9d03513b22ab6dcdbd9c.jpeg', '', 'He has some doubts about whether the new employee is the right person for the job.', '他有些怀疑这名新员工是否适合这份工作。', '42d21d6053f9966627b2133e497e4a6e_27474_1619171169.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2447, 'eager for', '/ˈiːɡər fɔːr/', 'eager for.mp3', 'phr.渴望，热切希望', '0a24b479a36b0320c78809c214883ace.jpeg', '', 'Fans were already crowding outside', '粉丝们早已挤在外面，迫不及待想看演出。', 'b6039b404b3fc1bc5fec5118643412dc.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2448, 'excessive', '/ɪkˈsesɪv/', 'excessive.mp3', 'adj.过多的', '3_52_20170505105910_31483_c-gigapixel-scale.jpg', '20121225_18_38_38_871.png', 'Excessive food intake made the cat overweight.', '贪食使得这只猫超重了。', '3_0_20160624145459_11790_c.aac', 'ex出，出去 + cess行走 + ive形容词后缀 → excessive过度的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2449, 'exercise', '/ˈeksərsaɪz/', 'exercise.mp3', 'n.操练，运动；活动；锻炼；  v.锻炼', '933_20120514_04_09_08_561-manual-scale.jpg', 'd_24_7107_0_5_20150808224932.png', 'Exercise is the key to keeping healthy.', '锻炼是保持健康的关键。', 'aad218114181e45f_1266763522284673574_250117.mp3', 'ex出 + erc力量 + ise表名词，物品，状态 → exercise练习，锻炼', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2450, 'familiar to', '/fəˈmɪljɚ tu/', 'familiar to.mp3', 'phr.......被某人熟悉', 'f6a1e245a82ea9fc6f7d8191c119bd96.jpeg', '', 'The works of Confucius are familiar to people all over the world.', '孔子的著作为全世界人民所熟悉。', '03309dd420e957120d78121d3d56113e_47758_1599466099.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2451, 'fiction', '/ˈfɪkʃn/', 'fiction.mp3', 'n.小说；虚构', '9c3b3ca825edabb208c3f891f6918309_179945_1573702068.jpeg', 'd_107_5858_0_2_20150809014307.png', 'This is a work of fiction about wizards and dragons.', '这是一本关于巫师和龙的小说。', 'us_This_is_20240815152933853_6ad1f2f8eb38ab07ccd0.mp3', 'fict塑造，虚构 + ion名词后缀 → 虚构的故事 → fiction小说', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2452, 'fine', '/ˈfaɪn/', 'fine.mp3', 'v.罚款；  n.罚款；  adv.可接受，够好；  adj.优质的', '964425e784180bf195004246c06de26b_101698_1587794615.jpeg', 'd_24_18924_0_4_20150808235953.png', 'The policeman fined the driver for driving too fast.', '警察因那个司机超速而对他处以罚款。', 'sa_24_18924_0_7_151224133048.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2453, 'freedom', '/ˈfriːdəm/', 'freedom.mp3', 'n.自由；自主', 'i_1_5579_0_7_150923100940-gigapixel-scale.jpg', 'd_24_5579_0_4_20150808224204.png', 'The birds finally get their freedom. They are flying out of the cage.', '鸟儿们终于自由了。它们正从笼子里飞出来。', 'd4a9bab155f73130_1266883008591780498_250207.mp3', 'free自由的 + dom状态或领域 → freedom自由', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2454, 'genuine', '/ˈdʒenjuɪn/', 'genuine.mp3', 'adj.真的；真正的；真诚的', '8aa15ebd8305416110a76866a1300f3b_182793_1740031675.jpg', 'd_1_10542_0_2_20150808131657.png', 'Which one is the genuine painting of the famous artist?', '哪一幅才是这位著名画家的真迹？', 'sa_4_10542_0_4_160111162002.aac', 'genu导致，产生 + ine形容词后缀 → 确实产生出的东西 → genuine真的，真正的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2455, 'ghost', '/ɡoʊst/', 'ghost.mp3', 'n.鬼，鬼魂，幽灵', '043567fae3b9e7858ca7d6bdd2dde9dc_28751_1565252344.jpg', 'd_1_8926_0_3_20150808131012.png', 'There are ghosts in movies and stories', '电影和故事里有鬼魂，但我认为它们（在现实生活中）不是真的。', 'sa_1_8926_0_3_20150808131012.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2456, 'globe', '/ɡloʊb/', 'globe.mp3', 'n.地球，世界；球体，地球仪', 'i_1_6803_0_3_20150808125512-gigapixel-scale.jpg', 'd_16_6803_0_2_20150808231058.png', 'Airplanes fly all over the globe', '飞机在全世界飞行，甚至会飞过两极上空。', 'sa_1_6803_0_3_20150808125512.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2457, 'grave', '/greɪv/', 'grave.mp3', 'adj.严肃的，庄重的；  n.墓', '2fe2203aef04219d99f0a74208f2c23e_126919_1587089726.jpeg', 'd_1_5848_0_2_20150808124516.png', 'The warriors\' expressions were grave as they noticed the enemy coming.', '战士们注意到敌人来了，表情严肃。', '91d6d018496c171792cefd1cdb51b19f_47028_1587089723.mp3', 'grav重 + e → grave严重的；庄重的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2458, 'guard against', '/ɡɑrd əˈɡɛnst/', 'guard against.mp3', 'phr.防止', 'a6a00ead64e4ff80ac4146d85a6e03b9.jpg', '', 'He carried his bag on his front to guard against pickpockets.', '他把包背在身前以防扒手。', '3e4a9665c843208217e6576203278b59.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2459, 'hold', '/hoʊld/', 'hold.mp3', 'v.拿住，握着；  n.（飞机、船的）货舱', '0b41ebd799a1a0475c8348c28b514127_63107_1738828610.jpg', 'd_69_12994_0_4_20150809003357.png', 'To hold someone\'s hand is a sign of love.', '握住一个人的手是爱的表现。', '44280dc053dabe7c_1266883327169682150_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2460, 'in favor of', '/ɪn ˈfeɪvər əv/', 'in favor of.mp3', 'phr.支持', 'i_905_-905_0_1_160202143110.jpg', '', 'The girl is in favor of taking exams with honesty.', '这个小女孩支持诚信考试。', 'sa_905_-905_0_1_160203152654.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2461, 'inference', '/ˈɪnfərəns/', 'inference.mp3', 'n.推断', 'i_1_9519_0_4_20150808131426-gigapixel-scale.jpg', 'd_103_9519_0_3_20150809033406.png', 'The boy made an inference about love.', '那个男孩推断了一下爱情。', 'sa_1_9519_0_4_20150808131426.aac', 'in在...内 + fer携带 + ence名词后缀 -> inference推断', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2462, 'interference', '/ˌɪntərˈfɪrəns/', 'interference.mp3', 'n.干涉，干预；介入；（电波的）干扰', 'acf17b138738e6d74e053e9088a1fac9_56757_1748339488.jpg', '', 'Interference refers to unnecessary interruption.', '干涉指的是不必要的打扰。', 'us_Interference_refers_20241120134100876_0e699ce0ca80478bda13.mp3', 'interfere干涉 + ence表名词 → interference干涉', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2463, 'invitation to', '/ˌɪnvɪˈteɪʃn tuː/', 'invitation to.mp3', 'phr.……的邀请', '20775a94a11c4cd1cc9df2b5651cf697.jpg', '', 'I got an invitation to my friend\'s wedding.', '我收到了朋友的婚礼邀请。', 'd693635f950e2a2929f98287f4a4d2ca_39200_1593586527.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2464, 'junior', '/ˈdʒuːniər/', 'junior.mp3', 'n.（中学或大学的）三年级学生；  adj.（年级、地位、职位等）低的', '017949da387573a4f29da645617a0414_164446_1699510068.jpg', 'd_24_4802_0_3_20150808223556.png', 'They are excellent junior students.', '他们是一群优秀的大学三年级学生。', 'us_They_are_20241009151840539_0396f1b63ee2e3e0362a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2465, 'legal', '/ˈliːɡl/', 'legal.mp3', 'adj.合法的，法定的，法律的', '7b73e63071c24f0240944a900aa5d3b1_87143_1522664876.jpg', 'd_24_3858_0_3_20150808223345.png', 'Now I have my driver\'s license; it\'s legal for me to drive on the road.', '我现在有驾照了，可以合法上路了。', '7d3e2c2b467934bd69261797b722a0f0_44178_1522664870.mp3', 'leg法律 + al形容词后缀 → legal法律的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2466, 'lift', '/lɪft/', 'lift.mp3', 'v.（使）升起，举起；  n.免费搭车', 'a7dc0aeb666a71ed7072fb8f5102795f_195765_1721371571.jpg', 'd_24_16491_0_5_20150808231425.png', 'They lifted the Euro 2024 trophy in Berlin.', '他们在柏林捧起了 2024 年欧洲杯的冠军奖杯。', 'xrlnmq6r4239q9hw8m8ult6kb9tgxvz4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2467, 'live through', '/lɪv θru/', 'live through.mp3', 'phr.度过', 'cdb10bd7af5d44fee1a37b6f17211f36_114309_1584087848.jpeg', '', 'The old woman lived through the war where she lost her husband.', '那位老妇人度过了这场战争，也在战争中失去了丈夫。', 'us_The_old_20221220182907279_39d3a79a751ec0af841f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2468, 'November', '/noʊˈvembər/', 'November.mp3', 'n.十一月', 'i_16_15933_0_4_160304110617-gigapixel-scale.jpg', 'd_24_15933_0_4_20150808230853.png', 'November is the eleventh month of the year.', '十一月是一年的第十一个月。', '980d9c56e66d03e4_1266763449895398146_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2469, 'now and then', '/naʊ ənd ðen/', 'now and then.mp3', 'phr.时而', '81f5892f15b775551eb608eb312cfd44.jpeg', '', 'Her grandfather still plays tennis now and then.', '她的祖父仍然时不时地去打网球。', '9e148f71ead6d8df55ee502704b516f7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2470, 'on occasion', '/ɑːn əˈkeɪʒən/', 'on occasion.mp3', 'phr.偶尔', '26aad73a305bbb98fc53f71003deb140.jpeg', '', 'She not only does Japanese translation but also', '她不仅做日语翻译，偶尔也做些韩语翻译。', '005a040e6277f6386e227216e957c04f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2471, 'on sale', '/ɑːn seɪl/', 'on sale.mp3', 'phr.在打折，廉价出售；待售的；拍卖的', '5508dc889a9f171131c2ea5e8fc0e931_97103_1604577309.jpg', '', 'All the shoes are on sale today.', '今天所有的鞋子都在打折。', '70db155969a601bd_1266883198295583538_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2472, 'once and for all', '/wʌns ənd fɔr ɔl/', 'once and for all.mp3', 'phr.一次性地', '3c77d8e54b24c24ee8022c3c0fb6954c.jpeg', '', 'He finally finished painting the wall once and for all.', '他最终还是一次性刷完了这面墙。', 'f756543005cbe63ac055882cdaecde27.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2473, 'outlet', '/ˈaʊtlet/', 'outlet.mp3', 'n.出口；表现机会，发泄方法', '61aaf87662ec8bb61ba553cfd0110783_912923_1747113321.jpg', 'd_107_14978_0_2_20150809025553.png', 'Water came out of the wall through several outlets.', '水从墙上的几个出口中排了出来。', 'sa_1_14978_0_2_20150808131924.aac', 'out外、出 + let名词后缀 → outlet出口；排出', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2474, 'overlook', '/ˌoʊvərˈlʊk/', 'overlook.mp3', 'v.忽视，未注意到；眺望，俯视', 'fb18556d311484dcb005be06f8f2bd8e_84253_1732243045.jpg', 'd_107_6418_0_2_20150809020034.png', 'He\'s so busy on his computer that he\'s totally overlooked his son.', '他忙着看电脑，全然忽视了他的儿子。', 'us_Hes_so_20241122103734368_f49ee667d67ffb8d485c.mp3', 'over在上，在外 + look看 → 在上面看 → 俯视；疏忽', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2475, 'parliament', '/ˈpɑrləmənt/', 'parliament.mp3', 'n.国会；议会', '212ad26bf5edf17682a8b3a4bda9e321_199956_1538474086.jpeg', 'd_106_4726_0_2_20150809070822.png', 'These are the Houses of Parliament in London.', '这是伦敦的议会大厦。', 'ebcf028e616c438411c236227e69e1d4_32858_1571023394.mp3', 'parlia=parley会谈 + ment表名词 → 议员们谈论政府的地方 → 议会，国会', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2476, 'participate in', '/pɑːrˈtɪsɪpeɪt ɪn/', 'participate in.mp3', 'phr.参与，参加', '5_48_34_20161111174224_30678_c.jpg', '', 'All participants are willing to participate in the meeting discussion.', '所有与会者都积极参与会议讨论。', '5_51_78_20161122111037_73168_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2477, 'percent', '/pərˈsent/', 'percent.mp3', 'n.百分比，比例，部分', '096aafc80182f4e018fd2dfe5270826b_178347_1525751008.jpeg', 'd_109_17161_0_2_20150809061800.png', 'The green part takes up 70 percent of the pie chart.', '绿色部分占据了饼状图的70%。', '596b91bd85264e3376835af69b34981e_35423_1525750990.mp3', 'per每一 + cent一百 → percent百分比', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2478, 'picnic', '/ˈpɪknɪk/', 'picnic.mp3', 'n.野餐', 'f204dbad37835fa7d7b4965ba901ecad_200949_1524109904.jpg', '20121227_14_00_45_760.png', 'The family enjoyed a nice picnic outside.', '这一家人在室外享用了一顿很好的野餐。', '3581e1bf1018d174_1266883369590369136_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2479, 'pop', '/pɑp/', 'pop.mp3', 'v.发出（砰的响声）；  n.砰的一声爆破声；  adj.流行的，大众的', '20120817_03_50_20_178-gigapixel-scale.jpg', '20141013_23_38_03_757_v3.png', 'Let\'s pop open the champagne!', '让我们砰的一声开启这瓶香槟吧！', 'sa_1_2732_0_4_20150808121918.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2480, 'present', '/ˈprezənt/', 'present.mp3', 'n. 礼物（读作/ˈprezənt/）；  v.颁发，授予（/prɪˈzent/）；  adj.出席的/ˈprezənt/', '3e6aa072b79f7b4d7c9f2dadf650e399_91951_1573717224.jpeg', 'd_24_17369_0_3_20150808232747.png', 'The girl gave me a carefully wrapped present.', '女孩给了我一份精心包装好的礼物。', '93baafb4e7f059b0_1266763400467819496_250117.mp3', 'pres前 + ent名词后缀 → present礼物，赠送物', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2481, 'press', '/pres/', 'press.mp3', 'v.按，压；  n.新闻界', '20120507_04_51_58_926-gigapixel-scale.jpg', '20121225_19_22_25_281.png', 'Press the button on the phone to make a call.', '按电话上的按键来打电话。', '5aceda9e5b69fff9_1266883524948437810_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2482, 'queen', '/kwiːn/', 'queen.mp3', 'n.王后，女王；出众的女人；皇后', 'eed2bdbee7b5e30218e278ad0adea03c_138736_1561953084.jpg', '', 'The queen in a long red dress stands beside the king.', '王后身着一袭红裙，站在国王身旁。', 'fa9569990afae711_1266741633608800930_250113.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2483, 'regard for', '/rɪˈɡɑːrd fɔːr/', 'regard for.mp3', 'phr.对……的尊重', 'ff186eab10e216bd7f99817b72b6f677_90306_1707023970.jpg', '', 'I have high regard for my teacher.', '我非常尊重我的老师。', 'us_I_have_20240204131808823_02bcc3b0e138996339ff.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2484, 'remind sb. of sth.', '/rɪˈmaɪnd ˈsʌmbədi əv ˈsʌmθɪŋ/', 'remind sb. of sth..mp3', 'phr.提醒某人某件事', 'c79dcda6d86a28cafc6bc6b91ae0ba2b.jpg', '', 'The snow globe reminded her of Christmas!', '这个雪球使她想起了圣诞节！', 'b0cb708d0f9c53241d6b0f6d11b341d9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2485, 'rough', '/rʌf/', 'rough.mp3', 'adj.粗糙的', '88e81cc2c8e9c6ed5eb676325de8b490_148926_1733118999.jpg', '20130315_17_33_09_492.png', 'The hands of the farmer are rough.', '这个农民的手很粗糙。', 'nze64amta4krvpy38v9a6uf4p5c77jh4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2486, 'school', '/skuːl/', 'school.mp3', 'n.学院', 'f40627a4246c57682f4a4e62cbcd8c4f.jpg', 'd_24_19472_0_3_20150809001437.png', 'They are the students in the School of Biology at the university.', '他们是这所大学生物学院的学生。', 'edc5be9bfd0b7e72936ebb6f00b970fa_47278_1600307831.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2487, 'sketch', '/sketʃ/', 'sketch.mp3', 'n.素描；  v.速写', 'c7b4b40668c4bf3aca329f1bbf1036ac_118698_1585058340.jpeg', '20140929_02_53_02_207_v3.png', 'The artist is doing a sketch of the living room.', '这位画家正在画一幅客厅的素描。', 'v6x9gwzjjmmfbrwkzhhte7kx67gl9kr7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2488, 'sometime', '/ˈsʌmtaɪm/', 'sometime.mp3', 'adv.在某一时候；  adj.某一时间的', '3_0_20170930071157_1597_c-gigapixel-scale.jpg', '', 'Although I failed the exam', '虽然我考试失败了，但我相信总有一天我会成功的。', '3_0_20170930071157_28242_c.aac', 'some某 + time时间 → sometime在某一时侯', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2489, 'step', '/step/', 'step.mp3', 'n.脚步，脚步声；  v.走，举步', '47fa458d388edc68ae63762b3e1daf7a_95412_1719565418.jpg', '20141010_22_00_32_249_v3.png', 'He\'s so excited to see his baby girl take her first step.', '看到他的宝贝女儿迈出第一步，他激动极了。', '69302f0452dbb358_1266883011454524134_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2490, 'stuff', '/stʌf/', 'stuff.mp3', 'n.东西；材料；原料；  v.把……塞进；装满', 'i_1_5632_0_2_20150808124121-gigapixel-scale.jpg', 'd_1_5632_0_2_20150808124121.png', 'We keep all of the baby\'s stuff in his bedroom.', '我们把婴儿的所有东西都放在他的卧室里。', '86b8cd2103b64a2d_1266798141710838730_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2491, 'such', '/sʌtʃ/', 'such.mp3', 'det.这样的，那样的，此类的', '41adef1a5e01c6e914b8e34bc69b603a_78782_1544079374.jpg', 'd_16_19276_0_2_20150809021524.png', 'Look! Such a beautiful view.', '看！这是多美的景色啊！', '42705c9b691063cdd2a160f4783d4edd_12427_1544079384.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2492, 'supply', '/səˈplaɪ/ ', 'supply.mp3', 'n.供应，供应量；（复数）储备；  v.供给', '47f1e3c234384314a48224d1d8d309ff_858939_1622431350.jpg', '20130301_12_58_50_745.png', 'The farmer has an adequate supply of milk.', '农场主有充足的牛奶供应。', 'mldh4qr6jru34w8wltkk9n8f4uczvle2.mp3', 'sup在下面 + ply填充，充满 → 填充下去 → 供应[下去]，补给', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2493, 'suppose', '/səˈpoʊz/', 'suppose.mp3', 'v.认为；设想，推想', '13c5198bef400e23e6fda068176ad07c_145980_1587465251.jpg', 'd_24_9907_0_3_20150808230326.png', 'I suppose that I can be back before nine o\'clock.', '我想我九点前能回来。', 'g8d679p523ltl92ncsbw6l77nhjdy97j.mp3', 'sup在……下面 + pose放 → 放下去想 → suppose猜想，推测', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2494, 'suspect', '/ˈsʌspekt/', 'suspect.mp3', 'n.犯罪嫌疑人，可疑分子；  v.怀疑，猜疑；  adj.可疑的', 'ec650add8ac240e7d8dfd45264db40e6_184270_1538666968.jpg', 'd_16_5769_0_4_20150808225839.png', 'The suspect is talking with his lawyer.', '犯罪嫌疑人正在和他的律师谈话。', '505470ad5a2d5f7a722673a43ac32f28_11958_1538667012.mp3', 'sus在…下面 + pect看 → (偷偷地)在下面看 → suspect怀疑；嫌疑犯，可疑分子', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2495, 'suspicious of', '/səˈspɪʃəs əv/', 'suspicious of.mp3', 'phr.对 ... 怀疑的', '845a509d8c4fd1bb759446faffb2e938.jpeg', '', 'She is suspicious of his motives for suddenly being so nice to her.', '他突然对她特别好，这不禁让她怀疑其动机。', '50292e20fb59f1238f9d7629d7c7b3f0.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2496, 'taste', '/teɪst/', 'taste.mp3', 'v.品尝，尝（......的味道），尝起来；品鉴；  n.味道；鉴赏力', '005b88d1a30b3d7f64044b6f5f158dfd_34409_1585124508.jpeg', 'd_24_7947_0_4_20150808225257.png', 'She always tastes the soup before serving it to others.', '她上汤之前总要先尝一尝。', '613ec30904aef761_1266883010312886992_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2497, 'tent', '/tent/', 'tent.mp3', 'n.帐篷', 'i_16_18022_0_4_151123142026-manual-scale.jpg', 'd_95_14499_0_4_20150809012858.png', 'The couple put up a tent beside the river.', '那对夫妇在河边支起了帐篷。', 'we8kha82bjn2dehpb3x4ycsl43us7ecj.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2498, 'tiny', '/ˈtaɪni/', 'tiny.mp3', 'adj.矮小的；很少的；微小的，很小的', 'i_1_5619_0_4_150926145542-gigapixel-scale.jpg', 'd_24_5619_0_4_20150808224229.png', 'The kitten is so tiny that it could be held in one hand.', '这只猫咪好小，一只手就可以把它托起。', 'wz3nvv2pczmwmckmajb3ps9gd2bql99m.mp3', 'tin=tine尖齿 + y表形容词 → tiny微小的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2499, 'tire', '/ˈtaɪər/', 'tire.mp3', 'v.使疲倦；  n.（=tyre）轮胎，车胎', 'dfb218dfdd0827f51ebd74fedafa99d9_12130_1732251709.jpg', '20140928_05_51_44_955_v3.png', 'He was beginning to tire after a long day of work.', '一整天的工作后，他开始感到疲倦了。', 'us_He_was_20241122130152051_2a9f3e24e8bb3c77a4d5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2500, 'title', '/ˈtaɪtl/', 'title.mp3', 'n.标题；  v.授予……称号', '167c17757736f0475168ef0faf0a86c9_192160_1573009122.jpeg', 'd_107_3867_0_2_20150809003231.png', 'She read a book whose title shows it\'s about a woman born in 1982.', '她读了一本书，书名表明这本书和一位在1982年出生的女性有关。', '354a1da53dac6cf7cab5864aa7a8f650_49712_1574154245.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2501, 'total', '/ˈtoʊtl/', 'total.mp3', 'adj.整个的，总体的；  n.总数', '7741775a42232e081980dfcd558d4364_156861_1574840726.jpeg', 'd_24_8090_0_4_20150808225429.png', 'What\'s the total number of ducks in the pond?', '池塘里一共有多少只鸭子呢？', 'd235b22c5f5511630730f9625bfdb218_39325_1574840723.mp3', 'tot全部 + al表形容词 → total总体的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2502, 'valley', '/ˈvæli/', 'valley.mp3', 'n.山谷，溪谷，低谷', '3_0_20170608071546_78109_c-gigapixel-scale.jpg', 'd_24_5080_0_4_20150808223903.png', 'A small stream flows through the valley.', '一条小溪流过山谷。', 'zl7dvetbavjx6tfut4xy3a79pzmhccdz.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2503, 'will', '/wɪl/', 'will.mp3', 'n.意志', '9b965820f4df39a68e0d7b0ab9b9cdfc.jpg', '20121225_18_42_46_651.png', 'He had a strong will', '他意志坚强，相信自己一定能够夺冠。', '5dcbac634baf2a2de69d8f5f461aa521_45598_1599536786.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2504, 'accustomed', '/əˈkʌstəmd/', 'accustomed.mp3', 'adj.习惯于；通常的，惯常的', 'i_1_10252_0_4_150917165124-gigapixel-scale.jpg', 'd_16_10252_0_2_20150808235354.png', 'He got accustomed to the food after 10 years of living here.', '在这里住了十年之后，他习惯了这里的食物。', '034871a29e9d5ccc_1266883374081727002_250207.mp3', 'ac加强意义 + custom习惯 + ed形容词后缀 → accustomed习惯的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2505, 'address', '/ˈædres/', 'address.mp3', 'n. 地址，住址；致辞（读作/ˈædres/）；  v.写姓名地址', 'i_24_4736_0_5_151208144337-gigapixel-scale.jpg', 'd_24_4736_0_3_20150808223547.png', 'You must write down the address before sending a letter.', '寄信之前你必须写上地址。', 'twkz9h57tkdxxa6x54t6nfqkgy4evh9x.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2506, 'Africa', '/ˈæfrɪkə/ ', 'Africa.mp3', 'n.非洲', '98bf25b9280b351037f4cafa92f47014_155486_1733897817.jpg', 'd_109_17534_0_2_20150809062237.png', 'These coffee beans are native to Africa.', '这些咖啡豆原产于非洲。', 'a4ucytys98hwva7x3l6cwa543rj58t4l.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2507, 'agriculture', '/ˈæɡrɪkʌltʃər/ ', 'agriculture.mp3', 'n.农业', '4fc7d7f76052b6f3d6a5d3e731748405_82969_1565684417.jpg', 'd_105_5125_0_2_20150809054449.png', 'Farmers rely on agriculture to make a living.', '农民以务农为生。', 'yhjg4het2a6c9tptcakxgzkaayburmps.mp3', 'agri田地 + cult耕种 + ure表名词 → 在田地里耕作 → agriculture农业', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2508, 'aim at', '/eɪm æt/', 'aim at.mp3', 'phr.瞄准，对准，目的在于', '9ae7fed6516588c451908b108a1fd1d3.jpg', '', 'She is aiming at the target.', '她正瞄准靶心。', 'us_She_is_20250224132803681_cd64304e546577c918b5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2509, 'appear', '/əˈpɪr/', 'appear.mp3', 'v.出现，呈现，露面', '3_0_20170928071253_11520_c-gigapixel-scale.jpg', 'd_13_6954_0_2_20150808192824.png', 'I\'m so excited! My idol is about to appear on stage.', '我实在太激动了！我的偶像马上就要出现在舞台上了。', '2562546426c1c912_1266797982569421334_250123.mp3', 'ap再 + pear看见 → 看见 → appear出现，显露', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2510, 'as a result of', '/æz ə rɪˈzʌlt əv/', 'as a result of.mp3', 'phr.作为……的结果，由于', '16c1bf96b66f0fe0c0162dd5907adae9_200980_1564370473.jpg', '', 'The statement of ICU waiting as a result of 996 working has aroused heated discussion.', '“工作996导致生病ICU”这一话题引起了热议。', '6387bcc76f0446726f51eaf4b0bb8fc9_49802_1564370473.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2511, 'assignment', '/əˈsaɪnmənt/', 'assignment.mp3', 'n.（课外）作业', '56940a28ccc660503c8a9b5f2acf5eb6_52944_1565707229.jpg', 'd_107_9307_0_2_20150809024606.png', 'My teacher gave me a lot of assignments for the weekend.', '老师给我布置了很多周末的家庭作业。', '82da8d3d29b35a0239a6090a0a9f6a8d_19638_1622169717.mp3', 'assign分配 + ment名词后缀 → assignment（课外）作业', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2512, 'at one time', '/æt wʌn taɪm/', 'at one time.mp3', 'phr.曾经', '2547e84cc99ceeaca389de6798f3cdc1.jpg', '', 'At one time she made her own clothes.', '曾经有段时间，她自己给自己做衣服穿。', 'd4e23af2cfe4549674ace760fac5778a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2513, 'attach', '/əˈtætʃ/', 'attach.mp3', 'v.贴上，使依附；把……固定，把……附（在……上）；缚；认为...有重要性；附加', 'c5ce85d0817eafb656690c21093b69f2_186990_1533105031.jpeg', '20130106_14_37_00_807.png', 'The card player has several pieces of paper to attach to his face.', '这个打牌的人有好多张纸条要贴在他的脸上。', 'us_The_card_20241009151641381_d460b9ab628252b242d1.mp3', 'at=ad 去 + tach 固定，栓→ 去固定 → attach附上，使附属，使依恋', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2514, 'attendant', '/əˈtendənt/', 'attendant.mp3', 'n.服务员，侍者，随从；  adj.伴随的，随之而产生的', 'f33d65f2c36cfa480fb23f25cfbc72be_174046_1556346961.jpeg', '20140709_22_10_10_833_v3.png', 'The gas attendant is filling up the car for the customer.', '这个加油站服务员正在为顾客的汽车加油。', '5766e12bd861d6a1b2e2d02fe54bfc21_19951_1613968413.mp3', 'attend照料 + ant名词后缀  → 照料的人  → 服务员，随从', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2515, 'Australia', '/ɔːˈstreɪljə/', 'Australia.mp3', 'n.澳大利亚', '8abda0a708eb3b7dd5f4700c4f35d17c_90438_1541842251.jpg', '20130307_16_43_37_452.png', 'Sydney is the biggest city in Australia.', '悉尼是澳大利亚最大的城市。', 'b3ffadcebd320a8e_1266763449128606436_250117.mp3', 'Austral南面的 + ia表名词 → Australia澳大利亚', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2516, 'authority', '/əˈθɔːrəti/', 'authority.mp3', 'n.权威，威信', '93dc992aee701cd11e67e2b12a0e765a_187878_1564822994.jpg', 'd_24_8955_0_3_20150808225945.png', 'The authority declared that catmint would be banned completely in three months.', '当局宣称猫薄荷将在三个月后被全面禁止。', '607be40329fe2fbb2a30b8f708713b8b_46828_1564822984.mp3', 'auth使增加；创造 + or施动者后缀 +ity名词后缀 → authority权力；权威', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2517, 'automatic', '/ˌɔːtəˈmætɪk/', 'automatic.mp3', 'adj.自动的；无意识的；  n.自动手枪', 'i_1_5766_0_3_20150808124349-gigapixel-scale.jpg', '20121225_20_04_12_771.png', 'The automatic production line improves the working efficiency greatly.', '自动化生产线大大地提高了工作效率。', 'sa_1_5766_0_3_20150808124349.aac', 'autom=auto，autom自动 + atic有…性质的 → automatic自动的，机械的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2518, 'automobile', '/ˈɑːtəmoʊbiːl/', 'automobile.mp3', 'n.汽车，机动车', 'i_1_8956_0_8_151019150403-gigapixel-scale.jpg', 'd_1_8956_0_4_20150808131052.png', 'This green automobile is for sale. Let\'s take a look.', '这辆绿色的汽车正在出售，我们去看看吧。', 'us_This_green_20241009155003209_3791935bd56b48e91b2e.mp3', 'auto自己 + mobile移动的 → automobile汽车', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2519, 'bar', '/bɑːr/', 'bar.mp3', 'n.酒吧；(金属)棒；闩；障碍；柜台；  v.阻挡（某人）；阻止；闩住', '3712ef74c3a2eab296771af967842c98_96605_1565343460.jpg', 'd_16_5535_0_2_20150808225407.png', 'There\'s no one drinking in the bar because it\'s too early.', '酒吧里现在没人在喝酒，因为太早了。', '1040e85141276fc872e6621ee3f3259e_18540_1619321812.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2520, 'bath', '/bæθ/', 'bath.mp3', 'n.洗澡；浴缸', '1f709d4a329465c44e835f56f9c80785_25571_1736400064.jpg', 'd_24_5711_0_4_20150808224310.png', 'I took a long bath to relax myself.', '我泡了很长时间的澡来放松自己。', 'spmznnx66rnqwajx57jbbudgzvk8j4v8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2521, 'beast', '/biːst/', 'beast.mp3', 'n.野兽', '52c72d186b1f0a8f2b589f00227134c0_162552_1538388277.jpeg', 'd_16_5249_0_2_20150808225201.png', 'Lions', '狮子、老虎、狼和豹子都是危险的野兽。', '4228130d3182c4834144055d4ecfed7d_37529_1621931369.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2522, 'bet', '/bet/', 'bet.mp3', 'n.赌，赌注；  v.打赌；敢断定', 'a5c782a9dee08928ddf0334c81c1e8a8_213822_1731037509.jpg', 'd_107_5412_0_2_20150809012403.png', 'The man made a bet on the score of a game.', '这个人在比赛比分上赌了一把。', '35cc88be01320bc805df2e821e9f9116_11958_1538758151.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2523, 'bring out', '/brɪŋ aʊt/', 'bring out.mp3', 'phr.出版，推出', 'f2ff2fa3e4ae79ab7c5cbb20b6884b7d_121186_1587886164.jpeg', '', 'The author will bring out a new book soon. ', '这位作家将会出版一本新书。', 'us_The_author_20220609102726261_8ae3154ff834fc7fd13f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2524, 'British', '/ˈbrɪtɪʃ/', 'British.mp3', 'adj.英国（人）的，不列颠的', '68d494b62238bbe434be88e2d28be984_260328_1656644459.jpg', 'd_24_19508_0_3_20150809001735.png', 'This is a classic old red British telephone box.', '这是一个经典的英国老式红色电话亭。', '13212fbfc1d2e99c_1266763449417313266_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2525, 'campaign', '/kæmˈpeɪn/', 'campaign.mp3', 'n.（社会性、政治性）活动，运动；  v.从事活动', '0a90858b2a659b29ab6e92692749a463_177776_1573616655.jpeg', 'd_107_4976_0_2_20150809011209.png', 'Many people launched a campaign to call for environmental protection.', '许多人发起了一场呼吁环保的运动。', 'a76b0ec7641035fd29d4ed0d9f6277ed_41594_1573616652.mp3', 'camp营地 + aign名词后缀 → 营地 → 战役', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2526, 'capital', '/ˈkæpɪtl/', 'capital.mp3', 'n.首都；大写字母；  adj.大写的', '6b9e5763495d80ef1ff26d8df3c0520d_130309_1656661919.jpg', '20130106_14_37_42_195.png', 'Beijing is the capital of China.', '北京是中国的首都。', '667ed21c13c8ad3f_1266883380364597856_250207.mp3', 'capit头 + al…的 → 头的 → capital首都', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2527, 'career', '/kəˈrɪr/', 'career.mp3', 'n.职业，事业', '30412ab3c326eb59e2e71caf8963176c_136806_1696662070.jpg', 'd_1_4996_0_2_20150808123313.png', 'What career would you want to choose? A policeman or fireman?', '你想选择哪种职业，警察还是消防员？', 'b2j8dtf3urvzgrg5neb89gku8pmlr4ut.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2528, 'coal', '/koʊl/', 'coal.mp3', 'n.煤', 'e00af5e6b827e3581561877e9cf5330d_134492_1574912295.jpeg', 'd_24_15988_0_4_20150808230947.png', 'He is holding a few pieces of coal.', '他正捧着几块煤。', '4qcyvfta4ucrl69tul5s4884ba57g2xn.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2529, 'commute', '/kəˈmjuːt/', 'commute.mp3', 'v.经常乘车往返于两地之间；  n.通勤，在两地之间乘车往返；  v.减轻（刑罚）', '1426493091256-gigapixel-scale.jpg', '20140726_12_11_06_599_v3.png', 'I commute from my home to the office by bus every day.', '我每天乘公交车往返于家和办公室。', 'sa_2_2948_0_8_160129143149.aac', 'com和，一起 + mute改变 -> commute两地往返', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2530, 'concept', '/ˈkɑːnsept/', 'concept.mp3', 'n.概念；想法；观念', '3_0_20170712071112_81332_c-gigapixel-scale.jpg', '20130105_10_18_23_23.png', 'Copernicus presented a new concept regarding the solar system.', '哥白尼提出了一个有关太阳系的新概念。', 'h93kz8mbtawhu6t8fztrucgbvy8ffb5t.mp3', 'con共同 + cept掌握 → 能共同掌握的 → 概念，设计', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2531, 'contest', '/ˈkɑːntest/', 'contest.mp3', 'n.比赛，竞争（读作/ˈkɑːntest/）；  v.争夺，争论（读作/kənˈtest/）', '7114eeeac538c2e02f7d0ecc5dc6bf15_138072_1544240987.jpeg', 'd_1_5953_0_2_20150808124558.png', 'The girl in the middle seems to be the winner of the contest.', '中间的女生好像是这场比赛的获胜者。', '11bc74b00d6aed0546fe5f0cf76baf8f_47552_1572345546.mp3', 'con共同 + test测试 → 共同测试 → contest比赛，竞赛', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2532, 'context', '/ˈkɑntɛkst/', 'context.mp3', 'n.上下文，语境；背景', 'e5615004a23d5bb0cce648c3e5a9efbe_125087_1583478805.jpeg', '', 'We need the context to choose the right answer.', '我们需要上下文才能选出正确答案。', 'us_We_need_20220705114049317_7c69c0a681ae9347aabe.mp3', 'con一起 + text编织 → context上下文，来龙去脉', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2533, 'continue', '/kənˈtɪnjuː/', 'continue.mp3', 'v.继续', '4bad24b1702a7b4ceec4f3ec586fb68a_200734_1578559660.jpeg', 'd_24_15922_0_3_20150808230832.png', 'She continued running when the others stopped.', '当其他人停下的时候，她还在继续奔跑。', '7f4c8264431e553e_1266883320407022156_250207.mp3', 'con全部 + tinu握住 + e → 全部拿住 → 做事做到尾 → continue继续', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2534, 'contract', '/ˈkɑːntrækt/', 'contract.mp3', 'n.合同，契约（读作/ˈkɑːntrækt/）；  v.感染（疾病）；签合同；订立（婚约）；缩减', '082a6c10a226c74604904545c2b096f2_55604_1721095247.jpg', '20121225_19_58_43_660.png', 'I signed the contract and bought the house.', '我签了合同，买下了这栋房子。', 'ff6388fbc408b7baf43a8bb665832126_14779_1646639277.mp3', 'con共同 + tract拉 → 拉到一起来 → contract合同', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2535, 'control', '/kənˈtroʊl/', 'control.mp3', 'v.控制，管理；  n.控制装置', 'd3343cf73c4a2fb871f154c0b415258e_186348_1577950456.jpeg', '20121225_20_14_00_674.png', 'The little boy can control the direction of his toy car.', '小男孩可以控制玩具汽车的方向。', '6a097fdade942dd6_1266883485716032336_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2536, 'cost', '/kɔːst/', 'cost.mp3', 'n.价格', 'f8048312d512ec2f18b1839400b6c107.jpeg', 'd_96_12256_0_4_20150809014330.png', 'The cost of this new house is one million dollars.', '这座新房子的价格是一百万美元。', '09a8c9c665ca948a20f5c151dda37c8a.mp3', 'co一起 + st站立，使稳定 → 使事物形成所需的东西 → cost支出，成本，花费', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2537, 'crystal', '/ˈkrɪstl/', 'crystal.mp3', 'n.水晶；结晶；水晶做成的东西', '271d5dc7f99cdbd04b7fba49b35580d4_82339_1573617920.jpeg', 'd_1_4734_0_2_20150808122940.png', 'She is holding a purple crystal in her hand.', '她正拿着一块紫水晶。', 'c089cf65891655d9_1266883532665170848_250207.mp3', 'crys冻，结冰 + tal → crystal水晶，晶体', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2538, 'cultural', '/ˈkʌltʃərəl/', 'cultural.mp3', 'adj.文化的；教养的', '432df4eb6176f41c5980a7186c842f80_187503_1583479070.jpeg', '', 'These cultural symbols are very important to Chinese people.', '这些文化符号对中国人来说非常重要。', 'c7b4a562d1db7a6591d1eb34bc770c97_39774_1583479067.mp3', 'cultur(e)文化 + al形容词后缀 → cultural文化的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2539, 'define...as', '/dɪˈfaɪn æz/', 'define...as.mp3', 'phr.给……下定义', '289a7fa1013affe5164b8b0d114844d1.jpg', '', 'Different people may define happiness as what they wish most at that moment.', '不同的人可能会把“幸福”定义为他们目前最希望得到的。', 'ea14910c09af2a8b95bcb4d41e435031.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2540, 'delicious', '/dɪˈlɪʃəs/ ', 'delicious.mp3', 'adj.美味的，可口的', '5d9b40307104c402db2747585bb88b6b_204619_1583335539.jpg', '20141012_07_32_30_322_v3.png', 'The rice noodles my brother is cooking look so delicious!', '我哥哥煮的米粉看起来真美味！', 'df558bf760a482f9_1266883006235499072_250207.mp3', 'de再 + lic诱惑 + ious表形容词 → 再引诱的 → delicious美味的，可口的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2541, 'density', '/ˈdensəti/', 'density.mp3', 'n.密度；密集，稠密', 'i_4_811_0_4_151222171706-gigapixel-scale.jpg', 'd_1_811_0_2_20150808121600.png', 'The high density of buildings makes the city so crowded.', '这个城市的建筑密度很高，所以城市也非常拥挤。', 'sa_4_811_0_4_151225155238.aac', 'dens稠密的 + ity名词后缀表性质 → 稠密 → density稠度，密度', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2542, 'depart', '/dɪˈpɑːrt/', 'depart.mp3', 'v.离开，出发', '29b3ae8a1dd6a54d8522a6689b05e9b6_133957_1556332531.jpeg', 'd_1_3846_0_3_20150808121940.png', 'The steamship just departed from the dock.', '这艘蒸汽轮船刚刚离开了港口。', '36sxp9twkywl3geasmhm8r5mx4ww9zbe.mp3', 'de从 + part分开 → depart离开', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2543, 'difficult', '/ˈdɪfɪkəlt/', 'difficult.mp3', 'adj.困难的，难做的；难对付的，不易相处的', '8ca76e39b9001ec892a8e7a61c15ad8a_174081_1743994998.jpg', 'd_24_17949_0_4_20150808233655.png', 'It is difficult for her to carry such a huge stone.', '让她搬起这么大的一块石头实在太难了。', 'z7udtcccgp24g6wegxtyaqd7pu7fhc9w.mp3', 'dif不 + fic做 + ult表名词 → 不好做 → difficult困难的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2544, 'digest', '/daɪˈdʒest/', 'digest.mp3', 'v.消化；  n.摘要（读作/ˈdaɪˌdʒest/）', '8308de514a4629598e3cf5faff742b47_99898_1594802687.jpg', 'd_16_6601_0_2_20150808230832.png', 'Many parts of your body are involved in digesting food.', '你身体中有很多的部位共同参与了食物的消化过程。', 'b57e8e1bb0961133b4fc9256110f3f6e_44896_1569577390.mp3', 'di分离 + gest执行 → digest消化', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2545, 'dine', '/daɪn/', 'dine.mp3', 'v.用正餐（或晚餐）；吃饭，用餐；招待……吃饭', '0280cb824a3b12bb725bff08514cfc97_132450_1538759136.jpg', '20121225_20_11_51_237.png', 'Those friends enjoy going out to dine on Friday night.', '这几个朋友很喜欢周五晚上出去吃饭。', '31e248d94c0df812d44165e2ab07b220_47120_1597654239.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2546, 'disagree with', '/ˌdɪsəˈɡriː wɪð/', 'disagree with.mp3', 'phr.不一致', '94db6407297a6411625b41d66ead24ff.jpg', '', 'They disagreed with each other about which car to buy.', '他们在买哪辆车的问题上意见不一致。', '022b2ff9c12c4171c6567b2902f09538.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2547, 'discuss', '/dɪˈskʌs/', 'discuss.mp3', 'v.讨论，商量；详述，论述', 'c5ee2e58fea1b4d70a55f85735377a62_150388_1605153529.jpg', 'd_24_4982_0_3_20150808223752.png', 'The students discussed the topic on the blackboard.', '学生们讨论了黑板上的话题。', 'f798b28cad2061b9_1266798147197098720_250123.mp3', 'dis分开，分离 + cuss敲打 → 把问题分开敲 → discuss讨论', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2548, 'distort', '/dɪˈstɔːrt/', 'distort.mp3', 'v.扭曲，使变形', 'd51c559c805cddf6c1d2040f1b10d791_191160_1633685315.jpg', '20140827_21_33_53_247_v3.png', 'Somebody is distorting the real image using a mirror.', '有人用镜子把真实的图像扭曲了。', 'sa_102_936_0_3_20150809040831.aac', 'dis分离 + tort变形，扭曲 → distort扭曲', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2549, 'dollar', '/ˈdɑːlər/', 'dollar.mp3', 'n.美元', '86f97f95d9c67cb31f6075bd9e70a91b_140492_1656658019.jpg', 'd_24_17208_0_3_20150808232354.png', 'There is only one dollar left in the wallet.', '钱包里只剩下一美元。', '9512c2b40c4c74612a309e09f3ef25ff_34366_1577950866.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2550, 'draw up', '/drɔ ʌp/', 'draw up.mp3', 'phr.起草；停靠在', '2b3db36bb3e46b3641ae1f0804f6e766.jpg', '', 'The couple is drawing up a list of furniture they need for their new house.', '这对夫妇正在草拟一份他们的新房子所需家具的清单。', 'fdd7488d6edd2a6eff7aa9d012e097cd.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2551, 'drop off', '/drɑːp ɔːf/', 'drop off.mp3', 'phr.减少，下降', '1b2ed2cf45223004e4fbc597ea08826f.jpg', '', 'The company had to close after sales dropped off sharply.', '这家公司在销售额急剧减少后不得不关门。', 'bvkcbez5fhrjlerc87vf695j4rxs79vr.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2552, 'earnest', '/ˈɜːrnɪst/', 'earnest.mp3', 'adj.真诚的，诚挚的，认真的', '1423912451002-manual-scale.jpg', 'd_1_4302_0_3_20150808122620.png', 'Thank you very much! said the granny with an earnest expression on her face.', '“非常感谢你！”这位老奶奶满脸真诚地说道。', 'sa_103_4302_0_3_20150809005305.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2553, 'earthquake', '/ˈɜːrθkweɪk/', 'earthquake.mp3', 'n.地震', 'f43dc29f37f3c6d4223d525cc150f40f_208677_1741241025.jpg', 'd_24_8603_0_4_20150808225827.png', 'The rescue team went to rescue the victims of the earthquake.', '营救小组去营救地震的受害者。', 'e4b76d3a1d7679db_1266883527853693550_250207.mp3', 'earth地球 + quake震动 → earthquake地震', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2554, 'ease', '/iːz/', 'ease.mp3', 'n.轻松；安逸；  v.缓解；解除痛苦', '6c609d0f4d504e4c9db6a413dd0c015a_125596_1725253791.jpg', 'd_16_4493_0_5_20150808224256.png', 'The strong man can lift the rock with ease compared to the other man.', '与另一个男人相比，这个强壮的男人可以轻松地举起石头。', 'us_The_strong_20240823144427310_a4d986217aae50afbf83.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2555, 'electronic', '/ɪˌlekˈtrɑːnɪk/', 'electronic.mp3', 'adj.使用电子装置的；电子的；电子学的；电子操控的', '37f86ba8bf4ef96a84af5efa34f10f8b_83530_1568711800.jpg', '20140926_03_58_41_280_v3.png', 'The DJ played electronic music at the party.', 'DJ在聚会上播放电子音乐。', 'f8db94d4ce4aefb00a901ecc205f3447_44029_1589537805.mp3', 'electron电子 + ic形容词，……的 → 电子的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2556, 'empire', '/ˈempaɪər/', 'empire.mp3', 'n.帝国', 'f1ec5299598a4ff9f7b01f32226519eb_86940_1565342715.jpg', 'd_16_5139_0_2_20150808225035.png', 'This was built during the Roman empire.', '这是在罗马帝国时期修建的。', 'pecusg8eywsh6yr696z4jzr9pfktykkv.mp3', 'em=in内 + pire命令  → 下命令  → empire帝国', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2557, 'employ', '/ɪmˈplɔɪ/', 'employ.mp3', 'v.雇用；使忙于，使从事；应用', '3_0_20170928071202_13400_c-gigapixel-scale.jpg', 'd_24_16813_0_4_20150808231919.png', 'She employed a babysitter to look after her children.', '她雇了个保姆来照顾她的孩子。', '5a4e5ae7840df4ae_1266883329500293902_250207.mp3', 'em在……里 + ploy折叠 → employ投入，雇佣', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2558, 'endure', '/ɪnˈdʊr/', 'endure.mp3', 'v.忍受，容忍', '3e85566bc27d2c53bb8d71d0055935dd_72701_1538621274.jpg', 'd_9_10562_0_3_20150808165710.png', 'It is very hard to endure the toothache.', '牙痛是难以忍受的。', '2236d2d363297451a66c6b1812b77e47_12271_1538621287.mp3', 'en艰难 + dure使……艰难 → endure度过，忍受', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2559, 'engine', '/ˈendʒɪn/', 'engine.mp3', 'n.引擎；发动机', '77058be597b097c0d2d8037154dfc5ee_87004_1626688934.jpg', '20130130_16_08_32_767.png', 'The engine at the front of the car makes the car move.', '汽车前部的引擎使汽车移动。', 'ybswdykrqf9ht9pzh9w7mzhb7l6erull.mp3', 'en=in内部 + gine生育 → engine引擎', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2560, 'estate', '/ɪˈsteɪt/', 'estate.mp3', 'n.地产', '09a39d0b87127d486280896f9ec7822a_81236_1566800860.jpg', 'd_1_3897_0_2_20150808122025.png', 'My estate includes my house and part of the forest.', '我的地产包括我的房子和这片森林的一部分。', '4d6be3c36997e430_1266883620725763038_250207.mp3', 'e出 + stat站着 + e强调 → 站出来的东西 → estate房子等不动产', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2561, 'excellent', '/ˈeksələnt/', 'excellent.mp3', 'adj.优秀的；杰出的，极好的', '3_0_20170721071138_14586_c-gigapixel-scale.jpg', 'd_78_18092_0_5_151021111339.png', 'He\'s an excellent student who always gets excellent scores.', '他是一名优秀的学生，总是得高分。', 'e23445afa6529695_1266797981615807228_250123.mp3', 'ex离开 + cell监狱 + ent…的 → 品德优秀的人离监狱很远 → excellent杰出的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2562, 'exhibition', '/ˌeksɪˈbɪʃn/', 'exhibition.mp3', 'n.展览；（技能、感情或行为的） 表演；陈列', '84562bf3279ffcab6b9bf6e463fbc75e_192516_1585808041.jpeg', '20140927_02_53_47_241_v3.png', 'They are visiting a new oil painting exhibition.', '他们正在参观一场新的油画展览。', 'dd9f66d35a590eee_1266798143166852052_250123.mp3', 'ex出 + hibit拿住 + ion名词后缀 → 拿出去给人看 → 展览；陈列', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2563, 'export', '/ɪkˈspɔːrt/', 'export.mp3', 'v.出口，输出；  n.出口，输出', '3193e336e63661293a448d5ed4046986.jpeg', 'd_107_3975_0_2_20150809003816.png', 'Our company exports products to many different countries.', '我们公司向许多国家出口货物。', 'us_Our_company_20240819164042645_c5b19b7b4ef7f2ce9be5.mp3', 'ex出 + port拿，引申为港口 → 拿出港口 → 出口', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2564, 'fan', '/fæn/', 'fan.mp3', 'n.风扇，扇子', '879d62605844e51145cc5dce2bbe3b86_88292_1577936737.jpeg', '20140927_20_50_06_818_v3.png', 'In summer', '夏日里，她坐在电扇前让自己凉快些。', 'ed0c9cfe18343e7faffa6f3c8d74ba8a_49486_1577936734.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2565, 'fate', '/feɪt/', 'fate.mp3', 'n.命运', 'i_1_5831_0_4_160324101731-gigapixel-scale.jpg', 'd_1_5831_0_2_20150808124458.png', 'It was my fate to marry him.', '我嫁给他是命中注定的。', '4f2394eb8655ac2e_1266883484437621542_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2566, 'fierce', '/fɪrs/', 'fierce.mp3', 'adj.凶猛的，凶狠的；激烈的', '9c634b77798a784670cffe3ea6311cd7_171907_1534151794.jpeg', 'd_24_5963_0_4_20150808224410.png', 'The tiger showing its sharp teeth looks so fierce.', '这只露出锋利牙齿的老虎看上去真凶猛。', 'af926b9b752c43ff20e6c445257ac2fd_20860_1554715197.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2567, 'financial', '/faɪˈnænʃl/', 'financial.mp3', 'adj.金融的', 'f08d7555f9a6061be9fe74704b71570b_356927_1653964799.jpg', 'd_107_6626_0_2_20150809020555.png', 'This is one of the most famous financial cities in the world.', '这是世界上最有名的金融城之一。', 'us_This_is_20220531103939098_f1e96bee380aa9593930.mp3', 'financ=finance金融 + ial属于……的 → financial财政的，金融的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2568, 'finger', '/ˈfɪŋɡər/', 'finger.mp3', 'n.手指；指状物', '3_0_20170709071054_32439_c-gigapixel-scale.jpg', 'd_93_12712_0_4_20150809002021.png', 'These finger puppets are so funny!', '这些手指人偶真是太有趣了！', '3_0_20170709071054_68644_c.aac', 'fing五 + er名词后缀，人或物 → 人有五个手指 → finger手指', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2569, 'fire', '/ˈfaɪər/', 'fire.mp3', 'v.解雇；  n.火；火灾', 'b1c0e931a89161077c3d384a8b364f8c_202233_1611037092.jpg', 'd_24_17988_0_3_20150808233949.png', 'The guy was fired by his boss.', '他被老板解雇了。', 'us_The_guy_20250327110501600_568cdf248b0da50686b4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2570, 'for the time being', '/fɔr ði taɪm ˈbiɪŋ/', 'for the time being.mp3', 'phr.暂时，目前', '88cbd81ffa893aa7d79bb5286cc714a6.jpg', '', 'Having not found a new apartment', '他还没有找到新公寓，所以暂时寄宿在一个朋友家。', '4aee9d47ccc0bdb1bf7bb95da7b68447.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2571, 'frequent', '/ˈfrikwənt/', 'frequent.mp3', 'adj.时常的，频繁的（读作/ˈfrikwənt/）', 'cd0c04b30ba04aa35980389aa7d39031_58853_1732245003.jpg', '20130307_16_04_10_470.png', 'My daddy bothers me on a frequent basis.', '我父亲经常来打扰我。', 'us_My_daddy_20241122110958941_ba98c38d9744161ce6b6.mp3', 'frequ挤在一起 + ent形容词后缀 -> frequent时常的，频繁的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2572, 'Germany', '/ˈdʒɜːrməni/', 'Germany.mp3', 'n.德国', 'bff97ecd9e0165698c5bf9204549aee3_108895_1541994723.jpg', 'd_109_17557_0_2_20150809062253.png', 'Look at their clothes! I bet the couple are from Germany.', '看他们的衣服！我打赌这对情侣来自德国。', 'c520dacfa6629e18_1266763401675823626_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2573, 'get across', '/ɡet ə\'krɔːs/', 'get across.mp3', 'phr.（使）被理解', '99cff3ced93bd9571496e335307a0440.jpg', '', 'The man successfully got across his meaning to the customer.', '这个人成功地让客户理解了他的意思。', '138e0db3db2d70b9498019c9ece63504.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2574, 'give away', '/ɡɪv ə\'weɪ/', 'give away.mp3', 'phr.分发；赠送；泄露', '20120928_03_39_38_63.jpg', '', 'His job is to give away samples of our products for people to try.', '他的工作就是将我们的产品的样品分发给人们体验。', '8a066594b7121378_1266883320820968274_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2575, 'goal', '/ɡoʊl/', 'goal.mp3', 'n.目标；（进球）得分', 'c112a684c03f510d1939babd29aa2c67_165082_1534229954.jpeg', 'd_24_5606_0_3_20150808224223.png', 'The boy\'s goal is to become as strong as the man in the poster.', '男孩的目标是变得像海报里的男人一样强壮。', 'mnzvn8pckb6r2hbf7tu62tw7yjylam4y.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2576, 'grade', '/ɡreɪd/', 'grade.mp3', 'n.成绩，评分；  v.给（试卷或作业）评分', 'aa014cec950b1416ee139f5961664461_100286_1584533279.jpeg', 'd_109_8026_0_2_20150809055317.png', 'The little girl is delighted with her excellent grade.', '小女孩为她的优异成绩而感到高兴。', '3744801472982b74612c8c1db10d4f91_48564_1584533276.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2577, 'greenhouse', '/ˈɡriːnhaʊs/', 'greenhouse.mp3', 'n.温室；花房；镶有玻璃的座舱', '20120504_04_06_12_857-gigapixel-scale.jpg', 'd_105_5226_0_2_20150809054539.png', 'Greenhouses are the best place to grow plants quickly.', '温室是快速栽种植物的最好地方。', 'sa_1_5226_0_2_20150808123653.aac', 'green绿色 + house屋子 → 温室，暖房', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2578, 'hand in', '/hænd ɪn/', 'hand in.mp3', 'phr.上交，递交', '5a2dd947f73dcf47a4ff6fcc2b45d4e4_189654_1605175374.jpg', '', 'He\'s handing in his homework to the teacher.', '他正在把自己的作业上交给老师。', '7l2bc5qdb9vkzuachbrzxss2f2kb9lux.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2579, 'haste', '/heɪst/', 'haste.mp3', 'n.匆忙；草率；  v.赶快', 'i_1_1378_0_3_20150808121708-gigapixel-scale.jpg', 'd_107_1378_0_2_20150809001823.png', 'They have to make haste to catch the flight.', '他们必须赶快才能坐上飞机。', 'sa_1_1378_0_3_20150808121708.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2580, 'hatred for', '/ˈheɪtrɪd fɔːr/', 'hatred for.mp3', 'phr.对……的憎恨', '08131ae96c9674b7d228013b29defa74.jpg', '', 'The girl felt hatred for her colleague.', '这个女生对她的同事怀有恨意。', '408b9be46872ff0a6096abce984f3347_35744_1593586785.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2581, 'hazard to', '/ˈhæzərd tuː/', 'hazard to.mp3', 'phr.对……有危险', '2939cf36c72966bb1f33f9bf4d12593a.jpg', '', 'Electricity may be a hazard to children.', '电对于儿童或许是一种危险。', 'a9fbc05f13ae2c76d7dbc1690d56fe97_44192_1593586748.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2582, 'hero', '/ˈhɪroʊ/', 'hero.mp3', 'n.英雄', '16e52b02d766e7a89c88f4185ab554bf_191902_1574909788.jpeg', '20130301_10_55_17_221.png', 'He was praised as a hero for saving the child from the river.', '他从河里救出了孩子，被大家称赞为英雄。', '0db57434f8cce574_1266763553410362330_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2583, 'highway', '/ˈhaɪweɪ/', 'highway.mp3', 'n.公路；城际干道', 'e6b48f57054be8220aae304bb423c414_200760_1574924623.jpeg', 'd_24_5237_0_3_20150808224033.png', 'We are enjoying the beautiful scenery as we drive along the highway.', '我们沿着高速公路开车，享受着美丽的风景。', 'c91bb04dbd14e153f38b2a8ac3198f84_42142_1574924620.mp3', 'high[引]主要的 + way路 → highway公路，大路', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2584, 'homesick', '/ˈhoʊmsɪk/', 'homesick.mp3', 'adj.想家的，思乡的', 'homesick_8833_20231106_6a2163f8.jpg', '', 'Gazing at the bright moon', '看着这轮明月，他很思念自己的家乡。', 'f4014c7090b796fccf58a36f7cb561d3_44960_1598844323.mp3', 'home家 + sick病 → homesick思乡病', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2585, 'household', '/ˈhaʊshoʊld/', 'household.mp3', 'n.家庭；  adj.家庭的', 'i_1_6639_0_3_20150808125305-gigapixel-scale.jpg', 'd_24_6639_0_4_20150808224702.png', 'I grew up in a large household.', '我生长在一个大家庭中。', 'sa_1_6639_0_3_20150808125305.aac', 'house家 + hold持有，拥有 → household家庭', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2586, 'humorous', '/ˈhjuːmərəs/', 'humorous.mp3', 'adj.幽默的，搞笑的', '3_0_20160520173443_16493_c-gigapixel-scale.jpg', 'd_107_6862_0_2_20150809021053.png', 'This guy was so humorous and made everyone laugh.', '这个人很幽默，把大家都逗笑了。', 'z7pe5952b2vmbf74jllnqmhjkyeeufth.mp3', 'humor幽默 + ous…...的 → humorous富于幽默的，诙谐的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2587, 'in a word', '/ɪn ə wɜːrd/', 'in a word.mp3', 'phr.总之，简言之', '20f004bc4a6fbd75b2cb7bbef8ac4b34_123300_1576492257.jpg', '', 'In a word', '总之，这部剧很烂。', '3_0_20170721071436_58327_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2588, 'in common', '/ɪn ˈkɑmən/', 'in common.mp3', 'phr.相同的，共有，有共同之处', 'i_16_10870_0_4_151105141730.jpg', '', 'The girl and boy are thinking in common.', '女孩和男孩有相同的想法。', 'sa_16_10870_0_4_151125165752.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2589, 'in consequence of', '/ɪn ˈkɑːnsəkwəns əv/', 'in consequence of.mp3', 'phr.因为...的缘故', '86a3313bf0db9d91255786564d69d6b6.jpeg', '', 'He lost a lot of money in consequence of the stock market crash.', '由于股市崩盘，他损失了很多钱。', '99f6c52eeb107f0b305385182000c3b0.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2590, 'inn', '/ɪn/', 'inn.mp3', 'n.客栈，小旅馆', 'b59940820b95234f1a3136db708543ec_192447_1532932021.jpeg', 'd_24_7929_0_4_20150808225244.png', 'This traditional inn is surrounded by trees.', '这个传统的小旅店被绿树环绕。', '5bbe03b69ef2dab43989a93cef1b6c2c_19132_1554715601.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2591, 'insist', '/ɪnˈsɪst/', 'insist.mp3', 'v.坚持要求；坚持认为', 'i_1_5169_0_4_160323150626-gigapixel-scale.jpg', 'd_24_5169_0_3_20150808224006.png', 'His mother insists that he should put on his warm pants.', '男孩的妈妈坚持要他穿秋裤。', 'e4b5859d48b9dc19_1266883115994557396_250207.mp3', 'in加强 + sist站立 → 一直站 → insist坚持；硬要', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2592, 'inspire', '/ɪnˈspaɪər/ ', 'inspire.mp3', 'v.激励，鼓舞；激发灵感', '9190a4d66476fd1950a4322306c6a156_71505_1705470532.jpeg', '', 'My father inspired my confidence to become an astronaut from an early age.', '父亲从小就激发了我成为宇航员的信心。', '8733cdbe1ec71aae_1266883493312572176_250207.mp3', 'in进 + spir呼吸 + e强调 → 吸气进去，引申为鼓励 → inspire鼓励', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2593, 'instance', '/ˈɪnstəns/', 'instance.mp3', 'n.例子，实例，事例', '27883823633fe4e278d2b50584f992ec_199158_1585378030.jpeg', '', 'Earthquakes', '地震在一些情况下可能是毁灭性的，但在另一些情况下则影响较小。', 'b7d467580c26437e73b57d24d8b7c175_48960_1586846210.mp3', 'in=inside在里面 ＋ st=stand站立 ＋ ance构成名词：表性质、状况等 → 站在里面，属于某事物内，以身为例 → instance例子', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2594, 'intermediate', '/ˌɪntərˈmiːdiət/', 'intermediate.mp3', 'adj.中间的；  n.媒介；  v.调解，干涉', '7c93f147d1b8e50b7c56693b6062660f_63621_1566960762.jpg', 'd_107_4705_0_2_20150809010302.png', 'The toy in the middle is of intermediate size.', '中间的物品尺寸适中。', '89c170d246315e7d614c9e73b91290ec_14936_1626251230.mp3', 'inter在…之间，相互 + medi中间 + ate做、造成 → intermediate中间的；中级的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2595, 'invent', '/ɪnˈvent/', 'invent.mp3', 'v.发明', '6aa1d295427c83587053cddc73a0d3b6_38237_1588737464.jpeg', 'd_24_6721_0_3_20150808224734.png', 'He invented a pair of special shoes which allowed people to walk on water.', '他发明了一双特殊的鞋子，人们可以穿着它在水上行走。', '876266d718a1c74a_1266883370429209230_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2596, 'jam', '/dʒæm/', 'jam.mp3', 'n.果酱；  v.（使）阻塞，使塞满', 'i_1_4789_0_5_150926150030-gigapixel-scale.jpg', 'd_24_4789_0_3_20150808223552.png', 'She spread some jam on the bread.', '她给面包涂上了果酱。', 'sa_1_4789_0_5_151017113346.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2597, 'jump', '/dʒʌmp/', 'jump.mp3', 'v.跳；暴涨', 'f780174e22b5de9fb4df4c29103c73be_36780_1736306962.jpg', 'd_71_17206_0_3_20150809014157.png', 'She was so happy that she jumped for joy.', '她高兴得都跳起来了。', 'f7kalhduvet2s3e7htjed6djq27ukv2d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2598, 'lay aside', '/leɪ əˈsaɪd/', 'lay aside.mp3', 'phr.把……搁置一旁', 'dba3aa636a35fab41ddcc84732289551.jpg', '', 'He finished the coffee and lay aside the cup.', '他喝完了咖啡，把杯子放在一边。', 'us_He_finished_20241009154837870_5a3ab9f00138e69f38a0.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2599, 'leave alone', '/liːv əˈloʊn/', 'leave alone.mp3', 'phr.不干涉', 'fb4fd24650807322eb0da8f6a642843e.jpg', '', 'His parents leave him alone in order to concentrate on his study.', '为了让他能专心学习，他的父母让他独自一人。', 'us_His_parents_20241009154405665_ff909367e0ea127c1b85.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2600, 'length', '/leŋkθ/ /leŋθ/ ', 'length.mp3', 'n.长度', 'beaeb415ec7f1553af7d891b7de1e384_186268_1535009520.jpeg', 'd_24_5006_0_4_20150808223817.png', 'The ruler is 15 cm in length.', '这把尺子长15厘米。', 'us_The_ruler_20250707163606510_269a16c1f3b7b382a8e7.mp3', 'leng长 + th名词后缀 → length长度', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2601, 'lessen', '/ˈlesn/', 'lessen.mp3', 'v.减轻；减少', '3_0_20170930071905_1885_c-gigapixel-scale.jpg', 'd_103_15469_0_3_20150809034738.png', 'Let\'s lessen the volume before our neighbors come over.', '我们把音量调小点吧，不然邻居会来敲门的。', '3_0_20170930071905_13655_c.aac', 'less减少 + en动词后缀 → lessen减少，减轻', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2602, 'liable to', '/ˈlaɪəbəl tu/', 'liable to.mp3', 'phr.很可能会发生的，可能性很大的', '032dd6b8e88e5d18eda201daf2df0071.jpeg', '', 'Footballers are liable to get injured if they don\'t warm up before a match.', '如果足球运动员不做赛前热身，他们很有可能会受伤。', '68a9a1d22c3948f37748797d80a4158f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2603, 'library', '/ˈlaɪˌbreri/', 'library.mp3', 'n.图书馆，藏书室', '2f71d254635174fa748b9a8f1567b95d_88726_1534229380.jpeg', 'd_24_15938_0_4_20150808230916.png', 'We can find many books in the library.', '我们可以在图书馆找到很多书。', '1a5d4e2c31951eb8_1266798143512730320_250123.mp3', 'libr表示书 + ary构成名词，表示与...有关的地方 → library图书馆', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2604, 'lost', '/lɔːst/', 'lost.mp3', 'adj.迷路的；失去的，失败的', '20120507_04_21_02_52-manual-scale.jpg', 'd_16_11056_0_2_20150809000005.png', 'Where are we? I think we might be lost.', '我们现在在哪儿？我想我们好像迷路了。', 'sa_13_11056_0_2_20150808202801.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2605, 'main', '/meɪn/', 'main.mp3', 'adj.主要的，最重要的；  n.输电干线，总管道', '3_0_20170707160209_52330_c-gigapixel-scale.jpg', 'd_24_18888_0_3_20150808235854.png', 'The main stream of this river leads to the sea.', '这条河的干流通向大海。', '9f9wf2ud7rhh5r3725d7lygepcglza2e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2606, 'maintain', '/meɪnˈteɪn/', 'maintain.mp3', 'v.保持，维持', 'i_1_3893_0_3_20150808122022-gigapixel-scale.jpg', 'd_1_3893_0_3_20150808122022.png', 'It\'s so hard to maintain this position for a long time!', '保持这个动作这么久太难啦!', '85a097ee9c1587981102f3ab535f990b_21205_1619146858.mp3', 'main手 + tain拿 → 用手拿住 → maintain维持', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2607, 'manual', '/ˈmænjuəl/', 'manual.mp3', 'adj.手工的；手的；手动的；  n.手册；指南，说明书', 'ced5c4f94b266eb63c6a20ec60b1ec40_226036_1727580681.jpg', 'd_1_9744_0_2_20150808131441.png', 'He enjoys doing manual work in his garden on weekends.', '他喜欢周末在花园里做手工活。', 'us_He_enjoys_20240929112149225_8990d96d86a9ca70cf2d.mp3', 'manu手 + al形容词后缀 → manual手工的；手册', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2608, 'match', '/mætʃ/', 'match.mp3', 'n.比赛；婚姻，配偶；  v.（使）相配，配对', '5ac5d0bc48b8c1cdee2c4d91ca96e11b_100360_1584684796.jpeg', 'd_24_7103_0_3_20150808224926.png', 'No. 10 is a real fan-favorite who works tirelessly every match.', '10号球员是球迷的最爱，每场比赛他都不知疲倦地踢球。', '61d3d75a61c998d2d0c270da3292c544_46376_1584684793.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2609, 'mental', '/ˈmentl/', 'mental.mp3', 'adj.精神的', '633b5ab6f12b72238cdfc014092d1fd4_119407_1732165351.jpg', 'd_24_7910_0_4_20150808225216.png', 'He is seeing a doctor for his mental health.', '他因精神健康问题正在看医生。', 'us_He_is_20241121114157714_667ddea03aa8aaccf695.mp3', 'ment思考，神智 + al...的 → mental精神的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2610, 'merely', '/ˈmɪrli/', 'merely.mp3', 'adv.只是，仅仅，只不过', '8e10ae7bcaa25b580de65d4d2765892e_85992_1565342500.jpg', '20130307_16_02_04_960.png', 'Don\'t worry. It\'s merely a minor injury.', '别担心。只是一点轻伤。', 'cf295777c172ac9b5761ef1393de3b52_17914_1624341995.mp3', 'mere仅仅 + ly……的 → adv.仅仅，只不过', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2611, 'mistake', '/mɪˈsteɪk/', 'mistake.mp3', 'n.错误，过失；  v.误解，弄错', 'daf4bcaa4ff8c488d8997729123e6a2b_178402_1577954453.jpeg', 'd_78_13451_0_4_20150808234924.png', 'The little boy made a mistake in his math homework.', '这个小男孩在数学作业中犯了一个错误。', 'adc180aa0f5e31ea_1266883115747552208_250207.mp3', 'mis错误，坏 + take拿 → 拿错 → mistake错误', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2612, 'model on', '/ˈmɑdl ɑn/', 'model on.mp3', 'phr.仿效(仿制)', 'fc364057af778d2e5a40e7172c3f3eda.jpg', '', 'Children will often model their behavior on that of their teacher.', '孩子们常常会模仿老师的行为。', '9c36f7969c40ca3bf2420e4fc1f55c57_56559_1599534178.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2613, 'more or less', '/mɔːr ɔːr les/', 'more or less.mp3', 'phr.或多或少', '1426493180397.jpg', '', 'The net weight of this package is', '这个包裹的重量在500克左右。', 'sa_16_18666_0_2_20150809015834.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2614, 'murder', '/ˈmɜːrdər/', 'murder.mp3', 'n.谋杀，凶杀；  v.谋杀，凶杀', 'b1e077317a07a310c6748be24733c5a9_166522_1534153101.jpeg', '', 'The ox chef was arrested for murder by the chicken policeman.', '牛厨师因为谋杀而被鸡警察逮捕。', 'us_The_ox_20250117133223822_96d4416b8f4fc2472235.mp3', 'murd死 + er → murder谋杀', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2615, 'nationality', '/ˌnæʃəˈnæləti/', 'nationality.mp3', 'n.国籍；民族', '97c2756054a47ca5dd7f93e5e17e0b2e_66285_1565678122.jpg', '83827331ed03d861e13803879870496a_33816_1551252433.png', 'People of all nationalities come together for the Olympic Games.', '所有国家的人们为奥运会欢聚一堂。', 'p659te8xjvnfdj8ws3b89lu3aawp2vvn.mp3', 'national国家的 + ity名词后缀；性质 → nationality国籍', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2616, 'obtain', '/əbˈteɪn/', 'obtain.mp3', 'v.获得，赢得，取得', '493c6425a0f51b02ee4826f6607e33ec_164791_1732002042.jpg', 'd_16_5559_0_2_20150808225439.png', 'The policeman is obtaining evidence.', '这个警察正在取证。', '812a11a53d5d512b_1266883485797014122_250207.mp3', 'ob向前 + tain抓 → obtain获得', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2617, 'officer', '/ˈɑːfɪsər/', 'officer.mp3', 'n.警官；官员；高级职员；干事', 'i_13_17718_0_2_20150808204954-gigapixel-scale.jpg', 'd_24_17718_0_3_20150808233317.png', 'He\'s a friendly police officer.', '他是一个和善的警察。', 'us_Hes_a_20250630143029390_4f9beaabe4a536b9ad55.mp3', 'office办公室 + er表人 → 坐办公室的人 → officer警官，官员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2618, 'on behalf of', '/ɔn bɪˈhæf ɑv/', 'on behalf of.mp3', 'phr.代表…...，为了…...', 'c7cc5f685b5c1f16d0689f6c79d08dbc_48792_1701683296.jpg', '', 'The man spoke on behalf of the lion.', '这个男人代表狮子发了言。', 'us_The_man_20241125140048616_877fa59057422fe56058.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2619, 'once again', '/wʌns əˈɡen/', 'once again.mp3', 'phr.再一次', '3_0_20170709071325_58716_c.jpg', '', 'Yay! I won! Yay! I won once again!', '耶！我赢了！耶！我又赢了一次！', '3_0_20170709071325_94732_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2620, 'orange', '/ˈɔːrɪndʒ/', 'orange.mp3', 'n.橘子，橙子', '32960930cd3c3482bd5d4a1b7528df74_81347_1575012891.jpeg', 'd_24_18148_0_4_20150808235019.png', 'An orange a day will give you all the vitamin C you need.', '一天一个橘子可以补充你所需的维生素C。', '51e5146ba9ba85fc_1266763312352897890_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2621, 'orient', '/ˈɔːrient/', 'orient.mp3', 'v.定……的方位；  n.【the Orient】东方', '15dc6f4c5b1254ca509d3fd31ae736a4_69391_1700013514.jpeg', '20140718_08_04_21_501_v3.png', 'I used a compass to orient myself.', '我用指南针来帮我确定方向。', 'us_I_used_20231115095840322_aaec886f3a8efd88e9d8.mp3', 'ori升起，开始 ＋ ent形容词后缀 → [太阳]升起的 → orient东方的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2622, 'outcome', '/ˈaʊtkʌm/', 'outcome.mp3', 'n.结果，后果', '160a1afdc0a7109b4c15f02088bba848_147397_1731403614.jpg', 'd_107_4762_0_2_20150809010612.png', 'The outcome of the boxing game was a draw.', '拳击比赛的结果是个平局。', 'us_The_outcome_20240131142940501_61a833a88c52fba1b505.mp3', 'out出 + come来 → outcome结果', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2623, 'outstanding', '/aʊtˈstændɪŋ/', 'outstanding.mp3', 'adj.杰出的，出众的', '76a99aa0567294ca72ce398579cafc54_77436_1623739453.jpg', 'd_107_6134_0_2_20150809015029.png', 'He is an outstanding example of entrepreneurs.', '他是企业家中的杰出代表。', 'bd2259ea9e1e476abc5eeb227475df8f_17287_1564994260.mp3', 'outstand突出 + ing形容词后缀 → outstanding突出的，杰出的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2624, 'owe to', '/o tu/', 'owe to.mp3', 'phr.把……归功于某人', '8c95a918e8ebd22a7af6b718dce6efb3.jpg', '', 'We owe our success to our education.', '我们将成功归功于我们所接受的教育。', 'b4762fb48e81853a_1266883322679765898_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2625, 'pale', '/peɪl/', 'pale.mp3', 'adj.苍白的，灰白的；  v.变苍白', '5b18c212e872343083a57b968652b656_46127_1731894283.jpg', 'd_24_5720_0_3_20150808224313.png', 'Recent stress from work left him pale.', '近期的工作压力使他脸色苍白。', 'tkrfjwuvct99ykc3xnkldkspc36p5a2l.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2626, 'personnel', '/ˌpɜːrsəˈnel/', 'personnel.mp3', 'n.员工，人员', '9dfbe5e981740ff63d9a2969ac1c43b2_162150_1558593389.jpeg', 'd_107_3940_0_2_20150809003615.png', 'All of the personnel within the business are busy doing their work.', '公司里所有的员工都忙着做自己的工作。', 'fb32c511bb6f5e18ef5ea71ad488b9c3_30870_1558593385.mp3', 'personn=person人 + el表名词 → 全体人员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2627, 'pill', '/pɪl/', 'pill.mp3', 'n.药丸，药', 'i_1_6806_0_6_150924173826-gigapixel-scale.jpg', 'd_24_6806_0_3_20150808224804.png', 'The woman is taking some pills as she is ill.', '这个女人因为生病了，正在服用一些药丸。', '6a10f317dee6bb960c1ee2c2732ae6ed_16189_1625734263.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2628, 'plate', '/pleɪt/', 'plate.mp3', 'n.盘子，碟子；  v.电镀', '3_0_20160520172838_84572_c-gigapixel-scale.jpg', 'd_24_16647_0_4_20150808231752.png', 'I can put much food on this big plate.', '我可以在这个大盘子里放很多食物。', 'rlr3jqz2cf43nqyde8umzhrbxrgx33sw.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2629, 'platform', '/ˈplætˌfɔrm/ ', 'platform.mp3', 'n.站台；讲台', '3_0_20170608071028_7395_c-gigapixel-scale.jpg', 'd_24_3984_0_3_20150808223424.png', 'The train is passing platform 4.', '列车正在经过4号站台。', '8tdrw4xdsdhugehue7cgesfp3k8c8f3d.mp3', 'plat平坦 + form形状 → 形状平的地方 → 平台，月台', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2630, 'portion', '/ˈpɔːrʃn/', 'portion.mp3', 'n.一部分；  v.把……分成若干份', '21bf5419fa37014de8ecd82e9bc798fd_181508_1541649265.jpeg', 'd_1_4175_0_2_20150808122459.png', 'Every month the couple manage to save a small portion of their salaries.', '这对夫妇每个月都设法从他们的工资里省下一小部分钱。', 'e46b8f0407d7ef61_1266763523600264024_250117.mp3', 'port + ion名词后缀 → portion一部分', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2631, 'possess', '/pəˈzes/', 'possess.mp3', 'v.拥有，占有；缠住，迷住', 'cf2a9d8f9f4b864f9a765d244690cfb0_293039_1700127402.jpg', '', 'She finally possesses an apartment of her own.', '她终于拥有了属于自己的公寓。', '7be11dc30fb6e921_1266883374365301288_250207.mp3', 'pos有权力的 + sess坐下 → possess拥有', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2632, 'poverty', '/ˈpɑːvərti/', 'poverty.mp3', 'n.贫困，贫穷；贫乏', '8d2ed5ece53be2d7b7b8e794852552cd_203286_1624006857.jpg', 'd_1_4384_0_3_20150808122712.png', 'Many people live in poverty nowadays.', '现今有很多人生活在贫困之中。', 'b08793671ee1a084fca07298ea9b7f38_13682_1538714216.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2633, 'precaution', '/prɪˈkɔːʃn/', 'precaution.mp3', 'n.预防措施', 'i_1_8567_0_3_20150808130902-gigapixel-scale.jpg', '20130509_20_57_41_694.png', 'We wear masks as a precaution against catching a cold.', '我们戴口罩来预防感冒。', 'a1f11af13b13ccb2_1266883625305746196_250207.mp3', 'pre…前的，预先 + caution小心 → 预先小心 → precaution预防措施', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2634, 'prejudice', '/ˈpredʒədɪs/', 'prejudice.mp3', 'n.偏见，成见；损害，侵害；  v.使抱有偏见', '6a06b6b06aaaf2353174274bc196a294_196878_1563419519.jpeg', '', 'The other elephants held a prejudice against him because of his giant ears.', '其他大象因他的大耳朵而对其抱有偏见。', 'ec1375bf8c6a1c190b87f04c75c94845_28415_1563419765.mp3', 'pre预先 + judice判断 → 预先判断 → 偏见', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2635, 'previous', '/ˈpriːviəs/', 'previous.mp3', 'adj.先前的；早先的；过早的', '76bc1a9d55a841ef0b372cd27b98484c_100639_1584611467.jpeg', '20140926_21_29_01_378_v3.png', 'People no longer use the old fashioned devices used in previous times.', '人们不再使用以前的老式设备。', 'd01e35a2abea2bef_1266883369351535220_250207.mp3', 'pre以前 + vi路[引申为走] + ous……的 → 以前走过的 → previous先的，前的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2636, 'profit', '/ˈprɑːfɪt/', 'profit.mp3', 'n.利润，盈利；益处；  v.得益，有益于', '11022b19f4d262c53eeedcf8367e10da_89573_1731911198.jpg', '20121227_14_01_52_317.png', 'Her business is finally turning a profit.', '她的生意终于开始盈利了。', 'e307e1c1cd2c1333_1266883628960537208_250207.mp3', 'pro很多… + fit做 → 做很多 → profit利润，收益', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2637, 'propose', '/prəˈpoʊz/', 'propose.mp3', 'v.提议；  v.求婚', '60c9db0e3631290a31d92f74ed597007_384844_1705030625.jpg', 'd_1_3872_0_3_20150808122004.png', 'He sincerely proposed a date', '他真诚地提议约会，希望能与女孩一起迎接新年。', 'us_He_sincerely_20240112113711058_a21743a275dd782c0264.mp3', 'pro向前 + pose放置 → 向前呈，呈出 → propose提出，提议', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2638, 'prosperity', '/prɑːˈsperəti/', 'prosperity.mp3', 'n.繁荣，兴旺，发达', 'b58200b6e39eaa691682bf6d33c1099f_101184_1595917984.jpeg', 'd_107_6736_0_2_20150809020847.png', 'The prosperity of the city is evident from this busy nighttime scene.', '这忙碌的夜景显示着这座城市的繁荣。', '9a144534214851f25519b0a4f1852291_46462_1595917982.mp3', 'prosper繁荣 + ity表名词 → prosperity繁荣昌盛', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2639, 'protection', '/prəˈtekʃn/', 'protection.mp3', 'n.保护，防卫', '3_0_20170608072233_23603_c-gigapixel-scale.jpg', 'd_93_13853_0_4_20150809002155.png', 'Everyone should get involved in environmental protection.', '每个人都应该投身到环境保护工作中来。', 'cqpv4unvm8ytdc77znrvxbuf6t8yrbvp.mp3', 'protect保护，防止 + ion表名词 → protection保护', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2640, 'pull in', '/pʊl ɪn/', 'pull in.mp3', 'phr.停车', 'b48d70db6ff86be827052be56616d9f8_145479.jpg', '', 'The truck driver decided to pull in at the side of the road.', '这个卡车司机决定靠边停下。', '17a0f66380ef4d8f6a8771c31d4f9312_41659.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2641, 'purpose', '/ˈpɜːrpəs/', 'purpose.mp3', 'n.目的，意图；  v.打算', '63c3a68c7faf3b7ee3cef4b56dcc7572_55633_1732866578.jpg', 'd_24_10951_0_3_20150808230456.png', 'His purpose for exercising is to get more muscles.', '他健身的目的是为了练出更多的肌肉。', 'us_His_purpose_20241009164000493_432914530fb80994f6fe.mp3', 'pur始终 + pose放 → 始终放的东西 → purpose目的，意图', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2642, 'purse', '/pɜːrs/', 'purse.mp3', 'n.钱包（尤指女用的），小钱袋，手袋', 'i_1_19109_0_3_20150808132541-gigapixel-scale.jpg', 'd_24_19109_0_4_20150809000640.png', 'This purse holds some coins.', '这个钱包装了一些硬币。', '46ecc48f06815aff_1266883197518830132_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2643, 'quarter', '/ˈkwɔːrtər/', 'quarter.mp3', 'n. 四分之一； 一个季度； 一刻钟', '3_0_20170928071143_23759_c-gigapixel-scale.jpg', 'd_24_10248_0_3_20150808230426.png', 'This stopwatch shows that a quarter of a minute has passed.', '这块秒表显示已经过去了十五秒。', '3_0_20170928071143_33992_c.aac', 'quart四 + er名词后缀 → quarter四分之一；一刻钟', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2644, 'rare', '/rer/', 'rare.mp3', 'adj.（肉）半熟的；罕见的，难得的', 'a6ce9effe8d305943cff8dcc403f02eb_92548_1562142193.jpeg', 'd_16_7925_0_2_20150808232140.png', 'He likes eating rare steak', '他喜欢吃那种中间呈血红色的半熟牛排。', '08139c26171f4100670540a803dcbc05_44976_1562142187.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2645, 'refresh', '/rɪˈfreʃ/', 'refresh.mp3', 'v.使恢复精神', '77ac65d6345f55be6bfa6ab883ed7a76_84044_1699350218.jpg', 'd_16_8625_0_4_20150808233300.png', 'The long sleep had refreshed her.', '一场酣睡使她又精力充沛。', 'us_The_long_20231107174350695_4e12306bdfa1a3d31a96.mp3', 're重新，再 + fresh新鲜 → refresh恢复精神，提神', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2646, 'relate', '/rɪˈleɪt/', 'relate.mp3', 'v.相关，有联系；讲述', 'e292c8f55b9a8ba9064be82ad60c3568_183367_1573787504.jpeg', '', 'The doctor said my lung problems relate to my smoking habit.', '医生说我肺部的问题和我吸烟的习惯有关。', '2eff2ee527c24316430414110cc86d29_48848_1574648969.mp3', 're回 + late拉 → 拉回来 → relate叙述，使联系', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2647, 'release', '/rɪˈliːs/', 'release.mp3', 'v.释放；免除（责任、债务等）；发布，发行；  n.解除；释放；发布', '3eef1efe6e401233c0597b1408435c1f_115338_1588089929.jpg', 'd_1_5549_0_2_20150808123948.png', 'The prisoner was released after his sentence was complete.', '这个囚犯服完刑后被释放了。', 'us_The_prisoner_20241009154724630_2a2c66d4652fa97a76d3.mp3', 're向后 + lease松开 → 释放，发布', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2648, 'residence', '/ˈrezɪdəns/', 'residence.mp3', 'n.住宅', '212bc32fc82c4bca532984f8a2b52743_34349_1585058160.jpeg', 'd_1_4039_0_3_20150808122248.png', 'Their residence is equipped with a large swimming pool.', '他们的住宅配有一个很大的游泳池。', '3b74fdfb79f646368e7004ed3da033f4_49144_1585058157.mp3', 're再 + sid坐 + ence名词后缀 → residence居住；住宅', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2649, 'reveal', '/rɪˈviːl/', 'reveal.mp3', 'v.揭示；透露；显示', 'e6197b53774b58958cecb857448dd008_160677_1564653118.jpeg', '20130510_18_35_09_476.png', 'He opened the curtain to reveal a landscape painting.', '他掀开帘布，露出一幅风景画。', 'lrn72rzxr3wzsn8yfyw7cckllwbcjmtm.mp3', 're相反 + veal=veil盖上 → 与掩盖相反 → reveal揭露', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2650, 'ring off', '/rɪŋ ɔːf/', 'ring off.mp3', 'phr.挂断电话，停止讲话', '75aad7093a6d3e834d09706ac593c6b5_99583_1579337603.jpeg', '', 'He ended the conversation angrily and rang off.', '他生气地结束谈话，挂断了电话。', 'd73593d5e988f0cf403c3a316363b7d5_41278_1579337600.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2651, 'rush', '/rʌʃ/', 'rush.mp3', 'v.冲，奔；匆忙做；  n.冲，急速行进；（交通）繁忙时段', 'i_1_6206_0_3_20150808124827-gigapixel-scale.jpg', 'd_24_6206_0_3_20150808224525.png', 'I\'ll have to rush to the canteen; otherwise there\'ll be nothing left.', '我得冲向食堂，不然什么吃的都没有了。', '2889856d722926ba2032eb27a70ff485_25750_1619143141.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2652, 'salesman', '/ˈseɪlzmən/', 'salesman.mp3', 'n.男推销员，男售货员', '9160ff0333619e65a33957d4f6b33e57_84627_1573790500.jpeg', '20130308_21_36_35_119.png', 'The salesman is introducing the latest car to his customer.', '这个推销员在向他的顾客介绍最新款汽车。', '00ec0a309965de465e4a4cc65626fb45_44960_1574674190.mp3', 'sales销售 + man人 → salesman售货员，推销员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2653, 'sandwich', '/ˈsænwɪtʃ/', 'sandwich.mp3', 'n.三明治，夹肉面包；  v.夹入，挤进', '20120527_05_36_34_913-gigapixel-scale.jpg', 'd_96_14054_0_4_20150809014419.png', 'The kids were really happy when I made them each a sandwich for lunch.', '当我给孩子们每人做了一个三明治当午餐时，他们好开心。', 'sa_65_14054_0_4_20150809014515.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2654, 'shade', '/ʃeɪd/', 'shade.mp3', 'n.树荫，阴凉处；遮光物；  v.遮蔽（光线）', '3_0_20170714071509_13175_c-gigapixel-scale.jpg', 'd_16_9810_0_2_20150808234818.png', 'I am standing in the shade of a tree. It\'s cooler here.', '我站在树荫下，这儿凉快些。', '3_0_20170714071509_28889_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2655, 'simply', '/ˈsɪmpli/', 'simply.mp3', 'adv.简单地；仅仅，只不过', '3_0_20170930071709_23802_c-gigapixel-scale.jpg', 'd_105_11341_0_2_20150809061842.png', 'My room is just simply furnished because I\'m not at home very often.', '我的房间陈设简单，因为我不常在家。', '3_0_20170930071709_32257_c.aac', 'simpl=simple简单的 + (l)y表副词 → simply简单地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2656, 'sorrow over', '/ˈsɑːroʊ ˈoʊvər/', 'sorrow over.mp3', 'phr.为…悲伤', '02208ab4c2b3a22fbc8ebf3dc9ff2083.jpeg', '', 'She expressed her sorrow over her husband\'s death.', '她为她丈夫的死悲痛万分。', '6d712775f549175bd021b759f9b65e92.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2657, 'spare', '/sper/', 'spare.mp3', 'adj.备用的；多余的，空闲的；  n.备用品；  v.抽出，腾出', 'i_1_4499_0_4_20150808122825-gigapixel-scale.jpg', 'd_16_4499_0_2_20150808224300.png', 'Prepare a spare pen for your exam.', '为考试准备一支备用的笔。', 'sa_11_4499_0_7_160326112158.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2658, 'stable', '/ˈsteɪbl/', 'stable.mp3', 'adj.稳定的；安定的；  n.马厩', '9528ee0732a5b080f6639587bbc6e125_163875_1595917390.jpeg', '20141012_04_10_18_655_v3.png', 'The price finally became stable after some ups and downs.', '物价在一阵起伏后终于变稳定了。', '9vkx842fn6259un7gunppdjvxd4x8w6j.mp3', 'st站立 + able能…的 → 能站的 → stable稳定的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2659, 'storm', '/stɔːrm/', 'storm.mp3', 'n.暴风雨，暴风雪；  v.横冲直撞；突袭', 'ad048a4aed2205491674d72fe117722b_204232_1578562199.jpeg', '20130130_16_18_58_159.png', 'The ship was hit by a storm at sea.', '这艘船在海上遭遇了暴风雨的袭击。', '4cde4071683bd46c_1266883378296368096_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2660, 'stream', '/stri:m/', 'stream.mp3', 'n.小河，溪；流；  v.流出', 'da644853ac0d62e71d80a49d6fd70d95_93323_1565254618.jpg', 'd_100_14375_0_4_20150809032644.png', 'There is a small stream running through the forest.', '有一条小溪从森林中流过。', '630f9b5881b41b13_1266883115132496836_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2661, 'suicide', '/ˈsuːɪsaɪd/', 'suicide.mp3', 'n.自杀', '1ae5622a695dbfd68f58735f75e91808_199663_1564370490.jpg', 'f7982fa6e370ebb167dbab5b910712ae_26861_1551252537.png', 'To avoid being cooked', '为了不被做成食物，鸡蛋从边上跳下自杀了。', 'f1696c3c9cafee50aae063528bc80588_34898_1564370490.mp3', 'sui自己 + cid杀 + e行为 → suicide自杀', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2662, 'summarize', '/ˈsʌməraɪz/', 'summarize.mp3', 'v.作概括；作总结', 'i_103_5234_0_3_20150809013632-gigapixel-scale.jpg', 'd_107_5234_0_2_20150809011854.png', 'I don’t want to read the whole thing. Could you just summarize the book for me?', '我不想再看这个东西了，你能就帮我概括一下这本书吗？', 'sa_103_5234_0_3_20150809013632.aac', 'summar总，加 + ize动词后缀 → summarize概括', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2663, 'sunlight', '/ˈsʌnlaɪt/', 'sunlight.mp3', 'n.阳光，日光', 'i_1_6701_0_4_151119170249-gigapixel-scale.jpg', 'd_24_6701_0_3_20150808224724.png', 'The sunlight brightens the green field.', '阳光照亮了绿地。', '48xm6zab4glbex5p6q5v64y44udg3yrt.mp3', 'sun太阳 + light光亮 → sunlight日光', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2664, 'sunrise', '/ˈsʌnraɪz/', 'sunrise.mp3', 'n.日出；朝霞；  adj.新兴的', 'i_1_9359_0_4_150926144459-gigapixel-scale.jpg', 'd_24_9359_0_3_20150808230218.png', 'I got up early today and saw a beautiful sunrise.', '我今天早起看了美丽的日出。', 'sa_1_9359_0_4_151017115124.aac', 'sun太阳 + rise升起 → 太阳升起来 → sunrise日出', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2665, 'superior to', '/sʊˈpɪriər tu/', 'superior to.mp3', 'phr.高于……，优于……，更胜一筹', '50c37f1979214a56c5d0a01822957a31_103205_1701677590.jpg', '', 'Do you feel superior to me just because you\'re taller?', '因为你比我高，你就有优越感了吗？', 'us_Do_you_20231204161313082_a882036aff6ca2a4c32c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2666, 'tale', '/teɪl/ ', 'tale.mp3', 'n.故事，传说', 'i_13_16655_0_2_20150808204242-gigapixel-scale.jpg', 'd_24_16655_0_4_20150808231821.png', 'He stayed up late at night just to finish reading the tale.', '他晚上熬夜，就是为了能看完这个故事。', 'ltmqmpzygucr9xh5f5hjage87p2wcfab.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2667, 'temporary', '/ˈtempəreri/', 'temporary.mp3', 'adj.临时的', '15a5dda8fea29508ea467c86b3562bd2_219653_1630051295.jpeg', 'd_16_3930_0_2_20150808223830.png', 'The tent on the car is a temporary home for us.', '车顶上的帐篷是我们的临时居所。', 'ypwxa44vrlj9vdra67xvw23vfwc7frrh.mp3', 'tempor时间 + ary形容词后缀 → 有时间性的 → temporary临时的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2668, 'theater', '/ˈθiːətər/', 'theater.mp3', 'n.戏院，电影院，剧场（=theatre）', '3_0_20170713071327_42257_c-gigapixel-scale.jpg', 'd_24_9925_0_4_20150808230339.png', 'The theater quickly emptied when the performance ended.', '表演结束之后，戏院很快就空了。', '3_0_20170713071327_12674_c.aac', 'thea看见 + ter=tron表地点 → theater剧场 ', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2669, 'thief', '/θiːf/', 'thief.mp3', 'n.小偷；窃贼', 'b63a65ad94dcd1e66bd6eea46c69e881_136894_1732265172.jpg', 'd_24_8517_0_3_20150808225759.png', 'A thief is stealing the girl\'s phone.', '一个小偷正在偷这个女孩的手机。', '7be0f6eeef660433_1266883008291384198_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2670, 'tide', '/taɪd/ ', 'tide.mp3', 'n.潮汐；  v.随潮漂流', 'e7b22b6528b7df8871999cf7d61332cc_101902_1587465855.jpeg', 'd_107_4049_0_2_20150809004139.png', 'The tide is going out', '潮水退去了，海滩变得柔软又干净。', 'e9hjl5wu89cnmva5s6upgyehh5v84x2q.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2671, 'training', '/ˈtreɪnɪŋ/', 'training.mp3', 'n.训练，锻炼', '14d20d67efb9b0e06658615bde4d7ddf_128950_1574822869.jpeg', 'd_24_17956_0_3_20150808233732.png', 'He performs strength training in the gym.', '他在健身房做力量训练。', '1dcb2eee7093d5df10671ee2dabc0b53_34888_1574822866.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2672, 'transfer', '/trænsˈfɜr/', 'transfer.mp3', 'v.转移；调任；换乘；  n.转让；转移；汇兑（读作/ˈtrænsfər/）', 'i_1_5539_0_3_20150808123938-gigapixel-scale.jpg', 'd_1_5539_0_3_20150808123938.png', 'The worker transferred the box to another place.', '工人把箱子转移到了另一个地方。', '3_41_20170330175545_59675_c.aac', 'trans横过，越过 + fer带来 → transfer转移', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2673, 'tremendous', '/trəˈmendəs/', 'tremendous.mp3', 'adj.巨大的；精彩的，出色的；惊人的', 'b2eeeed454e16e485cb3e8dadc6e3c23_175458_1573617968.jpeg', 'd_107_4754_0_2_20150809010540.png', 'I feel the tremendous pressure of car and house loans on my shoulders.', '我感觉肩上扛着巨大的车贷和房贷压力。', 'caeb09e24a173730_1266883625913264932_250207.mp3', 'trem颤抖 + end尽头 + ous形容词后缀 → 让人颤抖的 → tremendous可怕的，惊人的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2674, 'trick', '/trɪk/', 'trick.mp3', 'v.捉弄，戏弄；哄骗；  n.恶作剧，诡计，花招', '04c8bf4b9726921f489fcef5e7269e4e_174973_1718594479.jpg', 'd_16_4456_0_2_20150808224245.png', 'He tricked his brother by pretending to be a ghost.', '他假装成幽灵来捉弄他的弟弟。', 'bgqp4qqu8dxc79dae76kmsgnsrkt4m2c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2675, 'turn in', '/tɜːrn ɪn/', 'turn in.mp3', 'phr.上交', '7a6b22ed498b3feb0793c3b950980fa7.jpeg', '', 'He finished the test early and turned it in to the teacher.', '他很早就完成了试卷并交给了老师。', 'wtyr753r9txc7mcv9myxl3bqucbfdda5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2676, 'value', '/ˈvæljuː/', 'value.mp3', 'v.重视；给……定价，鉴定', 'i_103_4913_0_3_20150809011420-gigapixel-scale.jpg', 'd_24_4913_0_4_20150808223639.png', 'Which do you value more—the economy or the environment?', '经济和环境，你更重视哪个呢？', 'sa_103_4913_0_3_20150809011420.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2677, 'wear off', '/wer ɔːf/', 'wear off.mp3', 'phr.逐渐消失，磨灭，损耗', '5_44_185_20170329171008_51413_c.jpg', '', 'He\'s feeling sick again because the drugs are wearing off.', '他因为药效消失而又感觉不舒服。', '5_51_411_20170427195138_96929_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2678, 'whatever', '/wətˈevər/', 'whatever.mp3', 'pron.无论什么；  det.任何事物', '1425461326883-manual-scale.jpg', 'd_24_17996_0_3_20150808234037.png', 'Whatever the weather', '无论什么天气，他都坚持在户外游泳。', 'sa_114_17996_0_2_20150809072448.aac', 'what什么 + ever究竟 → whatever无论什么', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2679, 'wheel', '/wiːl/', 'wheel.mp3', 'n.轮子；  v.旋转', '11336f204d19ea29c5589eb490b0ecc7_100636_1577959377.jpeg', 'd_24_16529_0_3_20150808231541.png', 'The wheels of these bicycles are the same size.', '这些自行车的轮子大小相同。', '0512b6549a2ef665_1266763241754286744_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2680, 'yearly', '/ˈjɪrli/', 'yearly.mp3', 'adj.每年的，一年一度的；  adv.每年，一年一度', 'fbf81b5a70f4e21dc846a14cededcb31_118134_1538760006.jpg', 'd_1_6882_0_2_20150808125618.png', 'The yearly rental of the house is 2', '这房子的年租金是2350美元。', 'cc0670589efcbfecfdada6f40d49138a_20107_1538760058.mp3', 'year年 + ly表副词，每……地 → yearly每年地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2681, 'yield', '/jiːld/', 'yield.mp3', 'v.出产（作物）；  v.弯曲；屈服；让行；  n.收益', 'f9eb056022bc91b8160f30311660fd8a_65965_1565621296.jpg', 'd_1_4011_0_2_20150808122228.png', 'The fields yielded many carrots this year.', '这片土地今年产出了很多胡萝卜。', '6894af0597b0adaabc3a7be26b27ea27_16503_1624073525.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2682, 'youth', '/juːθ/', 'youth.mp3', 'n.青年', '7224aabde80d599cd541b644e8a9058c_197358_1538585325.jpg', 'd_24_7916_0_3_20150808225225.png', 'Youth is the symbol of hope.', '青年是希望的象征。', '1643df2db5bf072a2b4e3a1811efa2fc_8666_1538585331.mp3', 'you青春活力，生命力 + th抽象名词后缀 → youth青春；青年', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2683, 'actually', '/ˈæktʃuəli/', 'actually.mp3', 'adv.实际上', '5f026c2f717fd09b590fbe6692ba6983_155609_1572245298.jpeg', '', 'Mary may appear to be reading', '玛丽看起来像是在看书，但实际上，她正想着食物。', '4a80511668233fe0_1266798137756834404_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2684, 'all at once', '/ɔːl æt wʌns/', 'all at once.mp3', 'phr.同时；突然', 'i_50_20429_0_3_20150809020413.jpg', '', 'He can really do many tasks all at once.', '他真的可以同时做很多事情。', 'sa_50_20429_0_3_20150809020413.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2685, 'anticipate', '/ænˈtɪsɪpeɪt/', 'anticipate.mp3', 'v.期待；提早（做）', 'i_1_10116_0_3_20150808131558-gigapixel-scale.jpg', 'd_107_10116_0_2_20150809024928.png', 'I anticipate him winning the first prize as he is really great!', '我期待他能得第一，因为他真的很棒！', 'sa_1_10116_0_3_20150808131558.aac', 'anti前面 + cip抓 + ate动词后缀 → 开始抓 → anticipate预料；预期的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2686, 'assistant', '/əˈsɪstənt/', 'assistant.mp3', 'n.助理，助手；  adj.助理的，辅助的', 'f4d25e6f372be26e61d3d204124e0a2f_81853_1623738935.jpg', '7db9db0ef235d48e9208bcb3c8c7b234_69453_1551252449.png', 'The businessman has an assistant to help him with his work every day.', '这个商人有一名每天协助他工作的助理。', 'f9550aac23ed4007941a5619601009ff_42872_1603250071.mp3', 'assist援助 + ant名词后缀 → 帮助之人 → assistant助手，助理', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2687, 'at once', '/æt wʌns/', 'at once.mp3', 'phr.立刻', '9629e6bd2ff570890ba2059c6c37b844_79965_1590217396.jpeg', '', 'The dog ran to the door at once when the doorbell rang.', '门铃一响，小狗就立刻跑向门口。', '443f393df5ab6dfc_1266883374451415596_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2688, 'ballet', '/bæˈleɪ/', 'ballet.mp3', 'n.芭蕾舞，芭蕾舞剧', 'i_1_5998_0_4_20150808124638-gigapixel-scale.jpg', 'd_105_5998_0_2_20150809055426.png', 'Miss Elephant\'s dream is to become a ballet dancer.', '大象小姐的梦想是成为一个芭蕾舞者。', '2sxbbe648hwm3w3lgbr3dgvuk3hjurn7.mp3', 'ball舞蹈 + et名词后缀 → 舞蹈 → ballet芭蕾舞', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2689, 'below', '/bɪˈloʊ/', 'below.mp3', 'prep.在……之下；  adv.在（或到）下面', 'below_15917_20231106_199df10f.jpg', 'd_24_15917_0_3_20150808230821.png', 'Most of the iceberg is hidden below the water.', '大部分冰山都隐藏在水下。', '3_0_20170709071350_70086_c.aac', 'be表强调 ＋ low在下面 → below在…下面', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2690, 'billion', '/ˈbɪljən/', 'billion.mp3', 'num.十亿；数以十亿计；大量；  adj.大量的', 'd024e8af3a4fd35ce0829846f7533db9_34912_1573898054.jpeg', 'd_109_7806_0_2_20150809055110.png', 'The baby counted 9 zeros in the number 1 billion.', '这个小孩从10亿这个数字里数出了9个零。', 'bf0939aa42522126_1266883196674747160_250207.mp3', 'bi二 + llion=million百万 → 十亿', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2691, 'capable', '/ˈkeɪpəbl/', 'capable.mp3', 'adj.有本领的，有能力的', 'i_1_15326_0_2_20150808132019-gigapixel-scale.jpg', 'd_1_15326_0_2_20150808132019.png', 'Your penguin is a weightlifter? That must be a very capable bird.', '你的企鹅是个举重运动员？那它一定是一只有本领的鸟。', '28860601d26381a8_1266883319956613944_250207.mp3', 'cap握住 ＋ able形容词后缀，具有某种性质的 → capable有能力的，有才能的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2692, 'certainly', '/ˈsɜːrtnli/', 'certainly.mp3', 'adv.无疑，确定；当然，没问题（用于回答）', '7ed143b6570164bd9c04a50bd381b2d1_97544_1604306903.jpg', 'd_24_10802_0_3_20150808230447.png', 'Every human is certainly born and will certainly die.', '每个人无疑都会经历出生和死亡。', '5854752940bc3b0f_1266883009237768878_250207.mp3', 'certain确实的 + ly…地 → certainly无疑，确定', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2693, 'chain', '/tʃeɪn/', 'chain.mp3', 'n.链条；链子；连锁；  v.用链条拴住；束缚', '2f4ca5d6db141fd130d36e25bee3b14b_118652_1552617873.jpeg', 'd_24_5138_0_3_20150808223941.png', 'The lady\'s bag with a chain is a popular fashion style.', '这个带链条的女包是一种流行的时尚款式。', '6b1b75799a056712c110ff5f1e98d87f_29045_1552617879.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2694, 'charge', '/tʃɑːrdʒ/', 'charge.mp3', 'v.充电，充值；收费；控告；  n.主管；掌管；费用', 'i_5_4729_0_8_160311102342-gigapixel-scale.jpg', 'd_52_4729_0_3_20150809023644.png', 'I finally plugged in my phone and let it charge.', '我终于插上我的手机，让它充电了。', 'us_I_finally_20241009155418166_de7f6b07001000c0dc1e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2695, 'check out', '/tʃek aʊt/', 'check out.mp3', 'phr.结账离开', '50e45bbe6caf6d171b13c8f941aae311_98043_1600243843.jpg', '', 'They\'re checking out of the hotel.', '他们正在办理退房结账。', '3_0_20170721071544_30288_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2696, 'claim for', '/kleɪm fɔːr/', 'claim for.mp3', 'phr.要求支付……的费用', '8cdbd505fbb37b7e9a97cfe0de10076e.jpeg', '', 'I want to make an insurance claim for the damage to my car.', '我想对我的汽车遭受的损失提出保险索赔。', '6c773cd1be45ec8f94c7915404dabbf0.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2697, 'concentrate on', '/ˈkɑːnsəntreɪt ɑːn/', 'concentrate on.mp3', 'phr.聚精会神，集中思想', 'be4ebe55d966dffec49434186665f6d0.jpg', '', 'Although it\'s noisy', '尽管很吵，他仍然可以聚精会神地工作。', '1f9d2fa9976819c73a676c6c9fe93592.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2698, 'concerning', '/kənˈsɜːrnɪŋ/', 'concerning.mp3', 'prep.关于', '420c028f3bad65c453dbb488739f8d9b_198901_1703481082.jpg', '', 'The book gives lots of useful information concerning Botany.', '这本书介绍了许多关于植物学的有用信息。', 'us_The_book_20231225131350112_065449a1d8dc3f4619e0.mp3', 'con共同 ＋ cern搞清 ＋ ing构成介词 → concerning关于', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2699, 'consult', '/kənˈsʌlt/', 'consult.mp3', 'v.咨询', '06c858f611364ebda23b88f6e9b83f53_99582_1584003969.jpeg', 'd_107_3989_0_2_20150809003903.png', 'The couple are consulting the advisor for help.', '这对夫妇正在咨询那位顾问以寻求帮助。', '1652714ed7a6eb59_1266883377929628620_250207.mp3', 'con一起 + sult召集  → 召集到一起（协商事物） → consult咨询', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2700, 'convince', '/kənˈvɪns/', 'convince.mp3', 'v.使确信，使相信；说服', 'bc6bdb78576a93cd1bdecc3112b6e01a_186193_1528080952.jpeg', 'd_16_5731_0_4_20150808225754.png', 'The footprints convinced the wife that it was the cat who made the mess.', '这些脚印使这位太太确信是猫把一切弄乱的。', '6409c5f521037b72_1266883379169504008_250207.mp3', 'con加强 + vinc征服 + e → 彻底征服对方 → convince使确信', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2701, 'couple', '/ˈkʌpl/', 'couple.mp3', 'n.夫妇；一对；  v.配对，连接，结合', 'i_4_17998_0_2_20150808192204-gigapixel-scale.jpg', 'c501352a96305c2540cfa233cd80eef1_36179_1539341483.png', 'The happy couple smiled all throughout their wedding day.', '这对幸福的夫妇在婚礼的一整天都面带微笑。', 'a79b0ca436191af9_1266883008189475710_250207.mp3', 'co一起 ＋ up取到 ＋ le → 联系，连接 →couple恋人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2702, 'cruel', '/ˈkruːəl/', 'cruel.mp3', 'adj.残忍的，残酷的', 'c_20150704_105737_1_715-gigapixel-scale.jpg', '49285a9bdf1fa0c46a46590c08d94221_69265_1539341473.png', 'Don\'t be so cruel to me! I\'m just a watermelon.', '不要对我这么残忍！我只是一个西瓜。', 'b80a216645c8487d_1266883529788009344_250207.mp3', ' ', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2703, 'culture', '/ˈkʌltʃər/ ', 'culture.mp3', 'n.文化；文明；（细菌或细胞）培养；种植；  v.使有教养；培养（细胞、细菌）', '53a3554ce2e56a30abc04666f08e7108_201020_1564627050.jpeg', 'd_24_17719_0_4_20150808233319.png', 'China is a beautiful country with long history and colorful culture.', '中国是一个有着悠久历史以及多彩文化的美丽国家。', 'hzvsqqqvj96tnz8wh29fn98ef6tgpgqd.mp3', 'cult耕种，培养 + ure抽象名词 → [对心灵的]培养 → culture修养；文化', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2704, 'detail', '/ˈdiːteɪl/', 'detail.mp3', 'n.细节；  v.详细说明', '20120507_05_01_42_852-gigapixel-scale.jpg', 'd_1_6948_0_2_20150808125643.png', 'When the leaf is seen up close', '近距离看树叶时，你可以看到很多细节。', 'sa_1_6948_0_2_20150808125643.aac', 'de向下 + tail切割 → detail 细节', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2705, 'drum', '/drʌm/', 'drum.mp3', 'n.鼓；圆桶；  v.击鼓', '0946f0da15712a4470f1a704effd58f6_102784_1750758132.jpg', 'd_24_10247_0_3_20150808230425.png', 'She is playing the drums for the musical show.', '她正在为音乐表演打鼓。', '4qb6ldavrzweapvgauh5gh77nwyfj2sg.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2706, 'efficient', '/ɪˈfɪʃənt/', 'efficient.mp3', 'adj.效率高的；能胜任的', '3_0_20170930071322_2200_c-gigapixel-scale.jpg', 'd_1_4822_0_3_20150808123052.png', 'He\'s very efficient at work', '他工作很高效，能同时处理很多事情。', 'e4bbb10d89a58f15_1266763553478519774_250117.mp3', 'ef出 + fici做 + ent……的 → 能做出事来 → efficient做事有效的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2707, 'employment', '/ɪmˈplɔɪmənt/', 'employment.mp3', 'n.职业；雇用；就业', '8a22856805333727c65948ca6568de80_202399_1580891281.jpg', 'd_1_4952_0_2_20150808123221.png', 'She found employment as an English teacher.', '她找到了一份英语老师的工作。', '5b064711ea7e6160d6cb170488fe6dec_49648_1580891273.mp3', 'employ雇佣 + ment名词后缀 → employment雇佣', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2708, 'empty', '/ˈempti/', 'empty.mp3', 'adj.空的；  v.倒空；腾空', 'i_1_7917_0_2_20150808130137-gigapixel-scale.jpg', 'd_24_7917_0_4_20150808225227.png', 'There are many seats in the meeting room', '会议室有很多座位，但是都是空的。', 'tl4hkgp9acafzuahv3l8fvlkfgjcrae4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2709, 'establish', '/əˈstæblɪʃ/ /ɪˈstæblɪʃ/ ', 'establish.mp3', 'v.建立；确立', '979d47a8dadf832a9d9e1527bd66105d_136756_1524897125.jpeg', 'd_1_3859_0_3_20150808121952.png', 'The two businessmen are trying to establish links.', '这两个商人在试图建立联系。', 'd1fcca343cfbb6144be8d6a6748cbae3_33395_1524897132.mp3', 'e缓音字母，无含义 + stablish使稳固 → establish建立', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2710, 'extend', '/ɪkˈstend/', 'extend.mp3', 'v.伸展，展开；延伸；涉及；扩展', '37b30b655576afc77f3d2150bd31430a_104519_1573896474.jpeg', 'd_107_5608_0_2_20150809013155.png', 'He must extend the ladder to reach the roof.', '为了够得着房顶，他必须把梯子展开。', '8994d63be2acd82516edb8d6b3d4cba4_15249_1626058734.mp3', 'ex出 + tend延伸 → 伸出去 → extend扩张', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2711, 'fall out', '/fɔːl aʊt/', 'fall out.mp3', 'phr.争吵', 'ad79d0f5ea00270ef1570615bfb421cf_34598_1573899589.jpeg', '', 'They fell out and no longer speak to each other.', '他们闹翻了，再也不和对方说话了。', 'bxpp3ugvrbawbl3vazsu8rghhs9u2rvj.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2712, 'fault', '/fɔːlt/', 'fault.mp3', 'n.责任，过错；【地质学】断层；  v.责备，挑错', '3_52_20170617164923_53597_c-gigapixel-scale.jpg', '20141014_23_50_53_92_v3.png', 'It\'s the boy\'s fault that the window was broken.', '窗户破了是这个男孩的错。', 'us_Its_the_20250102095124806_fcb78d51e4b13ddd9176.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2713, 'flower', '/ˈflaʊər/', 'flower.mp3', 'n.花，花卉；  v.开花', '80cc8e4b999664a8f80b3ce842132695_340042_1733116702.jpg', 'd_24_19095_0_3_20150809000526.png', 'There are colorful flowers in that place.', '那里有五颜六色的花。', '6d34e654fff19ce6_1266763240535796608_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2714, 'focus on', '/ˈfoʊkəs ɑːn/', 'focus on.mp3', 'phr.聚焦于；将（注意力）集中', 'c0532e805d9ba551752591a306343d23.jpg', '', 'He is using his camera to focus on the flower to be photographed.', '他正在使用照相机以这朵花为焦点进行拍摄。', 'a2d760f33cac1c068792de94c94bdbbf.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2715, 'forest', '/ˈfɔːrɪst/', 'forest.mp3', 'n.森林，林区', 'a6c0fcf75a109814db7d3a6e1d7fd59e_83858_1574912384.jpg', 'd_24_16628_0_4_20150808231719.png', 'The forest looks beautiful when the sun shines through the trees.', '当阳光穿过树木时，整个森林看起来美极了。', '3b62a7f699cd7f3e_1266883198717352522_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2716, 'foundation', '/faʊnˈdeɪʃn/', 'foundation.mp3', 'n.地基；基金会', 'a73a503fa60b714708289d7d0468eab2_198593_1565692638.jpeg', 'd_107_7492_0_2_20150809021958.png', 'A strong building needs a solid foundation.', '一座坚固的建筑需要有稳固的地基。', '4fec071fdfac40391dff2bb5e3d6f3bf_34886_1565692650.mp3', 'found基础 + ation表名词 → foundation基础，地基', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2717, 'from time to time', '/frəm taɪm tu  taɪm/', 'from time to time.mp3', 'phr.不时地', 'fe65ec3e939d5268ba0156fd622113db_184270_1574145980.jpeg', '', 'I go jogging from time to time.', '我时不时地去慢跑一下。', '4e14a7341e8b9866300e7ab1b24218b1_23698_1574146032.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2718, 'grown', '/ɡroʊn/', 'grown.mp3', 'adj.成年的，成熟的', 'a09be8aa8582b588176bd7b4e38ff81c_106638_1588130154.jpeg', '', 'Even as a grown woman', '即使作为一名成年女性，她也能和孩子们打成一片。', 'ef26b7535da2cf53b686c3ab12874af8_47974_1588130158.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2719, 'handkerchief', '/ˈhæŋkərtʃɪf/', 'handkerchief.mp3', 'n.手帕；方巾', 'aafc345934749930f10c32fa2426bad1_81297_1577952441.jpeg', 'd_24_6805_0_4_20150808224802.png', 'These handkerchiefs have flowers on them.', '这些手帕上有绣花。', 'f3522c7d1f6a0d38_1266883380082027330_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2720, 'hang on', '/hæŋ ɔn/', 'hang on.mp3', 'phr.握住不放', 'eb0174e961fb8663bc6d197616ac45bd_94130_1579595773.jpeg', '', 'She hangs on the rock when she tries to climb up.', '当她试图向上爬的时候，她紧紧抓住了岩石。', 'us_She_hangs_20241015105804435_396b46af0d921c727917.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2721, 'head for', '/hɛd fər/', 'head for.mp3', 'phr.朝...方向去', '11d16968e206f78d8ce4d102f6dd581c.jpg', '', 'When the fire alarm went off', '火警警报响起时，大家都奔向紧急出口。', '4ede76b43bc7608933a02bd46386d60d_34784_1599549916.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2722, 'in advance', '/ɪn ədˈvæns/', 'in advance.mp3', 'phr.提前，预先', '4da735c960dda834728252e37c0259bb.jpg', '', 'He booked his flight tickets in advance.', '他提前订好了飞机票。', '82e3e26789a550fe_1266883378959505928_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2723, 'in brief', '/ɪn briːf/', 'in brief.mp3', 'phr.简单地说', 'dcd2d2275c86369d44950ca353f9b662.jpeg', '', 'It\'s a long letter', '这是一封长信，但简而言之，他拒绝了。', '0ae1276113d82fdf5b94022d097b9338.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2724, 'in vain', '/ɪn veɪn/', 'in vain.mp3', 'phr.徒劳，白费力气', '2e22d0a5d097c705af65c2a1fd856287_299427_1698027878.jpg', '', 'All his efforts to fetch water with such a basket were in vain.', '用这样的篮子打水，他所有的努力都是徒劳。', 'us_All_his_20231023102348665_2cdace75810bafcf1f6d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2725, 'injection', '/ɪnˈdʒekʃn/', 'injection.mp3', 'n.打针；注射，注入', '3625a8a2c66d0b96e5d71ce420a16ffe_169657_1557802677.jpeg', 'd0e5efde1f536414cb66ff2b84d3fe24_24972_1551259028.png', 'The doctor is giving an injection to the patient.', '医生正在给病人打针。', '4twje6jzyrfwjgl6fvl7t9mbkgaqw9tc.mp3', 'inject注射 + ion名词后缀 → injection 注射', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2726, 'interact', '/ˌɪntərˈækt/ ', 'interact.mp3', 'v.交流，互动；互相作用，互相影响', 'e78fffef43f2ca0a10b23b6ed72d287a_198426_1576071188.jpeg', 'd_1_5806_0_3_20150808124433.png', 'During the performance', '在表演过程中，这位美丽的舞者与观众互动，跟他们牵手。', 'e2cfbdec858c7c7acc04ebae49bfaf3b_44590_1591775045.mp3', 'inter互相 + act行动 → interact交流，沟通', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2727, 'interesting', '/ˈɪntrəstɪŋ/', 'interesting.mp3', 'adj.有趣的，吸引人的', 'd8821406c37332c703388f9f1d46c389_62022_1578559076.jpeg', 'd_24_16607_0_4_20150808231630.png', 'Watching cartoons is more interesting for the little boy than doing his homework.', '对这个小男孩来说，看动画片比做作业更有趣。', 'jx5phu7tq6vyn23ztwj548nph6k5hjhz.mp3', 'interest对...有兴趣 + ing形容词或现在分词后缀 → interesting有趣的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2728, 'investigation', '/ɪnˌvestɪˈɡeɪʃn/', 'investigation.mp3', 'n.调查，调查研究', '722ba730896421ec38a6eaa0b325d71c_188544_1588089422.jpeg', '', 'The biologist conducted an investigation into the species of birds in the forest.', '生物学家对这片森林中鸟的种类进行了调查。', '00cbd63cdeb2a8a646d00195cfcf0bd3_46174_1588089405.mp3', 'in向内，进入 + vestig脚印，踪迹 + ation名词后缀，表示行为、状态、过程 → 调查研究', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2729, 'invoice', '/ˈɪnvɔɪs/', 'invoice.mp3', 'n.费用清单；单据；  v.提供费用清单；记清单', '0505990a6c7c40d5eb0676577c1b739a_79503_1542885454.jpg', '20140909_01_42_46_414_v3.png', 'This is an invoice for your lunch bills.', '这是您的餐费单据。', '6ebcfd4dc5c59354365f86aeeae7b986_12114_1542885494.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2730, 'iron', '/ˈaɪərn/', 'iron.mp3', 'v.熨烫（衣物）；  n.熨斗；  adj.刚强的', '3ac9180e38a0ad86346375e563a1641b_120836_1624266370.jpg', 'd_24_8407_0_4_20150808225653.png', 'I have an interview tomorrow', '明天我有一个面试，所以要把衬衣熨一熨。', 'sa_94_8407_0_3_20150809005606.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2731, 'joint', '/dʒɔɪnt/', 'joint.mp3', 'n.关节；  adj.联合的，共同的', '67c04508484f6595f7f5784711e06ab9_39059_1650010487.jpg', 'd_1_5009_0_2_20150808123327.png', 'She felt a sudden pain in her knee joint.', '她感到膝关节突然一阵疼痛。', '2mkrwqnp538md27b8xbkspfsg52kq3pz.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2732, 'joy', '/dʒɔɪ/', 'joy.mp3', 'n.欢乐，高兴，喜悦，乐事', 'e138fafbec8117cc1c7f9a16363d4db6_87298_1541848091.jpg', 'd_24_16517_0_4_20150808231518.png', 'The father and his son played with joy.', '这对父子在一起愉快地玩耍。', 'us_The_father_20231219163705008_fff2760113c6e49a08af.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2733, 'justify', '/ˈʤʌstəˌfaɪ/', 'justify.mp3', 'v.证明……正确或有理', 'c0b256d115699bcc8ef886701ca39792_52873_1586761243.jpeg', '', 'He is trying to justify his rude behavior.', '他正试图为自己粗鲁的行为辩解。', '49a3b39a918bbf4efa62fc6863b60699_46850_1586761258.mp3', 'just公正的 + ify使成为 → justify证明…正当', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2734, 'leak', '/liːk/', 'leak.mp3', 'v.漏；泄露；  n.漏洞', '7a1240966e88357ad47662adda7b105f_264184_1728871568.jpg', 'd_107_4428_0_2_20150809005630.png', 'The pipe leaks and the water flows everywhere.', '水管漏水，水流得到处都是。', 'sa_1_4428_0_3_20150808122758.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2735, 'line up', '/laɪn ʌp/', 'line up.mp3', 'phr.排成一行', '482c34ae437924721ff5b08ff98f7370.jpg', '', 'These high-heel shoes are lined up nicely by the shopkeeper.', '这些高跟鞋被店主排列得很整齐。', 'us_These_highheel_20241009154653331_72555c6cae0b87a507a3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2736, 'logical', '/ˈlɑːdʒɪkl/', 'logical.mp3', 'adj.合乎逻辑的；推理正确的', '52e06d5be91beb160062322ebf3bf315_29985_1569570118.jpeg', 'd_1_5815_0_2_20150808124442.png', 'Logical thinking requires a step-by-step thought process.', '逻辑思维需要循序渐进的思维过程。', '7a813d62b9df29cbb7dc3bf704195fe3_43006_1569570116.mp3', 'log说话 + ic表名词 + al形容词后缀 → logical符合逻辑的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2737, 'make up', '/meɪk', 'make up.mp3', 'phr.构成，形成；补足', '16f67b436d2156f60ec6be67e3395dfa_31690_1739164788.jpeg', '', 'The red slice makes up about a quarter of the whole.', '这红色的部分构成整体的1/4。', 'sa_41_13339_0_4_20150809024002.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2738, 'medicine', '/ˈmedɪsn/', 'medicine.mp3', 'n.药', '8277acec1d723d7b5c25d353584272f1_183315_1552544782.jpeg', 'd_24_7990_0_4_20150808225322.png', 'He was given medicine from the doctor to help him cure his disease.', '医生给了他一些药来治病。', '887606ea0e02256f_1268213310376002488_250930.mp3', 'medic医师＋ ine名词后缀 → 跟医师有关的 → medicine医学，内科学', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2739, 'monitor', '/ˈmɑːnɪtər/', 'monitor.mp3', 'n.显示器；监视器；班长；  v.监视；监督；监测', '75921ae37ea579f19af3b494f339919d_79898_1569051375.jpg', 'd_24_10989_0_4_20150808230531.png', 'I want a new flat-screen computer monitor.', '我想要一台新的纯平电脑显示器。', 'sa_1_10989_0_2_20150808131750.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2740, 'navy', '/ˈneɪvi/', 'navy.mp3', 'n.海军；海军部队', 'i_1_6234_0_4_150917172549-gigapixel-scale.jpg', 'd_1_6234_0_2_20150808124856.png', 'I am now a navy and ready to protect our country. ', '我现在是一名海军，已做好准备保护祖国。', 'b734c4aa0d17e37a6108eff02b13bd12_16973_1625822647.mp3', 'nav船 + y表名词 → navy海军', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2741, 'opera', '/ˈɑːprə/', 'opera.mp3', 'n.歌剧', '7eaba7564633d1584a44ab5f8a3c7722_98542_1602663262.jpg', 'd_24_4964_0_3_20150808223730.png', 'The woman is performing a wonderful opera on the stage.', '那位女士正在舞台上表演一场精彩的歌剧。', '402e8be27f5d7d1f_1266883371772828344_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2742, 'opinion', '/əˈpɪnjən/', 'opinion.mp3', 'n.意见，看法，观点', 'e7134ef56ec9d6571cd8e4cc8d0c4355_94796_1588909434.jpeg', 'd_24_4997_0_4_20150808223805.png', 'Different people have different opinions about the same thing.', '不同的人对于同样的事物有不同的看法。', 'c35b4dd2d4a87f205efa15c9272dfd7f_38254_1588909431.mp3', 'opin想，判断 + ion表名词 → opinion看法', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2743, 'order', '/ˈɔːrdər/', 'order.mp3', 'v.点（食物、饮料）；  n.顺序，次序', 'i_13_17948_0_4_160316145840-gigapixel-scale.jpg', 'd_24_17948_0_3_20150808233652.png', 'Can I help you?Yes', '“请问有什么需要的吗？”“我们想点一些吃的。”', 'sa_13_17948_0_4_160316150254.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2744, 'parcel', '/ˈpɑːrsl/', 'parcel.mp3', 'n.包裹；一片地，一块地', 'i_1_10997_0_3_20150808131755-gigapixel-scale.jpg', 'd_24_10997_0_4_20150808230535.png', 'I have some parcels for you', '“有您的一些包裹。”邮递员说道。', '435a1bf66afaa60f_1266798137911126894_250123.mp3', 'par部分 + cel表名词 → 小包裹 → parcel包裹', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2745, 'peculiar', '/pɪˈkjuːliər/', 'peculiar.mp3', 'adj.奇怪的，古怪的；特有的，特别的', 'i_1_5979_0_4_151028125653-gigapixel-scale.jpg', 'd_1_5979_0_2_20150808124618.png', 'These mooncakes\' flavors are very peculiar.', '这些月饼的口味很奇怪。', '38c7486007342ee8_1266883615405267624_250207.mp3', 'peculi特有 + ar……的 → peculiar特有的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2746, 'pedestrian', '/pəˈdestriən/', 'pedestrian.mp3', 'n.步行者，行人；  adj.平庸无奇的，无聊的', 'i_1_2049_0_3_20150808121806-gigapixel-scale.jpg', 'd_105_2049_0_2_20150809053305.png', 'Pedestrians should cross the road through the zebra crossing.', '行人应该通过斑马线过马路。', '51570d2147770c92_1266883014089464340_250207.mp3', 'pedestr=pedester步行，步行的 + ian…的人 → 步行的人 → pedestrian步行者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2747, 'postman', '/ˈpoʊstmən/', 'postman.mp3', 'n.邮递员(pl. postmen)', 'i_13_17919_0_3_20150808205100-gigapixel-scale.jpg', '20130105_10_27_02_361.png', 'It\'s the postman with some love letters—or are they bills?', '邮递员手里拿的是情书还是账单呢？', '696a54aa5a0fcfc5_1266741633034640016_250113.mp3', 'post邮件，邮政 + man人 → postman邮递员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2748, 'precise', '/prɪˈsaɪs/', 'precise.mp3', 'adj.精确的；恰好的', 'a3158d21712adf58b5ba74ae392bc778_156303_1696674483.jpg', 'd_16_5708_0_2_20150808225728.png', 'This instrument gives precise measurements.', '这台仪器显示出精确的测量结果。', 'us_This_instrument_20240626152911161_c380b3e08ab6bbc28a98.mp3', 'pre…前的，预先 + cise切 → 预先切好的 → precise精确的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2749, 'produce', '/prəˈdu:s/', 'produce.mp3', 'v.生产，制造；  n.农产品（读作/ˈprɑːduːs/）', '1425952705375-gigapixel-scale.jpg', 'd_24_7818_0_3_20150808225138.png', 'The factory produces things quickly.', '这家工厂生产产品的速度很快。', '5c8f8e02bac4ca28_1266883328465677304_250207.mp3', 'pro向前 + duce引导，带来 → 引向前 → produce生产', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2750, 'property', '/ˈprɑpərti/', 'property.mp3', 'n.房产；财产；特性；性能', 'e7018b2a0e8b0064ce25821d2a5c9f09_90474_1588909577.jpeg', 'd_1_5424_0_2_20150808123829.png', 'He had finally saved enough money to buy a property.', '他终于攒了足够的钱来置办一处房产。', '566fad9cc6d02a5dd7cdc165131aaaa5_46404_1588909574.mp3', 'proper拥有 + ty名词后缀 → 个人拥有的 → property房产', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2751, 'puzzle', '/ˈpʌzl/ ', 'puzzle.mp3', 'n.拼图；难题；  v.使迷惑，迷惑', '64cc9eb248b6ee7e804d716d91b0efde_167374_1533105936.jpeg', 'd_24_5469_0_3_20150808224101.png', 'He puts in the last piece of the puzzle to complete the picture.', '他把拼图的最后一块放进去以完成这幅图。', '830b39c67e6409a3_1266741764999240392_250113.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2752, 'quit', '/kwɪt/', 'quit.mp3', 'v.辞职；戒掉；离开（工作职位、学校等）', '37d7e2363b9b2c7c7df5c0f441583e94_173817_1535177678.jpeg', '20141013_23_25_35_626_v3.png', 'The office worker was so happy after he quit his job.', '这名公司职员辞掉工作后感到很开心。', 'dcv25lsvapq8x3m996r6bp9x2qefdbkh.mp3', ' ', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2753, 'represent', '/ˌreprɪˈzent/', 'represent.mp3', 'v.象征；代表；表示；描述，展现；阐明；说明', 'c97829a43f8f8fb2c00293468f52853d_49841_1645090075.jpg', 'd_16_4777_0_2_20150808224421.png', 'This hand gesture represents love.', '这个手势象征着爱。', '5sqdg3ltsadhl335wmszndnt7pf2nr57.mp3', 're加强语气 + pre前面 + sent存在 → represent象征，代表，展现', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2754, 'result in', '/rɪˈzʌlt ɪn/', 'result in.mp3', 'phr.导致，造成', 'i_903_-903_0_1_160130160549.jpg', '', 'Sweet food can result in teeth problems.', '甜食会损害牙齿。', 'sa_903_-903_0_1_160202163342.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2755, 'safe', '/seɪf/', 'safe.mp3', 'n.保险箱；冷藏箱；  adj.可靠的，稳妥的；有把握的', 'dfa46f718bb90a078fe4ddeb2b97003b_80622_1753869079.jpg', 'd_24_16616_0_4_20150808231645.png', 'By using the safe', '有了保险箱，你的钱会更安全。', '3_0_20170608071735_31000_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2756, 'satisfaction', '/ˌsætɪsˈfækʃn/', 'satisfaction.mp3', 'n.满足，满意；乐事；补偿', 'i_1_10987_0_4_150829150722-gigapixel-scale.jpg', 'd_24_10987_0_4_20150808230529.png', 'I gave their service a good rating to show my satisfaction.', '我给了好评来表示我对他们的服务很满意。', 'f39d0345612c530f_1266883626597636670_250207.mp3', 'satis足够，饱足 + faction名词后缀 → satisfaction满足', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2757, 'scene', '/siːn/', 'scene.mp3', 'n.景象；（戏剧的）一场', 'f05b24bcd618c9f72125ac6d27483c7c_485723_1610087454.jpg', 'd_16_7905_0_2_20150808232054.png', 'The sunset over the road created quite a beautiful scene.', '道路尽头的日落创造了一幅唯美的景象。', 'sa_1_7905_0_2_20150808130124.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2758, 'scenic', '/ˈsiːnɪk/', 'scenic.mp3', 'adj.景色优美的；舞台背景的，舞台的；  n.风景名胜', '8af986514628f58f51f15dad59e562ef_152123_1564650522.jpg', '20140820_13_48_58_325_v3.png', 'These scenic islands are the perfect place to go traveling.', '这些景色优美的岛屿是旅行的绝佳地点。', '014db9885fbe49750976ed8cc77474f9_42457_1564650516.mp3', 'scen=scene情景 + ic形容词，...的 → 自然景色的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2759, 'sensible', '/ˈsensəbl/', 'sensible.mp3', 'adj.明智的，理智的；可觉察的', '4d837e95719354a33c4cda6e0f62c262_199584_1561953313.jpg', '20130201_16_30_00_948.png', 'It\'s a sensible choice to take only a few things when going climbing.', '轻装上阵去爬山是一个明智的选择。', '697444608a953a3f_1266883486517582460_250207.mp3', 'sens感觉 + ible形容词后缀，能…的 → sensible能感觉的，明智的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2760, 'severe', '/sɪˈvɪr/，/səˈvɪr/', 'severe.mp3', 'adj.极为恶劣的；严重的；严厉的；猛烈的；剧烈的', '80cc0ff01cc6df27eadecf26e6f93bdf_203348_1533105280.jpeg', '7d3312a1da8948573362663f254de762_72643_1539341233.png', 'It\'s hard for people to walk in such severe weather conditions.', '在如此恶劣的天气条件下，人们走得很艰难。', 'us_Its_hard_20220608134733556_6ed340268beb0adaf14a.mp3', 'sever诚恳 + e → severe严肃的，严厉的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2761, 'shadow', '/ˈʃædoʊ/ ', 'shadow.mp3', 'n.影子；阴影；  v.把影子投在……', 'i_1_7989_0_2_20150808130247-gigapixel-scale.jpg', 'd_16_7989_0_2_20150808232330.png', 'I could see the boy\'s shadow on the ground as he played soccer.', '这个男孩踢球的时候，我能看到他在地上的影子。', '87fgdare5ctfumvzcmqmmskcc3rswva8.mp3', 'shade阴影，影子 + ow后缀 → shadow影子', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2762, 'smell of', '/smel əv/', 'smell of.mp3', 'phr.有……的气味', 'a50cca7334163e2e1ce668ae8d6af8fc.jpeg', '', 'His breath smells of onions. ', '他呼的气有洋葱味。', '31a81af75a22f636a052432b192efaf6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2763, 'solution to', '/səˈluːʃn tuː/', 'solution to.mp3', 'n.解决...的方法', '352bf5b3d2c05f587f2d205b1de18a25.jpeg', '', 'She had a clever solution to save his wet book.', '她有一个聪明的解决办法来挽救他弄湿的书。', 'e3450f9cd0254318f8826fb3ec02f993.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2764, 'staff', '/stæf/', 'staff.mp3', 'n.工作人员，全体职员；五线谱；参谋；  adj.作为正式工作人员的；参谋的；职员的', 'e64ac7bcfd0eb216a64b45a5ff4c2950_171520_1533106553.jpeg', 'd_107_5416_0_2_20150809012419.png', 'The doctors and nurses are important members of the hospital staff.', '医生和护士都是重要的医院职员。', '835ef45ef3322be2_1266883531318209428_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2765, 'straw', '/strɔː/', 'straw.mp3', 'n.吸管；稻草，麦秆', 'i_16_8927_0_4_20150808233529-gigapixel-scale.jpg', 'd_16_8927_0_4_20150808233529.png', 'Why do you need two straws for one drink?', '你一杯饮料为什么要两根吸管？', 'sa_16_8927_0_4_20150808233529.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2766, 'suspicion', '/səˈspɪʃən/', 'suspicion.mp3', 'n.怀疑', '9a2ac15fe38792e3a431e4ccebb9fe30_100026_1541574110.jpeg', 'd_107_2504_0_2_20150809002759.png', 'The two men raised the suspicion of the policeman.', '这两个人引起了警察的怀疑。', 'ca97b3a4a1174851f194bf7a36d34cff_81824_1594793928.mp3', 'su=sus下面 + spic环顾，检查 + ion表名词 → 在下面看 → 怀疑', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2767, 'symbol', '/ˈsɪmbəl/ ', 'symbol.mp3', 'n.象征', '5c622936626f34c5e036c631ed29e3c6_46256_1733799482.jpg', '20141013_18_56_55_446_v3.png', 'Doves are the symbol of peace.', '鸽子是和平的象征。', 'a0d502718332b411_1266883627071265352_250207.mp3', 'sym共同，相同 + bol抛 → 共同抛出的标志 → 象征', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2768, 'think better of', '/θɪŋk ˈbetər əv/', 'think better of.mp3', 'phr.改变主意', '0b8ea23bb316113f38c45e3cbce9cf87.jpeg', '', 'His mother is relieved that he thought better of dyeing his hair green.', '他不打算把头发染成绿色了，这让母亲松了一口气。', 'dfe86e33d5b063feddfa03dbcbc63d25_49966_1600071403.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2769, 'visit', '/ˈvɪzɪt/', 'visit.mp3', 'v.拜访；  v.看望，探望；参观，访问；  n.访问参观，游览', 'b37534400c1ea93ba7f787ea6e133462_130534_1701682868.jpg', 'd_24_15923_0_4_20150808230834.png', 'Our neighbors always visit us after work.', '我们的邻居下班之后经常来串门。', 'us_Our_neighbors_20231204175629594_1d2e7115da1f6be943f4.mp3', 'vis看，观看 + it → visit参观', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2770, 'vivid', '/ˈvɪvɪd/', 'vivid.mp3', 'adj.（颜色）鲜艳的，强烈的（颜色、光）；生动的，清晰的（记忆、描述）', 'be2eba04b96dc26363d72760025e29a8_193752_1588928791.jpeg', '20141012_22_38_42_737_v3.png', 'The artist used vivid colors to graffiti the gray wall.', '画家用鲜艳的颜色在灰墙上涂鸦。', '568020c6906da104b818d2f3d2e0a3a2_44992_1588928786.mp3', 'viv生命 + id…形容词后缀，具有…性质的 → 有生命的 → vivid活泼的；生动的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2771, 'wind', '/wɪnd/', 'wind.mp3', 'n.风；  v.（道路、河流等）蜿蜒曲折', '639ddb6f4480f60a6cc4cb775c98dc68_90236_1577946863.jpeg', 'd_24_17142_0_4_20150808232128.png', 'The wind is blowing the leaves.', '风正吹着树叶。', '9cdca81dbc7c146e_1266797985319836226_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2772, 'acknowledge', '/əkˈnɑːlɪdʒ/', 'acknowledge.mp3', 'v.承认；认可；（公开）致谢；告知收到', 'b3d0fb37e99240a19027b2c460abdfaa_30419_1737704655.jpg', 'd_16_6221_0_2_20150808230421.png', 'The boy acknowledged breaking the glass.', '小男孩承认自己打碎了杯子。', '54c083735e23887f2147e00413a88faa_15092_1611036265.mp3', 'ac使 + knowledge了解 → acknowledge承认，认知', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2773, 'additional', '/əˈdɪʃənl/', 'additional.mp3', 'adj.增加的；附加的', '5b00ca8824c80ef4b798b015c307260c_203301_1585124666.jpeg', 'd_1_58_0_3_20150808113716.png', 'He had to pay an additional charge for the overweight luggage.', '他得为超重的行李支付额外的费用。', '2671d2bb8ce839c69a067ca8210e242c_49298_1585124662.mp3', 'add加上 + ition名词后缀 + al形容词后缀 → additional附加的，追加的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2774, 'amuse', '/əˈmjuːz/', 'amuse.mp3', 'v.使人发笑', 'i_1_4206_0_3_20150808122529-gigapixel-scale.jpg', 'd_16_4206_0_7_20150808224107.png', 'Their talk show amused the audience.', '他们的脱口秀把观众逗乐了。', 'sa_1_4206_0_3_20150808122529.aac', 'a使 + muse娱乐 → amuse娱乐，使发笑', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2775, 'anything', '/ˈeniθɪŋ/', 'anything.mp3', 'pron.任何事；任何事物', 'f8a2364df260c20ef5c4106bd86d0f6c_159450_1587814020.jpg', '', 'Welcome! Is there anything I can help you with?', '欢迎光临！请问有什么可以帮您的吗？', 'b566856b96f92b14_1266763447140068280_250117.mp3', 'any任何 + thing事物 → anything任何东西', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2776, 'appetizing', '/ˈæpɪtaɪzɪŋ/', 'appetizing.mp3', 'adj.促进食欲的', '4a5ce6023680a563eae6d6e5845de5a4.jpg', '', 'The freshly baked cake looks very appetizing to the girl!', '新鲜出炉的蛋糕对这个女孩来说看着十分可口！', 'f3598a04215b03624c82fe116256fbd7.mp3', 'ap加强动作+peti追寻，寻求+zing...的→ 促进食欲的，开胃的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2777, 'approve of sth.', '/əˈpruːv  əv ˈsʌmθɪŋ/', 'approve of sth..mp3', 'phr.赞成某事', 'i_908_-908_0_1_160225110112.jpg', '', 'I approve of your plan.', '我赞成你的计划。', 'sa_908_-908_0_1_160227155453.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2778, 'ash', '/æʃ/', 'ash.mp3', 'n.灰', '851344ef8597fb71385c437ab7356b35_202184_1564370397.jpg', 'd_16_6715_0_2_20150808231017.png', 'These backpackers left nothing here but a pile of ashes.', '这些背包客只在这儿留下一堆灰烬。', 'd485n5qcnfqr9kyewcnamalchaf5rbcu.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2779, 'at least', '/æt ˈlist/', 'at least.mp3', 'phr.至少，最少', '91a7c33ee153a5d9a5ebf8f86153f9f5_70925_1590217432.jpeg', '', 'She bought at least three apples.', '她至少买了三个苹果。', '2125be25ab321e99_1266883376112708470_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2780, 'at length', '/æt leŋkθ/', 'at length.mp3', 'phr.最后，详细地', '5_44_190_20170324164904_147_c.jpg', '', 'At length', '最后我们登上了山顶。', '5_51_403_20170401152950_85185_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2781, 'bathe', '/beɪð/', 'bathe.mp3', 'v.洗澡；用水清洗；给……洗澡', '86112fc99795ef24b2d8ef6a895f518a_121245_1532161429.jpeg', 'd_16_8957_0_5_20150808233630.png', 'The dog', '狗、猫和鸭子喜欢在一起洗澡。', '25a6eb67d47191edc7888d33b7e5fa0a_19852_1554093099.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2782, 'begin with', '/bɪˈɡɪn wɪθ/', 'begin with.mp3', 'phr.以……开始', 'e14feb200729b02eaa37ec1de5a5b8ea.jpg', '', 'Her day usually #begins with# a cup of coffee.', '她的一天通常是从一杯咖啡开始的。', '573bd206f33b5585829e0ce0c2ae4154.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2783, 'belief', '/bɪˈliːf/', 'belief.mp3', 'n.信仰；信条；信任；信心', '9555c204ff2f893407732060231f99e1_202547_1588091041.jpeg', '8a12a8c744d1444e3c3cd18b12c5b81b_34289_1551253529.png', 'The rights and wrongs of eating meat are subject to personal belief.', '吃肉的做法正确与否，取决于个人的信仰。', 'us_The_rights_20241009155626818_9741cfbe5cf02e537e29.mp3', 'be关于 + lief关心，爱 → belief信仰', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2784, 'beside the point', '/bɪˈsaɪd ðə pɔːɪnt/', 'beside the point.mp3', 'phr.不重要', '3dec60fb8eb571b5769dea1aedcdc2de.jpg', '', 'Whether he had fun or not is beside the point—he promised to be home by 8pm!', '他是否玩得开心并不重要——他承诺了晚上8点到家的！', '807374ae3bb69d3d7b81e56b55734116.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2785, 'bring', '/brɪŋ/', 'bring.mp3', 'v.引起，导致', 'b7e50daf31092a03b4fab7e133a75d63.jpeg', 'd_24_15918_0_3_20150808230825.png', 'This photo album brings back some memories. ', '这本相册勾起了一些回忆。', '430724831f0ed8c42016896fda4ff765.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2786, 'bring down', '/brɪŋ daʊn/', 'bring down.mp3', 'phr.使倒下；减少', '5_44_190_20161107140528_30346_c.jpg', '', 'The strong wind last night brought down the telephone pole.', '昨晚的强风把电线杆吹倒了。', '5_51_78_20161111145925_4815_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
