INSERT INTO `words` VALUES (2788, 'camp', '/kæmp/', 'camp.mp3', 'v.露营；宿营；  n.阵营', '2d11e96ac8346297e2d8332d2163bbbc_136895_1575012260.jpeg', 'd_109_16609_0_2_20150809061428.png', 'It is an amazing experience to camp in a forest.', '在森林里露营是一种奇妙的体验。', 'ed0cae0587c9ee4a_1266883198223100720_250207.mp3', 'camp=field田野 → camp营地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2789, 'cheer up', '/tʃɪr ʌp/', 'cheer up.mp3', 'phr.高兴起来', '1e4e221bd862b2f041a293db6671a11b.jpg', '', 'His friend\'s encouraging words cheered him up.', '朋友鼓励的话让他振作了起来。', '5bzjnc8whnldw8dzgwlldn267c68w39l.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2790, 'childhood', '/ˈtʃaɪldhʊd/', 'childhood.mp3', 'n.童年，幼年', '40fb8c5f22ef718091a8a067a70d4c37_102130_1577946507.jpeg', 'd_24_8427_0_4_20150808225713.png', 'We have been good friends since childhood.', '我们从小就一直是好朋友。', 'f9125f1c6e56130b5748764cddec809a_31342_1577946504.mp3', 'child孩子 ＋ hood时期，性质 → childhood童年', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2791, 'come on', '/kʌm ɔn/', 'come on.mp3', 'phr.来吧', '7edb3677e8601ed6a4d0d636dc8b1056_186107_1576287643.jpeg', '', 'Come on', '他说：“来吧，我们走！”', 'ae51c5d13e21c36cd158997424be3376_19794_1576287640.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2792, 'command', '/kəˈmænd/', 'command.mp3', 'v.值得，博得；命令；指挥，统率；  n.指令', 'f2223d2f6ff33f3982f490907969e449_121482_1705470628.jpg', 'd_16_7937_0_2_20150808232156.png', 'His good performance commands our praise. ', '他表现得好，值得表扬。', 'us_His_good_20240117135032065_40e953690b13288bd26b.mp3', 'com一起 + mand命令 → 命令大家一起做 → command指挥，命令', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2793, 'companion', '/kəmˈpæniən/', 'companion.mp3', 'n.同伴；指南', 'i_24_8900_0_5_151222143417-gigapixel-scale.jpg', 'd_24_8900_0_3_20150808225920.png', 'Dogs are good companions.', '狗狗是很好的伙伴。', 'sa_24_8900_0_5_151225151300.aac', 'com共同 + panion面包 → 吃一条面包的 → companion同伴', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2794, 'compromise', '/ˈkɑːmprəˌmaɪz/', 'compromise.mp3', 'n.妥协，折中；  v.使遭受危险', '4db98e5e9dd31cedb8db9c5a56cecdba_177148_1596684726.jpg', '20130105_10_18_10_109.png', 'The seller made a compromise and sold the dress at 50 yuan.', '卖方做出了妥协，以50元的价格卖出了那条裙子。', 'us_The_seller_20230227103920231_fdaafa7de1360de039d2.mp3', 'com共同 + pro前面 + mise送，放出 → 共同承诺、遵守一项决定 → 妥协，和解', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2795, 'conductor', '/kənˈdʌktər/', 'conductor.mp3', 'n.指挥；售票员', 'i_1_2744_0_3_20150808121920-gigapixel-scale.jpg', 'd_24_2744_0_5_20150808223306.png', 'The conductor is leading the band.', '乐队指挥正在指挥乐队。', '7wn3al9ehghppruwgcbwgtmj93a25qj4.mp3', 'con共同 + duct引导，带来 + or表名词，人 → 引导大家共同做事情的人 → conductor指挥家', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2796, 'confidential', '/ˌkɑːnfɪˈdenʃl/', 'confidential.mp3', 'adj.机密的；表示信任的', 'e94691ab8e98ee58199462c973b22013.jpg', 'd_107_579_0_2_20150809000943.png', 'He destroyed the confidential document as soon as he had finished reading it.', '他一读完机密文件就把它销毁了。', '15bd40cb92ba98b07eaaaa5e2ce0fa10.mp3', 'confident有信心的 + ial形容词后缀 → confidential表示信任的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2797, 'cope', '/koʊp/', 'cope.mp3', 'v.处理，应对', 'eac83b18615b0323e8a0cedfa101f326_201674_1564370519.jpg', '', 'The experienced captain can cope with the dangerous situation and find a solution.', '这位经验丰富的机长能应付危险情况并找到解决方法。', '976718afc076666e_1266883371518810798_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2798, 'correspond to', '/ˌkɔːrəˈspɑːnd tu/', 'correspond to.mp3', 'phr.符合', '7e816283a9f9cf11842993d61e15d85a.jpg', '', 'The number of seats should correspond to the number of guests.', '座位的数量应与客人的人数相符。', 'e94d97832641e54078d00d59aff59ca0.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2799, 'create', '/kriˈeɪt/', 'create.mp3', 'v.创造；造成，引起，产生', '5970e56fd7e8d91847f4161086718291_103862_1587815095.jpeg', 'd_24_4978_0_3_20150808223748.png', 'The writer created many characters.', '这位作家创造了很多角色。', '97zybm89y2c65rr929rp5qdnxnufj9nf.mp3', 'cre增长，产生 + ate造成 → 增长 → create创造', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2800, 'crowded', '/ˈkraʊdɪd/', 'crowded.mp3', 'adj.拥挤的', 'c_20150528_114258_16_17109-gigapixel-scale.jpg', 'd_16_17109_0_2_20150809004217.png', 'The subway is too crowded to get on.', '这趟地铁挤得上不去。', 'c7c55f576b3c326b101c0035b7fc657e.mp3', 'crowd拥挤 + ed形容词后缀 → crowded 拥挤的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2801, 'cut across', '/kʌt əˈkrɔs/', 'cut across.mp3', 'v.抄近路通过', '0fce1feff23ed1e2ac194141844a5eed_115710_1582791213.jpeg', '', 'The boy decided to cut across a field to get home.', '男孩决定抄近路通过一片田野回家。', '740b7c5b7ad093a4ca60355e16cb0d6b_49644_1582791210.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2802, 'deliver', '/dɪˈlɪvər/', 'deliver.mp3', 'v.递送，交付', '4d07b07bbca9deec05c51aea04c23292_100973_1601198945.jpg', '20141012_07_34_06_280_v3.png', 'The man delivers the packages to the woman.', '男人把包裹送到这位女士的手上。', '0baaf87584d87c06_1266883372596681436_250207.mp3', 'de离开 + liver自由 → deliver投递，投送', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2803, 'despair', '/dɪˈsper/', 'despair.mp3', 'n.绝望；  v.绝望，感到无望', '3_0_20160718113240_41305_c-gigapixel-scale.jpg', '23f4835eebb618fdc0dd2ba923fa7aa1_24853_1539341462.png', 'All of my money is gone! the man cried in despair.', '“我的钱全没了！”这个男人绝望地哭喊道。', '21d0eecd36262e9a_1266883493908228896_250207.mp3', 'de去掉 + spair希望 → despair 绝望', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2804, 'enemy', '/ˈenəmi/', 'enemy.mp3', 'n.敌人；危害物', 'b2f3c0ad2a278332960f34b0b91b8dde_199779_1530597787.jpeg', 'd_24_7968_0_4_20150808225313.png', 'The man who holds the pan is her enemy.', '拿着平底锅的男人是她的敌人。', 'enhnylwvyj7qa9zm9c7kv4u8ms7q8xyl.mp3', 'en不是 + emy朋友 → enemy敌人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2805, 'expectation', '/ˌekspekˈteɪʃn/', 'expectation.mp3', 'n.期望；预期', 'i_16_10565_0_4_151117094258-gigapixel-scale.jpg', 'd_105_10565_0_2_20150809061734.png', 'My parents have high expectations for me.', '我的父母对我抱有很高的期望。', 'sa_16_10565_0_4_151204103757.aac', 'expect期待 + ation表名词 → 期待，希望', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2806, 'familiar with', '/fəˈmɪljɚ wɪð/', 'familiar with.mp3', 'phr.对……熟悉', '6e76956906566dd41fcac6adf171a212.jpeg', '', 'As a professional', '作为一名专业人士，他对整个过程非常熟悉。', 'ca5f6f4ed773c977240dd307df6a8c34.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2807, 'fear', '/fɪr/', 'fear.mp3', 'v.害怕；敬畏；  n.害怕', '4352c152387cb17e78253da3db38a7a4_613665_1617778702.jpg', 'd_24_16611_0_4_20150808231637.png', 'The cat fears the mice running after it.', '那只猫害怕追它的老鼠。', '16420dadade56cc7989c406f11362dae_19901_1621924536.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2808, 'fun', '/fʌn/', 'fun.mp3', 'n.娱乐，乐趣，快乐；  adj.逗乐的，有趣的；  v.开玩笑，嬉戏', '3e8580fa8bc017dbe19ee36c7080e63c_156191_1701669484.jpeg', 'd_24_16614_0_4_20150808231642.png', 'They\'re all having fun at the party.', '他们在派对上玩得很开心。', '3_0_20170608071732_31974_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2809, 'geometry', '/dʒiˈɑːmətri/', 'geometry.mp3', 'n.几何学；几何形状', 'eae2ea9c9e3da794e15a790282def065_188868_1533108618.jpeg', 'd_105_5316_0_2_20150809054624.png', 'The little boy is so good at solving the mathematical problems of geometry.', '这个小男孩很擅长解决几何类的数学问题。', '2dd5b12ee07c474a34e0f7ce702041d9_61028_1533108614.mp3', 'geo地 + metry计量，测量 → 测量地面 → geometry几何学', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2810, 'get rid of', '/ɡet rɪd ɑv/', 'get rid of.mp3', 'phr.摆脱；除去', 'getridof_10388_20231106_6affce6a.jpg', '', 'Debts are difficult to get rid of', '债务是很难清除的，所以小心你的钱。', 'sa_4_10388_0_2_20150808184225.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2811, 'glance', '/ɡlæns/', 'glance.mp3', 'v.看一下；  n.一瞥，扫视', 'i_1_7986_0_3_20150808130245-gigapixel-scale.jpg', 'd_16_7986_0_4_20150808232325.png', 'I glanced at her', '我瞥了她一眼，但是她没有注意到。', 'sa_1_7986_0_3_20150808130245.aac', 'glanc冰，光滑 + ance表名词，性质，状况 → 像冰上划过的光线 → glance一瞥，扫视', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2812, 'Greek', '/ɡriːk/', 'Greek.mp3', 'adj.希腊的，希腊人的，希腊语的；  n.希腊人，希腊语', '3_0_20170930071256_45349_c-gigapixel-scale.jpg', 'd_24_9828_0_3_20150808230300.png', 'The Greek flag is made up of two colors', '希腊的国旗是由白、蓝两色组成的。', '3_0_20170930071256_44393_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2813, 'half', '/hæf/', 'half.mp3', 'n.半，半时；  adj.一半的', '1d4ebab5f345d48ed74c37a59eefbe5b_54139_1575016287.jpeg', 'd_24_16447_0_4_20150808231248.png', 'Compared to the left', '相比左边的来说，右边的塑料瓶是半满的。', 'ddec2210958d92fb4bfb92dd784c50fb_40558_1575016285.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2814, 'headmaster', '/ˌhedˈmæstər/', 'headmaster.mp3', 'n.校长（尤指私立学校的）', '8a8c24824f26066c75b364059dbfadc5_59411_1569568073.jpeg', 'd_109_6728_0_2_20150809054748.png', 'The headmaster is responsible for the management of this school.', '这位校长负责管理这所学校。', '12b0ad4ff7afa039_1266883330166598434_250207.mp3', 'head头 + master主人 → 学校里最高层的管理者 → headmaster英国中小学校长，男舍监', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2815, 'imagination', '/ɪˌmædʒɪˈneɪʃn/', 'imagination.mp3', 'n.想象力', '3_0_20170930071732_10987_c-gigapixel-scale.jpg', '20130510_12_49_51_85.png', 'Writers need a great imagination to create wonderful stories.', '作家需要很好的想象力才能创造出美妙的故事。', '3_0_20170930071732_8155_c.aac', 'imagin想象 + ation名词后缀 → imagination想象', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2816, 'in particular', '/ɪn pər\'tɪkjələr/', 'in particular.mp3', 'phr.尤其，特别', '183354568c232122d10da515e93cd217_202242_1564370518.jpg', '', 'I like eating fruits', '我喜欢吃水果，尤其是苹果。', '12ff65fc3e714835_1266883009776757696_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2817, 'in person', '/ɪn ˈpɜrsn/', 'in person.mp3', 'phr.亲自', '097ae5e2c5e779cc148c28916a6b481e.jpeg', '', 'Despite his tight schedule', '尽管时间很紧，他还是决定亲自送女儿上学。', 'abf94f692b3f76c8541606c086396e70.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2818, 'in the light of', '/ɪn ðə laɪt əv/', 'in the light of.mp3', 'phr.根据，按照', 'f6c0baeb621347047bcef560d5f5cdb8_157362_1574413283.jpeg', '', 'In the light of the school rules', '根据校规，你不能抽烟。', '8cb0fb31d04fc3157e96a0d8c6f329eb_32965_1574413280.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2819, 'in time', '/ɪn taɪm/', 'in time.mp3', 'phr.及时；总有一天', '3f5402ed2f6a1d54a3ad74e14d601a45_42335_1753757817.jpg', '', 'The firemen arrived in time and saved many lives.', '消防员及时赶到，拯救了许多生命。', 'sa_11_7739_0_2_20150808173607.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2820, 'inclusive', '/ɪnˈkluːsɪv/', 'inclusive.mp3', 'adj.包含……在内的', 'decc910569e4891268cf2370e9d78d3f_94604_1583482619.jpeg', '', 'The money he is paying the waiter is inclusive of tips.', '他付给服务员的钱里包含了小费。', 'e7ef34d4c3031e200669f7f87e84d63a_50004_1583482616.mp3', 'in进入 + clus关闭 + ive形容词后缀 → 包括在内的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2821, 'income', '/ˈɪnkʌm/', 'income.mp3', 'n.收入，收益', '3588e340a3b851ace63f4670970c21eb_34196_1619331116-gigapixel-scale.jpeg', '20130130_16_28_12_349.png', 'The workers\' income isn\'t as much as they expected.', '工人们的工资没有他们预期的高。', 'db65e1987388f78c_1266883487094844272_250207.mp3', 'in 向内，进入 + come来 → 收入；收益；进款', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2822, 'independent', '/ˌɪndɪˈpendənt/', 'independent.mp3', 'adj.独立的，自立的；  n.无党派者', 'bd032f1314978d131f0d9364d17775fa_145740_1552547717.jpeg', 'd_107_4949_0_2_20150809011142.png', 'He is learning to be independent in the face of a challenge.', '他在学习独立面对挑战。', '3_0_20170608071543_98281_c.aac', 'in不 + depend依靠 + ent……的 → 不依靠的 → independent独立的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2823, 'instruction', '/ɪnˈstrʌkʃn/', 'instruction.mp3', 'n.说明，说明书；指导', 'i_16_5702_0_9_151201120310-gigapixel-scale.jpg', 'd_24_5702_0_4_20150808224304.png', 'She follows the instructions to take her medicine.', '她按照说明书的指示服药。', 'sa_16_5702_0_9_151209173108.aac', 'instruct指导 + ion名词后缀 → instruction指导', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2824, 'invest', '/ɪnˈvest/', 'invest.mp3', 'v.投资', 'e7725f879a33aa7d258cf7155bb6711f_83394_1707200216.jpg', 'd_1_4359_0_3_20150808122647.png', 'He decided to invest in the real estate market.', '他决定投资房地产市场。', '8852df0407674c20_1266883376995523238_250207.mp3', 'in进 + vest衣服 → 把衣服中的钱放进事业中 → invest投资', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2825, 'January', '/ˈdʒænjueri/', 'January.mp3', 'n.一月', '3_0_20170701113541_68941_c-gigapixel-scale.jpg', 'd_24_15931_0_3_20150808230849.png', 'January always has 31 days.', '一月份总是31天。', 'zlhjblcdyxy5zs8lswhdj5cbckk9bbwp.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2826, 'keen on', '/kiːn ɑːn/', 'keen on.mp3', 'phr.热爱', '1bc06f7251cb836f14fa721fcb6a7901.jpeg', '', 'He is keen on starting his new job', '他失业了很长时间，所以对新工作充满热情。', '7c2b3c4fdf7ab4607935bf94cdb8e2f9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2827, 'labor', '/\'leɪbər/', 'labor.mp3', 'n.劳动，劳力；劳工；  v.劳动，苦干', 'f6ee875dc7fa197b5954104ec800003e_247900_1728540519.jpg', '20130311_16_49_57_75.png', 'This woman\'s labor in the fields is tireless.', '这位妇女在地里不知疲倦地劳动。', '6qkqqdxutp5jaaj3rwxhf2w5vt5jcsr8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2828, 'liberate', '/ˈlɪbəreɪt/', 'liberate.mp3', 'v.解放，释放', '5b0590809855230eaf30d7151fce323a_43718_1540803121.jpg', '20121225_19_23_19_217.png', 'She felt her heart liberated together with the birds.', '她感到自己的心随着鸟儿一起解放了。', '771295bf09c8485a10724cc1372632ac_14778_1540803267.mp3', 'liber自由 + ate动词后缀 → 使…自由 → liberate解放，释放', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2829, 'massive', '/ˈmæsɪv/', 'massive.mp3', 'adj.巨大的；大规模的', '4ea8f7a55db24a8be37eb07171debb2e_174540_1573615876.jpeg', 'd_1_5659_0_3_20150808124156.png', 'The massive statue is a popular tourist attraction in Sichuan province.', '这座巨大的雕像是四川省有名的旅游景点。', '2d7a1c2c8b0a546cc0f70b48d891b37e_34565_1621924902.mp3', 'mass大块，大团 + ive表形容词 → massive巨大的，大规模的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2830, 'may', '/meɪ/', 'may.mp3', 'v.可能，也许', '96cac2543ab3f6d0b72565c5eacb2c65_193864_1575105039.jpeg', 'd_24_19253_0_4_20150809001026.png', 'The cat in the box may or may not be alive.', '箱子里的猫可能活着也可能死了。', '0fb993200356da85_1266883009232263852_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2831, 'meet with', '/miːt wɪð/', 'meet with.mp3', 'phr.遇到，经历，会晤', '7698cc31ab8641caac0844832904a322_116398_1701681306.jpeg', '', 'The business partners met with each other this morning.', '双方商业伙伴于今天早上举行了会谈。', '5_51_411_20170427192242_94868_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2832, 'merry', '/ˈmeri/', 'merry.mp3', 'adj.欢乐的，愉快的', 'i_1_1846_0_4_151027112357-gigapixel-scale.jpg', 'd_24_1846_0_3_20150808223201.png', 'I wish you a merry Christmas!', '祝你圣诞快乐！', 'sa_1_1846_0_4_151109160446.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2833, 'missing', '/ˈmɪsɪŋ/', 'missing.mp3', 'adj.失踪的；缺少的；缺失的', 'b18f2afc43e463075a3bcc5ccc788974_123867_1656918650.jpg', '', 'One of the puzzles is missing.', '其中一个拼图丢失了。', 'a5gj6q27cmtuej22vlyxm6996q83esn5.mp3', 'miss消失，错过 + ing形容词或动名词后缀 → missing失踪的，缺少的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2834, 'mission', '/ˈmɪʃən/', 'mission.mp3', 'n.任务，使命；  v.派遣……执行任务', 'e3cca38ee7579a0db4749d80356c5d78_282870_1713249623.jpeg', 'd_1_1869_0_3_20150808121751.png', 'The soldiers are carrying out the mission.', '士兵们正在执行任务。', 'sa_1_1869_0_3_20150808121751.aac', 'miss送，放出 + ion名词后缀 → 送出 → mission派遣', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2835, 'new to', '/nu tu/', 'new to.mp3', 'phr.新接触的，不熟悉的', '115a73316cf8d9345b631dd6108f9a3a.jpeg', '', 'Coding was new to her  but it quickly became something she truly enjoyed. ', '虽然她才刚接触编程，但她很快就喜欢上了它。', '7f9c6aee589d98f14ecde3a9a9fbc4fc.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2836, 'novel', '/ˈnɑːvl/', 'novel.mp3', 'n.小说，长篇故事；  adj.新奇的，新颖的', '0af8ec982a44b5d660d9bf1fb49f489d_51973_1656930337.jpg', 'd_24_3915_0_3_20150808223406.png', 'He loves reading novels and these two are his favorites.', '他喜欢读小说，这两本是他最喜欢的。', 'a771c278553ab627_1266883528163940978_250207.mp3', 'nov新的 + el名词后缀 → 新的故事 → novel小说', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2837, 'obey', '/əʊˈbeɪ/', 'obey.mp3', 'v.服从，顺从，遵守', '6c235055d69cbf31829a358933eae17b.jpg', 'd_24_6819_0_4_20150808224808.png', 'The dog always obeys its master.', '这只狗总是服从它的主人。', '3d60627fb4468434_1266883322328820606_250207.mp3', 'ob去 + ey听，听见 → obey听从', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2838, 'on one hand', '/ɑːn wʌn hænd/', 'on one hand.mp3', 'phr.一方面', '2044c9ef4c27c056f9cdb418260388c7.jpeg', '', 'On one hand', '一方面，她很想要一只狗；另一方面，她对狗过敏。', 'bb41c1d43ee348151ab77eaf8c701043.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2839, 'on the grounds of', '/ɑn ðə ɡraʊndz ʌv/', 'on the grounds of.mp3', 'phr.以……为理由', '6cc3833dc0b2033391eb73d6351a6601.jpeg', '', 'He ruled out flying on the grounds of it being too expensive.', '因为费用太高的原因，他排除了坐飞机这一选项。', '31649f3c000a8a025089a1fdd8365620.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2840, 'optimal', '/ˈɑːptɪməl/', 'optimal.mp3', 'adj.最佳的，最理想的', 'i_4_1993_0_6_20150808144620-gigapixel-scale.jpg', '20140916_11_52_30_493_v3.png', 'Chopsticks would be the optimal choice to serve noodles.', '筷子是吃面的最佳选择。', 'sa_4_1993_0_6_20150808144620.aac', 'optim最好 + al表示属于...的、具有...性质的 → adj.最佳的；最理想的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2841, 'ownership', '/ˈoʊnərʃɪp/', 'ownership.mp3', 'n.所有权', '05a4a1fd6f4c20703476c86ff65fdd28_160637_1552544457.jpeg', 'd_105_5735_0_2_20150809055117.png', 'The couple have the certificate to prove their ownership of this house.', '这对夫妻拥有房产证可以证明他们对这栋房子的所有权。', 'e1f47d271ecc292f692390e18e32baaa_31205_1552544462.mp3', 'owner所有者 + ship表名词 → ownership所有(权)，所有制', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2842, 'palm', '/pɑːm/', 'palm.mp3', 'n.手掌，手心', 'i_1_4129_0_21_160201115325-gigapixel-scale.jpg', 'd_1_4129_0_2_20150808122403.png', 'She showed me the flower in her palm.', '她给我看了她手心里的花。', '5hltdupsmfnhzffrs6v7g6fvryy7e7uw.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2843, 'physics', '/ˈfɪzɪks/', 'physics.mp3', 'n.物理（学）', 'b49f1fb397534754132614663143046d_207501_1660558795-800-600.jpg', 'd_109_16414_0_2_20150809061132.png', 'He is teaching physics in the classroom.', '他正在教室里教物理。', '21f884ede3fb40b68334e216114d1a34_11643_1550301741.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2844, 'plus', '/plʌs/', 'plus.mp3', 'prep.加，加上；  n.加号；有利因素；  adj.正的', '532e03d22532e2582a677a113d115930_151929_1726307535.jpg', 'd_107_8974_0_2_20150809023930.png', 'One plus one equals two. Hopefully you knew that.', '一加一等于二，希望你知道这个。', 'sa_103_8974_0_3_20150809032716.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2845, 'postage', '/ˈpoʊstɪdʒ/', 'postage.mp3', 'n.邮费，邮资', 'i_1_5359_0_4_150906115308-gigapixel-scale.jpg', 'd_24_5359_0_3_20150808224045.png', 'The postage depends on the weight of your goods.', '邮费由你的物品重量决定。', 'sa_1_5359_0_4_150914162617.aac', 'post邮件，邮政 + age表状态 → 邮寄需要费用 → postage邮资', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2846, 'progress', '/ˈprɑːɡres/', 'progress.mp3', 'n.进步；前进（读作/ˈprɑːɡres/）', 'i_1_7899_0_6_150829100050-gigapixel-scale.jpg', '20141010_01_08_03_679_v3.png', 'The chart showed that we were making progress', '这张图表说明我们在取得进步，销量一年高于一年。', '727d810faa1efbda_1266883488529013436_250207.mp3', 'pro向前，在前 + gress走 → 向前走 → progress进步', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2847, 'promotion', '/prəˈmoʊʃən/', 'promotion.mp3', 'n.提拔，晋升；提升；促销；促进', '09f5f55ba160bd80754c73591f9df48c_75127_1564733798.jpg', '', 'He got a promotion and is now the CEO of the company.', '他在工作中得到了晋升，现在是这家公司的首席执行官。', '7573a4a772b30fa5e8a4f82cffd24355_47982_1564733803.mp3', 'pro向前 + mot移动 + ion名词后缀 → 促进；升级', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2848, 'reflect', '/rɪˈflekt/', 'reflect.mp3', 'v.倒映；反映；仔细思考；反思，反省', 'a3b3a22f3ea5ff318c5f89e80d8384ed_602772_1747104968.jpg', 'd_16_5679_0_2_20150808225701.png', 'The mountains are reflected in the water.', '群山倒映在水中。', 'us_The_mountains_20250513105611397_97710658587dc14d0387.mp3', 're回，向后 + flect弯曲 → 反弯曲 → reflect反射', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2849, 'regular', '/ˈreɡjələr/', 'regular.mp3', 'adj.定期的，有规律的；  n.正式队员', '26d6f6612d6a6953ef426ca9ce5187f2_131450_1739005792.jpeg', 'd_24_8195_0_4_20150808225522.png', 'We have a regular meeting on every Monday morning.', '我们每个星期一早晨都有例会。', '44850657a2e2db59_1266797979163450080_250123.mp3', 'reg国王 + ular……的 → 国王统治的 → regular规则的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2850, 'religion', '/rɪˈlɪdʒən/', 'religion.mp3', 'n.宗教信仰；虔诚的追求', '0107e6a1315914ac3e8542ab17752753_178960_1681094092.jpg', '2ca527d4c21f9554bdf2f3285103c23f_158885_1539341276.png', 'His religion taught him to be kind.', '他的宗教信仰教他要善良。', 'sa_16_8409_0_4_151113142945.aac', 'relig=rely依赖 + ion名词后缀 → 用来依赖的 → religion宗教，宗教信仰', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2851, 'responsible', '/rɪˈspɑːnsəbl/', 'responsible.mp3', 'adj.负有责任的', '936487174ebde4d65df44590c90024f0_140382_1558425052.jpeg', '', 'The dog was responsible for this mess.', '这只狗要对这片混乱负责。', '07ed244379f4dbfb_1266883527634606698_250207.mp3', 'respons回应 + ible能...的 → 能回应的 → responsible有责任的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2852, 'roof', '/ruːf/', 'roof.mp3', 'n. 屋顶；顶部', '17c25f75432a4ae22c155752218ea2f4_100553_1584956982.jpeg', 'd_24_5676_0_4_20150808224251.png', 'There\'s a window and a chimney on this roof.', '屋顶上有一扇窗户和一个烟囱。', '7699dd17139ee8d1_1266883373475518976_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2853, 'run away with', '/rʌn əˈweɪ wɪð/', 'run away with.mp3', 'phr.轻易赢得(比赛等)', 'de24ebe8a9aca6f759336b6f7e979ad2.jpeg', '', 'He ran away with the championship this year.', '他轻松赢得了今年的冠军。', '8864b7e310d4b00740f23e3ac4b91ab5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2854, 'salary', '/ˈsæləri/ ', 'salary.mp3', 'n.工资，薪水', 'd7895cf82241051ff53051a2d58def61_120863_1625798303.jpg', 'd_16_6329_0_2_20150808230553.png', 'They are receiving their monthly salary from Lord Bao.', '他们正在包大人那儿领每月工资。', 'b6967b2d73f2bc8c_1266883380693981810_250207.mp3', 'sal盐 + ary名词后缀 → salary工资（古代工钱以盐多少计算）', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2855, 'score', '/skɔːr/', 'score.mp3', 'n.得分，分数；刻痕；二十；  v.在……上刻痕', '62a0b25482d23c5509c9c5684493dd42_101958_1584459489.jpg', 'd_109_4637_0_2_20150809053706.png', 'Each judge gave him a full score.', '每个评委都给他打了满分。', '08806c6414465a70_1266883115538143960_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2856, 'set down', '/set daʊn/', 'set down.mp3', 'phr.放下', 'a1796672eefb2fde690a8a89326ac38d.jpeg', '', 'He set his schoolbag down on the sofa and turned on the TV.', '他把书包放在沙发上，并打开了电视。', '8587d52c44d2b59109962f4a769367dd_48622_1600072784.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2857, 'shell', '/ʃel/', 'shell.mp3', 'n.壳，外壳；  v.剥壳；炮击', 'i_1_4028_0_2_20150808122243-gigapixel-scale.jpg', '20130510_18_12_52_71.png', 'The egg shell broke in half.', '蛋壳破成了两半。', 'dx4ax4a8dtt6kqrl86aq5xq6b96zw3tn.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2858, 'shoe', '/ʃuː/', 'shoe.mp3', 'n.鞋', '99786e3f5750a0b912d195668b7dcd7f_85735_1577956303.jpeg', 'd_24_19497_0_3_20150809001639.png', 'There are two pairs of sports shoes on the floor.', '地上有两双运动鞋。', '13f8cd30f8872cc3_1268213308434563722_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2859, 'shortage', '/ˈʃɔːrtɪdʒ/', 'shortage.mp3', 'n.短缺，不足，缺少', '67075dbb258d06f2aa8d352a3774e7f7_182714_1595058781.jpg', 'd_107_6658_0_2_20150809020650.png', 'The child is experiencing a shortage of water.', '这个孩子正面临水的短缺。', 'us_The_child_20241009154617884_30f36242fc8876f12f93.mp3', 'short短 + age名词形式 → 不足，缺少', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2860, 'shout', '/ʃaʊt/', 'shout.mp3', 'v.呼喊，大声说，叫；  n.呼喊', 'aadb4845dfd1414bb541f1f09f7be4cb_102249_1578559317.jpeg', 'd_24_16527_0_4_20150808231537.png', 'He cupped his hands around his mouth and shouted loudly.', '他将双手拢在嘴边，大声呼喊。', '66cb1675dbeeef40_1266883009105124008_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2861, 'silk', '/sɪlk/ ', 'silk.mp3', 'n.丝，丝绸', '696de6407e5ce6e1f96b89d79c6efadb_118879_1738994628.jpg', 'd_24_18154_0_3_20150808235040.png', 'The white silk looks so soft.', '这块白色丝绸看上去真柔软。', '758730dd3a562782_1268213309390865330_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2862, 'smooth', '/smuːð/', 'smooth.mp3', 'adj.光滑的，平滑的；平稳的；  v.使......光滑；使......平稳', '3_0_20170930071724_7582_c-gigapixel-scale.jpg', '', 'She said the taste of the chocolate is as smooth as silk. Give me some!', '她说这种巧克力的口感如丝绸般柔滑，给我一点儿尝尝！', '85c0cccf2ccc3496_1266883010534681560_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2863, 'starve', '/stɑːrv/', 'starve.mp3', 'v.挨饿；饿死', '6af0adef41133eb8534f154e91f36b8e_187036_1605165072.jpg', 'd_16_4797_0_2_20150808224437.png', 'This polar bear is starving because it doesn\'t have enough food to eat.', '这只北极熊快饿死了，因为它没有足够的食物吃。', 'ca452781fbbe35f644a5d0bfd9cabcd8_23399_1625799094.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2864, 'steady', '/ˈstedi/', 'steady.mp3', 'adj.坚定的，扎实的；  v.（使）稳固', '3_45_20161228151601_50908_c-gigapixel-scale.jpg', 'd_16_4759_0_2_20150808224406.png', 'The stone house is quite steady under the extreme weather.', '石屋在极端天气下非常稳固。', '3_45_20161228151601_15204_c.aac', 'stead稳定 + y表形容词  → steady坚定的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2865, 'stiff', '/stɪf/', 'stiff.mp3', 'adj.僵直的，酸痛的', 'b97175025d09335a6523f19791fbe136_73646_1565606613.jpg', 'd_1_4104_0_2_20150808122341.png', 'My back is so stiff! the athlete complained.', '“我的背好酸痛啊！” 这位运动员抱怨道。', '1d1b90b273b6c839c4932c5962439f1d_20421_1640587900.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2866, 'supplement to', '/ˈsʌplɪmənt tuː/', 'supplement to.mp3', 'phr.对……的补充', 'cfa7240ef14f402bf664e0fe0fef288d.jpg', '', 'These pills are supplements to natural vitamins.', '这些药丸是对天然维生素的补充。', '25287cfd1c1b89a988118395ef1c1831_44192_1593584370.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2867, 'switch on', '/swɪtʃ ɑːn/', 'switch on.mp3', 'phr.打开（灯、无线电等）', '681103417fa974b271906059a3c66d6e_37206_1750846127.jpg', '', 'Your computer doesn\'t work? Did you switch it on?', '你的电脑不能运行了吗？你开电源了吗？', 'sa_40_20211_0_3_20150809022131.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2868, 'taste for', '/teɪst fɔːr/', 'taste for.mp3', 'n.对 ... 的爱好', '6d00a13737a98706414327d498fcca92.jpeg', '', 'The king has a real taste for precious treasures.', '国王很喜欢奇珍异宝。', 'd99e1ae68b03f7a7b1dda672ab42aeca.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2869, 'taste in', '/teɪst ɪn/', 'taste in.mp3', 'n.对 ... 的审美能力', 'cd623c95556eb9d8b1da0eecf0339bdb.jpeg', '', 'His taste in clothes differs from that of his friend.', '他和他朋友的服装品味不同。', 'b94a89a78bacd6e54dc248e75e8e4464.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2870, 'technology', '/tekˈnɑːlədʒi/', 'technology.mp3', 'n.科技；技术，工艺，工程技术', '5db07733663c027485a413cae61a05b9_203418_1578569114.jpg', 'd_107_6947_0_2_20150809021157.png', 'Now there are more and more technology products in our lives.', '现在我们的生活中科技产品越来越多。', 'xjb9w33yupp6zp9dznay68ajlhk6se7v.mp3', 'techno技术，能力 + logy学说 → 技术，科技', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2871, 'theory', '/ˈθiːəri/', 'theory.mp3', 'n.理论，原理；推测', '45ae0e5bc4da2b5dbe897866f9dfdd4d_175909_1586935286.jpg', 'd_16_6629_0_5_20150808230842.png', 'It can be inferred from his theory that the universe is expanding.', '我们可以从他的理论推测出宇宙在膨胀。', '7f511b257f9d4fa5e0217e7c7728d46f_22302_1623402339.mp3', 'theor思考 + y抽象名词词尾 → theory理论，原理；学说', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2872, 'toast', '/toʊst/', 'toast.mp3', 'n.烤面包，吐司；敬酒；  v.为……干杯', '157464aacad21426f9e2ade353a62849_180984_1552531784.jpeg', 'd_16_6407_0_2_20150808230658.png', 'There are two slices of toast and some butter on the table.', '桌上有两片吐司和一些黄油。', 'u9m3fnd5jlxm9a7tquyqseyj2hhnpj8s.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2873, 'tolerate', '/ˈtɑːləreɪt/', 'tolerate.mp3', 'v.忍受，容忍', 'i_16_6825_0_4_151027112620.jpg', 'd_16_6825_0_2_20150808231132.png', 'They have to tolerate the bad smell in the elevator.', '他们不得不忍受电梯里的臭味。', 'c1d21c20f66fa36eb9308d547768f667_24269_1621930499.mp3', 'toler容忍 + ate动词后缀 → tolerate容忍', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2874, 'tool', '/tuːl/', 'tool.mp3', 'n.工具', 'i_16_17639_0_8_151118120841-gigapixel-scale.jpg', 'd_24_17639_0_4_20150808233131.png', 'We have all kinds of useful tools.', '我们有各种各样的实用工具。', '5d37bfc6960fe83f_1266883375844842094_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2875, 'tortoise', '/ˈtɔːrtəs/', 'tortoise.mp3', 'n.陆龟，龟', '7b5763c5d6c6ed07dd07a3a3897aed42_72486_1715133433.jpg', '20141015_16_12_59_399_v3.png', 'Look', '看，这只乌龟在爬行。', '125083b533f34720_1266741632784226948_250113.mp3', 'tort扭 + o + ise名词后缀 → 乌龟的脚是扭曲的 → tortoise乌龟', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2876, 'treatment', '/ˈtriːtmənt/ ', 'treatment.mp3', 'n.治疗，疗法', 'i_16_4934_0_4_151222191850-manual-scale.jpg', '20130301_12_58_20_604.png', 'She is receiving treatment for a hand injury.', '她的手受伤了，正在接受治疗。', 'v33yg47nyv2rk5dvwpfahzclhtr66nx7.mp3', 'treat处理 + ment名词后缀 → treatment处理，治疗', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2877, 'twice', '/twaɪs/', 'twice.mp3', 'adv.两次', '9451d2e9cdac62b7a8b47847b2a3e40c_202920_1578562557.jpeg', 'd_24_17911_0_3_20150808233434.png', 'I go swimming twice a week.', '我一周游两次泳。', '21b41c1e424ca678_1266763527474535094_250117.mp3', 'twi二，两 + ce副词后缀，…次 → twice二次', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2878, 'valid', '/ˈvælɪd/', 'valid.mp3', 'adj.有效的，正式认可的；合理的，有根据的', 'i_16_8291_0_4_151118130149-gigapixel-scale.jpg', 'd_16_8291_0_2_20150808232822.png', 'The official stamp showed that the document was valid.', '这枚公章证明这份文件是有效的。', '0bb9e9849a02dbae_1266883484622281284_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2879, 'weep', '/wiːp/', 'weep.mp3', 'v.哭泣，流泪；（伤口）化脓', '3_0_20160528173936_26017_c-gigapixel-scale.jpg', 'd_16_2628_0_2_20150808223604.png', 'I could feel his sadness when I saw him weeping.', '当我看到他在哭泣时，我能感受到他的悲伤。', '54mtscu8gb9b925ruvw7utf85ped2l3f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2880, 'weight', '/weɪt/', 'weight.mp3', 'n.重量，分量；  v.使变重', 'i_53_14736_0_4_20150808234553-gigapixel-scale.jpg', 'd_95_14736_0_4_20150809012915.png', 'The weight of the apples you chose is 2 kilos.', '你所选的苹果的重量是2千克。', '8e745031bb4a1cd3_1266883484476332608_250207.mp3', 'weigh称量 + t名词后缀 → weight重量', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2881, 'whom', '/huːm/', 'whom.mp3', 'pron.谁', '3_0_20170608071535_86115_c-gigapixel-scale.jpg', 'd_109_19718_0_2_20150809063905.png', 'Do you know whom the reporters are discussing?', '你知道记者们在讨论谁吗？', '3_0_20170608071535_388_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2882, 'abroad', '/əˈbrɔːd/', 'abroad.mp3', 'adv.到国外，在国外；在户外', '1b37ed589929e482e81b8557c2113457_170843_1565691341.jpeg', 'd_24_7946_0_3_20150808225255.png', 'The two Asian students study abroad together.', '这两个亚洲学生一起出国留学。', '426bedf27d8eda9b_1266798138377329266_250123.mp3', 'a去，到 + broad宽的，广阔的 -> 去广阔的地方 -> abroad到国外', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2883, 'achievement', '/əˈtʃiːvmənt/', 'achievement.mp3', 'n.成就；实现', '1b2f3adde6f5ab0ecd5d1defba64ac04_177061_1544077588.jpeg', 'd_16_7972_0_4_20150808232300.png', 'He is known for his great achievements in the sport of tennis.', '他在网球运动上的成就令人瞩目。', '3cty3frltsj6vvstew4hpwwzqfmea9t3.mp3', 'achieve达成 + ment表示行为、行为的过程或结果 → achievement成就；实现', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2884, 'adequate', '/ˈædɪkwət/', 'adequate.mp3', 'adj.足够的，充分的；尚可的，过得去的', 'f05fb398d5b4b82b4022cff1c6f74ff0_109507_1585129815.jpeg', 'd_107_3931_0_2_20150809003545.png', 'The meal would not feed a family', '这一餐不够一家人吃，但够两个人的量。', '11132f02ce1f5e8007a2468669a023bf_50144_1597653234.mp3', 'ad加强意义 + equ相等 + ate…的 → 与所要求的相等 → adequate足够的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2885, 'advertisement', '/ˌædvərˈtaɪzmənt/', 'advertisement.mp3', 'n.广告；登广告', '3_0_20170709071144_82043_c-manual-scale.jpg', 'd_24_18807_0_4_20150808235824.png', 'This advertisement is used to promote a new product.', '这则广告的目的是推广新产品。', 'd93bbc87d0f4261929b46e1a42dec951_18697_1623812027.mp3', 'advertise做广告 + ment表名词 → advertisement广告', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2886, 'affected', '/əˈfektɪd/', 'affected.mp3', 'adj.受到影响的，受（疾病）侵袭的', '8fd1272e98411cab67528f3442244e44_446146_1701667510.jpg', '', 'They were really affected by the movie.', '他们确实被电影感动了。', 'sa_4_88_0_2_20150808142241.aac', 'affect感动 + ed形容词后缀 → affected 感动的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2887, 'aid', '/eɪd/', 'aid.mp3', 'n.帮助；救护；  v.援助，帮助', 'e66570925a7438fcbb0d80ed3279e724.jpg', 'd_16_106_0_7_20150808223144.png', 'The blind man walks with the aid of a guide dog.', '那个盲人在导盲犬的帮助下走路。', 'baf160bd3704091045cbd3b19b61d5e0_44576_1596782539.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2888, 'airline', '/ˈerlaɪn/', 'airline.mp3', 'n.航空公司；  adj.航空公司的，航线的', 'c6764026b966d3f51d48a492df13a803_75633_1656664447.jpg', 'd_109_16424_0_2_20150809061139.png', 'The plane of this airline has some red paint at the bottom.', '这个航空公司的飞机底部有一些红色的油漆。', 'us_The_plane_20220712151934055_9b627a2e278fc2c5a5bc.mp3', 'air空气，空运 + line直线 → airline航空系统，航线', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2889, 'alarm', '/əˈlɑːrm/', 'alarm.mp3', 'n.警报器，警报；  v.使惊恐，使忧虑', 'e9e3808c0798d0adab97982dfe10fe02_97282_1706767614.jpeg', 'd_16_6327_0_2_20150808230551.png', 'He switched off the fire alarm.', '他关闭了火警警报器。', '2dcd38c5dcbaea56_1266883380732189302_250207.mp3', 'a=to朝着，去 + l=the + arm武器 → 拿起武器，准备战斗 → alarm警报', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2890, 'alive', '/əˈlaɪv/', 'alive.mp3', 'adj.活着的，在世；活跃的，有生气的', 'i_16_10986_0_4_151116091540-gigapixel-scale.jpg', 'd_24_10986_0_3_20150808230528.png', 'His beating heart shows that he is alive.', '跳动的心脏表明他还活着。', 'f79ec73344deee1f_1266883529369737870_250207.mp3', 'a…的 + live活 → alive活的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2891, 'amount', '/əˈmaʊnt/', 'amount.mp3', 'n.数量；  v.总计', '3_0_20170714071334_35984_c-gigapixel-scale.jpg', 'd_16_3852_0_2_20150808223724.png', 'The amount of sugar in this product is 28g.', '这一产品中糖的总量是28克。', '8qemuzxmbnr5k6rhqf6cwbbuhwfcbktj.mp3', 'a去，往 + mount山顶 → 去山顶 → amount总计', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2892, 'appearance', '/əˈpɪrəns/', 'appearance.mp3', 'n.外貌，外表；出现，公开露面', 'c0f16eaae54d50640d1991138f156127_50972_1752817247.jpg', 'd_16_5604_0_7_20150808225539.png', 'She is checking her appearance in the mirror.', '她正在对着镜子检查自己的外表。', 'd7b5ae28dd7067d1_1266883115701590750_250207.mp3', 'appear出现，显露 + ance性质，状况 → 显露出的性质 → appearance外貌 ', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2893, 'apply', '/əˈplaɪ/', 'apply.mp3', 'v.涂，施于；申请', 'c6e4798b65c6c1beb57de4b3a9f1bb00_87605_1533024011.jpeg', 'd_16_7116_0_2_20150808231500.png', 'Don\'t forget to apply sunscreen if you spend time out in the sun.', '如果你要长时间待在太阳下，一定别忘记涂防晒霜。', 'ce32f4901114bc5430ee03a292902758_47717_1533024025.mp3', 'ap去 + ply应用 → 去运用起来 → apply申请，应用', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2894, 'as for', '/əz fɔːr/', 'as for.mp3', 'phr.至于，就…方面说，关于', '08b04e2f7b61180024796da1b4a0acb9_87874_1701668799.jpg', '', 'As for our market share', '就我们的市场份额来说，它正在下降。', 'sa_11_10930_0_2_20150808180611.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2895, 'as usual', '/æz ˈjuːʒuəl/', 'as usual.mp3', 'phr.通常，平常地，像往常一样', '45eb7f20493fac8c7662877530df0e6e_192499_1578103960.jpeg', '', 'As usual', '和往常一样，他去咖啡店买了一杯咖啡。', '675ff3b17479e51d_1266883112100932484_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2896, 'at present', '/æt ˈprɛzənt/', 'at present.mp3', 'phr.现在；目前', '446086e859f835f5e43b9c25c8b80bdc_186452_1605176152.jpg', '', 'At present I\'m free', '目前我有空，但十分钟后我有个会议。', 'fb7b0b677edcc51d_1266883324889225920_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2897, 'attend', '/əˈtend/', 'attend.mp3', 'v.护理，照顾；处理；参加', '3411986852166300e44f1bb1bdd154d0_163484_1524036634.jpg', 'd_24_5147_0_4_20150808223945.png', 'A nurse is attending to the newborn baby.', '一位护士正在照顾新生的宝宝。', 'c871c60b659ad84d9f77ac153aced5a3_12740_1551755637.mp3', 'at=ad，to + tend延伸 → 把思维延伸到 → 关注，引申为期待某人到达，后来又引申为到达 → attend出席', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2898, 'bachelor', '/ˈbætʃələr/', 'bachelor.mp3', 'n.学士；单身汉', '0f417bbfa295dced900e0b1a1cbe510f_20490_1523676450.jpg', 'd_107_4812_0_2_20150809010836.png', 'After four years of hard work', '经过四年的努力学习，我终于拿到了我的学士学位！', 'us_After_four_20230814143633830_a86a8e75c714252c7141.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2899, 'belong', '/bɪˈlɔːŋ/', 'belong.mp3', 'v.属于，附属', 'f2f0075924321800e15a9c565fb007e6_18251_1728895966.jpg', 'd_24_9749_0_3_20150808230253.png', 'A belongs to B.', 'A属于B。', 'wk7h95mxwu3j46s8nkf8xrhm7ygpq79u.mp3', 'be使 + long长 → 使长久拥有 → belong属于', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2900, 'belong to', '/bɪˈlɔŋ tu/', 'belong to.mp3', 'phr.属于', 'belongto_10451_20231106_491da101.jpg', '', 'This teddy bear belongs to me. ', '这个泰迪熊是我的。', 'us_This_teddy_20250421094806898_4a3251c52a3a933537f8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2901, 'beneath', '/bɪˈniːθ/', 'beneath.mp3', 'prep.在……下方；  adv.在下方', 'c_i_wm_20120210_02_44_58_695-gigapixel-scale.jpg', 'd_24_312_0_4_20150808223116.png', 'Most of the iceberg is beneath the sea surface.', '冰山的大部分在海面之下。', 'b4e62ace9933f82b_1266883625984612906_250207.mp3', 'be是 + neath下面 → beneath在下面', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2902, 'bonus', '/ˈboʊnəs/', 'bonus.mp3', 'n.奖金，额外津贴', 'i_2_4107_0_3_20150808142548-gigapixel-scale.jpg', 'd_107_4107_0_2_20150809004430.png', 'Compared to others', '和其他人相比，他的年终奖很特别。', 'd3682b58113ea522d900e8cc4d6b1377_22772_1619161691.mp3', 'bon好 + us用 → 用好的东西进行奖励 → 奖金，红利', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2903, 'branch', '/bræntʃ/', 'branch.mp3', 'n.树枝；分支', 'i_1_5621_0_4_150928154844-gigapixel-scale.jpg', 'd_16_5621_0_2_20150808225600.png', 'The man cut off a branch from the tree.', '那个男人从树上剪下了一根树枝。', 'sa_1_5621_0_4_151017093657.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2904, 'break down', '/breɪk daʊn/', 'break down.mp3', 'phr.（机器等）发生故障，抛锚；（精神）垮下来', 'bb0f58359aa509f6d46df868fb0e35f8_283414_1610102028.jpg', '', 'The man\'s car broke down', '这个男人的车抛锚了，所以他不得不停下来寻求帮助。', 'us_The_mans_20250214171738910_17408c9bd4c1b92754cd.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2905, 'break into', '/breɪk ˈɪntʊ/', 'break into.mp3', 'phr.闯入；碰到；发现', '218b3faba9487ebdefc1e9b89bd98e1a.jpg', '', 'The thief was arrested for breaking into a car.', '这个小偷因橇车而被捕。', '9e3a95a5f0097c84_1266797982948829986_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
