INSERT INTO `words` VALUES (2908, 'calendar', '/ˈkælɪndər/', 'calendar.mp3', 'n.日历，挂历；日程表；历法', '57be2dc0f56a1d428660caabe8e76949_160564_1729759517.jpg', 'd_105_5447_0_2_20150809054732.png', 'The month is over', '这个月结束了，是时候翻到日历的下一个月了。', 'sa_1_5447_0_2_20150808123850.aac', 'calend每月第一天 + ar表名词 → calendar日历', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2909, 'call for', '/ˈkɔl fɔr/', 'call for.mp3', 'phr.需要；呼吁', '4f415ce5e9fb62bddfa1496bc57128d1_199547_1580883165.jpg', '', 'This dish calls for two eggs.', '这道菜需要两个鸡蛋。', 'c79d99c67a90290b21128011645ac0a1_33934_1580883158.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2910, 'camera', '/ˈkæmərə/', 'camera.mp3', 'n.照相机，摄影机', '655e8ba8c2b3d1db3e85f2123df2582e_70151_1574827282.jpeg', 'd_109_16524_0_2_20150809061346.png', 'She is able to take high quality photos with that camera.', '她能用那台照相机拍出高质量的照片。', '6d0d062e63dff00f_1266763246127897106_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2911, 'Canadian', '/kəˈneɪdiən/', 'Canadian.mp3', 'adj.加拿大的', '7da16624fa46c40f16e066e2944336ad_185524_1541663387.jpeg', 'd_109_6277_0_2_20150809054607.png', 'The Canadian flag is waving under the blue sky.', '加拿大国旗在蓝天下飘扬。', '0ba68656978f206cfb070dc010647975_18070_1640244471.mp3', 'Canad=Cananda加拿大 + ian属于某国的，人或语言 → Canadian加拿大的（人）', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2912, 'carefully', '/ˈkerfəli/', 'carefully.mp3', 'adv.小心地，谨慎地', 'c1da0ceda9b3c23b6b81b697899a287d_99904_1587631928.jpeg', '', 'He pulled out the block very carefully.', '他小心地抽出了这个木块。', 'ed5100dcfa26e532_1266797983849404982_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2913, 'challenge', '/ˈtʃælɪndʒ/', 'challenge.mp3', 'n.挑战；质疑；  v.挑战', 'ba6e2c3eb321f2135fa1f829b1f550d7_93300_1580974214.jpg', 'd_24_5548_0_4_20150808224130.png', 'Walking on the tightrope is a big challenge for him.', '走钢丝对他来说是个很大的挑战。', '5cyccyhezfmjqcaxx6bqz5mdb9wp6h6j.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2914, 'champagne', '/ʃæmˈpeɪn/', 'champagne.mp3', 'n.香槟酒', '3b78285330b8bed04c1e755aa5def9bd_76523_1566894318.jpg', '20140829_00_55_44_483_v3.png', 'To celebrate', '我们开一瓶香槟酒来庆祝吧！', 'sa_2_4037_0_3_20150808142430.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2915, 'check on', '/tʃek ɑːn/', 'check on.mp3', 'phr.检查（以确保一切正常）；核实，调查', 'ecbb8c4ad703d93bd441c6f5a20222eb.jpeg', '', 'He checked on his child twice during the night.', '他夜里查看了孩子两次。', 'us_He_checked_20241009154553869_73b0fb07e05976662200.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2916, 'clean', '/kliːn/', 'clean.mp3', 'v.打扫；  adj.清洁的，干净的；  n.清洁', '20120926_03_21_07_28-manual-scale.jpg', 'd_24_2782_0_3_20150808223317.png', 'The man has been cleaning the house the whole afternoon.', '这个男人一整个下午都在打扫房子。', '228dv2jxl8qkrm9he4lpkm54fpvmdpsn.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2917, 'climb', '/klaɪm/', 'climb.mp3', 'v.攀登，爬；  n.攀爬', '20120524_15_13_29_922-gigapixel-scale.jpg', 'd_24_8009_0_3_20150808225340.png', 'I don\'t think I could climb that mountain.', '我觉得我攀不上这座山。', 'e7030f3d2846e39f_1266883004095965982_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2918, 'compensate for', '/ˈkɑmpənˌseɪt fɔr/', 'compensate for.mp3', 'phr.弥补', 'b68da30c86f4a2fc1c80b6d0de286b01_151703.jpg', '', 'The insurance company paid him some money to compensate for his accident.', '保险公司给了他一些钱来对他的事故做出赔偿。', 'us_The_insurance_20241009155329984_f15dcd1cd04e188ff379.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2919, 'competitive', '/kəmˈpetətɪv/', 'competitive.mp3', 'adj.努力竞争的；好胜的，一心求胜的；有竞争力的', 'df31a1b6f5e9704c6c5316a054c9026d_86462_1565341801.jpg', 'd_18_5694_0_2_20150808184807.png', 'The soccer game was really competitive.', '这场足球赛真的很有竞争性。', 'sa_1_5694_0_2_20150808124231.aac', 'compet=compete竞争 + itive..的 → competitive有竞争力的；竞争的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2920, 'compound', '/ˈkɑːmpaʊnd/', 'compound.mp3', 'n.【化学】化合物；复合物；  adj.合成的；复合的；多功能的（读作/ˈkɑːmpaʊnd/）；  v.妥协；和解；  v.混合；调和；调停；使恶化（读作/kəmˈpaʊnd/）', '0a2c119953dfd4d703acdb99670e73ec_173302_1572858635.jpg', 'd_1_14973_0_4_20150808131921.png', 'The science teacher is teaching about chemical compounds.', '理科老师正在课堂上讲化学化合物。', '76346d366a79f5bcde98d8e51a4790cd_28270_1565695353.mp3', 'com一起 + pound放 → compound 混合物', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2921, 'confidence', '/ˈkɑːnfɪdəns/', 'confidence.mp3', 'n.信心', 'df18a6b5f902ef3d54cf7f46c445228d_135382_1558425206.jpeg', 'd_24_7903_0_4_20150808225211.png', 'The student raised her hand with confidence to answer the question.', '这个学生自信地举起手回答问题。', '44457c06d0957a13_1266883489823087310_250207.mp3', 'con全部 + fid相信，信念 + ence名词后缀 → 全部相信 → confidence自信，信任', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2922, 'confidence in', '/ˈkɑːnfɪdəns ɪn/', 'confidence in.mp3', 'phr.对……的信心', 'f721ece284ce44e5ac2403e6d565651c.jpg', '', 'The soccer player has confidence in himself.', '这位足球运动员对自己有信心。', 'ac33bd139b6544689a147f62c92bd5c9_43808_1593575493.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2923, 'congress', '/ˈkɑːŋɡrəs/', 'congress.mp3', 'n.国会；代表大会；议会；立法机关', '1fb18a037988b060c2e3a5c4da4d2d0d_83197_1573898444.jpeg', 'd_106_3894_0_2_20150809064916.png', 'A congress is a legislative body that discusses national policies.', '国会是讨论国家政策的立法机构。', 'us_A_congress_20241009155532300_b5b8db65728aee01a630.mp3', 'con共同 + gress行走 → 走到一起 → congress代表大会', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2924, 'connection between', '/kəˈnekʃn bɪˈtwiːn/', 'connection between.mp3', 'phr.……之间的联系', '9d48bbff05914627b1b15a1cc8515c4f.jpg', '', 'There\'s a strong connection between food and health.', '食物和健康之间有着强烈的联系。', 'b4883b8021d5c5ffe6b6e3dee57b19ef_46112_1593575508.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2925, 'contribute to', '/kənˈtrɪbjuːt tuː/', 'contribute to.mp3', 'phr.有助于', '397cee53d8e550f11dcae0b158a54361_164821_1549957257.jpeg', '', 'A balanced diet and moderate exercise contributed to her good figure.', '均衡的饮食和适度的锻炼有助于她塑造好身材。', 'd990c558842c9c55bcd38372681a8804_31289_1621926716.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2926, 'convert', '/kənˈvɜːrt/', 'convert.mp3', 'v.可转变为，可变换成；改变，转变，转化；使改变信仰', 'db11ddfbc1eca3869991cfbc0e018d1b_110409_1701053206.jpg', 'd_107_4502_0_2_20150809005827.png', 'Cool! The sofa can be easily converted into a bed.', '真棒！这张沙发轻轻松松就能变成一张床。', 'fc9eb7698cec2629_1266883488419109560_250207.mp3', 'con共同 + vert转变 → 共同转 → 转化；改造', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2927, 'core', '/kɔːr/', 'core.mp3', 'n.核心，要点；果心，核；  adj.核心的，主要的；骨干的；必修的；  v.去核', '76688db77acf0b1eb0ed1a9d984aec0b_83237_1576288555.jpg', 'd_107_5722_0_2_20150809013622.png', 'The Earth\'s core is hot.', '地心的温度很高。', '5a8sudz835qvfaqyqjqzggpnuq9fsuen.mp3', 'cor心脏 + e → core果实的心，核心', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2928, 'could not help', '/kʊd nɑːt help/', 'could not help.mp3', 'phr.不得不', 'a05f625db751d31f4c6b656cbde23c75.jpg', '', 'Although his mother told him not to', '尽管他妈妈告诉他不能这么做，他还是忍不住把整个蛋糕吃光了。', 'us_Although_his_20231227133346216_ad5bc06aaa1f1177e8d8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2929, 'curious', '/ˈkjʊriəs/ ', 'curious.mp3', 'adj.好奇的；好管闲事的', 'eefd9a68fdcb652e0516ae51954f0092_74552_1567740776.jpg', 'd_16_5835_0_2_20150808225925.png', 'The cat is curious about the black mouse.', '这只猫对这个黑色鼠标感到好奇。', 'dduq5ct94b83m7hb6trptpt29ysr9g39.mp3', 'curi好奇 + ous形容词后缀 → curious好奇的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2930, 'deceive', '/dɪˈsiːv/', 'deceive.mp3', 'v.欺骗，行骗', '25e2ba513258aac3953c1f78195d87a7_42709_1703148371.jpeg', 'd_1_4801_0_3_20150808123039.png', 'The man deceives others by wearing a hilarious mask.', '这个男人用一张搞笑面具来欺骗别人。', '81e40d84aa1030acd9a221b52a255e43_16815_1540004906.mp3', 'de相反 + ceive拿，抓，握 → deceive欺骗', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2931, 'decide', '/dɪˈsaɪd/', 'decide.mp3', 'v.对...做出抉择，决定，下决心', 'fe4d533f59a63be87afd1cb72e62d3ba_47778_1621937968-gigapixel-scale.jpeg', '20130307_16_47_56_299.png', 'It\'s time to decide which way to go.', '是时候决定走哪条路了。', 'a623a8d6fd101950_1266883195961301526_250207.mp3', 'de使…成为 + cide切 → 切下去 → 下决心 → 决定，决心', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2932, 'die down', '/daɪ daʊn/', 'die down.mp3', 'phr.变弱', 'be856266326064cb94c674a4df411790.jpg', '', 'The fire died down and eventually went out.', '火渐渐变弱，最终熄灭了。', 'febc1d6f3b73ba9464cf74f09e5b91d9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2933, 'dot', '/dɑːt/', 'dot.mp3', 'n.点，圆点；  v.点缀', '9279b672c150a6ac52fe4be9e17453fd_94674_1566014392.jpeg', 'd_16_4728_0_2_20150808224350.png', 'Ladybugs have several black dots on their backs.', '瓢虫的背上有一些黑色圆点。', 'ce69d39127054a535efea28b95346cee_41278_1570783839.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2934, 'economic', '/ˌiːkəˈnɑːmɪk/', 'economic.mp3', 'adj.经济上的，经济学的', 'b19524684ca3cd278760cffcec64ca1d_50364_1585116779.jpeg', 'd_107_3841_0_2_20150809003107.png', 'It is important to keep a balance between economic development and environmental protection.', '在经济的发展和环境的保护之间保持平衡是非常重要的。', 'e44cb91f2f103d9fe9419af86e21d689_45166_1585116784.mp3', 'eco经济 + nom学术领域 + ic……的 → 经济的，经济学的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2935, 'economy', '/ɪˈkɑːnəmi/ ', 'economy.mp3', 'n.经济', 'i_1_6957_0_3_20150808125652-gigapixel-scale.jpg', 'd_1_6957_0_3_20150808125652.png', 'The economy is improving and people have more money.', '经济正在改善，人们也有了更多的钱。', 'sa_1_6957_0_3_20150808125652.aac', 'eco环境，经济 + nomy学术领域 → economy经济（学）', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
