INSERT INTO `words` VALUES (2937, 'emergency', '/iˈmɜːrdʒənsi/', 'emergency.mp3', 'n.紧急情况，突发事件', '8c9cbd2113336f84decad92298096b99_105657_1620812980.jpg', '20141010_00_30_59_800_v3.png', 'It\'s an emergency; get her to the hospital as soon as possible.', '情况紧急，尽快送她去医院。', '8rpcl5nwpk9lat4hcq8c3mmwd8gdpjed.mp3', 'e出 + merg沉，没 + ency名词后缀 → emergency突然出现的事情', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2938, 'encourage', '/ɪnˈkɜːrɪdʒ/', 'encourage.mp3', 'v.鼓励，支持', '2a1800bb1e712c68a2e3dca98a6681c7_93664_1736142731.jpg', 'd_93_12561_0_4_20150809002011.png', 'The boy’s grandmother encourages him to play the drums.', '男孩的外婆鼓励他打鼓。', 'us_The_boys_20250106135222023_5c9d2d62bde40a3db50b.mp3', 'en加强 + courage内心的力量=勇气 → encourage鼓励', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2939, 'enhance', '/ɪnˈhæns/', 'enhance.mp3', 'v.提高（强度、力量、数量等）；增加，加强', '6c29b1a23ec7ba90b4f37acbf894c27c_159987_1569030469.jpeg', 'd_107_10264_0_2_20150809025046.png', 'Clicking this button can enhance the video quality.', '点这个按钮可以提高画质。', 'ca5f2fcece56c5b53076eb68762565e5_18070_1625797491.mp3', 'en使... + hance高 → enhance提高', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2940, 'escape', '/ɪˈskeɪp/', 'escape.mp3', 'v.逃跑，逃脱；  n.逃跑，逃脱', '5b65abdcae3b7ff59df51525882b543f_39030_1734424257.jpg', 'd_24_7922_0_4_20150808225234.png', 'The bird escapes from the cage.', '小鸟逃出了鸟笼。', 'uvu3dd3pzgv4l5ayhu4s7xqy6x5hk2qb.mp3', 'es向外 + cape帽子，斗篷 → 从斗篷里钻出来 → escape逃跑，逃脱', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2941, 'expenditure', '/ɪkˈspendɪtʃər/', 'expenditure.mp3', 'n.花费，支出，消耗', 'f8e2504bc3be943739076a86f2a6d20e_186982_1564741121.jpg', '20140820_20_58_02_811_v3.png', 'The pie chart shows my monthly expenditure.', '这张饼状图显示了我每月的支出。', '6ed57b96b635f0f3e627e7acc9d85a92_46624_1564741105.mp3', 'ex出 + pendi=pend花费 + ture表名词 → expenditure支出，开销', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2942, 'experiment', '/ɪkˈsperɪmənt/ ', 'experiment.mp3', 'n.实验；试验；  v.进行实验', 'b08babfcb3b604833d7915fa9e433594_87411_1565342239.jpg', 'd_24_7974_0_4_20150808225315.png', 'There are many scientists doing experiments to find a cure.', '为了找到治疗方法，许多科学家在进行实验。', '85e9b5ec578bd872_1266883195018980340_250207.mp3', 'ex出 + peri尝试 + ment名词后缀 → experiment实验', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
