INSERT INTO `words` VALUES (2944, 'faith', '/feɪθ/', 'faith.mp3', 'n.宗教信仰；信心；信任', 'b0249ada14e857eb1c0eae15557e571a_201884_1585122320.jpeg', '567de4088b288719317688ef94dc2e08_13350_1551253568.png', 'Many people go on an annual pilgrimage to this sacred place to express their faith.', '很多人每年会到这个神圣的地方来参拜，以表达他们的信仰。', '55df17e1b65aefc9171be5294a9a61be_47896_1585122287.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
