INSERT INTO `words` VALUES (2957, 'happiness', '/ˈhæpinəs/', 'happiness.mp3', 'n.幸福，快乐', '3_0_20170721071540_32574_c-manual-scale.jpg', '20121225_18_38_50_882.png', 'The family are sharing a moment of happiness together.', '这家人正在一同享受幸福时光。', 'dw7kee4crcnrjzxljs75nm3hyu3rahkq.mp3', 'happi=happy快乐 + ness表名词 → happiness幸福，快乐', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2958, 'help oneself to', '/help wʌnˈself tu/', 'help oneself to.mp3', 'phr.请随便吃点', '3_0_20170712071243_11684_c.jpg', '', 'Help yourself to anything on the table.', '桌上的东西请随便吃。', '3_0_20170712071243_83489_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
