INSERT INTO `words` VALUES (2961, 'humour', '/ˈhjuːmər/', 'humour.mp3', 'n.幽默感；  v.使自己适应', 'i_13_6208_0_2_20150808185931.jpg', '', 'Women love men with a good sense of humour.', '女性喜欢有幽默感的男性。', 'sa_13_6208_0_2_20150808185931.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2962, 'ice', '/aɪs/', 'ice.mp3', 'n.冰块；  v.冰镇', 'bfed03663b736663dfb5a98238b2afb6_88933_1577953690.jpeg', 'd_24_17732_0_3_20150808233338.png', 'She is holding some ice in her hands.', '她手里捧着一些冰。', 'w8yt5u2h6ftrmdzdxtlgr383kv24dtga.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2963, 'impose on', '/ɪmˈpoʊz ɑn/', 'impose on.mp3', 'phr.把……强加于', '4d695d5cd6a974217e0fa47dc38e6c81.jpg', '', 'He imposed his own failed aspiration on his son.', '他把自己未实现的志向强加给了儿子。', '31dac476666b7031f0d50b41707f1758.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2964, 'impress', '/ɪmˈpres/', 'impress.mp3', 'v.给……留下深刻印象', '15a12344a3eecb2741662031c9b70282_98538_1699413234.jpg', '20121225_18_22_50_260.png', 'She impressed the foreigners with her costume.', '身着古装的她给外国人留下了深刻印象。', 'us_She_impressed_20231108111409972_d221873613048ecb4c7d.mp3', 'im入，向内 + press挤压 → 压进去 → 印入头脑 → impress 使有印象，使铭记', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2965, 'impress on', '/ɪmˈpres ɑn/', 'impress on.mp3', 'phr.给……留下深刻印象', '87db3ca7ec1bf7a335649b9f853733df.jpg', '', 'The woman\'s beauty had impressed itself on her memory.', '那位女士的美丽给她留下了深刻的印象。', 'be94ece47002075e659ab0d292873208.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2966, 'improvement in', '/ɪmˈpruːvmənt ɪn/', 'improvement in.mp3', 'phr.改善，提升', '8bffbe228239540e3eaf561c2a948da9.jpeg', '', 'There has been a clear improvement in the patient\'s condition. ', '这位病人的情况有了明显的改善。', '292f607cf7169ceaa60108f6fb521fa4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2967, 'in hand', '/ɪn hænd/', 'in hand.mp3', 'adv.在控制中；可以动用的', '4673d2e31c6cd75c13f0da95bf9670bd_190074_1588932568.jpeg', '', 'He acts calm and confident because he has the situation in hand.', '他看起来冷静而自信，因为局势尽在他掌握之中。', 'd574d2bcf996bc4def901e2649458cac_48564_1588932565.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2968, 'in memory of', '/ɪn \'meməri əv/', 'in memory of.mp3', 'phr.作为对……的纪念，追念', '45f81fc7e7d0d8adcc13bbf42d71329c.jpg', '', 'I named this boat in memory of my wife.', '为纪念我的妻子，我以她的名字命名了这条船。', '15c4a61caf55b2121108ecd4dae22009.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2969, 'in return for', '/ɪn rɪˈtɜːrn fɔːr/', 'in return for.mp3', 'phr.作为……的报答', 'e2b098549f427279aa84d9fc874f0f16.jpeg', '', 'He gave her some oranges in return for a little help pushing the car up the hill.', '他送了她一些橙子以答谢她帮忙把车推上坡。', 'us_He_gave_20241009151541309_139cf0fd6a1913beb9b3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2970, 'in touch with', '/ɪn tʌtʃ wɪð/', 'in touch with.mp3', 'phr.与……保持联系', '5e58f3ff545d0c3641613bfca0d80eec.jpeg', '', 'She stays in touch with her friends and family. ', '她与朋友和家人保持着联系。', '34d57c80c81fe2a79be21ae46f17819f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2971, 'integrate', '/ˈɪntɪˌɡreɪt/', 'integrate.mp3', 'v.（使）成为一体，（使）合并', '3_18_20161207165021_44555_c-gigapixel-scale.jpg', '', 'Our department\'s four teams must integrate together to work on new projects.', '我们部门的四个小组必须合力推进新项目。', '3_18_20161207165021_58291_c.aac', 'integr完整 ＋ ate使… → 使…完整 → integrate使一体，使结合', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2972, 'issue', '/ˈɪʃuː/', 'issue.mp3', 'n.问题；发行物；  v.发行；公布，发布', '66c60697d096ae200128b8d42ee81af5_143383_1627971200.jpg', '20130510_18_17_40_177.png', 'Food standards for fish are an important issue being talked about in the news.', '鱼类食用标准成了最近新闻讨论的重要问题。', 'f099f47f09b8061801b0378f10915a9a_50072_1597654095.mp3', 'is=ire行走 + sue=ex出，向外  → 向外走  → issue发行；流出', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2973, 'jealous', '/ˈdʒeləs/', 'jealous.mp3', 'adj.妒忌的，吃醋的', '5c534f42f876c116c1ebd2ce11cd039f_111680_1732003887.jpg', '20141009_02_38_18_576_v3.png', 'The dog was jealous that his friend had ice cream.', '这只狗嫉妒他的朋友有冰淇淋。', '19fdbf435eed9825_1266883529838930818_250207.mp3', 'jeal=zeal热心 + ous形容词后缀 → 对…热心而得不到 → jealous妒忌的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2974, 'juice', '/dʒuːs/', 'juice.mp3', 'n.（水果等）汁，果汁', 'i_67_13195_0_4_20150809024115-gigapixel-scale.jpg', 'd_67_13195_0_4_20150809024115.png', 'Fresh orange juice tastes better than the kind you can buy in a store.', '新鲜的橙汁比商店买的好喝多了。', 'sa_67_13195_0_4_20150809024115.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2975, 'July', '/dʒuˈlaɪ/', 'July.mp3', 'n.七月', '0e117697ec9b3dfb32d9f1f62618c62c_118410_1736403059.jpg', 'd_24_17545_0_3_20150808232939.png', 'It\'s July 1st. The summer holiday begins today!', '今天是7月1日，暑假从今天开始啦！', 'sa_16_17545_0_4_151221155328.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2976, 'lack', '/læk/', 'lack.mp3', 'n.缺乏，短缺；  v.缺乏', 'i_1_6960_0_3_20150808125655-gigapixel-scale.jpg', '20121225_19_45_06_576.png', 'The area is in an extreme lack of water resources.', '这个地区极度缺乏水资源。', 'sa_1_6960_0_3_20150808125655.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2977, 'lamp', '/læmp/', 'lamp.mp3', 'n.灯，台灯', 'i_16_17645_0_4_151117152818-gigapixel-scale.jpg', 'd_24_17645_0_3_20150808233141.png', 'An oil lamp burned in darkness.', '一盏油灯在黑暗中燃烧。', 'eba6af02288ffc6d_1266741814966135578_250113.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2978, 'lazy', '/ˈleɪzi/', 'lazy.mp3', 'adj.懒惰的，懒散的', '72696a0150f51bc374677bac9d8b2c77_55894_1731911357.jpg', 'd_24_8509_0_3_20150808225754.png', 'He is too lazy to go to school.', '他太懒了，不想去上学。', 'h7l9wktx2hzjhbs5htlxdhrzj4r93hea.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2979, 'make up for', '/meɪk ʌp fɔr/', 'make up for.mp3', 'phr.补偿，弥补', '4b8328150fe570f9b6eb6c2a10e7014a_188485_1574403296.jpeg', '', 'He wanted to make up for arguing with her by giving her a gift.', '他想给女朋友送个礼物作为和她吵架的弥补。', '8b56857ce6b9755fbeab6a9205a75ecc_36553_1574403292.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2980, 'maximum', '/ˈmæksɪməm/', 'maximum.mp3', 'n.最大值；最大限度；  adj.最大的', '2e3c339eea229966007aa4f69ba9aa40_100156_1579336519.jpeg', 'd_16_4710_0_4_20150808224343.png', 'It will reach 300 km/h which is the maximum.', '速度将达到最大值每小时300千米。', 'us_It_will_20230818154617607_6a07b70772345b55b9e3.mp3', 'maxi=max大的 + mum表名词 → maximum最大的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2981, 'mechanism', '/ˈmekənɪzəm/', 'mechanism.mp3', 'n.机械装置', '4a3a247aca81100e08606742be928b65_110902_1565262727.jpg', 'd_107_3952_0_2_20150809003645.png', 'A watch\'s mechanism is very complicated.', '手表内部的机械装置是很复杂的。', 'sa_1_3952_0_2_20150808122130.aac', 'mechanic机械的 + ism主义，思想 → mechanism机械装置', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2982, 'medical', '/ˈmedɪkl/', 'medical.mp3', 'adj.医学的，医疗的', '7385a139030700464d931507bd5b8a76_180158_1571024361.jpeg', 'd_24_4972_0_4_20150808223745.png', 'There is a lot of medical equipment in the operating room.', '手术室里有很多医疗器材。', '13e3da5350b554c8e7b88a75909ce5cc_37360_1571024354.mp3', 'medic医师 + al...的 → medical医学的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2983, 'modest', '/ˈmɑːdɪst/', 'modest.mp3', 'adj.谦虚的；端庄的', '3_0_20170703171623_59438_c.jpg', '', 'These two businessmen may be rich', '这两位企业家也许富有，但他们仍然很谦虚。', '3_0_20170703171623_57965_c.aac', 'mod模式 + est → 采取合适的模式 → modest谦虚的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2984, 'motive', '/ˈmoʊtɪv/', 'motive.mp3', 'n.动机，目的；  adj.发动的，运动的；  v.引发，促进，激发', 'eb811a42b32d231a5328869e3ac95428_93843_1580958823.jpg', 'd_1_1894_0_3_20150808121754.png', 'His motive for participating in the competition was to win the championship.', '他参加比赛的动机是拿冠军。', '1c57658af595ca6adeea48dad64a3475_26847_1626059631.mp3', 'mot移动 + ive名词后缀 → motive动机', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2985, 'nervous', '/ˈnɜːrvəs/', 'nervous.mp3', 'adj.紧张的，焦虑不安的', 'i_16_5759_0_7_151118114412-gigapixel-scale.jpg', '20141014_08_30_22_647_v3.png', 'The father is nervous about his baby\'s birth.', '这个父亲因为宝宝的出生很紧张。', '13d862827b72290b_1266883375371016792_250207.mp3', 'nerve神经 + ous…...的 → 与神经有关的 → nervous紧张的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2986, 'neutral', '/ˈnuːtrəl/', 'neutral.mp3', 'adj.中立的；  n.中立国', '56d9a68198b03dfd23a1d343ad6bdb69_197856_1585124279.jpeg', '36328fc4c64684a90801bb5b77e23fd8_41591_1551253148.png', 'He remained neutral in the disagreement', '他在这场争吵中保持中立，不偏袒任何一方。', '66592113beb8e7a46384083387d57bcf_48050_1585124275.mp3', 'neutr=neuter中性的 + al属于……的 → 中立的；中性的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2987, 'newsletter', '/ˈnuːzletər/', 'newsletter.mp3', 'n.时事通讯，业务通讯', '37856b731c60e8e5b5375e4357aa250d_85456_1750758186.jpg', '', 'I couldn’t read the foreign newsletter', '虽然我看不懂外语简讯，但这个头条似乎是个重大新闻。', 'sa_102_17763_0_3_20150809042535.aac', 'news新闻 + letter信 → newsletter 时事通讯', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2988, 'occur to', '/əˈkɜːr tu/', 'occur to.mp3', 'phr.想到', 'b337ad28abef5e928c82d8593664bac2.jpg', '', 'It occurred to her that she could give her mother a plant as a birthday gift.', '她想到可以送妈妈一盆植物当作生日礼物。', 'us_It_occurred_20241009153708986_095ee5d6593e4e36d891.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2989, 'oil', '/ɔɪl/', 'oil.mp3', 'n.油，食用油；  v.上油，涂油', '3_0_20160530153425_33994_c-gigapixel-scale.jpg', 'd_24_17618_0_3_20150808233036.png', 'The salad tastes better if you add some oil.', '加些菜油，沙拉会更好吃。', 'y67tj9w85jbpx5lap8y2qcnp63aaj55w.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2990, 'on the other hand', '/ɔn ðə ˈʌðər hænd/', 'on the other hand.mp3', 'phr.另一方面，反过来说', 'f30e949f8abd483e65d5a1d424d40405.jpg', '', 'She wants to eat out', '她想出去吃饭，但另一方面，她应该尽量省钱。', '557747468bd2388f33c93c4548d1c92c_45598_1600141877.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2991, 'oral', '/ˈɔrəl/', 'oral.mp3', 'adj.口腔的', 'c2d901ab0283b7cb05beb568892329fd_78514_1728538652.jpg', 'd_24_7501_0_3_20150808225127.png', 'The dentist recommended an oral examination every six months.', '牙医建议每六个月进行一次口腔检查。', 'us_The_dentist_20241010133736686_438eba14c524a9633ef0.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2992, 'overseas', '/ˌoʊvərˈsiːz/', 'overseas.mp3', 'adv.在海外；  adj.外国的；海外的', '86d32d5f69cadf6e786b0f2069e24bb5_96055_1565343053.jpg', 'd_107_5140_0_2_20150809011647.png', 'We export the goods overseas.', '我们把货物出口到海外。', '678219091c4cd759_1266883479776766882_250207.mp3', 'over越过 + sea海洋 + s → overseas海外', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2993, 'pair', '/per/ ', 'pair.mp3', 'n.一对，一双；  v.（使）成对，配对', 'f78bd641ffa46a4ba0f9c6027017265c_95302_1738823067.jpg', 'd_24_2750_0_4_20150808223307.png', 'A pair of parrots will be happier than a lonely one.', '一对鹦鹉会比一只鹦鹉要幸福。', 'mh46sp6msk34jlmdyw79thsg2nckee7n.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2994, 'perceive', '/pərˈsiːv/', 'perceive.mp3', 'v.意识到', '9f9c0ff30c1eab9a1ab8e087fe9f6193_83820_1586764189.jpeg', 'd_1_3982_0_3_20150808122203.png', 'Hearing a strange noise from the bush', '听到灌木丛里奇怪的声音，他意识到了危险并准备战斗。', 'us_Hearing_a_20230523104056088_6411b3599bab5f3b28ff.mp3', 'per通过 + ceive抓住 → perceive觉察，发觉', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2995, 'perform', '/pərˈfɔːrm/', 'perform.mp3', 'v.表演', '7bc28bca00c85ede200592517431c742_185843_1585035874.jpeg', 'd_94_13681_0_4_20150809010144.png', 'A band is performing on the stage.', '一支乐队正在舞台上表演。', '6aabb0071b72205b_1266883326852836314_250207.mp3', 'per完全 + form提供 → 提供完全提供、展现自己 → perform表演、表现', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2996, 'phenomenon', '/fəˈnɑːmɪnən/', 'phenomenon.mp3', 'n.现象；奇迹；奇才', '7997b1f67a624ea8de5e84fe3b2c6b9c_554611_1610014942.jpg', 'd_107_7844_0_2_20150809022250.png', 'The Northern Lights are a wonderful natural phenomenon.', '北极光是一种奇妙的自然现象。', '31d6a798506e232a501e09ba01df631c_19011_1619317438.mp3', 'phen显示 + omen预兆 + on表示抽象名词 → 显示预兆 → phenomenon现象', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2997, 'photograph', '/ˈfoʊtəɡræf/', 'photograph.mp3', 'n.照片；  v.上镜；  v.为……拍照', '087953be7fe8b65574f0fbe2bbfcdc1d_100603_1565343289.jpg', 'd_105_5738_0_2_20150809055120.png', 'Here are all of my travel photographs.', '这些都是我旅行拍的照片。', '9d0ac5c67841c5d3_1266763556741012004_250117.mp3', 'photo光 + graph写，图 → 用光写 → photograph相片', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2998, 'plenty', '/ˈplenti/', 'plenty.mp3', 'pron.大量，丰富', '3_0_20170709071550_38221_c-gigapixel-scale.jpg', 'd_24_17145_0_3_20150808232134.png', 'We have plenty of fruits and vegetables.', '我们有充足的水果和蔬菜。', '83e778d418dd3f45f98d81d3883173a2_13995_1621910086.mp3', 'plen满 ＋ ty表名词 → plenty大量，丰富', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (2999, 'possession', '/pəˈzeʃn/', 'possession.mp3', 'n.所有物', 'i_1_3960_0_4_20150808122139-gigapixel-scale.jpg', 'd_16_3960_0_2_20150808223903.png', 'My house is my most expensive possession.', '我的房子是我最贵重的财产。', '4e6facf5c007eb99_1266883488050797226_250207.mp3', 'pos能 + sess坐 + ion表名词，构成抽象名词 → 能坐在上面 → possession拥有', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3000, 'post', '/poʊst/', 'post.mp3', 'v.邮寄；  n.邮政', '3_0_20170723071134_3851_c-gigapixel-scale.jpg', 'd_24_15937_0_3_20150808230900.png', 'She is posting the letter.', '她正在寄信。', '3_0_20170723071134_52836_c.aac', 'po向前 + st使稳固，站立 → 直立的事物 → post柱，岗位', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3001, 'preferable to', '/ˈprefrəbl tuː/', 'preferable to.mp3', 'phr.优于(胜过)', '305b4c755670938ae793d9af9f8e1118.jpeg', '', 'For this dish', '做这道菜，用新鲜香草比大蒜更好。', 'fc4f0136dc68b948625eb506d08bafa1.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3002, 'preference', '/ˈprefrəns/', 'preference.mp3', 'n.偏爱，喜好；喜爱', 'i_1_6201_0_4_20150808124824-gigapixel-scale.jpg', 'd_107_6201_0_2_20150809015236.png', 'I have a preference for fruits over sweets.', '比起糖果，我更喜欢水果。', 'sa_13_6201_0_7_160330164243.aac', 'pre预先 + fer带来，拿来 + ence名词后缀 → 预先带来的行为 → 偏爱，优先权', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3003, 'prevail', '/prɪˈveɪl/', 'prevail.mp3', 'v.流行，普遍存在；战胜', 'd8314d21c06b3f20580444b4eaf71bae_125931_1701163021.jpg', 'd_107_4217_0_2_20150809004900.png', 'Nowadays', '如今，音乐节在年轻人中很流行。', 'us_Nowadays_music_20231128172408009_182a9bd8bc49e51efa94.mp3', 'pre预先 + vail强壮 → 能够领先强壮者的获胜 → prevail胜，优胜', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3004, 'prisoner', '/ˈprɪznər/', 'prisoner.mp3', 'n.囚犯，俘虏；拘留犯', 'ac6513372a7cd0a7a3a1a2ba92b3d99e_199348_1576131574.jpeg', 'd_100_13826_0_4_20150809032602.png', 'The people with the striped uniforms were kept as prisoners.', '这些穿着条纹衣服的人是被关押的囚犯。', '692ffa51b98055be_1266883491076791022_250207.mp3', 'prison监狱 ＋ er表示人，行为的主动者，做某事的人 → prisoner囚犯', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3005, 'proposal', '/prəˈpoʊzl/', 'proposal.mp3', 'n.求婚', 'i_1_7904_0_4_150917164433-gigapixel-scale.jpg', '', 'That guy made a proposal to his girlfriend with a diamond ring.', '那位男士手拿钻戒，向他的女朋友求婚。', 'sa_1_7904_0_4_150923123647.aac', 'pro向前 + pos放 + al名词后缀 → 向前放 → proposal提建议', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3006, 'provide for', '/prəˈvaɪd fɔr/', 'provide for.mp3', 'phr.供养', 'ec1e70bae688d198850c702cbfdd560a.jpg', '', 'Our parents provided for us when we were young.', '我们的父母在我们小时候供养我们。', 'afbef131985b992b818319cdc8a76fed_41120_1593575071.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3007, 'provide with', '/prəˈvaɪd wɪð/', 'provide with.mp3', 'phr.供给', 'a0bdb5423d4b9df9f9da382f62109db4.jpeg', '', 'This restaurant provides us with free juice.', '这家餐厅提供免费果汁。', 'f7c98e75808d4bda0411fa7576137db7_42656_1593575085.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3008, 'purchase', '/ˈpɜːrtʃəs/', 'purchase.mp3', 'v.购买；  n.购买；购买的东西', 'i_16_8400_0_4_151113111443-gigapixel-scale.jpg', 'd_107_8400_0_2_20150809023237.png', 'The shirt is so cheap that I really want to purchase it.', '这件T恤太便宜了，我真的想买。', 'sa_16_8400_0_4_151218195426.aac', 'pur向前 + chase追逐 → purchase购买', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3009, 'rate', '/reɪt/', 'rate.mp3', 'n.速度，速率；  v.评估，评价', 'eec83fc5a16025581bedc7611a3ba632_91547_1565342567.jpg', 'd_16_4908_0_2_20150808224558.png', 'My heart is beating at a normal rate.', '我的心脏以正常速度跳动着。', '323338a41b04bcba0a6a26c769a501c4_12898_1619160261.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3010, 'react', '/riˈækt/', 'react.mp3', 'v.起反应，对……做出反应', 'caf3ee9689ed3979d82377c2f4f05cee_143023_1734421209.jpg', 'd_107_5598_0_2_20150809013131.png', 'Different people react differently when watching a movie.', '看电影时，不同的人有不同的反应。', '1afa0e9d49e65875_1266883490514754268_250207.mp3', 're相反、反对 + act行动，做 → react起反应；有影响', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3011, 'reasonable', '/ˈriːznəbl/', 'reasonable.mp3', 'adj.合理的；通情达理的；（价格）公道的', '98a77a4f82537b876e7e2e00cf0486da_166446_1748413870.jpg', 'd_24_5576_0_3_20150808224200.png', 'He bought the apples at a reasonable price.', '他用合理的价格买了苹果。', 'efllagty4fgyfnxec4nzt7w324vke6rn.mp3', 'reason合理 + able形容词后缀，具有某种性质的 → 合理的，通情达理的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3012, 'recorder', '/rɪˈkɔːrdər/', 'recorder.mp3', 'n.录音机；记录员', '603004ea5efb17508990d5a12405b3a3_183954_1577936287.jpeg', 'd_109_17649_0_2_20150809062421.png', 'The old man is making a voice memo with a recorder.', '老人正在用录音机做语音备忘录。', 'b1489ebc035bbdca30709adfb1ba86d5_40414_1577936284.mp3', 'record记录，录音 + er表示人或物 → recorder记录者；录音机', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3013, 'register', '/ˈredʒɪstər/ ', 'register.mp3', 'v.注册；（仪表等）显示；  n.登记表，注册表', 'ec5af898cc042035e3f34abf4de2c81e_101318_1586599558.jpeg', 'd_16_5156_0_2_20150808225054.png', 'The athletes are registering for a half-marathon around the park.', '运动员们正在登记，报名参加环绕公园的半程马拉松。', '8b1c8dd42ed041a61a0f19a83518a9f0_48372_1586599555.mp3', 're回 + gist携带 + er → register注册', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3014, 'relatively', '/ˈrelətɪvli/', 'relatively.mp3', 'adv.比较地，相对地', 'd46e01782a9c7e697658a65562bf2f9f_112917_1698200456.jpeg', '', 'This test is relatively easy', '这次测试相对简单，拿100分不是问题。', 'us_This_test_20231025102112303_efe86041477ae181f141.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3015, 'reliable', '/rɪˈlaɪəbl/', 'reliable.mp3', 'adj.可靠的，可信赖的', '3_0_20170721105900_54918_c-gigapixel-scale.jpg', 'd_24_3997_0_3_20150808223429.png', 'My mobile phone is very reliable!', '我的手机相当靠得住！', '0994bc32ace4936c_1266798147868187364_250123.mp3', 'reli=rely依靠 + able表形容词，…的 → reliable可靠的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3016, 'rely on', '/rɪˈlaɪ ɑn/', 'rely on.mp3', 'phr.依赖，依靠，信赖', '6f9d3db4ec97b95414ab59ded9e2018a.jpeg', '', 'The success of this project relied on everyone\'s efforts.', '这个项目的成功靠的是大家的努力。', 'cb9c52e219a15c05_1266883380354964062_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3017, 'reply', '/rɪˈplaɪ/', 'reply.mp3', 'v.答复；  n.答复，回答', '56ef8ea1e7a8b6681a3d71fcd116c475_95890_1713941510.jpg', 'd_24_16646_0_5_20150808231750.png', 'He is replying to messages on the phone.', '他正在回复手机上的信息。', '642620dbc409207b_1266883196068604684_250207.mp3', 're反 + ply重叠，折叠 → 叠回去 → reply回答', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3018, 'report', '/rɪˈpɔːrt/', 'report.mp3', 'n.报道；报告，汇报；  v.报道；报告，汇报', 'd01f046115da7e17684937e68aef461d_199284_1578561862.jpeg', 'd_24_17609_0_3_20150808233020.png', 'She wrote a newspaper report about him.', '她写了一篇关于他的新闻报道。', '1b314cc86e77932ed45f42638aae6daf_30910_1578561859.mp3', 're回 + port拿，带 → 把消息、情况等带回来 → report报告，汇报', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3019, 'researcher', '/ˈriːsɜːrtʃər/', 'researcher.mp3', 'n.研究员', '19698822fc5d91aa64a0a4b0ddd26997_99467_1586510399.jpeg', '', 'The researchers are using the microscope to investigate something.', '研究员们正在用显微镜研究着什么。', '47aed751883fa150dccfa8d1e2762d62_42866_1584956854.mp3', 'research研究 ＋ er名词后缀 → researcher研究员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3020, 'retailer', '/ˈriːteɪlər/', 'retailer.mp3', 'n.零售商', '33c128b680ccc05ca41cf255f9fdc4a3_178258_1584533900.jpeg', '', 'This retailer sells many kinds of products.', '这个零售商销售各种各样的商品。', '3_0_20160718115046_36692_c.aac', 're再 + tail剪，割 + er表示人 → retailer零售商', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3021, 'reverse', '/riˈvərs/', 'reverse.mp3', 'v.倒（车）；  n.逆向，逆转；  adj.相反的', 'bd11433d3eacdf14ef9dd62bb994c077_195579_1585058394.jpeg', 'd_107_5836_0_2_20150809014157.png', 'He is reversing the car into his driveway.', '他正将车倒进私家车道里。', 'c5392c591fe1d906a6967b26a1c9b6d9_47920_1585058390.mp3', 're向后，相反 + verse转 → reverse反转，颠倒', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3022, 'rival', '/ˈraɪvl/', 'rival.mp3', 'n.竞争对手；  v.与……竞争，与……相匹敌', 'cedc2b013749d8d7ff626a0529db8fbb_153236_1573714917.jpeg', 'd_1_5814_0_2_20150808124441.png', 'The two lions are rivals and will fight each other to become the new leader.', '这两只狮子是竞争对手，它们为了成为新的头领即将展开战斗。', '393cf0ebb19097a9_1266798146780617438_250123.mp3', 'riv河 + al表名词 → 由“河”引申为“流动，跑 → 一起跑 → rival竞争者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3023, 'roast', '/roʊst/', 'roast.mp3', 'v.烤，焙，烘；挖苦；  adj.烤的，烘的', 'd8bc66476451531a90ba948ca95a09a8_167324_1582357781.jpeg', 'd_24_8326_0_4_20150808225604.png', 'I\'m roasting a chicken in the oven for dinner tonight.', '我正在为今晚的晚餐用烤箱烤鸡肉。', 'rsdem7wpfy8jaurxybhemzcqwk3jny8v.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3024, 'roll', '/roʊl/', 'roll.mp3', 'v.滚动，转动；  n.翻滚', '3_0_20170714071149_19789_c-manual-scale.jpg', 'd_16_2690_0_2_20150808223621.png', 'The kid is rolling the snowball to make it bigger.', '小孩正在滚雪球，使它变得更大。', '3_0_20170714071149_1452_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3025, 'secondary', '/ˈsɛkənˌdɛri/', 'secondary.mp3', 'adj.第二的；(疾病、感染等) 继发性的', 'i_1_4837_0_4_150831102556-gigapixel-scale.jpg', 'd_107_4837_0_2_20150809010933.png', 'He took the silver medal', '他获得了银牌，位列第二。', 'sa_1_4837_0_2_20150808123058.aac', 'second第二 + ary…的 → secondary第二的；次要的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3026, 'slide', '/slaɪd/', 'slide.mp3', 'v.使滑动；滑落；  n.幻灯片', 'i_1_5956_0_4_151116102424-gigapixel-scale.jpg', 'd_9_5956_0_2_20150808151841.png', 'You can slide your finger across the screen to unlock your phone.', '你可以在屏幕上滑动手指来解锁你的手机。', '7s3v9hbgbwy2234lfbrfk3ghdhnrgl6k.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3027, 'social', '/ˈsoʊʃl/ ', 'social.mp3', 'adj.交际的；社会性的', 'e27f737aff0b72570753d45bce21b365_106241_1654742962.jpg', 'd_24_15892_0_3_20150808230725.png', 'People chat and post things on social media platforms. ', '人们在社交媒体上聊天和发照片。', 'us_People_chat_20220609104640496_7782aaefd0076756ea94.mp3', 'soc社会 + ial形容词后缀 → 社会的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3028, 'solid', '/ˈsɑːlɪd/', 'solid.mp3', 'adj.结实的；坚固的；固体的；  n.固体', 'solid_5157_20231106_10281e47.jpg', 'd_24_5157_0_4_20150808223952.png', 'This safe is very solid.', '这个保险箱非常结实。', 'sa_1_5157_0_3_20150808123603.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3029, 'source', '/sɔːrs/', 'source.mp3', 'n.来源；出处', 'i_1_2662_0_3_20150808121909-gigapixel-scale.jpg', 'd_1_2662_0_3_20150808121909.png', 'The lake is the source of the river.', '这片湖是这条河的发源地。', 'd06049cdb358633b_1266883527669033812_250207.mp3', 'sou=sub从下往上 + rce引导 → source来源；出处', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3030, 'stand by', '/stænd baɪ/', 'stand by.mp3', 'v.袖手旁观，准备行动', 'i_50_19903_0_3_20150809020320.jpg', '', 'He is standing by in case they need him to play.', '他在旁边待命，以防需要他上场。', 'sa_50_19903_0_3_20150809020320.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3031, 'stand out', '/stænd aʊt/', 'stand out.mp3', 'phr.突出；继续抵抗', '3931419fdf74faf748e9babea78a3978_101303_1582792090.jpeg', '', 'The red cube stands out from the wooden ones.', '红色方块在木头方块中十分突出。', 'cf94b22edba01afd252df8aaeb55088e_47920_1582792087.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3032, 'step on', '/step ɑːn/', 'step on.mp3', 'phr.踩', '348d68037a6490572c7c9e570d0c0c01.jpeg', '', 'He stepped back and forth on the control pad', '他的脚在控制板上来回踩动，以对应屏幕上的图标。', '15857de077e98b48b5d07a57878c433a_48632_1596770273.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3033, 'subject', '/ˈsʌbdʒɪkt/', 'subject.mp3', 'n.学科，科目；实验对象；  v.使臣服，使顺从（读作/səbˈdʒɛkt/）', 'i_1_4910_0_2_20150808123138-gigapixel-scale.jpg', 'd_24_4910_0_3_20150808223633.png', 'English was my favorite subject in school.', '英语是我上学时最喜欢的科目。', '5554241c3f38f7cb_1266883010841500384_250207.mp3', 'sub在…下面 + ject投掷，扔 → 扔下去 → 服从的，扔下去让大家讨论的主题 → subject主题', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3034, 'substitute for', '/ˈsʌbstɪtuːt fɔːr/', 'substitute for.mp3', 'phr.代替', 'f75f96e4071e21515decd425621b399c.jpeg', '', 'He was substituted in for his injured teammate.', '他替换了受伤的队员。', 'us_He_was_20241009154752732_6c6abe945dc2a2bb71b9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3035, 'survival', '/sərˈvaɪvl/', 'survival.mp3', 'n.生存；存活', 'f2ee7e2bf6d644636fc3f7ad3e2f9bd1_256997_1681697775.jpg', 'd_107_5736_0_2_20150809013656.png', 'She taught me survival skills in the wild', '她教了我野外求生的技能，比如如何在森林里生火。', 'us_She_taught_20231110130053574_d4e51c6a32b8a847ed35.mp3', 'survive幸存 + al名词后缀 → survival生存，存活', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3036, 'take for', '/teɪk fɔːr/', 'take for.mp3', 'phr.误以为', '38d39af633075f1e1c53a5b47a0f443e.jpeg', '', 'The emperor took it for 100 coins.', '皇帝误以为是100枚钱。', 'us_The_emperor_20241009154652627_c165ce9fe9d937010970.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3037, 'tendency to sth.', '/ˈtendənsi tuː ˈsʌmθɪŋ/', 'tendency to sth..mp3', 'phr.做某事的倾向', '185577e07bb63423f7e6b47a22bb1278.jpg', '', 'When he is sad', '当他伤心时，他有想抽烟的倾向。', 'us_When_he_20241009154613067_26dcefadae373c657f8f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
