INSERT INTO `words` VALUES (3081, 'coast', '/koʊst/', 'coast.mp3', 'n.海岸，海滨；  v.沿海航行', '3_0_20170608071921_17830_c-gigapixel-scale.jpg', 'd_24_17289_0_3_20150808232620.png', 'The view of the coast is amazing.', '这片海岸的景色棒极了。', 'qu4xtzd4562r9fchp6gt3bzcgpddcq2k.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3082, 'comb', '/koʊm/', 'comb.mp3', 'v.梳（头发）；  n.梳理', '51998d34049cce7f17446e59831dfb2d_119995_1552895105.jpeg', '20121225_20_07_58_986.png', 'The mother is combing her daughter\'s hair.', '妈妈正在帮她的女儿梳头发。', 'e064480b7b61d010_1266883195193154050_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3083, 'combine with', '/kəmˈbaɪn wɪð/', 'combine with.mp3', 'phr.与……结合（联合）', '89ac9f4d2a8f3eea0f2db4732965118b_184010.jpg', '', 'Hydrogen #combines with# oxygen to form water.', '氢气和氧气结合形成水。', 'cc62990c84802136f69253fa93cdafe8_41347.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3084, 'come off', '/kʌm ɑf/', 'come off.mp3', 'phr.从……掉下，发生，举行，（计划）实现', 'comeoff_7732_20231106_a0207906.jpg', '', 'She is startled when her facial mask comes off her face.', '她的面膜从脸上掉下来时她被吓了一跳。', 'us_She_is_20241009155725166_9534fdab562b1c7d90a6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3085, 'component', '/kəmˈpoʊnənt/', 'component.mp3', 'n.零件，组成部分；  adj.组成的', '3_0_20170930071413_57488_c-gigapixel-scale.jpg', 'd_105_5730_0_2_20150809055106.png', 'These are different kinds of electrical components.', '这些是各种各样的电子元件。', '3_0_20170930071413_248_c.aac', 'com共同 + pon放 + ent名词后缀 → 放到一起的东西 → component成分', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3086, 'condition', '/kənˈdɪʃən/', 'condition.mp3', 'n.环境，形势；状况，状态；疾病；  v.使适应，使处于良好状态', '3_0_20170930071401_59045_c-gigapixel-scale.jpg', '20130130_16_12_56_620.png', 'The living conditions here are really poor.', '这儿的生活条件真的很差。', '824b9f9540688abf_1266883377354025908_250207.mp3', 'con和，一起 + dit说 +ion名词后缀 → condition状况，形势', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3087, 'conflict', '/ˈkɑːnflɪkt', 'conflict.mp3', 'n.冲突，争执，矛盾；  v.冲突，抵触（读作/kənˈflɪkt/）', 'feb039a1b4830ab368b12b36f981886d_130715_1538756791.jpg', '20121225_20_20_05_622.png', 'Apparently there is a conflict between them.', '显然，他们之间有争执。', '9f39ab394ad1a90f305591c72787018f_12428_1538756800.mp3', 'con共同 + flict打 → 一起打斗 → conflict冲突', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3088, 'consist of', '/kənˈsɪst ʌv/', 'consist of.mp3', 'phr.由……组成', '30d482c288afed8b5e2ce0e5fab2eaee_174001.jpg', '', 'This hamburger consists of bread', '这个汉堡包由面包、芝士、牛肉和蔬菜组成。', '0acc7cfe68556ceed08dc0b32b373cbc_49615.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3089, 'construction', '/kənˈstrʌkʃn/ ', 'construction.mp3', 'n.施工；建造；建筑；建造物；构造', 'beee237e68fb06d17659435c36a69561_87661_1535177472.jpeg', 'd_16_5566_0_2_20150808225448.png', 'The building is under construction.', '这栋大楼正在施工中。', '274a5245931fe130845b09f00c9933dc_28258_1535177465.mp3', 'con一起 + struct堆起 + ion名词后缀 → construction建造', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3090, 'consume', '/kənˈsuːm/ ', 'consume.mp3', 'v.消耗，消费；吃，喝，饮', 'a8b7e476790961944b0ee4d06939b7cd_161845_1574242019.jpg', '20141013_08_09_59_579_v3.png', 'We\'ve consumed all of the toilet paper that we bought from the supermarket.', '我们把从超市买来的厕纸都用完了。', '240dd79aa23521b3c478db1a32055660_30402_1574242017.mp3', 'con全部 + sum拿取 + e → 全部拿光 → consume消费', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3091, 'container', '/kənˈteɪnər/', 'container.mp3', 'n.集装箱', '3_0_20160520173610_67473_c-gigapixel-scale.jpg', 'd_74_12216_0_4_20150809024826.png', 'There are a lot of containers at the port.', '港口有很多集装箱。', 'y6zl8wbjbuu6q86wuhwqytnjmw7af835.mp3', 'con全部 + tain握住 + er表示物 → container容器，集装箱', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3092, 'continual', '/kənˈtɪnjuəl/', 'continual.mp3', 'adj.不断的，连续的；频繁的', 'i_1_10096_0_4_20150808131547-gigapixel-scale.jpg', 'd_1_10096_0_4_20150808131547.png', 'Learning English is a long-term continual process.', '学习英语是一个长期的、连续不断的过程。', 'sa_1_10096_0_4_20150808131547.aac', 'continu(e)持续 + al形容词后缀 → continual持续的，不间断的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3093, 'conversion', '/kənˈvɜːrʒn/', 'conversion.mp3', 'n.兑换；转变，转换', '1425952582014-gigapixel-scale.jpg', 'd_1_15260_0_2_20150808132011.png', 'There are different conversion rates among those currencies.', '这些货币之间有不同的汇率。', '6e1b6a73181be401926c6aac7d08e7e2_15248_1538650648.mp3', 'conver转化 + sion名词后缀 → conversion 转化', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3094, 'correspondence', '/ˌkɔːrəˈspɑːndəns/', 'correspondence.mp3', 'n.信件，函件；通信，通信联系', '569bc82705eb4d4561d163a7ca54a06c_204159_1576288600.jpeg', 'd_107_670_0_2_20150809001110.png', 'For a correspondence course', '函授课程是指你在家学习并通过邮寄方式与导师交流。', '5cddcdab1c12cc534c6c6ef91e597b20_43438_1576288597.mp3', 'cor共同 + respond回答 + ence表名词 → correspondence通信；通信联系', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3095, 'counter', '/ˈkaʊntər/', 'counter.mp3', 'n.柜台；回击，反击；  v.抵制；  adv.相反地', '3_0_20160520172951_87495_c-gigapixel-scale.jpg', 'd_16_4001_0_2_20150808223935.png', 'Customers pay money at the counter.', '顾客在柜台付钱。', '3_0_20160520172951_32482_c.aac', 'count计算，加总 + er表名词 → 结账的地方 → counter柜台', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3096, 'cover', '/ˈkʌvər/', 'cover.mp3', 'v.盖住；包括；覆盖', '8876391864bdbe8478e44a3a864032ef_174455_1574826872.jpeg', 'd_99_12275_0_4_20150809022226.png', 'He covers his face with sunglasses and a mask.', '他用墨镜和口罩遮住了脸。', '9z9pj6w28wsnu5ng4sn9ljw6tgl4h7nq.mp3', 'co表强调 + ver关闭，覆盖 → cover盖住', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3097, 'curse', '/kɜːrs/', 'curse.mp3', 'n.诅咒；咒骂；祸因；  v.诅咒；咒骂；使受罪', 'i_1_4425_0_3_20150808122756-gigapixel-scale.jpg', '20130520_01_00_07_298.png', 'I will draw a circle to lay a curse on you.', '我要画个圈圈诅咒你！', 'f_20150706_171231_1_4425.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3098, 'decorate', '/ˈdekəreɪt/', 'decorate.mp3', 'v.装饰，布置；装潢；授予勋章', 'i_1_6002_0_2_20150808124640-gigapixel-scale.jpg', 'd_24_6002_0_4_20150808224421.png', 'We decorated the tree to celebrate Christmas.', '我们装饰了这棵树来庆祝圣诞节。', '4ed8faaa978216ce_1266883321036647256_250207.mp3', 'decor装饰 + ate动词后缀 → decorate装修，装潢', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3099, 'defeat', '/dɪˈfiːt/', 'defeat.mp3', 'v.打败，击败，战胜；  n.挫败', 'dcb03c997b39ddebde76f9f5ae78e21d_150241_1724395908.jpg', '20130130_16_04_49_287.png', 'The girl skillfully defeated her challenger with a powerful kick.', '这个女孩一记飞踢，巧妙地将对手击败。', 'us_The_girl_20240823145152229_8bd9cbfea02a1c61592e.mp3', 'de向下 + feat做，制作 → 做下去 → 打下去 → defeat打败，摧毁', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3100, 'diagnose', '/ˌdaɪəɡˈnoʊs/ ', 'diagnose.mp3', 'v.诊断（疾病），下诊断结论', '2839c1ae35261653132bf49dd927987e_189218_1588928673.jpeg', '20140824_17_27_47_378_v3.png', 'The doctor diagnosed the patient with lung cancer.', '医生诊断这个病人患有肺癌。', 'd4bb98fc5946e29b59096dd52437e53b_46044_1588928668.mp3', 'dia穿过，二者之间 + gnos知道 + e → diagnose诊断(疾病)，对（病人）下诊断结论', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3101, 'disease', '/dɪˈziːz/', 'disease.mp3', 'n.疾病，病', 'cdbba34e23e00a5fbda009332a90e2e3_107173_1575285660.jpeg', 'd_24_7099_0_3_20150808224924.png', 'There is a disease spreading around the family.', '有一种疾病在这家人之间传播。', '4f67e032674e390a_1266883625490340384_250207.mp3', 'dis没有 + ease安逸 → 不舒服 → disease疾病', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3102, 'disgust', '/dɪsˈɡʌst/', 'disgust.mp3', 'v.使作呕，使厌恶；  n.恶心', 'ed0a15134e5bd4df461e8cc2c80a5ffc_98965_1650005926-800-600.jpg', 'd_1_6567_0_4_20150808125226.png', 'What really disgusts me is eating an entire worm in the apple.', '真正让我恶心的是在苹果中吃了一整条虫。', 'ed3f6676485b2526_1266883487553444504_250207.mp3', 'dis与...相反 + gust尝 → disgust使作呕', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3103, 'distinction', '/dɪˈstɪŋkʃn/', 'distinction.mp3', 'n.优秀，杰出；差别，区分', 'i_1_933_0_5_20150808121614-gigapixel-scale.jpg', '20141013_21_22_59_849_v3.png', 'I finished my final exam with distinction.', '我以优异的成绩完成了期末考试。', '36eec4dbd60670e94157411d3623aff1_16816_1648784588.mp3', 'distinct独特的 + ion名词后缀 → distinction卓越；区别', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3104, 'dorm', '/dɔːrm/', 'dorm.mp3', 'n.（集体）宿舍', 'c_20150526_095849_1_10219-gigapixel-scale.jpg', 'd_103_10219_0_3_20150809033816.png', 'Look here. The dorm is in a mess.', '看这儿。这宿舍一团糟。', '0c9dc433173f83faf9490c385d6c41fe_15406_1628487232.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3105, 'drawer', '/drɔːr/', 'drawer.mp3', 'n.抽屉', 'i_1_16016_0_3_20150808132058-gigapixel-scale.jpg', 'd_24_16016_0_3_20150808231040.png', 'Remember to keep all your files in the drawer.', '记得把你的所有文件都放在抽屉里。', 'f11474da9e4cd1a3_1266763445823756938_250117.mp3', 'draw拉，拖 + er施动者名词后缀，表人或物 → 被人拉开 → drawer抽屉', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3106, 'drink', '/drɪŋk/', 'drink.mp3', 'v.喝；  n.饮料', '7eafb8b154edc48051ab3415f4d306d1_101036_1595315299.jpeg', 'd_16_17722_0_4_20150809012453.png', 'He likes drinking orange juice.', '他喜欢喝橙汁。', 'krs8q8clt48dfnpkj97suv96hf6sg2eb.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3107, 'educational', '/ˌedʒuˈkeɪʃənl/', 'educational.mp3', 'adj.教育的；有教育意义的', '3_0_20161224072842_6358_c-gigapixel-scale.jpg', '', 'Well', '好吧，这就是教育的全过程。', '3_0_20161224072842_73414_c.aac', 'educat=educate教育 ＋ ion名词后缀 ＋ al...的 → educational教育的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3108, 'elementary', '/ˌelɪˈmentri/', 'elementary.mp3', 'adj.初级的；基本的', '2819a3fb5f8dd0ecbe842168c2c45565_111342_1656656967.jpg', 'd_1_6432_0_2_20150808125143.png', 'The elementary students are starting school for the first time.', '小学生们正准备第一次上学。', 'us_The_elementary_20241009155301172_ccc9096ae83dbdd2de20.mp3', 'element要素 + ary形容词后缀 → 最简单的要素 → elementary元素的，基本的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3109, 'emperor', '/ˈempərər/', 'emperor.mp3', 'n.皇帝', 'i_1_8019_0_3_20150808130313-gigapixel-scale.jpg', 'd_16_8019_0_2_20150808232417.png', 'In ancient China', '在中国古代，皇上有着至高无上的权力。', '5bad2beacc079c54_1266883321329462112_250207.mp3', 'emper命令，统治 ＋ or表示人 → 统治者 → emperor皇帝', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3110, 'entry', '/ˈentri/', 'entry.mp3', 'n.进入', '3_0_20170608071031_49557_c-manual-scale.jpg', 'd_24_4379_0_4_20150808223515.png', 'He made his entry into the meeting room.', '他走进了会议室。', '3_0_20170608071031_69229_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3111, 'envy of', '/ˈenvi əv/', 'envy of.mp3', 'phr.对……的羡慕（嫉妒）', 'bb8b9e2ccf7e1f9ead4bd7c7c6a77ced_161219_1707019052.jpg', '', 'She\'s the envy of her classmates.', '她是同学们的羡慕对象。', 'us_Shes_the_20240306105402257_a51abf644181c58c51ae.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3112, 'equivalent', '/ɪˈkwɪvələnt/', 'equivalent.mp3', 'adj.相等的；等值的；  n.同义词；等价物', '44ba1cd2bf4cb72a839fb84c107c6fa6_35504_1700446024.jpg', 'd_107_5655_0_2_20150809013340.png', 'The weight of three small balls is equivalent to that of this large one.', '三个小球的重量与这个大球的重量相等。', 'us_The_weight_20231120101057508_7eddad64770ecd15e230.mp3', 'equi相等，平均 + val力量 + ent形容词后缀→ 力量平等 → 相等的，等价的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3113, 'exact', '/ɪɡˈzækt/', 'exact.mp3', 'adj.确切的', 'i_1_4971_0_3_20150808123243-gigapixel-scale.jpg', 'd_24_4971_0_4_20150808223743.png', 'The exact height of the tree is 5.386 meters.', '这棵树的确切高度是5.386米。', 'sa_4971_1_0_2_150707113330.mp3', 'ex出，向外 + act启动，驱动 → 明确执行某事 → exact确切的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3114, 'exchange', '/ɪksˈtʃeɪndʒ/', 'exchange.mp3', 'v.交流；交换；交易；  n.交易所', '0f3a2f3211b1da9f3a4275e41f7d6910_117508_1565323050.jpg', 'd_16_7108_0_2_20150808231449.png', 'People can exchange their thoughts and ideas.', '人们可以交换他们的思想和想法。', 'mqy6hmdt5w73jlu4kzj5pqb3qzvuajr8.mp3', 'ex出 + change交换 → exchange交换，交流', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3115, 'experiment on', '/ɪkˈspɛrəmənt ɑn/', 'experiment on.mp3', 'phr.试用；用……做试验', 'eacee8087c1dce82587a3c45776a6128.jpg', '', 'The researcher is experimenting on the plants.', '研究人员正在用植物做试验。', '5214faa7fd2503fcde7a04e098dcb25b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3116, 'explain', '/ɪkˈspleɪn/', 'explain.mp3', 'v.说明', 'a8b5d11e59e3ddc2a3d7c9d9d27858c0_116848_1699600839.jpg', 'd_1_7134_0_2_20150808125815.png', 'The doctor is explaining the patient\'s illness to her.', '医生正在向她解释病人的病情。', 'p7ed2ub5xs2scm8u8cmafc7n5zrzbxjl.mp3', 'ex出 + plain清楚的 → 说清楚的 → explain解释', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3117, 'explode', '/ɪkˈsploʊd/', 'explode.mp3', 'v.爆炸', '5b86ec74448bb0f84f6ee287c2f36e3e_97020_1579590089.jpeg', 'd_107_1120_0_2_20150809001604.png', 'If a light bulb explodes', '如果灯泡爆炸了，在那附近是非常危险的。', 'ac9a822ae8e9aa4d2d484bf819c0f7fd_60080_1579590093.mp3', 'ex出 + plode爆炸声 → 发出爆炸声 → explode爆炸', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3118, 'extra', '/ˈekstrə/', 'extra.mp3', 'adj.额外的，附加的；  n.（报纸）号外；  adv.额外地', '3d6ca091ea1bbddab01154a770d8666a_178308_1719459550.jpg', 'd_24_7105_0_4_20150808224930.png', 'Could you give me some extra ice cream?', '你能再多给我一点儿冰激凌吗？', '97ee8bda426db04a_1266883010078137036_250207.mp3', 'extra=out出去 → 出去的 → 余出的 → extra额外的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3119, 'faculty', '/ˈfæklti/', 'faculty.mp3', 'n.教职工，全体教员；院系；科；能力', 'dc5f546dc4445fb3cc80d106ca50e803_80619_1562142004.jpeg', '', 'The official website of the Law School shows a profile for the faculty.', '法学院的官方网站上列有全体教师的简介。', '2341010f529aa0c4ed7999eaaf0e31ce_25437_1627870313.mp3', 'facul做 + ty表名词 → 会做东西 → faculty能力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3120, 'farewell', '/ˌferˈwel/', 'farewell.mp3', 'n.再见；告别，离别；  adj.告别的', '9f207f300cfe5dbf94a5488c043b0ad8_88111_1565343560.jpg', '20130522_04_56_09_228.png', 'She said her farewell and drove off.', '她说了句再见，就开车走了。', '62dc4fb82c2bce47_1266883618910284746_250207.mp3', 'fare旅途 + well好的 → 祝路途愉快 → farewell再会；告别', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3121, 'feeling', '/ˈfiːlɪŋ/', 'feeling.mp3', 'n.（内心和感官的）感觉，感触，情绪；  v.感觉', '16c9027a75a33fb750cbde299e9cf8c9_156361_1732247430.jpg', 'd_24_15924_0_3_20150808230836.png', 'We have different feelings', '我们有着不同的情绪，如高兴、担忧和愤怒。', 'us_We_have_20250623145021484_a70cbc0119deefb68f6b.mp3', 'feel感觉 + ing行业，状态，行为 → feeling感情，感觉', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3122, 'fetch', '/fetʃ/', 'fetch.mp3', 'v.取来；  n.拿来，取来', 'i_1_4247_0_3_20150808122551-gigapixel-scale.jpg', 'd_24_4247_0_4_20150808223503.png', 'Here', '我一边扔球一边喊道：“小狗，取回来！”', '0c0c4146daa534a4_1266883487747562146_250207.mp3', 'fet=fed脚 + ch → 跑腿 → fetch取来', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3123, 'focus', '/ˈfoʊkəs/', 'focus.mp3', 'n.焦点；  v.集中', 'i_5_8388_0_4_20150808144809-gigapixel-scale.jpg', 'd_24_8388_0_4_20150808225634.png', 'Make sure your subject is in focus before taking the photo.', '拍照前你要确保拍摄对象已对焦。', 'sa_5_8388_0_4_20150808144809.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3124, 'fog', '/fɔːɡ/', 'fog.mp3', 'n.雾，烟雾，尘雾', '8ea9b4bd17f6e048188a767606c5223b_87806_1533025626.jpeg', '20130201_16_22_46_698.png', 'The heavy fog covers the whole city.', '大雾弥漫了整座城市。', 'b40a8e4361e8d867_1266883482142726660_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3125, 'format', '/ˈfɔːrmæt/', 'format.mp3', 'n.版式；设计；格式；  v.设计一个版式，设计……的版面；使......格式化', 'i_1_4776_0_3_20150808123015-gigapixel-scale.jpg', 'd_107_4776_0_2_20150809010700.png', 'The format of the newspaper is well arranged.', '这份报纸排版十分整齐。', 'sa_1_4776_0_3_20150808123015.aac', 'form形式 + at=ate表动词 → format使格式化', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3126, 'former', '/ˈfɔːrmər/', 'former.mp3', 'adj.前任的；  n.形成者', '0ae4e15e69e40b4f0b482a73c391791f_124249_1621910774.jpg', 'd_16_10571_0_2_20150808235535.png', 'The first photograph is our former headmaster.', '第一张照片是我们的前任校长。', 'dezuet4xw7wv5ulq3shdgd3nzkfmu9ur.mp3', 'form=fore先前 + er表人/物 → former前者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3127, 'framework', '/ˈfreɪmwɝːk/', 'framework.mp3', 'n.框架，结构', 'i_1_4847_0_4_150923102143-gigapixel-scale.jpg', 'd_16_4847_0_4_20150808224508.png', 'You can see the framework of the building so well at the moment.', '你现在可以清楚地看见房子的框架。', 'f89c7aa04930617e_1266883633087404716_250207.mp3', 'frame框架 + work物 → framework框架', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3128, 'fuel', '/ˈfjuːəl/', 'fuel.mp3', 'n.燃料；  v.给……加燃料', 'd5fa9e0ac3b45573fa4a68cb756cd90e_134540_1706766350.jpeg', '20140927_14_51_41_969_v3.png', 'I need to add fuel to my car.', '我需要给我的车加燃料。', 'us_I_need_20240204144520777_59fb514c1fb6e54b80e7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3129, 'funny', '/ˈfʌni/', 'funny.mp3', 'adj.有趣的，好玩的；  n.反常的怪事', '3_0_20170705110457_25160_c-gigapixel-scale.jpg', 'd_24_16514_0_3_20150808231458.png', 'It was so funny that he cried with laughter.', '这太好笑了，他都笑出眼泪了。', '18ef7764bae1227c_1266763310392912676_250117.mp3', 'fu趣味 + (n)y形容词后缀 → funny有趣的，好玩的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3130, 'gas', '/ɡæs/', 'gas.mp3', 'n.气体；煤气；天然气', 'fb31155b962b1eb839750bcb720d2536_102946_1656997831.jpg', 'd_24_5546_0_4_20150808224125.png', 'A cloud of gas is coming out from the chimney.', '一团气体正从烟囱里冒出来。', 'dbzcx3varyha5pn4xtalgha6h35q7akk.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3131, 'gesture', '/ˈdʒestʃər/', 'gesture.mp3', 'n.手势，姿势；  v.做手势，用动作示意', 'bafcd4afddcac3116cfff5c63e984963_120408_1556244224.jpeg', '20121225_19_26_08_205.png', 'The girl believes that this gesture can bring her good luck.', '女孩相信这个手势能给她带来好运。', '75au6q7z3fjkesptya5knhjj64a8xz76.mp3', 'gest带来，产生 + ure名词后缀 → 带来信息的动作 → gesture手势', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3132, 'give out', '/ɡɪv aʊt/', 'give out.mp3', 'phr.分发；耗尽', '3_0_20160520172800_95890_c.jpg', '', 'The teacher gave out the exam papers.', '老师分发了试卷。', '3_0_20160520172800_98574_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3133, 'glorious', '/ˈɡlɔːriəs/', 'glorious.mp3', 'adj.辉煌的，壮丽的', '6de3407604bbf58859613cc0db07801a_101519_1584084037.jpeg', 'd_1_4188_0_2_20150808122514.png', 'The sunrise in the countryside is quite glorious.', '乡间的日出非常壮丽。', '9688e91a40fbd724642b76f430c0afcc_49144_1584084035.mp3', 'glori=glory光荣 + ous形容词后缀 → glorious光荣的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
