INSERT INTO `words` VALUES (3135, 'go out', '/ɡoʊ aʊt/', 'go out.mp3', 'phr.外出，出去（交际、娱乐等）', '83acb30039072ef61c2e407d13f0692f_142272_1538755086.jpg', '', 'I prefer to go out for a walk alone when I\'m free.', '我喜欢空闲时间独自散步。', '6753e8b6f7298e93_1266883323183082394_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
