INSERT INTO `words` VALUES (3137, 'grant', '/ɡrænt/', 'grant.mp3', 'v.允许，同意，准允；  n.拨款', 'i_1_4377_0_3_20150808122705-gigapixel-scale.jpg', 'd_1_4377_0_3_20150808122705.png', 'The Subway Committee grants the blind permission to bring guide dogs on board.', '地铁委员会允许盲人携带导盲犬上地铁。', 'sa_1_4377_0_3_20150808122705.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
