INSERT INTO `words` VALUES (3141, 'hence', '/hens/', 'hence.mp3', 'adv.因此', '155e52ceb99a1545faa913ac4b9f2ac4_181793_1524896025.jpeg', '', 'There is always someone stealing the corn; hence', '总是有人偷玉米，因此一个篱笆修了起来。', 'us_There_is_20250508140437905_3f6ff29fe77ae68327c9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
