INSERT INTO `words` VALUES (3143, 'honor', '/\'ɑːnər/ ', 'honor.mp3', 'n.荣誉', '876349932f1570336db3b1ad2964c7c5_158788_1599474469.jpeg', 'd_24_6759_0_4_20150808224745.png', 'She received an honor for her excellent academic performance.', '她因学习成绩优异而获得荣誉。', 'us_She_received_20231219162734992_b0330f6c2ae0d26a7e90.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
