INSERT INTO `words` VALUES (3145, 'implication', '/ˌɪmplɪˈkeɪʃn/', 'implication.mp3', 'n.暗示；含意；牵连，卷入', '3_52_20170513112501_28563_c-gigapixel-scale.jpg', 'd_107_5647_0_2_20150809013308.png', 'She expressed her desire for the cookie by implication.', '她含蓄地表达了想吃饼干的想法。', '3_41_20170518141321_47494_c.aac', 'im进 + plic重叠，折叠 + ation名词后缀 → [说话]进入重叠 → implication连累；含蓄', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3146, 'in consequence', '/ɪn ˈkɑːnsɪˌkwens/', 'in consequence.mp3', 'phr.结果', 'bd1d83940758099e17e0fd597f48caa4.jpeg', '', 'In consequence', '结果，他只好冒雨步行回家。', '04d7c4c86683fd5f16fb748a1d010cc1.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
