INSERT INTO `words` VALUES (3149, 'inform against', '/ɪnˈfɔrm əˈɡenst/', 'inform against.mp3', 'phr.告发', '08fb8fa3d9e18b72acca37533b0530c4.jpg', '', 'He informed against his boss in exchange for a softer punishment.', '他告发了自己的老板，以便能被从轻发落。', '380eee9eee53d62e06619603f51c78c7_26220_1617069485.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3150, 'inner', '/ˈɪnər/', 'inner.mp3', 'adj.内部的，里面的；内心的；  n.内部，里面', 'd9678ef46827df6f2b9ba86187a8903e_138990_1565345704.jpg', 'd_1_9897_0_2_20150808131506.png', 'The inner core of the Earth is made up of iron and nickel.', '地球内部的核心由铁和镍组成。', 'men7qzklqvvaqpkm62tlnvtnk8lcbrws.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3151, 'insurance', '/ɪnˈʃʊrəns/', 'insurance.mp3', 'n.保险；保险费；保险业', '4940afc5d033ac6675362fab1e134757_113304_1562141910.jpeg', 'd_16_4846_0_2_20150808224506.png', 'An insurance can offer financial protection against loss as a result of an accident.', '保险能够提供经济上的保护，赔偿因事故造成的损失。', '6c9ced0c30e7bf2448146a0771e523cf_46600_1562141905.mp3', 'insur保证 + ance名词后缀 → insurance保险', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3152, 'involve in', '/ɪnˈvɑlv ɪn/', 'involve in.mp3', 'phr.参与', '2d01b1fb7fcb78fb6e7de7cba9311699.jpg', '', 'These two friends are both involved in organizing the tree planting event.', '这两位朋友都参与了植树活动的组织工作。', 'd7cbe42e8bf26e9b9c631055f61f66b7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3153, 'Japanese', '/ˌdʒæpəˈniːz/', 'Japanese.mp3', 'adj.日本的，日本人的，日语的；  n.日本人，日语', 'i_24_17483_0_3_20150808232841-gigapixel-scale.jpg', 'd_24_17483_0_3_20150808232841.png', 'They wear clothes of Japanese style.', '他们穿着日本风格的服饰。', '79c545d88fabba09_1266763446689377194_250117.mp3', 'Japan日本 + ese某国人或语言 → Japanese日本的（人），日语', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
