INSERT INTO `words` VALUES (3155, 'jealous of', '/ˈdʒeləs əv/', 'jealous of.mp3', 'phr.嫉妒', 'd032db51781a70a7cfa7a48193fbe191.jpeg', '', 'The evil queen is jealous of her beauty.', '邪恶的王后嫉妒她的美貌。', '8c53fab3b36a7b9bab58b1609c9f46f7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3156, 'join', '/dʒɔɪn/', 'join.mp3', 'v.连接，结合；  n.连接，结合', 'i_13_16629_0_3_20150808204216-gigapixel-scale.jpg', '20141011_16_54_29_520_v3.png', 'When they join the four pieces together', '当他们把这四块拼图拼起来时，就成了一个正方形。', 'sa_13_16629_0_3_20150808204216.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3157, 'keep back', '/kiːp bæk/', 'keep back.mp3', 'phr.保留，阻止，阻挡，隐瞒', 'i_105_17886_0_2_20150809062759.jpg', '', 'They kept back fruit and drinks for the movies.', '他们留了水果和饮料看电影时享用。', 'sa_105_17886_0_2_20150809062759.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3158, 'keep down', '/kiːp daʊn/', 'keep down.mp3', 'phr.抑制', '53225385b7b0693f5ce0a81c53e6facd.jpg', '', 'They keep their voices down when their roommate falls asleep.', '当室友睡着时，他们会压低说话的声音。', 'us_They_keep_20241009151155319_50c23464236406c8e011.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3159, 'litre', '/ˈliːtər/', 'litre.mp3', 'n. （=liter）升【容量单位】', 'e9de3d2de817cbf0d686d4da43981228_39416_1701138174.jpg', 'd_16_10188_0_2_20150808235223.png', 'The bottle contains a litre of milk.', '这个瓶子装了一升牛奶。', 'us_The_bottle_20231128102301817_1ca06db43a510efaa1d9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3160, 'lonely', '/ˈloʊnli/', 'lonely.mp3', 'adj.孤独的', 'i_16_17209_0_4_160202174343-manual-scale.jpg', 'd_24_17209_0_4_20150808232356.png', 'The girl felt so lonely in this empty house.', '女孩一个人在这空荡的房间里，觉得非常孤独。', '0054b30aa67de862_1266763524182223720_250117.mp3', 'lone孤独的 + ly…地 → lonely孤独的；荒凉的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3161, 'look out', '/lʊk aʊt/', 'look out.mp3', 'phr.当心，留神', '8ca4fa486a85bd2dc2c8f813650fe20a_248907_1729576452.jpg', '', 'Look out! Don\'t fall into the hole!', '当心！别掉进洞里了。', '510875f1dde2af85_1266883486044564312_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3162, 'loyal to', '/ˈlɔɪəl tu/', 'loyal to.mp3', 'phr.效忠于', '4c5e607bb51d00a90c9b823fc5d0b066.jpeg', '', 'He\'s a loyal customer to this steak house. ', '他是这家牛排餐厅的忠实顾客。', '52af712b713405c0bda7ced0468cbb80.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3163, 'major', '/ˈmeɪdʒər/', 'major.mp3', 'adj.主要的；  n.主修（科目）', 'abb5a48382b2dd3abc9e12abd3dc8245_78924_1656986650.jpg', 'd_16_11032_0_2_20150808235936.png', 'A major cause of lung cancer is smoking.', '导致肺癌的一个主要原因是吸烟。', '3_0_20170712071411_3153_c.aac', 'maj大 + or...的 → major较大的，主要的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3164, 'memo', '/ˈmemoʊ/', 'memo.mp3', 'n.备忘录', 'i_4_7900_0_3_20150808171229-gigapixel-scale.jpg', '20140817_01_40_06_710_v3.png', 'I put memos everywhere to remind me of things that I must do.', '我把备忘录放得到处都是，以提醒自己必须做的事。', 'sa_4_7900_0_3_20150808171229.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3165, 'mere', '/mɪr/', 'mere.mp3', 'adj.仅仅的；纯粹的', 'f0cc473922c8a73a5d381b3f3a97150b_167221_1573806695.jpeg', 'd_1_6633_0_2_20150808125259.png', 'He was late by mere seconds', '他迟到了仅仅几秒钟，就被罚了200元。', '4b1b679dcbbc35665185048851e6316d_48848_1574673629.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3166, 'message', '/ˈmesɪdʒ/', 'message.mp3', 'n.消息，信息，留言；  v.发消息', 'i_16_17723_0_6_151222174255-gigapixel-scale.jpg', '20141014_06_16_51_28_v3.png', 'She left a message on the table for her son.', '她在桌子上给儿子留了一条消息。', '7ecabb2d8aa453e7_1266883320851245908_250207.mp3', 'mess送出 + age表名词 → 送出的信息 → message消息，信息', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3167, 'mirror', '/ˈmɪrər/', 'mirror.mp3', 'n.镜子；真实的写照，反映', '869d3382aad2e380afeacec222d3dd16_83490_1534227578.jpeg', 'd_24_5700_0_4_20150808224301.png', 'The old woman is looking into the mirror.', '这个老奶奶正在照镜子。', 'd101423f30f47d38_1266883112746244764_250207.mp3', 'mirr惊奇，看 + or表名词 → 能看见自己而感到惊奇 → mirror镜子', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3168, 'miserable', '/ˈmɪzrəbl/', 'miserable.mp3', 'adj.痛苦的，悲惨的；令人难受的', 'e0d452f42527ca461480a65289fd4069_196403_1588090900.jpeg', 'd_1_5437_0_3_20150808123841.png', 'The man feels tired and miserable.', '这个男人感到疲倦和痛苦。', '41ba4b81115262f7_1266763448111749838_250117.mp3', 'miser可怜 + able……的 → miserable可怜的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3169, 'nature', '/ˈneɪtʃər/', 'nature.mp3', 'n.大自然', '8b0456b0a711c344e2081290390f3a86_100090_1588136359.jpeg', 'd_24_17965_0_4_20150808233819.png', 'She loves being surrounded by nature.', '她喜欢被大自然包围。', 'dta84ek5cz5ml7jdnlnksxdh9lycgbsf.mp3', 'nat出生的 + ure状态 → 出生状态 → nature天性', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3170, 'neat', '/niːt/', 'neat.mp3', 'adj.整洁的；未经稀释的', '20120623_03_11_20_270-gigapixel-scale.jpg', '20121225_19_17_36_798.png', 'This house is very neat.', '这个房间很整洁。', '5874f809b3469b36_1266883324027448232_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3171, 'niece', '/niːs/', 'niece.mp3', 'n.侄女，外甥女', 'dbdaa8e9890333cba4c6667c9d9da1c5_37597_1565623852.jpg', '', 'My niece is my sibling\'s daughter.', '我的侄女或外甥女就是我兄弟姐妹的女儿。', '7732c58e8de15c78_1266883114063387318_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3172, 'of course', '/əv kɔːrs/', 'of course.mp3', 'phr.当然', '3_0_20170712071258_2929_c.jpg', '', 'Of course', '当然是胳膊强壮的那个人会赢啦。', 'us_Of_course_20250307112328951_47090f20e87757ebd031.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3173, 'offence', '/əˈfens/', 'offence.mp3', 'n.犯罪', 'a54131fe0e661a5a90c1f731bceb8805_289287_1586424054.jpg', '', 'He must be punished for this terrible offence.', '他必须因为这一严重犯罪行为而受到惩罚。', '4020c53b0ef8d1270b8f650a73b35aee_39365_1533545812.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3174, 'on average', '/ɑːn ˈævərɪdʒ/', 'on average.mp3', 'phr.平均，通常', '0e78e7077e034931b1db2cebf64e6264_67143_1617766090.jpg', '', 'On average', '平均来说，我每周早饭吃三个包子。', '29288a147cb8bac1e0acbe4cbee07122_111628_1617766081.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3175, 'on guard', '/ɑːn ɡɑːrd/', 'on guard.mp3', 'phr.（保持）警惕', 'i_40_20212_0_3_20150809022134.jpg', '', 'I don\'t have to worry about my things because my dog is on guard.', '我不用担心我的东西，因为有我的狗在站岗。', 'sa_40_20212_0_3_20150809022134.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3176, 'on the contrary', '/ɑːn ðə \'kɑːnˌtreri/', 'on the contrary.mp3', 'phr.与此相反，正相反', 'i_34_20072_0_4_20150809004259.jpg', '', 'One dog is very big; the other', '一只狗非常大；另一只正好相反，非常小。', 'sa_34_20072_0_4_20150809004259.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3177, 'out of touch with', '/aʊt ʌv tʌtʃ wɪð/', 'out of touch with.mp3', 'phr.与……不接触，不联系', '67a3d7f9f75555264bc70f74bc70cbba.jpeg', '', 'She has been out of touch with her friend for years.', '她和朋友已经多年没有联系了。', '36e3a91f958be9d47ad819aea97cd3e2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3178, 'overall', '/ˈoʊvərˌɔl/', 'overall.mp3', 'adj.全面的，全部的；  n.罩衫，工装服', '065f42794bf172f7f6f88f1d51bb94b7_71050_1672982841.jpg', 'd_1_8972_0_3_20150808131111.png', 'A good student should maintain overall development.', '三好学生应该全面发展。', 'b8256600b040601978cb826aac7a8cd5_17600_1623738459.mp3', 'over覆盖 + all全部 → 覆盖全部 → overall全部的，全面的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3179, 'overload', '/ˌoʊvərˈloʊd/', 'overload.mp3', 'v.使超载，使过载；使负担（或负荷）过重（读作/ˌoʊvərˈloʊd/）；  n.过重负担', 'overload_8865_20231106_c2e0a8c8.jpg', '20140712_13_53_43_842_v3.png', 'That bicycle is overloaded', '这辆自行车超载了，这太危险了。', 'sa_8865_2_0_3_150707154315.mp3', 'over过度、太甚 + load负载，装载 → 使超载，超过负荷', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3180, 'passenger', '/ˈpæsɪndʒər/', 'passenger.mp3', 'n.乘客，旅客', '3_0_20160718113028_71468_c-manual-scale.jpg', 'd_16_16526_0_2_20150809002839.png', 'All the passengers are seated and ready for the trip.', '乘客们已经坐好了，准备开始旅程。', '573a8b0a79135e4f_1268213315745301476_250930.mp3', 'pass通过 + enger人 → 通过的人 → passenger乘客', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3181, 'passport', '/ˈpæspɔːrt/', 'passport.mp3', 'n.护照；途径，手段', '44900f831ccbd50f27952b8573d88d94_105034_1740115927.jpg', '20130105_10_22_11_199.png', 'I got many stamps on my passport.', '我的护照上盖了很多章。', 'aa7a3e78b50abb5e_1266883009614142138_250207.mp3', 'pass通过 + port港口 → 通过港口的凭证 → passport护照', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3182, 'pick', '/pɪk/', 'pick.mp3', 'v.挑选；采摘；  n.精品，精华', '1a4fcb2b414954240bf1ccbb8dde7ab9_59979_1557469188.jpeg', 'd_24_2722_0_4_20150808223257.png', 'He picked out the block from the middle of the row.', '他挑出了这排中间的木块。', 'zl3tudfarcbnanvdk225jgnbu8scmzw8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3183, 'picture', '/ˈpɪktʃər/', 'picture.mp3', 'n.照片，图片；  v.拍摄，画', '11df1b98ca92a5ae218aeeef4f61cbd0_169921_1574823749.jpeg', 'd_24_17189_0_4_20150808232321.png', 'We took a group picture in front of this famous attraction in Rome.', '我们在罗马的这个著名景点前拍了一张合照。', '1a927422d83b594784a1ea438d7db15a_30353_1621924564.mp3', 'pict描画 + ure名词后缀 → picture图画，照片', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3184, 'pioneer', '/ˌpaɪəˈnɪr/ ', 'pioneer.mp3', 'n.先锋，先驱；  v.开辟，首倡', '3_0_20170930071751_2353_c-gigapixel-scale.jpg', 'd_24_8558_0_4_20150808225815.png', 'He\'s a pioneer in climbing', '他是登山的先锋，即第一个到达山顶的人。', 'fed1f30d519000181089e4f372a35134_44000_1603275460.mp3', 'pion=ped脚 + eer表示人  → 用脚走路的人  → pioneer先锋', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3185, 'poem', '/ˈpoʊəm/', 'poem.mp3', 'n.诗，韵文，诗体文', '1738a82122195ad5425917d9f9ff9450_124046_1756785046.jpg', 'd_94_13756_0_4_20150809010154.png', 'This great poem was written by Li Bai.', '这首名诗是李白写的。', 'uhg2ayj6rencl824s7nh3pubcfbjy98l.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3186, 'population', '/ˌpɑːpjuˈleɪʃn/', 'population.mp3', 'n.（地区、国家等的）人口', 'i_24_8105_0_4_20150808225450-gigapixel-scale.jpg', 'd_24_8105_0_4_20150808225450.png', 'The world population is about eight billion.', '全世界大概有80亿人口。', 'yhl8kx8vukrunwtmnadsm8fbymjxbzyt.mp3', 'popul人民 + ation表示行为、状态 → population全体居民，人口', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3187, 'possibly', '/ˈpɑːsəbli/', 'possibly.mp3', 'adv.也许，或许', 'eb29d05ed37939acc3429f4e995d2fcb_159806_1583488344.jpeg', '', 'Possibly', '也许我真的可以得到一个惊喜！', '81eb4b195f7e152b9e28721158242d24_28539_1583488341.mp3', 'poss可能 + ibly...地 → possibly可能地；也许', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3188, 'postpone', '/poʊˈspoʊn/', 'postpone.mp3', 'v.推迟，延缓', '555ead5ca22c43a8de392cb265e6333f_94222_1732589895.jpg', '20130301_12_40_29_897.png', 'I need to postpone my to-do lists.', '我需要推迟我的待办事项。', '29ddae6ac4b9d4bd_1266883493872577310_250207.mp3', 'post在后面 + pon放 + e → 放到后面 → postpone推迟', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3189, 'preside at', '/prɪˈzaɪd æt/', 'preside at.mp3', 'phr.主持', 'acdad333f6f6d79d41ea60cc1cf41821.jpg', '', 'The woman in the black dress is presiding at this meeting.', '穿着黑裙子的女士正在主持会议。', '522559aa19cb9c868dc15959bff7b838.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3190, 'province', '/ˈprɑːvɪns/', 'province.mp3', 'n.省；领域，部门', '96d7fc4508d97a79d83837987b30ec06_248310_1656929024.jpg', 'd_109_2153_0_2_20150809053423.png', 'This is a famous tourist spot in Sichuan Province.', '这是四川省的一处著名旅游景点。', 'l6gajnsgdwc5v2e4q3k4p6ayzafvgr6v.mp3', 'pro向前，在前 + vinc征服 + e → province被向前征服了的（土地）→ 省；领域', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3191, 'pull down', '/pʊl daʊn/', 'pull down.mp3', 'phr.拆毁', '987d4d5624c5999b97ae458cfc23ddd5_169335.jpg', '', 'After #pulling down# this old house', '拆毁这幢老房子后，我们就可以建新的了。', '0a69fb3864c783ac59a56d4f582592c3_36511.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3192, 'push', '/pʊʃ/', 'push.mp3', 'v.推；  n.推，推力', 'cb339475a76cd95e4bee78f057bb3443_95624_1577955575.jpeg', 'd_93_13880_0_4_20150809002201.png', 'The man tried very hard to push the car.', '这个男人非常努力地推车。', 'pga98hyxhtx9wrdgwpa7c2ct6s528qn6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
