INSERT INTO `words` VALUES (3194, 'radio', '/ˈreɪdioʊ/', 'radio.mp3', 'n.收音机；无线电', '663457ba9ff16b9b65f93d30f079b9de_137730_1575017455.jpeg', 'd_24_16617_0_3_20150808231646.png', 'The woman is listening to the radio with a cup of coffee in her hand.', '这位女士手端着咖啡，正在听收音机。', 'm4hjfbs6lefqywa95s9tlqy7j5bs9l64.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3195, 'rarely', '/ˈrerli/', 'rarely.mp3', 'adv.很少，难得', 'b813b5e690dacbbf1d442b7a556198cc_173782_1544066069.jpeg', 'd_107_3914_0_2_20150809003445.png', 'It rarely snows in Chengdu.', '成都很少下雪。', 'fb6225f6af7f4d81_1266883372480834508_250207.mp3', 'rare稀少的 + ly……的 → rarely很少，难得', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3196, 'react to', '/riˈækt tu/', 'react to.mp3', 'phr.对...起反应', 'dedcd3f89227b500b2992b078569d603.jpg', '', 'She reacted to the food and felt terrible.', '她对这盘食物起了反应，感觉很难受。', '7f1486b706ac26d60d3f4537e93ec1b9_46112_1593575115.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3197, 'recently', '/ˈriːsntli/', 'recently.mp3', 'adv.最近地', '37b282b0588b59f473683c2b1291a6af_132114_1575104973.jpeg', 'd_1_4937_0_2_20150808123206.png', 'He recently spent some time on the beach and got a tan.', '他最近在海滩上待了一段时间，晒黑了。', 'bb92f4418a57b90e_1266883009669978812_250207.mp3', 'recent最近 + ly表副词 → recently最近', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3198, 'reception', '/rɪˈsepʃn/', 'reception.mp3', 'n.前台，接待处', 'i_1_5810_0_4_150928175456-gigapixel-scale.jpg', '', 'The young couple got their room key at the reception of the hotel.', '这对年轻的夫妇在酒店前台拿到了他们房间的钥匙。', 'sa_1_5810_0_4_151017114158.aac', 're回，向后 + cept拿，握住 + ion名词后缀 → 接收', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3199, 'recommend', '/ˌrekəˈmend/', 'recommend.mp3', 'v.推荐，介绍；劝告，建议', 'f0fb0ae8576dd19ac9340bdc6d809df2_62900_1699413179.jpg', 'd_16_7948_0_5_20150808232224.png', 'The snack was highly recommended by the actress.', '这名女演员极力推荐这款零食。', 'f0ee994e17131413_1266763524723878776_250117.mp3', 're加强 + commend推荐 → recommend推荐', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3200, 'refer to...as', '/rɪˈfɜr tu æz/', 'refer to...as.mp3', 'phr.把……称为', '91985d99697c6b8b2c419aab8434d14c.jpg', '', 'The little boy refers to the tent in his room as his secret place.', '小男孩把他房间里的帐篷称为他的秘密基地。', '678147bc266346ae0b0ea4c3089c63a5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3201, 'regret', '/rɪˈɡret/', 'regret.mp3', 'v.对……感到后悔，对...感到遗憾；  n.歉意', 'bcab63d247e92ccd60535134ecac6739_200184_1578559621.jpg', '20130316_16_34_50_871.png', 'He regrets that he didn\'t prepare well for the English exam.', '他后悔没有好好准备英语考试。', '594f6a813be6fb5e_1266883002754488840_250207.mp3', 're表强调 + gret哭泣，流泪 → regret后悔', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3202, 'regularly', '/ˈreɡjələrli/', 'regularly.mp3', 'adv.经常，定期地', '56fcb21916f73e45eaedcdaabbe1a550_64091_1569572294.jpeg', '', 'We meet regularly to discuss the progress of the project.', '我们定期会面，讨论工程的进展情况。', '4794eb4d67f0f41a_1266797982809283100_250123.mp3', 'regular通常的 + ly……地 → regularly有规律地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3203, 'regulation', '/regjəˈleɪʃən/', 'regulation.mp3', 'n.规章，法规，条例；管理', 'c27d36b72369496c799bc2b3edf91c49_29634_1646647736.jpg', 'd_16_5113_0_4_20150808225011.png', 'The traffic police is introducing traffic rules and regulations to us.', '交警在向我们介绍交通法规。', '3_0_20160520173248_58520_c.aac', 'regul规则、统治 + ation表名词 → 有规则的 → regulation规则，规章', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3204, 'relationship', '/rɪˈleɪʃnʃɪp/', 'relationship.mp3', 'n.关系', '8d34ae8a64f607209bdd33e0491aa75f_177605_1578561816.jpeg', '', 'These five people have different relationships with each other.', '这五个人之间有不同的关系。', '5bd090b00ce1916fe4e8de19f6edffaf_44302_1578561814.mp3', 'relation关系 + ship表名词 →（亲属）关系', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3205, 'reward', '/rɪˈwɔːrd/', 'reward.mp3', 'n.奖品，奖励；回报，报答；  v.报答，回报', '7ff42064c5749dc1f91902237ccfe9ed_83245_1529483301.jpg', 'd_24_4026_0_4_20150808223433.png', 'I got a reward for my hard work.', '我因努力工作获得了报酬。', '032553f997f9ad50fa6d579ffcca6b55_11261_1529483177.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3206, 'round', '/raʊnd/', 'round.mp3', 'adj.圆的，球形的；  n.圆，圆形物；  adv.围绕着；  v.（使）成圆形；  prep.围绕', '33508e37d5a623ca8a0e789527b310bf_607831_1701139479.jpg', 'd_24_15901_0_4_20150808230740.png', 'Fortunately we now know that the Earth is round', '所幸我们现在知道地球是圆的，而不是平的。', 'sa_12_15901_0_2_20150808184142.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3207, 'run through', '/rʌn θruː/', 'run through.mp3', 'phr.挥霍', '09f76b67aa2a06c30995f87549fae8dd.jpeg', '', 'He ran through his savings as if they would never run out.', '他挥霍无度，仿佛钱永远花不完一样。', '84c225tsx8v2rmpya978j77jhabxtamg.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3208, 'scrape through', '/skreɪp θruː/', 'scrape through.mp3', 'phr.勉强通过', '6f5a241be720dc217ab2a89cebea14ac.jpeg', '', 'He scraped through the exam.', '他勉强通过了这次考试。', 'e51587ac6e961f2adffc03365af8cc8b_60591_1599537568.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3209, 'scream', '/skriːm/', 'scream.mp3', 'v.（因愤怒或恐惧）高声喊；尖叫着说出', 'eeca19b16887d43a1351e3da017d568c_77164_1617762655.jpg', 'd_24_8124_0_4_20150808225518.png', 'This cute animal is screaming in fear. ', '这只可爱的动物因为害怕而尖叫。', 'ece734e256a5160b1bfb26730fb92990_14936_1623812462.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3210, 'search for', '/sɜrtʃ fɔr/', 'search for.mp3', 'phr.搜寻，寻找，搜索', 'd701b9d19f1e9bbbc3c5e6e7aff0d3f6.jpg', '', 'The little boy is searching for his toy car.', '小男孩正在寻找他的玩具车。', '81e4b27b68b85494a66a217b72c36d1e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3211, 'shape', '/ʃeɪp/', 'shape.mp3', 'n.形状，样子；  v.使形成，塑造', 'f899874829c0940b7778e873ebaf269e_87295_1577956265.jpeg', 'd_24_18758_0_3_20150808235648.png', 'Put your hands together to make a heart shape.', '把你的手放在一起比个心形。', 'ad94ce5d20f7cb96_1266883004435421732_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3212, 'shock', '/ʃɑːk/ ', 'shock.mp3', 'v.使……震惊，使惊讶；使……震动；  n.震惊；震动', 'b8c93b746b43fec803e755a630ebb68d_107914_1740562665.jpg', 'd_16_3922_0_2_20150808223823.png', 'Everyone was shocked by how fragile the wine glass is.', '大家都对这个酒杯如此易碎感到震惊。', 'mez7xpuw25mlkmp286ez44qamcf8kbkc.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3213, 'sleeve', '/sliːv/', 'sleeve.mp3', 'n.袖子', '31c7fdd87dd55ac5e03cccb2c3f83636_31721_1565695476.jpg', '20140929_03_03_08_704_v3.png', 'In winter', '冬天，我比较喜欢穿长袖衬衫。', 'fk6l86nhxsz8ygrvl5rz95tkzn79eh7g.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3214, 'soil', '/sɔɪl/', 'soil.mp3', 'n.泥土，土壤；国土，领土；  v.弄脏；污损', 'i_1_5658_0_4_160415141154-gigapixel-scale.jpg', '20121225_19_00_20_641.png', 'He is holding some soil in his hands.', '他手里捧着一些泥土。', '8a1fdc500fb1649b_1266883528537496186_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3215, 'spring', '/sprɪŋ/', 'spring.mp3', 'n.春天；  v.反弹，跳，跃', '9790c2b707e9318a13d623571deff1c1_199872_1573719771.jpeg', 'd_24_15982_0_3_20150808230935.png', 'In China', '在中国，飞燕是春天的标志。', 'e025f4cfe0809de1_1266763405737220724_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3216, 'statistics', '/stəˈtɪstɪks/ ', 'statistics.mp3', 'n.统计数字；统计学', '3e7f9519f31d6a78e95c46359d3213d4_64514_1565342889.jpg', 'd_105_5749_0_2_20150809055129.png', 'I use facts and statistics to prove my point.', '我用事实和统计数字来证明我的观点。', 'sa_1_5749_0_2_20150808124330.aac', 'statist站，立 + ics名词后缀，学科 → 站着去计算数据的学科 → statistics统计学', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3217, 'strength', '/streŋθ/', 'strength.mp3', 'n.体力，力气，力量；长处；实力', '2e412934cc1cf4fcfd72d0c2dd5e8ac1_85308_1533105386.jpeg', 'd_16_5536_0_2_20150808225409.png', 'The man is flipping a heavy tire to build his strength.', '那个男人正通过推起一个沉重的轮胎来锻炼力量。', 'ndzd78jxmqhhnl6uyzj5azr5l5hzakq2.mp3', 'streng=strong强壮的 + th抽象名词 → strength力量', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3218, 'strict', '/strɪkt/', 'strict.mp3', 'adj.严厉的；确切的', '1f706bf48fdc283911ea72eb590e0e9b_94706_1565343526.jpg', 'd_24_8029_0_4_20150808225357.png', 'The teacher is strict during the exam.', '老师监考非常严格。', '9a5b6c7644358b32_1266883533389322936_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3219, 'strike', '/straɪk/', 'strike.mp3', 'v.击打；袭击；罢工；  n.罢工；打击；袭击', 'c_i_wm_20120513_04_40_51_800-manual-scale.jpg', '20130130_16_24_52_878.png', 'Strike the ball flat and hard to knock it out of the stadium.', '用力朝水平方向击球，就能把球打出场外。', '74081457da53de9a_1266883329270328070_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3220, 'submit to', '/səbˈmɪt tu/', 'submit to.mp3', 'phr.屈服', '4f32524a6440dec315743cacc894c7e5.jpeg', '', 'He submitted to the fact that one day he would be replaced by AI robot. ', '他屈服于将来被人工智能机器人取代的事实。', 'f10563d9affd985dbd8c29b7ef7201e5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3221, 'sunscreen', '/ˈsʌnskriːn/', 'sunscreen.mp3', 'n.防晒霜', '458c4aaa3bf25ad06ea08bd92ccfc425_34010_1588084897.jpeg', '', 'The sunscreen will protect her skin from the sun\'s rays.', '防晒霜会使她的皮肤免受太阳光的伤害。', 'c29b9ed6d8861fd310bd7e6370f74779_48358_1588084892.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3222, 'sunset', '/ˈsʌnset/', 'sunset.mp3', 'n.日落，傍晚；  adj.霞红色的', '3_0_20170713071703_57509_c-gigapixel-scale.jpg', '20121225_19_06_36_535.png', 'The sunset on the river looks amazing tonight.', '今天傍晚，河上的日落美不胜收。', '3_0_20170713071703_8721_c.aac', 'sun太阳 + set落 → sunset 日落', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3223, 'survey', '/ˈsɜrˌveɪ/', 'survey.mp3', 'n.调查；  v.鉴定', '926928d4738e98404877c875bb7c54d2_108455_1656917932.jpg', '20141010_01_09_43_549_v3.png', 'The old lady is taking a survey.', '这位年老的女士正在做调查。', '91d91a79c1b716a1_1266883113300241310_250207.mp3', 'sur在上面 + vey看 → 从上面看 → survey调查', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3224, 'sweat', '/swet/', 'sweat.mp3', 'v.出汗；  n.汗水', 'i_1_8228_0_3_20150808130515-gigapixel-scale.jpg', 'd_16_8228_0_2_20150808232729.png', 'I sweat a lot whenever I get to work.', '每次去上班，我都会出很多汗。', 'xrxdtpcrtacgzf9fvzqvrbfm7umqsnem.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3225, 'sympathy', '/ˈsɪmpəθi/', 'sympathy.mp3', 'n.同情；同感', 'i_1_5841_0_4_160323153325-gigapixel-scale.jpg', 'd_16_5841_0_4_20150808225930.png', 'He felt a lot of sympathy for the dog and gave it a bone.', '他很同情那条狗并给了它一根骨头。', 'sa_1_5841_0_4_160324171646.aac', 'sym共同 + pathy感情 → sympathy同情', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3226, 'take exception to', '/teɪk ɪkˈsepʃən tu/', 'take exception to.mp3', 'phr.反对', 'bd794cad179c80d3f9e6980f8c0c7d6f_186715.jpg', '', 'The celebrities took exception to the flashing cameras.', '这些名人反对被相机拍摄。', '7dce0c56f030239cc5438429d6bbdf9d_35263.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3227, 'taste of', '/test ʌv/', 'taste of.mp3', 'phr.……的味道', '0068bc2b548cba4dfaebd5593ed794e8.jpeg', '', 'She loves the taste of this cake. ', '她喜欢这个蛋糕的味道。', '331de5f6b3b0866241dea4dde0b396a6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3228, 'thunder', '/ˈθʌndər/', 'thunder.mp3', 'n.雷，雷声；轰隆声；  v.大声斥责', 'i_1_6786_0_4_151029115949-gigapixel-scale.jpg', 'd_16_6786_0_2_20150808231052.png', 'Don\'t stand under a tree when there is thunder. Lightning might strike you.', '打雷时不要站在树下，闪电可能会击中你。', 'sa_1_6786_0_4_151109170055.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3229, 'tie', '/taɪ/', 'tie.mp3', 'n.领带；  v.打成平局', '3_0_20170712071429_98099_c-gigapixel-scale.jpg', 'd_24_7999_0_3_20150808225330.png', 'He puts on his tie before going to work.', '他去上班之前会系上领带。', 'f8b0da78882e4efd_1266763245407918844_250117.mp3', ' ', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3230, 'tuition', '/tuˈɪʃn/', 'tuition.mp3', 'n.学费', 'bca4b695270a297add1b44c44f3522f6_96639_1595057822.jpg', 'd_105_6856_0_2_20150809060106.png', 'College tuition costs a lot of money.', '大学学费会花很大一笔钱。', '76fb07b843eaa216a4b57ef56349eb8b_41888_1595057827.mp3', 'tuit保护 + ion表名词 → 受教育的费用 → tuition学费；教导', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3231, 'turn up', '/tɜːrn ʌp/', 'turn up.mp3', 'phr.调高，来到，出现，到场', 'i_16_18903_0_5_151102102704.jpg', '', 'He turned up the volume on his phone to listen to music.', '他把手机音量调大听音乐。', '9gkun22yjj95ml7r767myecrh3uwn7pc.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3232, 'typical of', '/ˈtɪpɪkəl ʌv/', 'typical of.mp3', 'phr.是……的典型，是……的特征', 'ffc5d4c69c9a3c79ad10a0ccce3812c1.jpeg', '', 'Serving food on a banana leaf is typical of Indian cuisine.', '用香蕉叶盛食物是典型的印度菜风格。', 'd49a4af060dbc592b9256bf697966493.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3233, 'unusual', '/ʌnˈjuːʒuəl/', 'unusual.mp3', 'adj.特别的，不常见的', 'i_1_8419_0_3_20150808130732-gigapixel-scale.jpg', 'd_109_8419_0_2_20150809055601.png', 'That guy has an unusual ability! He can fly!', '这个男人有不寻常的能力！他会飞！', 'j6vbn9wdm33cxu3dj7u4xlkus4p243t8.mp3', 'un不 + usual通常的 → unusual不平常的；与众不同的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3234, 'upper', '/ˈʌpər/', 'upper.mp3', 'adj.较高的，上面的；  n.鞋面', 'i_1_5056_0_4_20150808123413-gigapixel-scale.jpg', 'd_16_5056_0_5_20150808224903.png', 'You can see the entire city from the upper floors of the building.', '从大厦的高层，你可以看到整个城市。', 'us_You_can_20250115143416072_d9a7ababc61af2bdc31c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3235, 'wage', '/weɪdʒ/', 'wage.mp3', 'n.工资，薪水；  v.开展，进行（战争、运动）', 'i_1_3936_0_2_20150808122112-gigapixel-scale.jpg', 'd_16_3936_0_2_20150808223839.png', 'The worker was so happy when she got her wages.', '这个工人拿到工资的时候很开心。', 'ad2b38462ed2f044_1266883321569172078_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3236, 'waitress', '/ˈweɪtrəs/', 'waitress.mp3', 'n.女服务员；女侍者', '20120606_03_51_02_99-manual-scale.jpg', '16aa444c7b08e3c5cdc3859041cb3efe_80704_1551250627.png', 'Can you ask the waitress to bring the bill?', '你能让女服务员把账单拿来吗？', '56ba46499d90330a_1266883112558373774_250207.mp3', 'wait等待 + ress女性 → waitress女服务员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3237, 'war', '/wɔːr/', 'war.mp3', 'n.战争；对抗', 'd3ea4e209913f875f38a3be868902678_190940_1733116434.jpg', 'd_24_16443_0_3_20150808231241.png', 'These two countries are having a war.', '这两个国家在打仗。', 'us_These_two_20220506094922697_55450414c05d2a7dac2e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3238, 'weather', '/ˈweðər/', 'weather.mp3', 'n.天气；  v.风化，受风蚀，经受风雨', '6fdc63a8a3b428e8e0da410d58fa9a83_75359_1617765690.jpg', 'd_24_18106_0_3_20150808234629.png', 'The weather was different when we went back to that place.', '我们再回到那个地方的时候，天气不一样了。', '0fcd19f07a300204_1266763445638224516_250117.mp3', 'we吹 + ther后缀 → 吹风等天气 → weather天气', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3239, 'weekly', '/ˈwiːkli/', 'weekly.mp3', 'adv.一周一次地；  adj.每周的，一周一次的；  n.周报，周刊', '229004bbf252f81594d83e16fb7b9386_131436_1750758208.jpg', 'd_24_6199_0_3_20150808224520.png', 'This TV show is updated weekly.', '这个电视节目每周更新一次。', 'sa_1_6199_0_4_151109170719.aac', 'week周 + ly表副词，每……地 → 每周的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3240, 'welfare', '/ˈwelfer/', 'welfare.mp3', 'n.福利', '2fee0459e717e6e0bd92ba0002ad6794_141491_1549953998.jpeg', 'd_16_5077_0_2_20150808224927.png', 'The organization aims to improve the welfare of animals.', '这个组织旨在提升动物的福利。', '14ac9b57a52d536a7e3aa8e68ef61540_48848_1572405914.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3241, 'wipe out', '/waɪp aʊt/', 'wipe out.mp3', 'phr.消灭', 'aa8c32366ab6d8f3dd0c8eee24007cb2_54119_1702013412.jpeg', '', 'Let\'s wipe out all the bugs with this insecticide.', '让我们用这瓶杀虫剂消灭所有的虫子吧。', 'sa_4_10229_0_2_20150808183547.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3242, 'admission', '/ədˈmɪʃn/', 'admission.mp3', 'n.准许进入；进入权', 'ede446631b00e4f34458ecd64f907d5b_148973_1745829382.jpg', 'd_16_3996_0_2_20150808223931.png', 'Children can gain admission to primary school at the age of 6.', '孩子要到6岁才能上小学。', 'sa_16_3996_0_4_151223154246.aac', 'admiss承认 + ion名词后缀 → admission承认，允许进入', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3243, 'afterward', '/\'ɑːftəwəd/', 'afterward.mp3', 'adv.之后，后来，以后', 'i_1_5100_0_2_20150808123505-gigapixel-scale.jpg', 'd_16_5100_0_5_20150808224953.png', 'Afterward', '随后，请清洁你家狗狗的便便。', 'sa_1_5100_0_2_20150808123505.aac', 'after以后 + ward向...的 → afterward之后', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3244, 'agent', '/ˈeɪdʒənt/', 'agent.mp3', 'n.代理商，代理人；特工', '597e3a4cc58ced0851e74cddabbc17e0_170345_1573789974.jpeg', 'd_24_8411_0_4_20150808225654.png', 'There are some real estate agents waiting for customers at the subway entrance.', '一些房产中介在地铁口等待顾客。', '35008623d07ff2df1262fba1b02c6405_42152_1574159541.mp3', 'ag做，代理做 + ent表人或物 → 代理人 → agent作用因素；代理人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3245, 'anniversary', '/ˌænɪˈvɜːrsəri/', 'anniversary.mp3', 'n.周年纪念日；  adj.（有关）周年纪念的', '1423913209745-gigapixel-scale.jpg', 'd_16_5860_0_2_20150808225946.png', 'He gave his wife a diamond ring on their tenth anniversary.', '在结婚十周年之际，他送给老婆一枚钻戒。', 'sa_1_5860_0_5_160323120709.aac', 'anni=ann年 + vers转 + ary名词后缀 → 一年的转弯处一次 → anniversary周年纪念日', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3246, 'arrival', '/əˈraɪvl/', 'arrival.mp3', 'n.到来，到达；到达者', '503963f73e17bcf72a27bbfe75b4c11a_193360_1576220402.jpeg', 'd_16_7959_0_4_20150808232241.png', 'Passengers on the platform are waiting for the train\'s arrival.', '站台上的乘客正在等候火车到站。', 'b5d772642a1256973ed483af7c161321_41278_1576220399.mp3', 'arriv(e)到达 + al名词后缀 → arrival到达', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3247, 'as well', '/æz wel/', 'as well.mp3', 'phr.同样地；也', 'bc8744f6f624f11df19c462fe1c0479b_165207_1576135849.jpeg', '', 'I am good at football and can play basketball as well.', '我擅长足球，也会打篮球。', '51938bef32e4f36e_1266763400895027948_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3248, 'aside', '/əˈsaɪd/', 'aside.mp3', 'adv.在旁边；留存；  n.离题的话', 'i_1_11451_0_3_20150808131817-gigapixel-scale.jpg', 'd_16_11451_0_2_20150809000051.png', 'Step aside to let the cars pass.', '靠边让车通行。', 'sa_1_11451_0_3_20150808131817.aac', 'a在…的 + side旁边 → 在旁边 → aside在边上', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3249, 'assess', '/əˈses/', 'assess.mp3', 'v.评估', 'bbba03ac6ff13de1afb7e2cec8f9c523_122697_1538759078.jpg', 'd_16_3881_0_2_20150808223750.png', 'How do you assess the risk level of this investment? Low', '你对这次投资的风险评估是怎样的？低风险、中风险，还是高风险？', '99ffac81679d0a0f3fde4bbf129d4036_26691_1538759107.mp3', 'ad=as有关 + sess坐 -> 文职人员都是坐着的 -> 评估', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3250, 'at any rate', '/æt ˈɛni ˌreɪt/', 'at any rate.mp3', 'phr.无论如何', 'i_910_-910_0_1_160322142757.jpg', '', 'Hold on to me! I won\'t leave you alone at any rate.', '“抓紧我！无论如何我都不会丢下你不管的。”', '29fbc3e8efbc25b0_1266883377094568870_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3251, 'Atlantic', '/ətˈlæntɪk/', 'Atlantic.mp3', 'adj.大西洋的；  n.大西洋', '20120503_04_47_59_473-gigapixel-scale.jpg', 'd_24_6202_0_4_20150808224523.png', 'There are big pieces of ice melting into the North Atlantic Ocean.', '有一大块冰融化到了北大西洋。', 'sa_103_6202_0_3_20150809022309.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3252, 'average', '/ˈævərɪdʒ/', 'average.mp3', 'n.平均数；  adj.通常的；  v.平均为', 'i_1_18875_0_4_150902145921-gigapixel-scale.jpg', 'd_24_18875_0_4_20150808235840.png', 'His height equals the average of his parents\' heights.', '他的身高等于他父母身高的平均数。', '3_62_20170819145557_8792_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3253, 'baggage', '/ˈbæɡɪdʒ/', 'baggage.mp3', 'n.行李', '3eefcc88f7bd89286a666725d6ecc19f_128190_1701670345.jpg', '20141015_16_13_17_685_v3.png', 'The young man is waiting for his baggage.', '这个年轻人正在等他的行李。', 'sa_1_5318_0_6_150923104529.aac', 'bagg=bag包 + age表示集合名词、总称 → baggage行李', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3254, 'beat', '/biːt/', 'beat.mp3', 'v.敲打，击打；打败，击败；有节奏地跳动；搅拌，搅打（用叉等）快速搅拌；  n.敲打；节拍', '1997b6cbe3c3fd75e8d214e89bce6ee4_79367_1577950754.jpeg', 'd_24_5626_0_4_20150808224232.png', 'He is beating the drum hard with two sticks.', '他正用两根鼓槌使劲击鼓。', '4794e9e1e7a467714432be772f85071e_39550_1577950750.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3255, 'bid', '/bɪd/', 'bid.mp3', 'n.出价；投标；努力争取；  v.出价；投标；问候；道别；吩咐', 'e7da440f4a6e6293f189ba63e5550e1a_119209_1682069814-800-600.jpg', 'd_16_322_0_2_20150808223212.png', 'The winning bid in the auction was $5.', '拍卖的中标价是5美元。', 'sa_1_322_0_3_20150808113754.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3256, 'bike', '/baɪk/', 'bike.mp3', 'n.自行车；  v.骑自行车', 'i_1_19506_0_2_20150808132644-gigapixel-scale.jpg', 'd_24_19506_0_4_20150809001724.png', 'I like riding my bike around the city.', '我喜欢骑自行车环绕城市。', '7d4a73798316fc4b_1266763447534922688_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3257, 'bind', '/baɪnd/', 'bind.mp3', 'v.捆绑；装订；约束；结合', 'i_1_5776_0_3_20150808124359-gigapixel-scale.jpg', 'd_21_5776_0_3_20150808193729.png', 'The mummies help to bind each other with the bandage.', '木乃伊互相帮着绑绷带。', '6f88d614864d0fedbc2e0d76488738f5_13821_1534233187.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
