INSERT INTO `words` VALUES (3260, 'bury', '/ˈberi/', 'bury.mp3', 'v.隐藏，埋藏；埋葬', '14b22fd37b13646fd3324d4bc8074f52_89595_1688027890.jpg', 'd_24_6765_0_4_20150808224747.png', 'The ostrich buried its head in the sand.', '这只鸵鸟把头埋在沙子里。', 'a56697aaca9c692e_1266883481018936262_250207.mp3', 'bur隐藏；保护 + y表发音 → bury隐藏；埋葬', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3261, 'by reason of', '/baɪ ˈriːzən əv/', 'by reason of.mp3', 'phr.由于', 'c1469f06a6032640d3272c9eb5da5077.jpg', '', 'She was asked for help by reason of her experience in dealing with this disease.', '因为她在治疗这种疾病方面有丰富的经验，所以病人向她寻求帮助。', '852118e6bea8e366345356fafc2b0c1b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3262, 'call up', '/ˈkɔːl ʌp/', 'call up.mp3', 'phr.打电话，号召', 'i_16_17857_0_5_20150809012757.jpg', '', 'She is going to call up her boss.', '她正准备给她老板打电话。', 'sa_16_17857_0_5_20150809012757.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3263, 'cheer', '/tʃɪr/', 'cheer.mp3', 'v.欢呼；鼓劲，使振作；  n.鼓励，振奋', '0bacc0445143d9ea451031742bc9641e_84454_1559039382.jpg', '', 'The sports fans cheered for their team.', '球迷们为他们的球队加油喝彩。', 'znplk7e4u5tr7pnmk6kzul2db2mkfjsa.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3264, 'cheese', '/tʃiːz/', 'cheese.mp3', 'n.乳酪，干酪，芝士', '3_0_20170705110521_93329_c-gigapixel-scale.jpg', 'd_72_12083_0_4_20150809020922.png', 'I love eating cheese.', '我喜欢吃奶酪。', '7d06766e843f7fac_1268213310981751454_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3265, 'clothing', '/ˈkloʊðɪŋ/', 'clothing.mp3', 'n.衣服；被褥', 'i_1_6222_0_7_151222175623-gigapixel-scale.jpg', 'd_109_6222_0_2_20150809054552.png', 'I have so many pretty pieces of clothing! said the girl.', '这个女孩说：“我有很多漂亮衣服。”', 'b7282a87ad95cb4d_1266883375077698370_250207.mp3', 'cloth布 + ing与……有关之物 → clothing衣服', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3266, 'collar', '/ˈkɑːlər/', 'collar.mp3', 'n.衣领', 'i_1_8922_0_5_20150808131009-gigapixel-scale.jpg', '20130105_10_22_42_908.png', 'The collar of this shirt is too tight.', '这件衬衣的衣领太紧了。', 'cpzgstfq7pzwfz5hrs2qe63cpvll4hws.mp3', 'coll脖子 + ar名词后缀 → collar衣领', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3267, 'collision with', '/kəˈlɪʒn wɪð/', 'collision with.mp3', 'phr.与……的碰撞', 'db384a47deab5866f3f98876ae512b77.jpg', '', 'The two cars had a collision with each other.', '这两辆汽车发生了碰撞。', '083e166f61e6f72f089490b3fd734801_38816_1593575477.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3268, 'come up with', '/kʌm ʌp wɪð/', 'come up with.mp3', 'phr.提出，想出；提出', '0fa45034430b0a34b5551c6188b381a3_402331_1701675950.jpg', '', 'The businesswoman has come up with many new ideas.', '这位女商人提出了很多新想法。', 'bsmaffu7uv8mnhq7pw7f5arhe4k3n64w.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3269, 'comment', '/ˈkɑːment/', 'comment.mp3', 'n.评论；批评，指责；注释，解释；  v.评论，表达意见', '3_0_20161225071035_86252_c-gigapixel-scale.jpg', 'd_107_5618_0_2_20150809013204.png', 'Some of my friends left me comments.', '我的一些朋友给我评论了。', '3_0_20161225071035_45049_c.aac', 'com共同 + ment思考，神智 → 共同思考 → 评论', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3270, 'common', '/ˈkɑːmən/', 'common.mp3', 'adj.共同的，共享的；普通的', '3_0_20170703171936_79173_c-gigapixel-scale.jpg', 'd_24_17964_0_4_20150808233815.png', 'The two boys share a common interest.', '这两个男孩有共同的爱好。', 'c2e45c4992e0af71b57430c0e831e532_20525_1621926432.mp3', 'com一起 + mon改变；去 → 所有人都共享的 → common普通的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3271, 'communicate', '/kəˈmjuːnɪkeɪt/', 'communicate.mp3', 'v.沟通，交流；传达，传递', '2a7383a9e5dbcd00127edc49991b8e0f_33134_1652782588-gigapixel-scale.jpg', 'd_107_9259_0_2_20150809024527.png', 'The police communicate with each other by radio.', '警察通过无线电进行沟通。', '6e9197f25e906329_1266883375115184964_250207.mp3', 'com共同 + muni交流 + cate表动词 → 共同交流 → 传播', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3272, 'composition', '/ˌkɑːmpəˈzɪʃ(ə)n/', 'composition.mp3', 'n.作品', '756fc7f538624f5a32b0da422f53a19b_105654_1750750584.jpg', '20130130_16_14_03_15.png', 'Beethoven\'s compositions are great works.', '贝多芬的作曲是伟大的作品。', '991c950edbceba87_1266883003839240734_250207.mp3', 'com一起 + posit放 + ion名词后缀 → 放到一起 → 组合 → composition创作、作文', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3273, 'conceive of', '/kənˈsiːv əv/', 'conceive of.mp3', 'phr.构想出', '34ff5e5828017feb51159d37434886f2.jpg', '', 'She found it difficult to conceive of him as a professional chef.', '她难以想象他是一个专业的厨师。', '4cddfcbdbd7767c0c30161d08bd668a3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3274, 'confront', '/kənˈfrʌnt/', 'confront.mp3', 'v.与某人对峙；与……对抗；正视', 'i_1_4164_0_4_150919160901-gigapixel-scale.jpg', 'd_107_4164_0_2_20150809004651.png', 'The two men confront each other with anger.', '两个男人面带怒火，相互对峙。', 'sa_1_4164_0_4_150923113921.aac', 'con共同 + front前额 → 互相面对 → confront对抗，面临', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3275, 'consequently', '/ˈkɑːnsəkwentli/', 'consequently.mp3', 'adv.因此，结果', '3_0_20170707172858_19185_c-gigapixel-scale.jpg', 'd_105_11499_0_2_20150809061909.png', 'She studied hard and consequently got high marks.', '她努力学习，因此得到了高分。', 'ebb59b9e542bb74487f67aa3a491285c_21518_1644829528.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3276, 'contradiction between', '/ˌkɑːntrəˈdɪkʃn bɪˈtwiːn/', 'contradiction between.mp3', 'phr.……互相矛盾', '2c68196dec875153d3ced53a65d01ae8.jpg', '', 'There\'s a contradiction between his hands.', '他的双手之间互相矛盾。', 'aef6d825d8fbbb4173d5b1b672694c68_38816_1593575524.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3277, 'contrast', '/ˈkɑnˌtræst/', 'contrast.mp3', 'n.差异；对照，对比；  v.对照，对比（读作/kənˈtræst/）', '7a595b9e604c7399f524f976de6f8341_122526_1718615814.jpg', 'd_1_4741_0_2_20150808122946.png', 'There\'s a striking contrast between his portrayals of two different characters.', '他扮演的两个不同的角色很有反差感。', 'us_Theres_a_20240617171617306_f23dd91b0e521b76ec71.mp3', 'contra相反 + st站 → 站在对立面 → contrast对比', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3278, 'conversion into', '/kənˈvɜːrʒn ˈɪntuː/', 'conversion into.mp3', 'phr.转变为……', '264ce8726a8b20d7d3572249879dcf85_60068_1707018649.jpg', '', 'This process requires conversion into energy. ', '这个过程需要转化为能源。', 'us_This_process_20240204115052589_1ce0bf2ee289369e9146.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3279, 'correct', '/kəˈrekt/', 'correct.mp3', 'adj.正确的；恰当的；  v.改正；矫正；批改', 'i_1_5025_0_4_20150808123339-manual-scale.jpg', '20141014_21_53_05_154_v3.png', 'Only one in four people know the correct answer to the question.', '只有四分之一的人知道这个问题的正确答案。', 'sa_1_5025_0_4_20150808123339.aac', 'cor共同，加强意义 + rect正 → 全部正确的 → 正确的，恰当的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3280, 'cream', '/kriːm/', 'cream.mp3', 'n.面霜；奶油，乳脂', '2813dbaada4cf641f2789b33f0cd42f1_198737_1585124849.jpeg', 'd_94_8429_0_3_20150809005611.png', 'She always applies face cream after shower.', '她洗完澡后总会涂面霜。', '1e1cc000446dfc90ea62b7a2eae61cde_17914_1624074869.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3281, 'crop', '/krɑːp/ ', 'crop.mp3', 'n.作物，庄稼；（一季的）收成', 'i_1_6647_0_6_151019115053-gigapixel-scale.jpg', 'd_109_6647_0_2_20150809054723.png', 'The crops are dying because of the drought.', '因为干旱，庄稼都快死了。', '7607be6ea54788e0_1266883628735376236_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3282, 'damp', '/dæmp/', 'damp.mp3', 'adj.潮湿的，有湿气的', 'i_1_741_0_3_20150808121541-gigapixel-scale.jpg', 'd_16_741_0_2_20150808223311.png', 'I had an umbrella', '尽管带了伞，我的衣服还是淋湿了。', 'sa_1_741_0_6_160407102621.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3283, 'debt', '/det/', 'debt.mp3', 'n.债', 'i_1_7912_0_3_20150808130132-gigapixel-scale.jpg', 'd_24_7912_0_4_20150808225219.png', 'The man is burdened with the housing debt.', '这个男人背负着房贷。', 'sa_1_7912_0_3_20150808130132.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3284, 'December', '/dɪˈsembər/', 'December.mp3', 'n.十二月', 'i_13_15932_0_2_20150808203546-gigapixel-scale.jpg', 'd_24_15932_0_3_20150808230851.png', 'Christmas is celebrated in December.', '人们在十二月庆祝圣诞节。', 'c412d5a6e35cd6b5_1266763445883743118_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3285, 'defence against', '/dɪˈfens əˈɡeɪnst/', 'defence against.mp3', 'phr.防御，保卫', '5e9b62487e44d23003dc93b87a8f620a.jpeg', '', 'The iron fence built by the shepherd is a great defence against the wolf. ', '牧羊人建造的铁栅栏可以很好地防御狼。', 'b807a85d836bf419cf735ea7e82ad7de.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3286, 'degree', '/dɪˈɡriː/', 'degree.mp3', 'n.学位；度', 'a52023cfc6cb93514ed759e0a2535625_82074_1565342324.jpg', '20121225_19_09_55_943.png', 'I finally got my degree after four years of studying.', '经过四年的学习，我终于拿到了学位。', 'de69dfb28e86b4ab_1266883321486814052_250207.mp3', 'de下面 + gree一步，一个台阶 → 一个位置和阶段 → degree学位', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3287, 'dictionary', '/ˈdɪkʃəneri/', 'dictionary.mp3', 'n.词典，字典', 'i_16_16669_0_6_151111151155-gigapixel-scale.jpg', '20141012_07_35_07_973_v3.png', 'Use this dictionary if there are any words you don\'t know.', '如果有不认识的单词，用这本字典查查。', '6fqfxgd8jemjyl7rh764syywzb5bcbtf.mp3', 'dict说话，断言 + ion行为 + ary表名词 → 措词的书 → dictionary字典', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3288, 'diet', '/ˈdaɪət/', 'diet.mp3', 'n.节食，规定饮食（为健康或减肥等目的）；日常饮食；日常食物；大量；  v.节食', 'adb57a13e9ee03cea8d81b044a7b442f_143688_1639107629.jpg', '20141011_04_23_00_718_v3.png', 'I\'m trying to eat a diet of only fruits and vegetables.', '我在努力节食，只吃水果和蔬菜。', 'cn6pmfurp737mr92wshnwtxexmhdbr3y.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3289, 'dirt', '/dɜːrt/', 'dirt.mp3', 'n.灰尘，污垢', 'i_1_6209_0_3_20150808124830-gigapixel-scale.jpg', 'd_24_6209_0_4_20150808224527.png', 'The vacuum cleaner helps me get rid of the dirt.', '真空吸尘器帮我除去灰尘。', 'crtjewwqm3j4g5u5ns3d4ztnhjfpss2y.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3290, 'dismiss', '/dɪsˈmɪs/', 'dismiss.mp3', 'v.开除；不考虑；解散', 'i_16_3955_0_9_151222170322-gigapixel-scale.jpg', '20141009_11_19_30_65_v3.png', 'The boss was angry and dismissed the staff.', '老板很生气，并且开除了那个职员。', '85be195119be1d1d_1266883373990763030_250207.mp3', 'dis离开 + miss送 → 我送你离开，千里之外 → dismiss解雇', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3291, 'dispose of', '/dɪˈspoʊz ɑv/', 'dispose of.mp3', 'phr.处理，安排；解决', 'disposeof_10534_20231106_c7b1af4d.jpg', '', 'You\'d better dispose of these used tissues in the garbage.', '你最好将这些用过的纸扔到垃圾桶里。', '3aeb343719f29dfc506ce1c4b813677e_29538_1574404783.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3292, 'dramatic', '/drəˈmætɪk/', 'dramatic.mp3', 'adj.巨大的，突然的，急剧的；戏剧的，戏剧性的；引人注目的；逼真的，刺激的', 'ba6ca21cd0bb78415889de752e89c2bb_202790_1596782125.jpg', 'd_1_5682_0_2_20150808124221.png', 'The dramatic decline of the stock value was a big blow for him.', '这次股价的暴跌对他来说是一个极大的打击。', '20b2d2bdce32e9a8b86512b7ea4810e0_58885_1596782120.mp3', 'drama戏剧 + tic形容词后缀 → dramatic戏剧的，戏剧性的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3293, 'easily', '/ˈiːzəli/', 'easily.mp3', 'adv.容易地', 'fb9f77fa3bc5017a2ab496b75cdeb8bb_111156_1729221416.jpg', 'd_24_11463_0_4_20150808230551.png', 'My four-year-old son can already solve math problems easily.', '我那四岁的儿子已经可以轻松地解决数学问题了。', '8869f01a717375a5_1266797988081654354_250123.mp3', 'easi=easy容易的 + ly 表副词...地 → 容易地；无疑地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3294, 'eastern', '/ˈiːstərn/', 'eastern.mp3', 'adj.东方的，东部的，朝东的', 'i_1_5036_0_3_20150808123352-gigapixel-scale.jpg', 'd_24_5036_0_4_20150808223839.png', 'I saw the sunrise in the eastern sky.', '我看到太阳从东方升起。', 'sa_1_5036_0_3_20150808123352.aac', 'east东方 + ern形容词后缀 → eastern东方的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3295, 'educate', '/ˈedʒukeɪt/', 'educate.mp3', 'v.教育，培养', '74ca94659c5bc83887f0e163dd8cf9d5_189840_1587459406.jpeg', '20121225_19_51_08_66.png', 'He was educated at the Baicizhan University.', '他在百词斩大学接受了教育。', '11f353e94559f09cf941a98bd9b18c39_40108_1587459404.mp3', 'e出 + duc引导 + ate动词后缀 → educate教育', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3296, 'elect', '/ɪˈlekt/ ', 'elect.mp3', 'v.选举，推选；选择', 'aa852bd50b39ee56bb697a3241baf866_55897_1538665860.jpg', 'd_107_6632_0_2_20150809020609.png', 'We elect our next leader by voting.', '我们通过投票来选举下一任领导。', 'ev45meleyhk329kccr49rnxxcnwqtrpa.mp3', 'e出 + lect选择，收集 → 选出，选举', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3297, 'emerge', '/iˈmɜːrdʒ/', 'emerge.mp3', 'v.出现；兴起；浮现', '4388190782363180cbd4ea889c2cc927_184520_1573700765.jpeg', 'd_1_5684_0_2_20150808124223.png', 'A little rabbit emerged from the hole to look for food.', '一只小兔子从洞口钻出来找吃的。', 'sgblkd7flbkb64ksyqupnvjpvp8f8uew.mp3', 'e出 + merge沉没 → 沉没的东西出现 → emerge浮现', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3298, 'enlarge', '/ɪnˈlɑːrdʒ/', 'enlarge.mp3', 'v.放大，扩展', 'c_i_wm_20121113_17_26_45_180-gigapixel-scale.jpg', 'd_16_8524_0_5_20150808233156.png', 'I need to use a magnifying glass to enlarge the text.', '我需要用放大镜来把文字放大。', 'us_I_need_20231219163411046_5da789eec7ecc8a6b4d5.mp3', 'en使 + large大 → enlarge使扩大', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3299, 'entrance', '/ˈentrəns/', 'entrance.mp3', 'n. 入口，通道', 'a35c59302fc2146c44082d0bfb424f1e_107000_1595474688.jpeg', 'd_24_6127_0_4_20150808224439.png', 'Children are gathering at the entrance of the park.', '孩子们在公园的入口处集合。', 'f4f574b8612c1bc7_1266883483393808936_250207.mp3', 'entr=enter进入 + ance表名词，状态、行为 → entrance入口；进入，入学', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3300, 'equal', '/ˈikwəl/', 'equal.mp3', 'adj.平等的；相等的；  v.比得上；  n.同等的人', '0f193e334c0d9ddd699a832eecb171b2_39942_1565262324.jpg', 'd_24_10949_0_4_20150808230455.png', 'Today', '如今，男女在法律面前是平等的。', '227da28a6c94efa4123eea1998452580_19324_1619318696.mp3', 'equ相等，平均 + al形容词后缀 → 相等的，平等的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3301, 'examination', '/ɪɡˌzæmɪˈneɪʃn/', 'examination.mp3', 'n.考试', 'a4b7703bb97462cf6a6e59aa3e2c6219_167156_1733880961.jpg', 'd_16_17624_0_7_20150809011935.png', 'The students are taking an examination.', '学生们正在参加考试。', 'u559zjal6usrbvvggzvm8z5vmwmmy2e5.mp3', 'examin检查 + ation名词后缀 → examination检查', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3302, 'executive', '/ɪɡˈzekjətɪv/', 'executive.mp3', 'n.经理；执行者；行政人员；  adj.执行的', '1f21d8dd5d9367fe548255c54b49ab86_87168_1565343316.jpg', 'd_1_4993_0_2_20150808123309.png', 'The executives of both companies discussed the issue in depth.', '双方公司的经理深入地讨论了这个问题。', 'sa_1_4993_0_2_20150808123309.aac', 'execut执行 + ive名词后缀 → executive执行者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3303, 'exploit', '/ɪkˈsplɔɪt/', 'exploit.mp3', 'v.剥削，压榨；开发，开拓（读作/ɪkˈsplɔɪt/）；  n.辉煌的功绩（读作/ˈeksplɔɪt）', '3_0_20170709071414_29677_c-manual-scale.jpg', 'd_107_1121_0_2_20150809001610.png', 'The greedy employer exploits his workers for his own profits.', '这个贪婪的老板为了自己的利益剥削工人。', 'a77b061ac339d64b520606d623ffe697_19323_1538468544.mp3', 'ex向外 + ploit卷 → exploit剥削', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3304, 'expression', '/ɪkˈspreʃn/', 'expression.mp3', 'n.表情；表达', 'c3f30442d4f69b520223c73b7c7ac951_129238_1715582897.jpg', 'd_24_7139_0_4_20150808225005.png', 'People in the car were amazed by his sudden cutesy expression.', '车上的人都被他突然卖萌的表情震惊了。', '0bd4137942c01e32_1266883372018457284_250207.mp3', 'ex出来 + press挤压 + ion名词后缀 → expression表达；表情', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3305, 'external', '/ɪkˈstɜːrnl/', 'external.mp3', 'adj.外面的，外部的；外国的', 'b86457e37d366cd3ef8c316839458c33_199924_1533018926.jpeg', 'd_1_1133_0_2_20150808121641.png', 'This medicine is just for external use', '这种药只能外用，因此我们不能往嘴里喷。', '7c9e88675a7089e51b55f804c35d3d6a_29198_1621931707.mp3', 'exter出去 + nal=al……的 → 出去的 → 在外面的  → external外部的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3306, 'extraordinary', '/ɪkˈstrɔːrdəneri/', 'extraordinary.mp3', 'adj.非同寻常的；特别的', '0d1c82b0b65c72629203d846d4ba8c03_102067_1595857359.jpg', 'd_100_12638_0_4_20150809032457.png', 'Her little daughter has extraordinary musical talent.', '她的小女儿在音乐方面天赋异禀。', 'bb8d11a10653d7fb_1266883374599723570_250207.mp3', 'extra超过 + ordinary普通的 → extraordinary特别的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3307, 'face', '/feɪs/', 'face.mp3', 'n.脸，面孔；表面，外面；  v.面对，面临', '815f32fb62bd69749772f8fa35e4bc00_40371_1574838328.jpg', 'd_24_17164_0_4_20150808232223.png', 'The beautiful woman is touching her face.', '这个美丽的女人正在摸自己的脸。', 'yrgh8wzcbkfxgrxaqs8dfppgpuyz9t6j.mp3', 'face=fac表示脸、面 → face脸，表面，外表', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3308, 'faithfully', '/ˈfeɪθfəli/', 'faithfully.mp3', 'adv.忠实地，忠诚地；诚心诚意地', '328f4dcb46f998eafce8823c4a9aeecf_101749_1588090365.jpeg', '', 'This dog faithfully waits for its master to come home every day.', '这只狗每天忠诚地等待他的主人回家。', 'c609afe5b1bc9bcf722bcc7a47f04d69_47590_1588090361.mp3', 'faith忠实 ＋ ful...的 ＋ ly...地 → faithfully忠实地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3309, 'fall', '/fɔːl/', 'fall.mp3', 'v.落下；  n.秋天', '3_0_20170719071125_93513_c-gigapixel-scale.jpg', 'd_99_12659_0_4_20150809022256.png', 'An apple fell from the tree and hit Newton.', '苹果从树上落下并砸中了牛顿。', 'n688xmxpkydqtbvtjpdydw378n7k7lbs.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3310, 'famous', '/ˈfeɪməs/ ', 'famous.mp3', 'adj.著名的', '9ff3ba624a38e7db15fe642565de35f6_77300_1732507079.jpg', 'd_24_16635_0_5_20150808231730.png', 'She is a famous singer and has many fans.', '她是一位著名的歌手，有很多粉丝。', 'vbta5frzftekj5cnm5s94wblj4sqdbs7.mp3', 'fam=fame荣誉 + ous形容词后缀 → famous著名的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3311, 'feed', '/fiːd/', 'feed.mp3', 'v.给（人或动物）食物，喂，饲养', 'i_4_2686_0_2_20150808145407-gigapixel-scale.jpg', 'd_24_2686_0_4_20150808223243.png', 'I used to nurse my baby myself; now I just feed him out of the bottle.', '我过去要亲自给宝宝喂奶，现在只要用瓶子喂他就行了。', 'a13167f5ac93033bde34dc58d1cfcf10_33941_1621924202.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3312, 'for the sake of', '/fɔr ðə seɪk ʌv/', 'for the sake of.mp3', 'phr.为了…的利益', '52f8a225708e3fcd1c507cdc5debf496_199198_1605178049.jpg', '', 'The old couple exercise for the sake of keeping healthy.', '这对老夫妻锻炼是为了保持健康。', 'aaefdd578d851d7dfab34483171a7ff4_15876_1542878334.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3313, 'forecast', '/ˈfɔːrkæst/', 'forecast.mp3', 'n.预报；预言；  v.预报', 'fce7fc9b93ba75e44c6b1e9aebe41875_185925_1604041296.jpg', 'd_16_5442_0_4_20150808225316.png', 'The weather forecast says the weather next week will be terrible.', '天气预报说下周的天气会很糟糕。', '7e5821d8a24c425c_1266798141249772218_250123.mp3', 'fore前面，预先 + cast投射 → 预先投射 → forecast预料，预测', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3314, 'frustrate', '/ˈfrʌstreɪt/', 'frustrate.mp3', 'v.使沮丧', '6f1e26cd69823796b672368cce4ba068_93268_1595230587.jpg', '20130307_15_57_07_138.png', 'A large amount of work frustrates the workers.', '大量的工作使这些员工感到灰心。', '6e095198be60a811671b03b5286a8cca_17443_1648784468.mp3', 'frustr犯错误 + ate做，造成 → frustrate挫败', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3315, 'geography', '/dʒiˈɑːɡrəfi/', 'geography.mp3', 'n.地理（学）', '56010ffcc532246a17b5deaf33ca9f7f_99948_1541832212.jpg', 'd_24_17024_0_4_20150808231932.png', 'Geography can help us know the world better.', '学习地理可以让我们更好地了解世界。', 'v3eq9x289824fqdpasyj88slnnjz833x.mp3', 'geo地球 + graphy写，图 → geography地理，地理学', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3316, 'get into', '/ɡet ˈɪntu/', 'get into.mp3', 'phr.对…有兴趣；陷入，染上（习惯）', 'a9a9f2d8850bd7a9436f25db4d9b9003_100941_1584083638.jpeg', '', 'The little boy got into basketball after a famous player visited his school.', '那个小男孩在一位著名球员参观他的学校后迷上了篮球。', '26d2a916a62cf652_1266883635002890958_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
