INSERT INTO `words` VALUES (3319, 'gratitude', '/ˈɡrætɪtuːd/', 'gratitude.mp3', 'n.感激，感谢', '48c181ad5775f06c977b122987bca50d_121411_1738898564.jpg', 'd_18_4821_0_2_20150808180940.png', 'In the speech', '她在演讲中表达了对母亲的无限感激。', 'us_In_the_20240407101958020_b4eda24fe776983f7fd8.mp3', 'grat(e)感谢 + itude名词后缀 → gratitude感激，感恩', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3320, 'guide', '/ɡaɪd/', 'guide.mp3', 'v.给……领路；给……做导游，带领；  n.导游', 'i_16_9209_0_5_151031104628-gigapixel-scale.jpg', 'd_24_9209_0_4_20150808230124.png', 'I am blind', '虽然我失明了，但是我的狗可以领着我回家。', 'sa_16_9209_0_5_151201172008.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3321, 'handle', '/ˈhændl/', 'handle.mp3', 'n.柄，把手；  v.处理，解决', '56953ab39146fc085ce150d4eb0eff43_105146_1538761814.jpg', 'd_16_5698_0_2_20150808225716.png', 'Turn the handle and the door will open.', '转动把手，门就会开。', '9d1f75691c09833ae1dec4f9a22b178e_12741_1626492286.mp3', 'hand手 + le表示做某种动作时所使用的东西 → handle柄，把手', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3322, 'hate', '/heɪt/', 'hate.mp3', 'v.恨，憎恨；不喜欢，讨厌；  n.恨，憎恶', '87a4796fdd5ab46a9af38545089136bf_63396_1736831238.jpg', '0e4616fb4ceca5b9665de9379aeaeb9a_15043_1539341424.png', 'They hate each other.', '他们憎恨彼此。', '0dadddbe67d4800d_1266763399866788822_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3323, 'helpful', '/ˈhelpfl/', 'helpful.mp3', 'adj.肯帮忙的，给予帮助的', '3923a037cccbe5690318119c563b7df3_157449_1565149468.jpg', 'd_24_18135_0_4_20150808234855.png', 'This helpful boy is helping the old lady cross the road.', '这个乐于助人的男孩正在帮助老奶奶过马路。', 'b475940c1f9ca03b_1266883373042064112_250207.mp3', 'help帮助 + ful形容词后缀 → helpful肯帮忙的，给予帮助的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3324, 'hinder from', '/ˈhɪndɚ frʌm/', 'hinder from.mp3', 'phr.妨碍', '412c39fc02f2319b2cb841049a993733.jpg', '', 'The landslide hindered the relief supplies from being delivered to the disaster area.', '山体滑坡阻碍了救援物资运送到灾区。', '28f88561df9c553307d20255062f01eb.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
