INSERT INTO `words` VALUES (3326, 'homeless', '/ˈhoʊmləs/', 'homeless.mp3', 'adj.无家的；  n.无家可归者', '547beaa98ee4e926bb4a4abe6b44d9d8_101790_1596163535.jpeg', 'd_39_12998_0_5_20150809015701.png', 'The homeless dog wishes he had a family.', '这只流浪狗希望有个家。', 'cb9d71637bcb6e3d614f650157c66e60_46624_1596166102.mp3', 'home家 ＋ less表形容词，无…的 → homeless无家可归的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
