INSERT INTO `words` VALUES (3329, 'in no case', '/ɪn noʊ keɪs/', 'in no case.mp3', 'phr.决不', 'e6de239199cb46fbd35be5742b791b41.jpeg', '', 'He would surrender to his enemy in no case.', '他绝不会向敌人屈服。', '310a87e41c0ab0097d2c38077b44a456.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
