INSERT INTO `words` VALUES (3350, 'museum', '/mjuˈziəm/  ', 'museum.mp3', 'n.博物馆，展览馆', 'a6bd5ef2be83e259c62fe477a598f370_56519_1750932363.jpg', 'd_24_15943_0_4_20150808230925.png', 'There are many pieces of art in the museum.', '博物馆里有很多艺术作品。', 'qy7mejscjxgplsne5anyxsr56bd7fmbd.mp3', 'muse文艺、音乐 + um名词后缀，表场所 → museum博物馆', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3351, 'mutual', '/ˈmjuːtʃuəl/', 'mutual.mp3', 'adj.互相的；共同的', '8d5a766f3d858f56912254d1190c098f_69907_1669634198.jpg', '', 'Good communication can build a bridge of mutual understanding.', '良好的沟通能架起一座相互理解的桥梁。', '3_0_20170930071455_9752_c.aac', 'mut变 + ual形容词后缀 → 你变我也变 → mutual相互的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3352, 'nail', '/neɪl/', 'nail.mp3', 'n.指甲，爪；  v.将……钉牢，钉住', 'e195b4756085aec5d998f14007be6536_107975_1729822965.jpg', 'd_24_8936_0_4_20150808225931.png', 'I got diverse patterns on my nails from the nail salon.', '我去美甲沙龙给指甲做了不同的图案。', 'vqys8wgh53be6kgyg4q7ughd8jmftajq.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3353, 'nearby', '/ˌnɪrˈbaɪ/', 'nearby.mp3', 'adj.附近的，邻近的；  adv.在附近', 'c0516655b5eb24ba5ec2af585706f1d3_63648_1565680824.jpg', 'd_24_5148_0_4_20150808223947.png', 'My phone can exchange information with any smart phone that is nearby.', '我的手机可以跟附近任何智能手机交换信息。', '3_66_20170711140447_12075_c.aac', 'near附近 + by旁边 → nearby附近的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3354, 'negative', '/ˈneɡətɪv/', 'negative.mp3', 'adj.消极的，负面的；否定的；  n.否定', 'd05997d84fa40666e7bce890e658500f_142260_1538659441.jpg', 'd_107_9901_0_2_20150809024810.png', 'He received too many negative comments from others.', '他收到了太多负面的评价。', 'c7f94e179cc275d6_1266883488606432162_250207.mp3', 'negat否认 + ive形容词后缀 → 否认的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3355, 'neighborhood', '/ˈneɪbərhʊd/', 'neighborhood.mp3', 'n.社区，街区，邻近地区', 'f3750ab5b2cdca6a60bc1fc49b6f5f8f_101642_1595584275.jpg', 'd_24_9922_0_4_20150808230337.png', 'The houses in this neighborhood all look the same.', '这个社区的房子都一模一样。', 'xpzwn5jbw6ghpjauja8ajrg4jxns4q96.mp3', 'neighbor邻居 + hood名词后缀 → neighborhood与某处邻近的地区', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3356, 'nor', '/nɔːr/', 'nor.mp3', 'conj.也不', 'e9b402923167b0f2d4855a8a23dc46a3_132150_1732261455.jpg', 'd_24_19598_0_3_20150809002310.png', 'Neither my sister nor I like eggs.', '我和我的妹妹都不喜欢吃鸡蛋。', 'us_Neither_my_20241122154351285_a003f9557a5551d752a4.mp3', 'n不 + or或者 → nor也不', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3357, 'object', ' /ˈɑːbdʒekt/', 'object.mp3', 'n.物体；宾语；目标；  v.提出……作为反对的理由', '1425953215179-gigapixel-scale.jpg', 'd_24_5024_0_4_20150808223824.png', 'UFO is the short form of Unidentified Flying Object.', 'UFO是“不明飞行物体”的简写。', 'sa_5_5024_0_6_20150808143153.aac', 'ob朝向 + ject扔 → object目标，物体', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3358, 'operate', '/ˈɑːpəreɪt/', 'operate.mp3', 'v.做手术；运转', '15bf9894ab90ea32910f37f0421d7e1d_158033_1533106942.jpeg', 'd_20_5117_0_2_20150808164437.png', 'The doctors are operating on the patient.', '医生们正在给病人做手术。', 'qx396r2vgfdt96369kf5mwu4pe5tlgku.mp3', 'oper工作 + ate表示做、造成 → 行动起来 → operate操作；施行手术', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3359, 'opposite', '/ˈɑːpəzɪt/', 'opposite.mp3', 'adj.相反的；对立的；对面的；  adv.对立地；反面地；  n.对立物；反面，对立面', '49ccb81f899c4aea62f7b0aa3c9ad407_126141_1739768809.jpg', 'd_24_5589_0_3_20150808224211.png', 'She is running in the opposite direction of all the others.', '她正朝着与其他所有人相反的方向跑。', 'wnb3dmb35ru4h7hks73zfxrgs2pey6qv.mp3', 'oppos反对 + ite形容词后缀 → opposite反对的，反的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3360, 'originate from', '/əˈrɪdʒɪneɪt frʌm/', 'originate from.mp3', 'phr.源于', '4417e12ba97da01340102e42631a8c30.jpg', '', 'The movie originates from a popular children\'s book.', '这部电影源于一本很受欢迎的儿童读物。', '579a50a3c0acd3c4d802923525cf65fc.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3361, 'packet', '/ˈpækɪt/', 'packet.mp3', 'n.小袋，小包装', '03ddaf6c087d580d275c12e922911b14_85774_1595499905.jpg', 'd_105_10104_0_2_20150809061627.png', 'This packet of potato chips has been opened.', '这袋薯片已经被打开了。', '768c51319ac7cb09e4860cfb052e48cc_16973_1595501225.mp3', 'pack包捆 + et小东西→ packet小包', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3362, 'painting', '/ˈpeɪntɪŋ/', 'painting.mp3', 'n.画作，油画', '0e0c1a59df67a9569a64bcad0c21d4ef_100599_1595472422.jpeg', '20141013_20_55_00_137_v3.png', 'There is a famous painting on the wall.  ', '墙上有一幅名画。', 'us_There_is_20240523142932029_836a881f0f10d6f06a34.mp3', 'paint画 + ing表名词 → painting画作，绘画', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3363, 'particularly', '/pərˈtɪkjələrli/', 'particularly.mp3', 'adv.特别地，尤其', '3_0_20170930071459_27709_c-gigapixel-scale.jpg', 'd_1_4902_0_2_20150808123127.png', 'This guy particularly likes eating meat.', '这个男人尤其爱吃肉。', '3_0_20170930071459_15169_c.aac', 'particular特别的 + ly...地 → 有自己的部分地 → particularly特别地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3364, 'patient', '/ˈpeɪʃnt/', 'patient.mp3', 'n.病人，接受治疗者；  adj.有耐心的', '65e8b425e62515a09f6efbaf6baf402c_162516_1594115557.jpg', 'd_24_4911_0_4_20150808223636.png', 'As a nurse', '作为一名护士，我喜欢近距离接触我的病人。', '85d1da407d63f4b2_1266763402980579882_250117.mp3', 'pati忍受 + ent表名词，...的人 → 正在受苦的人 → patient病人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3365, 'peace', '/piːs/', 'peace.mp3', 'n.和平；平静', 'i_24_16612_0_8_151222151716-gigapixel-scale.jpg', 'd_95_13659_0_4_20150809012816.png', 'This kind of bird always stands for peace.', '这种鸟一直代表着和平。', 'sa_24_16612_0_8_151224140323.aac', 'pea固定 + ce名词后缀 → peace和平，无战争', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3366, 'pity', '/ˈpɪti/', 'pity.mp3', 'n.憾事；  v.（觉得）可怜，惋惜', '3_0_20160520173619_88884_c-gigapixel-scale.jpg', 'd_24_18806_0_4_20150808235819.png', 'What a pity! My ice cream dropped before I ate it.', '真遗憾！我还没来得及吃，我的冰激凌就掉地上了。', '2a078a4c01f6fe67_1266883325076745150_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3367, 'possibility', '/ˌpɑːsəˈbɪləti/', 'possibility.mp3', 'n.可能性', '3_0_20160718113442_50468_c-gigapixel-scale.jpg', 'd_24_5008_0_3_20150808223820.png', 'The possibility that I grab the black ball is fifty percent.', '我抓到黑球的可能性是50%。', 'dc810d19d8fe64e87493ba756e474897_20891_1619170017.mp3', 'poss可能 + ibility表名词 → possibility可能；可能的事', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3368, 'postcard', '/ˈpoʊstkɑːrd/', 'postcard.mp3', 'n.明信片', '33d7a8f70033a9b8832e1eef01851415_72524_1740470650.jpg', 'd_24_16426_0_4_20150808231200.png', 'My sister always sends me a postcard from whatever new country she visits.', '我姐姐每新到一个国家都会给我寄明信片。', '75wfr4qel8paz6pfqe6bprae8kuj3e2e.mp3', 'post邮件，邮政 + card卡片 → 邮寄的卡片 → postcard明信片', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3369, 'potato', '/pəˈteɪtoʊ/', 'potato.mp3', 'n.马铃薯，土豆', 'i_16_17108_0_2_20150809004212-gigapixel-scale.jpg', '20121225_18_21_45_93.png', 'Let\'s cut these potatoes and fry them into chips.', '我们把这些土豆切了然后炸薯片吧。', '78a64e7490938a71_1266763401585252868_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3370, 'powerful', '/ˈpaʊərfl/', 'powerful.mp3', 'adj.强有力的，强大的；有权势的，有影响力的', 'i_1_5533_0_3_20150808123931-gigapixel-scale.jpg', '20130301_12_50_13_505.png', 'He lifts us up easily with his powerful arms.', '他用强健的手臂轻松地把我们举起来了。', '1804f59967e22d78_1266798144196226008_250123.mp3', 'power力量 + ful表形容词，“有…的” → powerful有力的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3371, 'practical', '/ˈpræktɪkl/', 'practical.mp3', 'adj.实用的，可行的；实际的，实践的', '2dfb468c79ca7272c55dc67f0c4e3b18_186260_1583458673.jpeg', 'd_24_10980_0_4_20150808230522.png', 'Sneakers are more practical than boots for runners.', '对于跑步者来说，运动鞋比靴子更实用。', '621d8195cd150321_1266883628445313892_250207.mp3', 'pract实践 + ical…的 → 实践的 → practical实践的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3372, 'prescribe', '/prɪˈskraɪb/', 'prescribe.mp3', 'v.给……开药；命令，指示', '9b9b26fbbb01e2371d0273552ac48c22_99889_1619334399.jpg', 'd_107_4153_0_2_20150809004614.png', 'The doctor prescribed me some medicine for my cold.', '医生针对我的感冒给我开了一些药。', 'sa_4153_1_0_2_150707163156.mp3', 'pre预先 + scribe写 → 预先写好药量 → prescribe开药方；命令', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3373, 'presence', '/ˈprezns/', 'presence.mp3', 'n.出席，到场', '5e8a20ccd51335820279a20b7137cfed_182833_1604978603.jpg', 'd_24_4984_0_4_20150808223755.png', 'Every morning the teacher checks the presence of students in class.', '老师每天早上都在课堂上检查学生的出勤情况。', 'us_Every_morning_20241009155955400_e48e9d4dc14fa0f8634a.mp3', 'pres前 + ence名词后缀 → presence出席，到场', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3374, 'prior', '/ˈpraɪər/', 'prior.mp3', 'adj.优先的；事先的', '3_45_20170112120047_58051_c-gigapixel-scale.jpg', 'd_107_4770_0_2_20150809010636.png', 'At the crossroads', '在十字路口，校车有优先通行权。', '042a3c4db12b70e0d97c82857b763a93_19323_1539157265.mp3', 'pr=pri先，前 + ior表形容词  → 较先的  → prior优先的；事先的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3375, 'procedure', '/prəˈsiːdʒər/', 'procedure.mp3', 'n.步骤；程序；手续', '3_66_20170703172419_75492_c-gigapixel-scale.jpg', 'd_107_5584_0_2_20150809013057.png', 'There\'re three steps in the procedure of hot-dog production.', '热狗的生产过程包括三个步骤。', '3_66_20170703172418_21976_c.aac', 'pro在前 + ced行走 + ure名词后缀 → 在前面走完的 → procedure程序；手续', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3376, 'proper', '/ˈprɑːpər/', 'proper.mp3', 'adj.得体的；适合的，适用的；真正的；独特的；  adv.完全地', '3_0_20170930071712_59764_c-gigapixel-scale.jpg', '20121227_13_56_49_8.png', 'You should wear something proper when having an interview.', '面试时，你应当穿着得体。', '3_0_20170930071712_33599_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3377, 'proud of', '/praʊd əv/', 'proud of.mp3', 'phr.以...为满，以...而骄傲', '8511da7467b253dd5eefdcc2b9a60c8a.jpeg', '', 'Seeing his daughter with her prize', '看到女儿获奖，他为其感到骄傲。', 'b2d29f6497d357f4262be0ab6a5e2dd4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3378, 'pursue', '/pərˈsuː/', 'pursue.mp3', 'v.追赶；进行，从事', 'bd54b7db794c170d4c03b68baf7426f0_197012_1585280572.jpeg', '20140814_03_53_30_910_v3.png', 'The police were pursuing the two thieves who had stolen a woman\'s purse.', '警察正在追赶那两个小偷，他们偷了一个女人的钱包。', '9570f003e3ee6b3b061bea483f11f2cd_48848_1596768646.mp3', 'pur=pro向前 + sue跟随 → pursue追求', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3379, 'random', '/ˈrændəm/', 'random.mp3', 'adj.随机的；任意的；  n.随意，胡乱', '3fc56397f3503d6f2ccae82745be618a_179540_1596253669.jpg', 'd_107_4511_0_2_20150809005912.png', 'It\'s just a random series of numbers.', '这就是一系列随机的数字。', 'sa_16_4511_0_2_20150808224308.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3380, 'ratio of sth. to sth.', '/ˈreɪʃioʊ əv ˈsʌmθɪŋ tuː ˈsʌmθɪŋ/', 'ratio of sth. to sth..mp3', 'phr.……和……的比例', 'c52b9295529ac54c7cdfa37c3965bbc0.jpg', '', 'The ratio of boys to girls is 3 to 2.', '男生和女生的比例是3比2。', '989ac118e7b4ad9f90cadfcb7119a68e_46496_1593584564.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3381, 'react against', '/riˈækt əˈɡeɪnst/', 'react against.mp3', 'phr.反抗(反对)', 'd6d5b342d49099c868108b52762d233f.jpeg', '', 'They reacted violently against the king\'s unreasonable demand.', '他们猛烈地反抗国王的无理要求。', '79b6438fdc8f0fe40468c46123cc5589.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3382, 'readily', '/ˈredɪli/', 'readily.mp3', 'adv.欣然地；容易地', '96e8345d745e09aa69149a19a6481323_146258_1728357052.jpg', 'd_107_8201_0_2_20150809022904.png', 'The girl readily accepted his invitation to go to the live music show.', '女孩欣然接受了他提出的去看现场音乐表演的邀请。', '3225fd4511fe47542fb1d6d479c5780a_34661_1552543225.mp3', 'readi=ready准备好的，情愿的 + ly……地 → readily乐意地，欣然地；容易地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3383, 'recognition', '/ˌrekəɡˈnɪʃn/', 'recognition.mp3', 'n.承认，认可', 'e173a524a543a98dd128109249d2b53e_82864_1565342696.jpg', '', 'I received this medal in recognition of my sports skills.', '这枚奖牌是对我运动技能的认可。', '3_41_20170324172005_47526_c.aac', 're一再，重新 + cogn知道 + ition名词后缀 → 认出，承认，识别', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3384, 'recover', '/rɪˈkʌvər/', 'recover.mp3', 'v.痊愈，恢复健康；恢复；收回；换回；重新获得；重新找到', 'i_1_4844_0_3_20150808123103-gigapixel-scale.jpg', 'd_11_4844_0_3_20150808154507.png', 'He has recovered well from his foot injury.', '他的脚伤已经痊愈了。', 'h9nlysjdrm225nn47wfwkrl3uvm3l4fc.mp3', 're重新 + cover盖住 → recover重新获得', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3385, 'recycle', '/ˌriːˈsaɪkl/', 'recycle.mp3', 'v.回收利用', '12e62a4667e62f712226fac665f7ae5c_161189_1557973172.jpeg', 'd_24_6044_0_4_20150808224430.png', 'We should recycle trash by putting it into different bins.', '我们应当通过把垃圾扔进分类垃圾桶中来将其回收再利用。', 'b7be01dadc2d3f36_1266883114016877486_250207.mp3', 're一再，重新 + cycle圆，环 → recycle再循环；回收', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3386, 'refer', '/rɪˈfɝːr/', 'refer.mp3', 'v.参考；把……描述为', '8e2fdcdbe00b0125f136cad39a84cc45_59010_1559024150.jpg', 'd_107_7129_0_2_20150809021503.png', 'When cooking a new recipe', '在烹饪新菜时，我总要查阅烹饪书。', 'sa_1_7129_0_2_20150808125810.aac', 're再次 + fer带来，拿来 → 再次带来 → refer提到；指点', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3387, 'regard', '/rɪˈɡɑːrd/', 'regard.mp3', 'v.把……视为；  n.关注；尊敬；问候', 'c517fec91bd1636492ea590809de6754_88227_1699858409.jpg', 'd_24_5007_0_4_20150808223819.png', 'She was regarded as the most intelligent student in her class.', '她被视作是班上最聪明的学生。', 'us_She_was_20231018124006908_82fefe07ac51e893644e.mp3', 're表强调 + gard看，注意 → regard关注', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3388, 'religious', '/rɪˈlɪdʒəs/', 'religious.mp3', 'adj.虔诚的；宗教的', '63b2de6602beb69e7817224331d7afdf_175911_1538714120.jpg', '50d7e20b1ad7c96e94df16aec7fd1258_48906_1551253591.png', 'He is a religious believer; he goes to church every week.', '他是一名虔诚的教徒，每周都会去教堂做礼拜。', 'db6d25b429e65334465f2d5993f5fc62_19011_1538714138.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3389, 'remote', '/rɪˈmoʊt/ ', 'remote.mp3', 'n.遥控器；  adj.关系远的', 'i_1_7985_0_3_20150808130244-gigapixel-scale.jpg', 'd_24_7985_0_3_20150808225319.png', 'You need a remote to turn on the air conditioner.', '你需要遥控器才能打开空调。', 'gtfcvzsw37skrx5glq4b4tn3cxzp6bnm.mp3', 're远离+ mot移动 → 逐渐向远处移动 → remote偏远的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3390, 'rent', '/rent/', 'rent.mp3', 'n.租金；  v.租', 'i_37_5725_0_3_20150809011227-gigapixel-scale.jpg', 'd_24_5725_0_3_20150808224318.png', 'I have to pay rent on my house every month.', '我得每月支付我的房租。', '3450cc33bd5df541_1266883374742809394_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3391, 'require', '/rɪˈkwaɪər/', 'require.mp3', 'v.要求，规定', '0e050c153b096fdcbb7bb0b43286ab05_204021_1605153160.jpg', 'd_24_10159_0_4_20150808230351.png', 'The worker is required by law to wear a helmet to work.', '法律规定工人佩戴安全头盔进行工作。', '1592083b082b1cccb6c62210d6e006ae_46064_1595924009.mp3', 're再 + quire寻求，询问 → 再寻求 → require请求', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3392, 'responsible for', '/rɪˈspɑːnsəbl fɔːr/', 'responsible for.mp3', 'phr.对……负责', 'ec01c3773d330de7ef91774b0c722f8b.jpeg', '', 'I am responsible for the safety of this plane.', '我对这架飞机的安全负责。', 'bbc3070f4aa4c1c8e76c8db020a82a3f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3393, 'restrain', '/rɪˈstreɪn/', 'restrain.mp3', 'v.抑制（愤怒等），控制', '10b2e3aba570e633655aa1c125831295_140486_1557973097.jpeg', 'd_1_6005_0_2_20150808124643.png', 'I must restrain my anger because he is the boss.', '我必须抑制我的愤怒，因为他是老板。', '526fc42b6c307ce0dd01bd4e64a7b0ac_18069_1557973093.mp3', 're回 + strain拉紧，压 → restrain抑制，限制', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3394, 'rid', '/rɪd/', 'rid.mp3', 'v.使去掉；使摆脱', '3_0_20160520172919_31749_c-gigapixel-scale.jpg', 'd_16_5179_0_2_20150808225113.png', 'The stain can be easily rid of.', '这个污渍很容易去除。', '84cf638eb059a471_1266883320267168330_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3395, 'rob of', '/rɑːb əv/', 'rob of.mp3', 'phr.抢劫', '228e43cec67be8343fc72df955758ac1.jpeg', '', 'He was robbed of his wallet on the way back from the bank. ', '他在从银行回来的路上钱包被抢了。', 'd64a75d2aaca9de607b9fd6699e847fd_36320_1599550018.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3396, 'route', '/ruːt/', 'route.mp3', 'n.路线；途径；固定路线', '7b3196237bcf6ec5f1100cb336e0f73c_162034_1549955181.jpeg', '20130301_12_45_21_95.png', 'This blue line is the quickest route to get there.', '这条蓝色的线是到那儿最快的路线。', '6d97c38c24123f0b_1266763558614358606_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3397, 'run over', '/rʌn ˈoʊvər/', 'run over.mp3', 'phr.匆匆浏览', '3eb35cce82e14791435d9db6c781a09b.jpeg', '', 'He is running over his notes before the exam.', '他正在考试前匆匆浏览笔记。', '66e57fefee2a82062623521caa35b18a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3398, 'sale', '/seɪl/', 'sale.mp3', 'n.廉价出售', 'a3eded5ba2ab33427e7eef5fe8d14c08_91776_1590138413.jpg', 'd_24_18007_0_3_20150808234134.png', 'All the clothes are on sale.', '所有衣服都在打折。', 'cdp894a4qdz37ygdvu2kvst68u95tzvj.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3399, 'scenery', '/ˈsiːnəri/', 'scenery.mp3', 'n.风景', '8181dd00958d3eec84c48aec82bbf96d_152004_1557977583.jpeg', 'd_24_6410_0_4_20150808224626.png', 'The woman sat on the swing and admired the beautiful scenery.', '那个女人坐在秋千上，欣赏美丽的景色。', 'b3915edeadeac97596fa8188ed93e0da_43885_1557977579.mp3', 'scen场景 + ery表场所，地点 → scenery风景，舞台布景', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3400, 'schedule', '/ˈskedʒuːl/', 'schedule.mp3', 'n.时间表，计划表；  v.预订，安排', '094d84965e8b96eeedf9b4f0a5c2ef7a_156315_1619323080.jpg', '20141011_04_38_58_510_v3.png', 'According to my schedule', '根据我的日程表，星期一下午我会去购物。', '3b6b97732cda19ccbf72da8c1b2bfe05_42574_1570783854.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3401, 'scientific', '/ˌsaɪənˈtɪfɪk/', 'scientific.mp3', 'adj.科学的', 'daf2b338511fc777ffc5830be528ba4c_55685_1565684353.jpg', 'd_105_7909_0_2_20150809060545.png', 'Be very careful when doing scientific experiments.', '做科学实验时一定要小心。', 'sa_1_7909_0_2_20150808130128.aac', 'sci知道 + ent……的 + ific表形容词 → 知道的很多的 → 科学的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3402, 'seal', '/siːl/', 'seal.mp3', 'v.封（信封）；  n.印章', 'f167dc0fa72b0f4a944b4800a505528f_201244_1573802708.jpeg', '20121225_19_03_52_990.png', 'He is sealing the envelope before posting the letter.', '他正在封信封，然后把信寄出去。', '5277123ccfa0f20acc1b067773dbdadf_37382_1573802705.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3403, 'search', '/sɜ:rtʃ/', 'search.mp3', 'v.搜索；  n.探求', '3948664d0844dff66e78202dc4d7425f_190095_1564627371.jpeg', 'd_24_5569_0_4_20150808224150.png', 'The police is searching for the thief.', '警察正在搜寻窃贼。', '5dvbr422mzagr9mu6wsm73lxbfhue38a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3404, 'senate', '/ˈsenət/', 'senate.mp3', 'n.参议院，上院', 'f6555d320fba1a511da0294ab8707cf5_169495_1525760465.jpeg', 'd_103_8719_0_3_20150809032355.png', 'Several politicians are talking in front of the United States Senate.', '几个政治家在美国参议院前面交谈。', 'f96dcb9ad4a71954466fad1319423229_37919_1525760451.mp3', 'sen老 + ate名词后缀  → 参议院，上议院，古罗马的元老院议员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3405, 'senior', '/ˈsiːniər/', 'senior.mp3', 'adj.资格老的，地位较高的；  n.（大学或高中）毕业生', '5a96a6e641cf8b5ca9c907739003d2d4_92091_1575269622.jpeg', 'd_16_4990_0_2_20150808224744.png', 'He is saluting the senior officer.', '他正在向长官敬礼。', '3d70c663ea770ea6b3869d2003957630_28976_1575269626.mp3', 'sen年老 + ior表示人 → 上年纪的人 → senior长辈', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3406, 'serve', '/sɜːrv/', 'serve.mp3', 'v.服务；招待；供应；服役', '2e0c1f45fd1dbeb7b88629e2ef5d34fc_91302_1710210594.jpeg', 'd_54_5568_0_3_20150808235334.png', ' Wearing a smile', '这个男人面带微笑，为我们端上一盘大饼。', 'us__Wearing_20250829102852909_badb7ed479adefe70b1b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3407, 'set aside', '/sɛt əˈsaɪd/', 'set aside.mp3', 'phr.省出（时间、金钱），放置一边', 'i_904_-904_0_1_160201152608.jpg', '', 'He sets aside money every month.', '他每个月都会省出一笔钱。', 'sa_904_-904_0_1_160203152612.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3408, 'set in', '/ˈsɛt ˈɪn/', 'set in.mp3', 'phr.生效；设置（戏剧、小说等的）背景', 'bdee972e3b2700d64daba68365b00ecd_187478_1588927953.jpeg', '', 'As the medicine set in', '药力生效了，她慢慢就睡着了。', 'a8e8051e41b6f575617a1edd1f79eb3b_47484_1588927951.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3409, 'sheet', '/ʃiːt/', 'sheet.mp3', 'n.被单；纸张', 'i_1_5666_0_5_20150808124204-gigapixel-scale.jpg', '20140929_02_52_31_994_v3.png', 'I like the white sheet since it looks clean.', '我喜欢这个白床单，因为它看起来很干净。', '0e6460639060af8a_1266883381037280116_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3410, 'similar to', '/ˈsɪmələr tuː/', 'similar to.mp3', 'phr.跟...类似的', 'ed3fae1ee49ff8e2b51304e0a586ec4f.jpeg', '', 'He bought some new shoes which are very similar to a pair he had before.', '他买的新鞋和他以前的那双很相似。', '34a9f9077261e353805e8fe4e8714dea.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3411, 'sincere', '/sɪnˈsɪr/', 'sincere.mp3', 'adj.真诚的，诚恳的', '2ca01b55b90ee59a74f4cdc98b3c3c05_65550_1700619999.jpg', 'd_1_2361_0_2_20150808121835.png', 'She bowed to show her sincere thanks to her classmate.', '她鞠躬表示她对同学的诚挚的谢意。', 'us_She_bowed_20231122102741392_582c9e5cda247e39af25.mp3', 'sin同样的 + cere成长 -> 一同成长，关系密切 -> 真诚的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3412, 'smoke', '/smoʊk/', 'smoke.mp3', 'n.烟，烟尘；  v.抽（烟）', 'i_16_18126_0_4_151119142500-gigapixel-scale.jpg', 'd_24_18126_0_4_20150808234815.png', 'Black smoke is rising from the burning houses.', '黑色浓烟正从着火的房子冒出来。', 'sa_16_18126_0_4_160326175713.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3413, 'specialist', '/ˈspeʃəlɪst/', 'specialist.mp3', 'n.专科医生；专家；  adj.专家的；专业的', 'e54f8a0d547dfd984dd239bf471bb030_91563_1538661378.jpg', 'd_107_5108_0_2_20150809011543.png', 'They are the specialists in our hospital.', '他们是我们医院的专家。', '378892c4baf64fe17e59aa696539a089_11487_1538661394.mp3', 'special特别的 + ist表示人 → 特殊的人，有特别专长的人 → specialist专家', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3414, 'spirit', '/ˈspɪrɪt/', 'spirit.mp3', 'n.精神，心灵', '9d4a884bb55f70bdcd39586f476a9cc5_59446_1569642130.jpg', 'd_24_15458_0_3_20150808230700.png', 'The dove with olive branch symbol captures the spirit of peace and friendship.', '鸽子衔橄榄枝的标志象征和平友爱的精神。', 'e9256979625b66c0ef29a2c30ede5125_21517_1544067243.mp3', 'spir呼吸 + it名词 → spirit精神', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3415, 'stand', '/stænd/', 'stand.mp3', 'v.忍受；起立；  n.讲台', 'c322cdd426d5ddb5aa6733b1fd30e997_99719_1583142194.jpeg', 'd_24_19556_0_4_20150809001947.png', 'He often wondered how he could stand living below such a noisy person.', '他常常在想，他怎么能够忍受住在这么吵闹的人下面。', 'b75bb5d4dde7d954_1266883329629510168_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3416, 'steep', '/stiːp/', 'steep.mp3', 'adj.陡峭的；过高的；  v.浸，泡', '3_0_20170930071553_85600_c-gigapixel-scale.jpg', 'd_24_5957_0_4_20150808224406.png', 'Don\'t stand too close to the edge of the steep cliff!', '别站得离陡峭的悬崖太近了！', 'caf7c713caec99a0_1266883377993636568_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3417, 'stimulate', '/ˈstɪmjuleɪt/', 'stimulate.mp3', 'v.激发，促进', '3_66_20170711113924_23031_c-manual-scale.jpg', 'e28ba57913c5d97bda2508cf709a830e_39111_1551843565.png', 'The globe can be used to stimulate discussion among the kids.', '地球仪可用来鼓励孩子们相互讨论。', '3_66_20170711145355_56582_c.aac', 'stimul刺激 + ate使 → stimulate刺激', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
