INSERT INTO `words` VALUES (3421, 'supportive', '/səˈpɔːrtɪv/', 'supportive.mp3', 'adj.支持的', '5_48_94_20161211225109_27382_c.jpg', '', 'My family was supportive of my dream to be a singer.', '对于我想要成为歌唱家的梦想，我的家人持肯定态度。', 'ct4rt6j7bwvybjvsljclxk2e3ldyxeq6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3422, 'tail', '/teɪl/', 'tail.mp3', 'n.尾巴；  v.紧跟，尾随', 'c0b6d8138fb2d5d5caf1e531aae75d14_78756_1565343353.jpg', 'd_24_5785_0_3_20150808224342.png', 'The horse\'s long tail lifted up into the air as it ran.', '马的长尾巴随着其奔跑的步伐甩向空中。', '7zv5zu3zvwa7wjxuypm4bu3wcpv847pn.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
