INSERT INTO `words` VALUES (3424, 'talent', '/ˈtælənt/  ', 'talent.mp3', 'n.天赋，才能', '1771015830047aceb3bbb5df54b17611_189568_1565693193.jpeg', 'd_16_8027_0_4_20150808232430.png', 'This baby showed great talent as he was playing the piano.', '这个宝宝弹钢琴的时候展现出超强的天赋。', '590e703f19d1510a9b98eea6ee388d2d_39410_1565693191.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3425, 'terminal', '/ˈtɜːrmɪnl/', 'terminal.mp3', 'n.航站楼；  adj.末端的', 'i_1_4510_0_3_20150808122839-gigapixel-scale.jpg', 'd_16_4510_0_2_20150808224307.png', 'This terminal was built in the 1960s.', '这个航空站于20世纪60年代建成。', '9b4fb5471c9cd6aa115f4095f1ddea2d_16816_1621236983.mp3', 'termin终端 + al形容词词尾 → terminal终端的；末端的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
