INSERT INTO `words` VALUES (3427, 'tobacco', '/təˈbækoʊ/', 'tobacco.mp3', 'n.烟草，烟叶', '08bc98336cb8487f52c6280c9ac9dae4_198884_1561952982.jpg', 'd_24_6663_0_3_20150808224718.png', 'Tobacco is made up of dried leaves.', '烟草是由干叶片制成的。', '15350f4ad9c170fa4e22aa2b54e411e5_15406_1625727558.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
