INSERT INTO `words` VALUES (3429, 'trace', '/treɪs/', 'trace.mp3', 'v.追踪；  n.痕迹', 'a7b48cb623db1900676927870b0395eb_77401_1585376678.jpeg', 'd_107_10132_0_2_20150809024932.png', 'The police dog traced the scent and located the stolen money.', '这只警犬循着气味找到了被偷走的钱款。', 'ffe70a4a8439e9e5d850b5f2ea105bc9_44724_1586704755.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
