INSERT INTO `words` VALUES (3431, 'try on', '/traɪ ɑːn/', 'try on.mp3', 'phr.试穿，试试看', '42c26b521e2107c619480abab2c84a98_99847_1589816603.jpg', '', 'The two girls are trying on dresses.', '这两个女孩正在试裙子。', '4f535fe13a4cb667186879bd48379e42_13525_1589816626.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3432, 'turn over', '/tɜrn ˈoʊvər/', 'turn over.mp3', 'quant.翻动，犁翻（土地），翻转', '4bd29ec723ac428b009e5c1bec1c60ef_88910_1579339591.jpeg', '', 'The green car turned over during the accident.', '那辆绿色轿车在事故中翻车了。', 'dheed9zr6e6z9t6avavsq56eq3uue6d8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3433, 'under control', '/ˈʌndər kənˈtroʊl/', 'under control.mp3', 'phr.被控制住，在…控制下', '36fa25763e4658028d53454fc7a8c3cd_41316.jpg', '', 'We have the blaze under control. It\'s safe now.', '我们控制住火势了，现在安全了。', '99cdadcfe8b771f0ce3835daf207d312_38383.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3434, 'under the circumstances', '/ˈʌndər ðə ˈsɜːrkəmstænsɪz/', 'under the circumstances.mp3', 'phr.在这种情况下；既然如此', '378062a038e8aa13790f430ffbcd1110.jpeg', '', 'Under the circumstances', '在这种情况下，他上学迟到是可以理解的。', 'dc99c8f9928d4d703ea84f277dd95091.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3435, 'understanding', '/ˌʌndərˈstændɪŋ/', 'understanding.mp3', 'n.（非正式）协议；理解；  adj.体谅的，谅解的', 'i_1_8368_0_4_20150808130627.jpg', '20141012_08_24_26_7_v3.png', 'We finally reached an understanding about how the house would be built.', '我们最终在如何建造房子上达成了一致。', 'sa_1_8368_0_4_20150808130627.aac', 'under下 + stand站立 + ing名词或形容词后缀 → 站在其中才明白 → understanding理解', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3436, 'uneasy', '/ʌnˈiːzi/', 'uneasy.mp3', 'adj.心神不宁', 'f1568f491d3e5a9a797a983eaed3172f_176225_1731403379.jpg', 'd_1_6996_0_2_20150808125721.png', 'Insomnia made the man feel uneasy.', '失眠让这个男人感到不安。', 'd028a429a2216566_1266883538659400426_250207.mp3', 'un不 + eas放松 + y形容词后缀 → uneasy心神不安的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3437, 'video', '/ˈvɪdioʊ/', 'video.mp3', 'n.视频，录像；录像带；  v.制作……的录像', 'deb6bd7dae3921467a4a6c85fdd696d8_86165_1565341961.jpg', 'd_109_18100_0_2_20150809062922.png', 'Her job is to record the show on video.', '她的工作是制作演出的录像。', '6e07ad9054d98043_1266763403805436738_250117.mp3', 'vid=see看 + eo后缀 → video视频，录像', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3438, 'vote', '/voʊt/', 'vote.mp3', 'v.投票，表决；  n.投票', 'f98cf5eb16306f101b27bdd8ec686ecf_30919_1545460837.jpeg', 'd_107_5016_0_2_20150809011316.png', 'Voting is a fair way for selection.', '投票是一种公平的选举方式。', 'a29de94c62ab2194_1266883330076465700_250207.mp3', 'vot发誓 + e → 投票前需要发誓以示诚实 → vote投票', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3439, 'weak', '/wiːk/', 'weak.mp3', 'adj.虚弱的；软弱的', 'afb30dc151833a4a2037b086e6737230_106290_1733385729.jpg', 'd_24_16649_0_3_20150808231756.png', 'He\'s so weak that he can\'t even lift this tiny weight.', '他真的是太虚弱了，竟然连这么轻的重量都举不起来。', '98f4f528fe4a7782_1266763310681643562_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3440, 'wear', '/wer/', 'wear.mp3', 'v.穿，戴', 'i_16_18116_0_4_20150809014457-gigapixel-scale.jpg', '20141015_14_11_05_117_v3.png', 'She loves to wear white coats.', '她爱穿白色的大衣。', '378d4a544608e20d_1266763554541689584_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3441, 'with regard to', '/wɪð rɪˈɡɑrd tu/', 'with regard to.mp3', 'phr.有关，至于', '6bfee3c81da241b4d84a9a27c9ba6ebf.jpeg', '', 'He has a few questions with regard to the dance competition on the poster.', '关于海报上的那个舞蹈比赛，他有几个问题。', '211eb585d8e808226cfd245256621f8a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3442, 'wonder', '/ˈwʌndər/', 'wonder.mp3', 'v.想知道，想弄明白；  n.惊奇，惊异', '6db69cfd896b488ceaeb13559e5173b5_151956_1573717348.jpeg', 'd_24_10984_0_3_20150808230526.png', 'He was wondering what was in the box.', '他想知道箱子里是什么。', 'b456f9c4a1167c6f_1266883115667708636_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3443, 'absence from', '/ˈæbsəns frəm/', 'absence from.mp3', 'phr.缺席于……', 'f224ddade30a8d68c92745bc6bb2b081.jpeg', '', 'He did not know the reason for his deskmate\'s absence from class.', '他不知道他的同桌缺课的原因。', '13968c0df187eb8699426722aa407568_23242_1620807210.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3444, 'account for', '/əˈkaʊnt fɔr/', 'account for.mp3', 'phr.解释，说明', 'b469e873c53fc523a787f8a47bb1b566.jpg', '', 'The awful weather may account for the lack of customers in the restaurant today.', '糟糕的天气或许可以说明今天这家餐馆人少的原因。', 'utmhwgwfdy3gpqsq6jsjk95bt4jqbanl.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3445, 'acquaint oneself with', '/əˈkweint wʌnˈsɛlf wɪð/', 'acquaint oneself with.mp3', 'phr.熟悉（知道）', 'd530309b28839dfd56b5c1d2966d2a45.jpg', '', 'She would acquaint herself with the local culture before visiting an unfamiliar city.', '在去一个陌生的城市旅游之前，她总会预先熟悉当地文化。', 'deb86a1f2f5481999812bc966b6d5405.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3446, 'act', '/ækt/', 'act.mp3', 'v.表演，扮演；  n.行为，行动', '169e8e8df2cb67434f069db8463a0e6a_86688_1577953136.jpeg', '20130307_16_39_05_124.png', 'The girl will act the part of princess in the play.', '这个女孩将在剧中扮演公主的角色。', '659506d06dcb92d681fb1c454402eb7e_38254_1577953132.mp3', 'act行动，做 → act表演，装作', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3447, 'advantage over', '/ədˈvæntɪdʒ ˈoʊvər/', 'advantage over.mp3', 'phr.占优势', '45622b4106f5a03a08d9f3c2df57190d.jpeg', '', 'Wheels gave the snail an advantage over everyone else in the race. ', '轮子让这只蜗牛在赛跑中比其他蜗牛占优势。', '11cda6c968ef0c256a532d257d5fc1c6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3448, 'ahead', '/əˈhed/', 'ahead.mp3', 'adv.领先地；提前；  adj.在前的，向前的', '3_0_20160718112907_44738_c-gigapixel-scale.jpg', 'd_16_8389_0_2_20150808232939.png', 'I am running ahead of the rest of the group.', '跑步的时候，我领先于小组的其他人。', '3_0_20160718112907_88721_c.aac', 'a副词前缀 + head头 → ahead在前，提前', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3449, 'all over', '/ɔːl ˈoʊvər/', 'all over.mp3', 'phr.到处，遍及', '1d9a885e8c0b0be10fe60d2bb0b32639_192289_1579338045.jpeg', '', 'I have friends all over the world.', '我的朋友遍天下。', 'ncnv2he4rg8n64f5qf7zmadmbm432xec.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3450, 'all right', '/ˌɔːl ˈraɪt/', 'all right.mp3', 'phr.顺利的；正确的', '2c3d5020c497faa43d2c54a4b97e563f_196176_1579596571.jpeg', '', 'Thankfully the operation went all right.', '谢天谢地，手术进行得很顺利。', '87c1c5a0e938fd2815b1c3db5963d9f2_36958_1579596567.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3451, 'anxious', '/ˈæŋkʃəs/', 'anxious.mp3', 'adj.焦虑的，不安的', 'i_16_10250_0_5_151104095040-gigapixel-scale.jpg', '20140926_00_09_39_81_v3.png', 'The boy is anxious about the exam.', '这个男孩对考试感到焦虑。', 'sa_16_10250_0_6_160326163924.aac', 'anxi焦虑 + ous形容词后缀 → anxious焦虑的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3452, 'apparent', '/əˈpærənt/', 'apparent.mp3', 'adj.显然的；表面上的，貌似（真实）的', 'i_1_185_0_10_160125155921-manual-scale.jpg', 'd_16_185_0_2_20150808223150.png', 'It\'s apparent that the boy is taller than the girl.', '很明显，那个男孩比女孩高。', 'sa_1_185_0_10_160125155958.aac', 'ap加强意义 + par看见 + ent…的 → 能看见的 → apparent清晰易见的；显然的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3453, 'application', '/ˌæplɪˈkeɪʃn/', 'application.mp3', 'n.应用程序', 'a1398338de017175ab9f1b171b0426d1_181360_1582269399.jpg', 'd_107_6955_0_2_20150809021217.png', 'I download many applications on my cellphone.', '我在手机上下载了许多应用程序。', '75d010dba1e132fabc892bf7fdf36a1b_32912_1562142963.mp3', 'apply放置到=应用 + cation表名词 → application应用，运用', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3454, 'appreciate', '/əˈpriːʃieɪt/', 'appreciate.mp3', 'v.感谢，感激；欣赏；增值', 'fd56eaf0a9d02050aeceff538890354b_40230_1565620269.jpg', 'd_13_5788_0_3_20150808183527.png', 'Grandma appreciated the gift on her birthday.', '外婆为她生日那天收到的礼物表示感谢。', 'us_Grandma_appreciated_20240124134001954_d5f1348a079124e1fb12.mp3', 'ap一再 + preci价值 + ate动词后缀 → 一再给价 → appreciate欣赏', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3455, 'arrest', '/əˈrest/', 'arrest.mp3', 'n.逮捕，拘留；  v.逮捕，拘留', 'c767eef3a9aa93c8b99781be39ca2425_87370_1700719431.jpeg', '20141014_01_11_07_7_v3.png', 'He was arrested for breaking the law.', '他因为犯法被抓起来了。', '67e17f6a724795a5_1266883370362034828_250207.mp3', 'ar一再 + rest休息 → 不让动 → arrest逮捕，阻止', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3456, 'artificial', '/ˌɑːrtɪˈfɪʃl/', 'artificial.mp3', 'adj.人造的', '6f49ad415aca0f3993be42c3bc8e485c_52881_1669366541.jpg', '20141013_02_18_36_626_v3.png', 'Even with an artificial leg', '尽管有一条假肢，他依然可以跑赢你。', 'ws2ukbk5t9q4ph7dcl5afpzepuel69du.mp3', 'artific技巧 + ial形容词后缀 → 用技巧做出的 → artificial人工的；矫揉造作的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3457, 'assign', '/əˈsaɪn/', 'assign.mp3', 'v.布置；分配；指定；分派；归因；确定', '7e4d54f00404cd977a68fe0dedcda254_90988_1565321546.jpg', 'd_1_4595_0_2_20150808122912.png', 'Our teacher assigned us lots of homework.', '我们的老师给我们布置了许多家庭作业。', 'bkxscud34bzvc52q4jf3w93xr96394ct.mp3', 'as一再 + sign记号 → 不断给人标记号 → assign指定；分配', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3458, 'associate', ' /əˈsoʊsieɪt/; /əˈsoʊʃieɪt/ ', 'associate.mp3', 'v.联想；联合；  n.伙伴；同事，合作人；  adj.副的', '3_0_20160718114844_24998_c-gigapixel-scale.jpg', 'd_16_5434_0_2_20150808225308.png', 'People always associate red roses with love and romance.', '人们总是把红玫瑰与爱情和浪漫联系在一起。', '3_0_20160718114844_82886_c.aac', 'as去 + soci联合 + ate表动词  → 结成团队 → associate联合', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3459, 'astonish', '/əˈstɑːnɪʃ/', 'astonish.mp3', 'v.使吃惊', 'd03393a13d78a6fc17824706e282686e_64132_1564823517.jpg', '0892daca45c34883d9ed84a75f894aa0_52068_1551843227.png', 'The magic astonished the kids.', '这个魔术使孩子们感到吃惊。', 'sa_16_8478_0_7_151124154010.aac', 'as=ex表强调 + ton打雷 + ish表动词 → astonish使吃惊', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3460, 'Australian', '/ɔːˈstreɪliən/', 'Australian.mp3', 'adj. 澳大利亚的；澳大利亚人的；  n.澳大利亚人', '8225272e992c1a7ff8a3c83b6e979e8e_104791_1656930281.jpg', '20141014_17_59_18_651_v3.png', 'Kangaroos are the Australian national animals.', '袋鼠是澳大利亚的国家动物。', 'us_Kangaroos_are_20250604140505213_8f2d43e74f05c8257af0.mp3', 'Australi澳大利亚 + an...的/人 → Australian澳大利亚的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3461, 'await', '/əˈweɪt/', 'await.mp3', 'v.等候；  v.等待……发生', 'i_1_5267_0_4_150908145343-gigapixel-scale.jpg', 'd_1_5267_0_2_20150808123723.png', 'People are awaiting the bus.', '人们正在等车。', 'us_People_are_20230314141208004_0de163ea0c38ac2f58f3.mp3', 'a使 + wait等待 → await等候', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3462, 'bargain', '/ˈbɑːrɡən/', 'bargain.mp3', 'v.讨价还价；经讨价还价成交；  n.交易；便宜货；契约', 'e52d4232b1ca30eceaed45ebd57a1963_137097_1701049238.jpg', 'd_16_4156_0_2_20150808224039.png', 'The lady is trying to bargain with the seller.', '这位女士试图和卖方砍价。', 'bacc6ssrekgmqxanbrcfdvx393x26w3a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3463, 'be absorbed in', '/bi əbˈzɔːrbd ɪn/', 'be absorbed in.mp3', 'phr.专心于', 'eb33ddfa18bd992ca06d82e35ba010fe.jpg', '', 'Although it\'s very noisy outside', '虽然外面很吵，但她完全专注于看书而没有注意到噪声。', 'd56d4a1b0c8b61aa8d88b507d59513b5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3464, 'behind', '/bɪˈhaɪnd/', 'behind.mp3', 'prep.在……后面；  adv.（时间或空间上）在后面；  n.（口语）屁股', 'i_16_17946_0_8_151104124154-gigapixel-scale.jpg', 'd_24_17946_0_4_20150808233645.png', 'Who is the girl standing behind the boy?', '站在那个男孩子后面的小女孩是谁？', '9e6705186777fe5d_1266763311914462040_250117.mp3', 'be构成介词 + hind藏在后面 → behind在......后面', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3465, 'being', '/ˈbiːɪŋ/', 'being.mp3', 'n.存在；生物', 'e228b2a40c7edfbbc5011406a857d4fb_55717_1585130277.jpeg', 'd_16_19557_0_6_20150809022623.png', 'The universe came into being as a result of a big bang.', '宇宙的出现是大爆炸的结果。', 'us_The_universe_20220704102417738_02c027b60f27e27d2a6f.mp3', 'be存在，成为 + ing名词后缀 → being存在', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3466, 'bicycle', '/ˈbaɪsɪkl/', 'bicycle.mp3', 'n. 自行车', 'cc21bb7eceea8da744875fcdd76ee729_120407_1587457586.jpg', '20141015_14_20_03_691_v3.png', 'We are riding bicycles for a trip.', '我们正在骑自行车旅行。', 'a42434f152ab9329_1268213315428696764_250930.mp3', 'bi两 + cycle轮转 → bicycle自行车', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3467, 'building', '/ˈbɪldɪŋ/', 'building.mp3', 'n.建筑；大楼', '83c2cabbc70632b0aa61f93dbca2fea3_148486_1680148194.jpg', 'd_24_17963_0_3_20150808233758.png', 'In this modern city center', '在这座现代化城市的中心，每栋建筑看起来都一样。', '02635cadee70b8b6_1266797982352321296_250123.mp3', 'build建造 + ing某种行为的产物 → building建筑物', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3468, 'bulletin', '/ˈbʊlətɪn/', 'bulletin.mp3', 'n.公告；公告牌；公报', '3_0_20160530152329_23283_c-gigapixel-scale.jpg', '20140917_20_31_17_839_v3.png', 'The students are reading some notices posted on the bulletin board.', '学生正在读公告栏上张贴的一些通知。', 'c3cb93dc2c13d42e_1266883626118634032_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3469, 'by way of', '/baɪ weɪ əv/', 'by way of.mp3', 'n.作为……', '074c130c88b3ee3378688ad6a15aa735.jpg', '', 'He sent her flowers by way of appreciation for helping him find his dog. ', '她帮忙找到了他的狗，所以他送花给她作为答谢。', '2fc93ca93d32d51aab11c6e76cf61d4d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3470, 'catalogue', '/ˈkætəlɔːɡ/', 'catalogue.mp3', 'n.目录', 'i_904_-904_0_1_160202144112.jpg', '', 'The girl got information about the clothes from the product catalogue.', '女孩能从产品目录中得到关于衣服的信息。', 'fxjlcwrvsxwt6sv7yd734evq4dd4suan.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3471, 'champion', '/ˈtʃæmpiən/', 'champion.mp3', 'n.冠军，优胜者；拥护者，卫士；  v.拥护；保卫；为……而斗争', 'b21d8348a981d0e1a5be808276ab88a2_187787_1539660567.jpeg', 'd_14_5733_0_3_20150808162313.png', 'The French football team became the champion of the 2018 World Cup!', '法国足球队成为2018年世界杯冠军！', '0756d897dc9c0f5cb588f9ac96ef9786_35525_1552617456.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3472, 'check', '/tʃek/', 'check.mp3', 'v.查看，检查；阻止；  n.阻碍物；支票（=cheque）；阻止；检查', '85e2a706e98574d184dd4064c2a55d3e_78383_1575286419.jpg', 'd_51_9995_0_2_20150809022458.png', 'Let me check if your blood pressure is normal.', '让我查查你的血压是否正常。', '102512284314aafb_1266883198038399548_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3473, 'circle', '/ˈsɜːrkl/', 'circle.mp3', 'n.圆圈；范围；  v.围绕', 'i_1_7963_0_2_20150808130226-gigapixel-scale.jpg', 'd_24_7963_0_3_20150808225310.png', 'We\'re running in circles.', '我们在绕圈跑。', 'svelj7rzytb4k8fzlegfua94m265gws8.mp3', 'circ环 + le名词后缀 → circle圆圈', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3474, 'colleague', '/ˈkɑːliːɡ/', 'colleague.mp3', 'n.同事；同行', 'i_4_5610_0_4_151222171856-manual-scale.jpg', 'd_16_5610_0_5_20150808225547.png', 'I really learned a lot by discussing with my colleagues.', '通过和同事们讨论，我真的学到了很多。', '8a9711a48e638143_1266883529659275920_250207.mp3', 'col共同 + league捆绑 → 捆绑在一起的人 → colleague同事', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3475, 'combination', '/ˌkɑːmbɪˈneɪʃn/', 'combination.mp3', 'n.（保险锁等的）组合码；结合，联合', 'fae876e3d4d21e1e24ae9c75cf95a818_98965_1579596931.jpg', 'd_105_8404_0_2_20150809060929.png', 'A combination is a series of numbers or letters used to open a combination lock.', '组合码是用来开密码锁的一系列数字或字母。', '1a066bde4eb8597a77f9d6f9871cfb83_47278_1579596888.mp3', 'com共同 + bin=bine藤蔓 + ation表名词 → combination结合，联合', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3476, 'compact', '/kəmˈpækt/', 'compact.mp3', 'adj.小巧的，体积小的；紧凑的，密集的；  v.把……压紧；变得坚实；  n.带镜小粉盒', '4d633c305c6c0d50f129878d6b89b2b4_200594_1528687549.jpg', '', 'Smartphones are the most compact computers; they\'re much smaller than laptops.', '手机是最小巧的电脑，它们比笔记本电脑小多了。', '9e9dd42e82331d43dc33f3f7671b36e5_48853_1584787779.mp3', 'com共同 + pact压紧 → 全部压紧 → compact紧密的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3477, 'complaint about', '/kəmˈpleɪnt əˈbaʊt/', 'complaint about.mp3', 'phr.有关…的投诉，抱怨，不满', 'b0656a20ddd126f22fdeb79bbea0044f.jpeg', '', 'He is making a complaint about the noise upstairs to the police.', '他正在向警察投诉楼上的噪音。', '7101e33f2c460c16af8c75ec77fb1d62.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3478, 'conflict with', '/ˈkɑnˌflɪkt wɪð/', 'conflict with.mp3', 'phr.与……冲突', 'ebe0509520b77ca513df63ae8dec8f45.jpg', '', 'The date of the party #conflicts with# her final maths exam.', '聚会的日期与她期末数学考试的日子冲突了。', '8656ea0e681d7f5aba22e9ef323b43b5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3479, 'conform', '/kənˈfɔːrm/', 'conform.mp3', 'v.遵照，顺从；  v.使一致', '600b7a501ebcb1fde38bca60dcad3962_56136_1701050624.jpg', 'd_107_584_0_2_20150809000955.png', 'It is important for everyone to conform to traffic regulations.', '我们每个人都应该遵守交通规则！', 'us_It_is_20231127100841011_112411bd0bebc2f2c171.mp3', 'con共同 + form形状 → conform符合，一致', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3480, 'conservative', '/kənˈsɜːrvətɪv/', 'conservative.mp3', 'adj.保守的；保守估计的；保守党的；  n.保守者；保守党党员', 'c93295f32308ae6715a05d9993336b51_120855_1741156635.jpg', 'd_107_5542_0_2_20150809012937.png', 'The company’s conservative investment strategy helped them avoid major losses during the economic downturn.', '公司的保守投资策略帮助他们在经济低迷时期避免了重大损失。', 'us_The_companys_20250305143709694_2d45a419c8ba4a021ae4.mp3', 'conserv保留 + a + tive形容词后缀 → conservative保守的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3481, 'contrary to', '/ˈkɑːnˌtreriː tu/', 'contrary to.mp3', 'phr.与……相反', '06d38b30fa5e0f39a2ecd24b6f9340e4_151910.jpg', '', 'Contrary to popular belief', '与普遍观点相反，很多猫不喜欢牛奶。', '69ef5208514ab9c5fc9f5bfd65472e34_39163.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3482, 'contribution to', '/ˌkɑːntrɪˈbjuːʃn tuː/', 'contribution to.mp3', 'phr.对……的贡献', '323441736402c4a9a6475d649e854cf2.jpg', '', 'He made a contribution to helping the poor.', '他对帮助穷人做出了贡献。', '81c5af398aebfa91cb474bc53bc9bbfa_37664_1593575542.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3483, 'conversation with sb. about sth.', '/ˌkɑːnvərˈseɪʃn wɪð ˈsʌmbədi əˈbaʊt ˈsʌmθɪŋ/', 'conversation with sb. about sth..mp3', 'phr.和……关于……的交谈', 'bb7c4f1dbf33dd84673e5492a0b5d53b.jpg', '', 'He is having a conversation with his friend about football.', '他和朋友正在谈论足球。', 'ed202d39c797e49991fae6047c183718_47744_1593575558.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3484, 'cow', '/kaʊ/', 'cow.mp3', 'n.母牛，奶牛；  v.恐吓，吓倒', 'cow_6711_20231106_ee2cb1d3.jpg', '20141009_20_06_38_534_v3.png', 'We feed a cow to get milk for breakfast.', '我们养了一头奶牛为我们的早餐提供牛奶。', 'd71ec34a80346c3f_1266763312896584564_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3485, 'creature', '/ˈkriːtʃər/ ', 'creature.mp3', 'n.动物；生物', 'd022edc3fd2beaabc1be53d8f3ecbf64_55262_1565604958.jpg', 'd_24_9748_0_3_20150808230251.png', 'Is your favorite creature the dog', '你最喜欢的动物是狗、猫，还是兔子？', 'a5b9d0a1e05c63be_1266883634504575942_250207.mp3', 'creat创造 + ure表名词 → 创造物，生物', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3486, 'criticize', '/ˈkrɪtɪsaɪz/', 'criticize.mp3', 'v.批评，评论，责难（同criticise）', '34bc76b0964a85951ddcb3c7e3663550_179720_1535009164.jpeg', 'd_20_5803_0_2_20150808170202.png', 'The teacher is criticizing the student for being late.', '老师正在因为学生迟到而批评这名学生。', 'a2946ccf2c4654189caac37698a16df1_35827_1535009158.mp3', 'critic评论家 + ize表动词 → criticize批评', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3487, 'cut back', '/kʌt bæk/', 'cut back.mp3', 'phr.削减', '1e93cc20296a92fe703bc644e349050e.jpg', '', 'She has cut back her studying hours recently. ', '她最近减少了学习时间。', '310317974b49bbb1bdf556fad38212cd.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3488, 'database', '/ˈdeɪtəˌbeɪs/', 'database.mp3', 'n.数据库', '916160d6adc0f1b04ebefb6a64e5e097_96965_1575099556.jpeg', 'd_16_5149_0_3_20150808225044.png', 'He works in the data center and maintains the database.', '他在数据中心工作，负责维护数据库。', '382cad80b2efaad32d74336e87f86029_38686_1575099554.mp3', 'data数据 + base基地，根据 → database数据库', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3489, 'deadline', '/ˈdedlaɪn/', 'deadline.mp3', 'n.最后期限', '57093b6a88464ece717e499a6391589a_143729_1557995373.jpeg', 'd_107_7008_0_2_20150809021337.png', 'The employee worked overtime to meet the deadline.', '为了赶最后期限，这名员工加班加点地工作。', '3_0_20160624110612_34499_c.aac', 'dead死亡 + line直线，线条 → 死亡期限 → 最后期限', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3490, 'deaf', '/def/', 'deaf.mp3', 'adj.聋的；不愿听的', '90d7310f3874c71f9a9715a850349661_43296_1578558578.jpeg', 'd_24_5777_0_4_20150808224338.png', 'The girl is completely deaf; she can\'t hear anything.', '这个女孩失聪了，什么也听不见。', '7d567f3b9f7f8f79_1266883002522446594_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3491, 'deal with', '/ˈdiːl wɪθ/', 'deal with.mp3', 'phr.处理；研究', 'f4771058eac86691d294ff0a65b5726d_583432_1701678799.jpg', '', 'The workers are hired to deal with the garbage.', '工人们被雇用来处理这些垃圾。', 'sa_4_10230_0_2_20150808183552.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3492, 'delicate', '/ˈdelɪkət/', 'delicate.mp3', 'adj.易碎的，脆弱的；（人）娇弱的，体弱多病的；精美的，精致的；微妙的，需要谨慎处理的；优美的，优雅的；淡雅的', '830bb70153ee9bf694e1446d77245af0_177548_1543909970.jpeg', 'd_16_4512_0_7_20150808224313.png', 'The vase is delicate and should be packed with care.', '花瓶易碎，应小心打包。', 'zzb4bp5h4wpdmd2dsm29zgewltxd5ucq.mp3', 'de远离 + licate诱惑，吸引 → 易损坏但有吸引力的 → delicate精致的，易碎的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3493, 'demand for', '/dɪˈmænd fɔr/', 'demand for.mp3', 'phr.对……的需求', 'f35a5c2de2309250cdc34c49a0342e0b.jpeg', '', 'There is much more demand for ice cream in summer than in winter. ', '人们在夏天对冰激凌的需求比在冬天多得多。', '624ce7b0567d9365073f7a54fc47db1b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3494, 'derive from', '/dɪˈraɪv frʌm/', 'derive from.mp3', 'phr.起源于', 'bae302d497ea31835babed011aac46e6.jpg', '', 'Some English words are derived from old French words.', '有些英语单词来自古法语词汇。', 'b3l93b33m9hghjrr72ysxvpe4qej65g4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3495, 'design', '/dɪˈzaɪn/', 'design.mp3', 'n.设计（方案）；图样；  v.设计，制造', 'i_1_16468_0_4_151019152408-gigapixel-scale.jpg', 'd_100_12381_0_4_20150809032444.png', 'Look at these dress designs. They are so fashionable.', '看这些裙子的设计，真是时尚。', 'sa_1_16468_0_4_151029154459.aac', 'de使…成为，加强 ＋ sign写，做标志 → design设计，计划', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3496, 'destination', '/ˌdestɪˈneɪʃn/', 'destination.mp3', 'n.目的地', 'i_1_841_0_6_150910171534-gigapixel-scale.jpg', '20141011_04_16_57_417_v3.png', 'The destination of their journey was the Western Heaven.', '他们此行的目的地是西天。', 'x3q6htahsuszccanalpab6cj89g83wcv.mp3', 'de向下 + stin站立 + ation名词后缀 → 下一个立足点 → destination目的地，目标', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3497, 'determination', '/dɪˌtɜːrmɪˈneɪʃn/', 'determination.mp3', 'n.决心；确定', '186adf04fa93b4364e39ce26c9031cb5_195252_1584008199.jpeg', '', 'His determination helps him lose weight through exercise.', '他的决心帮助他通过运动减肥。', '17653b887f5da04ef641efd65e9cf1f6_21362_1619335260.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3498, 'diagram', '/ˈdaɪəɡræm/', 'diagram.mp3', 'n.图表', '12234a335c59f7f96d725241eb82f130_69959_1594800707.jpg', 'd_24_4811_0_3_20150808223558.png', 'The diagram in this textbook shows how the water cycle works.', '这本教科书中的图解展示了水循环的过程。', '5d88p9tw39tl8g3gnyebxkq3ukywuw6u.mp3', 'dia穿过，二者之间 + gram写，图 → 交叉对着画 → 图表', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3499, 'die', '/daɪ/', 'die.mp3', 'v.死亡', 'a2d209edf0365958403b8ef2f9373b5d_52604_1578559718.jpeg', '20141005_02_16_42_805_v3.png', 'The old dog died peacefully at home.', '那只老狗在家里安详地死去了。', '29r7rblf5w4zk6zghh8g7yhvt2v7jk3l.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3500, 'digital', '/ˈdɪdʒɪtl/', 'digital.mp3', 'adj.数字显示的；数码的', '9a6c69e531e786ded8730a2ff7f24cf1_73939_1559026202.jpg', 'd_24_6318_0_3_20150808224601.png', 'This is a black digital stopwatch.', '这是一块黑色的数码秒表。', 'ev6ux5b89qljsda4wmsewwl2ftjfs9h8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3501, 'dimension', '/dɪˈmɛnʃən/', 'dimension.mp3', 'n.维，维度；尺寸；尺度；方面', 'baac28084f0ebe5429b8e9a1a9a3e7b4_58798_1569059401.jpg', 'd_16_4515_0_2_20150808224314.png', 'These different shapes have three dimensions.', '这些不同的图形都是三维的。', '89d056256e6e408269363cef233d2827_14936_1624332242.mp3', 'di=dis不同的方向 + men测量 + ion名词后缀 → dimension维度', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3502, 'direct to', '/dɪˈrɛkt tu/', 'direct to.mp3', 'phr.指向，对着；送往，呈交', 'f1f7543fa6328f4c732e71c3e4aee7df.jpg', '', 'She directed the extinguisher to the fire.', '她把灭火器对准火焰喷射。', 'afc4a09a93bc805e2de102fe24c67daf_14622_1607065216.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3503, 'discourage', '/dɪsˈkɜːrɪdʒ/', 'discourage.mp3', 'v.劝阻；使泄气', '718097b74a456261b920c0e9dd45afa5_204285_1558670541.jpeg', 'd_105_6866_0_2_20150809060115.png', 'The bad weather discouraged her from having a picnic.', '这糟糕的天气使她不能外出野餐。', 'zeqhctk37q79upg4ywjcvftadqw8efsv.mp3', 'dis除去，取消 + courage勇气 → discourage使失去勇气', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3504, 'dispute', '/dɪˈspjuːt/', 'dispute.mp3', 'n.争论，争端；  v.争执，驳斥', '16d19d46a6a4e31153ae9321dd4761b3_72661_1732687802.jpg', 'd_1_5748_0_3_20150808124329.png', 'They\'re having a dispute about the car accident.', '他们正在争论车祸的事情。', 'us_Theyre_having_20241127141008543_fb95fb2fe20ded410dff.mp3', 'dis分开 + put思考 → 不同的思考 → 引申为dispute争论', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3505, 'distribute', '/dɪˈstrɪbjuːt/', 'distribute.mp3', 'v.分发；配送', 'b7d80bacb6aee3c2af1c2891b6e2e602_189976_1588932995.jpeg', 'd_16_3969_0_2_20150808223910.png', 'They distribute food to the people in need.', '他们把食物分发给有需要的人。', 'bec9fb517aac418bcf4d8bcf481050a6_13525_1633682314.mp3', 'dis分开 + tribute赠品 → 分开给 → distribute分配；区分', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3506, 'distribute to', '/dɪˈstrɪbjuːt tuː/', 'distribute to.mp3', 'phr.分配，分发', 'b7d80bacb6aee3c2af1c2891b6e2e602.jpeg', '', 'They are distributing food to the people in need. ', '他们正在把食物分发给有需要的人。', '922a58b58730fc4a546b6643046f9c02.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3507, 'drop in', '/drɑp ɪn/', 'drop in.mp3', 'phr.顺便拜访', '3_0_20160528170616_52847_c.jpg', '', 'My classmate dropped in on me on his way home.', '我同学在他回家的路上顺道拜访了我。', '3_0_20160528170616_45892_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3508, 'drop out', '/drɔp aut/', 'drop out.mp3', 'phr.辍学；不参与', 'b7d5f03489b6601ac05f501078277657_168573_1524899255.jpeg', '', 'He dropped out of school and found a job in order to help his family.', '为了帮扶家里，他辍学去工作了。', '9vkh6quq4wqm4jhttpw33328a46hj3cl.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3509, 'element', '/ˈelɪmənt/', 'element.mp3', 'n.元素；成分；要素', 'i_1_10561_0_4_160114102834-gigapixel-scale.jpg', 'd_1_10561_0_2_20150808131701.png', 'Water contains the elements of hydrogen and oxygen.', '水含有氢和氧元素。', '50a4eb83a8a3c7f81d2f1ffd999fe0b4_35399_1528529780.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3510, 'embassy', '/ˈembəsi/', 'embassy.mp3', 'n.大使馆；大使馆全体人员', 'd6ee4b37d40dc439c779b77fe0957af2_110153_1524128733.jpg', '7a962b80b0b05b3fb155460f31c33094_56838_1551252638.png', 'The US embassy in the UK is located in London.', '美国驻英大使馆位于伦敦。', '59adfb252edde179_1266883627794279252_250207.mp3', 'ambi两边，周围 + ass做，代理 + y表名词 → 代理围在一起做事 → embassy大使馆', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3511, 'evident', '/ˈevɪdənt/', 'evident.mp3', 'adj.显然的，明显的，明白的', '8ee96a4e1d7da2b95266819151e05839_172785_1524896367.jpeg', 'd_16_6156_0_4_20150808230248.png', 'It\'s evident that the salesman is lying.', '很明显这个推销员在说谎。', '1dd55b5f481b886806ec899dd3d51a69_31055_1524896373.mp3', 'e易于的 + vident看 → evident明显的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3512, 'evil', '/ˈiːvl/', 'evil.mp3', 'adj.邪恶的；  n.邪恶，罪恶，恶行', 'b62b016e6bdfc8251a0e358854bdac9c_71032_1564733624.jpg', '97189ac6e158347d69f94ad0eb39b8d8_27123_1539341444.png', 'This evil monster has a devilish stare.', '这个邪恶的怪物眼中闪过一丝魔鬼般的光芒。', 'eae0f3a351b71c38_1266883534753737642_250207.mp3', 'e加强或引申意义、使… + vil=base（卑劣的）→ evil邪恶；罪恶的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3513, 'evolution', '/ˌevəˈluːʃn/', 'evolution.mp3', 'n.进化，演变', 'i_1_5786_0_2_20150808124411-gigapixel-scale.jpg', 'd_107_5786_0_2_20150809013917.png', 'The theory of evolution is a wonderful explanation of how life arose.', '进化论是关于生命如何产生的精彩阐释。', 'sa_1_5786_0_2_20150808124411.aac', 'e出 + volu转 + tion表名词 → evolution进化', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3514, 'exchange for', '/ɪksˈtʃendʒ fɔr/', 'exchange for.mp3', 'phr.交换', '4fda42f936213e923be1bc405794eb64.jpg', '', 'She wants to exchange the red dress for a white one.', '她想把这件红色的连衣裙换成白色的。', '3570bf4574fe66e4b3d193fd274d77e6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3515, 'exist', '/ɪɡˈzɪst/ ', 'exist.mp3', 'v.存在；生存，生活', '76ec9b383f8eec95d39b8b4c68ab5e23_50031_1707199443.jpg', 'd_24_4961_0_4_20150808223724.png', 'Do aliens exist on other planets?', '其他星球上会有外星人存在吗？', 'ebb5b8709da54944_1266797979305007846_250123.mp3', 'ex出 + ist站立 → 站出来 → 活下来 → exist存在，生存', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3516, 'exit', '/ˈeksɪt/', 'exit.mp3', 'n.出口；退场；  v.离开，出去', 'i_1_8239_0_4_151020152018-gigapixel-scale.jpg', 'd_24_8239_0_4_20150808225536.png', 'You can find the exit by following the green light.', '跟着绿灯走，你就能找到出口。', '9ee30cae9b651f80_1266763525964475292_250117.mp3', 'ex出自…… + it走 → exit出口', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3517, 'expert', '/ˈekspɜːrt/ ', 'expert.mp3', 'n.专家；  adj.专业的；熟练的', '63105786393c91de420b9410c28d321b_150060_1565695100.jpeg', 'd_107_5102_0_2_20150809011534.png', 'The expert is sharing his knowledge of traditional Chinese medicine on the TV show.', '这个电视节目里的专家正在给观众讲授传统中医知识。', '52413e7e8620c332_1266883329359981322_250207.mp3', 'ex向外 + per尝试，试验 + t后缀 → 经历多次的人 → expert专家，行家', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3518, 'express', '/ɪkˈspres/', 'express.mp3', 'v.表达，表示；用快递寄出；  adj.快速的；明确的；  n.快车；快递', '97e4b77527cdc1b93ca3afbb555f3f0c_120638_1720086508.jpg', 'd_94_7138_0_3_20150809005041.png', 'With special gestures', '这对情侣用一些很独特的手势来表达爱意。', 'us_With_special_20240704174833554_38b88a3ff4c953c1b1dd.mp3', 'ex出来 + press挤压 → 挤出来 → express表达', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3519, 'extensive', '/ɪkˈstensɪv/', 'extensive.mp3', 'adj.广泛的；广阔的', '10531b717787754bfbb1de0f06dc2ce8_101112_1600669948.jpeg', 'd_107_1130_0_2_20150809001622.png', 'The flood caused extensive damage to the area.', '洪水导致该地区遭受大面积破坏。', 'us_The_flood_20241009154138457_3eb74ac6241926d92ca0.mp3', 'ex向外 + tens延伸 + ive形容词后缀 → 向外伸展的 → extensive大面积的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3520, 'extreme', '/ɪkˈstriːm/', 'extreme.mp3', 'adj.极端的；极限的；  n.极端', '1c8a26ca66a424befa7e650cf4d4ddb3_490624_1610522717.jpg', 'd_24_5555_0_4_20150808224136.png', 'Extreme weather conditions destroyed the city.', '极端天气状况摧毁了这座城市。', '85c6e1bcb1532ded15dc5f3a8ce92a61_23021_1621924244.mp3', 'extr出去 + eme表最高级 → extreme极端的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3521, 'farther', '/ˈfɑːrðər/', 'farther.mp3', 'adv.更远地；  adj.更远的', 'c5969c815fd3c37db5afe2bbf84c7952_21456_1649672645-gigapixel-scale.jpg', 'd_109_6865_0_2_20150809054821.png', 'We need to move farther to reach the destination.', '我们需要再往前走才会到达目的地。', 'sa_1_6865_0_3_20150808125606.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3522, 'fast', '/fæst/', 'fast.mp3', 'adj.迅速的，动作敏捷的；  adv.迅速地', '1752e8b7a26c4c14b320083bfd55d2b1_1083242_1680491475-800-600.jpg', '20121225_18_34_27_292.png', 'The car was going so fast! I could hardly see it!', '那辆车开得太快了！我几乎看不见它了。', 'nyrr95j44behap4vrtgm2ph6aaen3keb.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3523, 'fit for', '/fɪt fɔr/', 'fit for.mp3', 'phr.适合的', '2e77918432551c56cdfcfa6ce02f4ea9.jpeg', '', 'She was confident and outgoing—a perfect fit for this job.', '她既自信又外向，非常适合这份工作。', '325dc261192b6d874d4941d3258d3b9f.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3524, 'furthermore', '/ˌfɜːrðərˈmɔːr/', 'furthermore.mp3', 'adv.此外，而且', '1d2e039c009af0643dbd323a61be68ca_195543_1604915798.jpg', '', 'He broke his leg in the forest', '他在森林中摔断了腿，此外，一些奇怪的生物正盯着他。', '5_51_78_20161128181529_32374_c.aac', 'further更远的 + more更多的 → furthermore此外，而且', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3525, 'gene', '/dʒiːn/', 'gene.mp3', 'n.基因', 'i_1_1259_0_4_150923101254-gigapixel-scale.jpg', 'd_105_1259_0_2_20150809053136.png', 'DNA consists of a large number of genes.', 'DNA包含大量的基因。', 'sa_1_1259_0_5_160317100506.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3526, 'give way to', '/ɡɪv weɪ tu/', 'give way to.mp3', 'phr.让路', '0c1bcac4762092cb8eadcccc68d10f14.jpg', '', 'The driver has stopped to give way to the chickens.', '司机停下车，给小鸡们让路。', '617d00bae2c60f5c6240fd2dfb2ea2b0.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3527, 'glance at', '/ɡlæns æt/', 'glance at.mp3', 'phr.浏览，扫一眼', '5d7ba7f92522760aea90e6697c6219b6.jpg', '', 'She glanced at her watch.', '她瞥了一眼自己的手表。', '9e5ba1ab45c573bd0140ff1be231556e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3528, 'grasp', '/ɡræsp/', 'grasp.mp3', 'v.抓住，抓紧；领会，理解；  n.紧握', '12cec94ec077566f467282be2fd942d7_99639_1600068615.jpeg', '20140929_03_05_00_955_v3.png', 'The baby grasped his mother\'s finger.', '婴儿抓住了母亲的手指。', '0d941df36b75469e1855327b0ec6ff95_39406_1600068638.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3529, 'hardly', '/ˈhɑːrdli/', 'hardly.mp3', 'adv.几乎不，几乎没有', '8bfa9c384554276168dc631c9ca76dd4_77110_1732243796.jpg', 'd_24_19513_0_4_20150809001752.png', 'The man always stays at home and hardly goes out.', '这个男人整天待在家，几乎不出门。', '1e9c237c272118be_1266883376147028604_250207.mp3', 'hard艰难 + ly...地 → ad.几乎不，简直不', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3530, 'heading', '/ˈhedɪŋ/', 'heading.mp3', 'n.标题（用于文章或章节开头）', 'b9817466ebcc7b6ed0d26935e2e28c4a_149604_1591847210.jpeg', 'd_105_6148_0_2_20150809055509.png', 'A heading is written or printed at the top of a page of writing.', '标题通常书写或打印在一页文字的顶部。', '7f947bae49cb42c50a121a5c860490fa_27389_1621924872.mp3', 'head头 + ing表名词 → 文章中在顶头的 → heading标题', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3531, 'hear of', '/hɪr əv/', 'hear of.mp3', 'phr.听说，听到；知道', '81f4006f62752565e8f706a5ad7b48d7_122768_1579333335.jpeg', '', 'She heard of a car accident that happened on the street.', '她听说街上发生了一起车祸。', 'c3946560c1ce7b7ea374ea57ffa0560a_45958_1579333332.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3532, 'heat', '/hiːt/', 'heat.mp3', 'n.高温；【物理学】热；  v.加热，变热', 'a85a68cb2153ba8925ac40f25a029528_112622_1574823320.jpeg', 'd_24_17725_0_4_20150808233329.png', 'Charcoal gives off heat when it burns.', '木炭在燃烧时释放出热量。', '04ff0c00cdbe327d14750f0152c41d8a_28750_1574823315.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3533, 'heel', '/hiːl/', 'heel.mp3', 'n.（鞋、袜子、脚）后跟；  v.修理后跟', '2e459c158cad9c57be329fd922826bac_33885_1731901284.jpg', 'd_24_9526_0_4_20150808230238.png', 'The red shoes with high heels look great.', '这双红色高跟鞋看起来不错。', 'sa_1_9526_0_4_160123143534.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3534, 'hold on', '/həʊld ɒn/', 'hold on.mp3', 'phr.紧紧抓住', 'aa76c97646412c7eaf267fcc34df9f2d_119102_1579335950.jpeg', '', 'He still holds on to his phone', '即使他要摔倒了，他仍然紧紧抓住他的手机。', 'f97fa4188620c100b8b10cbd6ea26934_43798_1579335948.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3535, 'illness', '/ˈɪlnəs/', 'illness.mp3', 'n.疾病', '9fa282adb8f553cb02abe9428ac3c55c_65613_1541831815.jpg', '20121225_19_23_51_4.png', 'He has an illness', '他生病了，但仍然要工作。', 'xz3wuzsfaar5jcmefg63stpkr62pum3z.mp3', 'ill有病的 + ness名词后缀 → illness疾病', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3536, 'impatient', '/ɪmˈpeɪʃnt/', 'impatient.mp3', 'adj.不耐烦的', '2985d36467932731bb0f4e987e23f715_45754_1538810080.jpg', 'd_13_10995_0_2_20150808202706.png', 'He had been waiting for twenty minutes and he was getting impatient.', '他已经等了二十分钟，有点不耐烦了。', '0ef8450d6e34e12e72f8c4c05d1f9de7_17129_1538810086.mp3', 'im不 + patient有耐心的 → impatient不耐烦的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3537, 'importance', '/ɪmˈpɔːrtns/', 'importance.mp3', 'n.重要性', 'i_1_11033_0_4_151112105323-gigapixel-scale.jpg', 'd_24_11033_0_4_20150808230537.png', 'Wi-Fi is of great importance to people as it becomes a basic need.', 'Wi-Fi对人们很重要，它已经成了一项基本需求。', 'sa_1_11033_0_4_151211154918.aac', 'im进 + port拿，运 + ance名词后缀 → 带有意义的状态 → importance重要性', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3538, 'in a hurry', '/ɪn ə ˈhɜːri/', 'in a hurry.mp3', 'phr.匆忙，很快地', 'i_16_18650_0_5_20150809015736.jpg', '', 'He is in a hurry to go to work!', '他急着赶去上班。', '917ba3b7140546ef_1266763241808833446_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3539, 'in fact', '/ɪn ˈfækt/', 'in fact.mp3', 'phr.事实上，实际上', '3_0_20170713071646_14740_c.jpg', '', 'In fact', '事实上，这是一只狗狗，而不是熊猫。', 'be9ba4f2af7f36d3_1266797979462097640_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3540, 'in general', '/ɪn ˈdʒenərəl/', 'in general.mp3', 'phr.总的来说', 'cffe4e248243da2865087c78d09d49d0_203154_1605179664.jpg', '', 'In general', '天鹅通常是白色的，但也有一些黑色的天鹅。', '4ba633c5721a8d1de023db6a4948087e_29198_1619322509.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3541, 'in itself', '/ɪn ɪtˈself/', 'in itself.mp3', 'phr.实质上', 'dd8118db98988408c5172c9f30ccedc2.jpeg', '', 'The problem in itself was not difficult', '这道题本身并不难，只是他计算的时候太粗心了。', '931fcce5d076f6cd6469412e5780c6cf.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3542, 'in order', '/ɪn ˈɔːrdər/', 'in order.mp3', 'phr.按顺序', '04bcf0cdee7cdd40ca20ba2781eb6833_67443_1701672782.jpeg', '', 'Customers will be served in order of arrival. Please wait.', '消费者按先来后到的顺序消费。请等候。', 'zxfwzzp8caelw2cwsupg2bb78lqphbxr.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3543, 'in order to', '/ɪn ˈɔrdər tu/', 'in order to.mp3', 'phr.为了，目的是', '3_0_20170721071425_98486_c.jpg', '', 'In order to drink the water', '为了喝到水，这只乌鸦叼来了许多小石头放进瓶子里。', '2618a1000f9dbf1c_1266883483434855186_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3544, 'in part', '/ɪn pɑrt/', 'in part.mp3', 'phr.在某种程度上', '54cd0a947cf414067e5bd2722dace075.jpeg', '', 'People\'s health is determined in part by what they eat and drink. ', '人们的健康在某种程度上取决于他们的饮食。', 'ad74f4d8b873a107a131c80b8728aee7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3545, 'in the event of', '/ɪn ði ɪˈvent əv/', 'in the event of.mp3', 'phr.如果发生', '7d901cf67ea9cc0fa43d86dd83045738.jpeg', '', 'In the event of a fire', '如果发生火灾，请用灭火器灭火。', '7c7d34a81bc19befe2fc51ae86122b1c.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3546, 'Indian', '/ˈɪndiən/', 'Indian.mp3', 'adj.印度的；印第安人的；  n.印第安人', '1462b96204b6c20de6c63aeda6e870ce_86652_1577953766.jpeg', 'd_109_17626_0_2_20150809062343.png', 'Indian clothing and jewelry are very beautiful.', '印度的服饰和珠宝非常漂亮。', '7gst27rejcvyqysvp9jlqskzynj6qts2.mp3', 'India印度 + n表示人 → Indian印度人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3547, 'inferior', '/ɪnˈfɪriər/', 'inferior.mp3', 'adj.（等级、地位等）低等的；低劣的；  n.部下，地位低的人；次品', 'fd5132c8d0c09f3c583f83c9ae16815a_105110_1522825839.jpg', 'd_1_5259_0_2_20150808123717.png', 'He makes me feel I\'m inferior to him.', '他让我感觉在他面前低人一等。', 'd22bc27be1d62d9f_1266883529732676244_250207.mp3', 'infer推断 + ior表形容词，较…的 → 轻易推断出的 → inferior低下的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3548, 'injure', '/ˈɪndʒər/', 'injure.mp3', 'v.伤害，使受伤', 'f91f4e953ee1c4c731a2dfc2d5f8bfa1_84807_1533095220.jpeg', 'd_16_6128_0_5_20150808230159.png', 'The worker injured himself at the construction site.', '这名工人在工地上受伤了。', 'f0fb1997fa60e0ad_1266883194852715504_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3549, 'inquiry into', '/ˈɪnkwəri ˈɪntuː/', 'inquiry into.mp3', 'phr.对……的调查', 'd184566c177dee0a844f023d0f57861c.jpg', '', 'The customer service is making an inquiry into a problem.', '客服正在对一个问题展开调查。', 'a0366303831ec82970bb5d3fcf0875c5_47744_1593586643.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3550, 'insure', '/ɪnˈʃʊr/', 'insure.mp3', 'v.为……投保', 'i_101_6827_0_3_20150809035405-gigapixel-scale.jpg', 'd_107_6827_0_2_20150809021011.png', 'I insure my car against accident and theft.', '我为我的车上了事故险和偷盗险。', 'sa_101_6827_0_3_20150809035405.aac', 'in进入 + sure肯定 → 进入肯定 → 保险', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3551, 'introduction', '/ˌɪntrəˈdʌkʃn/', 'introduction.mp3', 'n.介绍；引进', '4795467bad5f30225e568e4dbb69dbf6_370501_1701068428.jpg', 'd_94_13151_0_4_20150809010051.png', 'She was making an introduction of her new friend.', '她在介绍自己的新朋友。', 'us_She_was_20231127150032653_4c4898b49c7082847bc8.mp3', 'intro向内，入内 + duc引导 + tion名词后缀，表状态 → 引进的行为 → introduction介绍；引进', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3552, 'isolate', '/ˈaɪsəleɪt/', 'isolate.mp3', 'v.使隔离；使孤立；  adj.孤立的；单独的', '0d8dd5fedd51b4d2c76e5fe8b6b24737_36771_1584087027.jpeg', '20141009_02_36_14_95_v3.png', 'The old man built a huge fence to isolate himself from his neighbors.', '老人筑起了一道巨大的篱笆，将自己与邻居隔绝开来。', 'b8e0e58e5d42804e2892252d8bec08e7_48372_1584087025.mp3', 'isol岛 + ate表动词 → 使成为岛 → 孤立', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3553, 'Japan', '/dʒəˈpæn/', 'Japan.mp3', 'n.日本', '6eb4b26df20adfc4f1086eaf24e1627d_108444_1541842054.jpg', 'd_24_17500_0_3_20150808232853.png', 'In Japan', '在日本，我们可以看到美丽的富士山。', 'uf4quvgf8d8bbm7pjm5sak668kbbxw5z.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3554, 'journal', '/ˈdʒɜːrnl/', 'journal.mp3', 'n.日志，日记；定期刊物，杂志', 'i_1_7846_0_3_20150808130050-gigapixel-scale.jpg', 'd_107_7846_0_2_20150809022255.png', 'The man writes everything down in his journal.', '这个人把发生的事情都记在日记里。', 'ef7vfgvp7dgkqj74b6zlcnkapmr6hrkl.mp3', 'journ日期 + al名词后缀 → 带有日期的读本 → journal日期，杂志', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3555, 'ladder', '/ˈlædər/', 'ladder.mp3', 'n.梯子', 'i_13_8950_0_5_160405151318-gigapixel-scale.jpg', '20141015_16_13_58_325_v3.png', 'I climbed up the ladder to change the light bulb.', '我爬上梯子换灯泡。', '799c1a239e97eac6_1266798145375415262_250123.mp3', 'lad倚靠 + der名词后缀 → 倚靠放置的东西 → ladder梯子', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3556, 'learned', '/ˈlɜrnɪd/', 'learned.mp3', 'adj.博学的（读作/ˈlɜrnɪd/）；有学问的', '796e27c7901a71aef6c8cbdecb1a2e0f_65335_1656927653.jpg', 'd_107_5054_0_2_20150809011423.png', 'The man on the stage is a well-learned professor.', '站在台上的是一名学识渊博的教授。', 'us_The_man_20220704174100569_7a1a77616950c435d670.mp3', 'learn学习 + ed形容词后缀 → learned有学问的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3557, 'let off', '/let ɔːf/', 'let off.mp3', 'phr.宽恕', 'b07f0ae8e5f24e57c52150d9ac40a10c.jpg', '', 'Although he was naughty in the mall', '虽然他在商场里很闹腾，但他的爸爸这次没有生气。', 'f301462459700630_1266883538343996368_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3558, 'like', '/laɪk/', 'like.mp3', 'prep.像', '986879189b261ef660b0b2a2e2c21c4f.jpeg', 'd_102_13282_0_4_20150809042321.png', 'He looks like his father.', '他看起来像他爸爸。', 'b4130207967f8f48_1266763242753862594_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3559, 'limit to', '/ˈlɪmɪt tuː/', 'limit to.mp3', 'phr.限制，限定', '064f0ef6feb1d19329dcff1703b2c4c2.jpeg', '', 'Cars are limited to 60 km/h on this road.', '此路段的车速限制为每小时60千米。', '2afd432c8f543474a8367f49be2e018d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3560, 'line', '/laɪn/', 'line.mp3', 'n.线，线条', '0a72f9a9701933e41b087f2b58e5b7f7_87925_1574841882.jpeg', 'd_24_17947_0_3_20150808233648.png', 'There is a yellow line in the middle of the road.', '道路中间有条黄线。', '3026db064ae58114657a76b3ed1fdfb1_29182_1574841879.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3561, 'lion', '/ˈlaɪən/', 'lion.mp3', 'n.狮子', '4c32b837e37d85e6a780ac99f46cdee3_97998_1577954118.jpeg', '20141013_23_19_20_964_v3.png', 'The lion is standing proudly', '这头狮子面向太阳骄傲地站着。', 'f3g3w7tesr5qq4tl7kcgppb5n3rd3e92.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
