INSERT INTO `words` VALUES (3563, 'major in', '/ˈmeɪdʒər ɪn/', 'major in.mp3', 'phr.专攻', '7b94a187962727c3fdf927ccfc02ac51_116176_1722830038.jpg', '', 'I major in mathematics.', '我学数学专业。', '8e04fd8f21499c6ddb281e1cc21f51df_27151.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
