INSERT INTO `words` VALUES (3565, 'menu', '/ˈmenjuː/', 'menu.mp3', 'n.菜单', '5b9e7d7f282a5dd459233cf6c75ab17b_147778_1744270715.jpg', 'd_24_17027_0_3_20150808231938.png', 'The boy is looking at the menu to choose which dessert to order.', '这个小男孩在看着菜单，选择该点哪个甜品。', 'us_The_boy_20220422183248237_6a6abbac7a910cb6f075.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3566, 'merit', '/ˈmerɪt/', 'merit.mp3', 'n.优点；价值；功绩；  v.值得；应得', '3752ff83a28b2e784f9e3ca0b91c821b_188945_1569576957.jpeg', 'd_1_4203_0_3_20150808122527.png', 'A merit of this phone is that the excellent camera can clearly capture the moon.', '这款手机的优点之一是它出色的拍照功能可以清晰地捕捉月亮的样子。', 'ede7064517fb48d441828a86acafcf2c_47038_1569576954.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3567, 'meter', '/ˈmiːtər/', 'meter.mp3', 'n. 米（=metre）；计，表，仪表', '3_0_20170723071410_74295_c-gigapixel-scale.jpg', 'd_109_8255_0_2_20150809055450.png', 'A hundred centimeters is equal to one meter.', '一百厘米即一米。', '3_0_20170723071410_48405_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3568, 'midnight', '/ˈmɪdnaɪt/', 'midnight.mp3', 'n.子夜，午夜；午夜蓝', 'f398ebc2516af3b378da83c25fdcc4c1_80019_1591869189.jpg', 'd_24_6268_0_4_20150808224543.png', 'When the clock shows 12 at night', '当时钟在晚上显示12点时，那便是午夜。', 'ayvj838vregcs3awj8skgd7r4m9er9tr.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3569, 'military', '/ˈmɪləteri/', 'military.mp3', 'adj.军事的；  n.军队', 'c1a600ad51bc12c287ecc5e81555ebcb_147064_1568272596.jpeg', 'd_49_13422_0_4_20150809013830.png', 'University freshmen are required to participate in military training.', '大学新生要参加军训。', '2a77973d2e4694ea6fae2a2d7724e56e_41638_1591778997.mp3', 'milit兵 + ary……的 → military军人的，军队的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3570, 'mind', '/maɪnd/', 'mind.mp3', 'n.头脑，思想，心智；  v.注意；记住', 'i_13_17239_0_2_20150808204628-gigapixel-scale.jpg', '5c4465e9ea0bb6673112e8f0da417565_55634_1539341395.png', 'Here\'s a hard question for you: Are your mind and your brain the same thing?', '问你一个难题：你的思想和你的头脑是同一个东西吗？', 'sa_13_17239_0_2_20150808204628.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3571, 'modify', '/ˈmɑːdɪˌfaɪ/', 'modify.mp3', 'v.更改，改造', '3c158f403b4f541cf97b27a21303f41b_53715_1565279738.jpg', '20141010_16_02_01_350_v3.png', 'This car has been modified to make it even faster.', '这辆车已经被改装过，以便它跑得更快。', 'sa_1_6576_0_4_20150808125232.aac', 'mod方式，模式 + ify…化 → 规范化 → modify修改', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3572, 'naked', '/ˈneɪkɪd/', 'naked.mp3', 'adj.裸体的，无遮蔽的', '8ca86d69f755b15c53af9a917cc06af9_88009_1538639556.jpg', 'd_1_6326_0_3_20150808125017.png', 'The naked baby is crawling and smiling on the floor.', '那个光着身子的婴儿正在地上边爬边笑。', 'fea155f4288d44640b22a58c0c3c1753_16346_1538639563.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3573, 'noise', '/nɔɪz/', 'noise.mp3', 'n.噪声，吵闹声', '52ee1e0074c7e81bec7ac0fa5450894b_99224_1595315231.jpg', 'd_24_15993_0_4_20150808230952.png', 'The machines outside are making a loud noise.', '外面的机器发出了巨大的噪声。', 'xggv9wy6hsvullras2tp38qh84lvqhtt.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3574, 'noisy', '/ˈnɔɪzi/', 'noisy.mp3', 'adj.喧闹的；嘈杂的', 'i_1_5236_0_4_151010164606-gigapixel-scale.jpg', 'd_24_5236_0_3_20150808224031.png', 'It\'s so noisy outside. I can\'t stand this kind of environment!', '外面太吵了。我受不了这样的环境了！', '94ae4db4786b24fa_1266763524060961368_250117.mp3', 'nois=noise喧闹 + y形容词后缀 → noisy喧闹的，嘈杂的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3575, 'occupation', '/ˌɑkjuˈpeɪʃn/', 'occupation.mp3', 'n.职业，工作', 'i_1_6200_0_3_20150808124823-gigapixel-scale.jpg', 'd_16_6200_0_5_20150808230351.png', 'These people have different occupations.', '这些人有不同的职业。', '969arl4p3bwjn5wqcgw74ds82umbuc76.mp3', 'oc表强调 + cup拿，抓，握住 + ation表名词 → 占领，占据；职业', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3576, 'occur', '/əˈkɜːr/', 'occur.mp3', 'v.发生', 'i_1_3889_0_2_20150808122018-gigapixel-scale.jpg', 'd_107_3889_0_2_20150809003331.png', 'Car accidents usually occur very quickly.', '车祸通常发生在一瞬间。', '62c8dd1a06ddf8eb_1266883482899557124_250207.mp3', 'oc向 + cur 跑 → 某个方向跑 → occur发生', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3577, 'odd', '/ɑːd/', 'odd.mp3', 'adj.奇怪的；古怪的；奇数的', '50ee8018bf8d6e19720c8a13dbd313dc_143214_1710210551.jpeg', 'd_1_5680_0_2_20150808124218.png', 'It\'s odd that the wolf simply jumps over the lamb instead of eating it.', '奇怪的是，狼只是从羔羊身上跳过，没有吃掉它。', 'gvnsa3lvhg4xsfvgancjeefew238xlc4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3578, 'offend', '/əˈfend/', 'offend.mp3', 'v.冒犯', '7a33320e2a0747c0f785d684401e56cf_58090_1731407184.jpg', 'cec5dfd2cd3e663755d2c64ef959c355_24408_1551253070.png', 'Comments from online haters offended her.', '网络喷子的言论冒犯了她。', 'us_Comments_from_20241112182631961_50d787de6c72b1325d64.mp3', 'of反对 + fend打击 → 一再打击 → offend冒犯，得罪', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3579, 'on the road', '/ɑn ði rəʊd/', 'on the road.mp3', 'phr.在旅途中，上路', '61c33bb20ccf3803703665f8aeb56ab8.jpeg', '', 'He just wanted a new car so he could get back on the road.', '他只想要一辆新车以便重新上路。', '05d6bb0bc614fac8199a615131683913.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3580, 'orientation', '/ˌɔːriənˈteɪʃn/', 'orientation.mp3', 'n.定向，方向', 'f5efe2b7492a27876de5947e5e57b825_38933_1654164113.jpg', '', 'A clear orientation is important for the development of a company.', '一个明确的方向对公司发展至关重要。', 'us_A_clear_20220602180157109_a655ff6c254ed6335522.mp3', 'orient东方 + ation名词后缀 → 向东方 → orientation定位', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3581, 'out of date', '/aʊt əv deɪt/', 'out of date.mp3', 'phr.过时', '36dd39543491925511099c373d0e5c6e_64885_1605181178.jpg', '', 'The big heavy phone is out of date.', '又大又笨重的手机已经过时了。', 'sa_37_20142_0_3_20150809012504.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3582, 'owe', '/oʊ/', 'owe.mp3', 'v.归功于；欠（债、情）；欠钱', 'd7f38f1eab6cee2abfca22a6172adc8c_175061_1582269381.jpg', 'd_16_7244_0_2_20150808231641.png', 'I owe my full mark to this phone app!', '我把我的满分归功于这个手机应用！', 'lyys3fwyymhhpyfuqt5daed6crplbddu.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3583, 'passion for', '/ˈpæʃn fɔːr/', 'passion for.mp3', 'phr.对……热爱', '00f412f6b1b29d15d64f504fd08f6ede.jpg', '', 'She got a passion for playing the guitar.', '她对弹奏吉他有一份热爱。', 'd71e8033b10e3b27fe840aee77ffc048_36512_1593586334.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3584, 'period', '/ˈpɪriəd/', 'period.mp3', 'n.时期', '1188c556513f9646179b8b67dd67d672_189848_1578561236.jpeg', 'd_24_17671_0_3_20150808233246.png', 'He became a math teacher over a period of four years.', '他花了四年的时间成了一名数学老师。', '047ce05d6a0d6f4316b64b0b38923c69_45598_1578561233.mp3', 'peri周围，靠近 ＋ od道路 → period周期', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3585, 'permanent', '/ˈpɜːrmənənt/', 'permanent.mp3', 'adj.永久的，永恒的', 'ba9ae95fca745c932cd95db0e9ee0643_91719_1706779106.jpg', 'd_16_8973_0_2_20150808233642.png', 'The love between them was permanent', '他们之间的爱情是永久的，经得起时间的考验。', 'huvr9r8gw4pwrlts7m6y4r6mbqsyu8z7.mp3', 'per贯穿，自始至终 + man留住 + ent形容词后缀 → 永久留住 → permanent永恒的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3586, 'permissible', '/pərˈmɪsəbl/', 'permissible.mp3', 'adj.容许的；许可的', '98d41f9b4f1ef357a22d8efb73bf2c63_87507_1731997393.jpg', 'd_106_2066_0_2_20150809064408.png', 'Smoking is permissible in this area.', '该区域允许吸烟。', 'us_Smoking_is_20241119142316538_ed595038e818456cf4fb.mp3', 'permiss=permit允许 + ible形容词后缀 → permissible可允许的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3587, 'persist', '/pərˈsɪst/', 'persist.mp3', 'v.坚持，固执；继续留存', '1ec99a4a4844ce46a0c277fa43c4418e_66871_1565705498.jpg', '20130301_12_57_45_883.png', 'Although the water is cold', '尽管水很凉，我们还是坚持前进。', '943781421b4431ac_1266883375308647244_250207.mp3', 'per贯穿，自始至终 + sist站 → 站到最后 → persist坚持', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3588, 'philosophy', '/fəˈlɑːsəfi/', 'philosophy.mp3', 'n.哲学，哲学体系', '19c7d8aa36c77cd99fa608ee2da182cf_63765_1730369707.jpg', 'd_1_7830_0_2_20150808130040.png', 'I often think about the meaning of life and other questions of philosophy.', '我常常思考生命的意义以及其他哲学问题。', 'sa_1_7830_0_2_20150808130040.aac', 'philo爱 + sophy智慧 → 爱与智慧 → philosophy哲学', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3589, 'physical', '/ˈfɪzɪkəl/', 'physical.mp3', 'adj.身体的，肉体的；  n.体格检查', 'c081c710924b5e1a4ef4a2411eb3cc67_171857_1738912536.jpeg', '7394966b9eb68b4eeb4f3f509b7edb58_48867_1539341341.png', 'Physical exercise is good for your body and mind.', '体育锻炼有益于你的身心健康。', '67908fc75ea5ad7910dfcc4344f62586_19011_1625728007.mp3', 'physic自然，自然科学 + cal表形容词 → 大自然中本身就存在的 → physical身体的，物理的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3590, 'pity for', '/ˈpɪti fɔr/', 'pity for.mp3', 'phr.同情，怜悯', '62051ce119d4ee88dbe7177c8008a5a4.jpg', '', 'They felt pity for the crying little girl.', '他们同情那个哭泣的小女孩。', '7dabb0b1fa1eee3ab3dd8184d2f6d4cf_42272_1593586120.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3591, 'plot', '/plɑːt/', 'plot.mp3', 'n.情节；  v.密谋', '057e229415c49c7fa39a9588e1c33464_126421_1729823696.jpg', 'd_16_4047_0_2_20150808223950.png', 'She is crafting a romantic plot for her story.', '她正在为故事构思一个浪漫的情节。', '7n5a5fyj6uxb2q75dj8u4z6b7x7az7tt.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3592, 'pond', '/pɑːnd/', 'pond.mp3', 'n.池塘', 'b2ef07c07932dd25fca520de647ff7ce_101266_1535525082.jpeg', 'd_24_8447_0_3_20150808225729.png', 'The duck dived into the pond.', '鸭子一头扎进了池塘。', 'n365dudkjuhqucd9bhbtefxmwfqbtnex.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3593, 'pour', '/pɔːr/', 'pour.mp3', 'v.注，倒，灌；下（雨）', 'i_24_5948_0_5_151222151801-gigapixel-scale.jpg', 'd_24_5948_0_3_20150808224405.png', 'The milk is being poured into the glass.', '牛奶正被倒进玻璃杯里。', '6amujuf9dkhu4e8yrqw8hhsfwr7v88b3.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3594, 'practise', '/ˈpræktɪs/', 'practise.mp3', 'v.练习', '11939db281691234f7c8b8137380be6d_129259_1737957670.jpg', 'd_16_6710_0_2_20150808230956.png', 'You had better practise for your big fight tomorrow!', '你最好为明天的大决战练习。', '34f5b6cabae164b7_1266883369521142392_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3595, 'preceding', '/prɪˈsidɪŋ/', 'preceding.mp3', 'adj.在前的，在先的', '3_0_20170928071519_19953_c-gigapixel-scale.jpg', 'd_107_16316_0_2_20150809025708.png', 'Click this button to browse the preceding text.', '点击这个按钮以浏览前文。', '3_0_20170928071519_11665_c.aac', 'pre预先 + ced走 + ing形容词后缀，…的 → preceding在前的，在先的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3596, 'predict', '/prɪˈdɪkt/', 'predict.mp3', 'v.预言，预告，预测', '333899ac61a6f046e535f5a0fc16c29f_190793_1561953236.jpg', 'd_16_6254_0_2_20150808230445.png', 'He predicted this stock would experience an increase in a few days.', '他预测该股票过几天会涨。', 'dytgew6dqxt88w4qcz47b47encx7duz6.mp3', 'pre…前的，预先 + dict说 → 预先说 → 预言', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3597, 'prime', '/praɪm/', 'prime.mp3', 'adj.首要的，主要的；最好的，一流的；  n.青春，全盛期，青壮年时期', 'i_1_4763_0_7_151009181142-gigapixel-scale.jpg', 'd_1_4763_0_3_20150808123008.png', 'Our prime task is to reduce the pollution', '“我们的首要任务是减少污染。” 市长说道。', 'sa_1_4763_0_3_20150808123008.aac', 'prim第一，主要的 + e → prime首要的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3598, 'priority', '/praɪˈɔːrəti/', 'priority.mp3', 'n.优先考虑的事', 'fd57e517695556e9260239406d079c0f_57811_1562142090.jpeg', 'd_107_7493_0_2_20150809022002.png', 'These priority seats are reserved for the elderly', '这些优先座位是留给老年人、残疾人和孕妇的。', 'f2383f9a6876668cc8a1e7028c02c5c0_49512_1562142094.mp3', 'prior优先 + ity名词后缀 → priority优先（权），重点', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3599, 'prize', '/praɪz/', 'prize.mp3', 'n.奖品，奖励；  adj.得奖的；  v.珍视', 'i_24_16007_0_5_151221175524-gigapixel-scale.jpg', 'd_24_16007_0_3_20150808231027.png', 'Finally', '最终，他获得了一等奖。', 'us_Finally_he_20230526181657600_4998e4eb859f2d4788f8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3600, 'procession', '/prəˈseʃn/', 'procession.mp3', 'n.队伍，行列，列队行进', 'i_1_2125_0_4_151019104243-gigapixel-scale.jpg', 'd_103_2125_0_3_20150809002145.png', 'The procession of these yellow chickens seems endless.', '这支由小黄鸡组成的队伍看起来没有尽头。', 'sa_1_2125_0_4_151102165444.aac', 'pro 向前，在前 + cess 行走，前进 + ion 表示行为、过程或结果 → n.队伍，行列', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3601, 'professional', '/prəˈfeʃənl/', 'professional.mp3', 'adj.职业的；  n.专业人员', 'd2ff1d54179df67e62e73aa38af535c5_62682_1565281825.jpg', 'd_107_8111_0_2_20150809022820.png', 'My parents want me to have a professional career', '父母希望我步入职业生涯，但是我应该选哪个职业呢？', 'f9ceab73b06c98a1_1266883376026442360_250207.mp3', 'profession职业 + al……的 → professional职业的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3602, 'profitable', '/ˈprɑːfɪtəbl/', 'profitable.mp3', 'adj.有利润的', '1426083460411-gigapixel-scale.jpg', '', 'Planting trees can be a profitable investment into your future.', '种植树木是一项对你的未来有利的投资。', 'sa_9_2136_0_2_20150808143325.aac', 'pro前 + fit做，制作 + able能...的 → 能提前做好的 → profitable有利润的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3603, 'programme', '/ˈproʊɡræm/', 'programme.mp3', 'n.节目，电视节目；活动安排；  v.编制程序；安排节目', 'ba497fb46d6b3a3bb057aff7f640c7d6_113223_1701667672.jpg', '', 'The whole family is watching its favourite TV programme.', '所有的家庭成员一起看着他们最爱的电视节目。', '9a492b063bfba24f_1266763526456126378_250117.mp3', 'pro很多 + gram写 + me → programme程序，编程', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3604, 'protest', '/ˈprəʊtest/', 'protest.mp3', 'v.抗议；反对（读作/proʊˈtɛst/）；  n.抗议（读作/ˈproʊˌtɛst/）', 'ffbda6d296e9353625c3191c87fa5438_160469_1538658848.jpg', '', 'Raising fists and flags is a symbol of protesting something.', '举起拳头和旗帜是抗议的一种标志。', '7887f1c4a8af6352d01b091644dbc5e0_18854_1538658861.mp3', 'pro在前面 + test证据 → 向前作证 → protest抗议，坚决声明', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3605, 'pull on', '/pʊl ɑːn/', 'pull on.mp3', 'phr.穿', '4071fb2257ca5389c3d0c71d3cec08b0_126861_1620813440.jpg', '', 'He pulled on his jeans and ran downstairs to answer the door.', '他穿上牛仔裤跑下楼去开门。', 'ad3106c8ae79ff2b741a597c21041948_55551_1599537618.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3606, 'punctual', '/ˈpʌŋktʃuəl/', 'punctual.mp3', 'adj.准时的，守时的', 'i_1_8975_0_6_151009142058-gigapixel-scale.jpg', '20141013_22_42_34_353_v3.png', 'I\'m always punctual; I\'m never late for work.', '我总是很守时，上班从来不迟到。', 'aca67f2a5cf2acc1_1266883372863150822_250207.mp3', 'punct点 + ual…的 → 总能踩准点的 → punctual严守时刻的；准时的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3607, 'quarrel', '/ˈkwɔːrəl/', 'quarrel.mp3', 'n.争吵，口角；  v.争吵，争论', 'c60f76531bd2d7a0f02e2103c6a335e6_271472_1710503243.jpg', 'd_24_7165_0_4_20150808225026.png', 'A heated quarrel arose when the couple realized they\'d both forgotten their keys.', '两个人都忘带钥匙，这对情侣大吵了一架。', 'us_A_heated_20240315183330465_4b096e6c9c20ae3054e7.mp3', 'quarr=quer抱怨 + el人，集体 → 几个人同时抱怨对方的不好 → quarrel争吵', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3608, 'ray', '/reɪ/', 'ray.mp3', 'n.光线；射线；  v.放射，照射', 'adc99255feb68e9cd55c6dc8a56ca314_95051_1579594642.jpeg', 'd_16_6237_0_2_20150808230434.png', 'Part of the sun\'s rays are blocked by clouds.', '一部分太阳光线被云层挡住了。', 'c2d65267d192c27f6b96305135ac0d91_45166_1579594640.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3609, 'ready', '/ˈredi/', 'ready.mp3', 'adj.准备好的；现成的；  v.预备，准备', '4969e3128e3012e23ca406d8c47a68f8_91428_1577955701.jpeg', 'd_95_13913_0_4_20150809012832.png', 'He is ready to run.', '他准备好起跑了。', '5mjaed8ccwhcsk93ytwtmj5pext9ctfp.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3610, 'realistic', '/ˌriːəˈlɪstɪk/', 'realistic.mp3', 'adj.现实主义风格的；现实主义的', 'e32e023dffa49e1ad068f1e6eff493d3_136291_1559025332.jpeg', '66a5c00e733269288cf0714d5994ea24_31620_1570502778.png', 'Wow! What a realistic painting!', '哇！多么逼真的一幅画啊！', '67a968a69cdbd5200b31128fd9859a1b_27282_1559025336.mp3', 'real真的 + istic...的 → 逼真的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3611, 'reflection', '/rɪˈflekʃən/ ', 'reflection.mp3', 'n.映像', 'i_1_5853_0_3_20150808124520-gigapixel-scale.jpg', 'd_1_5853_0_3_20150808124520.png', 'The reflection the cat saw in the mirror was not itself', '猫咪在镜中看到的映像不是它自己，而是一只狮子。', 'us_The_reflection_20250113132548501_38d55dd8b5c6ea181f52.mp3', 're反 + flect弯曲 + ion名词后缀 → reflection反射；思考', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3612, 'refreshment', '/rɪˈfreʃmənt/', 'refreshment.mp3', 'n.茶点；（会议或旅行期间提供的）饮料，点心', '9324476c92b32bdc1bff0bbcebd87db9_179035_1564799609.jpg', 'd_107_9989_0_2_20150809024857.png', 'Feel free to enjoy the refreshments on the table that we prepared for you.', '请尽情享用桌上我们为您准备的茶点。', 'ec480701302bb6c15c85add9fc986557_49221_1564799588.mp3', 're再 ＋ fresh清新的 ＋ ment表物 → refreshment茶点', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3613, 'relative to', '/ˈrelətɪv tu/', 'relative to.mp3', 'phr.相对于，与……相比', 'd17999a1a2918909790fd7bf504faba7.jpeg', '', 'The company seems to have employed too many people relative to the size of its business. ', '相对于其规模，该公司似乎雇佣了过多员工。', '28321635ac7a20a745e65c289154dcc7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3614, 'remark', '/rɪˈmɑːrk/', 'remark.mp3', 'n.评论；谈论；  v.议论；评论', '6087724812febbb5e000958db8134010_163996_1573627815.jpeg', 'd_16_5146_0_4_20150808225039.png', 'The man got different remarks.', '这个人得到了不同的评论。', 'c81805255fa58adc13005e7c8096eb27_11331_1648605883.mp3', 're再 + mark记号，符号 → 再做记号 → remark评点，评论', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3615, 'reply to', '/rɪˈplaɪ tuː/', 'reply to.mp3', 'phr.答复，回答，回复', 'c89172e0d49f0fedca42e767ba5adb49.jpeg', '', 'She started replying to her pen pal.', '她开始给笔友回信。', '26252d2c6437fb6ae7f51aca1fa7d6ed_43438_1600072726.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3616, 'request', '/rɪˈkwest/', 'request.mp3', 'n.（正式或礼貌的）请求；要求；  v.请求，要求；要求，请求', '40f6cc16d6f25340efa3d150c5ff7f7e_83515_1584685037.jpeg', 'd_16_5650_0_2_20150808225633.png', 'His father agreed to his request for a Superman costume.', '他父亲同意了他想要一套超人服装的请求。', 'us_His_father_20250319152817966_453718d99d2bc413e6b8.mp3', 're再 + quest寻求，询问 → 再寻求 → request要求', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3617, 'resign to', '/rɪˈzaɪn tuː/', 'resign to.mp3', 'phr.顺从', '4a39158b2a94c2f135e3d7a5cc4543af.jpeg', '', 'To practice social distancing', '为了实行社交隔离，他只好安于独自在家看球赛。', '9b810850f874fb74a6ca89d77110f36e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3618, 'response', '/rɪˈspɑːns/', 'response.mp3', 'n.响应；回应；回答，答复', '3_0_20160720071759_12947_c-gigapixel-scale.jpg', 'd_1_9905_0_2_20150808131513.png', 'The students raised their hands in response to the teacher\'s question.', '同学们举起手来回答老师的提问。', '3_0_20160720071759_92667_c.aac', 're回，向后 + sponse承诺 → response回答；答应', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3619, 'rubbish', '/ˈrʌbɪʃ/', 'rubbish.mp3', 'n.垃圾，废物', 'i_13_17643_0_3_20150808204904-gigapixel-scale.jpg', '20121225_19_32_16_269.png', 'Please put your rubbish in the bag.', '请把你的垃圾放在这个袋子里。', 'mgnfj9vfk4pt6bkq42ps6jqngqndhkb5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3620, 'scholarship', '/ˈskɑːlərʃɪp/', 'scholarship.mp3', 'n.奖学金；学问', '1262fbda1b0b490be36d82d32fd90d2e_36335_1706146858.jpg', 'd_105_9018_0_2_20150809061229.png', 'She is an excellent student so she gets the scholarship every year.', '她是一位优秀的学生，所以每年她都能得到奖学金。', '11962671b04abbeb_1266883492971784964_250207.mp3', 'scholar学者 + ship表名词 → scholarship学问，学识', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3621, 'science', '/ˈsaɪəns/', 'science.mp3', 'n.科学', 'e9d0e56da4593bfa6ff675a6d9381ee2_105556_1595314228.jpeg', 'd_24_4954_0_4_20150808223716.png', 'Physics and Chemistry are two different areas of science.', '物理和化学是科学的两个不同领域。', '066e74ac03ac3fe0_1266883001786674166_250207.mp3', 'sci知道 + ence名词后缀 → science科学；学科', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3622, 'see to', '/siː tu/', 'see to.mp3', 'phr.负责', '9d7ed5806a3312fd534cb1fbc9d204db.jpeg', '', 'He saw to the luggage while his girlfriend checked in at the hotel.', '他负责处理行李，他的女朋友则去酒店办理入住。', '88fe2f40e4372d7d_1266883480382778288_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
