INSERT INTO `words` VALUES (3625, 'sight', '/saɪt/', 'sight.mp3', 'n.视力', 'i_13_15944_0_2_20150808203604-gigapixel-scale.jpg', 'd_24_15944_0_4_20150808230926.png', 'My dog\'s sight is better with these binoculars.', '用了望远镜，我的狗视力更好了。', 'dba4ce6491cf2558_1266883490904234728_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3626, 'slave', '/sleɪv/', 'slave.mp3', 'n.奴隶；  v.奴隶般地工作，苦干', '4b33a31cba9dd032e43f9f5046bd128f_111642_1522662958.jpg', 'd_16_17211_0_2_20150809005106.png', 'Some people believe that the slaves of Egypt were forced to carry heavy bricks.', '有些人认为埃及的奴隶是被迫搬运沉重砖块的。', 'us_Some_people_20250807165626526_1b8cd6547a7a8d397de9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
