INSERT INTO `words` VALUES (3628, 'spoil', '/spɔɪl/', 'spoil.mp3', 'v.溺爱；毁坏；  v.（食物）变质', 'i_1_5342_0_4_151225141806-gigapixel-scale.jpg', 'd_24_5342_0_4_20150808224043.png', 'The grandparents spoil their grandchild by doing everything for him.', '爷爷奶奶太宠他们的孙子了，恨不得替他把所有事都做了。', 'sa_1_5342_0_4_160104163035.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
