INSERT INTO `words` VALUES (3633, 'sufficient for', '/səˈfɪʃnt fɔːr/', 'sufficient for.mp3', 'phr.足够', '4d1db0474940abfc6a96c4f3ac52c3c8.jpg', '', 'The food in the fridge is sufficient for us to eat.', '冰箱里的食物足够我们吃了。', 'a0245b726d60391c7b7740b06fbbbd66_40736_1593575869.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
