INSERT INTO `words` VALUES (3636, 'technique', '/tekˈniːk/', 'technique.mp3', 'n.技巧，技能；技术，方法', '264a9ade684d558b48bed2dfe52c5481_192075_1573801311.jpeg', 'd_105_5575_0_2_20150809054840.png', 'The musician combines different techniques in the performance.', '这位音乐家在表演中结合了不同的技巧。', '5d820df731492002ea4f29d295aff8fd_38786_1573801308.mp3', 'techni技术 + que后缀 -> 技术', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3637, 'temperature', '/ˈtemprətʃər/', 'temperature.mp3', 'n.温度；气温', 'b3655ee6a9ccf03b8c87488f7c6b0f9e_10057_1597373693-gigapixel-scale.jpg', 'd_97_14493_0_5_20150809015921.png', 'The temperature of my phone is high enough to cook eggs.', '我的手机温度好高，都可以煎蛋了。', 'fde365c8e741ecca_1266763401329466110_250117.mp3', 'tempera克制自己 + ture名词后缀 → 可管控自己的 → temperature气温；体温', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3638, 'terrible', '/ˈterəbl/', 'terrible.mp3', 'adj.非常严重的，糟糕的；病得很重的，心情很糟的', '4dc5a451408967b8e955777a9a4a1313_178301_1536130721.jpeg', 'd_95_14503_0_4_20150809012903.png', 'Thousands of eggs were broken in the terrible traffic accident.', '在这场严重的车祸中，数以千计的鸡蛋碎了。', 'rdmh328nhj6qs59ms58dxtzgtwzpzdh2.mp3', 'terr怕 + ible…的 → terrible可怕的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
