INSERT INTO `words` VALUES (3641, 'trip', '/trɪp/', 'trip.mp3', 'n.旅行，旅游；  v.绊倒，失足', 'i_16_18119_0_4_151222174411-gigapixel-scale.jpg', 'd_24_18119_0_4_20150808234741.png', 'He is going to make a trip by plane.', '他打算坐飞机去旅行。', '049f0ee6464b045c_1266763556843268914_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
