INSERT INTO `words` VALUES (3644, 'unhealthy', '/ʌnˈhelθi/', 'unhealthy.mp3', 'adj.不健康的，对健康有害的', '663084243a822d95043b349aa1ed1a8f_171304_1590332267.jpg', 'd_16_17127_0_2_20150809004353.png', 'It is unhealthy to stay up late', '熬夜、抽烟、酗酒都是不健康的。', '5d32a136a5140ca12c77c61ecd542930_34229_1552531622.mp3', 'un不 + health健康 + y…的 → unhealthy不健康的，对健康有害的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
