INSERT INTO `words` VALUES (3670, 'block', '/blɑ:k/', 'block.mp3', 'v.阻挡，妨碍，阻塞；  n.街区；块状物；大楼，大厦；阻碍', '63396ff9f78e32bef4c3068563d3c2e6_84954_1535947191.jpeg', 'd_24_5663_0_4_20150808224244.png', 'The fallen tree blocks the way.', '倒下的树阻挡了去路。', 'd6ace4feb3529417334076ba83ecea9a_29041_1535947187.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
