INSERT INTO `words` VALUES (3672, 'born', '/bɔːrn/', 'born.mp3', 'v.出世（仅用于被动语态）；  adj.天生的', '23c99559f4e5254d465619d9ea5fa1f1_194379_1578568873.jpeg', 'd_24_15940_0_4_20150808230920.png', 'The couple were so happy when the baby was born.', '孩子出生时，夫妻俩非常高兴。', 'f47047c129d821d47bf5d83ff6edabad_36958_1578568869.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
