INSERT INTO `words` VALUES (3674, 'brochure', '/broʊˈʃʊr/', 'brochure.mp3', 'n.手册，小册子', '5af634a07927da61a4998ed9cf4adab4_189193_1742262257.jpg', 'd_24_373_0_4_20150808223117.png', 'Travel brochures contain many beautiful pictures.', '旅行手册里有许多漂亮的图片。', '3_0_20170701113342_39926_c.aac', 'broch刺，缝 + ure表名词 → 手册', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
