INSERT INTO `words` VALUES (3676, 'by virtue of', '/baɪ ˈvɜːrtʃuː əv/', 'by virtue of.mp3', 'n.凭借，依靠', '9c354cb96455a60cc28b24217e8cb239.jpg', '', 'By virtue of her outstanding acting', '她凭借精湛演技获得了奥斯卡最佳女演员奖！', '7bd21178bb8574d42aaa033e5bd26d33.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3677, 'cable', '/ˈkeɪbl/', 'cable.mp3', 'n.电缆；  v.发电报', 'i_1_6334_0_4_151019104313-gigapixel-scale.jpg', 'd_107_6334_0_2_20150809015644.png', 'Many birds are standing on the cables for a rest.', '许多小鸟正停在电缆上休息。', 'ej734gt46dlx5jbdb8gxqy666p7zeq9j.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3678, 'call at', '/kɔl æt/', 'call at.mp3', 'phr.短暂访问（某地）', '2057220a14c8e2da6e802040c5b92b7b.jpg', '', 'The teacher called at her student\'s home to talk with his parents.', '这位老师到学生家里拜访，和其家长进行了一番交谈。', '3568ce5002cec8d48f263336c30ce1d8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3679, 'centimeter', '/ˈsentəˌmiːtɚ/', 'centimeter.mp3', 'n.厘米（同centimetre）', '3_0_20170928071249_12740_c-gigapixel-scale.jpg', 'd_105_10299_0_2_20150809061710.png', 'This ruler measures objects in centimeters.', '这把尺子以厘米为单位来测量物体。', '3_0_20170928071249_90334_c.aac', 'centi百分之一 + meter计量，测量 → 用一米的百分之一来测量 → n.厘米(cm)', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
