INSERT INTO `words` VALUES (3681, 'chemist', '/ˈkemɪst/', 'chemist.mp3', 'n.化学家；药剂师', '948f980ba01fac79f0845fcd9d1325a7_70530_1617938309.jpg', 'd_24_14931_0_4_20150808230637.png', 'The chemist is working in a lab.', '化学家正在实验室里工作。', 'sa_13_14931_0_4_160328110108.aac', 'chem化学的 + ist表示人 → chemist化学家', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
