INSERT INTO `words` VALUES (3688, 'concern', '/kənˈsɜːrn/', 'concern.mp3', 'n.关心，关切；  v.感兴趣', '20f1b81daa9c49b467a0c62e0b9b8f79_162288_1541664117.jpeg', '', 'Hair loss is a real concern for her.', '脱发的确是她所担忧的问题。', '45b34b6d380762e6db28c8934871b223_30574_1569655114.mp3', 'con表强调 + cern区别 → 区分开，只关心自己的部分 → concern关系到', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3689, 'confine to', '/kənˈfaɪn tu/', 'confine to.mp3', 'phr.限制', 'c1ae268b51c0364010bbd96513c32b8d.jpg', '', 'The dog was confined to the circle.', '这条狗被限制在这个圈内活动。', '0b6143cf841d0ce93aa6605a25133dad.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
