INSERT INTO `words` VALUES (3691, 'consist in', '/kənˈsɪst ɪn/', 'consist in.mp3', 'phr.在于', '59c78906036a6329f3693e034fd0d926.jpg', '', 'The beauty of her music consists in its ability to comfort and encourage others.', '她的音乐之美在于能安慰和鼓励他人。', 'b965926bdc3f0fe9932910bb0089d2d5_33161_1621924665.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
