INSERT INTO `words` VALUES (3694, 'cool', '/kuːl/', 'cool.mp3', 'adj.凉的，凉爽的；  v.（使）冷却；变凉', '94275d4b5a9f77819fa4830c03d45545_110822_1541841020.jpg', 'd_55_12239_0_4_20150809001835.png', 'Washing face with cold water is so cool.', '用冷水洗脸特别凉爽！', 'cd74d48133e5c62503a32cbb82f158dd_13681_1541841061.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3695, 'correspondent', '/ˌkɔːrəˈspɑːndənt/', 'correspondent.mp3', 'n.通讯员，记者', 'c_i_wm_1425952581948-gigapixel-scale.jpg', 'd_105_671_0_2_20150809053021.png', 'After the earthquake', '发生地震后，这记者发回了第一手新闻。', 'sa_1_671_0_3_20150808121531.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3696, 'costly', '/ˈkɔːstli/', 'costly.mp3', 'adj.昂贵的；价值高的', 'fa939bc992dc754cd16cd9a184a2ee6a_145687_1731317077.jpg', 'd_1_6743_0_2_20150808125434.png', 'The diamond ring is quite costly.', '这枚钻戒相当昂贵。', 'us_The_diamond_20241111172511439_8ebc4f4035e477e99c5f.mp3', 'cost花费 + ly形容词后缀 → costly昂贵的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3697, 'craft', '/kræft/', 'craft.mp3', 'n.手艺，工艺；  v.手工制作，精心制作', '0964e542de5de33b908f9631bb063a91_152041_1732267181.jpg', 'd_105_4016_0_2_20150809053700.png', 'Crafts usually involve making things skillfully with one\'s hands.', '手工艺品中往往包含了熟练的手工制作。', '6730cf9b3874878b25f9285be9254d1f_30459_1590571288.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
