INSERT INTO `words` VALUES (3699, 'crude', '/kruːd/', 'crude.mp3', 'n.原油；  adj.天然的；粗糙的；粗鲁的；简陋的', '7c2db15090ac894a21ad508a93570132_171126_1555556517.jpeg', 'd_1_4586_0_3_20150808122906.png', 'The Middle East is rich in crude.', '中东是一个原油丰富的地区。', 'us_The_Middle_20240621163441956_edcae5624adf5a1de6f6.mp3', 'crud生的 + e → crude粗糙的；原始的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3700, 'custom', '/ˈkʌstəm/', 'custom.mp3', 'n.风俗；  adj.定制的', '9f5208860ac3bb8501d7de0a102ea2c2_181649_1538648145.jpg', 'd_24_5565_0_4_20150808224146.png', 'It\'s our custom to have dragon boat racing at this festival.', '在这个节日里，赛龙舟是我们的习俗。', '5f65bd6456d37859_1266883493562243624_250207.mp3', 'cu=com表加强 + stom习惯于 → custom风俗；习惯', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3701, 'delegate', '/ˈdelɪɡeɪt/', 'delegate.mp3', 'n.代表（读作/ˈdɛləgɪt/）；  v.委派……为代表', 'dd04bbc5ff295477a06a653a76a7a9eb_199549_1523158899.jpg', '20140819_22_06_16_934_v3.png', 'Delegates from both nations signed the peace agreement.', '两个国家的代表签订了和平协议。', '820fa57efa8e12352423a9589e8fb6c1_18303_1523158936.aac', 'de使…成为，加强 + leg法律 + ate动词后缀 → 加强法律 → delegate授权', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3702, 'deliberately', '/dɪˈlɪbərətli/', 'deliberately.mp3', 'adv.故意地；慢条斯理地，从容不迫地', '492a1742654ed522f337bc79bc2c8ba0_98856_1594803251.jpg', 'd_105_16328_0_2_20150809062141.png', 'Why does he deliberately try to make other people fall over?', '他为什么故意绊倒别人？', '4e6a98be28a17f2ab2ae1816095e7e57_47744_1595929798.mp3', 'deliberate故意的 + ly……地 → deliberate不是任意而为=故意的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3703, 'desire for', '/dɪˈzaɪər fɔr/', 'desire for.mp3', 'phr.欲望', '79ffb2119f87cdcb227c2fbb5edcede1.jpeg', '', 'The boy went to a fast-food restaurant to satisfy his desire for a hamburger.', '那个男孩去一家快餐店满足了自己想吃汉堡包的欲望。', '4b951332c93023587fd1c339d1d40c2e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3704, 'develop', '/dɪˈveləp/', 'develop.mp3', 'v.患病；发展，壮大', '222906d60a93dccf29ad9280bc43269f.jpeg', 'd_24_10968_0_3_20150808230458.png', 'The man has developed liver disease.', '这个男人患上了肝病。', '1c38208549c28567e530ba1448bdce48_28112_1599549987.mp3', 'de不 + velop盖上 → 不阻止，不掩盖 → develop发展', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3705, 'dialect', '/ˈdaɪəlekt/', 'dialect.mp3', 'n.方言；语调', '3_0_20170930071736_80701_c-gigapixel-scale.jpg', 'd_107_5888_0_2_20150809014423.png', 'They come from two different areas', '他们来自两个不同的地区，所以他们说不同的方言。', '9nb4c4laddke9r2xwj2k8sm6cxb9r8xy.mp3', 'dia在…之间 + lect讲，读 → 在一部分人之间说 → dialect方言', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3706, 'die out', '/daɪ aʊt/', 'die out.mp3', 'phr.灭绝，绝种', 'dffb6147b5fdb74748a1b60db5b14c21_130292.jpg', '', 'Dinosaurs have died out', '恐龙已经灭绝了，但是你依然可以找到他们的化石遗骸。', 'us_Dinosaurs_have_20240401130606383_9a636712356301159eff.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3707, 'dig', '/dɪɡ/', 'dig.mp3', 'v.挖掘，掘出；  n.挖苦', '9241972382429a9522700002836316c5_69885_1599472174.jpeg', '20130130_16_27_08_484.png', 'The dog is digging a hole.', '这只狗正在挖洞。', '68c97d029a0cd7f4091bcec05d83888a_35374_1599472169.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3708, 'dinner', '/ˈdɪnər/', 'dinner.mp3', 'n.正餐，主餐，（现通例指）晚餐', '6b4d14bde4099a1c4b220af1674e92c3_178074_1574821857.jpeg', 'd_67_12411_0_4_20150809024049.png', 'The family enjoyed a big dinner.', '全家人享受了丰盛的晚餐。', '56dacfc5e7397105_1266763450989456164_250117.mp3', 'di打破，与...相反 + nner空腹，饥饿 → 打破饥饿的状态吃大餐 → dinner正餐，晚餐', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3709, 'director', '/dəˈrektər/', 'director.mp3', 'n.（电影、戏剧等的）导演', 'i_1_16476_0_4_151019150946-gigapixel-scale.jpg', '20130130_16_27_04_971.png', 'Cut! the director shouted while shooting a film.', '”卡!“导演在拍摄电影的时候大叫道。', 'sa_1_16476_0_4_151029155455.aac', 'di使……变成 + rect表示直 + or表示人 → director指导者，导演', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3710, 'dispute about', '/dɪˈspjut əˈbaʊt/', 'dispute about.mp3', 'phr.争论；纠纷', '83f55758dbbfc04363e9c81f6e469b38.jpeg', '', 'They resolved their dispute about the land.', '他们解决了关于土地的纠纷。', '83636fe97ab2efc93762dcccf18ce431.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3711, 'distance', '/ˈdɪstəns/ ', 'distance.mp3', 'n.距离；间距', '94690c3a59b5852b229c5be08bd604ae_48436_1621938074-gigapixel-scale.jpeg', 'd_24_7906_0_3_20150808225213.png', 'The distance between the two buildings is 2 km.', '这两栋建筑之间的距离是2千米。', 'lhprzdpskpmm5yj2mrav8jakkdv5zhyf.mp3', 'dist距离 + ance表状态 → distance距离，远处', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3712, 'doughnut', '/ˈdoʊnʌt/', 'doughnut.mp3', 'n.甜甜圈；油炸圈饼；多纳滋', '37fa82db6eb8ea8253b6019867ba63bc.jpg', '', 'There are some delicious doughnuts in the box.', '盒子里有些美味的甜甜圈。', 'q5xcwmvcva6mkhu6hakqdjl77hwf6pr2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3713, 'draw', '/drɔː/', 'draw.mp3', 'v.绘画；吸引；  n.平局', 'i_1_16054_0_4_151019160957-gigapixel-scale.jpg', 'd_24_16054_0_4_20150808231055.png', 'The girls are sitting on the ground drawing pictures.', '女孩们正坐在地上画画。', 'd74945f5942acb5f_1266883199249439318_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3714, 'drill', '/drɪl/', 'drill.mp3', 'v.钻孔；  n.训练；反复操练；钻头', 'cec836f33b8c48a1c440d8c141110622_36594_1565690203.jpg', 'd_24_4285_0_3_20150808223505.png', 'The worker drills into the wall.', '工人在墙上钻孔。', '503805eebe73566f_1266883327545420776_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3715, 'drug', '/drʌɡ/', 'drug.mp3', 'n.药物；  v.下麻药', '4b0609f9202260fac168104ea8d0e167_82508_1577950990.jpeg', 'd_109_15984_0_2_20150809061009.png', 'The doctor gave me some drugs.', '医生给了我一些药。', '85a722e99013ebc5dc6c7aeae7be01cb_25294_1577950988.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3716, 'eliminate', '/ɪˈlɪmɪneɪt/', 'eliminate.mp3', 'v.消除，根除；消灭，铲除；（在比赛中）淘汰', 'i_1_5484_0_5_20150808123918-gigapixel-scale.jpg', 'de9f01f221abb8f4c78db3c06babf156_681789_1551843720.png', 'This device helps me eliminate the weeds in my garden.', '这个装置帮助我除掉我花园里的杂草。', '746bff2e861d910f971a5b4931226c2d_16502_1546401836.mp3', 'e出 + limin门槛 + ate动词后缀 → eliminate消灭，删除', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3717, 'emotion', '/ɪˈmoʊʃn/', 'emotion.mp3', 'n.情绪，情感；感情；强烈的感情；感性', 'eb5cef935e176538280846e0a75b2d9a_175957_1552552122.jpeg', 'd_1_5693_0_2_20150808124230.png', 'She expressed different emotions when watching this TV series.', '她看这部电视剧的时候表现出了不同的情绪。', '1568ae6e35126e2cf4d8512db85f7632_31205_1552552128.mp3', 'e出 + mot移动 + ion名词后缀 → 动出[感情] → emotion感情', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3718, 'employer', '/ɪmˈplɔɪər/', 'employer.mp3', 'n.雇主，老板', 'a9302bb304cf1735f7f85210219ac016_106854_1538668702.jpg', '20130513_13_40_59_629.png', 'The girl is hired by the employer.', '女孩被雇主录用了。', '8gnshk3edzmq7n3plz2bur793klt6kda.mp3', 'employ雇用 + er施动者 → employer雇主', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3719, 'enclose', '/ɪnˈkloʊz/', 'enclose.mp3', 'v.围住；装入信封', '7ece6f2b7d4cd35f0c08b29355fc1d28_146252_1538753143.jpg', 'd_1_4166_0_2_20150808122453.png', 'The girl enclosed the butterflies in the glass jar.', '女孩把蝴蝶装到了玻璃罐里。', 'qwmm8x8pd8xrwdfpqqn4jlfjldsfxc7p.mp3', 'en使 + close关闭 → enclose包围', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3720, 'engage in', '/ɪnˈɡeɪdʒ ɪn/', 'engage in.mp3', 'phr.参与', 'eb0ca4122bda3760592a5613ebd6882e.jpg', '', 'The teacher is engaged in discussions with the students.', '老师参与了学生之间的讨论。', '36a9b5fee3832ecb62e2f226042629da_49568_1596772016.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3721, 'entertain', '/ˌentərˈteɪn/', 'entertain.mp3', 'v.使欢乐；招待，款待', '833221a3f3eb1a6a902e9dee6ec4830c_155735_1538757977.jpg', 'd_107_6232_0_2_20150809015329.png', 'The woman plays the clown to entertain children at the party.', '这个女人扮成小丑在派对上逗孩子们开心。', 'us_The_woman_20241009153529893_b50cecfc417a01a5cc8d.mp3', 'enter在……中间 + tain拥有 → entertain娱乐', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3722, 'eve', '/iːv/', 'eve.mp3', 'n.（节日等的）前夜，前夕', 'i_1_16696_0_3_20150808132306-gigapixel-scale.jpg', 'd_109_16696_0_2_20150809061556.png', 'We set off some fireworks on New Year\'s Eve.', '我们在新年前夜放了一些烟花。', 'sa_1_16696_0_3_20150808132306.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3723, 'exclude', '/ɪkˈskluːd/', 'exclude.mp3', 'v.排挤，排除；驱逐，赶出', '1cca5bf38ffc1b389a14d6a2b8b47833_145401_1583393984.jpg', '20140927_08_54_15_575_v3.png', 'He was excluded by other teenagers.', '他被其他青少年排挤。', 'e856203d199898e994207e343ffd2163_11801_1538649883.mp3', 'ex向外 + clude关 → 关在外面 → exclude不包括', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3724, 'exposure to', '/ɪkˈspoʊʒər tuː/', 'exposure to.mp3', 'phr.暴露', '6b2fc3ff2a321692fecfbdf9722fc9ae.jpeg', '', 'Because of exposure to the sun', '因为暴露在太阳下，玉米先生都晒伤了。', '2a6d31e2b0f3dbc0c9e672bec7a550f8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3725, 'face up to', '/feɪs ʌp tu/', 'face up to.mp3', 'phr.大胆面向', '3bb4f21f580506150e36b5c13dbf1dd1.jpg', '', 'He has to face up to his failure instead of running away from it.', '他必须直面自己的失败而不是逃避。', '9f352313eb23e95c03719d79a65127a4.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3726, 'fare', '/fer/', 'fare.mp3', 'n.交通费；  v.（事情）进行得（好或坏）', '947babeadbec7e655de42687ad3f6578_91111_1562141817.jpeg', 'd_24_6409_0_3_20150808224624.png', 'She paid three dollars for the bus fare.', '她付了三美元的公交车费。', 'd1f51f2e00fbf7ea694b376525b93e16_27504_1562141825.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3727, 'fashion', '/ˈfæʃn/', 'fashion.mp3', 'n.时髦，风尚；  v.制作，塑造', '2e5e68e77c2f091fe78a593c03830ff4_112176_1747722733.jpg', 'd_1_7931_0_2_20150808130153.png', 'He is trying to keep up with the latest fashion trend.', '他在努力追随最新的时尚潮流。', '0aabf45e2ac41c426b2c842a5c638ae1_37132_1534226628.mp3', 'fash放置，设置 + ion名词后缀 → fashion制作，塑造，时尚', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3728, 'fatigue', '/fəˈtiːɡ/', 'fatigue.mp3', 'n.疲乏，劳累', 'ca808b290908eca8164733f78effc559_98230_1565171896.jpg', 'd_105_6620_0_2_20150809055834.png', 'Students got fatigue while writing homework.', '学生们在写作业时感到疲劳。', '5ab9ec49fa52f0c02b2df839d2edddd4_15249_1648781758.mp3', 'fat断裂 + ig做，驱动 + ue动词后缀 → fatigue快断裂的，接近极限点的 → fatigue疲乏，劳累', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3729, 'feature', '/ˈfitʃər/', 'feature.mp3', 'n.特征，特点，特色；  v.以……为特色；起重要作用，作为主要角色', 'i_1_4374_0_4_151204105622-gigapixel-scale.jpg', 'd_1_4374_0_2_20150808122700.png', 'The thick lips are a feature of Lord Bao.', '厚嘴唇是包大人的一个特征。', '590e41866bba96b314f8c3e6393739dc_15406_1619172197.mp3', 'feat做，制作 + ure名词后缀 → 做事的状态 → 做事特征 → feature面貌；特征', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3730, 'fill in', '/fɪl ɪn/', 'fill in.mp3', 'phr.填充', '3_0_20160528173707_72339_c.jpg', '', 'Please fill in the form if you want to join our club.', '如果你想加入我们俱乐部，请先填写这张表格。', '3_0_20160528173707_12202_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3731, 'finding', '/ˈfaɪndɪŋ/', 'finding.mp3', 'n.发现，调查结果', 'i_1_5023_0_4_151104141033-gigapixel-scale.jpg', 'd_1_5023_0_2_20150808123336.png', 'Her finding is beneficial to the medical field.', '她的发现对医学领域大有裨益。', 'sa_1_5023_0_4_160129145350.aac', 'find发现 + ing构成抽象名词 → finding发现；调查的结果', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3732, 'fluent', '/ˈfluːənt/', 'fluent.mp3', 'adj.（语言）讲得流利的；（文字）流畅熟练的', 'beeb088836173941464760a65afa40c4_157476_1624093779.jpg', '45b762f85f164bfdd5a8479eb4b95c28_36919_1566273399.jpg', 'The rapper used his fluent English to complete the freestyle.', '这个说唱歌手用他流利的英文完成了这段即兴说唱。', '3_0_20170930071740_25529_c.aac', 'flu流动 + ent…的 → 流动的 → fluent流利的，流畅的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3733, 'forget', '/fərˈɡet/', 'forget.mp3', 'v.忘记，遗忘', '52fbfcb69b3cadb0df797d8b0aa8b0bf_193614_1585123900.jpeg', '20130201_16_29_57_520.png', 'He forgot to remove his key from the lock when he left his apartment.', '他离开公寓时忘了把钥匙从门锁上拔下来。', '7w7k9v7vxjnbwmcfx8uqf9xj7hhrhlul.mp3', 'for否定，相反 + get得到，想起 → 想不起来的 → forget忘记', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3734, 'forward', '/ˈfɔːrwərd/', 'forward.mp3', 'adv.向前，向将来；前进；  adj.向前的，前面的；  v.转寄，转投', '8a6d0d4098dca2a4ed1fae8960ad1ee0_76046_1605584300.jpg', 'd_24_17980_0_5_20150808233918.png', 'Forward', '向前吧，伙计们！让我们今天就达成目标！', 'us_Forward_men_20240627113953553_c30a82500e17ac435ad2.mp3', 'for前 ＋ ward向…... → forward向前；今后', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3735, 'freeze', '/friːz/', 'freeze.mp3', 'v.冻结，结冰；（使）冻住；  n.严寒，冻结', '89d6e0ebfab6988ad24d9a2621d74448_70306_1585125010.jpeg', '20140927_13_39_22_947_v3.png', 'Water freezes at 0°C.', '水在零摄氏度时会结冰。', 'ybhq8evy84vaygg7w7bbuyfr8befjg47.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3736, 'friendship', '/ˈfrendʃɪp/', 'friendship.mp3', 'n.友谊', '4b92911f9daf9dbd4e1dbdb1692f99f7_88142_1522657300.jpg', '20140927_13_39_33_981_v3.png', 'The two kids have a very close friendship.', '这俩孩子有着深厚的友谊。', '568bc5ab99b1002322ca6648f04235ca_29938_1522657288.mp3', 'friend朋友 ＋ ship名词后缀 → friendship友谊', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3737, 'frown upon', '/fraʊn əˈpɑːn/', 'frown upon.mp3', 'phr.皱眉', 'fd7361b541878e041ac8f8a04edadd7b.jpg', '', 'Playing videos aloud on the subway is permitted', '在地铁上大声外放视频未被禁止，尽管其他乘客都为之皱眉。', '8527603216f9d1b2ba49388cf42eb173.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3738, 'fry', '/fraɪ/', 'fry.mp3', 'v.油煎；油炸', 'i_1_5440_0_4_151019112307-gigapixel-scale.jpg', 'd_109_5440_0_2_20150809054141.png', 'It\'s easy to fry eggs; I can make two for you.', '煎鸡蛋很容易，我可以给你做两个。', '43dfd4602d657dd1_1266883008969857698_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
