INSERT INTO `words` VALUES (3740, 'funeral', '/ˈfjuːnərəl/', 'funeral.mp3', 'n.丧葬，葬礼', 'c_i_4796_1001_2_1_150711145417-gigapixel-scale.jpg', 'd_101_4796_0_3_20150809034600.png', 'They held a funeral for the leader\'s dog.', '他们为老大的狗举行了葬礼。', 'us_They_held_20230206215825367_be5f8f47c95da9f15587.mp3', 'funer葬礼 + al表名词 → funeral葬礼', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3741, 'furniture', '/ˈfɜːrnɪtʃər/', 'furniture.mp3', 'n.家具；装置；设备', 'a1e51c2b35b2863407734f4c3f9a8ceb_27567_1584955196.jpeg', 'd_24_5160_0_4_20150808223955.png', 'All of his furniture came as a set.', '他的所有家具都是成套的。', 'b295f46ac882b067_1266883320880126554_250207.mp3', 'furni安置 + ture表名词 → furniture家具', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3742, 'further', '/ˈfɜːrðər/', 'further.mp3', 'adv.更远地；  adj.更进一步的', '1d325677357188b6e73aab816a849019_234965_1728373821.jpg', 'd_1_10573_0_2_20150808131707.png', 'Combined with advanced robotic technology', '与先进的机器人技术结合，我能看得更远。', 'us_Combined_with_20250116141839464_af45a31b80e332b12c94.mp3', 'furth=forth向前，向前方 + er比较级 → 更前面的 → further更远的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3743, 'garage', '/ɡəˈrɑːʒ/', 'garage.mp3', 'n.车库；修车厂', '5b8e650365acca63c6f768574c89eeef_112156_1533120466.jpeg', 'd_105_7250_0_2_20150809060311.png', 'There is a car parked in the garage.', '有一辆车停在车库里。', '766cb91894edc9d1_1266883004916259372_250207.mp3', 'gar掩盖，保护 + age名词后缀 → 遮挡和维修的地方 → garage车库，维修厂', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3744, 'generation', '/ˌdʒenəˈreɪʃn/ ', 'generation.mp3', 'n.一代；一代人', 'b7da97be9d3b599c8551c1a4b76f35e2_56730_1732529441.jpg', 'd_16_16066_0_4_20150809001736.png', 'My family includes three generations of people.', '我们家三代同堂。', 'us_My_family_20221205183915227_75e3dc0a065a2ebd25b7.mp3', 'generate 产生，发生 + ion表名词 → 产生出的一代人 → generation一代；一代人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3745, 'get at', '/ɡet æt/', 'get at.mp3', 'phr.够得着，触及', 'd0dedeca3cf52c458b2dc929ff67c861.jpg', '', 'This little boy was trying to get at the apple on the table. ', '小男孩努力想够到桌上的苹果。', '258d8aebd3d00e947b1f1a065ca7834a.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
