INSERT INTO `words` VALUES (3748, 'guess at', '/ɡɛs æt/', 'guess at.mp3', 'phr.对……猜测', '004aa7308f436ec61b7b001e8ed24b65.jpg', '', 'He guessed at the gift.', '他猜了猜礼物是什么。', 'us_He_guessed_20241009154630893_d19ff6639ef6eeb74201.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3749, 'hatred', '/ˈheɪtrɪd/', 'hatred.mp3', 'n.憎恨', '23852dddd30b42367e12bc7ce3e9c3ee_120382_1538664665.jpg', 'd_1_8226_0_2_20150808130514.png', 'He has a lot of hatred for this terrible phone.', '他对这个糟糕的手机有极大的怨恨。', 'us_He_has_20250330193847349_28c522faebdf97a0760f.mp3', 'hatr仇恨 + ed名词后缀 → hatred憎恶，憎恨，仇恨', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3750, 'headline', '/ˈhedlaɪn/', 'headline.mp3', 'n.大字标题', 'c2106e6c382a1051a9d18cac0e0c65d2_110811_1736745619.jpg', '20141011_05_17_18_972_v3.png', 'I didn\'t read the story; I only saw the headline.', '我没读这个故事，我只看了大字标题。', '7ybf4x9jlvd9ktuqd6awl9d739ry97pe.mp3', 'head头 + line字行 → 头一行字 → headline标题', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3751, 'hostile', '/ˈhɑːstl/', 'hostile.mp3', 'adj.怀有敌意的；敌对的，敌方的', '6720159d0cce7be5c77281f0d51b74a6_103424_1538621676.jpg', 'd_107_5951_0_2_20150809014555.png', 'He is hostile to everyone.', '他对每个人都充满敌意。', '822c78f67fb1333b59fa0474e8523290_8666_1538621699.mp3', 'host(=hostis)敌人 + ile……的 → 有敌意的 → hostile敌意的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3752, 'hundred', '/ˈhʌndrəd/', 'hundred.mp3', 'num.百，百个；许多', '004c24a61a6415142f5714df69be5885_136035_1656661126.jpg', 'd_24_17138_0_3_20150808232120.png', 'Whose face is on the hundred-dollar bill?', '一百元美钞上是谁的头像？', '2a11c7016e4277f2c9ee1c8d7aef44ec_13525_1596092380.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3753, 'ignore', '/ɪɡˈnɔːr/', 'ignore.mp3', 'v.忽略；不理睬，佯装未见', '8c03e0619353851b02642236c311ecfe_176344_1532143459.jpeg', 'd_16_5732_0_2_20150808225758.png', 'The boy\'s parents ignored him as they were doing their own things.', '男孩的父母忽略了他，只顾着自己的事。', 'm9pg2g5djczbhsm4h8kkytzzdatz2txt.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3754, 'immediate', '/ɪˈmiːdiət/', 'immediate.mp3', 'adj.立刻的', '11f60f58ec5b4893ba2d03dc73bfe5f2_125701_1605175494.jpg', 'd_16_10581_0_3_20150808235544.png', 'You should take immediate action when facing problems.', '面对问题时，你应该立即采取行动。', 'a389e513541e6cb74b572e4ae3844030_18697_1619316423.mp3', 'im不 + mediate间接的 → immediate直接的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3755, 'impact', '/ˈɪmˌpækt/', 'impact.mp3', 'n.影响；冲击力；碰撞，冲击（读作/ˈɪmˌpækt/）；  v.有影响（读作/ɪmˈpækt/）', 'c05593fbaaa3338e272e877144e787b2_116956_1558592918.jpeg', 'd_1_8969_0_2_20150808131108.png', 'The continuous heavy rain had a big impact on transport.', '持续的暴雨对交通造成了严重的影响。', '397myzb9k3cz5be4num5ahbha6z7ll9y.mp3', 'im进入 + pact紧的 → 紧紧进入人心的力量 → impact影响力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3756, 'import', '/ˈɪmpɔ:rt/', 'import.mp3', 'v.进口；  n.进口', '013c5d899b8d07534116af895a8d28c1_138845_1544066831.jpeg', 'd_107_4887_0_2_20150809011012.png', 'The goods on this ship were imported from overseas.', '这艘船上的货物是从海外进口的。', 'f5dde80d5932917267ae8d2f13208b59_44929_1569642511.mp3', 'im向内，进入 + port拿，运 → 拿进港口 → import进口', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3757, 'in a moment', '/ɪn ə ˈmoʊmənt/', 'in a moment.mp3', 'n.马上', 'fee8f818c46a667796b66d60b1719492.jpg', '', 'The busy cashier told the customer she\'d be with her in a moment. ', '忙碌的收银员告诉顾客稍等，她马上就来。', 'cf7abfa8f330ab33c19da59b024f9ddc.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
