INSERT INTO `words` VALUES (3772, 'less', '/les/', 'less.mp3', 'det.更少的', 'i_16_17903_0_2_20150809013043-gigapixel-scale.jpg', 'd_109_17903_0_2_20150809062550.png', 'It seems that every day I have less and less money.', '看起来我的钱是一天比一天少。', 'dcd9ee0071042186_1266883113920211882_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
