INSERT INTO `words` VALUES (3775, 'lose', '/luːz/', 'lose.mp3', 'v.失去；遗失，丢失；（在竞争或比赛中）输掉', '3_0_20170707172409_95979_c-gigapixel-scale.jpg', 'd_24_16640_0_4_20150808231740.png', 'He is losing weight by running.', '他正通过跑步来减肥。', 'rhm87xax3b7p9ulns47d38pmrzdl2w29.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
