INSERT INTO `words` VALUES (3777, 'magnificent', '/mæɡˈnɪfɪsnt/', 'magnificent.mp3', 'adj.宏伟的，壮丽的，极好的', '9dd6715aebc9522d4994c8066a28f670_194152_1535008310.jpeg', 'd_107_5850_0_2_20150809014242.png', 'They are some of the most magnificent landmarks in the world.', '它们是世界上最宏伟的几处地标性建筑。', 'x32g47798tw8syfyasrehtv78v9fpr5w.mp3', 'magn大 + ific的 + ent…的 → magnificent壮丽的，宏伟的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3778, 'mass', '/mæs/', 'mass.mp3', 'n.大量，一堆；群众；  v.聚集', 'fb4ab551bfe3ffe43a06145fd5847870_89051_1565342815.jpg', 'd_16_7487_0_2_20150808231817.png', 'A mass of people are waiting.', '一大群人在等待。', '9a9796d2497a67ab224e76eceb2eb00d_8822_1539932359.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3779, 'mill', '/mɪl/', 'mill.mp3', 'n.磨坊，碾磨机，制造厂；  v.碾，磨，（毫无目的地）乱转', 'c1ef7cce50d00d345793f2f00b7b393c_164015_1719222943.jpg', 'd_1_4895_0_2_20150808123121.png', 'It is a mill once used for corn flour production.', '这是一个曾经用来生产玉米粉的磨坊。', '9d2568247w9dbsnlv86j6dup9x4aghwp.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3780, 'millimeter', '/ˈmɪlimiːtər/', 'millimeter.mp3', 'n.毫米', 'i_1_11453_0_4_151015144515-gigapixel-scale.jpg', 'd_105_11453_0_2_20150809061856.png', 'The thickness of a single coin is one millimeter.', '一枚硬币的厚度是一毫米。', 'sa_1_11453_0_5_151120105544.aac', 'milli千，千分之一 + meter米 → millimeter千分之一米', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3781, 'million', '/ˈmɪljən/', 'million.mp3', 'num.百万', 'b9f63f1805a6915ec0c13c6a74c31698_172597_1656661072.jpg', 'd_24_4896_0_4_20150808223615.png', 'The businessman holds one million dollars in his arms.', '这个商人怀里抱着一百万美元。', '86253e5e318f2592_1266763524255603294_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3782, 'moisture', '/ˈmɔɪstʃər/', 'moisture.mp3', 'n.湿气；潮湿', '9bbc7a2f3a543ec62682baec885b12ce_155339_1565695653.jpeg', '20141012_02_20_47_142_v3.png', 'The machine on the table adds moisture to the air.', '桌上的机器能增加空气中的湿气。', '7108ab0a8f5ec624d226e7e8cd9165a6_17443_1619342893.mp3', 'moist潮湿的 + ure名词后缀，表行为、状态 → moisture潮湿，湿度', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3783, 'mood', '/muːd/', 'mood.mp3', 'n.情绪，心情', '4fb5d3c13f5d2681ab4bdf601ffb2245_59157_1565342042.jpg', 'd_1_7973_0_2_20150808130234.png', 'I\'m in a good mood today', '“我今天心情很好。”她微笑着说。', '1093d6b9862bb0ef_1266883626510342714_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3784, 'mount', '/maʊnt/', 'mount.mp3', 'v.骑上；登上；爬上；增长；  n.山；峰', 'mount_5126_20231106_68d28c28.jpg', 'd_24_5126_0_3_20150808223934.png', 'He mounted his horse and rode away.', '他飞身上马，疾驰而去。', 'us_He_mounted_20240407130206043_e1227c11e220aea8c046.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3785, 'multiply', '/ˈmʌltɪplaɪ/', 'multiply.mp3', 'v.乘，乘以；繁殖；增加，倍增', '3_45_20170211104015_25815_c-gigapixel-scale.jpg', 'd_107_6018_0_2_20150809014907.png', 'If I multiply 10 by 8', '如果我用8乘以10，我得到80。', 'us_If_I_20230519153306771_debdeb4c193fc307cbf9.mp3', 'multi很多 + ply重叠 → 变多 → multiply乘，繁殖', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3786, 'navigation', '/ˌnævɪˈɡeɪʃn/', 'navigation.mp3', 'n.导航，领航', 'c31b739164a446e6966946af294c4708_83369_1617762172.jpg', 'd_107_6800_0_2_20150809020937.png', 'The rat uses navigation to find the cheese.', '这只老鼠用导航为自己寻找那块奶酪。', 'a157a769311ad3c47761746cea1ca68f_100360_1617762152.mp3', 'nav船 + ig走 + ation表名词 → navigation航行；航海术；导航', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3787, 'no longer', '/noʊ ˈlɔːŋɡər/', 'no longer.mp3', 'phr.不再', '48c0f2484ace5c1751e216191a08a0ec_167500_1538760460.jpg', '', 'I am no longer addicted to smoking.', '我已经不再吸烟。', '0297af0ee8c51b534f307f03b1e46f5d_11174_1538760472.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3788, 'normally', '/ˈnɔːrməli/', 'normally.mp3', 'adv.通常，正常地', '8478bc972b8e3b2d26fb9d96629047ef_87256_1595469374.jpeg', '', 'Primary schools are normally open from Monday to Friday.', '通常来说，小学在周一到周五上课。', 'a893f7b3407214b8_1266883537386187712_250207.mp3', 'norm规则，规范 ＋ ally表示方式、程度、状态、“…地” → normally通常，正常地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3789, 'oblige', '/əˈblaɪdʒ/', 'oblige.mp3', 'v.（以法律、义务等）迫使，使感激', 'i_1_4051_0_5_20150808122257-gigapixel-scale.jpg', 'd_1_4051_0_5_20150808122257.png', 'Tax payers are obliged to pay taxes accordingly.', '纳税人有义务按规定交税。', 'b1977a228a14d201a9b44ff289b3f588_24737_1621930612.mp3', 'ob去 + lig绑 + e  → 去绑住某人  → oblige迫使', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3790, 'on earth', '/ɑːn ɜːrθ/', 'on earth.mp3', 'phr.到底，究竟', '09f5f759490bdc7e45bc6155a63a45bd.jpeg', '', 'She wondered what on earth her roommate was making.', '她想知道她的室友到底在做什么。', 'fc67c82b3cc3ab457d25522e7188de48.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3791, 'on one\'s own', '/ɑn wʌnz oʊn/', 'on one\'s own.mp3', 'phr.独自地', 'c01969acad150cee7f267a1cd633cabc.jpeg', '', 'He did his buttons up all on his own.', '他自己把纽扣全都扣上了。', '5d798ea5a7435cb6_1266883374390225696_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3792, 'onion', '/ˈʌnjən/', 'onion.mp3', 'n.洋葱', '4038b0f79942db82f852b00c83a2b6eb_125213_1552894706.jpeg', 'd_24_8551_0_3_20150808225809.png', 'She is slicing the onion with a knife.', '她正在用刀切洋葱。', 'c38ebf012183aef67791ba89a571595e_34228_1571034550.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3793, 'operation', '/ˈɑːpəˈreɪʃən/', 'operation.mp3', 'n.手术；运转，运行', '26b9645866eb64aeeb2aad02721137e9_88533_1565343420.jpg', 'd_24_4965_0_4_20150808223732.png', 'The doctors are performing the operation carefully.', '医生们在小心地做手术。', 'db29a5bee8750b8d_1266883112957029270_250207.mp3', 'operat操作 + ion名词后缀 → operation操作', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3794, 'ourselves', '/ɑːrˈselvz/', 'ourselves.mp3', 'pron.我们自己', 'c3f74235d142fec639a6764054e4a15d_51366_1558777416.jpg', 'd_24_19510_0_3_20150809001747.png', 'We took this picture of ourselves.', '我们给自己拍了这张照片。', '927042bcaee8d89a_1266883198157412926_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3795, 'out of control', '/aʊt əv kənˈtroʊl/', 'out of control.mp3', 'phr.失去控制', '984f5e6643171361c71e671b90b63977_186416.jpg', '', 'The forest fire was completely out of control.', '这场森林火灾彻底失控了。', 'v5zttt7u3l6pkmqwtn2psrzmchvw8lg7.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3796, 'outside', '/ˌaʊtˈsaɪd/', 'outside.mp3', 'adv.在户外，在外面，向外面；  n.外部；  adj.外部的，外面的；  prep.在……外面，不在……范围内', '1f3ccf7a4fa2f7f00073a6001ea2c933_148135_1701683592.jpeg', 'd_24_2786_0_3_20150808223323.png', 'I like my kids to play outside on the grass.', '我喜欢孩子们到外面的草地上玩耍。', 'us_I_like_20240628134038335_426c448eaab510379e8e.mp3', 'out外，出 + side旁边 → outside在外边', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3797, 'package', '/ˈpækɪdʒ/', 'package.mp3', 'n.包裹；一揽子，一整套', 'i_24_7911_0_4_20150808225217-gigapixel-scale.jpg', 'd_24_7911_0_4_20150808225217.png', 'I received a package with a card.', '我收到了一个带卡片的包裹。', 'sa_24_7911_0_4_20150808225217.aac', 'pack包裹 + age表物 → package包裹', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3798, 'paid', '/peɪd/', 'paid.mp3', 'adj.付费的', '1170e8303e7a72ff4154796086b058d7.jpg', '', 'The video-sharing website offers a paid service', '这家视频分享网站提供付费服务，允许用户跳过广告。', 'd2f5325c640d4d1328b2d45e8bb4a77d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3799, 'perfect', '/ˈpɜːrfɪkt/', 'perfect.mp3', 'adj.极好的；准确的；  v.使完美（读作/pərˈfekt/）', '3_0_20160520171741_94577_c.jpg', 'd_24_5611_0_4_20150808224225.png', 'Baicizhan is a perfect English study application.', '百词斩是一款极好的英语学习应用程序。', '56dc9fa9b4e9e3ec6338a1eae36ac566_16815_1552621919.mp3', 'per全 + fect做 → perfect完美的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3800, 'perhaps', '/pərˈhæps/', 'perhaps.mp3', 'adv.大概，也许', '3_0_20170707160149_52354_c-gigapixel-scale.jpg', 'd_24_18602_0_4_20150808235530.png', 'Perhaps she likes me', '也许她喜欢我，也许她根本不喜欢我。我真的不知道。', 'b82372f4bf8f4e19a94b9084b72810f9_27318_1619331270.mp3', 'per全部 + hap机会，运气 + s表复数 → 全是机会 → perhaps也许，可能', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3801, 'persuade', '/pərˈsweɪd/', 'persuade.mp3', 'v.劝说；使相信', 'd49f672588d58d792aabfb8ed0aaf169_48260_1586767875.jpeg', '20130316_16_34_55_221.png', 'He is trying to persuade his friend to go on a roller coaster with him.', '他正试图说服他的朋友和他一起坐过山车。', 'ec3907481c9d113a_1266883371641777068_250207.mp3', 'per贯穿，自始至终 + suade劝 → 一直劝 → persuade劝说', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3802, 'persuade of', '/pərˈsweɪd əv/', 'persuade of.mp3', 'phr.说服，使相信', 'd49f672588d58d792aabfb8ed0aaf169.jpeg', '', 'He is trying to persuade his friend of the fun on that roller coaster.', '他正在试图说服他的朋友相信坐那个过山车的乐趣。', 'us_He_is_20250821161046789_008dbff4073252e14363.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3803, 'phrase', '/freɪz/', 'phrase.mp3', 'n.短语，词组；简短的警句', '8c622918307215304cf31879750c8f40_132246_1619340960.jpg', 'd_24_6119_0_3_20150808224433.png', 'A phrase is a group of words that forms part of a sentence.', '短语是构成句子一部分的一组词。', 'a3447c00aa99f38050a809e31e831aaa_48848_1575269249.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3804, 'pilot', '/ˈpaɪlət/', 'pilot.mp3', 'n.飞行员；  adj.试验性的；  v.给……领航', '5911c5af82ccb9f52ddc2cacebbb68b7_98481_1595858912.jpg', 'd_24_5740_0_4_20150808224320.png', 'He dreamed of being a pilot since he was a little boy.', '他从小就梦想成为一名飞行员。', '8620960cab0a719b_1266883008892414880_250207.mp3', 'pil=ped脚 + ot名词后缀 → pilot飞行员，领航员', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3805, 'pleasant', '/ˈpleznt/', 'pleasant.mp3', 'adj.令人愉快的，舒适的', '0f15432ece4c8d64eb5bfc5f1ff45325_121728_1700203635.jpeg', 'd_24_16008_0_4_20150808231029.png', 'Her pleasant smile has lit up my day.', '她明媚的笑容照亮了我的一天。', 'us_Her_pleasant_20231117144719343_457c4d8f48998b8500be.mp3', 'pleas=please快乐 ＋ ant形容词词尾 → pleasant令人愉快的，舒适的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3806, 'pole', '/poʊl/', 'pole.mp3', 'n.杆子，棍，杖；电极', 'f79b1e39d549914d60b0284fb80a4f0b_26758_1566804311.jpg', 'd_105_4585_0_2_20150809054035.png', 'The wire pole holds the cables.', '电线杆支撑着电缆。', 'us_The_wire_20240423145700790_a4c2d3c15a4e3bdfc0e2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3807, 'powder', '/ˈpaʊdər/', 'powder.mp3', 'n.粉末；细面；火药；  v.抹粉', 'i_1_6705_0_6_150928175410-gigapixel-scale.jpg', 'd_24_6705_0_3_20150808224726.png', 'The white powder is flour which can be used to make bread.', '这种白色的粉末是面粉，可以用来做面包。', 'sa_1_6705_0_6_151017114047.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3808, 'practice', '/ˈpræktɪs/', 'practice.mp3', 'v.练习（=practise）；  n.练习，训练', '3_0_20170930071744_25138_c-manual-scale.jpg', 'd_24_16458_0_4_20150808231321.png', 'The little girl practices yoga with her mom every day.', '小女孩每天都和妈妈一起练习瑜伽。', 'us_The_little_20240621143649818_9c60e9aa1ee125d50f92.mp3', 'pract实践 + ice表名词，行为，状态 → practice实践', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3809, 'pride', '/praɪd/', 'pride.mp3', 'n.自豪；傲慢；  v.使得意；为……自豪', '3_0_20160520173541_34830_c-gigapixel-scale.jpg', 'd_24_7496_0_4_20150808225123.png', 'The parents took pride in their son\'s graduation.', '父母为儿子的毕业感到很自豪。', '3_0_20160520173541_20546_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3810, 'prompt', '/prɑːmpt/', 'prompt.mp3', 'v.敦促，促使，激励；  adj.迅速的，及时的；  n.提示', '0ef7a15199076fcf2ef660d39a181d30_41800_1558321635.jpg', 'd_1_4075_0_2_20150808122314.png', 'My phone prompts me to get out of bed and finish my paper!', '我的手机敦促我起床写论文！', 'cbba5c4d98f2113023b973069db454de_19637_1558321716.mp3', 'pro先，前 + mpt=empt拿 → 最先拿到的 → prompt迅速的，及时的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3811, 'protect', '/prəˈtekt/ ', 'protect.mp3', 'v.保护；警戒', 'abf2628f7981ad313b5a2064fb88f8ce_161543_1534821105.jpeg', 'd_24_7121_0_4_20150808224947.png', 'Builders should wear professional equipment to protect themselves.', '建筑工人需要穿着专业装备来保护自己。', 'cdfqgxjz7495nbr3x38askhnmsynuv6w.mp3', 'pro在前面 + tect盖上，保护 → 在前面盖上 → protect保护；防止', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3812, 'qualified', '/ˈkwɑːlɪfaɪd/', 'qualified.mp3', 'adj.有资格的', 'f7f2b4f69e3d2af8cc322b8dfbf52a35_166502_1545124448.jpg', '20130301_12_53_57_168.png', 'Admission letters indicate students are qualified for their dream university.', '录取通知书表明学生有资格进入他们梦想的大学。', 'ac00775f8cac54c1627125b8c8db61ab_22145_1545124458.mp3', 'qualif=qualify资格 + ied形容词后缀 → qualified有资格的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3813, 'radar', '/ˈreɪdɑːr/', 'radar.mp3', 'n.雷达，无线电探测器', '20120703_03_13_13_845-gigapixel-scale.jpg', 'd_106_6797_0_2_20150809073741.png', 'We saw the airplane with radar before we could see it with our own eyes.', '在肉眼能看到飞机前，我们就能用雷达探测到它了。', 'sa_1_6797_0_3_20150808125509.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3814, 'regulate', '/ˈreɡjuleɪt/', 'regulate.mp3', 'v.管理，控制', 'i_1_6589_0_3_20150808125238-gigapixel-scale.jpg', 'd_1_6589_0_3_20150808125238.png', 'This guy\'s duty is to regulate the traffic.', '这个人的职责是管理交通。', 'sa_6589_1_0_2_150707163717.mp3', 'regul规则 ＋ ate表动词 → regulate管理，控制，调整', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3815, 'relieved', '/rɪˈliːvd/ ', 'relieved.mp3', 'adj.放心的，宽慰的', 'd289388c78427a0ada67c9bae2f8accb.jpg', '20140913_04_40_48_430_v3.png', 'The parents were relieved that their child\'s operation was successful.', '孩子的手术成功了，这对父母松了一口气。', 'aaj485vp84un2at3r4d2rhd3u2lc7ys9.mp3', 'reliev=relieve宽慰 + ed形容词后缀 → 放心的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3816, 'reserve', '/rɪˈzɜːrv/', 'reserve.mp3', 'n.储备；储备金；保护区；  v.保留；预订；储备', '473dea4a12b861ca04b1c6c23c4d018b_195920_1579597497.jpeg', 'd_107_3974_0_2_20150809003810.png', 'He has an emergency reserve of food stored at home.', '他在家里有一个存放食物的紧急储备库。', 'd5a510863ca8ca26a39aa2d0f995c08e_34877_1590569083.mp3', 're再 + serve服务，保持 → 再留住 → reserve预定', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3817, 'rice', '/raɪs/', 'rice.mp3', 'n.米饭', 'i_67_14000_0_4_20150809024147-gigapixel-scale.jpg', 'd_76_14000_0_4_20150809031008.png', 'I\'ll cook rice for dinner.', '晚餐我会煮米饭。', '19cf5e7b6d8b2d22_1268213309878977174_250930.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3818, 'rich', '/rɪtʃ/', 'rich.mp3', 'adj.富有的；肥沃的', '20120522_05_40_02_854-manual-scale.jpg', 'd_24_16636_0_4_20150808231733.png', 'The rich couple decided to sail around the world after they retired.', '这一对富裕的夫妻决定在退休后去环游世界。', 'a5320d155f6a6b3b_1266883004047645216_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3819, 'rob', '/rɑːb/', 'rob.mp3', 'v.抢劫，盗取', 'a058e9e7eeafdff49c43d042bcde4b81_195934_1731909731.jpg', '20141014_04_15_30_332_v3.png', 'The man has robbed the bank.', '那个人抢劫了银行。', '50d442af888e8bfe_1266883331346422342_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3820, 'rubber', '/ˈrʌbər/', 'rubber.mp3', 'n.橡皮；橡胶制品，胶鞋', 'i_13_17033_0_2_20150808204357-gigapixel-scale.jpg', '4c43e8b1313bf8b707586267c53d47b4_44503_1551252564.png', 'Wear rubber gloves to do dirty work.', '戴上橡胶手套来做脏活。', '10fd224d8e1b4e05_1266741632845458318_250113.mp3', 'rub擦 + b + er名词后缀：物 → rubber橡皮', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3821, 'ruin', '/ˈruːɪn/', 'ruin.mp3', 'v.毁灭，毁坏；（使）破产；（使）堕落；  n.废墟', '2267f6c63059e28cc765cfa2687b88a3_50191_1558073250.jpeg', '20141014_00_15_13_340_v3.png', 'Our village was totally ruined by the UFO lasers.', '不明飞行物用射线完全摧毁了我们的村庄。', '3_0_20170930071244_36738_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3822, 'run down', '/rʌn daʊn/', 'run down.mp3', 'phr.逐渐耗尽', 'a369bcf2ac46e0d64fc3a6925df9f4b0.jpeg', '', 'Having the brightness on full really runs down the battery!', '把亮度调到最大会很快耗尽电池！', '981c13c49b6157d09e75a6e5e69be955.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3823, 'satisfactory', '/ˌsætɪsˈfæktəri/', 'satisfactory.mp3', 'adj.令人满意的', '7f120b20168d84765901f6d8dcc22ceb_189358_1538664840.jpg', 'd_24_6213_0_4_20150808224528.png', 'The little boy had a satisfactory service at the barber shop.', '小男孩在理发店得到了令他满意的服务。', '5f2458e4d67af204c3bd32a0ba6f8e14_19011_1538664857.mp3', 'satis足够 + fact做 + ory表形容词 → satisfactory令人满意的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3824, 'satisfy', '/ˈsætɪsfaɪ/', 'satisfy.mp3', 'v.满足；符合……的标准', '79ffb2119f87cdcb227c2fbb5edcede1_140935_1574740627.jpeg', 'd_24_6347_0_3_20150808224608.png', 'The boy went to a fast food restaurant to satisfy his desire for a hamburger.', '男孩去快餐店满足了自己想吃汉堡包的欲望。', '9b8d7421890f48de_1266883487410137980_250207.mp3', 'satis足够，饱足 + fy化 → satisfy使…满足', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3825, 'semester', '/sɪˈmestər/', 'semester.mp3', 'n.学期', '3_0_20161224072432_26490_c-gigapixel-scale.jpg', 'd_1_10296_0_2_20150808131647.png', 'A school year often contains two semesters.', '一学年通常包含两个学期。', '3_0_20161224072432_34007_c.aac', 'se=sex六 + mester=mensis月  → 六个月（约一个学期）  → semester学期', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3826, 'sensitive', '/ˈsensətɪv/', 'sensitive.mp3', 'adj.敏感的；灵敏的', 'a96c16a861d20fd3e5f5ce387a049dff_126356_1732156609.jpg', 'd_107_5692_0_2_20150809013458.png', 'His teeth are sensitive to ice cream.', '他的牙齿对冰淇淋很敏感。', 'f80de02ce9e1be9b_1266883487810694022_250207.mp3', 'sens感觉 + itive形容词后缀 → sensitive敏感的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3827, 'settle down', '/ˈsɛtəl daʊn/', 'settle down.mp3', 'phr.定居，安定下来', 'bf5d2cafcbb14b5749d3dabd12fbfb17_170150_1701674922.jpg', '', 'The couple decided to settle down and buy a house together.', '这对夫妇决定安定下来，一起买套房子。', '4zvbg5xqq6s4vstdddgajuxum4x6gur9.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3828, 'shareholder', '/ˈʃerhoʊldər/', 'shareholder.mp3', 'n.股东，股票持有者', 'i_13_2343_0_5_151226111412.jpg', '20140729_23_45_21_67_v3.png', 'Shareholders are expecting rapid market growth by next month.', '股东们期望下个月市场快速增长。', 'sa_12_2343_0_5_160107102056.aac', 'share股份 + holder持有人 → shareholder股东', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3829, 'shelf', '/ʃelf/', 'shelf.mp3', 'n.架子，搁板', '226ece97da7a11c565562882b815315a_153426_1541663951.jpeg', 'd_24_17111_0_4_20150808232029.png', 'There are many books on the shelf.', '架子上放了很多书。', '25c561993688d0ad_1266763241231657876_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3830, 'sign', '/saɪn/ ', 'sign.mp3', 'v.签署；  n.记号，符号', 'i_1_8107_0_4_151110170102-gigapixel-scale.jpg', 'd_24_8107_0_4_20150808225454.png', 'Please sign your name on this paper.', '请在这张纸上签下你的名字。', 'f76aaq3e8skb37ykqpgq4xdcklrck5nx.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3831, 'signal', '/ˈsɪɡnəl/', 'signal.mp3', 'n.信号；  v.标志；发信号', '39e5915f034846141d1874052cad2f33_165977_1595058708.jpg', '20130106_14_37_53_307.png', 'There\'s no signal in the mountains.', '山里没有信号。', 'xfhavgkae83m9fka24l3rp2kx4gedjyu.mp3', 'sign标志 + al名词/形容词后缀 → signal信号/显要的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3832, 'slowly', '/ˈsloʊli/', 'slowly.mp3', 'adv.缓慢地', '6bb75a336d4a9873306101d808797059_100995_1587629475.jpeg', '', 'The boy with brown hair is running slowly.', '棕色头发的男孩跑得很慢。', '0272ac34e6925e6472adabbff8c784f0_45760_1587819815.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3833, 'sooner or later', '/ˈsʊnər ɔːr ˈleɪtər/', 'sooner or later.mp3', 'phr.迟早；早晚有一天', '4eceec676394b70fc5ee722766b46ed8_141524_1538754631.jpg', '', '“I swear I will succeed sooner or later! thought the businessman standing by the window.', '“我发誓我一定会成功的！”那个站在窗边的商人这样想。', 'b8d167d213572c1aaada199dc11de215_27631_1538754655.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3834, 'souvenir', '/ˈsuːvənɪr/ ', 'souvenir.mp3', 'n.纪念品', '479bda813f2d4a548a53b08c0fa5cfcc_86054_1522663285.jpg', '20130130_16_21_17_465.png', 'I bought a handmade bell as a souvenir for my friend.', '我给朋友买了一个手工铃铛作为纪念品。', '4ee84e4665efb97f_1266883375810980712_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3835, 'space', '/speɪs/', 'space.mp3', 'n.（可利用的）空间，空地，距离；（两物或某物两部分之间的）空当，空隙，间隔，距离；  v.留间隔，隔开', 'b04526ada1d33b1a5c40f0171356b64a_215588_1656999460.jpg', 'd_24_17991_0_4_20150808234014.png', 'This house comes with large open space.', '这个房子拥有宽敞的开放空间。', 'd2f15f287e208802_1266883009515334580_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3836, 'spell', '/spel/', 'spell.mp3', 'v.拼写；  n.符咒', '20120515_04_16_49_533-gigapixel-scale.jpg', 'd_99_14292_0_4_20150809022535.png', 'Sometimes we can play word games to learn how to spell.', '有时候我们能通过玩拼字游戏来学会拼写。', 'z9jtbvtj6jswl4bmmpq7hsm4kw4edhft.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3837, 'spend', '/spend/', 'spend.mp3', 'v.花（时间或精力）', '666b03c986cdc8b712e02c95ce550f9e.jpg', 'd_24_11039_0_4_20150808230541.png', 'They like spending time together as a family.', '他们喜欢全家一起共度时光。', 'eff37ad43cc31289_1266797983044885026_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3838, 'stand for', '/stænd fɔr/', 'stand for.mp3', 'phr.代表，象征', 'c04f659f57b2dcfbd6c0e8f21f176e57_172830_1538761034.jpg', '', 'The sign stands for a bicycle path.', '这个标识代表了自行车道。', '2f67bd77bd4799c322a7598bfbb2f0d7_12741_1538761047.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3839, 'studio', '/ˈstuːdioʊ/', 'studio.mp3', 'n.摄影棚；工作室；录音室，录像室', '54fe58191b6edffd70258b6777244500_75833_1750758059.jpg', 'd_105_4989_0_2_20150809054317.png', 'In the studio', '摄影棚里模特和摄影师正在工作。', 'us_In_the_20250121184120223_13eb1778c5b15551d34f.mp3', 'studi=study学习 + o表名词，物 → 工作室', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3840, 'subtract from', '/səbˈtrækt frʌm/', 'subtract from.mp3', 'phr.从...中减去', '36e720e6a362fb3ea8db5a42a2d9a3be.jpeg', '', 'Two subtracted from three equals one.', '三减去二等于一。', 'fc93916e6f81403c9837146632962c93.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3841, 'synthetic', '/sɪnˈθetɪk/', 'synthetic.mp3', 'adj.合成的，人造的；  n.合成物', '2065986bca66514060e2609190d57f0d_101518_1565341783.jpg', '', 'These fibers are synthetic.', '这些纤维是人造的。', 'us_These_fibers_20241009155703800_395444c0e79857aac202.mp3', 'syn共同 + the=thesis放置 + tic形容词后缀 → 放一起 → synthetic合成的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3842, 'tend', '/tend/', 'tend.mp3', 'v.照顾，照料', 'd0030a0b5200692efcbda77a47b8f2f6_184345_1701056559.jpg', 'd_107_5035_0_2_20150809011352.png', 'They tend the tree with care.', '他们小心地照料这棵树。', 'us_They_tend_20231127114243641_fde06d07ed76f1d0f6ae.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3843, 'tidy', '/ˈtaɪdi/', 'tidy.mp3', 'adj.整洁的；整齐的', 'i_16_15332_0_4_160413115745-gigapixel-scale.jpg', 'd_99_14530_0_4_20150809022606.png', 'The living room looked so tidy after mom cleaned it.', '妈妈打扫后，客厅看起来如此干净整洁。', '833e430bb8f710b5fc4a183bbeaa5546_25205_1621930474.mp3', 'tid=tide季节，时间 + y形容词后缀 → 符合季节和时间规律 → tidy整洁的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3844, 'try sth. out', '/traɪ ˈsʌmθɪŋ aʊt/', 'try sth. out.mp3', 'phr.试验（同 try out sth）', '3_0_20170721071253_80028_c.jpg', '', 'I\'m going to try out my new experiment on some mice.', '我将在小白鼠身上试验我的新实验。', '3_0_20170721071253_78715_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3845, 'typewriter', '/ˈtaɪpraɪtər/', 'typewriter.mp3', 'n.打字机', 'i_16_6860_0_5_151222140731-gigapixel-scale.jpg', '20141014_11_39_18_657_v3.png', 'The author used a typewriter to write the novel.', '作家用打字机来写小说。', 'sa_16_6860_0_5_151225173007.aac', 'type打字 ＋ writer用来打字的东西 → typewriter打字机', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3846, 'ultimate', '/ˈʌltɪmət/', 'ultimate.mp3', 'adj.根本的；最终的', '53a37bc37214a942a63c973eda8f4de8_139344_1696754203.jpg', '20141012_04_02_31_250_v3.png', 'Rainstorm is the ultimate method to deal with the severe drought in this area.', '暴雨是解决该地干旱问题的根本方法。', 'us_Rainstorm_is_20231008163723829_0c54ed997a759d31a304.mp3', 'ult(er)那边的 + im最高级后缀 + ate形容词后缀 → 最那边的，最终的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3847, 'vice', '/vaɪs/', 'vice.mp3', 'n.恶习；罪行；  adj.副的', '4b7dfd107faf8cfb5b3bee792ef8936e_141965_1732156850.jpg', '20141005_02_10_59_100_v3.png', 'Both smoking and gambling are vices. You should quit them.', '抽烟和赌博都是恶习，你们应该戒掉。', 'sa_1_5438_0_6_151112183002.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3848, 'voltage', '/ˈvoʊltɪdʒ/', 'voltage.mp3', 'n.电压', 'i_1_4225_0_2_20150808122540-gigapixel-scale.jpg', 'd_106_4225_0_2_20150809065654.png', '“Be careful', '“小心，这台机器带高压电。”', 'sa_4_4225_0_4_151223162309.aac', 'volt电压 + age表示集合名词、总称 → voltage电压', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3849, 'waiter', '/ˈweɪtər/', 'waiter.mp3', 'n.侍者，服务员', 'i_16_6776_0_4_151221183555-gigapixel-scale.jpg', 'd_13_6776_0_2_20150808192325.png', 'The young man is a waiter in a restaurant.', '这个年轻的小伙子是一家餐馆的服务员。', 'f8990b4cfd0acda1_1266883196991658538_250207.mp3', 'wait等待 + er名词后缀 → 等待着的人 → waiter侍者', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3850, 'wash', '/wɑːʃ/', 'wash.mp3', 'v.清洗；  n.洗', 'i_71_14719_0_6_151229161616-gigapixel-scale.jpg', 'd_99_14719_0_4_20150809022716.png', 'He washes his car every week to keep it clean.', '为了保持车子的整洁，他每个星期都洗车。', 'r54h547qap7rzses8ymw68blkzrtz2vy.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3851, 'weapon', '/ˈwepən/', 'weapon.mp3', 'n.武器；手段', '0dc0bb030af89ba2f1b38fce06194309_197163_1564733005.jpeg', 'd_108_5674_0_2_20150809041139.png', 'There are a number of different kinds of weapons on the floor.', '地板上有很多种不同种类的武器。', '2ec3d31ee9e197537b6d0ff645748591_39838_1564733002.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3852, 'whichever', '/wɪtʃˈevər/', 'whichever.mp3', 'det.无论哪个；  pron.无论哪些', 'a3b4118fc7ba0330a916fe9dbb836d4b_75438_1582962067.jpg', 'd_16_19604_0_2_20150809023002.png', 'I will have whichever drink is the most delicious.', '无论哪种饮料，我都要喝最好喝的。', '523fbe7b6e624a775ffb51866a2f3435_14464_1539934097.mp3', 'which哪个 + ever究竟 → whichever无论哪一个，任何一个', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3853, 'wipe', '/waɪp/', 'wipe.mp3', 'v.擦，拭，揩', 'b85fb24edd9a096ec9c09feab6e840b5_179568_1538645931.jpg', '20141014_02_01_19_177_v3.png', 'The bride wipes away the tears from the groom\'s face.', '新娘拭去了新郎脸上的泪水。', '2946431c2f6241498d26d4eb389a3593_39344_1574158072.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3854, 'wire', '/ˈwaɪər/', 'wire.mp3', 'n.电线，电缆，导线，金属丝，金属线', 'i_1_9747_0_3_20150808131444-gigapixel-scale.jpg', '20121225_19_44_21_559.png', 'It\'s a bird sitting on a wire.', '鸟停落在电线上。', '4eb136ed3ee530a0_1266883538002815944_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3855, 'wood', '/wʊd/', 'wood.mp3', 'n.木头，木材', 'cf8d78d8ea2d372c20d6693a137e80d5_190959_1577959652.jpeg', 'd_24_16630_0_3_20150808231722.png', 'Wood can be used to build houses.', '木材可以用来建造房屋。', '0d17563bd520d54a_1266883013090323204_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3856, 'accuse', '/əˈkjuːz/', 'accuse.mp3', 'v.指责；控告；把……归咎于', 'caa1ade26213bc2d69cf8f9fd75560f3_63441_1732155481.jpg', 'd_16_5643_0_2_20150808225623.png', 'They accused each other of being wrong.', '他们相互指责对方做错了。', '93e38649d69668f3_1266883379677387314_250207.mp3', 'ac=ad有关 + cuse起因；诉讼 → accuse指控', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3857, 'agenda', '/əˈdʒendə/', 'agenda.mp3', 'n.议程，议程表', 'i_1_99_0_5_150919104940-gigapixel-scale.jpg', 'd_107_99_0_2_20150809000317.png', 'What topics should we put on the agenda for our afternoon meeting?', '我们应该把哪些议题放入下午的会议议程中？', 'sa_1_99_0_3_20150808113721.aac', 'ag做，代理做 + enda表示复数 → 做的事情 → agenda议事日程', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3858, 'agree to do sth.', '/əˈɡriː tuː duː ˈsʌmθɪŋ/', 'agree to do sth..mp3', 'phr.同意做某事', '4b9bf87f925f6bb863cf506910ce72f3_92534_1538761218.jpg', '', 'The mother agrees to let her son drink some soda.', '妈妈同意让她的儿子喝点汽水。', 'e04588b6b0a6b8a9f3ac3e1689102c3f_14152_1538761229.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3859, 'aim', '/eɪm/', 'aim.mp3', 'v.瞄准，对准；力求达到，力争做到；  n.目标；对准', 'i_1_5562_0_4_150917170104-gigapixel-scale.jpg', 'd_24_5562_0_4_20150808224142.png', 'The man aims at the center of the target.', '这位男士瞄准了靶心。', '1d0e05f80297a7c7_1266883635406154704_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3860, 'almost', '/ˈɔːlmoʊst/', 'almost.mp3', 'adv.几乎，差不多', '3_0_20170707173307_46919_c-gigapixel-scale.jpg', 'd_109_19514_0_2_20150809063644.png', 'He almost reached the diamonds.', '他差一点就挖到钻石了。', '3_0_20170707173307_19571_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3861, 'alphabet', '/ˈælfəbet/', 'alphabet.mp3', 'n.字母表', '4c10672bfeb893691183e627943e1717_67786_1565705581.jpg', 'd_105_9343_0_2_20150809061437.png', 'The English alphabet has 26 letters.', '英语字母表有26个字母。', 'sa_1_9343_0_2_20150808131409.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3862, 'already', '/ɔːlˈredi/', 'already.mp3', 'adv.已经', '3_0_20170713071600_55670_c-gigapixel-scale.jpg', 'd_24_19688_0_4_20150809002534.png', 'The concert already started at 7 o\'clock', '演唱会七点就已经开始了，快点啊！', '1ebb0a9249297261792a88e9cc368d80_21518_1640243136.mp3', 'al=all全部的 + ready准备好的 → already已经', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3863, 'amaze', '/əˈmeɪz/', 'amaze.mp3', 'v.使惊奇，使惊诧', 'c15560397d779e25ff2c409b9f12d47c_148163_1720088054.jpg', '20140926_14_15_54_771_v3.png', 'The contents on the phone amazed both men greatly.', '手机上的内容让这两个人都大吃一惊。', 'jpthltwnep4raunng9g5srbjrvssyv24.mp3', 'a表加强 + maze迷宫 → 像进了迷宫一样 → amaze使诧异', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3864, 'amazed', '/əˈmeɪzd/', 'amazed.mp3', 'adj.惊奇的，吃惊的', '1a6ab66a4f2fa02c67042d17fd7594d9.jpg', '', 'They are both amazed by the splendid views.', '他们俩都对这壮丽的风景惊叹不已。', '3lf55bwpvsxgtw45sc9ga7scypfen95u.mp3', 'amaz惊奇 ＋ ed形容词后缀 → amazed惊奇的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3865, 'American', '/əˈmerɪkən/', 'American.mp3', 'adj.美国的，美国人的；  n.美洲人', '6a77f8a5782db75b8d8371ada8b07447_107949_1656662158.jpg', 'd_109_17529_0_2_20150809062234.png', 'These things are all American stuff.', '这些都是美国的东西。', 'dccd44207f38780e5185f1a215b68d64_21472_1522220084.mp3', 'Americ=America美洲 + an…的 → American美洲的，美洲人，美国人', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3866, 'ancestor', '/ˈænsestər/', 'ancestor.mp3', 'n.祖先；祖宗', 'a011761a497ce4d0ace9aed3543d7640_177250_1576914164.jpeg', 'd_16_4368_0_2_20150808224155.png', 'It\'s said that the ancestors of whales may have had four limbs.', '据说鲸鱼的祖先可能有四肢。', 'k6xpsmpwrkxsmkzkp6klfm66lc8mygef.mp3', 'an=ante前，先 + cest=cess行走，前进 + or表人 → 走在前面的人 → ancestor祖先', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3867, 'annual', '/ˈænjuəl/', 'annual.mp3', 'adj.年度的，一年一次的；  n.年鉴', '954e6ebe5bebb79991dd925d178f137c_77904_1706774209.jpeg', 'd_107_3873_0_2_20150809003253.png', 'Our company has seen a rise in annual revenues in recent years.', '近年来，我们公司的年收入不断增加。', 'bemfdz9yrjuzxcqcjjekj522tzv2kkrn.mp3', 'ann一年 + ual…的 → annual一年一度的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3868, 'apology', '/əˈpɑːlədʒi/', 'apology.mp3', 'n.道歉，歉意', 'b0bacab6b06a2e513fd9640ca6d50c43_127457_1732267236.jpg', '20130307_16_43_11_432.png', 'He is making an apology to his boss.', '他在向他的老板道歉。', 'b562975dd04ff4d1_1266883486581611138_250207.mp3', 'apo离开 + logy说话 → 退后一步说 → apology道歉', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3869, 'appeal for', '/əˈpil fɔr/', 'appeal for.mp3', 'phr.要求，呼吁', '793407a4c1a9e330285bcc7f658c8f5b_77256.jpg', '', 'Many people are on parade to appeal for government changes.', '很多人上街游行来要求政府做出改变。', 'a76c3c97d0dceddbedc578444a0665a3_41659.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3870, 'appliance', '/əˈplaɪəns/', 'appliance.mp3', 'n.家用电器，器具；装置；应用，适用', 'i_1_5315_0_3_20150808123748-gigapixel-scale.jpg', 'd_107_5315_0_2_20150809012050.png', 'I spent all my money on domestic appliances', '我把所有钱都花在像电视和冰箱这种家用电器上了。', '48kfqybyhvgxumhebmf8a35g6khlb6ds.mp3', 'apply适用 + ance表名词 → appliance家用电器，应用', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3871, 'arrive', '/əˈraɪv/', 'arrive.mp3', 'v.到达；（时间等）来临', 'i_16_17720_0_4_151110142436-gigapixel-scale.jpg', 'd_24_17720_0_4_20150808233321.png', 'She arrived at the airport on time.', '她准时抵达了机场。', 'qruqg3s7lmlb9mxdgus29r8577nc5hez.mp3', 'ar一再 + rive河 → 到达河边 → 达到目标 → arrive到达', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3872, 'as regards', '/æz rɪˈɡɑːrdz/', 'as regards.mp3', 'phr.关于', '0018af79957b2a007ef5a1acd9df93c7.jpg', '', 'As regards this book', '关于这本书，他爸爸对其给予了很高的评价。', 'f4ca7e6369e92c00977439a8377a2d00.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3873, 'Asia', '/ˈeɪʒə/', 'Asia.mp3', 'n.亚洲', 'd739d60b31b56607197dbae6ffa4d93b_69965_1656655303.jpg', '20121225_19_35_32_468.png', 'These people are all from Asia.', '这些人来自亚洲。', 'xqrryjklz5n29jeubgjawemvz4wghb38.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3874, 'aspect', '/ˈæspekt/', 'aspect.mp3', 'n.（问题等的）方面', 'a5c1a2a813fc0ea09f6156a7824f03c2_105772_1569053148.jpeg', 'd_16_7822_0_4_20150808231952.png', 'The students are recording every aspect of the plant\'s growth.', '学生们正在记录这株植物生长的各个方面。', '295d4c03d90ef24c2c074ea4d145f67c_27545_1621915085.mp3', 'a来，临近 + spect看 → 看的东西 → aspect外表，容貌，形势，方面', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3875, 'assure', '/əˈʃʊr/', 'assure.mp3', 'v.向……保证，使确信', '198ab142ece86059f1b6e13536228298_187124_1564733566.jpg', 'd_1_6210_0_4_20150808124832.png', 'I can assure you that the dog will be well cared for.', '我可以向你保证，狗会得到很好的照顾。', '21d7ff7e59a2bb81_1266883320185838152_250207.mp3', 'as一再 + sure确定 → 一再确定 → assure肯定，确信', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3876, 'at the cost of', '/æt ðə kɔːst əv/', 'at the cost of.mp3', 'phr.以...为代价', '8e17013afc0e13de3a09275aa38e40ff.jpg', '', 'He took the injured child to hospital at the cost of missing his exam. ', '他以错过考试为代价，把受伤的孩子送到了医院。', '36230a79b3ebd914996490c913c92338.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3877, 'attraction for', '/əˈtrækʃn fɔːr/', 'attraction for.mp3', 'phr.对……的吸引力', 'f7be52aafb3bae38c50863195000f5c6.jpeg', '', 'This store is a great attraction for all kinds of people.', '这家店强烈吸引了各类顾客。', 'e87e0689bbff928d0321940ef0482ed6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3878, 'avenue', '/ˈævənuː/', 'avenue.mp3', 'n.林荫道，道路', 'i_1_6673_0_18_160331113925-gigapixel-scale.jpg', 'd_16_6673_0_2_20150808230937.png', 'The avenue is lined with lush green trees.', '道路两旁，绿树成荫。', 'b503e5e4689f5065_1266883486573222528_250207.mp3', 'a向 + ven来，走 + ue → 让人可以走来走去 → avenue大路，道路', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3879, 'background', '/ˈbækɡraʊnd/', 'background.mp3', 'n.（图片、布景等的）背景；出身，经历；（事件的）背景；时代背景', '89bd958d5b3ba3e82af2089c2bcb83d2_441114_1610616001.jpg', 'd_24_5573_0_3_20150808224157.png', 'I have a photo with the sea in the background.', '我有张照片的背景是大海。', 'c2b6d888061e473cd16ed02cf202adb7_16281_1610615667.aac', 'back背后 + ground场地 → background背景，后台', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3880, 'backward', '/ˈbækwərd/', 'backward.mp3', 'adv.向后地；  adj.落后的；向后的，倒行的', '5add213cc05d851c7e8e9a9636740106_70670_1743127195.jpg', 'd_16_6278_0_2_20150808230500.png', 'He leaned backward to stretch his back after sitting for hours.', '坐了几个小时后，他向后仰伸展了下背部。', 'us_He_leaned_20250328095502603_bc773e0cfdd8200aec43.mp3', 'back后边 + ward向 → backward 向后的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3881, 'bit', '/bɪt/', 'bit.mp3', 'n.少量，小片', '0c5485f877e1f7d2b11ca11f6f90bf94_95742_1585132249.jpeg', 'd_24_17617_0_3_20150808233033.png', 'He broke the loaf into bits to feed the ducks.', '他把面包掰成小块喂鸭子。', '7e0c860497d55d720d7619e0ebdcb8b6_49216_1585132245.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3882, 'blacken', '/ˈblækən/', 'blacken.mp3', 'v.使变黑', 'c9602c6f6e17197f83c62035ddad231f_154601_1571130665.jpeg', '', 'The white cat was blackened having fallen down the chimney.', '白猫掉进烟囱里变黑了。', 'ab3a898373dfd4b3_1266883528831642478_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3883, 'blame for', '/bleɪm fɔr/', 'blame for.mp3', 'phr.归咎于', '5c1d824a55f4dc571931ffa9b7553be2.jpg', '', 'The mother blamed her son and the dog for the messy room.', '这位妈妈把杂乱的房间归咎于她的儿子和狗。', 'a0362446207b26ec9c299dab22588c1e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3884, 'blind', '/blaɪnd/', 'blind.mp3', 'adj.失明的；  v.使失明；  n.百叶窗', '5e2f45458c520a896b2949334ef1648d_123733_1535525563.jpeg', 'd_24_7992_0_3_20150808225325.png', 'The blind woman is crossing the street with her guide dog.', '这位失明的女士正和她的导盲犬一起过马路。', '5df70359fa854e2c_1266883484527385154_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3885, 'board', '/bɔːrd/', 'board.mp3', 'n.板子，木板；董事会；  v.上船（或火车、飞机、公共汽车等）', '3_0_20170714071235_85581_c-gigapixel-scale.jpg', 'd_24_5422_0_4_20150808224047.png', 'There is a board hanging on the outside of the door.', '门外挂着一块板子。', '3_0_20170714071235_11205_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3886, 'boil', '/bɔɪl/', 'boil.mp3', 'v.烧开，煮沸，沸腾', '0918ff1db0a8deea005854963a2c3a4d_90311_1533028973.jpeg', '20130301_11_00_18_606.png', 'The water is boiling in the cooking pot.', '锅里的水正在沸腾。', 'vrwmht22kllxsk68f7r62n8hjvsrmpyq.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3887, 'border', '/ˈbɔːrdər/', 'border.mp3', 'n.边界；边沿；  v.近似；毗邻；与……接壤；为……镶边', 'ba633ace0b8db00045257c2f8397f18c_204746_1524897751.jpeg', 'd_16_4760_0_2_20150808224408.png', 'There is a distinct border between the urban and the rural areas.', '城市与农村之间有一条明显的边界。', '1f7c2c7f5663da16_1266763556877654566_250117.mp3', 'bord边 + er表名词 → border边境', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3888, 'brain', '/breɪn/', 'brain.mp3', 'n.脑', 'f02a1dad06df1bdb688b8147e38b8693_90986_1577947731.jpeg', 'd_24_17203_0_4_20150808232344.png', 'Your brain is the organ inside your head that controls your body\'s activities.', '大脑是在你的脑袋里控制身体活动的器官。', '5ef428699544456ab1d7eef29527565b_43822_1577947725.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3889, 'break up', '/breikʌp/', 'break up.mp3', 'phr.关系破裂，离异，结束，散会，解散，驱散，衰弱', 'breakup_10463_20231106_20be484d.jpg', '', 'Please don\'t break up with me - I love you', '请别和我分手-我爱你，我可以改！', 'cjugnq7pg8aja94neg3ucxgjr9q49nug.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3890, 'brilliant', '/ˈbrɪliənt/', 'brilliant.mp3', 'adj.聪颖的；卓越的', 'i_1_4387_0_3_20150808122716-gigapixel-scale.jpg', '', 'This girl is so brilliant that she can solve the difficult problem.', '这个小女孩很聪明，她能解决这道难题。', '9ecc61b916a85b87_1266883008328280968_250207.mp3', 'brilli=brill光辉 + ant…的 → brilliant光辉的；卓越的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3891, 'bring about', '/brɪŋ əˈbaʊt/', 'bring about.mp3', 'phr.导致，引起', 'c35d798bbd9a93d0f12a4bb2b08a4d54_175415_1542877818.jpg', '', 'Such a small issue brought about a quarrel between the kids.', '一点小事引发了孩子间的争吵。', '7w7kqz9at25agc93yrh32w683v84gjhu.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3892, 'bring forth', '/brɪŋ fɔːrθ/', 'bring forth.mp3', 'phr.产生', '48c8b092fb29bdcc5c160711ae758d67_122147_1630029841.jpeg', '', 'This apple tree always brings forth lots of fruit.', '这棵苹果树总是结出很多果实。', '0fff4f16e851ee97a1e3a3682c50ed36.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3893, 'budget', '/ˈbʌdʒɪt/', 'budget.mp3', 'n.预算；  v.预算，安排；  adj.低廉的', 'i_1_7135_0_4_20150808125816-gigapixel-scale.jpg', 'd_107_7135_0_2_20150809021519.png', 'The total amount on the shopping list is over my budget.', '购物清单的总额超出了我的预算。', '751768e36a24e0c1222fdfa3de730d1f_24737_1621931148.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3894, 'by itself', '/baɪ ɪtˈself/', 'by itself.mp3', 'phr.单独地', '14715e57a84f784ce130e1506e2c62d4.jpg', '', 'The washing machine will start by itself in a few minutes. ', '洗衣机将在几分钟后自动启动。', 'd46fa7af64c5b7ba734f977793cc8c96.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3895, 'call on', '/kɔːl ɑːn/', 'call on.mp3', 'phr.要求（某人讲话等）', '2dda134a23bdcab2bd7b871d67841b45_407600_1604732222.jpg', '', 'He calls on a student to answer his question.', '他请一个学生回答他的问题。', 'sa_16_7688_0_7_20150808231922.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3896, 'canal', '/kəˈnæl/', 'canal.mp3', 'n.运河，河流', '2c04f25fa6f164a356dfad9e8e2f42bb_75077_1565341785.jpg', 'd_105_4002_0_2_20150809053651.png', 'There are many canals running through the city.', '这座城市有很多运河穿流其中。', 'z9dd3wtngnsxbl8adu9mz9rczy7z2qa6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3897, 'carpet', '/ˈkɑːrpɪt/', 'carpet.mp3', 'n.地毯', 'ec9283a93588b64d43f01b4fab240b0f_151616_1587458466.jpg', 'd_24_8028_0_3_20150808225355.png', 'I put my books on the carpet.', '我把我的书放在了地毯上。', '63b8d55cf47dd08a_1266883329686416148_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3898, 'catch', '/kætʃ/', 'catch.mp3', 'v.抓住', 'i_66_12039_0_4_20150809021552.jpg', 'd_73_12039_0_4_20150809023257.png', 'She enjoys catching butterflies.', '她可喜欢捉蝴蝶了。', 'faebf21bfe742ad2_1266763310326328096_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3899, 'chance', '/tʃæns/', 'chance.mp3', 'n.机会；偶然；  v.偶然发生；冒险；  adj.偶然的', '7df3cc373495b291afcb07a8c6676fa6_133554_1657611168.jpg', 'd_24_17247_0_3_20150808232518.png', 'I have a chance to win the prize.', '我有机会赢得这个奖品。', '4d0915b47c45846d_1266798140536368046_250123.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3900, 'cheap', '/tʃiːp/', 'cheap.mp3', 'adj.便宜的；低劣的，不值钱的', '3_0_20160603095502_13954_c-gigapixel-scale.jpg', 'd_24_19566_0_4_20150809002032.png', 'You won\'t find cheaper carrots than this anywhere!', '你再也找不到比这更便宜的胡萝卜了！', '5f07faa7809f2a4a_1266763311312120644_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3901, 'chest', '/tʃest/', 'chest.mp3', 'n.胸膛，胸部', 'a6b17545b619fd3fe1e3b3553dedc941_123165_1731403791.jpg', '', 'The doctor conducted a chest examination.', '医生进行了胸部检查。', 'db25b1e10c3f869b_1266883012909423358_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3902, 'clear up', '/klɪr ʌp/', 'clear up.mp3', 'phr.放晴', '8c42dcec606937891976032e0117b0f9_186082_1580883212.jpg', '', 'The sky clears up after the rain has fallen.', '雨后的天空放晴了。', 'e0a965ae2f590db57a79bed185914e6a_41710_1580883205.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3903, 'coarse', '/kɔːrs/', 'coarse.mp3', 'adj.粗糙的；粗俗的；粗鲁的', '9203b0d51dae3f07a54566fd0ea221a5_193990_1583834331.jpeg', '', 'Poor people used coarse cloth to make clothes in ancient China.', '在中国古代，穷人用粗糙的布料制作衣服。', '8w6gdwtcxtu3xu3gkrcs5mcrnbz59b4v.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3904, 'collective', '/kəˈlɛktɪv/', 'collective.mp3', 'adj.集体的，共同的；  n.集体', 'c_i_512_1_0_2_150709105816-gigapixel-scale.jpg', 'd_107_512_0_2_20150809000838.png', 'Class fund is collective property. It needs everybody to contribute.', '班费是集体财产，它需要每个人的贡献。', 'sa_1_512_0_4_150923113832.aac', 'col一起 + lect选择，收集 + ive……的 → 集中到一起 → 集体的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3905, 'come across', '/kəm əˈkrɔs/', 'come across.mp3', 'phr.偶然遇到', 'ab37fb701902bd8107a46e5124ca3669_100668_1605181361.jpg', '', 'They #came across# each other on the way to walk their dogs.', '他们在遛狗的路上碰到了对方。', 'd3ac3897326cd3c9b36e12b97ffbf110_18540_1605180659.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3906, 'compare to', '/kəmˈpɛr tu/', 'compare to.mp3', 'phr.与……相比', 'e21e84538f7fdcaef1cec496e255e6e3_85957_1579334038.jpg', '', 'Compared to her brother', '跟她哥哥比起来，她要矮一点。', 'bad9c02de6eee16176757421e29ce814_35230_1579334035.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3907, 'concert', '/ˈkɑnsərt/', 'concert.mp3', 'n.音乐会，演奏会', '1ae76a4ba34c086109ff6ac0a5985959_93616_1688546204.jpg', 'd_24_8443_0_4_20150808225725.png', 'I went to the concert. It was awesome.', '我去了那场音乐会。真的棒极了。', 'us_I_went_20230705163754148_a5dd1073116f9a19ddaf.mp3', 'con一起 + cert歌唱 → 一起歌唱 → concert音乐会', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3908, 'confirm', '/kənˈfɜːrm/', 'confirm.mp3', 'v.证实；确认，使确信；批准', '3_18_20161220102910_20382_c-gigapixel-scale.jpg', 'd_16_5642_0_7_20150808225621.png', 'The X-ray picture confirmed that he had broken his finger.', 'X光影像证实他的手指已经骨折。', '6f4f36ee14732ef0_1266883628792982382_250207.mp3', 'con共同 + firm坚定 → confirm证实；坚定', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3909, 'confuse', '/kənˈfjuːz/', 'confuse.mp3', 'v.使混乱，使迷糊', 'i_1_4501_0_4_150924104126-gigapixel-scale.jpg', 'd_16_4501_0_2_20150808224302.png', 'I always confuse the girl with her twin sister.', '我一直把那个女孩和她的双胞胎姐姐搞混。', '53d42fdd6f8191f8_1266883375755385450_250207.mp3', 'con一起 + fuse流 → confuse混淆，使困惑', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3910, 'conscious of', '/ˈkɑːnʃəs əv/', 'conscious of.mp3', 'phr.意识到的，关注的', '14f3b2b875e263e2900f0f3e69f1fb2d.jpeg', '', 'Conscious of the show being about to start', '意识到节目即将开始，他调整了领带并微笑。', '932708c53eb05ec66eb79c6705027116.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3911, 'content with', '/ˈkɑnˌtɛnt wɪð/', 'content with.mp3', 'phr.对...满意的，满足的', '70f1aafb266f67c6e99cd1095a9ca331.jpeg', '', 'The director is content with the filming of this scene.', '导演对这一幕的拍摄很满意。', '30bfd96d649c9ad816b882b22567671b.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3912, 'contest for', '/ˈkɑnˌtɛst fɔr/', 'contest for.mp3', 'phr.争夺', '892df8d86160d4493c6ddf005fb02ea0_104700_1712714943.jpg', '', 'They are contesting for the championship.', '他们正在争夺冠军。', 'us_They_are_20240410100907578_d9ffcd4251c90a9382fd.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3913, 'courage', '/ˈkɜːrɪdʒ/', 'courage.mp3', 'n.勇气，胆量', '74cfeafe22002a126a57e5eed47e2b95_98332_1522722652.jpg', '20130105_10_18_00_310.png', 'It needs a lot of courage for the little girl to climb the rock wall.', '小女孩攀登这块岩壁需要很大的勇气。', '5c9adbc4ac6e315f83aa895f6f9ce5ed_40122_1522722644.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3914, 'cousin', '/ˈkʌzn/', 'cousin.mp3', 'n.堂（或表）兄弟（姐妹），同辈表亲（或堂亲）', '9d7c65e60c0d951a4f6fc72ee4f57d5d_198426_1577950653.jpeg', 'd_76_12274_0_4_20150809030840.png', 'The boy likes to play with his little cousin.', '男孩喜欢和他的小表妹一起玩。', '359c7c93457492fc_1266763243948059618_250117.mp3', 'cou=com共同 + sin姐妹 → 共同的兄弟姐妹 → cousin堂/表兄弟/姐妹', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3915, 'crazy', '/ˈkreɪzi/', 'crazy.mp3', 'adj.疯狂的，荒唐的', 'f1f05d2b5ce667c64a90adbe09d1ed0e_53031_1656922257.jpg', 'd_24_8902_0_4_20150808225921.png', 'The crazy man wears a watermelon as a hat.', '那个疯狂的男人把西瓜当帽子戴。', 'c4a7e6225e6d0637_1266798144696834776_250123.mp3', 'craz=craze发狂 + y表形容词  → 发狂的  → crazy疯狂的，荒唐的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3916, 'cut down', '/kʌt daʊn/', 'cut down.mp3', 'phr.减少，削减', '20121027_03_17_35_445.jpg', '', 'Because of the recession', '因为不景气，我们已经不得不削减我们的开支。', 'mjjl4nuv42fyvm683xj5hknpef5gyw9k.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3917, 'definite', '/ˈdefɪnət/', 'definite.mp3', 'adj.明确的，肯定的', '58d601237bf8e104f88874cea886fa50_187667_1571023235.jpeg', 'd_1_783_0_2_20150808121556.png', 'The police found definite proof that he committed the crime.', '警方已经掌握明确证据，可以证明是他实施了犯罪。', 'f34760c02587aaa3_1266883114122828472_250207.mp3', 'defin明确 + ite形容词后缀 → definite明确的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3918, 'delay', '/dɪˈleɪ/', 'delay.mp3', 'v.延误，延迟；磨蹭，使迟到', '3_0_20170714071221_90924_c-gigapixel-scale.jpg', 'd_16_5175_0_2_20150808225109.png', 'His flight is delayed because of bad weather.', '他的航班由于恶劣的天气晚点了。', '3_0_20170714071221_9216_c.aac', 'de从...离开 + lay留下，停留 → delay延迟', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3919, 'depend', '/dɪˈpend/', 'depend.mp3', 'v.依靠', 'i_1_5087_0_2_20150808123450-gigapixel-scale.jpg', 'd_24_5087_0_3_20150808223911.png', 'Sometimes people have to depend on others for help.', '有时候，人们不得不依靠他人的帮助。', 'd4a26dedc4117e96_1266883328297753338_250207.mp3', 'de加强 + pend挂  → 挂在...上面  → depend依靠；依赖', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3920, 'deserve', '/dɪˈzɜːrv/', 'deserve.mp3', 'v.值得，应得；应受', '00fe69f5739ddd10baf54ddab4a0ba7c_32523_1701915294.jpg', 'd_24_4461_0_3_20150808223533.png', 'She deserves a pat on the back for all her hard work.', '她工作兢兢业业，值得嘉许。', 'us_She_deserves_20231207101529827_8fc97b4bed2457eea426.mp3', 'de加强语气 + serve为…服务 → deserve值得，应得', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3921, 'disabled', '/dɪsˈeɪbld/', 'disabled.mp3', 'adj.有残疾的；丧失能力的', 'dde44e6fef0a5ce1d8fa0ce9b3fdbe37_93154_1574844458.jpeg', '20141010_00_51_44_905_v3.png', 'These two young people are disabled but can still play basketball.', '这两个年轻人虽然残疾了，但仍能打篮球。', 'fe29e2ee2542de28c0d6de07b6c567b5_47120_1603271664.mp3', 'dis没有 + abl=able能力 + ed形容词后缀 → 伤残的，丧失能力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3922, 'disappointed', '/ˌdɪsəˈpɔɪntɪd/', 'disappointed.mp3', 'adj.失望的，沮丧的', '1dbb23ed9c4d6268e35f4a42a82e9776_156001_1574766034.jpeg', 'd_24_889_0_3_20150808223138.png', 'He felt quite disappointed about his test score.', '他对他这次的考试成绩失望透顶。', 'ac5fe0182f234e0c_1266883370009734010_250207.mp3', 'dis非，不是 + appoint约定 + ed形容词后缀 → disappointed失望的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3923, 'divide by', '/dɪˈvaɪd baɪ/', 'divide by.mp3', 'phr.用……除（尽）', 'e65449565250ea030fade1e463660c3b.jpg', '', 'Divide eight by two', '用8除以2，我们就得到4。', '58cd53150ebe1e7f9adb382519cc1c47.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3924, 'due to', '/duː tuː/', 'due to.mp3', 'phr.由于', 'ff7486765ca4a161fb6c1d201efb87c4_106404_1538754166.jpg', '', 'She cannot hear things clearly due to her old age.', '由于年岁过高，她的耳朵听不太清。', '328d235782b336a2_1266883487119158130_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3925, 'dusk', '/dʌsk/', 'dusk.mp3', 'n.黄昏，傍晚', 'i_1_8564_0_4_150924172626-gigapixel-scale.jpg', 'd_24_8564_0_4_20150808225817.png', 'I enjoy watching the sunset at dusk.', '我很享受在黄昏时看日落。', 'sa_1_8564_0_2_20150808130859.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3926, 'earn', '/ɜːrn/', 'earn.mp3', 'v.挣得，挣钱', 'da8c554f27967f7209a2624285fef894_90588_1588139248.jpeg', '20121225_20_15_02_148.png', 'She earns some extra money by doing a part-time job.', '她通过做兼职赚了一些外快。', 'fu3a22zvl3tvr9lt3thce575ufnfuxbg.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3927, 'effect', '/ɪˈfekt/', 'effect.mp3', 'n.效果；影响；结果；  v.使发生', '1425952698328-gigapixel-scale.jpg', 'd_16_7879_0_6_20150808232039.png', 'That lighting effect makes the stage look very mysterious.', '那种灯光效果使舞台看起来很神秘。', '873edccdfcd5ed2a_1266883478896421778_250207.mp3', 'ef出 + fect做，制作 → 做出来 → effect实施，生效；效果', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3928, 'effect on', '/ɪˈfekt ɑːn/', 'effect on.mp3', 'phr.对……的影响', '4db4dd912b7ced1fc4ea578af9b916bc.jpg', '', 'Dry weather has an important effect on plants.', '干旱天气对植物有重要影响。', 'd50966cbce76c59e74389d0be53f0822_46112_1593585033.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3929, 'elevator', '/ˈelɪveɪtər/', 'elevator.mp3', 'n.电梯', 'dfbd5e3fd51cbebc9f5195e04f3e76dc_165103_1552896709.jpeg', 'd_24_7067_0_3_20150808224916.png', 'The three people are waiting for the elevator.', '这三个人正在等电梯。', '684jf32snl5gx28v9wpsu5bcdxgtgy4e.mp3', 'elevat升高 + or名词后缀 → elevator电梯', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3930, 'emotional', '/ɪˈmoʊʃənl/', 'emotional.mp3', 'adj.情绪激动的，感动的', 'ebefcdfb5be625b8bd2efcd2eec9f2b8_99378_1724401728.jpg', 'd_1_8209_0_2_20150808130502.png', 'He gets emotional seeing a fan propose to his girlfriend. ', '看到粉丝向女友求婚，他十分感动。', 'us_He_gets_20240823162908234_4be36219cd0fc77cb0de.mp3', 'emotion情感 + al形容词后缀 → emotional情感上的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3931, 'emphasize', '/ˈemfəsaɪz/', 'emphasize.mp3', 'v.强调；着重；使突出', '94e1bf526012f377490edd7d5ed1360c_68940_1565342159.jpg', 'd_107_4508_0_2_20150809005858.png', 'I want to emphasize the importance of teamwork.', '我想强调团队合作的重要性。', '3_65_20170608175627_96726_c.aac', 'emphasi=emphasis强调 + ize动词后缀 → emphasize强调', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3932, 'equip with', '/ɪˈkwɪp wɪð/', 'equip with.mp3', 'phr.用……装备起来', '33fe600628b4a72cfe7785afea88af37.jpg', '', 'He equipped his living room with a security camera.', '他在客厅里安装了一个安全摄像头。', '396f485f111cabc4dbbfb01d37b38639.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3933, 'exert', '/ɪɡˈzɜːrt/', 'exert.mp3', 'v.尽（力），运用，发挥', 'c49500ab431de958c36e4c55ff6818b6_65691_1565320285.jpg', 'd_1_4341_0_2_20150808122640.png', 'I exerted all my strength to lift all the boxes.', '我用尽全力抬起所有箱子。', 'sa_1_4341_0_4_150923164353.aac', 'ex向外 + ert连接 → exert尽力', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3934, 'expose', '/ɪkˈspoʊz/', 'expose.mp3', 'v.显露，暴露；揭露', '3_0_20171001071546_19216_c-gigapixel-scale.jpg', 'c2bf38d592e42f31b85a580669986fb2_59469_1551253309.png', 'Some cement fell from the wall', '墙上的水泥掉下来后，砖块露了出来。', '3_0_20171001071546_52613_c.aac', 'ex出，出去 + pose放 → 放出去 → expose暴露', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3935, 'factory', '/ˈfæktəri/ /ˈfæktri/', 'factory.mp3', 'n.工厂，制造厂', '4b0ea5eb67339cb385d6424d77ff0b26_255643_1656998542.jpg', 'd_24_17204_0_4_20150808232346.png', 'There are many workers working in the factory.', '有许多工人在工厂工作。', '6b4d283c8902586a_1266883327259400936_250207.mp3', 'fact做 + ory场所，地点后缀 → 做东西的场所 → factory工厂', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3936, 'fail', '/feɪl/', 'fail.mp3', 'v. 不及格', 'fd391ea01753069c0f4fd410340762aa_42638_1709782521.jpg', '20130301_11_02_53_78.png', 'Sadly', '非常遗憾，他这次考试没有及格。', 'us_Sadly_he_20240307111507775_dc186fd4329db626d4fe.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3937, 'failure', '/ˈfeɪljər/', 'failure.mp3', 'n.失败者', '5e0a0848dc217d969a81ed45a5c0110e_61382_1565344239.jpg', 'd_24_7132_0_4_20150808224957.png', 'If I can\'t increase sales', '如果不能增加销售额，我就是一个失败者！', 'sa_1_7132_0_2_20150808125814.aac', 'fail犯错误，欺骗 + ure名词后缀 → 错误状态 → failure失败', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3938, 'fatal', '/ˈfeɪtl/', 'fatal.mp3', 'adj.灾难性的，毁灭性的；致命的；决定性的', '3_0_20160720071646_60332_c-gigapixel-scale.jpg', 'd_107_4587_0_2_20150809010151.png', 'Nobody survived the fatal accident.', '在这场毁灭性的事故中，无人幸免。', '522dd613a05d1383e1ccca7bd1b1097d_13525_1619167839.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
