INSERT INTO `words` VALUES (3941, 'festival', '/ˈfestɪvl/', 'festival.mp3', 'n.节日；活动', 'd64df11c320ddb20906a3b24e30d629e_124600_1564805070.jpg', 'd_100_12701_0_4_20150809032502.png', 'Traditionally people spend time with their families during the Chinese Spring Festival.', '人们历来在春节期间与家人共度时光。', 'y9pqhuckqw4ulce7md3mem3k89u7jd6p.mp3', 'fest节日；祝宴 +ival表名词 → festival节目，宴会', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
