INSERT INTO `words` VALUES (3947, 'foreign to', '/ˈfɔrɪn tu/', 'foreign to.mp3', 'phr.与……无关；感到陌生', '765e4f660b46cab63cd930b4beb44938.jpeg', '', 'The concept of geometry seemed foreign to them.', '几何的概念对于他们来说太陌生了。', '51157b1b41e81ce11f96e7d85dfac8a0.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3948, 'forgive', '/fərˈɡɪv/', 'forgive.mp3', 'v.饶恕', 'f46e43f1291678b20094bb5495243f96_99968_1588085410.jpeg', 'd_24_4177_0_4_20150808223452.png', 'The kitty has forgiven its master for hugging other cats.', '小猫原谅主人抱了别的猫。', '1b156b1757526838_1266883482283060206_250207.mp3', 'for完全地 + give给予 → forgive饶恕', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
