INSERT INTO `words` VALUES (3954, 'get together', '/ɡet təˈɡeðər/', 'get together.mp3', 'phr.聚集；汇集；开会', 'd499bb933890a2092b5e33622ab41665_145521_1701670039.jpeg', 'd_16_17594_0_2_20150809011715.png', 'The whole family got together for my birthday.', '全家人为了庆祝我的生日，而聚在一起。', '8d335a83a016486f_1266883323260000930_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
