INSERT INTO `words` VALUES (3960, 'hill', '/hɪl/', 'hill.mp3', 'n.小山，山岗', 'd686e8c91600d21ca8e4221b9ce21227_195230_1578560010.jpeg', 'd_24_17324_0_3_20150808232715.png', 'There is a red house on the top of that green hill.', '在那绿色小山的山顶上有一所红房子。', 'a8832cc00bcba777_1266763553609439958_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3961, 'horizon', '/həˈraɪzn/', 'horizon.mp3', 'n.地平线；眼界，见识', 'i_1_4112_0_3_20150808122346-gigapixel-scale.jpg', 'd_1_4112_0_3_20150808122346.png', 'The sun is slowly rising from the horizon.', '太阳从地平线上缓缓升起。', 'sa_1_4112_0_3_20150808122346.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
