INSERT INTO `words` VALUES (3970, 'initial', '/ɪˈnɪʃl/', 'initial.mp3', 'adj.字首的；最初的，开始的；  n.（单词）首字母', '9edaa32d13614a9f4507639242ca79fa_165886_1576306098.jpg', 'd_107_16703_0_2_20150809025740.png', 'The initial letter of this word is a.', '这个单词的首字母是“a”。', 'bb16c832e47a0b445d770b6bc2f83cd1_36094_1576306100.mp3', 'in进入 + it行走 + ial形容词后缀 → 走进 → initial开始的，最初的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3971, 'inspection', '/ɪnˈspekʃn/', 'inspection.mp3', 'n.检查，细看', '50b5d12921a3fd03ff033da14bd87051_183142_1566007925.jpg', '', 'The mechanic gave the car a thorough inspection according to the check list.', '技工根据检查清单对汽车进行了一次全面检查。', 'us_The_mechanic_20230821095606288_5f5ad7458fa893a083ad.mp3', 'inspect视察 + ion表名词 → 视察；认真看', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3972, 'interior', '/ɪnˈtɪriər/', 'interior.mp3', 'adj.内部的；  n.内部', 'c_i_wm_20120503_03_50_59_22-gigapixel-scale.jpg', 'd_107_6116_0_2_20150809014957.png', 'The interior furnishing of the living room is very delicate.', '客厅的内部装潢十分精致。', 'sa_1_6116_0_3_20150808124654.aac', 'inter内 + ior表形容词，较...的 → interior内部的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3973, 'intimate', '/ˈɪntɪmət/', 'intimate.mp3', 'adj.亲密的，密切的；详细的；  v.宣布，通知（读作/ˈɪntəˌmeɪt/）；  n.密友，知己', 'e3b198b0a943be93137f7911b72e4309_93498_1538658256.jpg', 'd_1_1636_0_3_20150808121729.png', 'They are very intimate friends.', '她们是非常亲密的朋友。', 'cc63c7c3959353ce21e80e6c150f6bd1_18185_1621914987.mp3', 'intim内心的 + ate……的 → 内心的 → 亲近的；不说出口的 → intimate亲密的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3974, 'knee', '/niː/', 'knee.mp3', 'n.膝盖', 'i_13_18147_0_2_20150808205349-gigapixel-scale.jpg', 'd_24_18147_0_4_20150808235014.png', 'Coach', '教练，我伤到了膝盖！我们有冰块来敷吗？', 'fbtmtva33nluf4mww9u5yhn5xywsk8pl.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3975, 'leading', '/ˈliːdɪŋ/', 'leading.mp3', 'adj.首位的，居前的；主角的', '86cc4e4b3b174a6e1862a21638c0d81f_163846_1605086228.jpg', '20140710_16_46_23_931_v3.png', 'The leading cyclist was starting to pull away from the rest.', '领先的骑手渐渐甩开了其他人。', 'sa_1_4945_0_4_20150808123214.aac', 'lead领导 + ing...的 → leading指导的；最主要的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3976, 'learn from', '/lɜrn frəm/', 'learn from.mp3', 'phr.向......学习', '0dd64f091dfa83aec3861b0a4229af32.jpg', '', 'The boy learnt how to play basketball from his father.', '小男孩从父亲那里学会了打篮球。', 'eab81292bb5aa5db_1266883375153240652_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3977, 'learning', '/ˈlɜːrnɪŋ/', 'learning.mp3', 'n.学习；知识', 'i_1_4974_0_6_150919110243-manual-scale.jpg', 'd_1_4974_0_4_20150808123246.png', 'Mom often helps me with my learning.', '妈妈经常在学习上给我帮助。', 'sa_1_4974_0_6_150923120534.aac', 'learn学习 + ing行业，状态，行为 → learning学问', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3978, 'leave for', '/liv fɔr/', 'leave for.mp3', 'v.动身去', '010ff700b0bd4117d0e77b214067ac8c_131575_1585057906.jpeg', '', 'The family are leaving for their vacation by the sea.', '这一家人动身去海边度假了。', '2d6f191f48cc3a774ed2e9f93f2d8e09_45544_1585057904.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3979, 'liquid', '/ˈlɪkwɪd/', 'liquid.mp3', 'n.液体；  adj.液体的，液态的', '02a16385a0e948fd3aa6e7c0862de5e7_84853_1701054471.jpg', '20141013_03_37_55_581_v3.png', 'Liquid', '液体，比如说水，可以自由地流动。', '91d32c6b9597066e_1266883490455858116_250207.mp3', 'liqu湿 + id表形容词 → liquid流体的，液态的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3980, 'locate', '/ˈloʊkeɪt/', 'locate.mp3', 'v.找出……的位置', '3_0_20160718113752_42996_c-gigapixel-scale.jpg', 'd_107_6165_0_2_20150809015137.png', 'We have located the robber; he\'s currently waiting by the river.', '我们已经找到了劫匪的位置，他现在就在河边等着。', '3_0_20160718113752_21223_c.aac', 'loc地方 + ate表动词 → 找到地方 → locate探明；查出', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3981, 'location', '/loʊˈkeɪʃn/', 'location.mp3', 'n.位置，地点；定位；外景拍摄地', 'i_1_5661_0_2_20150808124157-gigapixel-scale.jpg', 'd_18_5661_0_2_20150808184623.png', 'I found the location on the map.', '我在地图上找到了这个位置。', '8gy5hpzn7p4cve4vlahj9t867mr2a6ye.mp3', 'loc地方 + ation行为、状态、过程 → location位置，场所', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3982, 'look over', '/lʊk ˈoʊvər/', 'look over.mp3', 'phr.检查', 'ddf102bfed6a863c9969d66e5790b80b_200509_1588929289.jpeg', '', 'He looked over the contract before he signed it.', '他在签合同前仔细检查了一番。', 'a4762400f89174c4ff1519f020498730_50080_1588929286.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3983, 'mad', '/mæd/', 'mad.mp3', 'adj.异常狂暴的；生气的，狂怒的；精神错乱的；蠢笨的；  n.狂怒', 'i_16_7873_0_5_160204144010-gigapixel-scale.jpg', '', 'He got mad with so much work.', '如此多的工作令他发狂。', '96978f2fc881de7778dcde2578d0abae_42656_1603271640.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3984, 'magazine', '/ˈmæɡəziːn/', 'magazine.mp3', 'n.杂志，期刊', 'a8fbd42f699ec2e8a8a2f11c626019a7_89589_1535177589.jpeg', '20130307_16_41_24_977.png', 'The girl spent her afternoon reading a magazine.', '这个女孩读着杂志度过了午后时光。', '5fe452d43ac0dec8_1266763450778299164_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3985, 'material', '/məˈtɪriəl/', 'material.mp3', 'n.材料，原料；  adj.物质的，客观存在的', 'c_20150618_164928_1_8101-gigapixel-scale.jpg', 'd_16_8101_0_2_20150808232556.png', 'She has prepared the cooking material for lunch.', '她已经准备好了午餐的烹饪原料。', 'c_sa_8101_1_0_2_150715161158.aac', 'mater=mother母亲，起源 + ial → 各种物品的起源 → 原材料', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3986, 'meal', '/miːl/', 'meal.mp3', 'n.一餐，一顿饭', 'd217337f81c9cf5afb8449f6f3c50882_133913_1575010221.jpeg', 'd_96_13386_0_4_20150809014403.png', 'The family enjoyed a tasty meal.', '这家人享受了一顿美餐。', '77d158fb951084a6_1266763402361526808_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3987, 'memorial', '/məˈmɔːriəl/', 'memorial.mp3', 'n.纪念物，纪念碑，纪念仪式；  adj.记忆的', '14f8e0b820bd761ba9ef73bf97610a3e_130595_1522721390.jpg', 'd_107_9485_0_2_20150809024647.png', 'The memorial of Confucius is built to remind us of his achievements.', '修建孔子纪念碑是为了让我们记住他的成就。', 'us_The_memorial_20241009155109659_5707714e32b8191a6f7f.mp3', 'memor记忆 + ial形容词后缀，…的 → memorial记忆的；纪念物，纪念日', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3988, 'mention', '/ˈmenʃn/', 'mention.mp3', 'v.提到，提及；  n.谈到，提及', '5c6ae93c0be2b5356a2abe22b93d5055_157177_1750752116.jpg', 'd_24_7486_0_3_20150808225113.png', 'She mentioned her child during their conversation.', '她在谈话中提到了她的孩子。', 'ef701153d382ec6d_1266883320372439880_250207.mp3', 'ment思考，神智 + ion名词后缀 → 有思考 → mention想到，提到', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3989, 'minus', '/ˈmaɪnəs/', 'minus.mp3', 'prep.减，减去；  adj.负的；  n.缺点', '1086c99da1a771c7feae8408b1629df9_86347_1577946231.jpeg', '20141015_14_21_41_344_v3.png', 'Seven minus one is six.', '7减1等于6。', 'b7c9b7f9c0d1782fa37f4e3f4511a6f2_29614_1577946229.mp3', 'min小 + us用 → 变少 → minus减去', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3990, 'misunderstand', '/ˌmɪsʌndərˈstænd/', 'misunderstand.mp3', 'v.误解，误会', '3_0_20160520172744_26581_c-gigapixel-scale.jpg', 'd_16_8595_0_2_20150808233247.png', 'He misunderstood the way of making smoked meat.', '他误解了做烟熏肉的方法。', 'vmxt7qwte2hsjb5zq2ep534hf7p9aah8.mp3', 'mis错误，坏 + understand理解 → misunderstand误解', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3991, 'mixture', '/ˈmɪkstʃər/', 'mixture.mp3', 'n.混合物，混合剂（或液）', 'i_1_9101_0_4_151022155916-gigapixel-scale.jpg', 'd_107_9101_0_2_20150809024224.png', 'The fruit salad is a great mixture and looks good.', '这份水果沙拉是一份大杂烩，看起来很美味。', 'mknnzkbwreja953wfjl7nuyg3j78alnl.mp3', 'mix混合 + ture表名词 → mixture混合物', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3992, 'moderate', '/ˈmɑːdərət/', 'moderate.mp3', 'adj.中等的，适中的', '354ccaa5fa8031414bdedd84f2ba1661_96701_1585131469.jpeg', 'd_1_4114_0_2_20150808122349.png', 'The yellow area indicates moderate power output.', '黄色区域表示中等功率输出。', '2b883df2982cc36b7868bb15da64235a_49284_1585131466.mp3', 'moder方式，模式，风度 + ate形容词后缀 → 做事有风度 → moderate适度的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3993, 'narrow', '/ˈnæroʊ/', 'narrow.mp3', 'adj.狭窄的，窄小的；  v.（使）变窄；  n.海峡', 'i_1_7920_0_7_151110144644-gigapixel-scale.jpg', 'd_24_7920_0_4_20150808225231.png', 'The fat man is wondering how to pass through the narrow alley.', '那个胖子正在纠结如何才能穿过那条窄巷。', '392bff736ca0aae6_1266883481806002938_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3994, 'no doubt', '/noʊ daʊt/', 'no doubt.mp3', 'phr.无疑地', 'i_16_19310_0_4_151204120249.jpg', '', 'There is no doubt that the answer is four.', '毫无疑问，这个答案是4。', 'sa_16_19310_0_4_151125175000.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3995, 'noble', '/ˈnoʊbl/', 'noble.mp3', 'adj.贵族的，高贵的；  n.贵族成员', 'e193ce0fedaf90703e0cdb827856e5ab_222217_1706498570.jpg', 'd_16_6690_0_5_20150808230942.png', 'The woman in the expensive dresses comes from a noble family.', '这位穿着昂贵衣服的女人出身高贵。', '23f09a8137a3742c_1266883627083410238_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3996, 'nowhere', '/ˈnoʊwer/', 'nowhere.mp3', 'adv.任何地方都不', '685602ad190ba58d168d503980c25545_110695_1580870253.jpg', 'd_1_4004_0_2_20150808122222.png', 'He looked everywhere in the room', '他在房间里到处找，但哪里都找不到钥匙。', '754d374ee5fecb87_1266883011363908584_250207.mp3', 'no无 + where哪里 → nowhere无处', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3997, 'off duty', '/ˈɔːf ˈdjuːti/', 'off duty.mp3', 'phr.下班的', '39fad1ff9db7a3bed17b867a119ce4c4.jpeg', '', 'When she\'s off duty', '下班后，她的主要爱好是自然摄影。', 'a3dcd928f66fbf60aa72edae6f68e090.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3998, 'once more', '/wʌns mɔr/', 'once more.mp3', 'adv.再一次', '3_0_20160718113154_76443_c.jpg', '', 'I will write the word once more.', '我再写一遍这个单词。', '3_0_20160718113154_94641_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (3999, 'once upon a time', '/wʌns əˈpɑːn ə taɪm/', 'once upon a time.mp3', 'phr.很久以前，从前', 'dac996c51e763bfc8f30470fea186183_205560_1605082198.jpg', '', 'My grandma used to tell stories for us: once upon a time', '过去奶奶经常为我们讲故事：很久以前，有一位公主吻了一只会魔法的青蛙。', '3_41_20170325163845_58902_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4000, 'ought', '/ɔːt/', 'ought.mp3', 'v.应该，应当，本该', '3_0_20170703171657_67339_c-gigapixel-scale.jpg', '20121225_18_53_36_336.png', 'You ought to wash your hands first.', '你应该先去洗手。', '3_0_20170703171657_36186_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4001, 'park', '/pɑːrk/', 'park.mp3', 'n.公园；专用区；  v.停车', '51c119ab8213c9084a638bd6ca8b8e3a_199884_1524814294.jpg', '20141014_06_41_30_885_v3.png', 'Let\'s go for a walk in the park.', '我们去公园散散步吧。', 'q43lrws32pznq5kn9xlf75wp45vblahj.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4002, 'participate', '/pɑːrˈtɪsɪˌpeɪt/', 'participate.mp3', 'v.参与，参加', '7c0dfa17386dec0922cc26c326df31a6_115038_1628933225.jpg', 'd_107_6348_0_2_20150809015724.png', 'The teacher is happy when her students participate in class discussions.', '当学生们参与课堂讨论时，老师很开心。', 'us_The_teacher_20241009151651487_a63ee929c4907cc3be1d.mp3', 'parti=part部分，分开 + cip抓住 + ate动词后缀 → 抓住机会成为其中一部分 → 参加', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4003, 'pass away', '/pæs əˈweɪ/', 'pass away.mp3', 'phr.死，逝世', 'd3993a593d3e61d44fe82687dc18527f_61185_1641956374.jpg', '', 'Her grandpa passed away last year.', '她的爷爷在去年去世了。', 'lw5tncs35auuslh7rbjkd38a8qbyveeb.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4004, 'pay for', '/peɪ fɔr/', 'pay for.mp3', 'phr.因…受处罚，付出代价', '0a57317341611aa65e81ecb7096852d2_158723_1604571825.jpg', '', 'If you park the car in the wrong place', '你如果把车停在了不该停的地方，就要为此付出代价。', 'c13ff7f174c566e70db1f2ce2d12d2f2_23399_1604571810.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4005, 'peak', '/piːk/ ', 'peak.mp3', 'n.山顶；顶峰；顶点；  v.达到最高点', '254d27c710543dc365dabbfa0a823481_92081_1533106656.jpeg', 'd_1_5762_0_2_20150808124346.png', 'The peak of the mountain is covered by snow.', '山顶被积雪覆盖。', 'n5x8jykp9qp9hw2unl6q3jdp64r8tvw5.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4006, 'per', '/pər/', 'per.mp3', 'prep.每，每一', '3_0_20170930071705_2156_c-gigapixel-scale.jpg', 'd_24_17419_0_4_20150808232755.png', 'You are allowed to drive at 80 kilometers per hour on this road.', '你可以在这条路上以每小时最快80公里的速度行驶。', 'b84a7d31083d64aa_1266883480604007120_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4007, 'place', '/pleɪs/', 'place.mp3', 'v.（尤指小心地）放置', 'b26c2eb975a0eab4a647c5127fdabb46.jpeg', 'd_24_17926_0_3_20150808233523.png', 'She carefully placed the folder back in the filing cabinet.', '她小心地把文件夹放回档案柜里。', 'e2d1fe2f39cd3e2525aa51cc6510ede2.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4008, 'preface to', '/ˈprefəs tuː/', 'preface to.mp3', 'phr.……的序言', '3a0162f3f5c21188a6e8404bdd3fbe55.jpg', '', 'A preface to a book is usually at the beginning.', '序言一般在书的开头。', 'f84c539c1e8b3be25efc91285c551329_41888_1593586265.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4009, 'preparation for', '/ˌprepəˈreɪʃn fɔːr/', 'preparation for.mp3', 'phr.……的准备', 'c1ba4fc245bdbeaa822241e26622b56f.jpg', '', 'Cutting up vegetables is the preparation for cooking.', '切菜是做饭的准备工作。', '98bb0e7d7a2097d0fdddc86f8f07db2d_47648_1593586207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4010, 'prepare', '/prɪˈper/', 'prepare.mp3', 'v.使有准备', '87c31affb4bdd2af42cecbf90063b8fb_190184_1719804938.jpg', 'd_24_8115_0_3_20150808225506.png', 'The family is preparing for a meal together.', '这家人正在一起准备一顿饭。', 'ce2a99f0b070623b_1266763556614417196_250117.mp3', 'pre预先 + pare准备 → 预先准备预先准备好 → prepare准备', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4011, 'proficient', '/prəˈfɪʃnt/', 'proficient.mp3', 'adj.精通的，熟练的', '6d4dc852dbff1934dd52d93ab4384b80_178479_1730686198.jpg', '', 'Despite his young age', '这个男孩小小年纪就精通七国语言。', 'us_Despite_his_20240312102558161_64b18e375ac0ec5496fb.mp3', 'pro向前，在前 + fici做 + ent形容词后缀 → 做在别人前面 → proficient精通的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4012, 'project', '/ˈprɑːdʒekt/', 'project.mp3', 'n.项目，工程，习作项目；  v.投射', 'i_16_3854_0_8_160428102309-gigapixel-scale.jpg', 'd_13_3854_0_3_20150808162622.png', 'The housing project is going on well as planned.', '这个住宅工程正在如期进展。', 'bqg66275dxn2kvefrl2spgc3nrwvzwd6.mp3', 'pro向前，在前 + ject扔 → 扔向前面 → project投射', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4013, 'psychological', '/ˌsaɪkəˈlɑdʒɪkəl/', 'psychological.mp3', 'adj.心理的，心理学的', 'i_13_6143_0_8_160109120140-gigapixel-scale.jpg', 'd_105_6143_0_2_20150809055505.png', 'Intense pressure results in psychological problems of the poor man.', '沉重的压力让那个可怜的男人出现了心理问题。', 'sa_1_6143_0_8_160111180910.aac', 'psycho=psych灵魂 + logical…学的 → psychological心理的，心理学的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4014, 'put', '/pʊt/', 'put.mp3', 'v.放，摆；使处于；表达，表述；对事件作出说明，提出意见', '420f36ccd8a0b3c8a4b4d12342ca51ff_134335_1575019198.jpeg', 'd_24_17925_0_4_20150808233520.png', 'I put this green vase on the table.', '我把这个绿色的花瓶放到了桌子上。', '21629152ced1ea77_1266763311866862154_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4015, 'put aside', '/pʊt əˈsaɪd/', 'put aside.mp3', 'phr.储存', 'd31ff475b7131d271b67b78a4950b699.jpg', '', 'He puts some of his salary aside every month to buy a car in the future.', '他每个月都把一部分薪水存起来，想在将来买辆车。', 'us_He_puts_20241009154642052_ee26b35d8c23a57b7e60.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4016, 'put forward', '/pʊt \'fɔːrwəd/', 'put forward.mp3', 'phr.提出', '7b492fa324c539aa6556708e1d5c4543.jpg', '', 'He put forward a proposal for how they could increase product sales. ', '他就如何提高产品销量提出了一项建议。', 'f8186bdf5002c1dfd31c6163d4c46410_29261_1621926790.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4017, 'railroad', '/ˈreɪlroʊd/', 'railroad.mp3', 'n.铁路；  v.迫使某人做某事', 'e1ab9577135aa4b3aec4f0a749bba021_81633_1565342538.jpg', 'd_105_8699_0_2_20150809061100.png', 'I\'m afraid of flying', '我怕坐飞机，所以我长途旅行都选择坐火车（铁路运输）。', 'sa_1_8699_0_4_160317101956.aac', 'rail铁轨 + road路 → railroad铁路', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4018, 'remove', '/rɪˈmuːv/', 'remove.mp3', 'v.去除；脱去，摘下；免除', 'e98d208815ab34a8cbf6a1c09acefeec_42675_1565280564.jpg', 'd_24_5583_0_3_20150808224208.png', 'Use the other end of the hammer to remove nails.', '用锤子的另一端拔除钉子。', 'e7720c23c9c131e8_1266883485359057726_250207.mp3', 're往回 + move移动 → remove移除', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4019, 'resolution', '/ˌrezəˈluːʃn/ ', 'resolution.mp3', 'n.决心，决定，坚定', 'cf2f62f838b9b0e88d32dc5b2f3a1de7_151417_1541649585.jpeg', 'd_107_5687_0_2_20150809013453.png', 'She made a resolution to read all of these English novels in just one week.', '她下定决心要在一周内读完所有这些英文小说。', '01a9924b2d13c2ffbf613ad55e95556c_34543_1569654073.mp3', 're不 + solut松开 + ion名词后缀，构成抽象名词 → 不解决就不松开 → resolution决心；溶解', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4020, 'resort', '/rɪˈzɔːrt/', 'resort.mp3', 'n.度假胜地；诉诸，凭借，求助；  v.诉诸，采用', 'cef06182b89f6d53df56796b04f91998_142511_1544077378.jpeg', 'd_107_5830_0_2_20150809014136.png', 'We will stay on a beach resort for our next holiday.', '下个假期我们将去一个海滨度假胜地。', '74abc709805a7203_1266883196172196380_250207.mp3', 're再一次 + sort出去 → resort度假胜地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4021, 'restrict', '/rɪˈstrɪkt/', 'restrict.mp3', 'v.限制；约束', '041ab7c638f6a0bc451d3abfee5a4867_79902_1698311599.jpeg', 'd_107_5742_0_2_20150809013707.png', 'A combination lock can restrict others from prying into their privacy.', '密码锁可以限制别人偷窥自己的隐私。', 'us_A_combination_20231026171409891_aa9b265b14e2f317fafc.mp3', 're回 + strict拉紧，压 → 拉回来 → 限制', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4022, 'ride', '/raɪd/', 'ride.mp3', 'v.骑（车），乘；  n.短途旅程', 'i_65_14002_0_4_20150809014503-gigapixel-scale.jpg', 'd_93_14002_0_4_20150809002207.png', 'When I ride my bike', '当我骑自行车时，为了安全我总会戴安全帽。', '1a40aa4014df47a9_1266763450432182796_250117.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4023, 'section', '/ˈsekʃn/', 'section.mp3', 'n.部分', 'i_1_5418_0_4_150923101438-gigapixel-scale.jpg', 'd_105_5418_0_2_20150809054659.png', 'This chart can be divided into six sections of different sizes.', '这个图表可以分成六个大小不同的部分。', 'sa_1_5418_0_4_151017114734.aac', 'sect切，割 + ion名词后缀 → 切开；部门', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4024, 'send for', '/send fɔːr/', 'send for.mp3', 'phr.派人去请（拿），召唤', '3_0_20170712071036_77691_c.jpg', '', 'Go and send for a doctor! the emperor cried.', '“快去请太医！”皇上喊道。', '3_0_20170712071036_89004_c.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4025, 'series', '/ˈsɪriz/', 'series.mp3', 'n.一连串；系列，系列节目；连续比赛，系列比赛', 'c472f95a302a78d1acdcc2761b6221f4_92000_1585056702.jpeg', 'd_1_5421_0_2_20150808123826.png', 'A series of coinciding incidents resulted in the glass-breaking.', '一连串巧合的事件导致玻璃被打碎。', 'tytvsssprmqrdaqse3h4gnwruwd9yfsa.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4026, 'seriously', '/ˈsɪriəsli/', 'seriously.mp3', 'adv.认真地；严肃地', 'cfa6407d24899221ba0bea0b4116296c_99667_1587629420.jpeg', '', 'He took training very seriously.', '他对待训练非常认真。', 'ddcd3664830850e4_1266883324239195050_250207.mp3', 'serious严肃的 + ly……地 → seriously认真地；严重地，严肃地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4027, 'service to', '/ˈsɜːrvɪs tuː/', 'service to.mp3', 'phr.为……服务', '4d22671ffb265e6a06654f4850fb5e29.jpg', '', 'The waiter offers services to customers.', '服务生为顾客提供服务。', '14a8f1f5467b9ac90b62f887edb8439c_39200_1593584435.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4028, 'set about', '/set əˈbaʊt/', 'set about.mp3', 'phr.着手进行', 'i_905_-905_0_1_160131120935.jpg', '', 'The woman set about cleaning the house.', '这个女人开始打扫房子了。', 'us_The_woman_20241009154803395_7ee597ea4d342ffafaa8.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4029, 'settle', '/ˈsetl/', 'settle.mp3', 'v.安顿；结束（争论）；解决；调停', '9cf0dac57f6f872886c839d76983703c_167651_1595323183.jpg', 'd_24_5641_0_4_20150808224239.png', 'He built himself a house and decided to settle there.', '他给自己修建了一所房子，并决定在那里安顿下来。', 'c5b2e3b0ea9c98d6_1266883375719537256_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4030, 'shake off', '/ʃeɪk ɔːf/', 'shake off.mp3', 'phr.甩掉', '49f71ffeeeb721b0e3ee551d7742f372.jpeg', '', 'The horse is shaking off the dust from his back.', '这匹马正在甩掉背上的尘土。', 'us_The_horse_20241009151358071_83d7983430cea8ebd2ee.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4031, 'sightseeing', '/ˈsaɪtsiːɪŋ/', 'sightseeing.mp3', 'n.游览；观光', '3_0_20170519070918_40873_c-gigapixel-scale.jpg', 'd_107_2711_0_2_20150809002959.png', 'I like to go sightseeing around seaside towns.', '我喜欢游览海滨小镇。', 'zbsj7nsftgeuzgkv4544r69s5bzdvdfy.mp3', 'sight眼光 + see看 + ing名词后缀 → 用眼看 → 观光，游览', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4032, 'soldier', '/ˈsoʊldʒər/', 'soldier.mp3', 'n.士兵，军人；  v.当兵', 'dfb7f48200517939a516385c933e6241_98605_1601197868.jpg', 'd_75_14258_0_4_20150809030000.png', 'These soldiers are wearing uniforms and helmets.', '士兵们穿着制服，戴着头盔。', 'dkealjaelgsqjvrp8j5vttudd6gwzxf6.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4033, 'sort', '/sɔːrt/', 'sort.mp3', 'v.把……分类，整理，挑选；  n.种类，类别', 'b420e6f6c757987a94ed27ef3dcb5950_114392_1582358172.jpeg', '20130106_14_38_45_627.png', 'I sorted the books into piles of big ones and small ones.', '我将书按大小分成了几摞。', '9ceaa587566e2686739c5db45b957917_47988_1582358164.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4034, 'span', '/spæn/', 'span.mp3', 'n.跨度；时间段；持续时间；小范围，短距离；  v.持续，贯穿（时间）；横跨；包括', 'cf2201a177a78e4799144277192733ff_85612_1565342512.jpg', 'dd5d340162494cb1a9e9b468958fa24f_75877_1551252556.png', 'The bridge\'s span is about half a kilometer.', '这座大桥的跨距大约是500米。', 'sa_1_4324_0_3_20150808122632.aac', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4035, 'specialize', '/ˈspɛʃəˌlaɪz/', 'specialize.mp3', 'v.专门研究，专门从事', '3_0_20160528171149_41613_c-gigapixel-scale.jpg', '20130510_18_17_35_974.png', 'The store specializes in selling hiking gear.', '这家店专门卖登山设备。', '3_0_20160528171149_68380_c.aac', 'special特别的 + ize……化 → 特殊化', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4036, 'stare', '/ster/', 'stare.mp3', 'v.盯，凝视', '5ed39ce8964aefee63737306d8ce2d4d_163020_1739004288.jpeg', 'd_94_7934_0_3_20150809005315.png', 'She secretly stared at others from behind the window.', '她在窗户后面偷偷地盯着别人。', '1db410f5e2e5f6c9_1266883114167261882_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4037, 'state', '/steɪt/', 'state.mp3', 'n.州，邦；状态，情况；  v.说明，陈述', '30577d9e1a443d9d2727173c65acbaf7_55430_1587656224.jpg', 'd_24_15895_0_3_20150808230729.png', 'Alaska is the northernmost state of America.', '阿拉斯加是美国最北边的州。', '7ca00407726db1204dd733b7a2a3c89d_14935_1541993618.mp3', 'stat站立 + e强调 → state国家，状态', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4038, 'store', '/stɔr/', 'store.mp3', 'n.商店；储存品；  v.贮藏，储存，积蓄', '20120716_03_16_08_713-manual-scale.jpg', 'd_24_7149_0_4_20150808225018.png', 'I took my son to the grocery store to buy some food.', '我带着儿子去杂货店买了一些食物。', '4bc293631c69ff30_1266883374924847682_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4039, 'success', '/səkˈses/', 'success.mp3', 'n.成功，成就', '3_0_20170714071050_94159_c.jpg', '20141009_02_33_41_339_v3.png', 'The success of reaching the top of the mountain brought him great joy.', '成功登上山顶让他无比喜悦。', 'r7e85ehcfjdu7lmypmbv8e46hxr9zkce.mp3', 'suc在……下面 + cess行走 → 在后面跟着前人走 → success成功；胜利', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4040, 'support', '/səˈpɔːrt/', 'support.mp3', 'v.支援；支撑；  n.支持；支撑物', '28c7ffa4b54e1f01de15a88b48847e6d_171328_1691114348.jpg', 'd_24_6940_0_3_20150808224837.png', 'Doctors and resources are being sent from other areas to support this province.', '其他地区派遣医生、运送物资来支援这个省。', 'de6229fa68faaf67c6a779ce11a13b11_50580_1591774742.mp3', 'sup在…下面 + port带 → 带来支持 → support支持', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4041, 'take in', '/teɪk ɪn/', 'take in.mp3', 'phr.吸收', '554fc1214a08a4120212353391710980.jpg', '', 'Plants generally take in water through their roots.', '植物一般通过根部吸收水分。', 'uf2yap2zynb3jzaxs8umhj2hptljw85e.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4042, 'take off', '/ˈteɪk ˌɔf/', 'take off.mp3', 'phr.起飞', '8a22294684b6bc7526b6972a429e6ad9_95687_1580871099.jpg', '', 'Look', '看，这架飞机正在起飞！它将飞上天空。', '617f5746048d7ee1_1266883326138624976_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4043, 'telephone', '/ˈtelɪfoʊn/', 'telephone.mp3', 'n.电话（机）；  v.打电话', 'i_24_19495_0_5_151128101517-gigapixel-scale.jpg', 'd_24_19495_0_3_20150809001626.png', 'The telephone rang while she was sleeping.', '电话在她睡觉的时候响了起来。', 'v7f6aqfhwz86latt5nfn7qldctkxf4uy.mp3', 'tele远，传送 + phone声音 → 远方声音传过来 → 电话', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4044, 'third', '/θɜːrd/', 'third.mp3', 'num.第三的；第三；  n.三分之一', '3_0_20170723071240_33351_c-gigapixel-scale.jpg', 'd_24_17612_0_4_20150808233025.png', 'The bronze medal was awarded for the third place.', '铜牌被颁发给了第三名。', '6anezsp43nmm5mlj5bsd8qezevhtyukp.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4045, 'throughout', '/θruːˈaʊt/', 'throughout.mp3', 'prep.在……期间，在整个时期；遍及；到处', 'i_1_16318_0_4_150909143531-gigapixel-scale.jpg', 'd_16_16318_0_2_20150809001842.png', 'It snowed throughout the day and night.', '雪下了整整一天一夜。', 'sa_1_16318_0_4_150914164625.aac', 'through通过 + out在外部 → 走到底最后到外面 → throughout遍及，到处', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4046, 'thumb', '/θʌm/', 'thumb.mp3', 'n.拇指；  v.以拇指示意；  v.<口语>做手势要求搭车', 'c2014a9a3bd9a65886fbe8b233d3a4b3_84887_1750907622.jpg', '20141013_17_28_48_928_v3.png', 'She gave a thumbs-up to the winning athletes.', '她向夺冠运动员竖起了大拇指。', 'us_She_gave_20240802113346240_9e56f0f39dbf8e1c4bec.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4047, 'tight', '/taɪt/', 'tight.mp3', 'adj.紧身的，紧的；  adv.紧紧地，牢固地', '1e4d0f4b35dee8e8fc70cc400251576e_44734_1731902346.jpg', '', 'Oh no', '哦不，这件线衣对我来说太紧了。', '2b5a7ee5288c7c53_1266883378061487062_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4048, 'trap', '/træp/', 'trap.mp3', 'n.陷阱；捕兽夹，捕鼠器；  v.困住', 'ebe3d06d23b2c4a75521704f220d64f5_99759_1533105471.jpeg', 'd_24_5973_0_4_20150808224415.png', 'The man is about to fall into the trap!', '这个男人就要陷入圈套了！', 'pyqczp85ubxgarsagahpydtmswqsaf62.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4049, 'trust in', '/trʌst ɪn/', 'trust in.mp3', 'v.信任', 'e5bbcfc2761ed744549d5ad9e85fe417.jpeg', '', 'He trusts in his ability to shoot the apple.', '他相信他的能力足以射中那个苹果。', 'b1c51bd6df7183398906c37a93d1199d.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4050, 'upon', '/əˈpɑːn/', 'upon.mp3', 'prep.在……上面', '3_0_20170924071149_19897_c-gigapixel-scale.jpg', 'd_24_19256_0_4_20150809001043.png', 'Once upon a time', '从前有座山，山上有座庙。', '3_0_20170924071149_6844_c.aac', 'up向上 + on在...上面 → upon在...上面', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4051, 'usually', '/ˈjuːʒuəli/', 'usually.mp3', 'adv.通常，经常', 'i_1_11455_0_2_20150808131824-gigapixel-scale.jpg', 'd_24_11455_0_3_20150808230549.png', 'We usually have lunch at 12:00.', '我们通常在十二点吃午饭。', 'a4421c31fa21dd40_1266763447169407666_250117.mp3', 'usual通常的 + ly副词后缀 → usually通常地，惯常地', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4052, 'vertical', '/ˈvɜːrtɪkl/', 'vertical.mp3', 'adj.垂直的；  n.垂直线', 'd8e06fed39737d0755c3d6daf22336ea_193437_1534152717.jpeg', '20141013_01_08_34_538_v3.png', 'The boy found the only vertical tree in the woods.', '这个男孩在树林里找到了唯一一棵与地面垂直的树。', 'zbn4lbs37rf3xg4eag93pffnga9n2gte.mp3', 'vert转变 + ical…的 → 转变成直的 → vertical垂直', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4053, 'victim', '/ˈvɪktɪm/', 'victim.mp3', 'n.受害者', '0e31000df78c18687c4e5f5a97919ff3_84537_1595859735.jpg', 'd_24_7952_0_3_20150808225301.png', 'The family are victims of the flood', '这一家人是这次洪灾的受害者，现在他们无家可归了。', '3c1cf13b6f349a4d57a115b486d5557c_22459_1619172135.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4054, 'wander', '/ˈwɑːndər/', 'wander.mp3', 'v.闲逛，漫步；蜿蜒；迷路；离题；  n.游荡；闲逛，漫步；失散', 'e2ffcdd3b2cd27b98a39038a91e91aaf_62680_1710209865.jpeg', 'd_16_5488_0_2_20150808225349.png', 'The couple are casually wandering amidst the maple trees.', '这对恋人正在枫叶林里悠闲地漫步。', '700d18c4dadd3d40_1266883374117902876_250207.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4055, 'worthwhile', '/ˌwɜːrθˈwaɪl/', 'worthwhile.mp3', 'adj.值得的，有意义的', 'c778068ebc38f393941efb2c6ef9781d_234490_1582707260.jpg', '20121225_20_41_13_915.png', 'Studying English words with this app is definitely worthwhile!', '用这款应用学英语单词绝对超值哦！', 'y4c97p8jkz23swjp6n7f6hh2cfcxjw8r.mp3', 'worth有...价值 + while一段时间 → worthwhile值得的', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
INSERT INTO `words` VALUES (4056, 'wrist', '/rɪst/', 'wrist.mp3', 'n.腕部', 'd02097dab8cfb2b377653cd3d6247c10_61242_1556346675.jpeg', 'd_16_5217_0_2_20150808225142.png', 'The basketball player injured his wrist.', '这名篮球运动员的手腕受伤了。', '9becac514cd7ec88cc673f834fc05a5c_43940_1556346681.mp3', '', '2025-12-15 12:40:52', '2025-12-15 12:40:52');
